const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 9":["זָר שֶׁעָבַד בַּמִּקְדָּשׁ עֲבוֹדָתוֹ פְּסוּלָה וְחַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (במדבר יח ז) \"וְהַזָּר הַקָּרֵב יוּמָת\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵין חִיּוּב זֶה אֶלָּא לִקְרַב לַעֲבוֹדָה. וְהֵיכָן הִזְהִיר עָלָיו וְזָר לֹא יִקְרַב אֲלֵיכֶם. אֵי זֶהוּ זָר כָּל שֶׁאֵינוֹ מִזֶּרַע אַהֲרֹן הַזְּכָרִים שֶׁנֶּאֱמַר (ויקרא א ח) \"וְעָרְכוּ בְּנֵי אַהֲרֹן\". וְהִקְטִירוּ בְּנֵי אַהֲרֹן. בְּנֵי אַהֲרֹן וְלֹא בְּנוֹת אַהֲרֹן:","אַף עַל פִּי שֶׁהַזָּרִים מֻזְהָרִין שֶׁלֹּא יִתְעַסְּקוּ בַּעֲבוֹדָה מֵעֲבוֹדוֹת הַקָּרְבָּנוֹת אֵין חַיָּבִין מִיתָה אֶלָּא עַל עֲבוֹדָה תַּמָּה לֹא עַל עֲבוֹדָה שֶׁיֵּשׁ אַחֲרֶיהָ עֲבוֹדָה. וְאֵין הַזָּר חַיָּב מִיתָה אֶלָּא עַל אַרְבַּע עֲבוֹדוֹת בִּלְבַד. עַל הַזְּרִיקָה וְעַל הַהַקְטָרָה וְעַל נִסּוּךְ הַמַּיִם בֶּחָג וְעַל נִסּוּךְ הַיַּיִן תָּמִיד:","כֵּיצַד עַל הַזְּרִיקָה. בֵּין שֶׁזָּרַק בִּפְנִים בֵּין שֶׁזָּרַק בַּחוּץ בֵּין שֶׁהִזָּה הַזָּאָה אַחַת מִכָּל הַזָּיוֹת הַדָּם בֵּין שֶׁהִזָּה הַזָּאָה אַחַת מִכָּל הַזָּיוֹת קָרְבְּנוֹת הַמְצֹרָע הֲרֵי זֶה חַיָּב מִיתָה:","כֵּיצַד עַל הַקְטָרָה. הִקְטִיר אֵיבָרִים אוֹ קֹמֶץ אוֹ לְבוֹנָה עַל הַמִּזְבֵּחַ אֲפִלּוּ הָפַךְ בָּאֵיבָרִים שֶׁלֹּא נִתְעַכְּלוּ וְקֵרֵב שְׂרֵפָתָן חַיָּב מִיתָה וְהוּא שֶׁהִקְטִיר כְּזַיִת. וְכֵן אִם הִקְטִיר קְטֹרֶת עַל מִזְבַּח הַזָּהָב מִשֶּׁיַּקְטִיר כְּזַיִת חַיָּב. אֲבָל הַמַּקְטִיר קְטֹרֶת בְּיוֹם הַכִּפּוּרִים בְּקֹדֶשׁ הַקָּדָשִׁים אֵינוֹ חַיָּב מִיתָה עָלֶיהָ עַד שֶׁיַּקְטִיר מְלֹא חָפְנָיו שִׁעוּר הַמְפֹרָשׁ בַּתּוֹרָה:","וְהַמְסַדֵּר שְׁנֵי גִּזְרֵי עֵצִים עַל הַמַּעֲרָכָה הֲרֵי הוּא כְּמַקְטִיר אֵיבָרִים וְחַיָּב מִיתָה שֶׁהָעֵצִים קָרְבָּן הוּא. אֲבָל הַיּוֹצֵק וְהַבּוֹלֵל וְהַפּוֹתֵת וְהַמּוֹלֵחַ וְהַמֵּנִיף וְהַמַּגִּישׁ וּמְסַדֵּר אֶת לֶחֶם הַפָּנִים אוֹ אֶת הַבְּזִיכִין עַל הַשֻּׁלְחָן וְהַמֵּטִיב אֶת הַנֵּרוֹת וְהַמַּצִּית אֵשׁ בַּמִּזְבֵּחַ וְהַקּוֹמֵץ וְהַמְקַבֵּל דָּמִים. אַף עַל פִּי שֶׁנִּפְסְלוּ וַהֲרֵי הוּא מֻזְהָר עַל כָּל אֵלּוּ וְלוֹקֶה אֵינוֹ חַיָּב מִיתָה. מִפְּנֵי שֶׁכָּל אַחַת מֵהֶן עֲבוֹדָה שֶׁאַחֲרֶיהָ עֲבוֹדָה וְאֵינָהּ גְּמַר עֲבוֹדָה:","שְׁחִיטַת הַקָּדָשִׁים כְּשֵׁרָה בְּזָרִים אֲפִלּוּ קָדְשֵׁי קָדָשִׁים. בֵּין קָדְשֵׁי יָחִיד בֵּין קָדְשֵׁי צִבּוּר שֶׁנֶּאֱמַר (ויקרא א ה) \"וְשָׁחַט אֶת בֶּן הַבָּקָר לִפְנֵי ה' וְהִקְרִיבוּ בְּנֵי אַהֲרֹן\" מִקַּבָּלָה וְאֵילָךְ מִצְוַת כְּהֻנָּה. וְכֵן הַהֶפְשֵׁט וְהַנִּתּוּחַ וְהוֹלָכַת עֵצִים לַמִּזְבֵּחַ כְּשֵׁרָה בְּזָרִים שֶׁנֶּאֱמַר בָּאֵיבָרִים (ויקרא א ט) \"וְהִקְטִיר הַכֹּהֵן אֶת הַכּל הַמִּזְבֵּחָה\" זוֹ הוֹלָכַת אֵיבָרִים לַכֶּבֶשׁ. הוֹלָכַת אֵיבָרִים הִיא שֶׁצְּרִיכָה כְּהֻנָּה וְלֹא הוֹלָכַת עֵצִים:","וְכֵן הַדְלָקַת הַנֵּרוֹת כְּשֵׁרָה בְּזָרִים לְפִיכָךְ אִם הֵטִיב הַכֹּהֵן אֶת הַנֵּרוֹת וְהוֹצִיאָן לַחוּץ מֻתָּר לְזָר לְהַדְלִיקָן:","הֲרָמַת הַדֶּשֶׁן צְרִיכָה כֹּהֵן שֶׁנֶּאֱמַר (ויקרא ו ג) \"וְלָבַשׁ הַכֹּהֵן מִדּוֹ בַד\" וְגוֹ'. וְאִם הֵרִים יִשְׂרָאֵל לוֹקֶה וְאֵינוֹ חַיָּב מִיתָה אַף עַל פִּי שֶׁאֵין אַחֲרֶיהָ עֲבוֹדָה שֶׁנֶּאֱמַר עֲבֹדַת מַתָּנָה (במדבר יח ז) \"עֲבוֹדַת מַתָּנָה\" הוּא שֶׁתִּהְיֶה בְּכֹהֵן לְבַדּוֹ וְאִם קָרַב לָהּ הַזָּר חַיָּב מִיתָה. אֲבָל עֲבוֹדַת סִלּוּק אֵין חַיָּבִין עָלֶיהָ מִיתָה. [וְכֵן אִם דִּשֵּׁן מִזְבֵּחַ הַפְּנִימִי וְהַמְּנוֹרָה אֵינוֹ חַיָּב מִיתָה]:","סִדֵּר הַמַּעֲרָכָה פּוֹרְקָהּ וְחוֹזֵר הַכֹּהֵן וְסוֹדְרָהּ מִפְּנֵי שֶׁסִּדּוּרָהּ פָּסוּל:","הַטָּמֵא וּבַעַל מוּם וְשֶׁלֹּא רָחוּץ יָדַיִם וְרַגְלַיִם שֶׁשִּׁמֵּשׁ בַּמִּקְדָּשׁ אֵינָן חַיָּבִין אֶלָּא עַל עֲבוֹדוֹת שֶׁהַזָּר חַיָּב עֲלֵיהֶן מִיתָה. וְעַל שְׁאָר הָעֲבוֹדוֹת בְּאַזְהָרָה:","כֹּהֵן טְבוּל יוֹם וּמְחֻסַּר כִּפּוּרִים שֶׁנִּטְמָא וַהֲרֵי הוּא מְחֻסַּר בְּגָדִים וְשֶׁלֹּא רָחוּץ יָדַיִם וְרַגְלַיִם וְעָבַד חַיָּב עַל כָּל אֶחָד וְאֶחָד. וְאִם הָיָה זָר אֵינוֹ לוֹקֶה אֶלָּא אַחַת מִשּׁוּם זָרוּת:","זָר שֶׁשִּׁמֵּשׁ בְּשַׁבָּת חַיָּב מִשּׁוּם שַׁבָּת וּמִשּׁוּם זָרוּת. וְכֵן בַּעַל מוּם שֶׁשִּׁמֵּשׁ בְּטֻמְאָה חַיָּב מִשּׁוּם טֻמְאָה וּמִשּׁוּם בַּעַל מוּם:","כָּל כֹּהֵן שֶׁעָבַד עֲבוֹדָה זָרָה בֵּין בְּמֵזִיד בֵּין בְּשׁוֹגֵג אַף עַל פִּי שֶׁחָזַר בִּתְשׁוּבָה גְּמוּרָה הֲרֵי זֶה לֹא יְשַׁמֵּשׁ בַּמִּקְדָּשׁ לְעוֹלָם שֶׁנֶּאֱמַר (יחזקאל מד יג) \"וְלֹא יִגְּשׁוּ אֵלַי לְכַהֵן לִי\". אֶחָד הָעוֹבֵד אוֹתָהּ בְּשֵׁרוּת כְּגוֹן שֶׁנַּעֲשָׂה כֹּמֶר לַעֲבוֹדָה זָרָה אוֹ הַמִּשְׁתַּחֲוֶה לָהּ אוֹ הַמּוֹדֶה בָּהּ וְקִבְּלָהּ עָלָיו בֶּאֱלוֹהַּ הֲרֵי זֶה פָּסוּל לְעוֹלָם. עָבַר וְהִקְרִיב אֵין קָרְבָּנוֹ רֵיחַ נִיחוֹחַ אַף עַל פִּי שֶׁהָיָה שׁוֹגֵג בְּעֵת שֶׁשֵּׁרֵת אוֹ שֶׁהִשְׁתַּחֲוָה אוֹ שֶׁהוֹדָה. אֲבָל הַשּׁוֹחֵט לַעֲבוֹדָה זָרָה בְּשׁוֹגֵג אִם עָבַר וְהִקְרִיב קָרְבָּנוֹ רֵיחַ נִיחוֹחַ וְנִתְקַבֵּל שֶׁהֲרֵי לֹא שֵׁרֵת וְלֹא נַעֲשָׂה כֹּמֶר אֶלָּא שָׁחַט בִּלְבַד וְהוּא שׁוֹגֵג וְאַף עַל פִּי כֵן לְכַתְּחִלָּה לֹא יַעֲבֹד:","מִי שֶׁעָבַר וְעָשָׂה בַּיִת חוּץ לַמִּקְדָּשׁ לְהַקְרִיב בּוֹ קָרְבָּנוֹ לַשֵּׁם אֵינוֹ כְּבֵית עֲבוֹדָה זָרָה וְאַף עַל פִּי כֵן כָּל כֹּהֵן שֶׁשִּׁמֵּשׁ בְּבַיִת כָּזֶה לֹא יְשַׁמֵּשׁ בַּמִּקְדָּשׁ לְעוֹלָם. וְכֵן כֵּלִים שֶׁנִּשְׁתַּמְּשׁוּ בָּהֶן שָׁם לֹא יִשְׁתַּמְּשׁוּ בָּהֶן בַּמִּקְדָּשׁ לְעוֹלָם אֶלָּא יִגָּנְזוּ. וְיֵרָאֶה לִי שֶׁאִם עָבַד כֹּהֵן שֶׁשִּׁמֵּשׁ שָׁם בַּמִּקְדָּשׁ לֹא פָּסַל:","נִמְצְאוּ כָּל הַפְּסוּלִין לַעֲבוֹדָה שְׁמוֹנָה עָשָׂר וְאֵלּוּ הֵן. הָעוֹבֵד עֲבוֹדָה זָרָה. הַזָּר. בַּעַל מוּם. הֶעָרֵל. הַטָּמֵא. טְבוּל יוֹם. מְחֻסַּר כִּפּוּרִים. הָאוֹנֵן. הַשִּׁכּוֹר. מְחֻסַּר בְּגָדִים. יָתֵר בְּגָדִים. פְּרוּם בְּגָדִים. פְּרוּעַ רֹאשׁ. שֶׁלֹּא רָחַץ יָדַיִם וְרַגְלַיִם. הַיּוֹשֵׁב. מִי שֶׁיֵּשׁ בֵּין יָדוֹ וּבֵין הַכְּלִי דָּבָר חוֹצֵץ. מִי שֶׁיֵּשׁ בֵּין רַגְלוֹ וּבֵין הָאָרֶץ דָּבָר חוֹצֵץ. מִי שֶׁעָבַד בִּשְׂמֹאלוֹ. כָּל אֵלּוּ פְּסוּלִין לַעֲבוֹדָה וְאִם עָבְדוּ חִלְּלוּ. חוּץ מִפְּרוּעַ רֹאשׁ וּקְרוּעַ בְּגָדִים וְהַשּׁוֹחֵט לַעֲבוֹדָה זָרָה בְּשׁוֹגֵג. שֶׁאִם עָבְדוּ עֲבוֹדָתָן כְּשֵׁרָה:"],"Mishneh Torah, Appraisals and Devoted Property 2":["הָאוֹמֵר עֵרֶךְ יָדִי אוֹ עֵרֶךְ עֵינִי אוֹ רַגְלִי עָלַי אוֹ שֶׁאָמַר עֵרֶךְ יָד זֶה אוֹ עֵינוֹ עָלַי לֹא אָמַר כְּלוּם. עֵרֶךְ לִבִּי אוֹ כְּבֵדִי עָלַי אוֹ עֵרֶךְ לִבּוֹ שֶׁל פְּלוֹנִי אוֹ כְּבֵדוֹ עָלַי נוֹתֵן עֵרֶךְ כֻּלּוֹ. וְכֵן כָּל אֵיבָר שֶׁאִם יִנָּטֵל מִן הַחַי יָמוּת אִם אָמַר עֶרְכּוֹ עָלַי נוֹתֵן עֵרֶךְ כֻּלּוֹ:","אָמַר חֲצִי עֶרְכִּי עָלַי נוֹתֵן חֲצִי עֶרְכּוֹ. עֵרֶךְ חֶצְיִי עָלַי נוֹתֵן עֵרֶךְ כֻּלּוֹ שֶׁאִי אֶפְשָׁר שֶׁיִּנָּטֵל חֶצְיוֹ וְיִחְיֶה:","הָאוֹמֵר דְּמֵי יָדִי עָלַי אוֹ דְּמֵי יַד פְּלוֹנִי עָלַי שָׁמִין אוֹתוֹ כַּמָּה הוּא שָׁוֶה בְּיָד וְכַמָּה הוּא שָׁוֶה בְּלֹא יָד וְנוֹתֵן לַהֶקְדֵּשׁ. כֵּיצַד. אִם נִמְכַּר הוּא כֻּלּוֹ [יִהְיֶה] שָׁוֶה חֲמִשִּׁים. וְאִם יִמָּכֵר חוּץ מִיָּדוֹ שֶׁתִּשָּׁאֵר יָדוֹ זוֹ לִבְעָלָיו וְלֹא יִהְיֶה לַלּוֹקֵחַ בָּהּ כְּלוּם שָׁוֶה אַרְבָּעִים. נִמְצָא זֶה יִתְחַיֵּב לְשַׁלֵּם לַהֶקְדֵּשׁ עֲשָׂרָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאוֹמֵר דְּמֵי רֹאשִׁי אוֹ כְּבֵדִי עָלַי אוֹ דְּמֵי רֹאשׁוֹ שֶׁל פְּלוֹנִי עָלַי אוֹ לִבּוֹ אוֹ כְּבֵדוֹ עָלַי נוֹתֵן דְּמֵי כֻּלּוֹ. וְכֵן הָאוֹמֵר דְּמֵי חֶצְיִי עָלַי נוֹתֵן דְּמֵי כֻּלּוֹ. אֲבָל הָאוֹמֵר חֲצִי דָּמַי עָלַי נוֹתֵן חֲצִי דָּמָיו:","הָאוֹמֵר מִשְׁקָלִי עָלַי אוֹ מִשְׁקַל פְּלוֹנִי עָלַי נוֹתֵן מִשְׁקָלוֹ אִם כֶּסֶף כֶּסֶף אִם זָהָב זָהָב כְּמוֹ שֶׁפֵּרֵשׁ. אָמַר מִשְׁקַל יָדִי אוֹ רַגְלִי עָלַי רוֹאִין כַּמָּה הִיא רְאוּיָה לִשְׁקל וְנוֹתֵן מָמוֹן שֶׁפֵּרֵשׁ. עַד הֵיכָן הִיא הַיָּד לְעִנְיָן זֶה עַד הֶאָצִיל וְהָרֶגֶל עַד הָאַרְכֻּבָּה לְפִי שֶׁבִּנְדָרִים הוֹלְכִין אַחַר לְשׁוֹן בְּנֵי אָדָם:","הָאוֹמֵר קוֹמָתִי עָלַי כֶּסֶף אוֹ זָהָב נוֹתֵן שַׁרְבִיט שֶׁאֵינוֹ נִכְפָּף מְלֹא קוֹמָתוֹ מִמִּין שֶׁפֵּרֵשׁ. אָמַר מְלֹא קוֹמָתִי עָלַי נוֹתֵן אֲפִלּוּ שַׁרְבִיט שֶׁנִּכְפָּף מִמִּין שֶׁפֵּרֵשׁ:","הָאוֹמֵר מִשְׁקָלִי עָלַי וְלֹא פֵּרֵשׁ מֵאֵי זֶה מִין. אִם הָיָה עָשִׁיר בְּיוֹתֵר וְנִתְכַּוֵּן לְמַתָּנָה מְרֻבָּה נוֹתֵן מִשְׁקָלוֹ זָהָב. וְהוּא הַדִּין בְּאוֹמֵר מִשְׁקַל יָדִי אוֹ רַגְלִי אוֹ קוֹמָתִי וְלֹא פֵּרֵשׁ מֵאֵי זֶה מִין נוֹתֵן זָהָב. וְאִם אֵינוֹ מֻפְלָג בַּעֲשִׁירוּת נוֹתֵן מִשְׁקָלוֹ אוֹ מִשְׁקַל יָדוֹ מִדְּבָרִים שֶׁדַּרְכָּן לְהִשָּׁקֵל בְּאוֹתוֹ מָקוֹם אֲפִלּוּ פֵּרוֹת. וְכֵן נוֹתֵן שַׁרְבִיט מְלֹא קוֹמָתוֹ אֲפִלּוּ שֶׁל עֵץ הַכּל לְפִי מָמוֹנוֹ וְדַעְתּוֹ:","הָאוֹמֵר עָמְדִי עָלַי יְשִׁיבָתִי עָלַי אוֹ מְקוֹם יְשִׁיבָתִי עָלַי אוֹ רָחְבִּי עָלַי עָבְיִי עָלַי הֶקֵּפִי עָלַי כָּל אֵלּוּ סָפֵק וּמֵבִיא לְפִי מָמוֹנוֹ. עַד שֶׁיֹּאמַר לֹא כָּךְ נִתְכַּוַּנְתִּי. וְאִם מֵת יִתְּנוּ הַיּוֹרְשִׁים פָּחוּת שֶׁבַּלְּשׁוֹנוֹת:","הָאוֹמֵר הֲרֵי עָלַי מַטְבֵּעַ כֶּסֶף לֹא יִפְחֹת מִדִּינָר כֶּסֶף. מַטְבֵּעַ נְחשֶׁת לֹא יִפְחֹת מִמָּעָה כֶּסֶף. הֲרֵי עָלַי בַּרְזֶל לֹא יִפְחוֹת מֵאַמָּה עַל אַמָּה לְכָלֶה עוֹרֵב שֶׁהָיָה לְמַעְלָה בְּגַג הַהֵיכָל כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","הָאוֹמֵר הֲרֵי עָלַי כֶּסֶף אוֹ זָהָב וְלֹא הִזְכִּיר מַטְבֵּעַ יָבִיא לָשׁוֹן שֶׁל כֶּסֶף אוֹ שֶׁל זָהָב יִהְיֶה מִשְׁקָלָהּ עַד שֶׁיֹּאמַר לֹא לְכָךְ נִתְכַּוַּנְתִּי. וְכֵן אִם פֵּרֵשׁ הַמִּשְׁקָל וְשָׁכַח כַּמָּה פֵּרֵשׁ יָבִיא עַד שֶׁיֹּאמַר לֹא לְכָךְ נִתְכַּוַּנְתִּי:","אֶחָד הָאוֹמֵר דָּמַי עָלַי אוֹ דְּמֵי פְּלוֹנִי עָלַי. אוֹ הָאוֹמֵר הֲרֵי עָלַי מָנֶה אוֹ חֲמִשִּׁים אוֹ כֶּסֶף אוֹ זָהָב. הַכּל הֵן הַנִּקְרָאִים חַיָּבֵי דָּמִים. וְהַדָּמִים וְהָעֲרָכִין לְבֶדֶק הַבַּיִת כְּמוֹ שֶׁבֵּאַרְנוּ:","שְׁתֵּי לְשָׁכוֹת הָיוּ בַּמִּקְדָּשׁ. אַחַת לִשְׁכַּת חֲשָׁאִים. וְאַחַת לִשְׁכַּת הַכֵּלִים. לִשְׁכַּת חֲשָׁאִים יִרְאֵי חֵטְא נוֹתְנִין לְתוֹכָן בַּחֲשַׁאי וַעֲנִיִּים בְּנֵי טוֹבִים מִתְפַּרְנְסִים מִמֶּנָּה בַּחֲשַׁאי. לִשְׁכַּת הַכֵּלִים כָּל מִי שֶׁהִתְנַדֵּב כְּלִי זוֹרְקוֹ לְתוֹכָהּ וְאַחַת לִשְׁלֹשִׁים יוֹם הַגִּזְבָּרִין פּוֹתְחִין אוֹתָהּ. כָּל כְּלִי שֶׁנִּמְצָא בּוֹ צֹרֶךְ לְבֶדֶק הַבַּיִת מַנִּיחִין אוֹתוֹ וְהַשְּׁאָר נִמְכָּרִין וּדְמֵיהֶן נוֹפְלִין לְלִשְׁכַּת בֶּדֶק הַבַּיִת:","הֻצְרְכוּ לְקָדְשֵׁי מִזְבֵּחַ וְלֹא הִסְפִּיקוּ לָהֶן תְּרוּמַת הַלִּשְׁכָּה מוֹצִיאִין אֶת הָרָאוּי לָהֶן מִקָּדְשֵׁי בֶּדֶק הַבַּיִת. אֲבָל אִם הֻצְרְכוּ לְבֶדֶק הַבַּיִת וְלֹא מָצְאוּ בְּלִשְׁכַּת בֶּדֶק הַבַּיִת דָּבָר הַמַּסְפִּיק לָהֶן אֵין מוֹצִיאִין הָרָאוּי לָהֶן מִקָּדְשֵׁי הַמִּזְבֵּחַ:"],"Mishneh Torah, Blessings 4":["כָּל הַמְבָרֵךְ בִּרְכַּת הַמָּזוֹן אוֹ בְּרָכָה אַחַת מֵעֵין שָׁלֹשׁ צָרִיךְ לְבָרֵךְ אוֹתָהּ בַּמָּקוֹם שֶׁאָכַל. אָכַל כְּשֶׁהוּא מְהַלֵּךְ יוֹשֵׁב בְּמָקוֹם שֶׁפָּסַק וִיבָרֵךְ. אָכַל כְּשֶׁהוּא עוֹמֵד יוֹשֵׁב בִּמְקוֹמוֹ וִיבָרֵךְ. שָׁכַח לְבָרֵךְ בִּרְכַּת הַמָּזוֹן וְנִזְכַּר קֹדֶם שֶׁיִּתְעַכֵּל הַמָּזוֹן שֶׁבְּמֵעָיו מְבָרֵךְ בַּמָּקוֹם שֶׁנִּזְכַּר. וְאִם הָיָה מֵזִיד חוֹזֵר לִמְקוֹמוֹ וּמְבָרֵךְ. וְאִם בֵּרֵךְ בַּמָּקוֹם שֶׁנִּזְכַּר יָצָא יְדֵי חוֹבָתוֹ. וְכֵן אִם בֵּרֵךְ כְּשֶׁהוּא עוֹמֵד אוֹ כְּשֶׁהוּא מְהַלֵּךְ יָצָא יְדֵי חוֹבָתוֹ. וּלְכַתְּחִלָּה לֹא יְבָרֵךְ בִּרְכַּת הַמָּזוֹן וְלֹא בְּרָכָה שֶׁמֵּעֵין שָׁלֹשׁ אֶלָּא כְּשֶׁהוּא יוֹשֵׁב וּבַמָּקוֹם שֶׁאָכַל:","מִי שֶׁנִּסְתַּפֵּק לוֹ אִם בֵּרֵךְ הַמּוֹצִיא אוֹ לֹא בֵּרֵךְ הַמּוֹצִיא אֵינוֹ חוֹזֵר וּמְבָרֵךְ מִפְּנֵי שֶׁאֵינוֹ מִן הַתּוֹרָה. שָׁכַח לְבָרֵךְ הַמּוֹצִיא. אִם נִזְכַּר עַד שֶׁלֹּא גָּמַר סְעֻדָּתוֹ חוֹזֵר וּמְבָרֵךְ וְאִם נִזְכַּר לְאַחַר שֶׁגָּמַר אֵינוֹ חוֹזֵר וּמְבָרֵךְ:","הָיָה אוֹכֵל בְּבַיִת זֶה וּפָסַק סְעֻדָּתוֹ וְהָלַךְ לְבַיִת אַחֵר. אוֹ שֶׁהָיָה אוֹכֵל וּקְרָאָהוּ חֲבֵרוֹ לְדַבֵּר עִמּוֹ וְיָצָא לוֹ לְפֶתַח בֵּיתוֹ וְחָזַר הוֹאִיל וְשִׁנָּה מְקוֹמוֹ צָרִיךְ לְבָרֵךְ לְמַפְרֵעַ עַל מַה שֶּׁאָכַל וְחוֹזֵר וּמְבָרֵךְ בַּתְּחִלָּה הַמּוֹצִיא וְאַחַר כָּךְ יִגְמֹר סְעֻדָּתוֹ:","חֲבֵרִים שֶׁהָיוּ יוֹשְׁבִים לֶאֱכל וְיָצְאוּ לִקְרַאת חָתָן אוֹ לִקְרַאת כַּלָּה. אִם הִנִּיחוּ שָׁם זָקֵן אוֹ חוֹלֶה חוֹזְרִין לִמְקוֹמָן וְגוֹמְרִין סְעֻדָּתָן וְאֵינָן צְרִיכִין לְבָרֵךְ שְׁנִיָּה. וְאִם לֹא הִנִּיחוּ שָׁם אָדָם כְּשֶׁהֵן יוֹצְאִין צְרִיכִין בְּרָכָה לְמַפְרֵעַ וּכְשֶׁהֵן חוֹזְרִין צְרִיכִין בְּרָכָה לְכַתְּחִלָּה:","וְכֵן אִם הָיוּ מְסֻבִּין בִּשְׁתִיָּה אוֹ לֶאֱכל פֵּרוֹת. שֶׁכָּל הַמְשַׁנֶּה מְקוֹמוֹ הֲרֵי פָּסַק אֲכִילָתוֹ וּלְפִיכָךְ מְבָרֵךְ לְמַפְרֵעַ עַל מַה שֶּׁאָכַל וְחוֹזֵר וּמְבָרֵךְ שְׁנִיָּה לְכַתְּחִלָּה עַל מַה שֶּׁהוּא צָרִיךְ לֶאֱכל. וְהַמְשַׁנֶּה מְקוֹמוֹ מִפִּנָּה לְפִנָּה בְּבַיִת אֶחָד אֵינוֹ צָרִיךְ לַחֲזֹר וּלְבָרֵךְ. אָכַל בְּמִזְרָחָהּ שֶׁל תְּאֵנָה וּבָא לֶאֱכל בְּמַעֲרָבָהּ צָרִיךְ לַחֲזֹר וּלְבָרֵךְ:","בֵּרֵךְ עַל הַפַּת פָּטַר אֶת הַפַּרְפֶּרֶת שֶׁאוֹכְלִין בָּהֶן הַפַּת מִמִּינֵי הַתַּבְשִׁיל וּפֵרוֹת וְכַיּוֹצֵא בָּהֶן. אֲבָל אִם בֵּרֵךְ עַל הַפַּרְפֶּרֶת לֹא פָּטַר אֶת הַפַּת. בֵּרֵךְ עַל מַעֲשֵׂה קְדֵרָה פָּטַר אֶת הַתַּבְשִׁיל בֵּרֵךְ עַל הַתַּבְשִׁיל לֹא פָּטַר אֶת מַעֲשֵׂה קְדֵרָה:","גָּמַר בְּלִבּוֹ מִלֶּאֱכל אוֹ מִלִּשְׁתּוֹת וְאַחַר כָּךְ נִמְלַךְ לֶאֱכל אוֹ לִשְׁתּוֹת אַף עַל פִּי שֶׁלֹּא שִׁנָּה מְקוֹמוֹ חוֹזֵר וּמְבָרֵךְ. וְאִם לֹא גָּמַר בְּלִבּוֹ אֶלָּא דַּעְתּוֹ לַחֲזֹר לֶאֱכל וְלִשְׁתּוֹת אֲפִלּוּ פָּסַק כָּל הַיּוֹם כֻּלּוֹ אֵינוֹ צָרִיךְ לְבָרֵךְ שֵׁנִית:","הָיוּ שׁוֹתִין וְאָמְרוּ בּוֹאוּ וּנְבָרֵךְ בִּרְכַּת הַמָּזוֹן אוֹ בּוֹאוּ וּנְקַדֵּשׁ קִדּוּשׁ הַיּוֹם נֶאֱסַר עֲלֵיהֶם לִשְׁתּוֹת עַד שֶׁיְּבָרְכוּ אוֹ יְקַדְּשׁוּ. וְאִם רָצוּ לַחֲזֹר וְלִשְׁתּוֹת קֹדֶם שֶׁיְּבָרְכוּ אוֹ יְקַדְּשׁוּ אַף עַל פִּי שֶׁאֵינָם רַשָּׁאִים צְרִיכִים לַחֲזֹר וּלְבָרֵךְ תְּחִלָּה בּוֹרֵא פְּרִי הַגָּפֶן וְאַחַר כָּךְ יִשְׁתּוּ. אֲבָל אִם אָמְרוּ בּוֹאוּ וְנַבְדִּיל אֵין צְרִיכִין לַחֲזֹר וּלְבָרֵךְ:","הָיוּ מְסֻבִּין לִשְׁתּוֹת יַיִן וּבָא לָהֶן מִין יַיִן אַחֵר כְּגוֹן שֶׁהָיוּ שׁוֹתִין אָדֹם וְהֵבִיאוּ שָׁחֹר אוֹ יָשָׁן וְהֵבִיאוּ חָדָשׁ אֵינָן צְרִיכִין לְבָרֵךְ בִּרְכַּת הַיַּיִן פַּעַם שְׁנִיָּה. אֲבָל מְבָרְכִין בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַטּוֹב וְהַמֵּטִיב:","אֵין מְבָרְכִין עַל אֹכֶל מִן כָּל הָאֳכָלִין וְלֹא עַל מַשְׁקֶה מִן כָּל הַמַּשְׁקִין עַד שֶׁיָּבוֹא לְפָנָיו. וְאִם בֵּרֵךְ וְאַחַר כָּךְ הֱבִיאוֹ לְפָנָיו צָרִיךְ לַחֲזֹר וּלְבָרֵךְ. נָטַל אֹכֶל וּבֵרֵךְ עָלָיו וְנָפַל מִיָּדוֹ וְנִשְׂרַף אוֹ שְׁטָפוֹ נָהָר נוֹטֵל אַחֵר וְחוֹזֵר וּמְבָרֵךְ עָלָיו אַף עַל פִּי שֶׁהוּא מֵאוֹתוֹ הַמִּין. וְצָרִיךְ לוֹמַר בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד עַל בְּרָכָה רִאשׁוֹנָה כְּדֵי שֶׁלֹּא לְהוֹצִיא שֵׁם שָׁמַיִם לְבַטָּלָה. עוֹמֵד אָדָם עַל אַמַּת הַמַּיִם וּמְבָרֵךְ וְשׁוֹתֶה אַף עַל פִּי שֶׁהַמַּיִם שֶׁהָיוּ לְפָנָיו בִּשְׁעַת הַבְּרָכָה אֵינָם הַמַּיִם שֶׁשָּׁתָה מִפְּנֵי שֶׁלְּכָךְ נִתְכַּוֵּן תְּחִלָּה:","דְּבָרִים הַבָּאִים בְּתוֹךְ הַסְּעֻדָּה וְהֵן מֵחֲמַת הַסְּעֻדָּה אֵינָן צְרִיכִין בְּרָכָה לִפְנֵיהֶם וְלֹא לְאַחֲרֵיהֶם אֶלָּא בִּרְכַּת הַמּוֹצִיא שֶׁבַּתְּחִלָּה וּבִרְכַּת הַמָּזוֹן שֶׁבַּסּוֹף פּוֹטֶרֶת הַכּל שֶׁהַכּל טְפֵלָה לַסְּעֻדָּה. וּדְבָרִים שֶׁאֵינָן מֵחֲמַת הַסְּעֻדָּה שֶׁבָּאוּ בְּתוֹךְ הַסְּעֻדָּה טְעוּנִין בְּרָכָה לִפְנֵיהֶם וְלֹא לְאַחֲרֵיהֶם. וּדְבָרִים הַבָּאִים לְאַחַר הַסְּעֻדָּה בֵּין מֵחֲמַת הַסְּעֻדָּה בֵּין שֶׁלֹּא מֵחֲמַת הַסְּעֻדָּה טְעוּנִין בְּרָכָה לִפְנֵיהֶן וּלְאַחֲרֵיהֶם:","בְּשַׁבָּתוֹת וּבְיָמִים טוֹבִים וּבִסְעוּדַת הַקָּזַת הַדָּם וּבְשָׁעָה שֶׁיָּצָא מִן הַמֶּרְחָץ וְכַיּוֹצֵא בָּהֶן שֶׁאָדָם קוֹבֵעַ סְעֻדָּתוֹ עַל הַיַּיִן. אִם בֵּרֵךְ עַל הַיַּיִן שֶׁלִּפְנֵי הַמָּזוֹן פָּטַר אֶת הַיַּיִן שֶׁשָּׁתָה לְאַחַר הַמָּזוֹן קֹדֶם שֶׁיְּבָרֵךְ בִּרְכַּת הַמָּזוֹן. אֲבָל בִּשְׁאָר הַיָּמִים צָרִיךְ לַחֲזֹר וּלְבָרֵךְ בַּתְּחִלָּה עַל הַיַּיִן שֶׁל אַחַר הַמָּזוֹן. בָּא לָהֶן יַיִן בְּתוֹךְ הַמָּזוֹן כָּל אֶחָד וְאֶחָד מְבָרֵךְ לְעַצְמוֹ שֶׁאֵין בֵּית הַבְּלִיעָה פָּנוּי שֶׁיַּעֲנוּ אָמֵן וְאֵינוֹ פּוֹטֵר אֶת הַיַּיִן שֶׁלְּאַחַר הַמָּזוֹן:"],"Mishneh Torah, Borrowing and Deposit 7":["הַמַּפְקִיד פֵּרוֹת אֵצֶל חֲבֵרוֹ הֲרֵי זֶה לֹא יִגַּע בָּהֶן וְאַף עַל פִּי שֶׁהֵן חוֹסְרִין וּמִתְמַעֲטִין וְהוֹלְכִין. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁחָסְרוּ חִסָּרוֹן הָרָאוּי לָהֶן בְּכָל שָׁנָה. אֲבָל אִם חָסְרוּ יוֹתֵר מִכְּדֵי חֶסְרוֹנָן מוֹכְרָן בְּבֵית דִּין מִפְּנֵי שֶׁהוּא מֵשִׁיב אֲבֵדָה לַבְּעָלִים. וּכְשֶׁהוּא מוֹכְרָן יִמְכֹּר לַכֹּהֲנִים בִּדְמֵי תְּרוּמָה שֶׁמָּא עָשׂוּ אוֹתָן הַבְּעָלִים תְּרוּמָה אוֹ תְּרוּמַת מַעֲשֵׂר עַל פֵּרוֹת אֲחֵרוֹת:","הַמַּפְקִיד אֵצֶל חֲבֵרוֹ פֵּרוֹת וְהִרְקִיבוּ דְּבַשׁ וְנִפְסַד יַיִן וְהֶחְמִיץ עוֹשֶׂה תַּקָּנָה לְבַעַל הַפִּקָּדוֹן וּמוֹכְרָן בְּבֵית דִּין אַף עַל פִּי שֶׁעָמְדוּ בְּהֶפְסֵדָן וְאֵין הַהֶפְסֵד פּוֹשֶׂה בָּהֶן הֲרֵי הַקַּנְקַנִּים וְהַסַּלִּים מוֹסִיפִין הֶפְסֵד:","הַמַּפְקִיד חָמֵץ אֵצֶל חֲבֵרוֹ וְהִגִּיעַ הַפֶּסַח הֲרֵי זֶה לֹא יִגַּע בּוֹ עַד שָׁעָה חֲמִישִׁית מִיּוֹם אַרְבָּעָה עָשָׂר. מִכָּאן וְאֵילָךְ יוֹצֵא וּמוֹכְרוֹ בַּשּׁוּק לִשְׁעָתוֹ מִשּׁוּם הֶשֵּׁב אֲבֵדָה לַבְּעָלִים. וְהוּא הַדִּין לִשְׁאָר הַפִּקְדוֹנוֹת שֶׁלֹּא יִגַּע בָּהֶן אַף עַל פִּי שֶׁהוּא יוֹדֵעַ בְּוַדַּאי שֶׁיִּזּוֹלוּ בִּזְמַן פְּלוֹנִי אוֹ יֶאֱנֹס אוֹתָם הַמֶּלֶךְ שֶׁמָּא יָבוֹא בַּעֲלֵיהֶן מִקֹּדֶם וְיִטְּלוּ מָמוֹנָם:","הַמַּפְקִיד סֵפֶר תּוֹרָה אֵצֶל חֲבֵרוֹ גּוֹלְלוֹ פַּעַם אַחַת לִשְׁנֵים עָשָׂר חֹדֶשׁ. וְאִם כְּשֶׁהוּא גּוֹלְלוֹ פּוֹתְחוֹ וְקָרָא בּוֹ מֻתָּר. אֲבָל לֹא יִפְתַּח בִּגְלַל עַצְמוֹ וְיִקְרָא. וְהוּא הַדִּין שְׁאָר סְפָרִים. וְאִם פָּתַח וְקָרָא וְגָלַל בִּגְלַל עַצְמוֹ הֲרֵי שָׁלַח יָד בַּפִּקָּדוֹן וְנִתְחַיֵּב בָּאֳנָסִין. הִפְקִיד אֶצְלוֹ כְּסוּת שֶׁל צֶמֶר מְנַעְנְעָהּ אַחַת לִשְׁלֹשִׁים יוֹם כְּדֶרֶךְ שֶׁאָמְרוּ בַּאֲבֵדָה כָּךְ אָמְרוּ בַּפִּקָּדוֹן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה שֶׁזּוֹ חוֹבָה עָלָיו מִשּׁוּם הֶשֵּׁב אֲבֵדָה לַבְּעָלִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּפִקָּדוֹן שֶׁהָלְכוּ בְּעָלָיו לִמְדִינַת הַיָּם אֲבָל אִם הָיוּ עִמּוֹ בְּאוֹתָהּ הָאָרֶץ הֲרֵי זֶה לֹא יִגַּע בּוֹ אַף עַל פִּי שֶׁהוּא אָבֵד:","כָּל הַמּוֹכֵר פִּקָּדוֹן עַל פִּי בֵּית דִּין הֲרֵי זֶה מוֹכֵר לַאֲחֵרִים וְאֵינוֹ מוֹכֵר לְעַצְמוֹ מִפְּנֵי הַחֲשָׁד וְהַדָּמִים יִהְיוּ מֻנָּחִים אֶצְלוֹ וְיֵשׁ לוֹ לְהִשְׁתַּמֵּשׁ בָּהֶן. לְפִיכָךְ הֲרֵי הוּא עֲלֵיהֶן שׁוֹמֵר שׂוֹכֵר אַף עַל פִּי שֶׁעֲדַיִן לֹא נִשְׁתַּמֵּשׁ בָּהֶן:","הַמַּפְקִיד מָעוֹת אֵצֶל חֶנְוָנִי אוֹ הַשֻּׁלְחָנִי אִם הָיוּ צְרוּרִין וַחֲתוּמִין אוֹ קְשׁוּרִין קֶשֶׁר מְשֻׁנֶּה הֲרֵי זֶה לֹא יִשְׁתַּמֵּשׁ בָּהֶן לְפִיכָךְ אִם אָבְדוּ אוֹ נִגְנְבוּ אֵינוֹ חַיָּב בְּאַחֲרָיוּתָן. וְאִם אֵינָן חֲתוּמִין וְלֹא קְשׁוּרִין קֶשֶׁר מְשֻׁנֶּה אַף עַל פִּי שֶׁהֵן צְרוּרִין יֵשׁ לוֹ לְהִשְׁתַּמֵּשׁ בָּהֶן לְפִיכָךְ הוּא נַעֲשֶׂה עֲלֵיהֶם שׁוֹמֵר שָׂכָר וְאִם אָבְדוּ אוֹ נִגְנְבוּ חַיָּב בְּאַחֲרָיוּתָן וְאִם נֶאֶנְסוּ כְּגוֹן שֶׁאָבְדוּ בְּלִסְטִים מְזֻיָּן הֲרֵי זֶה פָּטוּר:","בַּמֶּה דְּבָרִים אֲמוּרִים קֹדֶם שֶׁיִּשְׁתַּמֵּשׁ בָּהֶן אֲבָל אַחַר שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן נִתְחַיֵּב בְּאַחֲרָיוּתָן כְּכָל מִלְוֶה שֶׁבָּעוֹלָם עַד שֶׁיַּחְזִירֵם לַבְּעָלִים:","הַמַּפְקִיד מָעוֹת אֵצֶל בַּעַל הַבַּיִת בֵּין צְרוּרִין בֵּין מֻתָּרִין הֲרֵי זֶה לֹא יִשְׁתַּמֵּשׁ בָּהֶן לְפִיכָךְ אִם אָבְדוּ אוֹ נִגְנְבוּ אֵינוֹ חַיָּב בְּאַחֲרָיוּתָן. וְהוּא שֶׁיִּטְמְנֵם בַּקַּרְקַע כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמַּפְקִיד חָבִית אֵצֶל חֲבֵרוֹ בֵּין שֶׁיִּחֲדוּ לָהּ הַבְּעָלִים מָקוֹם בֵּין לֹא יִחֲדוּ לָהּ מָקוֹם וְטִלְטְלָהּ לְצָרְכּוֹ וְנִשְׁבְּרָה בֵּין מִתּוֹךְ יָדוֹ נִשְׁבְּרָה בֵּין אַחַר שֶׁהֶחְזִירָהּ לַמָּקוֹם שֶׁיִּחֲדוּ לָהּ נִשְׁבְּרָה חַיָּב לְשַׁלֵּם. טִלְטְלָהּ לְצָרְכָּהּ בֵּין שֶׁנִּשְׁבְּרָה מִתּוֹךְ יָדוֹ בֵּין שֶׁנִּשְׁבְּרָה מִשֶּׁהֵנִיחָהּ בְּמָקוֹם אַחֵר פָּטוּר:","אֵין מְקַבְּלִין פִּקְדוֹנוֹת לֹא מִן הַנָּשִׁים וְלֹא מִן הָעֲבָדִים וְלֹא מִן הַתִּינוֹקוֹת. קִבֵּל מִן הָאִשָּׁה יַחְזִיר לָאִשָּׁה. מֵתָה יַחְזִיר לְבַעֲלָהּ. קִבֵּל מִן הָעֶבֶד יַחְזִיר לָעֶבֶד. מֵת יַחְזִיר לְרַבּוֹ. קִבֵּל מִן הַקָּטָן יִקְנֶה לוֹ בּוֹ סֵפֶר תּוֹרָה אוֹ דֶּקֶל שֶׁיֹּאכַל בָּהֶן פֵּרוֹתָיו. וְכֻלָּן שֶׁאָמְרוּ בִּשְׁעַת מִיתָתָן שֶׁל פְּלוֹנִי הֵם אִם נֶאֱמָנִין לוֹ יַעֲשֶׂה כְּפֵרוּשָׁן וְאִם לָאו יַחְזִיר לְיוֹרְשֵׁיהֶם:","הַפִּקָּדוֹן וְהָאֲבֵדָה לֹא נִתְּנוּ לִתָּבַע אֶלָּא בִּמְקוֹמָם. כֵּיצַד. הִפְקִיד אֶצְלוֹ בִּירוּשָׁלַיִם אֵינוֹ יָכוֹל לְתָבְעוֹ בְּנֹב וְאִם הֶחְזִיר לוֹ בְּנֹב מְקַבְּלוֹ מִמֶּנּוּ. הִפְקִיד אֶצְלוֹ בַּיִּשּׁוּב וְהֵבִיא פִּקְדוֹנוֹ בַּמִּדְבָּר אֵינוֹ מְקַבְּלוֹ מִמֶּנּוּ אֶלָּא יֹאמַר לוֹ הֲרֵי הוּא בְּאַחְרָיוּתְךָ עַד שֶׁתַּחֲזִירֶנּוּ לִי בַּיִּשּׁוּב כְּדֶרֶךְ שֶׁהִפְקַדְתִּי אֶצְלְךָ בַּיִּשּׁוּב:","הַמַּפְקִיד אֵצֶל חֲבֵרוֹ וְהָלַךְ בַּעַל הַפִּקָּדוֹן לִמְדִינַת הַיָּם וַהֲרֵי הַשּׁוֹמֵר רָצָה לְפָרֵשׁ מִיַּבָּשָׁה לַיָּם אוֹ לָצֵאת בְּשַׁיָּרָא יֵשׁ מִי שֶׁהוֹרָה שֶׁאִם בָּא הַשּׁוֹמֵר וְהֵבִיא הַפִּקָּדוֹן לְבֵית דִּין נִפְטַר מֵאַחֲרָיוּת שְׁמִירָתוֹ וּדְבָרִים שֶׁל טַעַם הֵם שֶׁאֵין אוֹסְרִין זֶה בִּמְדִינָה זוֹ מִפְּנֵי פִּקָּדוֹן שֶׁל זֶה שֶׁהָלַךְ וְאִי אֶפְשָׁר לוֹ לְהוֹלִיכוֹ עִמּוֹ שֶׁמָּא יֶאֱרַע לוֹ אֹנֶס וְיִהְיֶה חַיָּב בְּאַחֲרָיוּתוֹ וּבֵית דִּין מַפְקִידִין אוֹתוֹ בְּיַד נֶאֱמָן אֶצְלָם מִשּׁוּם הֶשֵּׁב אֲבֵדָה לַבְּעָלִים:"],"Mishneh Torah, Creditor and Debtor 16":["הַחוֹב בְּאַחֲרָיוּת הַלּוֶֹה עַד שֶׁיִּפְרָעֶנּוּ לְיד הַמַּלְוֶה אוֹ לְיַד שְׁלוּחוֹ. אָמַר לוֹ הַמַּלְוֶה זְרֹק לִי חוֹבִי וְהִפָּטֵר וּזְרָקוֹ וְאָבַד אוֹ נִשְׂרַף קֹדֶם שֶׁיַּגִּיעַ לְיַד הַמַּלְוֶה פָּטוּר. אָמַר לוֹ זְרֹק לִי חוֹבִי בְּתוֹרַת גִּטִּין. הָיוּ הַמָּעוֹת קְרוֹבוֹת לַלּוֶֹה הֲרֵי עֲדַיִן בְּאַחֲרָיוּתוֹ. הָיוּ קְרוֹבוֹת לַמַּלְוֶה נִפְטָר הַלּוֶֹה. מֶחֱצָה עַל מֶחֱצָה אִם אָבְדוּ מִשָּׁם אוֹ נִגְנְבוּ מְשַׁלֵּם הַלּוֶֹה מֶחֱצָה:","הָיָה רְאוּבֵן חַיָּב לְשִׁמְעוֹן מָנֶה וְאָמַר לְלֵוִי הוֹלֵךְ לְשִׁמְעוֹן מָנֶה זֶה שֶׁאֲנִי חַיָּב לוֹ. אִם בָּא לַחְזֹר אֵינוֹ חוֹזֵר וְהוּא חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיַּגִּיעַ הַמָּנֶה לְשִׁמְעוֹן. הֶחְזִיר לֵוִי אֶת הַמָּנֶה לִרְאוּבֵן שְׁנֵיהֶן חַיָּבִין בְּאַחֲרָיוּתוֹ עַד שֶׁיַּגִּיעַ לְיַד שִׁמְעוֹן כָּל חוֹבוֹ:","רְאוּבֵן שֶׁהָיָה חַיָּב לְשִׁמְעוֹן מָנֶה וְאָמַר שִׁמְעוֹן לִרְאוּבֵן מָנֶה שֶׁיֵּשׁ לִי בְּיָדְךָ תְּנֵהוּ לְלֵוִי וְהָיוּ שְׁלָשְׁתָּן עוֹמְדִין וְקִבֵּל לֵוִי וְנִמְצָא רְאוּבֵן עָנִי וְאֵין לוֹ מִמַּה שֶּׁיִּגְבֶּה מִמֶּנּוּ הֲרֵי לֵוִי חוֹזֵר בַּחוֹב שֶׁל שִׁמְעוֹן שֶׁזֶּה הִטְעָהוּ. וְאִם יָדַע לֵוִי שֶׁהוּא עָנִי אוֹ שֶׁהָיָה עָשִׁיר בְּאוֹתָהּ שָׁעָה וְהֶעֱנִי אֵינוֹ יָכוֹל לַחְזֹר שֶׁהֲרֵי קִבֵּל. טָעַן לֵוִי שֶׁהָיָה רְאוּבֵן עָנִי וְהִטְעָהוּ וְשִׁמְעוֹן אוֹמֵר עָשִׁיר הָיָה וְהֶעֱנִי יֵרָאֶה לִי שֶׁעַל שִׁמְעוֹן לְהָבִיא רְאָיָה וְאַחַר כָּךְ יִפָּטֵר מֵחוֹב לֵוִי. לֹא יִהְיֶה אֶלָּא שׁוֹבֵר בְּיָדוֹ. אוֹמְרִים לוֹ קַיֵּם שׁוֹבֶרְךָ וְהִפָּטֵר:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת מִקָּח וּמִמְכָּר שֶׁרְאוּבֵן שֶׁלֹּא הָיָה לוֹ אֵצֶל שִׁמְעוֹן כְּלוּם וְהָיָה רְאוּבֵן חַיָּב לְלֵוִי מָנֶה וְהִמְחָהוּ אֵצֶל שִׁמְעוֹן אַף עַל פִּי שֶׁהִמְחָהוּ בְּמַעֲמַד שְׁלָשְׁתָּן לֹא קָנָה. וְאִם רָצָה שִׁמְעוֹן שֶׁלֹּא יִתֵּן לֹא יִתֵּן וְאִם נָתַן חוֹזֵר וְגוֹבֶה מֵרְאוּבֵן שֶׁהֲרֵי עַל פִּיו נָתַן. וְכֵן אִם רָצָה לֵוִי לַחְזֹר וְלוֹמַר אֵינִי רוֹצֶה לִגְבּוֹת מִשִּׁמְעוֹן חוֹזֵר וְגוֹבֶה מֵרְאוּבֵן וְאַף עַל פִּי שֶׁנִּפְרָע מִקְצָת מִשִּׁמְעוֹן חוֹזֵר וְגוֹבֶה הַשְּׁאָר מֵרְאוּבֵן:","חֶנְוָנִי שֶׁהָיָה נוֹתֵן לְבַעַל הַבַּיִת מִן הַחֲנוּת כָּל מַה שֶּׁיִּרְצֶה בְּתוֹרַת הַלְוָאָה וּמַקִּיפוֹ עַד שֶׁיִּתְקַבֵּץ הַכּל וּפוֹרֵעַ לוֹ וְאָמַר לוֹ בַּעַל הַבַּיִת תֵּן לַפּוֹעֲלִים סֶלַע אוֹ לְבַעַל חוֹבִי מָנֶה שֶׁיֵּשׁ לוֹ אֶצְלִי וַאֲנִי אֶתֵּן לְךָ וַהֲרֵי הַחֶנְוָנִי אוֹמֵר נָתַתִּי וְהַפּוֹעֵל אוֹ בַּעַל חוֹבוֹ אוֹמֵר לֹא לָקַחְתִּי הֲרֵי הַפּוֹעֵל אוֹ בַּעַל חוֹב נִשְׁבָּע וְנוֹטֵל מִבַּעַל הַבַּיִת חוֹבוֹ וְכֵן הַחֶנְוָנִי נִשְׁבָּע וְנוֹטֵל מִבַּעַל הַבַּיִת מַה שֶּׁטָּעַן שֶׁנָּתַן שֶׁהֲרֵי הוּא אָמַר לוֹ לִתֵּן. וְהַפּוֹעֵל נִשְׁבָּע בְּמַעֲמַד הַחֶנְוָנִי וְכֵן הַחֶנְוָנִי בְּמַעֲמַד הַפּוֹעֵל אוֹ בַּעַל חוֹב כְּדֵי שֶׁיִּכָּלְמוּ זֶה מִזֶּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וּשְׁבוּעָה זוֹ תַּקָּנַת חֲכָמִים הִיא בִּנְקִיטַת חֵפֶץ מִפְּנֵי שֶׁבָּאִין שְׁנֵיהֶן לִטּל. לְפִיכָךְ אִם מֵת הַחֶנְוָנִי נוֹטֵל בַּעַל חוֹב בְּלֹא שְׁבוּעָה וְכֵן אִם מֵת פּוֹעֵל אוֹ בַּעַל חוֹב הַחֶנְוָנִי נוֹטֵל בְּלֹא שְׁבוּעָה שֶׁהֲרֵי אֵין בַּעַל הַבַּיִת מַפְסִיד כְּלוּם וְאֵינוֹ מְשַׁלֵּם אֶלָּא תַּשְׁלוּם אֶחָד:","הַחֶנְוָנִי אוֹמֵר אַתָּה אָמַרְתָּ לִתֵּן לָזֶה מָנֶה אוֹ צִוִּיתָ וְאָמַרְתָּ לִי אִם יָבוֹא פְּלוֹנִי תֵּן לוֹ וּבַעַל הַבַּיִת אוֹמֵר לֹא אָמַרְתִּי לְךָ הֲרֵי בַּעַל הַבַּיִת נִשְׁבָּע הֶסֵּת וְנִפְטָר וְהַחֶנְוָנִי עוֹשֶׂה דִּין עִם זֶה שֶׁנָּתַן לוֹ. וְכֵן אִם אָמַר הַחֶנְוָנִי לְבַעַל הַבַּיִת הַמַּקִּיפוֹ כָּתוּב בְּפִנְקָסִי שֶׁיֵּשׁ לִי אֶצְלְךָ מָנֶה וּבַעַל הַבַּיִת אוֹמֵר אֵינִי יוֹדֵעַ נִשְׁבָּע בַּעַל הַבַּיִת הֶסֵּת שֶׁאֵינוֹ יוֹדֵעַ וְנִפְטָר כְּדִין כָּל טוֹעֵן עַל חֲבֵרוֹ לְכָל דָּבָר וְאֵין בָּזֶה תַּקָּנַת חֲכָמִים:","רְאוּבֵן שֶׁהוֹצִיא שְׁטַר חוֹב שֶׁיֵּשׁ לְלֵוִי עַל שִׁמְעוֹן וְטָעַן שֶׁלֵּוִי נְתָנוֹ לוֹ בִּכְתִיבָה וּמְסִירָה וְאָבַד הַשְּׁטָר שֶׁהִקְנָהוּ בּוֹ אוֹ שֶׁטָּעַן שֶׁהִקְנָהוּ לוֹ עַל גַּב הַקַּרְקַע הֲרֵי זֶה גּוֹבֶה אוֹתוֹ מִשִּׁמְעוֹן הוֹאִיל וְיוֹצֵא מִתַּחַת יָדוֹ. טָעַן שִׁמְעוֹן שֶׁפָּרַע לְלֵוִי וְאָמַר יִשָּׁבַע לִי יִשָּׁבַע לֵוִי לְשִׁמְעוֹן וְאַחַר כָּךְ יִגְבֶּה רְאוּבֵן. הוֹדָה לוֹ שֶׁפָּרַע יְשַׁלֵּם לֵוִי לִרְאוּבֵן. טָעַן לֵוִי שֶׁלֹּא מָכַר וְלֹא נָתַן שְׁטָר זֶה נִשְׁבָּע הֶסֵּת וְנִפְטָר:","שְׁטָר שֶׁהָיָה בְּיַד שָׁלִישׁ וְהוֹצִיא מִתַּחַת יָדוֹ בְּבֵית דִּין וְאָמַר פָּרוּעַ הוּא נֶאֱמָן אַף עַל פִּי שֶׁהַשְּׁטָר מְקֻיָּם שֶׁאִלּוּ רָצָה הָיָה שׂוֹרְפוֹ אוֹ קוֹרְעוֹ. וְכֵן אִם מֵת הַשָּׁלִישׁ וְנִמְצָא כְּתָב יוֹצֵא מִתַּחַת יְדֵי שָׁלִישׁ שֶׁשְּׁטָר זֶה הַמֻּנָּח אֶצְלוֹ פָּרוּעַ הוּא הֲרֵי זֶה פָּרוּעַ אַף עַל פִּי שֶׁאֵין עֵדִים עַל הַכְּתָב. אֲבָל כְּתָב שֶׁיָּצָא מִתַּחַת יְדֵי מַלְוֶה שֶׁשְּׁטָר פְּלוֹנִי פָּרוּעַ אֲפִלּוּ הָיָה בִּכְתַב יְדֵי הַמַּלְוֶה אֵינוֹ אֶלָּא כְּמִשְׂחָק:","הָיוּ עֵדִים עַל הַכְּתָב אִם הָיוּ מְקֻיָּמִין הֲרֵי הַשְּׁטָר פָּרוּעַ. וְאִם אֵין עָלָיו קִיּוּם יִשְׁאֲלוּ הָעֵדִים הַחֲתוּמִין עַל זֶה הַשּׁוֹבֵר. אִם לֹא יָדְעוּ אוֹ שֶׁאֵין הָעֵדִים מְצוּיִין הוֹאִיל וּמִתַּחַת יְדֵי הַמַּלְוֶה אוֹ מִתַּחַת יְדֵי יוֹרְשָׁיו יָצָא אֵין הַשּׁוֹבֵר כְּלוּם:","נִמְצָא הַשְּׁטָר בֵּין שְׁטָרוֹת פְּרוּעִין הֲרֵי זֶה פָּרוּעַ וְאַף עַל פִּי שֶׁאֵין עֵדִים עַל הַכְּתָב הַנִּמְצָא. וְכֵן אִם נִמְצָא כָּתוּב בְּגוּפוֹ שֶׁל שְׁטָר בֵּין מִפָּנָיו בֵּין מֵאֲחוֹרָיו וַאֲפִלּוּ בְּמִקְצָתוֹ שְׁטָר זֶה פָּרוּעַ אוֹ נִפְרָע מִמֶּנּוּ כָּךְ וְכָךְ עוֹשִׂין עַל פִּי הַכְּתָב וְאַף עַל פִּי שֶׁאֵין עַל הַכְּתָב עֵדִים וְאַף עַל פִּי שֶׁיָּצָא מִתַּחַת יְדֵי הַמַּלְוֶה שֶׁאִלּוּ לֹא נִפְרָע לֹא הָיָה כּוֹתֵב עַל הַשְּׁטָר:","הַמּוֹצֵא שְׁטָר בֵּין שִׁטְרוֹתָיו וְאֵין יוֹדֵעַ מַה טִּיבוֹ יִהְיֶה מֻנָּח עַד שֶׁיָּבוֹא אֵלִיָּהוּ:","הָאוֹמֵר לְבָנָיו שְׁטָר בֵּין שִׁטְרוֹתַי פָּרוּעַ וְאֵינִי יוֹדֵעַ אֵיזֶה הוּא שִׁטְרוֹתָיו כֻּלָּן פְּרוּעִין. נִמְצָא לְאֶחָד שָׁם שְׁנֵי שְׁטָרוֹת הַגָּדוֹל פָּרוּעַ וְהַקָּטָן אֵינוֹ פָּרוּעַ. אָמַר לַחֲבֵרוֹ שְׁטָר לְךָ בְּיָדִי פָּרוּעַ הַגָּדוֹל פָּרוּעַ וְהַקָּטָן אֵינוֹ פָּרוּעַ. חוֹב לְךָ בְּיָדִי פָּרוּעַ כָּל שְׁטָרוֹת שֶׁיֵּשׁ לוֹ עָלָיו כֻּלָּן פְּרוּעִין:"],"Mishneh Torah, Creditor and Debtor 27":["שְׁטָר שֶׁכָּתוּב בְּכָל לָשׁוֹן וּבְכָל כְּתָב אִם הָיָה עָשׂוּי כְּתִקּוּן שִׁטְרֵי יִשְׂרָאֵל שֶׁאֵינָן יְכוֹלִין לְהִזְדַּיֵּף וְלֹא לְהוֹסִיף וְלֹא לִגְרֹעַ וְהָיוּ עֵדָיו יִשְׂרָאֵל וְיוֹדְעִין לִקְרוֹתוֹ הֲרֵי הוּא כָּשֵׁר וְגוֹבִין בּוֹ מִן הַמְשֻׁעְבָּדִין. אֲבָל כָּל הַשְּׁטָרוֹת שֶׁחוֹתְמֵיהֶן עַכּוּ\"ם הֲרֵי אֵלּוּ פְּסוּלִין חוּץ מִשִּׁטְרֵי מִקָּח וּמִמְכָּר וְשִׁטְרֵי חוֹב. וְהוּא שֶׁיִּתֵּן הַמָּעוֹת בִּפְנֵיהֶם וְיִכְתְּבוּ בַּשְּׁטָר לְפָנֵינוּ מָנָה פְּלוֹנִי לִפְלוֹנִי כָּךְ וְכָךְ דְּמֵי הַמֶּכֶר אוֹ מְעוֹת הַחוֹב. וְהוּא שֶׁיִּהְיוּ עֲשׂוּיִין בְּעַרְכָּאוֹת שֶׁלָּהֶם. אֲבָל בִּמְקוֹם קִבּוּץ פְּלִילֵיהֶן בְּלֹא קִיּוּם הַשּׁוֹפֵט שֶׁלָּהֶם לֹא יוֹעִילוּ כְּלוּם. וְכֵן צְרִיכִין עֵדֵי יִשְׂרָאֵל שֶׁיָּעִידוּ עַל אֵלּוּ הָעַכּוּ\"ם שֶׁהֵן עֵדֵי שְׁטָר וְעַל זֶה הַשּׁוֹפֵט שֶׁלָּהֶן שֶׁקִּיֵּם עֵדוּתָן שֶׁאֵינָן יְדוּעִין בְּקַבְּלָנוּת שֹׁחַד. וְאִם חָסְרוּ שִׁטְרֵי הָעַכּוּ\"ם דָּבָר מִכָּל אֵלּוּ הֲרֵי הֵן כְּחֶרֶס. וְכֵן שִׁטְרֵי [חוֹב] וְהוֹדָאוֹת וּמַתָּנוֹת וּפְשָׁרוֹת וּמְחִילוֹת שֶׁהֵן בְּעֵדִים שֶׁלָּהֶן אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן כָּל הַדְּבָרִים שֶׁמָּנִינוּ הֲרֵי הֵן כַּחֲרָסִים. וְהוֹרוּ רַבּוֹתַי שֶׁאֲפִלּוּ שִׁטְרֵי חוֹב שֶׁלָּהֶן שֶׁנָּתְנוּ הַמָּעוֹת בִּפְנֵיהֶם פְּסוּלִין וְלֹא הִכְשִׁירוּ אֶלָּא שִׁטְרֵי מִקָּח וּמִמְכָּר שֶׁנָּתְנוּ הַמָּעוֹת בִּפְנֵיהֶם. וְאֵין אֲנִי מוֹדֶה בָּזֶה. אִם לֹא יָדְעוּ דַּיָּנֵי יִשְׂרָאֵל לִקְרוֹת שְׁטָר זֶה הַנַּעֲשָׂה בְּעַרְכָּאוֹת שֶׁל עַכּוּ\"ם נוֹתְנוֹ לִשְׁנֵי עַכּוּ\"ם זֶה שֶׁלֹּא בִּפְנֵי זֶה וְקוֹרִין לוֹ שֶׁנִּמְצָא כָּל אֶחָד מֵהֶן כְּמֵסִיחַ לְפִי תֻּמּוֹ וְגוֹבֶה בּוֹ מִבְּנֵי חוֹרִין אֲבָל אֵין טוֹרְפִין בּוֹ מִפְּנֵי שֶׁאֵין לוֹ קוֹל שֶׁהֲרֵי לֹא יָדְעוּ הַלָּקוֹחוֹת בְּמַה שֶּׁנַּעֲשָׂה בָּעַכּוּ\"ם:","שְׁטָר שֶׁעֵדָיו עַכּוּ\"ם שֶׁמְּסָרוֹ הַלּוֶֹה לְיַד הַמַּלְוֶה אוֹ הַמּוֹכֵר לְיַד הַלּוֹקֵחַ בִּפְנֵי שְׁנֵי עֵדִים מִיִּשְׂרָאֵל אַף עַל פִּי שֶׁאֵינוֹ עָשׂוּי בְּעַרְכָּאוֹת שֶׁל עַכּוּ\"ם וְאֵין בּוֹ כָּל הַדְּבָרִים שֶׁמָּנִינוּ הֲרֵי זֶה גּוֹבֶה מִבְּנֵי חוֹרִין. וְהוּא שֶׁיִּהְיוּ הָעֵדִים שֶׁמָּסַר בִּפְנֵיהֶם יוֹדְעִין לִקְרוֹתוֹ וּקְרָאוּהוּ כְּשֶׁמְּסָרוֹ בִּפְנֵיהֶן וְיִהְיֶה כְּתִקּוּן שְׁטַר יִשְׂרָאֵל שֶׁאֵינוֹ יָכוֹל לְהִזְדַּיֵּף וְלֹא לְהוֹסִיף וְלֹא לִגְרֹעַ. וְלָמָּה לֹא יִגְבֶּה בּוֹ מִן הַמְשֻׁעְבָּדִים מִפְּנֵי שֶׁאֵין לוֹ קוֹל:","תִּקּוּן שִׁטְרֵי יִשְׂרָאֵל כָּךְ הוּא. כָּל הַשְּׁטָרוֹת כֻּלָּן צָרִיךְ שֶׁיַּחֲזֹר מֵעִנְיָנוֹ שֶׁל שְׁטָר בְּשִׁיטָה אַחֲרוֹנָה [אֶלָּא] שֶׁאֵין לְמֵדִין מִשִּׁיטָה אַחֲרוֹנָה שֶׁמָּא הָיוּ הָעֵדִים מְרֻחָקִין מִגּוּפוֹ שֶׁל שְׁטָר בִּכְדֵי הַשִּׁיטָה וּבָא זֶה הַמְזַיֵּף וְכָתַב בְּאוֹתוֹ הָרֶוַח שִׁיטָה זוֹ:","עֵדִים שֶׁהָיוּ מְרֻחָקִין מִן הַכְּתָב שְׁתֵּי שִׁיטִין פָּסוּל. פָּחוֹת מִכָּאן כָּשֵׁר. שְׁתֵּי שִׁיטִין שֶׁאָמְרוּ בִּכְתַב יְדֵי עֵדִים וְלֹא בִּכְתַב יְדֵי סוֹפֵר שֶׁכָּל הַמְזַיֵּף אֵינוֹ הוֹלֵךְ אַחַר הַסּוֹפֵר אֶלָּא אַחַר הָעֵדִים. וּשְׁתֵּי שִׁיטִין אֵלּוּ הֵן וַאֲוִירָן כְּגוֹן לָמֶ\"ד עַל כָּ\"ף. הָיוּ הָעֵדִים מְרֻחָקִין מִן הַכְּתָב יֶתֶר עַל שְׁתֵּי שִׁיטִין וְהָיָה הָרֶוַח שֶׁבֵּין הַכְּתָב וְהָעֵדִים מָלֵא בְּעֵדִים פְּסוּלִין אוֹ קְרוֹבִים הֲרֵי זֶה כָּשֵׁר שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהִזְדַּיֵּף. וְאִם מִלְּאָהוּ בִּשְׂרִיטָה שֶׁל דְּיוֹ פָּסוּל שֶׁמָּא הָעֵדִים עַל הַשְּׂרִיטוֹת חָתְמוּ וְלֹא עַל גּוּפוֹ [שֶׁל שְׁטָר]. הָיָה הַשְּׁטָר כֻּלּוֹ עִם עֵדָיו בְּשִׁיטָה אַחַת הֲרֵי זֶה כָּשֵׁר:","הָיָה הַשְּׁטָר בְּשִׁיטָה זוֹ וְהָעֵדִים בְּשִׁיטָה שְׁנִיָּה פָּסוּל שֶׁמָּא אֵלּוּ הָעֵדִים הָיוּ מְרֻחָקִין מִן הַשְּׁטָר כָּשֵׁר שִׁיטָה אַחַת וְחָתַךְ כָּל הַשְּׁטָר וְכָתַב זֶה הַשְּׁטָר בְּאוֹתָהּ הַשִּׁיטָה וְנִמְצְאוּ כָּל אֵלּוּ הָעֵדִים חֲתוּמִים עָלָיו. וְכֵן אִם הָיָה הַשְּׁטָר וּשְׁנֵי עֵדִים בְּשִׁיטָה אַחַת וּשְׁנֵי עֵדִים אֲחֵרִים בְּשִׁיטָה שְׁנִיָּה וְאָמַר אֲנִי נִתְכַּוַּנְתִּי לְרַבּוֹת הָעֵדִים אֵין מְקַיְּמִין שְׁטָר זֶה מֵעֵדִים שֶׁל מַטָּה בְּשִׁיטָה שְׁנִיָּה אֶלָּא מֵעֵדִים שֶׁל מַעְלָה. שֶׁמָּא בַּשִּׁיטָה שֶׁהָיְתָה בֵּין הָעֵדִים שֶׁל מַטָּה וּבֵין הַשְּׁטָר שֶׁחָתַךְ כָּתַב שְׁטָר זֶה וּשְׁנֵי עֵדָיו:","קִיּוּם בֵּית דִּין צָרִיךְ שֶׁיִּהְיֶה סָמוּךְ לִכְתַב יְדֵי עֵדִים אוֹ סָמוּךְ לְצַד הַשְּׁטָר אוֹ מֵאֲחוֹרָיו כְּנֶגֶד הַכְּתָב. וְאִם הָיָה בֵּין הַקִּיּוּם וְהַשְּׁטָר רֶוַח שִׁיטָה אַחַת פָּסוּל שֶׁמָּא יַחְתֹּךְ הַשְּׁטָר שֶׁנִּתְקַיֵּם וִיזַיֵּף בְּאוֹתָהּ שִׁיטָה שְׁטָר וּשְׁנֵי עֵדָיו. וְנִמְצָא הַקִּיּוּם עַל שְׁטָר מְזֻיָּף:","הִרְחִיק אֶת הַקִּיּוּם מִן הַשְּׁטָר יֶתֶר עַל שְׁתֵּי שִׁיטִין וּמָלֵא כָּל הָרֶוַח שְׂרִיטוֹת דְּיוֹ כָּשֵׁר שֶׁהֲרֵי אֵינוֹ יָכוֹל לְזַיֵּף וְאֵין חוֹשְׁשִׁין לְבֵית דִּין שֶׁיְּקַיְּמוּ קִיּוּם עַל הַשְּׂרִיטוֹת אֶלָּא עַל גּוּפוֹ שֶׁל שְׁטָר:","כָּל הַמְּחָקִין כֻּלָּן צָרִיךְ שֶׁיִּכְתֹּב קִיּוּמֵיהֶן בְּסוֹף הַשְּׁטָר וְיֹאמַר אוֹת פְּלוֹנִית אוֹ מִלָּה פְּלוֹנִית אוֹ שִׁיטָה פְּלוֹנִית עַל מַחַק אוֹ תְּלוּיָה וְהַכּל קַיָּם. וְאִם הָיָה הַמַּחַק בְּמָקוֹם שָׁרִיר וְקַיָּם וּבְשִׁעוּר שָׁרִיר וְקַיָּם אַף עַל פִּי שֶׁחָזַר וְקִיְּמוֹ פָּסוּל שֶׁמָּא מְחָקוֹ וְכָתַב דָּבָר שֶׁזִּיֵּף וְחָזַר וְקִיְּמוֹ בָּרֶוַח שֶׁבֵּין הַכְּתָב וְהָעֵדִים:","שְׁטָר הַבָּא הוּא וְעֵדָיו עַל הַמַּחַק כָּשֵׁר. וְאִם תֹּאמַר מוֹחֵק וְחוֹזֵר וּמוֹחֵק אֵינוֹ דּוֹמֶה מִי שֶׁנִּמְחַק פַּעַם אַחַת לְנִמְחַק שְׁתֵּי פְּעָמִים. וְאִם תֹּאמַר שֶׁמָּא נִמְחַק שְׁתֵּי פְּעָמִים מְקוֹם הָעֵדִים וְאַחַר שֶׁכָּתַב הַשְּׁטָר חוֹזֵר וּמוֹחֲקוֹ וְכוֹתֵב כָּל מַה שֶּׁיִּרְצֶה שֶׁהֲרֵי הוּא וְעֵדָיו כֻּלּוֹ שָׁוֶה מִפְּנֵי שֶׁנִּמְחַק הַכּל שְׁתֵּי פְּעָמִים. כְּבָר תִּקְּנוּ חֲכָמִים שֶׁלֹּא יִהְיוּ הָעֵדִים חוֹתְמִין עַל שְׁטָר מָחוּק אֶלָּא אִם כֵּן נִמְחַק בִּפְנֵיהֶם:","שְׁטָר הַבָּא הוּא וְעֵדָיו עַל הַמַּחַק וְהַקִּיּוּם מִלְּמַטָּה עַל הַנְּיָר אֵין מְקַיְּמִין אוֹתוֹ מֵעֵדֵי הַקִּיּוּם אֶלָּא מֵעֵדִים שֶׁלְּמַעְלָה שֶׁמָּא הַקִּיּוּם הָיָה רָחוֹק מִן הַשְּׁטָר הַרְבֵּה וְהָיָה הָרֶוַח מָלֵא שְׂרִיטוֹת שֶׁל דְּיוֹ וְחָתַךְ גּוּף הַשְּׁטָר וּמָחַק הַשְּׂרִיטוֹת וְכָתַב הַשְּׁטָר וְעֵדָיו עַל הַמַּחַק:","שְׁטָר הַבָּא עַל הַנְּיָר וְעֵדָיו עַל הַמַּחַק פָּסוּל שֶׁמָּא יִמְחֹק הַשְּׁטָר וְיִזְדַּיֵּף וְנִמְצָא הוּא וְעֵדָיו עַל הַמַּחַק. וְאִם כָּתְבוּ הָעֵדִים אֲנַחְנוּ הָעֵדִים חָתַמְנוּ עַל הַמַּחַק וְהַשְּׁטָר עַל הַנְּיָר כָּשֵׁר. וְכוֹתְבִין כֵּן בֵּין עֵד לְעֵד כְּדֵי שֶׁלֹּא יְזַיֵּף:","שְׁטָר הַבָּא עַל הַמַּחַק וְעֵדָיו עַל הַנְּיָר פָּסוּל. וַאֲפִלּוּ כָּתְבוּ הָעֵדִים אֲנַחְנוּ עֵדִים חָתַמְנוּ עַל הַנְּיָר וְהַשְּׁטָר עַל הַמַּחַק. מִפְּנֵי שֶׁהוּא מוֹחֵק אוֹתוֹ פַּעַם שְׁנִיָּה וְכוֹתֵב כָּל מַה שֶּׁיִּרְצֶה וְכֵיוָן שֶׁכֻּלּוֹ נִמְחַק שְׁתֵּי פְּעָמִים אֵינוֹ נִכָּר. שֶׁאִלּוּ הָיָה בּוֹ מָקוֹם הַנִּמְחָק פַּעַם אַחַת וּמָקוֹם הַנִּמְחַק שְׁתֵּי פְּעָמִים הָיָה נִכָּר. וּמִתִּקּוּן הַשְּׁטָרוֹת לְהִתְבּוֹנֵן בַּשְּׁטָר בְּוָאוִי\"ן וְזַיִנִּי\"ן שֶׁלּוֹ שֶׁלֹּא יְהוּ דְּחוּקִין בֵּין הַתֵּבוֹת שֶׁמָּא זִיֵּף וְהוֹסִיף זוֹ. וְלֹא יִהְיוּ מְרֻחָקִין שֶׁמָּא מָחַק אוֹת אַחַת כְּגוֹן הֵ\"א אוֹ חֵי\"ת וְהִנִּיחַ רַגְלָהּ הָאַחַת מְקוֹם וָא\"ו. וְכָל כַּיּוֹצֵא בָּזֶה מְדַקְדְּקִין בּוֹ בְּכָל לָשׁוֹן וּבְכָל כְּתָב:","מִשָּׁלֹשׁ וְעַד עֶשֶׂר אֵין כּוֹתְבִין בְּסוֹף שִׁיטָה שֶׁמָּא יְזַיֵּף וְיַחְזִיר הַשָּׁלֹשׁ לִשְׁלֹשִׁים וְהָעֶשֶׂר עֶשְׂרִים. וְאִם נִזְדַּמֵּן לוֹ בְּסוֹף שִׁיטָה מַחְזִיר הַדִּבּוּר בְּגוּפוֹ שֶׁל שְׁטָר פְּעָמִים רַבּוֹת עַד שֶׁיָּבוֹא בְּאֶמְצַע הַשִּׁיטָה:","שְׁטָר שֶׁכְּתָבוֹ מִלְּמַעְלָה מָנֶה וּמִלְּמַטָּה מָאתַיִם מִלְּמַעְלָה מָאתַיִם וּמִלְּמַטָּה מָנֶה הַכּל הוֹלֵךְ אַחַר הַתַּחְתּוֹן. וְלָמָּה אֵין הוֹלְכִין אַחַר הַפָּחוּת שֶׁבִּשְׁנֵיהֶם לְפִי שֶׁאֵין הָאֶחָד תָּלוּי בַּחֲבֵרוֹ. שֶׁאִם הָיָה כָּתוּב בּוֹ מֵאָה שֶׁהֵן מָאתַיִם אוֹ מָאתַיִם שֶׁהֵן מֵאָה הָיָה נוֹטֵל מֵאָה. אֲבָל שְׁנֵי דְּבָרִים שֶׁאֵין הָאַחֲרוֹן תָּלוּי בָּרִאשׁוֹן הַלֵּךְ אַחַר אַחֲרוֹן. הָיָה בּוֹ מִלְּמַעְלָה שֵׁם וּלְמַטָּה שֵׁם קָרוֹב לוֹ הַלֵּךְ אַחַר הַתַּחְתּוֹן. אִם כֵּן לָמָּה כּוֹתְבִין אֶת הָעֶלְיוֹן שֶׁמָּא תִּמָּחֵק אוֹת אַחַת מִן הַתַּחְתּוֹן וְיִלְמַד מִן הָעֶלְיוֹן כְּגוֹן הָיָה בָּעֶלְיוֹן חֲנָנִי אוֹ עֲנָנִי וּבַתַּחְתּוֹן חָנָן אוֹ עָנָן בְּיָדוּעַ שֶׁהוּא הַשֵּׁם הָעֶלְיוֹן. אֲבָל לֹא יִלְמֹד תַּחְתּוֹן מֵעֶלְיוֹן בִּשְׁתֵּי אוֹתִיּוֹת:","כָּתוּב בּוֹ מִלְּמַעְלָה סֵפֶל וּמִלְּמַטָּה קֵפֶל הַכּל הוֹלֵךְ אַחַר הַתַּחְתּוֹן שֶׁהַקֵּפֶל פָּחוֹת מִן הַסֵּפֶל. כָּתוּב בּוֹ מִלְּמַעְלָה קֵפֶל וּמִלְּמַטָּה סֵפֶל חוֹשְׁשִׁין שֶׁמָּא זְבוּב הֵסִיר רֶגֶל הַקּוּף וְנַעֲשֵׂית סָמֶ\"ךְ וְאֵינוֹ גּוֹבֶה אֶלָּא בְּמִדַּת קֵפֶל הַקְּטַנָּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה שֶׁיַּד בַּעַל הַשְּׁטָר עַל הַתַּחְתּוֹנָה. מַעֲשֶׂה בִּשְׁטָר שֶׁהָיָה כָּתוּב בּוֹ שֵׁשׁ מֵאוֹת וְזוּז אֶחָד וַהֲרֵי הַדָּבָר סָפֵק אִם שֵׁשׁ מֵאוֹת זוּז וְזוּז אֶחָד אוֹ שֵׁשׁ מֵאוֹת אַסְתִּירָא וְזוּז. אָמְרוּ חֲכָמִים יִטּל שֵׁשׁ מֵאוֹת אַסְתִּירָא וְזוּז שֶׁיַּד בַּעַל הַשְּׁטָר עַל הַתַּחְתּוֹנָה. אִם כֵּן לָמָּה לֹא נֶאֱמַר שֵׁשׁ מֵאוֹת פְּרוּטָה וְזוּז לְפִי שֶׁהַפְּרוּטוֹת כּוֹלֵל אוֹתָן הַסּוֹפֵר זוּזִין וְאַחַר כָּךְ כּוֹתְבִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה בְּכָל זְמַן וּבְכָל מָקוֹם לְפִי דַּרְכָּם הַיָּדוּעַ עַל פִּיו עוֹשִׂין:","שְׁטָר שֶׁכָּתוּב בּוֹ אַסְתִּירָא מֵאָה מָעֵי אוֹ שֶׁכָּתוּב בּוֹ מֵאָה מָעֵי אַסְתִּירָא הַלֵּךְ אַחַר פָּחוּת שֶׁבַּלְּשׁוֹנוֹת וְאֵינוֹ נוֹטֵל אֶלָּא אַסְתִּירָא אַחַת. שֶׁיַּד בַּעַל הַשְּׁטָר עַל הַתַּחְתּוֹנָה מִפְּנֵי שֶׁהוּא הַמּוֹצִיא מֵחֲבֵרוֹ וְאֵינוֹ מוֹצִיא אֶלָּא בְּדָבָר שֶׁאֵין בּוֹ סָפֵק. לְפִיכָךְ כָּל שְׁטָר שֶׁיֵּשׁ בּוֹ מַשְׁמַע שְׁתֵּי לְשׁוֹנוֹת שֶׁמָּא כָּךְ אוֹ שֶׁמָּא כָּךְ אֵינוֹ נוֹטֵל אֶלָּא הַפָּחוּת שֶׁבִּשְׁתֵּיהֶן. וְאִם תָּפַס בָּעֶלְיוֹנָה אֵין מוֹצִיאִין מִיָּדוֹ אֶלָּא בִּרְאָיָה בְּרוּרָה:","כָּתוּב בּוֹ מַטְבֵּעַ זָהָב אֵין פָּחוֹת מִדִּינַר זָהָב. זָהָב דִּינָרִין אוֹ דִּינָרִין זָהָב אֵין פָּחוֹת מִשְּׁוֵה שְׁנֵי דִּינָרִין שֶׁל זָהָב. זָהָב בְּדִינָרִין אֵין פָּחוֹת מִשְּׁוֵה שְׁנֵי דִּינָרִין שֶׁל כֶּסֶף מִן הַזָּהָב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה: סְלִיקוּ לְהוּ הִלְכוֹת מַלְוֶה וְלֹוֶה"],"Mishneh Torah, Daily Offerings and Additional Offerings 4":["כָּל הָעֲבוֹדוֹת הָאֵלּוּ שֶׁעוֹשִׂין בְּכָל יוֹם בְּפַיִס הָיוּ עוֹשִׂין אוֹתָן. וְכֵיצַד הָיוּ עוֹשִׂין. כָּל כֹּהֲנֵי בָּתֵּי אָבוֹת שֶׁל יוֹם נִכְנָסִין לְלִשְׁכַּת הַגָּזִית אַחַר שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר וּמְלֻבָּשִׁין הֵן בְּבִגְדֵי כְּהֻנָּה. וְהַמְמֻנֶּה שֶׁעַל הַפְּיָסוֹת עִמָּהֶן וְהֵן עוֹמְדִין בְּהַקָּפָה וְהַמְמֻנֶּה נוֹטֵל מִצְנֶפֶת מֵעַל רֹאשׁוֹ שֶׁל אֶחָד מֵהֶן וּמַחֲזִירָהּ וְהוּא הָאִישׁ שֶׁמַּתְחִילִין לִמְנוֹת מִמֶּנּוּ וּמְפִיסִין כְּמוֹ שֶׁיִּתְבָּאֵר:","וְיוֹצְאִין לַעֲבוֹדָה אֲנָשִׁים שֶׁעוֹבְדִין בּוֹ. וּשְׁאָר הַכֹּהֲנִים מוֹסְרִין אוֹתָן לְחַזָּנִין וּמַפְשִׁיטִין אוֹתָן אֶת בִּגְדֵי הַקֹּדֶשׁ וְלֹא הָיוּ מַנִּיחִין עֲלֵיהֶן אֶלָּא הַמִּכְנָסַיִם בִּלְבַד עַד שֶׁלּוֹבְשִׁין בִּגְדֵי חֹל וְחוֹזְרִין וּפוֹשְׁטִין אֶת הַמִּכְנָסַיִם שֶׁל קֹדֶשׁ וּמַחְזִירִים הַחַזָּנִים אֶת הַכֵּלִים לַחַלּוֹנוֹת:","כֵּיצַד מְפִיסִין. עוֹמְדִין בְּהֶקֵּף וּמַסְכִּימִין עַל מִנְיַן שְׁמוֹנִים מֵאָה אוֹ אֶלֶף אוֹ כָּל מִנְיַן שֶׁיַּסְכִּימוּ עָלָיו. וְהַמְמֻנֶּה אוֹמֵר לָהֶם הַצְבִּיעוּ וְהֵן מוֹצִיאִין אֶצְבְּעוֹתֵיהֶן אַחַת אוֹ שְׁתַּיִם. וְאִם הוֹצִיא שָׁלֹשׁ מוֹנִין לוֹ שָׁלֹשׁ. וְאֵין מוֹצִיאִין גּוּדָל בַּמִּקְדָּשׁ מִפְּנֵי הָרַמָּאִים שֶׁהַגּוּדָל קָצָר וְנוֹחַ לְהוֹצִיאוֹ וְלִכְפּוֹתוֹ. וְהַמּוֹצִיא גּוּדָל אֵין מוֹנִין אוֹתוֹ לוֹ. וּמַתְחִיל הַמְמֻנֶּה לִמְנוֹת מִן הָאִישׁ הַיָּדוּעַ שֶׁהֵסִיר מִצְנַפְתּוֹ תְּחִלָּה. וּמוֹנֶה עַל אֶצְבְּעוֹתֵיהֶן וְחוֹזֵר חֲלִילָה עַד שֶׁיַּשְׁלִים הַמִּנְיָן שֶׁהִסְכִּימוּ עָלָיו וְהָאִישׁ שֶׁשָּׁלֵם הַמִּנְיָן אֵצֶל אֶצְבָּעוֹ הוּא שֶׁיֵּצֵא בְּפַיִס רִאשׁוֹן לַעֲבוֹדָה:","וְלָמָּה מוֹנֶה הַמִּנְיָן שֶׁהִסְכִּימוּ עָלָיו עַל הָאֶצְבָּעוֹת שֶׁהוֹצִיאוּ וְלֹא הָיָה מוֹנֶה עַל הָאֲנָשִׁים עַצְמָן לְפִי שֶׁאָסוּר לִמְנוֹת יִשְׂרָאֵל אֶלָּא עַל יְדֵי דָּבָר אַחֵר שֶׁנֶּאֱמַר (שמואל א טו ד) \"וַיִּפְקְדֵם בַּטְּלָאִים\":","אַרְבָּעָה פְּיָסוֹת הָיוּ מְפִיסִין בְּכָל יוֹם בְּשַׁחֲרִית. הַפַּיִס הָרִאשׁוֹן מִי תּוֹרֵם אֶת הַמִּזְבֵּחַ. הֵפִיסוּ וְזָכָה מִי שֶׁזָּכָה לִתְרֹם. וְהוּא מְסַדֵּר אֶת הַמַּעֲרָכָה. וְהוּא מַעֲלֶה שְׁנֵי גִּזְרֵי עֵצִים לַמִּזְבֵּחַ. וְהוּא מַכְנִיס מַחְתָּה מְלֵאָה אֵשׁ מִן הַמִּזְבֵּחַ הַחִיצוֹן לְמִזְבַּח הַזָּהָב לְהַקְטִיר עָלֶיהָ קְטֹרֶת:","הַפַּיִס הַשֵּׁנִי זוֹכִין בּוֹ שְׁלֹשָׁה עָשָׂר עַל סֵדֶר עֲמִידָתָן. כֵּיצַד. הַמְמֻנֶּה אוֹמֵר לָהֶם הַצְבִּיעוּ וּמוֹנֶה כְּדֶרֶךְ שֶׁבֵּאַרְנוּ. וְזֶה שֶׁיָּצָא בְּפַיִס רִאשׁוֹן הוּא שׁוֹחֵט תָּמִיד שֶׁל שַׁחַר. וְהַשֵּׁנִי שֶׁעוֹמֵד בְּצִדּוֹ הוּא מְקַבֵּל אֶת דַּם הַתָּמִיד וְהוּא זוֹרְקוֹ. וְהַשְּׁלִישִׁי הַסָּמוּךְ לַשֵּׁנִי מְדַשֵּׁן הַמִּזְבֵּחַ הַפְּנִימִי שֶׁהוּא מִזְבַּח הַקְּטֹרֶת. וְהָרְבִיעִי שֶׁבְּצִדּוֹ מְדַשֵּׁן אֶת הַמְּנוֹרָה וּמֵיטִיב אֶת הַנֵּרוֹת. וְהַחֲמִישִׁי מַעֲלֶה רֹאשׁ הַתָּמִיד וְרַגְלוֹ לַכֶּבֶשׁ. וְהַשִּׁשִּׁי מַעֲלֶה שְׁתֵּי הַיָּדַיִם. וְהַשְּׁבִיעִי מַעֲלֶה הָעֹקֶץ וְהָרֶגֶל. וְהַשְּׁמִינִי מַעֲלֶה הֶחָזֶה וְהַגֵּרָה. וְהַתְּשִׁיעִי מַעֲלֶה שְׁתֵּי הַדְּפָנוֹת. וְהָעֲשִׂירִי מַעֲלֶה הַקְּרָבַיִם. וְהָאַחַד עָשָׂר מַעֲלֶה סֹלֶת הַנְּסָכִים. וְהַשְּׁנֵים עָשָׂר מַעֲלֶה הַחֲבִיתִין. וְהַשְּׁלֹשָׁה עָשָׂר מַעֲלֶה הַיַּיִן שֶׁל נְסָכִים:","הַפַּיִס הַשְּׁלִישִׁי אוֹמֵר לָהֶן הַמְמֻנֶּה לְכָל אַנְשֵׁי בֵּית אָב שֶׁל אוֹתוֹ הַיּוֹם מִי שֶׁלֹּא הִקְטִיר קְטֹרֶת מִיָּמָיו יָבוֹא וְיָפִיס. וְיִתְקַבְּצוּ אֵצֶל הַמְמֻנֶּה וְיָפִיסוּ וּמִי שֶׁיֵּצֵא בְּפַיִס זֶה רִאשׁוֹן הוּא שֶׁיִּזְכֶּה לְהַקְטִיר קְטֹרֶת:","הַפַּיִס הָרְבִיעִי מִתְקַבְּצִין כֻּלָּן וּמְפִיסִין לֵידַע מִי מַעֲלֶה אֵיבָרִים מִן הַכֶּבֶשׁ לַמִּזְבֵּחַ. הֵפִיסוּ וְזָכָה מִי שֶׁזָּכָה. תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם אֵין מְפִיסִין לוֹ פַּיִס אַחֵר. אֶלָּא כָּל כֹּהֵן שֶׁזָּכָה בַּעֲבוֹדָה מִן הָעֲבוֹדוֹת שַׁחֲרִית יִזְכֶּה בֵּין הָעַרְבַּיִם. חוּץ מִן הַקְּטֹרֶת שֶׁהֵן מְפִיסִין לָהּ פַּיִס אַחֵר בֵּין הָעַרְבַּיִם וְיָבוֹא כָּל מִי שֶׁלֹּא הִקְטִיר קְטֹרֶת מֵעוֹלָם מֵאַנְשֵׁי אוֹתוֹ בֵּית אָב וְיָפִיסוּ עָלֶיהָ. וְאִם כְּבָר הִקְטִירוּ כֻּלָּן מִימֵיהֶן מְפִיסִין לָהֶן כֻּלָּן בְּשַׁחֲרִית בְּפַיִס שְׁלִישִׁי וְזֶה שֶׁזָּכָה בָּהּ שַׁחֲרִית מַקְטִירָהּ בֵּין הָעַרְבַּיִם:","בְּשַׁבָּת שֶׁיֵּשׁ שָׁם תְּמִידִין וּמוּסָפִין וּשְׁנֵי בְּזִיכֵי לְבוֹנָה כֵּיצַד הֵם עוֹבְדִין. מְפִיסִין בְּשַׁחַר אַנְשֵׁי אוֹתוֹ בֵּית אָב שֶׁל מִשְׁמָר הַיּוֹצֵא וּמַקְרִיבִין תָּמִיד שֶׁל שַׁחַר וּשְׁנֵי כִּבְשֵׂי עוֹלָה שֶׁל מוּסָפִין. וְכָל שֶׁזָּכָה בַּעֲבוֹדָה מֵעֲבוֹדַת הַתָּמִיד שֶׁל שַׁחַר הוּא זוֹכֶה בָּהּ בִּשְׁנֵי כִּבְשֵׂי מוּסָף. וְהַמִּשְׁמָר הָאַחֵר שֶׁנִּכְנַס בְּשַׁבָּת מְפִיסִין פְּיָסוֹת אֲחֵרוֹת לְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְאֵלּוּ וְאֵלּוּ חוֹלְקִין בְּלֶחֶם הַפָּנִים:","וְאֵין אוֹכְלִין אֶת הַלֶּחֶם עַד שֶׁיַּקְטִירוּ שְׁנֵי בְּזִיכֵי לְבוֹנָה עַל הָאֵשׁ. וְהַלְּבוֹנָה טְעוּנָה מֶלַח כִּשְׁאָר הַקָּרְבָּנוֹת:","וְאַחַר קָרְבַּן הַמּוּסָפִין מַקְטִירִין שְׁנֵי הַבְּזִיכִין. וּשְׁנֵי כֹּהֲנִים מַקְרִיבִין אֶת שְׁנֵי הַבְּזִיכִין:","כֵּיצַד חוֹלְקִין לֶחֶם הַפָּנִים בְּכָל שַׁבְּתוֹת הַשָּׁנָה. מִשְׁמָר הַנִּכְנָס נוֹטֵל שֵׁשׁ חַלּוֹת. וּמִשְׁמָר הַיּוֹצֵא נוֹטֵל שֵׁשׁ. הַנִּכְנָסִין חוֹלְקִין בֵּינֵיהֶם בַּצָּפוֹן שֶׁהֲרֵי הֵן מוּכָנִים לַעֲבוֹדָה. וְהַיּוֹצְאִין חוֹלְקִין בַּדָּרוֹם. וּבִזְמַן שֶׁיִּהְיֶה יוֹם טוֹב שֶׁל אֶחָד מִשְּׁלֹשָׁה רְגָלִים בְּשַׁבָּת וְכֵן בְּשַׁבָּת שֶׁבְּתוֹךְ הֶחָג חוֹלְקִין כָּל הַמִּשְׁמָרוֹת בְּשָׁוֶה בְּלֶחֶם הַפָּנִים. וְכֵן אִם חָל יוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג בְּשַׁבָּת חוֹלְקִין כָּל הַמִּשְׁמָרוֹת בְּשָׁוֶה מֵעֶרֶב יוֹם טוֹב שֶׁהוּא שַׁבָּת בְּלֶחֶם הַפָּנִים מִפְּנֵי שֶׁהִקְדִּימוּ לַעֲבוֹדָה. וְכֵן אִם חָל יוֹם טוֹב הָאַחֲרוֹן לִהְיוֹת בְּעֶרֶב שַׁבָּת חוֹלְקִין כָּל הַמִּשְׁמָרוֹת בְּשָׁוֶה בְּלֶחֶם הַפָּנִים בְּאוֹתָהּ שַׁבָּת שֶׁהִיא מוֹצָאֵי הֶחָג. וְדָבָר זֶה תַּקָּנָה כְּדֵי שֶׁיִּתְאַחֲרוּ הַכֹּהֲנִים בִּשְׁבִיל חִלּוּק לֶחֶם הַפָּנִים וְאִם נִתְאַחֵר אֶחָד מִבַּעֲלֵי מִשְׁמָר וְלֹא בָּא יִמָּצֵא אַחֵר:","חָל יוֹם אֶחָד לְהַפְסִיק בֵּין הַשַּׁבָּת וּבֵין יוֹם טוֹב כְּגוֹן שֶׁהָיָה יוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג בְּשֵׁנִי אוֹ יוֹם טוֹב הָאַחֲרוֹן בַּחֲמִישִׁי אוֹ יוֹם שֶׁל עֲצֶרֶת שֶׁחָל לִהְיוֹת בְּשֵׁנִי אוֹ בַּחֲמִישִׁי. מִשְׁמָר שֶׁזְּמַנּוֹ קָבוּעַ בְּאוֹתָהּ שַׁבָּת נוֹטֵל עֶשֶׂר חַלּוֹת וְזֶה הַנִּכְנָס נוֹטֵל שְׁתַּיִם. שֶׁהֲרֵי לֹא נִשְׁאַר לָהֶם לַעֲבוֹדָה הֵם לְבַדָּם אֶלָּא יוֹם אֶחָד שֶׁהוּא עֶרֶב שַׁבָּת אוֹ אֶחָד בְּשַׁבָּת וּמִתְעַצְּלִין וְאֵין בָּאִין מֵהֶן אֶלָּא מְעַט:","כֹּהֵן גָּדוֹל לְעוֹלָם נוֹטֵל מִכָּל מִשְׁמָר חֲצִי הַחַלּוֹת שֶׁזָּכָה בָּהֶן שֶׁנֶּאֱמַר (ויקרא כד ט) \"וְהָיְתָה לְאַהֲרֹן וּלְבָנָיו\" מֶחֱצָה לְאַהֲרֹן וּמֶחֱצָה לְבָנָיו. וְאֵין כֹּהֵן גָּדוֹל נוֹטֵל פְּרָס שֶׁאֵין זֶה כְּבוֹדוֹ:"],"Mishneh Torah, Damages to Property 2":["אֶחָד אֲבוֹת נְזִיקִין וְאֶחָד הַתּוֹלָדוֹת אִם הָיָה הָאָב מוּעָד תּוֹלְדוֹתָיו מוּעָדוֹת וְאִם הָיָה תָּם תּוֹלְדוֹתָיו כָּמוֹהוּ. וְכָל אֲבוֹת נְזִיקִין וְכָל תּוֹלְדוֹתֵיהֶן מוּעָדִין הֵן מִתְּחִלָּתָן חוּץ מִקֶּרֶן וְתוֹלְדוֹתָיו שֶׁהֵן תָּמִים בַּתְּחִלָּה עַד שֶׁיּוּעֲדוּ כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל תּוֹלָדָה כְּאָב שֶׁלָּהּ חוּץ מִצְּרוֹרוֹת הַמְנַתְּזִין מִתַּחַת רַגְלֵי הַבְּהֵמָה בִּשְׁעַת הִלּוּכָהּ. שֶׁאַף עַל פִּי שֶׁתּוֹלֶדֶת הָרֶגֶל הֵם וּפָטוּר עֲלֵיהֶן בִּרְשׁוּת הָרַבִּים כְּרֶגֶל וְאִם הִזִּיקוּ בִּרְשׁוּת הַנִּזָּק מְשַׁלֵּם מִן הַיָּפֶה שֶׁבִּנְכָסָיו כְּרֶגֶל שֶׁהוּא אָב אַף עַל פִּי כֵן אֵינוֹ מְשַׁלֵּם אֶלָּא חֲצִי נֵזֶק:","כֵּיצַד. בְּהֵמָה שֶׁנִּכְנְסָה לַחֲצַר הַנִּזָּק וְהָלְכָה וְהָיוּ צְרוֹרוֹת מְנַתְּזִין מִתַּחַת רַגְלֶיהָ וְשָׁבְרוּ אֶת הַכֵּלִים מְשַׁלֵּם חֲצִי נֵזֶק מִן הַיָּפֶה שֶׁבִּנְכָסָיו. וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה הִיא:","וְכֵן אִם הָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וְנִתְּזוּ צְרוֹרוֹת מִתַּחַת רַגְלֶיהָ לִרְשׁוּת הַנִּזָּק וְשָׁבְרוּ אֶת הַכֵּלִים מְשַׁלֵּם חֲצִי נֵזֶק. דָּרְסָה עַל הַכְּלִי בִּרְשׁוּת הַנִּזָּק וּשְׁבָרַתּוּ וְנָפַל עַל כְּלִי אַחֵר וּשְׁבָרוֹ. עַל הָרִאשׁוֹן מְשַׁלֵּם נֵזֶק שָׁלֵם וְעַל הָאַחֲרוֹן מְשַׁלֵּם חֲצִי נֵזֶק:","הָיְתָה מְהַלֶּכֶת בִּרְשׁוּת הָרַבִּים וּבָעֲטָה וְהִתִּיזָה צְרוֹרוֹת וְהִזִּיקוּ בִּרְשׁוּת הָרַבִּים פָּטוּר. וְאִם תָּפַשׂ הַנִּזָּק רְבִיעַ נֵזֶק אֵין מוֹצִיאִין מִיָּדוֹ. שֶׁהַדָּבָר סָפֵק הוּא שֶׁמָּא שִׁנּוּי הוּא וְאֵינוֹ תּוֹלֶדֶת רֶגֶל שֶׁהֲרֵי בָּעֲטָה:","בָּעֲטָה בָּאָרֶץ בִּרְשׁוּת הַנִּזָּק וְהִתִּיזָה צְרוֹרוֹת מֵחֲמַת הַבְּעִיטָה וְהִזִּיקוּ שָׁם חַיָּב לְשַׁלֵּם רְבִיעַ נֵזֶק שֶׁזֶּה שִׁנּוּי הוּא בְּהַתָּזַת הַצְּרוֹרוֹת. וְאִם תָּפַשׂ הַנִּזָּק חֲצִי נֵזֶק אֵין מוֹצִיאִין מִיָּדוֹ. וַאֲפִלּוּ הָיְתָה מְהַלֶּכֶת בְּמָקוֹם שֶׁאִי אֶפְשָׁר לָהּ שֶׁלֹּא תַּתִּיז וּבָעֲטָה וְהִתִּיזָה מְשַׁלֵּם רְבִיעַ נֵזֶק. וְאִם תָּפַשׂ הַנִּזָּק חֲצִי נֵזֶק אֵין מוֹצִיאִין מִיָּדוֹ:","כָּל הַמְשַׁלֵּם נֵזֶק שָׁלֵם הֲרֵי הַתַּשְׁלוּמִין מָמוֹן שֶׁהוּא חַיָּב לְשַׁלְּמוֹ כְּמִי שֶׁלָּוָה מֵחֲבֵרוֹ שֶׁהוּא חַיָּב לְשַׁלֵּם. וְכָל הַמְשַׁלֵּם חֲצִי נֵזֶק הֲרֵי הַתַּשְׁלוּמִין קְנָס חוּץ מֵחֲצִי נֵזֶק שֶׁל צְרוֹרוֹת שֶׁהוּא הֲלָכָה כְּמוֹ שֶׁבֵּאַרְנוּ:","זֶה הַכְּלָל כָּל הַמְשַׁלֵּם מַה שֶּׁהִזִּיק הֲרֵי זֶה מָמוֹן וְכָל הַמְשַׁלֵּם יֶתֶר אוֹ פָּחוֹת כְּגוֹן תַּשְׁלוּמֵי כֶּפֶל אוֹ חֲצִי נֵזֶק הֲרֵי הַיָּתֵר עַל הַקֶּרֶן אוֹ הַפָּחוֹת קְנָס. וְאֵין חַיָּבִין קְנָס אֶלָּא עַל פִּי עֵדִים. אֲבָל הַמּוֹדֶה בְּכָל קְנָס מִן הַקְּנָסוֹת פָּטוּר:","תַּרְנְגוֹל שֶׁהוֹשִׁיט רֹאשׁוֹ לַאֲוִיר כְּלִי זְכוּכִית וְתָקַע בּוֹ וּשְׁבָרוֹ. אִם הָיוּ בְּתוֹכוֹ תַּבְלִין וְכַיּוֹצֵא בָּהֶן שֶׁהוֹשִׁיט רֹאשׁוֹ כְּדֵי לְאָכְלָן. עַל הַתַּבְלִין מְשַׁלֵּם נֵזֶק שָׁלֵם וְעַל הַכְּלִי מְשַׁלֵּם חֲצִי נֵזֶק כַּחֲצִי נֵזֶק צְרוֹרוֹת שֶׁכָּךְ הוּא דַּרְכּוֹ. וְאִם הָיָה הַכְּלִי רֵיקָן הֲרֵי זֶה מְשֻׁנֶּה וּמְשַׁלֵּם חֲצִי נֵזֶק כְּכָל הַקְּנָסוֹת:","וְכֵן סוּס שֶׁצָּנַף וַחֲמוֹר שֶׁנָּעַר וְשָׁבַר אֶת הַכֵּלִים מְשַׁלֵּם חֲצִי נֵזֶק. הַתַּרְנְגוֹלִין מוּעָדִין לְהַלֵּךְ כְּדַרְכָּן וּלְשַׁבֵּר. הָיָה חוּט אוֹ רְצוּעָה קָשׁוּר בְּרַגְלֵיהֶן וְנִסְתַּבֵּךְ כְּלִי בְּאוֹתוֹ הַחוּט וְנִתְגַּלְגֵּל וְנִשְׁבַּר מְשַׁלֵּם חֲצִי נֵזֶק. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁקְּשָׁרוֹ אָדָם. אֲבָל אִם נִקְשַׁר עַל רַגְלֵיהֶם מֵאֵלָיו בַּעַל הַתַּרְנְגוֹלִין פָּטוּר. וְאִם הָיוּ לַחוּט בְּעָלִים וְלֹא הָיָה הַחוּט הֶפְקֵר בַּעַל הַחוּט חַיָּב חֲצִי נֵזֶק שֶׁהֲרֵי הוּא כְּבוֹר הַמִּתְגַּלְגֵּל:","הִצְנִיעַ בַּעַל הַחוּט אֶת הַחוּט וְהַתַּרְנְגוֹלִים דָּרְסוּ עָלָיו וְהוֹצִיאוּהוּ וְנִקְשַׁר בְּרַגְלֵיהֶן וְשָׁבְרוּ בּוֹ אֶת הַכֵּלִים אַף בַּעַל הַחוּט פָּטוּר שֶׁהֲרֵי אָנוּס הוּא:","תַּרְנְגוֹלִין שֶׁהָיוּ מַפְרִיחִין מִמָּקוֹם לְמָקוֹם וְשָׁבְרוּ אֶת הַכֵּלִים. אִם בְּכַנְפֵיהֶם שָׁבְרוּ מְשַׁלֵּם נֵזֶק שָׁלֵם וְאִם בָּרוּחַ שֶׁבְּכַנְפֵיהֶם מְשַׁלֵּם חֲצִי נֵזֶק:","הָיוּ מְהַדְּסִין עַל גַּבֵּי עִסָּה אוֹ עַל גַּבֵּי פֵּרוֹת וְטִנְּפוּ אוֹ נִקְּרוּ מְשַׁלְּמִין נֵזֶק שָׁלֵם. הִזִּיקוּ בְּעָפָר אוֹ בִּצְרוֹרוֹת שֶׁהֶעֱלוּ בְּכַנְפֵיהֶן אוֹ בְּרַגְלֵיהֶן מְשַׁלְּמִין חֲצִי נֵזֶק:","הָיוּ מְחַטְּטִין בְּחֶבֶל וְנִפְסַק הַחֶבֶל וְנִשְׁבַּר הַדְּלִי מְשַׁלְּמִין נֵזֶק שָׁלֵם. וְהוּא שֶׁנִּתְגַּלְגֵּל הַדְּלִי מֵחֲמָתָן עַד שֶׁנָּפַל וְנִשְׁבַּר. וְאִם הָיָה עַל הַחֶבֶל אֹכֶל וּבָעֵת אֲכִילָתָן פְּסָקוּהוּ מְשַׁלֵּם גַּם עַל הַחֶבֶל נֵזֶק שָׁלֵם:","הַכֶּלֶב וְהַגְּדִי שֶׁקָּפְצוּ מֵרֹאשׁ הַגַּג מִלְּמַעְלָה לְמַטָּה וְשָׁבְרוּ אֶת הַכֵּלִים מְשַׁלְּמִין נֵזֶק שָׁלֵם מִפְּנֵי שֶׁמּוּעָדִים הֵן לְדָבָר זֶה. וְכֵן אִם נָפְלוּ וְהִזִּיקוּ. שֶׁעֲלִיָּתָן לְרֹאשׁ הַגַּג פְּשִׁיעָה. וְאַף עַל פִּי שֶׁנְּפִילָתָן אֹנֶס כָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס חַיָּב:","קָפְצוּ מִמַּטָּה לְמַעְלָה מְשַׁלְּמִין חֲצִי נֵזֶק. וְהוּא שֶׁנִּתְלַשׁ הַגְּדִי וְנִסְרַךְ וְקָפַץ הַכֶּלֶב. אֲבָל נִסְרַךְ הַכֶּלֶב וְדִלֵּג הַגְּדִי בֵּין מִלְּמַעְלָה לְמַטָּה בֵּין מִמַּטָּה לְמַעְלָה חַיָּבִין נֵזֶק שָׁלֵם. וְכֵן תַּרְנְגוֹל שֶׁדִּלֵּג בֵּין מִלְּמַעְלָה לְמַטָּה בֵּין מִלְּמַטָּה לְמַעְלָה מְשַׁלֵּם נֵזֶק שָׁלֵם:","כֶּלֶב שֶׁנָּטַל אֶת הַחֲרָרָה וְהָלַךְ לוֹ לַגָּדִישׁ. אִם הִנִּיחָהּ בַּגָּדִישׁ וְאָכַל אֶת הַחֲרָרָה וְהִדְלִיק אֶת הַגָּדִישׁ עַל הַחֲרָרָה וְעַל מְקוֹם הַחֲרָרָה מְשַׁלֵּם נֵזֶק שָׁלֵם וְעַל שְׁאָר הַגָּדִישׁ חֲצִי נֵזֶק. וְאִם הָיָה מְגָרֵר אֶת הַחֲרָרָה עַל הַגָּדִישׁ וְהוֹלֵךְ וְשׂוֹרֵף מְשַׁלֵּם עַל הַחֲרָרָה נֵזֶק שָׁלֵם וְעַל מְקוֹם הַגֶּחָלִים חֲצִי נֵזֶק וְעַל שְׁאָר הַגָּדִישׁ פָּטוּר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁשָּׁמַר בַּעַל הַגַּחֶלֶת אֶת אִשּׁוֹ וְסָתַם הַדֶּלֶת וּבָא הַכֶּלֶב וְחָתַר וְנָטַל אֶת הַחֲרָרָה מֵעַל הָאֵשׁ. אֲבָל אִם לֹא שָׁמַר אִשּׁוֹ בַּעַל הָאֵשׁ חַיָּב עַל שְׂרֵפַת הַגָּדִישׁ וּבַעַל הַכֶּלֶב חַיָּב עַל אֲכִילַת הַחֲרָרָה וְעַל מְקוֹמָהּ:","הַמְשַׁסֶּה כַּלְבּוֹ שֶׁל חֲבֵרוֹ בַּחֲבֵרוֹ פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם וּבַעַל הַכֶּלֶב חַיָּב חֲצִי נֵזֶק שֶׁכֵּיוָן שֶׁהוּא יוֹדֵעַ שֶׁאִם שִׁסָּה אֶת כַּלְבּוֹ לְהַזִּיק נוֹשֵׁךְ לֹא הָיָה לוֹ לְהַנִּיחוֹ. וְאִם שִׁסָּהוּ בְּעַצְמוֹ בַּעַל הַכֶּלֶב פָּטוּר שֶׁכָּל הַמְשַׁנֶּה וּבָא אַחֵר וְשִׁנָּה בּוֹ פָּטוּר:","שְׁתֵּי פָּרוֹת בִּרְשׁוּת הָרַבִּים אַחַת רְבוּצָה וְאַחַת מְהַלֶּכֶת וּבָעֲטָה מְהַלֶּכֶת בִּרְבוּצָה חַיָּב חֲצִי נֵזֶק שֶׁאַף עַל פִּי שֶׁדַּרְכָּהּ לְהַלֵּךְ עָלֶיהָ אֵין דַּרְכָּהּ לִבְעֹט בָּהּ:"],"Mishneh Torah, Defilement by Leprosy 13":["אֵין מִטַּמֵּא בִּנְגָעִים אֶלָּא בִּגְדֵי צֶמֶר וּפִשְׁתִּים בִּלְבַד. אוֹ הַשְּׁתִי אוֹ הָעֵרֶב שֶׁל צֶמֶר וּפִשְׁתִּים. וְכָל כְּלֵי הָעוֹר בֵּין קָשֶׁה בֵּין רַךְ. אַף הָעוֹר הַצָּבוּעַ בִּידֵי שָׁמַיִם מִטַּמֵּא בִּנְגָעִים. וְהַלְּבָדִים כִּבְגָדִים וּמִטַּמְּאִין בִּנְגָעִים. וְהָאֹהָלִים מִטַּמְּאִין בִּנְגָעִים בֵּין שֶׁהָיוּ שֶׁל צֶמֶר וּפִשְׁתִּים בֵּין שֶׁהָיוּ שֶׁל עוֹר:","כָּל הַבְּגָדִים שֶׁל צֶמֶר וּפִשְׁתִּים מִטַּמְּאִין בִּנְגָעִים חוּץ מִבִּגְדֵי עַכּוּ\"ם. הַלּוֹקֵחַ בְּגָדִים מִן הָעַכּוּ\"ם יֵרָאוּ בַּתְּחִלָּה. בֶּגֶד שֶׁהוּא כִּלְאַיִם מִן הַצֶּמֶר וּמִן הַפִּשְׁתִּים מִטַּמֵּא בִּנְגָעִים:","צֶמֶר גְּמַלִּים וְצֶמֶר רְחֵלִים שֶׁטְּוָאָן זֶה עִם זֶה אִם רֹב מִן הַגְּמַלִּים אֵינוֹ מִטַּמֵּא בִּנְגָעִים וְאִם רֹב מִן הָרְחֵלִים מִטַּמֵּא בִּנְגָעִים. מֶחֱצָה לְמֶחֱצָה מִטַּמֵּא בִּנְגָעִים. וְהוּא הַדִּין בְּפִשְׁתָּן וְקַנְבּוֹס שֶׁטְּרָפָן זֶה בָּזֶה. וְרָחֵל בַּת עֵז אֵין הַצֶּמֶר שֶׁלָּהּ מִטַּמֵּא בִּנְגָעִים. בֶּגֶד שֶׁהָיָה שִׁתְיוֹ פִּשְׁתָּן וְעֶרְבוֹ קַנְבּוֹס אוֹ שִׁתְיוֹ קַנְבּוֹס וְעֶרְבוֹ פִּשְׁתָּן אֵינוֹ מִטַּמֵּא בִּנְגָעִים. וְכֵן אִם הָיָה שִׁתְיוֹ אוֹ עֶרְבוֹ פִּשְׁתָּן אוֹ צֶמֶר וְהַשְּׁאָר נוֹצָה שֶׁל עִזִּים וְכַיּוֹצֵא בָּהּ אֵינוֹ מִטַּמֵּא בִּנְגָעִים:","הָעוֹר שֶׁאֵינוֹ מְעֻבָּד אֵינוֹ מִטַּמֵּא בִּנְגָעִים. וְכֵן הָעוֹר שֶׁהוּא גּלֶם קֹדֶם שֶׁעָשָׂה מִמֶּנּוּ כֵּלִים אֵינוֹ מִטַּמֵּא בִּנְגָעִים שֶׁנֶּאֱמַר כְּלִי הָעוֹר. וְכָל (ויקרא יג נב) \"כְּלֵי הָעוֹר\" בֵּין פְּשׁוּטֵיהֶן בֵּין מְקַבְּלֵיהֶן כָּל שֶׁהֵן מִטַּמְּאִין בִּנְגָעִים:","עוֹרוֹת חַיָּה שֶׁבַּיָּם אֵין מִטַּמְּאִין בִּנְגָעִים. חִבֵּר לָהֶן מִן הַגָּדֵל בָּאָרֶץ אֲפִלּוּ חוּט אוֹ מְשִׁיחָה שֶׁל צֶמֶר אוֹ פִּשְׁתִּים אוֹ עוֹר בְּהֵמָה וְחַיָּה הַמְעֻבָּדִין כָּל שֶׁהוּא וְעָשָׂה מֵהֶן כֵּלִים מִטַּמְּאִין בִּנְגָעִים וְהוּא שֶׁיְּחַבְּרֶנּוּ לוֹ כְּדֶרֶךְ חִבּוּרֵי בְּגָדִים לְטֻמְאָה:","כָּל כְּלִי הָרָאוּי לְהִתְטַמֵּא בִּשְׁאָר הַטֻּמְאוֹת אַף עַל פִּי שֶׁאֵינוֹ מִתְטַמֵּא בְּמִדְרַס הַזָּב מִפְּנֵי שֶׁלֹּא נַעֲשָׂה לְמִשְׁכָּב אוֹ לְמוֹשָׁב הֲרֵי זֶה מִטַּמֵּא בִּנְגָעִים כְּגוֹן קֶלַע שֶׁל סְפִינָה וְהַפָּרֹכֶת וְשָׁבִיס שֶׁל שְׂבָכָה וּמִטְפְּחוֹת סְפָרִים וְהָאַבְנֵט וּרְצוּעוֹת מִנְעָל וְסַנְדָּל שֶׁיֵּשׁ בָּהֶן רֹחַב כִּגְרִיס. הֲרֵי אֵלּוּ וְכָל כַּיּוֹצֵא בָּהֶן מִטַּמֵּא בִּנְגָעִים וְאֵין צָרִיךְ לוֹמַר שְׁאָר הַכֵּלִים כְּגוֹן כָּרִים וּכְסָתוֹת. הַחֵמֶת וְהַתּוּרְמָל נִרְאִין כְּדַרְכָּן וּפוֹשֶׂה הַנֶּגַע מִתּוֹכָן לַאֲחוֹרֵיהֶן וּמֵאֲחוֹרֵיהֶן לְתוֹכָן. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן מִכְּלֵי הָעוֹר הַכְּפוּלִין:","סָדִין הַמְקֻמָּט מַפְשִׁיטִין אֶת קְמָטָיו וְרוֹאִין אֶת נִגְעוֹ:","הַשְּׁתִי וְהָעֵרֶב בֵּין שֶׁל צֶמֶר בֵּין שֶׁל פִּשְׁתָּן מִטַּמְּאִין בִּנְגָעִין מִיָּד מִשֶּׁיִּטָּווּ אַף עַל פִּי שֶׁלֹּא לִבֵּן הַפִּשְׁתָּן וְלֹא שָׁלַק הַצֶּמֶר. וְכַמָּה יִהְיֶה בִּפְקַעַת שֶׁל טָווּי וְתִטָּמֵא בִּנְגָעִים, כְּדֵי לֶאֱרֹג מִמֶּנּוּ שָׁלֹשׁ עַל שָׁלֹשׁ שְׁתִי וָעֵרֶב, בֵּין שֶׁהָיְתָה כֻּלָּהּ שְׁתִי בֵּין שֶׁהָיְתָה כֻּלָּהּ עֵרֶב. הָיְתָה הַפְּקַעַת מְקֻבֶּצֶת מֵחוּטִים פְּסוּקִין אֵינָהּ מִטַּמְּאָה בִּנְגָעִים:","שְׁתֵּי פְּקָעִיּוֹת הַמְעֻרוֹת זוֹ לָזוֹ בְּחוּט. וְכֵן הַשְּׁתִי שֶׁמִּקְצָתוֹ לָפוּף עַל הַכֹּבֶד הָעֶלְיוֹנָה וּמִקְצָתוֹ לָפוּף עַל הַכֹּבֶד הַתַּחְתּוֹנָה. וְכֵן שְׁנֵי דַּפֵּי חָלוּק שֶׁמְּעֵרוֹת בְּחוּט אֶחָד וְנִרְאָה הַנֶּגַע בְּאֶחָד מֵהֶן. הַשֵּׁנִי טָהוֹר אַף עַל פִּי שֶׁחוּט אֶחָד מְחַבֵּר בֵּינֵיהֶן. נִרְאָה הַנֶּגַע בְּנֶפֶשׁ הַמַּסֶּכֶת וּבַשְּׁתִי הָעוֹמֵד אַף עַל פִּי שֶׁמִּקְצָת הַנֶּגַע בַּבֶּגֶד וּמִקְצָתוֹ בַּשְּׁתִי הֲרֵי זֶה טָמֵא. נִרְאָה הַנֶּגַע בַּשְּׁתִי הָעוֹמֵד לְבַדּוֹ הָאָרוּג טָהוֹר. נִרְאָה בָּאָרוּג לְבַדּוֹ הַשְּׁתִי הָעוֹמֵד טָהוֹר. נִרְאָה בְּסָדִין שׂוֹרֵף אֶת הַנִּימִין. נִרְאָה בַּנִּימִין הַסָּדִין טָהוֹר. פָּשָׂה מִן הַנִּימִין לַסָּדִין הַסָּדִין טָמֵא:","חָלוּק שֶׁנִּרְאָה בּוֹ נֶגַע מַצִּיל אֶת הָאִמְרִיוֹת שֶׁבּוֹ אֲפִלּוּ הָיְתָה הָאִימֶרֶת צֶמֶר אוֹ פִּשְׁתִּים מַצִּילָהּ וְאֵינָהּ נִשְׂרֶפֶת:","בֶּגֶד מֻסְגָּר שֶׁצְּבָעוֹ אוֹ מְכָרוֹ לְעַכּוּ\"ם טָהוֹר. וְכֵן אִם נִתְעָרֵב בַּאֲחֵרִים כֻּלָּן טְהוֹרִים. קְצָצוֹ וְעָשָׂהוּ מוֹכִין פָּחוֹת מִשָּׁלֹשׁ עַל שָׁלֹשׁ טָהוֹר וּמֻתָּר בַּהֲנָיָתוֹ. הָיְתָה בָּהֶן אַחַת שָׁלֹשׁ עַל שָׁלֹשׁ וְנִרְאָה בָּהּ נֶגַע הִיא לְבַדָּהּ טְמֵאָה:","בֶּגֶד מֻחְלָט שֶׁנִּתְעָרֵב בַּאֲחֵרִים כֻּלָּן טְמֵאִין וְיִשָּׂרְפוּ אֲפִלּוּ אֶחָד בְּכַמָּה אֲלָפִים. וְכֵן אִם קְצָצָן וַעֲשָׂאָהוּ מוֹכִין הֲרֵי הֵן טְמֵאִין וְאָסוּר בַּהֲנָיָתָן:","אֶחָד בֶּגֶד אוֹ כְּלִי עוֹר אוֹ שְׁתִי אוֹ עֵרֶב הַמֻּסְגָּר אוֹ הַמֻּחְלָט לְעִנְיַן טֻמְאָה הֲרֵי הוּא אָב מֵאֲבוֹת הַטֻּמְאוֹת כְּאָדָם מְצֹרָע לְכָל דָּבָר מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְבִיאָה וְעוֹשֶׂה מִשְׁכָּב וּמוֹשָׁב אֲפִלּוּ מִתַּחַת הָאֶבֶן. כֵּיצַד. בֶּגֶד מְנֻגָּע אוֹ שְׁתִי אוֹ עֵרֶב אוֹ כְּלֵי עוֹר הַמְנֻגָּעִין שֶׁהִכְנִיס מֵהֶן אֲפִלּוּ כְּזַיִת לְבַיִת טָהוֹר נִטְמָא כָּל אֲשֶׁר בַּבַּיִת בֵּין אָדָם בֵּין כֵּלִים וְנַעֲשׂוּ כֻּלָּן רִאשׁוֹן לְטֻמְאָה. וְכֵן מִשְׁכָּב וּמוֹשָׁב הַמֻּנָּח תַּחַת הָאֶבֶן וְהִנִּיחַ כְּזַיִת מֵהֶן לְמַעְלָה מִן הָאֶבֶן נִטְמָא הַמִּשְׁכָּב אוֹ הַמּוֹשָׁב:","מַטְלִית שֶׁיֵּשׁ בָּהּ שָׁלֹשׁ עַל שָׁלֹשׁ אַף עַל פִּי שֶׁאֵין בָּהּ כְּזַיִת כֵּיוָן שֶׁנִּכְנַס רֻבָּהּ לְבַיִת טָהוֹר טִמְּאַתּוּ. הָיוּ בָּהּ כַּמָּה זֵיתִים כֵּיוָן שֶׁנִּכְנַס מִמֶּנָּה כְּזַיְת לְבַיִת טָהוֹר נִטְמָא. אַף עַל פִּי שֶׁכָּל הַשִּׁעוּרִין הֲלָכָה לְמשֶׁה מִסִּינַי הֲרֵי הוּא אוֹמֵר (ויקרא יד נד) \"לְכָל נֶגַע הַצָּרַעַת וְלַנָּתֶק\" (ויקרא יד נה) \"וּלְצָרַעַת הַבֶּגֶד וְלַבָּיִת\" הִקִּישׁ נִגְעֵי אָדָם לְנִגְעֵי בְּגָדִים וּבָתִּים וְהִשְׁוָה הַמְצֹרָע לְמֵת שֶׁנֶּאֱמַר (במדבר יב יב) \"אַל נָא תְהִי כַּמֵּת\" מָה הַמֵּת בִּכְזַיִת אַף אֵלּוּ בִּכְזַיִת:","בְּגָדִים הַמְנֻגָּעִים מְשַׁלְּחִין אוֹתָן חוּץ לָעִיר בֵּין שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בֵּין שֶׁאֵינָהּ מֻקֶּפֶת. וְזֶה חֹמֶר בִּבְגָדִים מִבְּאָדָם:"],"Mishneh Torah, Defilement by a Corpse 1":["הַמֵּת מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל טֻמְאַת שִׁבְעָה. וְטֻמְאַת מַגָּע וְאֹהֶל מְפֹרָשִׁין בַּתּוֹרָה שֶׁנֶּאֱמַר (במדבר יט יא) \"הַנֹּגֵעַ בְּמֵת לְכָל נֶפֶשׁ אָדָם וְטָמֵא שִׁבְעַת יָמִים\". וְנֶאֱמַר (במדבר יט יד) \"כָּל הַבָּא אֶל הָאֹהֶל וְכָל אֲשֶׁר בָּאֹהֶל יִטְמָא שִׁבְעַת יָמִים\":","טֻמְאַת מַשָּׂא מִפִּי הַשְּׁמוּעָה. וְקַל וָחֹמֶר הַדְּבָרִים אִם נְבֵלָה שֶׁהִיא טֻמְאַת עֶרֶב וְאֵינָהּ מְטַמְּאָה בְּאֹהֶל מְטַמְּאָה בְּמַשָּׂא שֶׁנֶּאֱמַר (ויקרא יא כח) \"וְהַנּשֵֹׁא אֶת נִבְלָתָם\" הַמֵּת לֹא כָּל שֶׁכֵּן. וּמַה נְּבֵלָה שֶׁמַּגָּעָהּ טֻמְאַת עֶרֶב מַשָּׂאָהּ טֻמְאַת עֶרֶב אַף הַמֵּת שֶׁמַּגָּעוֹ טֻמְאַת שִׁבְעָה מַשָּׂאוֹ טֻמְאַת שִׁבְעָה. אֵין טֻמְאַת מַשָּׂא בְּמֵת מִדִּבְרֵי סוֹפְרִים אֶלָּא דִּין תּוֹרָה. וְיֵרָאֶה לִי שֶׁשָּׁתַק מִמֶּנָּה הַכָּתוּב כְּדֶרֶךְ שֶׁשָּׁתַק מֵאִסּוּר הַבַּת לְפִי שֶׁאָסַר בְּפֵרוּשׁ אֲפִלּוּ בַּת הַבַּת. וְשָׁתַק מֵאִסּוּר אֲכִילַת בָּשָׂר בְּחָלָב לְפִי שֶׁאָסַר בְּפֵרוּשׁ אֲפִלּוּ בִּשּׁוּלוֹ. כָּךְ שָׁתַק מִטֻּמְאַת מַשָּׂא בְּמֵת לְפִי שֶׁטִּמֵּא בְּפֵרוּשׁ אֲפִלּוּ טֻמְאַת אָהֳלוֹ כָּל שֶׁכֵּן מַשָּׂאוֹ:","טֻמְאַת מַגָּע הָאֲמוּרָה בְּכָל מָקוֹם בֵּין בְּמֵת בֵּין בִּשְׁאָר הַמְטַמְּאִים הוּא שֶׁנָּגַע הָאָדָם בִּבְשָׂרוֹ בַּטֻּמְאָה עַצְמָהּ. בֵּין בְּיָדוֹ בֵּין בְּרַגְלוֹ בֵּין בִּשְׁאָר בְּשָׂרוֹ וַאֲפִלּוּ בִּלְשׁוֹנוֹ הֲרֵי זֶה נִטְמָא. וְכֵן נִרְאֶה לִי שֶׁאִם נָגַע בְּצִפָּרְנָיו אוֹ בְּשִׁנָּיו נִטְמָא כֵּיוָן שֶׁהֵם מְחֻבָּרִים לַגּוּף הֲרֵי הֵם כְּגוּף. אֲבָל אִם תָּחַב אָדָם טֻמְאָה בְּכוּשׁ וְהִכְנִיסָהּ לְתוֹךְ גְּרוֹנוֹ שֶׁל אָדָם טָהוֹר וְלֹא נָגְעָה בִּלְשׁוֹנוֹ. אוֹ שֶׁהִכְנִיסָהּ לְתוֹךְ מְעִי שֶׁל אִשָּׁה מִלְּמַטָּה וְלֹא נָגְעָה בִּבְשָׂרָהּ. לֹא נִטְמָא הַבּוֹלֵעַ מִשּׁוּם מַגָּע זֶה שֶׁהֲרֵי לֹא נָגְעָה בִּבְשָׂרוֹ. שֶׁנְּגִיעַת פְּנִים אֵינָהּ נְגִיעָה:","קְרוּם שֶׁעַל הַמַּכָּה הֲרֵי הוּא כְּעוֹר הַבָּשָׂר לְעִנְיַן מַגַּע טֻמְאוֹת. וּכְשׁוּת שֶׁעַל הַקָּטָן אֵינָהּ כְּעוֹר הַבָּשָׂר. כֵּיצַד. מִי שֶׁנָּגְעָה טֻמְאָה בִּקְרוּם מַכָּתוֹ נִטְמָא כְּאִלּוּ נָגְעָה בְּעוֹרוֹ. נָגְעָה בְּשֵׂעָר הַדַּק שֶׁעַל בְּשַׂר הַקָּטָן לֹא נִטְמָא. וְכֵן אָדָם טָמֵא שֶׁהָיְתָה בּוֹ מַכָּה וְנָגַע הַטָּהוֹר בִּקְרוּם מַכַּת הַטָּמֵא נִטְמָא. אִם הָיָה קָטָן טָמֵא וְנָגַע הַטָּהוֹר בַּכְּשׁוּת שֶׁלּוֹ לֹא נִטְמָא בֵּין בְּטֻמְאַת מֵת בֵּין בִּשְׁאָר טֻמְאוֹת. וְכֵן לִכְלוּכֵי צוֹאָה אוֹ טִיט וְכַיּוֹצֵא בָּהֶם מִדְּבָרִים שֶׁאֵין חוֹצְצִין עַל הַגּוּף וְכֵן גִּלְדֵי צוֹאָה מִן הַדְּבָרִים שֶׁחוֹצְצִין עַל הַגּוּף אֵינָם כְּעוֹר הַבָּשָׂר לֹא לְטַמֵּא וְלֹא לְהִתְטַמֵּא:","כְּשֵׁם שֶׁאָדָם מִתְטַמֵּא בִּנְגִיעָתוֹ בְּטֻמְאָה כָּךְ הַכֵּלִים מִתְטַמְּאִים בִּנְגִיעַת הַטֻּמְאָה בָּהֶן. חוּץ מִכְּלִי חֶרֶס שֶׁאֵינוֹ מִתְטַמֵּא אֶלָּא מֵאֲוִירוֹ כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת כֵּלִים. [וְזֶהוּ כְּלָל גָּדוֹל בַּטֻּמְאָה. כָּל הַמְטַמֵּא אָדָם בְּמַגָּע מְטַמֵּא כֵּלִים. וְכָל שֶׁאֵינוֹ מְטַמֵּא אָדָם בְּמַגָּע אֵינוֹ מְטַמֵּא כֵּלִים. וְאֵין אָדָם וְכֵלִים מְקַבְּלִין טֻמְאָה אֶלָּא מֵאַב הַטֻּמְאָה]:","טֻמְאַת מַשָּׂא הָאֲמוּרָה בְּכָל מָקוֹם בֵּין בְּמֵת בֵּין בִּשְׁאָר כָּל הַמְטַמְּאִים בְּמַשָּׂא. הוּא שֶׁיִּשָּׂא הָאָדָם הַטֻּמְאָה אַף עַל פִּי שֶׁלֹּא נָגַע בָּהּ. אֲפִלּוּ הָיָה בֵּינוֹ לְבֵינָהּ אֶבֶן הוֹאִיל וְנָשָׂא נִטְמָא. וְאֶחָד הַנּוֹשֵׂא עַל רֹאשׁוֹ אוֹ עַל יָדוֹ אוֹ עַל שְׁאָר גּוּפוֹ. וְאֶחָד הַנּוֹשֵׂא הוּא בְּעַצְמוֹ אוֹ שֶׁנְּשָׂאָהּ אַחֵר וְהִנִּיחָהּ לְמַעְלָה מִזֶּה הוֹאִיל וְנִשֵּׂאת עָלָיו מִכָּל מָקוֹם נִטְמָא וַאֲפִלּוּ הָיְתָה הַטֻּמְאָה תְּלוּיָה בְּחוּט אוֹ בִּשְׂעָרוֹ וְתָלָה הַחוּט בְּיָדוֹ וְהִגְבִּיהַּ הַטֻּמְאָה כָּל שֶׁהוּא הֲרֵי זֶה נוֹשֵׂא וְנִטְמָא:","מֵסִיט בִּכְלַל נוֹשֵׂא הוּא. וְכָל דָּבָר שֶׁמְּטַמֵּא בְּמַשָּׂא מְטַמֵּא בְּהֶסֵּט. כֵּיצַד. קוֹרָה שֶׁהִיא מֻנַּחַת עַל הַכֹּתֶל וְעַל צִדָּהּ מֵת אוֹ נְבֵלָה וְכַיּוֹצֵא בָּהֶן. וּבָא הַטָּהוֹר לִקְצֵה הַקּוֹרָה הַשֵּׁנִי וְהֵנִידוֹ. כֵּיוָן שֶׁהֵנִיד אֶת הַטֻּמְאָה שֶׁבַּקָּצֶה הַשֵּׁנִי טָמֵא מִשּׁוּם נוֹשֵׂא. וְאֵין צָרִיךְ לוֹמַר אִם מָשַׁךְ אֶת הַקָּצֶה הַשֵּׁנִי כְּנֶגֶד הָאָרֶץ עַד שֶׁהִגְבִּיהַּ הַטֻּמְאָה אוֹ שֶׁגָּרַר הַטֻּמְאָה עַל הָאָרֶץ. שֶׁזֶּה נוֹשֵׂא וַדַּאי. וְזֶה וְכָל כַּיּוֹצֵא בָּהּ הִיא טֻמְאַת הֶסֵּט הָאֲמוּרָה בְּכָל מָקוֹם:","הַנּוֹשֵׂא בְּתוֹךְ בֵּית הַסְּתָרִים נִטְמָא שֶׁאַף עַל פִּי שֶׁאֵין הַנְּגִיעָה שָׁם נְגִיעָה הַנּוֹשֵׂא שָׁם נוֹשֵׂא הוּא. אֶלָּא אִם כֵּן נִבְלַע הַטֻּמְאָה בְּתוֹךְ מֵעָיו שֶׁמֵּאַחַר שֶׁהִגִּיעָה לְתוֹךְ בִּטְנוֹ אֵינוֹ לֹא נוֹגֵעַ וְלֹא נוֹשֵׂא. וְאִם טָבַל טָהוֹר וְאַף עַל פִּי שֶׁהַטֻּמְאָה בְּתוֹךְ מֵעָיו:","אֵין מִתְטַמֵּא בְּמַשָּׂא אֶלָּא הָאָדָם בִּלְבַד לֹא הַכֵּלִים. כֵּיצַד. הֲרֵי שֶׁהָיָה מֻנָּח עַל יָדוֹ עֲשָׂרָה כֵּלִים זֶה עַל גַּבֵּי זֶה וְהַנְּבֵלָה וְכַיּוֹצֵא בָּהּ בַּכְּלִי הָעֶלְיוֹן הָאָדָם טָמֵא מִשּׁוּם נוֹשֵׂא נְבֵלָה וְהַכֵּלִים שֶׁעַל יָדוֹ כֻּלָּן טְהוֹרִים חוּץ מִכְּלִי הָעֶלְיוֹן שֶׁנָּגְעָה בּוֹ הַטֻּמְאָה. וְכֵן כַּיּוֹצֵא בָּזֶה:","טֻמְאַת אֹהֶל אֵינָהּ בִּשְׁאָר טֻמְאוֹת אֶלָּא בְּמֵת בִּלְבַד. וּבֵין שֶׁהֶאֱהִיל הָאָדָם אוֹ הַכְּלִי אֲפִלּוּ מַחַט שֶׁהֶאֱהִילָה עַל הַמֵּת אוֹ שֶׁהֶאֱהִיל הַמֵּת עַל הָאָדָם אוֹ עַל הַכֵּלִים אוֹ שֶׁהָיָה הַמֵּת עִם הָאָדָם אוֹ עִם הַכֵּלִים תַּחַת אֹהֶל אֶחָד הֲרֵי אֵלּוּ טְמֵאִים:","וְטֻמְאַת אֹהֶל הָאֲמוּרָה בְּכָל מָקוֹם הוּא שֶׁתְּטָמֵּא אוֹתָהּ טֻמְאָה הָאָדָם אוֹ הַכֵּלִים בְּאַחַת מִשָּׁלֹשׁ דְּרָכִים אֵלּוּ. אֶחָד הַבָּא כֻּלּוֹ לְאֹהֶל הַמֵּת אוֹ הַבָּא מִקְצָתוֹ הֲרֵי זֶה נִטְמָא בְּאֹהֶל אֲפִלּוּ הִכְנִיס יָדוֹ אוֹ רָאשֵׁי אֶצְבְּעוֹתָיו אוֹ חָטְמוֹ לְאֹהֶל הַמֵּת הֲרֵי זֶה נִטְמָא כֻּלּוֹ. נָגַע בַּמַּשְׁקוֹף וְצֵרֵף יָדוֹ עִם הַמַּשְׁקוֹף נִטְמָא כְּאִלּוּ בָּא מִקְצָתוֹ. נָגַע בָּאַסְקֻפָּה מִטֶּפַח וּלְמַטָּה קָרוֹב לָאָרֶץ טָהוֹר. וּמִטֶּפַח וּלְמַעְלָה טָמֵא. וְיֵרָאֶה לִי שֶׁדָּבָר זֶה מִדִּבְרֵיהֶם:","אֶחָד הַמֵּת מִיִּשְׂרָאֵל אוֹ מִן הָעַכּוּ\"ם מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא:","וְאֵין הָעַכּוּ\"ם מְטַמֵּא בְּאֹהֶל וְדָבָר זֶה קַבָּלָה הוּא וַהֲרֵי הוּא אוֹמֵר בְּמִלְחֶמֶת מִדְיָן (במדבר לא יט) \"כּל נֹגֵעַ בֶּחָלָל\" וְלֹא הַזְכִּיר שָׁם אֹהֶל. וְכֵן הָעַכּוּ\"ם אֵינוֹ נַעֲשֶׂה טְמֵא מֵת אֶלָּא עַכּוּ\"ם שֶׁנָּגַע בְּמֵת אוֹ נְשָׂאוֹ אוֹ הֶאֱהִיל עָלָיו הֲרֵי הוּא כְּמִי שֶׁלֹּא נָגַע. הָא לְמָה זֶה דּוֹמֶה לִבְהֵמָה שֶׁנָּגְעָה בְּמֵת אוֹ הֶאֱהִילָה עַל הַמֵּת. וְלֹא בְּטֻמְאַת הַמֵּת בִּלְבַד אֶלָּא בְּכָל הַטֻּמְאוֹת כֻּלָּן אֵין הָעַכּוּ\"ם וְלֹא הַבְּהֵמָה מִתְטַמְּאִין בָּהֶן:","וּמִדִּבְרֵי סוֹפְרִים שֶׁיְּהוּ הָעַכּוּ\"ם כְּזָבִין לְכָל דִּבְרֵיהֶן. וְאֵין לְךָ בְּכָל מִינֵי נֶפֶשׁ מַה שֶּׁמִּתְטַמֵּא וְהוּא חַי אוֹ מְטַמֵּא וְהוּא חַי חוּץ מִן הָאָדָם בִּלְבַד. וְהוּא שֶׁיִּהְיֶה מִיִּשְׂרָאֵל. אֶחָד גָּדוֹל וְאֶחָד קָטָן מִתְטַמְּאִין בְּכָל הַטֻּמְאוֹת אֲפִלּוּ בְּטֻמְאַת הַמֵּת. שֶׁנֶּאֱמַר בָּהּ (במדבר יט כ) \"אִישׁ אֲשֶׁר יִטְמָא\" אֶחָד הָאִישׁ וְאֶחָד הַקָּטָן שֶׁהֲרֵי הוּא אוֹמֵר שָׁם (במדבר יט יח) \"וְעַל כָּל הַנְּפָשׁוֹת אֲשֶׁר הָיוּ שָׁם\". אֲפִלּוּ קָטָן בֶּן יוֹמוֹ שֶׁנָּגַע אוֹ נָשָׂא אוֹ הֶאֱהִיל עַל הַמֵּת נִטְמָא וַהֲרֵי הוּא טְמֵא מֵת. וְהוּא שֶׁנּוֹלַד לְתִשְׁעָה. אֲבָל בֶּן שְׁמוֹנָה הֲרֵי הוּא כְּאֶבֶן וְאֵינוֹ מְקַבֵּל טֻמְאָה:","הַמֵּת אֵינוֹ מְטַמֵּא עַד שֶׁתֵּצֵא נַפְשׁוֹ אֲפִלּוּ מְגֻיָּד אוֹ גּוֹסֵס. אֲפִלּוּ נִשְׁחֲטוּ בּוֹ שְׁנֵי הַסִּימָנִים אֵינוֹ מְטַמֵּא עַד שֶׁתֵּצֵא נַפְשׁוֹ שֶׁנֶּאֱמַר (במדבר יט יג) \"בְּנֶפֶשׁ הָאָדָם אֲשֶׁר יָמוּת\". נִשְׁבְּרָה מִפְרַקְתּוֹ וְרֹב בְּשָׂרָהּ עִמָּהּ אוֹ שֶׁנִּקְרַע כְּדָג מִגַּבּוֹ אוֹ שֶׁהֻתַּז רֹאשׁוֹ אוֹ שֶׁנֶּחְלַק לִשְׁנֵי חֲלָקִים בְּבִטְנוֹ הֲרֵי זֶה מְטַמֵּא אַף עַל פִּי שֶׁעֲדַיִן הוּא מְרַפְרֵף בְּאֶחָד מֵאֵיבָרָיו:"],"Mishneh Torah, Defilement by a Corpse 20":["שְׁלֹשָׁה דְּבָרִים מַצִּילִין בְּאֹהֶל הַמֵּת. צָמִיד פָּתִיל. וְאֹהָלִין. וּבְלוּעִין. הַבְּלוּעִין מַצִּילִין עַל הַטְּהוֹרִים שֶׁלֹּא יִתְטַמְּאוּ וּמוֹנְעִין הַטֻּמְאָה שֶׁלֹּא תֵּצֵא וּתְטַמֵּא. אֲבָל צָמִיד פָּתִיל וְאֹהָלִין מַצִּילִין עַל הַטְּהוֹרִים שֶׁלֹּא יִתְטַמְּאוּ וְאֵינָן מוֹנְעִין אֶת הַטֻּמְאָה שֶׁלֹּא תֵּצֵא וּתְטַמֵּא אֶת אֲחֵרִים. כֵּיצַד. בַּיִת טָמֵא שֶׁיֵּשׁ בּוֹ כְּלִי מֻקָּף צָמִיד פָּתִיל. כָּל שֶׁבְּתוֹךְ הַכְּלִי טְהוֹרִים. וְכֵן אִם הָיָה שָׁם אֹהֶל בְּתוֹךְ הַבַּיִת כָּל הַכֵּלִים שֶׁבְּתוֹךְ הָאֹהֶל טְהוֹרִין. אֲבָל אִם הָיָה כְּזַיִת מִן הַמֵּת נָתוּן בְּכֵלִים וּמֻקָּף עָלָיו בְּצָמִיד פָּתִיל וְהִכְנִיסוֹ לַבַּיִת הַבַּיִת טָמֵא. וְכֵן אֹהֶל בְּתוֹךְ אֹהֶל וּכְזַיִת מִן הַמֵּת בָּאֹהֶל הַפְּנִימִי כָּל הַכֵּלִים שֶׁבָּאֹהֶל הַחִיצוֹן טְמֵאִים:","אֲבָל הַבְּלוּעִין מַצִּילִין עַל הַטְּהוֹרִים וּמוֹנְעִין אֶת הַטֻּמְאָה. כֵּיצַד. כֶּלֶב שֶׁאָכַל בְּשַׂר הַמֵּת וְנִכְנַס לַבַּיִת הַבַּיִת טָהוֹר. בָּלַע טַבַּעַת אֲפִלּוּ אָדָם שֶׁבָּלַע טַבַּעַת וְנִכְנַס לְאֹהֶל הַמֵּת אַף עַל פִּי שֶׁנִּטְמָא טֻמְאַת שִׁבְעָה הַטַּבַּעַת טְהוֹרָה. וְכֵן כָּל הַבְּלוּעִין בְּחַיָּה וּבְהֵמָה וּבְעוֹפוֹת וּבְדָגִים מַצִּילִין כָּל זְמַן שֶׁהֵן חַיִּין. וְאִם מֵתוּ וּבְשַׂר הַמֵּת בְּתוֹךְ מֵעֵיהֶן אוֹ הַכֵּלִים. הֲרֵי הֵן כְּמוֹ שֶׁאֵינוֹ בָּלוּעַ:","נִשְׁחַט רֹב אֶחָד בָּעוֹף וְרֹב שְׁנַיִם בִּבְהֵמָה אַף עַל פִּי שֶׁעֲדַיִן הֵן מְפַרְכְּסִין הֲרֵי הֵן כְּמֵתִים וְאֵינָן מַצִּילִין עַל הַכֵּלִים הַבְּלוּעִים וְלֹא מוֹנְעִין אֶת הַטֻּמְאָה שֶׁבְּתוֹךְ מֵעֵיהֶן שֶׁלֹּא תְּטָמֵא:","וְכַמָּה תִּשְׁהֶא הַטֻּמְאָה בְּמֵעֵיהֶן וְתִהְיֶה מְטַמְּאָה כְּשֶׁיָּמוּתוּ. בְּכֶלֶב שְׁלֹשָׁה יָמִים מֵעֵת לְעֵת. וּבִשְׁאָר חַיָּה וּבְהֵמָה וְעוֹפוֹת וְדָגִים יוֹם אֶחָד מֵעֵת לְעֵת. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנִּשְׁאַר בְּשַׂר הַמֵּת בְּתוֹךְ מֵעֵיהֶן. אֲבָל זְאֵב שֶׁבָּלַע תִּינוֹק וֶהֱקִיאוֹ דֶּרֶךְ בֵּית הָרְעִי. הַבָּשָׂר טָהוֹר וְהָעֲצָמוֹת בְּטֻמְאָתָן:","אֵין הַבְּלוּעִין נִצָּלִין אֶלָּא בְּבֶטֶן נֶפֶשׁ הַחַיָּה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל הַבְּלוּעִין בְּגוּף הַכֵּלִים וְהָאֲבָנִים אֵינָן נִצָּלִין. כֵּיצַד. כּוּשׁ שֶׁנִּבְלְעָה בּוֹ הַצִּנּוֹר שֶׁל מַתֶּכֶת. וּמַלְמָד שֶׁנִּבְלַע בּוֹ הַדָּרְבָן. וּלְבֵנָה שֶׁהָיְתָה טַבַּעַת מֻבְלַעַת בְּתוֹכָהּ. וְנִכְנְסוּ לְאֹהֶל הַמֵּת. נִטְמְאוּ אַף עַל פִּי שֶׁאֵין נִרְאִין וַהֲרֵי הֵן מְחֻפִּין שֶׁאֵין הַבְּלוּעִין בַּכֵּלִים מַצִּילִין אֶלָּא בְּצָמִיד פָּתִיל. וְכֵן מַחַט אוֹ טַבַּעַת שֶׁהָיוּ מֻבְלָעִין בִּטְפֵלַת הַתַּנּוּר וְנִטְמָא הַתַּנּוּר בְּאֹהֶל הַמֵּת אוֹ שֶׁנָּפַל שֶׁרֶץ לַאֲוִירוֹ נִטְמְאוּ הַכֵּלִים שֶׁבְּתוֹךְ הַטְּפֵלָה. וְאִם הָיָה הַתַּנּוּר מֻקָּף צָמִיד פָּתִיל הוֹאִיל וְהַתַּנּוּר טָהוֹר אַף הַכֵּלִים הַמֻּבְלָעִין בַּטִּיט שֶׁעַל גַּבָּיו טְהוֹרִים. וְכֵן חָבִית הַמֻּקֶּפֶת צָמִיד פָּתִיל וְהָיְתָה מַחַט אוֹ טַבַּעַת בִּמְגוּפַת הֶחָבִית מִצִּדָּהּ. הֲרֵי אֵלּוּ טְמֵאִין וְאֵין מַצִּילִין בְּאֹהֶל הַמֵּת. הָיוּ בִּמְגוּפַת הֶחָבִית כְּנֶגֶד פִּיהָ אִם הָיוּ נִרְאִין לְתוֹךְ הֶחָבִית וְאֵינָן יוֹצְאִין לַאֲוִירָהּ טְהוֹרִין. וְאִם יָצְאוּ לַאֲוִירָהּ טְמֵאִין. שֶׁאֵין כְּלִי חֶרֶשׂ הַמֻּקָּף צָמִיד פָּתִיל מַצִּיל עַל הַכֵּלִים שֶׁבְּתוֹכוֹ כְּמוֹ שֶׁיִּתְבָּאֵר. וְאִם יֵשׁ תַּחְתֵּיהֶן כִּקְלִפַּת הַשּׁוּם אַף עַל פִּי שֶׁהֵן שׁוֹקְעִין לְתוֹךְ אֲוִירָהּ הֲרֵי אֵלּוּ טְהוֹרִין:","כָּל הַבְּלוּעִין בְּקַרְקָעִיתוֹ שֶׁל בַּיִת הֲרֵי הֵן טְמֵאִין וְאֵין נִצָּלִין. שֶׁקַּרְקַע הָאֹהֶל כָּמוֹהוּ עַד הַתְּהוֹם מַה שֶּׁאֵין כֵּן בִּכְתָלָיו כְּמוֹ שֶׁיִּתְבָּאֵר. כֵּיצַד. הַטֻּמְאָה בַּבַּיִת וְכֵלִים הַטְּמוּנִים בְּקַרְקָעִיתוֹ אֲפִלּוּ תַּחַת מֵאָה אַמָּה טְמֵאִים. אִם יֵשׁ בִּמְקוֹמָן טֶפַח עַל טֶפַח טְהוֹרִין שֶׁהֲרֵי הֵן תַּחַת אֹהֶל אֲחֵר. לְמַה זֶּה דּוֹמֶה לַעֲלִיָּה שֶׁעַל גַּבֵּי הַבַּיִת וְטֻמְאָה בַּעֲלִיָּה שֶׁהַבַּיִת טָהוֹר. וְכֵן אִם חָלַק הַבַּיִת בִּמְחִצָּה מִכְּלַפֵּי אַרְצוֹ וְהָיְתָה הַטֻּמְאָה בֵּין הַמְּחִצָּה וְהָאָרֶץ כֵּלִים שֶׁבַּבַּיִת לְמַעְלָה מִן הַמְּחִצָּה טְמֵאִין שֶׁאֵין הָאֹהָלִים מוֹנְעִין הַטֻּמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ. הָיְתָה הַטֻּמְאָה לְמַעְלָה מִן הַמְּחִצָּה כֵּלִים שֶׁבֵּין הַמְּחִצָּה וְהָאָרֶץ טְהוֹרִין שֶׁהָאֹהֶל מַצִּיל. וְאִם אֵין בֵּין הַמְּחִצָּה וְהָאָרֶץ גֹּבַהּ טֶפַח הֲרֵי הֵן כִּטְמוּנִים בְּקַרְקַע הַבַּיִת וּטְמֵאִים:","בִּיב שֶׁהוּא קָמוּר תַּחַת הַבַּיִת וְיֵשׁ בּוֹ פּוֹתֵחַ טֶפַח וְיֵשׁ בְּפִתְחוֹ שֶׁהוּא חוּץ לַבַּיִת פּוֹתֵחַ טֶפַח וְהָיְתָה טֻמְאָה בְּתוֹכוֹ הַבַּיִת טָהוֹר. הָיְתָה טֻמְאָה בַּבַּיִת מַה שֶּׁבְּתוֹכוֹ טָהוֹר. הָיָה בּוֹ פּוֹתֵחַ טֶפַח וְאֵין בִּיצִיאָתוֹ פּוֹתֵחַ טֶפַח וְהָיְתָה טֻמְאָה בְּתוֹכוֹ הַבַּיִת טָמֵא. טֻמְאָה בַּבַּיִת מַה שֶּׁבְּתוֹכוֹ טָהוֹר שֶׁאֵין דַּרְכָּהּ שֶׁל טֻמְאָה לְהִכָּנֵס. אֵין בּוֹ פּוֹתֵחַ טֶפַח וְאֵין בִּיצִיאָתוֹ פּוֹתֵחַ טֶפַח טֻמְאָה בְּתוֹכוֹ הַבַּיִת טָמֵא כְּאִלּוּ הִיא בְּתוֹךְ הַבַּיִת. טֻמְאָה בַּבַּיִת מַה שֶּׁבְּתוֹכוֹ טָמֵא מִפְּנֵי שֶׁהֵן כְּכֵלִים הַטְּמוּנִים בַּקַּרְקַע וְקַרְקַע הַבַּיִת כָּמוֹהוּ עַד הַתְּהוֹם:","שְׁתֵּי חָבִיּוֹת וְכַחֲצִי זַיִת בְּכָל אֶחָד וּמֻקָּפוֹת צָמִיד פָּתִיל וּמֻנָּחוֹת בְּתוֹךְ הַבַּיִת הֵן טְהוֹרוֹת שֶׁאֵין חֲצִי שִׁעוּר מְטַמֵּא. וְהַבַּיִת טָמֵא שֶׁהֲרֵי יֵשׁ בַּבַּיִת כְּזַיִת וְאֵין צָמִיד פָּתִיל לַטֻּמְאָה. וְאֵינָן מִטַּמְּאוֹת מֵחֲמַת הַבַּיִת שֶׁהֲרֵי הֵן מֻקָּפוֹת צָמִיד פָּתִיל. נִפְתְּחָה אַחַת מֵהֶן הִיא וְהַבַּיִת טְמֵאִין וַחֲבֶרְתָּהּ טְהוֹרָה. וְכֵן שְׁנֵי חֲדָרִים שֶׁהֵן פְּתוּחִים זֶה לָזֶה וְלַבַּיִת וְכַחֲצִי זַיִת בַּפְּנִימִי אוֹ בָּאֶמְצָעִי וְכַחֲצִי זַיִת בַּחִיצוֹן הַחִיצוֹן טָמֵא וְהַפְּנִימִי וְהָאֶמְצָעִי טְהוֹרִין. כַּחֲצִי זַיִת בַּפְּנִימִי וְכַחֲצִי זַיִת בָּאֶמְצָעִי הַפְּנִימִי טָהוֹר וְהָאֶמְצָעִי וְהַחִיצוֹן טְמֵאִים שֶׁדֶּרֶךְ הַטֻּמְאָה לָצֵאת וְאֵין דַּרְכָּהּ לְהִכָּנֵס:"],"Mishneh Torah, Defilement by a Corpse 9":["מִי שֶׁהָיָה חוֹפֵר בְּשָׂדֶה וּמָצָא מֵתִים רַבִּים בְּגֻמָּא אַחַת זֶה עַל גַּב זֶה אוֹ זֶה בְּצַד זֶה אוֹ שֶׁמָּצָא הֲרוּגִים אוֹ שֶׁמָּצָא מֵת יוֹשֵׁב אוֹ רֹאשׁוֹ בֵּין בִּרְכָּיו אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא מָקוֹם זֶה בֵּית הַקְּבָרוֹת הָיָה אֶלָּא נוֹטֵל הַמֵּת שֶׁמָּצָא וְנוֹטֵל כָּל הֶעָפָר הַתִּחוֹחַ שֶׁתַּחְתָּיו וְחוֹפֵר בִּבְתוּלַת קַרְקַע שָׁלֹשׁ אֶצְבָּעוֹת וּמוֹצִיא הַכּל וּשְׁאָר הַשָּׂדֶה בְּחֶזְקַת טָהֳרָה כְּשֶׁהָיְתָה קֹדֶם שֶׁיִּמְצָא. וְעָפָר זֶה עִם שָׁלֹשׁ אֶצְבָּעוֹת שֶׁחוֹפֵר הוּא הַנִּקְרָא תְּבוּסַת הַמֵּת:","שָׂדֶה שֶׁנֶּהֶרְגוּ בּוֹ הֲרוּגִים מְלַקֵּט כָּל הָעֲצָמוֹת שֶׁבָּהּ וַהֲרֵי הִיא טְהוֹרָה. וְכֵן הַמְפַנֶּה קִבְרוֹ מִתּוֹךְ שָׂדֵהוּ מְלַקֵּט כָּל הָעֲצָמוֹת עֶצֶם עֶצֶם וַהֲרֵי הִיא טְהוֹרָה. וְכֵן בּוֹר שֶׁמְּטִילִים בְּתוֹכוֹ נְפָלִים אוֹ הֲרוּגִים מְלַקֵּט כָּל הָעֲצָמוֹת שֶׁבּוֹ עֶצֶם עֶצֶם וַהֲרֵי הוּא טָהוֹר:","הָיָה חוֹפֵר וּמָצָא מֵת מֻשְׁכָּב כְּדֶרֶךְ שֶׁקּוֹבְרִין הַמֵּתִים נוֹטְלוֹ וְאֶת תְּבוּסָתוֹ. וְכֵן אִם מָצָא שְׁנַיִם נוֹטֵל כָּל אֶחָד מֵהֶן וּתְבוּסָתוֹ עִמּוֹ וְכָל הַשָּׂדֶה טְהוֹרָה. מָצָא שְׁלֹשָׁה מֵתִים כָּל אֶחָד מֵהֶן מֻטָּל כְּדֶרֶךְ הַנִּקְבָּרִין אִם יֵשׁ בֵּין זֶה לָזֶה מֵאַרְבַּע אַמּוֹת וְעַד שְׁמוֹנֶה כִּמְלוֹא מִטָּה וְקוֹבְרֶיהָ הֲרֵי זֶה חוֹשֵׁשׁ שֶׁמָּא בֵּית הַקְּבָרוֹת הוּא זֶה וְצָרִיךְ לִבְדֹּק מִן הָאַחֲרוֹן עֶשְׂרִים אַמָּה שֶׁהֵן כִּשְׁתֵּי מְעָרוֹת וְחָצֵר שֶׁבֵּינֵיהֶן. וְאִם לֹא מָצָא שָׁם מֵת אַחֵר הֲרֵי אוֹתָן הָעֶשְׂרִים שֶׁבָּדַק טְהוֹרוֹת אַף עַל פִּי שֶׁהֵן שְׁכוּנַת קְבָרוֹת. מָצָא מֵת אֶחָד בְּסוֹף עֶשְׂרִים אַמָּה צָרִיךְ לִבְדֹּק מִמֶּנּוּ עֶשְׂרִים אַמָּה אֲחֵרוֹת לְפִי שֶׁרַגְלַיִם לַדָּבָר. וְאִם הָיָה אֶחָד מֵאֵלּוּ שֶׁמָּצָא בַּתְּחִלָּה אוֹ בַּסּוֹף הָרוּג אוֹ יוֹשֵׁב אוֹ מֻשְׁכָּב שֶׁלֹּא כְּדַרְכּוֹ שֶׁיִּהְיֶה רֹאשׁוֹ בֵּין יַרְכוֹתָיו אֵינוֹ בּוֹדֵק עֶשְׂרִים אַמָּה אֶלָּא נוֹטְלָן וְאֶת תְּבוּסָתָן בִּלְבַד שֶׁחֶזְקָתָן עַכּוּ\"ם:","הָעַכּוּ\"ם אֵין לָהֶם טֻמְאַת קְבָרוֹת הוֹאִיל וְאֵינָן מְטַמְּאִין בְּאֹהֶל הֲרֵי הַנּוֹגֵעַ בְּקִבְרָן טָהוֹר עַד שֶׁיִּגַּע בְּעַצְמָהּ שֶׁל טֻמְאָה אוֹ יִשָּׂאֶנָּה:","מֵת שֶׁחָסֵר אֵיבָר שֶׁאִם יִנָּטֵל מִן הַחַי יָמוּת אֵין לוֹ תְּבוּסָה וְלֹא שְׁכוּנַת קְבָרוֹת. וּמֵתִים הַנִּמְצָאִים גְּלוּיִים עַל פְּנֵי הַשָּׂדֶה אֵין לָהֶם שְׁכוּנַת קְבָרוֹת וְלֹא תְּבוּסָה אֶלָּא מְלַקֵּט עֶצֶם עֶצֶם וְהַכּל טָהוֹר. וְהַנִּקְבָּר שֶׁלֹּא בִּרְשׁוּת יֵשׁ לוֹ תְּבוּסָה וְאֵין לוֹ שְׁכוּנַת קְבָרוֹת:","אֶחָד הַמּוֹצֵא שְׁלֹשָׁה מֵתִים כְּדַרְכָּן בַּתְּחִלָּה אוֹ שֶׁמָּצָא שְׁלֹשָׁה כּוּכִין אוֹ כּוּךְ וּנְקִיעַ וּמְעָרָה הֲרֵי זוֹ שְׁכוּנַת קְבָרוֹת. מָצָא שְׁנַיִם וְאֶחָד הָיָה יָדוּעַ יֵשׁ לָהֶם תְּבוּסָה וְאֵין לָהֶם שְׁכוּנַת קְבָרוֹת שֶׁהַקֶּבֶר הַיָּדוּעַ אֵינוֹ עוֹשֶׂה שְׁכוּנָה. וְלֹא אָמְרוּ אֶלָּא הַמּוֹצֵא שְׁלֹשָׁה בַּתְּחִלָּה הוּא שֶׁצָּרִיךְ בְּדִיקָה. כֵּיצַד בּוֹדֵק הָעֶשְׂרִים אַמָּה שֶׁאָמַרְנוּ. חוֹפֵר עַד שֶׁהוּא מַגִּיעַ לְסֶלַע אוֹ לִבְתוּלָה. וְהִיא הַקַּרְקַע שֶׁנִּרְאֵית שֶׁאֵינָהּ עֲבוּדָה. הֶעְמִיק אֲפִלּוּ מֵאָה אַמָּה וּמָצָא חֶרֶשׂ הֲרֵי זוֹ כְּבַתְּחִלָּה וְצָרִיךְ לְהַעֲמִיק עַד שֶׁיַּגִּיעַ לִבְתוּלָה. הִגִּיעַ לְמַיִם הֲרֵי זוֹ כִּבְתוּלָה:","אֵינוֹ צָרִיךְ לַחְפֹּר תֶּלֶם אֶחָד מִתְּחִלַּת הָעֶשְׂרִים עַד סוֹפָן אֶלָּא חוֹפֵר אַמָּה עַל אַמָּה וּמַנִּיחַ אַמָּה וְחוֹפֵר אַמָּה עַל אַמָּה וּמַנִּיחַ אַמָּה וְכֵן עַד סוֹפָן שֶׁאֵין בֵּין קֶבֶר לְקֶבֶר פָּחוֹת מֵאַמָּה:","הָיָה בּוֹדֵק וְהִגִּיעַ בְּתוֹךְ הָעֶשְׂרִים לְנָהָר אוֹ לִשְׁלוּלִית אוֹ לְדֶרֶךְ הָרַבִּים יַפְסִיק וְאֵינוֹ צָרִיךְ לִבְדֹּק שֶׁהֲרֵי נִפְסְקָה שְׁכוּנַת הַקְּבָרוֹת:","הַמּוֹצֵא עָפָר זֶה שֶׁל בְּדִיקָה טָהוֹר אֶלָּא אִם כֵּן מָצָא טֻמְאָה בַּמָּקוֹם שֶׁחָפַר. אֲבָל קֹדֶם שֶׁיִּמְצָא אוֹכֵל בִּתְרוּמָה. וְהַמְפַקֵּחַ בְּגַל אֵינוֹ אוֹכֵל בִּתְרוּמָה שֶׁהֲרֵי יוֹדֵעַ וַדַּאי שֶׁהַמֵּתִים שָׁם תַּחַת הַגַּל אֶלָּא שֶׁאֵינוֹ מַכִּיר מְקוֹמָן:","גַּל טָמֵא שֶׁנִּתְעָרֵב בִּשְׁנֵי גַּלִּין טְהוֹרִין בָּדַק אֶחָד מֵהֶן וּמְצָאוֹ טָהוֹר הוּא טָהוֹר וְהַשְּׁנַיִם טְמֵאִין. בָּדַק שְׁנַיִם וְנִמְצְאוּ טְהוֹרִים הֵן טְהוֹרִים וְהַשְּׁלִישִׁי בְּחֶזְקַת טָמֵא. בָּדַק שְׁלָשְׁתָּן וּמָצָא טָהוֹר כֻּלָּן בְּחֶזְקַת טֻמְאָה עַד שֶׁיִּבְדֹּק שְׁלָשְׁתָּן עַד שֶׁיַּגִּיעַ לְסֶלַע אוֹ לִבְתוּלָה וְיִהְיוּ שְׁלָשְׁתָּן טְהוֹרִין:","בּוֹר שֶׁמְּטִילִין לְתוֹכוֹ נְפָלִים הַמַּאֲהִיל עָלָיו טָמֵא דִּין תּוֹרָה אַף עַל פִּי שֶׁחֻלְדָּה וּבַרְדְּלָס מְצוּיִין שָׁם אֵין סָפֵק מוֹצִיא מִידֵי וַדַּאי. אֲבָל אִם הִפִּילָה שָׁם אִשָּׁה נֵפֶל וְאֵין יָדוּעַ אִם הִפִּילָה דָּבָר הַמְטַמֵּא אוֹ לֹא הִפִּילָה הוֹאִיל וְחֻלְדָּה וּבַרְדְּלָס מְצוּיִין שָׁם הֲרֵי סְפֵקוֹ טָהוֹר:","דָּבָר יָדוּעַ שֶׁכָּל אֵלּוּ הַטֻּמְאוֹת וְכַיּוֹצֵא בָּהֶן שֶׁהֵן מִשּׁוּם סָפֵק הֲרֵי הֵן שֶׁל דִּבְרֵיהֶן. וְאֵין טָמֵא מִן הַתּוֹרָה אֶלָּא מִי שֶׁנִּטְמָא טֻמְאַת וַדַּאי אֲבָל כָּל הַסְּפֵקוֹת בֵּין בְּטֻמְאוֹת בֵּין בְּמַאֲכָלוֹת אֲסוּרוֹת בֵּין בַּעֲרָיוֹת וְשַׁבָּתוֹת אֵין לָהֶם אֶלָּא מִדִּבְרֵי סוֹפְרִים [וְאַף עַל פִּי כֵן דָּבָר שֶׁחַיָּבִין עַל זְדוֹנוֹ כָּרֵת סְפֵקוֹ אָסוּר מִן הַתּוֹרָה. שֶׁהֲרֵי הָעוֹשֶׂה אוֹתוֹ חַיָּב אָשָׁם תָּלוּי] כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי בִּיאָה וּבְכַמָּה מְקוֹמוֹת:"],"Mishneh Torah, Defilement of Foods 5":["יְדוֹת הָאֳכָלִים הֵן הָעֵצִים הָרַכִּין הַסְּמוּכִין לָאֹכֶל שֶׁהָאֹכֶל נִתְלֶה בָּהֶן מִן הָאִילָן. כְּמוֹ עֵקְצֵי הַתְּאֵנִים וְהָאֲגַסִּים וּקְצָת הָאֶשְׁכּוֹל. וְכֵן הַגַּרְעִינִים וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים שֶׁהָאֹכֶל צָרִיךְ לָהֶן. וְשׁוֹמְרֵי הָאֳכָלִין הֵן הַקְּלִפָּה שֶׁעַל הָאֹכֶל שֶׁהִיא שׁוֹמַרְתּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל שֶׁהוּא יָד וְאֵינוֹ שׁוֹמֵר מִתְטַמֵּא וּמְטַמֵּא וְלֹא מִצְטָרֵף. וְכָל שֶׁהוּא שׁוֹמֵר אַף עַל פִּי שֶׁאֵינוֹ יָד מִתְטַמֵּא וּמְטַמֵּא וּמִצְטָרֵף. וְכָל שֶׁאֵינוֹ לֹא שׁוֹמֵר וְלֹא יָד אֵינוֹ מִתְטַמֵּא וְלֹא מְטַמֵּא וְאֵין צָרִיךְ לוֹמַר שֶׁאֵינוֹ מִצְטָרֵף. כֵּיצַד מִתְטַמֵּא וּמְטַמֵּא וְאֵינוֹ מִצְטָרֵף. שֶׁאִם נָגְעָה טֻמְאָה בַּיָּד נִטְמָא הָאֹכֶל הַתָּלוּי בּוֹ. וְאִם נָגְעָה טֻמְאָה בָּאֹכֶל נִטְמָא הַיָּד. וְאֵין הַיָּד מִצְטָרֶפֶת עִם הָאֹכֶל לְהַשְׁלִימוֹ לִכְבֵיצָה אוֹ לְכַחֲצִי פְּרָס. אֲבָל אִם הָיָה שׁוֹמֵר הֲרֵי זֶה מִצְטָרֵף לִכְבֵיצָה וְלִכַחֲצִי פְּרָס:","כְּשֵׁם שֶׁיָּד לְטֻמְאָה כָּךְ יֵשׁ יָד לְהֶכְשֵׁר. שֶׁאִם הֻכְשַׁר הַיָּד הֻכְשַׁר כָּל הָאֹכֶל הַתָּלוּי בּוֹ. וְיֵשׁ יָד לְפָחוֹת מִכְּזַיִת. וְיֵשׁ שׁוֹמֵר לְפָחוֹת מִכְּפוֹל. וְשׁוֹמֵר שֶׁחִלְּקוֹ אֵינוֹ מִצְטָרֵף עִם הָאֹכֶל:","וּמִנַּיִן לְשׁוֹמְרֵי אֳכָלִין שֶׁהֵן מִתְטַמְּאִין עִם הָאֹכֶל כְּשֶׁהֵן מְחֻבָּרִין בָּהֶן שֶׁנֶּאֱמַר (ויקרא יא לז) \"עַל כָּל זֶרַע זֵרוּעַ אֲשֶׁר יִזָּרֵעַ\" כְּדֶרֶךְ שֶׁבְּנֵי אָדָם מוֹצִיאִין לִזְרִיעָה. חִטִּים בְּשַׂעֲרֵיהֶן וּשְׂעוֹרִים בִּקְלִפֵּיהֶן וַעֲדָשִׁים בִּקְלִפֵּיהֶן. וְהוּא הַדִּין לִשְׁאָר הַשּׁוֹמְרִין:","וּמִנַּיִן לִידוֹת הָאֳכָלִין שֶׁהֵן מִתְטַמְּאוֹת וּמְטַמְּאוֹת כְּשֶׁהֵן מְחֻבָּרִין עִם הָאֳכָלִין שֶׁנֶּאֱמַר (ויקרא יא לח) \"טָמֵא הוּא לָכֶם\" לְכָל שֶׁבְּצָרְכֵיכֶם:","הַבּוֹצֵר לַגַּת אֵין לוֹ יָדוֹת שֶׁהֲרֵי אֵין לוֹ צֹרֶךְ בְּיָד מִפְּנֵי שֶׁמּוֹצֵץ אֶת הַמַּשְׁקֶה:","הַקּוֹצֵר לְסִכּוּךְ אֵין לוֹ יָדוֹת שֶׁהֲרֵי אֵינוֹ צָרִיךְ לַיָּד:","כָּל יְדוֹת הָאֳכָלִין שֶׁבִּסְּסָן בְּגֹרֶן טְהוֹרִין:","פְּסִיגָה שֶׁל אֶשְׁכּוֹל שֶׁרִקְּנָהּ טְהוֹרָה. וְאִם נִשְׁתַּיֵּר בָּהּ גַּרְגֵּר אֶחָד הֲרֵי זֶה יָד לְאוֹתוֹ גַּרְגֵּר וּמְקַבֶּלֶת טֻמְאָה. וְכֵן שַׁרְבִיט תְּמָרָה שֶׁרִקְּנוֹ טָהוֹר. שִׁיֵּר בּוֹ תְּמָרָה אַחַת טָמֵא. וְכֵן שַׁרְבִיט קִטְנִיּוֹת שֶׁרִקְּנוֹ טָהוֹר. שִׁיֵּר בּוֹ גַּרְגֵּר אֶחָד מְקַבֵּל טֻמְאָה:","לְעוֹלָם אֵין שׁוֹמֵר עַל גַּבֵּי שׁוֹמֵר אֶלָּא שׁוֹמֵר אֶחָד בִּלְבַד הַסָּמוּךְ לָאֹכֶל הוּא הַנֶּחְשָׁב עִמּוֹ:","שָׁלֹשׁ קְלִפּוֹת בַּבָּצָל. פְּנִימִית בֵּין שְׁלֵמָה בֵּין קְדוּרָה מִצְטָרֶפֶת. אֶמְצָעִית שְׁלֵמָה מִצְטָרֶפֶת קְדוּרָה אֵינָהּ מִצְטָרֶפֶת. הַחִיצוֹנָה בֵּין כָּךְ וּבֵין כָּךְ טְהוֹרָה:","כָּל הַקְּלִפִּין מִתְטַמְּאוֹת וּמְטַמְּאוֹת וּמִצְטָרְפוֹת מִפְּנֵי שֶׁהֵן שׁוֹמֵר. קְלִפֵּי פּוֹלִין וְתוּרְמוּסִין זְרָקָן אֵינָן מִתְטַמְּאוֹת כְּנָסָן לָאֳכָלִין מִתְטַמְּאִין. וְאִם נִשְׁאַר בָּהֶן אֹכֶל בֵּין כָּךְ וּבֵין כָּךְ מִתְטַמְּאִין. קְלִפַּת מְלָפְפוֹן אַף עַל פִּי שֶׁאֵין בָּהֶן מִתּוֹךְ הַמְּלָפְפוֹן מִתְטַמְּאוֹת טֻמְאַת אֳכָלִין. הַשְּׂעוֹרִים בִּזְמַן שֶׁהֵן יְבֵשִׁין קְלִפָּתָן מִצְטָרֶפֶת עִמָּהֶן וּבִזְמַן שֶׁהֵן לַחִין אֵין מִצְטָרְפִין. אֲבָל הַחִטָּה בֵּין לֶחָה בֵּין יְבֵשָׁה קְלִפָּתָהּ מִצְטָרֶפֶת:","כָּל הַגַּרְעִינִין מִתְטַמְּאוֹת וּמְטַמְּאוֹת וְלֹא מִצְטָרְפוֹת חוּץ מִגַּרְעִינוֹת הָרֹטֶב. אֲבָל שֶׁל תְּמָרָה יָבֵשָׁה אֵינָהּ מִצְטָרֶפֶת:","הַחֹתֶל שֶׁעַל הַגַּרְעִינָה שֶׁל רֹטֶב אֵינָהּ מִצְטָרֶפֶת וְשֶׁעַל גַּרְעִינַת הַיְּבֵשָׁה מִצְטָרֶפֶת מִפְּנֵי שֶׁהוּא דָּבוּק בָּאֹכֶל נֶחְשָׁב כְּאֹכֶל:","גַּרְעִינָה שֶׁל רֹטֶב שֶׁיָּצָאת מִקְּצָתָהּ כָּל שֶׁכְּנֶגֶד הָאֹכֶל מִצְטָרֵף וְהַיּוֹצֵא אֵינוֹ מִצְטָרֵף. וְכֵן עֶצֶם שֶׁיֵּשׁ עָלָיו בָּשָׂר כָּל שֶׁכְּנֶגֶד הַבָּשָׂר מִצְטָרֵף. הָיָה עָלָיו הַבָּשָׂר מִצַּד אֶחָד אֵינוֹ מִצְטָרֵף מִמֶּנּוּ אֶלָּא הָעֶצֶם שֶׁתַּחַת הַבָּשָׂר עַד חֲלַל הָעֶצֶם. וְאִם לֹא הָיָה לָעֶצֶם חָלָל רוֹאִין אוֹתוֹ כְּאִלּוּ הוּא כָּעֳבִי הָאֵזוֹב וּשְׁאָר הָעֶצֶם אֵין מִצְטָרֵף שֶׁהָעֲצָמוֹת לַבָּשָׂר כְּשׁוֹמֵר הֵן חֲשׁוּבִין:","קוּלִית שֶׁהָיָה עָלֶיהָ בָּשָׂר אֲפִלּוּ כְּפוֹל גּוֹרֵר אֶת כֻּלָּהּ לְטֻמְאָה:","גַּרְעִינֵי זֵיתִים וּתְמָרָה אַף עַל פִּי שֶׁשְּׁלָקָן לָאֳכָלִין אֵין מִתְטַמְּאִין:","גַּרְעִינֵי חָרוּבִין אַף עַל פִּי שֶׁכְּנָסָן לָאֳכָלִין אֵין מִתְטַמְּאִין. שְׁלָקָן לָאֳכָלִין מִתְטַמְּאִין:","וְאֵלּוּ מִתְטַמְּאִין וּמְטַמְּאִין וּמִצְטָרְפִין. שָׁרְשֵׁי הַשּׁוּם וְהַבְּצָלִים וְהַקַּפְלוֹטוֹת בִּזְמַן שֶׁהֵן לַחִין. וְהַפִּטְמָה שֶׁלָּהֶן בֵּין לֶחָה בֵּין יְבֵשָׁה. וְהָעַמּוּד שֶׁהוּא מְכֻוָּן כְּנֶגֶד הָאֹכֶל. וְשָׁרְשֵׁי הַחֲזָרִין וְהַנָּפוּס. וְשֹׁרֶשׁ צְנוֹן גָּדוֹל מִצְטָרֵף. וְהַסִּיב שֶׁלּוֹ אֵינוֹ מִצְטָרֵף. וְשָׁרְשֵׁי הַמִּנְתָּא וְהַפֵּיגָם. וְשָׁרְשֵׁי יַרְקוֹת שָׂדֶה וְיַרְקוֹת גִּנָּה שֶׁעֲקָרָן לִשְׁתָלִים. וְהַשִּׁ[זְ]רָה שֶׁל שִׁבּלֶת וְהַלְּבוּשׁ שֶׁלָּהּ. וְעֻקְצֵי תְּאֵנִים וּגְרוֹגָרוֹת. וְהַכְּלֻסִּים וְהֶחָרוּבִין:","וְאֵלּוּ מִתְטַמְּאִים וּמְטַמְּאִין וְלֹא מִצְטָרְפִין. שָׁרְשֵׁי הַשּׁוּם וְהַבְּצָלִים וְהַקַּפְלוֹטוֹת בִּזְמַן שֶׁהֵן יְבֵשִׁין. וְהָעַמּוּד שֶׁאֵינוֹ מְכֻוָּן כְּנֶגֶד הָאֹכֶל. וּמַלָעִין שֶׁל שִׁבֳּלִים וְהֵן הַשְּׂעָרוֹת הַשְּׁחוֹרוֹת שֶׁבְּרֹאשׁ הַשִּׁבּלֶת שֶׁדּוֹמִין כְּמוֹ מַסָּר. וְעֵקְצֵי הָאֲגַסִּים וְהַקְּרוּסְטְמָלִין וְהַפְּרִישִׁין וְהָעוּזְרָדִין. וְעֹקֶץ דְּלַעַת טֶפַח הַסָּמוּךְ לָאֹכֶל. וְעֹקֶץ קֻנְדָּס טֶפַח. וְכֵן יַד הַפַּרְכִּיל טֶפַח מִכָּאן וְטֶפַח מִכָּאן. וְהַפַּרְכִּיל הוּא הַשָּׂרִיג שֶׁהָאֶשְׁכְּלוֹת תְּלוּיִין בּוֹ. וְיַד הָאֶשְׁכּוֹל כָּל שֶׁהוּא. וּזְנַב הָאֶשְׁכּוֹל שֶׁרִקְּנוֹ. וְיַד הַמִּכְבָּד שֶׁל תְּמָרָה אַרְבָּעָה טְפָחִים. וְהַמִּכְבָּד הוּא הָעֵץ הָאָדֹם שֶׁהַשַּׁרְבִיטִין תְּלוּיִין בּוֹ וְהַתְּמָרִין דְּבוּקוֹת בַּשַּׁרְבִיטִין. וּקְנֵה הַשִּׁבּלֶת שְׁלֹשָׁה טְפָחִים. וְיַד כָּל הַנִּקְצָרִין שְׁלֹשָׁה טְפָחִים. וְשֶׁאֵין דַּרְכּוֹ לְהִקָּצֵר יְדֵיהֶם וְשָׁרְשֵׁיהֶן כָּל שֶׁהֵן. כָּל אֵלּוּ מִתְטַמְּאִין וּמְטַמְּאִין וְלֹא מִצְטָרְפִין מִפְּנֵי שֶׁהֵן יְדוֹת אֳכָלִין:","וְאֵלּוּ לֹא מִתְטַמְּאִין וְלֹא מְטַמְּאִין וְלֹא מִצְטָרְפִין. שְׁאָר כָּל הָעֳקָצִים. וְשָׁרְשֵׁי קִלְחֵי הַכְּרוּב. וְחַלְפֵי תְּרָדִים וְחַלְפֵי הַלֶּפֶת וְהֵן הָעִקָּרִין שֶׁנִּשְׁאֲרוּ בַּקַּרְקַע כְּשֶׁלָּקְטוּ הַכְּרוּב וְהַלֶּפֶת וְחָזְרוּ וְהֶחְלִיפוּ. וְכָל הַשָּׁרָשִׁין שֶׁדַּרְכָּן לְהִגָּזֵז שֶׁנֶּעֶקְרוּ עִם הָאֹכֶל. הַפִּטְמָה שֶׁל רִמּוֹן מִצְטָרֶפֶת וְהַנֵּץ שֶׁלּוֹ אֵינוֹ מִצְטָרֵף:","הָרִמּוֹן וְהָאֲבַטִּיחַ שֶׁנִּמּוֹק מִקְצָתוֹ אֵין הַנִּשְׁאָר חִבּוּר לְאוֹתוֹ שֶׁנִּמּוֹק. וְאֵין הַנִּשְׁאָר מִן הַקְּלִפָּה מִצְטָרֵף שֶׁהֲרֵי אֵין שְׁמִירָתוֹ מוֹעֶלֶת כְּלוּם. וְכֵן אִם הָיָה שָׁלֵם מִכָּאן וּמִכָּאן וְנִמּוֹק בָּאֶמְצַע אֵין הַצְּדָדִין חִבּוּר זֶה לָזֶה וְאֵין קְלִפָּתוֹ מִצְטָרֶפֶת. עֲלֵי יְרָקוֹת יְרֻקִּין מִצְטָרְפִין וּלְבָנִים אֵינָם מִצְטָרְפִין שֶׁהֲרֵי אֵינָן כְּלוּם:"],"Mishneh Torah, Diverse Species 7":["הַבָּא לִזְרֹעַ בְּצַד הַכֶּרֶם מַרְחִיק מִמֶּנּוּ אַרְבַּע אַמּוֹת מֵעִקְּרֵי הַגְּפָנִים וְזוֹרֵעַ. וְאִם גֶּפֶן יְחִידִית הִיא מַרְחִיק מִמֶּנָּה שִׁשָּׁה טְפָחִים וְזוֹרֵעַ. הָיְתָה שׁוּרָה אַחַת שֶׁל גְּפָנִים זוֹ בְּצַד זוֹ אֲפִלּוּ הֵן מֵאָה אֵין זֶה כֶּרֶם אֶלָּא כְּגֶפֶן יְחִידִית וּמַרְחִיק מִן הַשּׁוּרָה שִׁשָּׁה טְפָחִים וְזוֹרֵעַ. הָיוּ שְׁתֵּי שׁוּרוֹת הֲרֵי אֵלּוּ כֶּרֶם וְצָרִיךְ לְהַרְחִיק אַרְבַּע אַמּוֹת מִכָּל צַד וְאַחַר כָּךְ יִזְרַע:","וְכַמָּה יִהְיֶה בְּכָל שׁוּרָה שָׁלֹשׁ גְּפָנִים אוֹ יוֹתֵר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה בֵּין כָּל גֶּפֶן וְגֶפֶן מֵאַרְבַּע אַמּוֹת עַד שְׁמוֹנֶה אַמּוֹת. אֲבָל אִם הָיָה בֵּין שְׁתֵּי הַשּׁוּרוֹת שְׁמוֹנֶה אַמּוֹת חוּץ מִמְּקוֹם הַגְּפָנִים עַצְמָן הֲרֵי אֵלּוּ כְּמֻבְדָּלוֹת זוֹ מִזּוֹ וְאֵינָן כֶּרֶם אֶחָד וְאֵינוֹ מַרְחִיק אֶלָּא שִׁשָּׁה טְפָחִים מִכָּל שׁוּרָה. וְכֵן אִם הָיָה בֵּינֵיהֶן פָּחוֹת מֵאַרְבַּע הֲרֵי אֵלּוּ כְּגֶפֶן אַחַת וּמַרְחִיק שִׁשָּׁה טְפָחִים לְכָל רוּחַ:","הָיוּ שָׁלֹשׁ שׁוּרוֹת אַף עַל פִּי שֶׁיֵּשׁ בֵּינֵיהֶן פָּחוֹת מֵאַרְבַּע הֲרֵי אֵלּוּ כֶּרֶם וְרוֹאִין אֶת הָאֶמְצָעִיּוֹת כְּאִלּוּ אֵינָם. וְכֵן אִם הָיוּ שָׁלֹשׁ שׁוּרוֹת וּבֵין כָּל שׁוּרָה וְשׁוּרָה שְׁמוֹנֶה אַמּוֹת אוֹ יוֹתֵר הֲרֵי זֶה זוֹרֵעַ בֵּין הַשּׁוּרוֹת:","לְפִיכָךְ הַנּוֹטֵעַ אֶת כַּרְמוֹ מִתְּחִלָּה וְהִרְחִיק בֵּין כָּל שׁוּרָה וְשׁוּרָה שְׁמוֹנֶה אַמּוֹת מֻתָּר לְהָבִיא זֶרַע בְּתוֹכוֹ. וּמַרְחִיק מִכָּל שׁוּרָה שִׁשָּׁה טְפָחִים בִּלְבַד. אֲבָל אִם זָרַע חוּצָה לוֹ צָרִיךְ לְהַרְחִיק מִשּׁוּרָה הַחִיצוֹנָה אַרְבַּע אַמּוֹת כִּשְׁאָר הַכְּרָמִים וְאֵין דִּין בֵּין הַשּׁוּרוֹת שֶׁל זֶה הַכֶּרֶם כְּכֶרֶם שֶׁחָרַב בְּאֶמְצָעוֹ שֶׁהֲרֵי מִתְּחִלָּה נְטָעָן מְרֻחָקִין:","הָיְתָה בְּשָׂדֶה זוֹ שׁוּרָה אַחַת שֶׁל גְּפָנִים וּבִשְׂדֵה חֲבֵרוֹ שׁוּרָה אַחֶרֶת כְּנֶגְדָּהּ קְרוֹבָה לָהּ. אַף עַל פִּי שֶׁמַּפְסִיק בֵּינֵיהֶן דֶּרֶךְ הַיָּחִיד אוֹ דֶּרֶךְ הָרַבִּים אוֹ גָּדֵר שֶׁהוּא נָמוּךְ מֵעֲשָׂרָה טְפָחִים הֲרֵי אֵלּוּ מִצְטָרְפוֹת לִהְיוֹת שְׁתֵּיהֶן כֶּרֶם וְהוּא שֶׁיִּהְיֶה בֵּינֵיהֶן פָּחוֹת מִשְּׁמוֹנֶה:","נָטַע שׁוּרָה אַחַת בָּאָרֶץ וְשׁוּרָה אַחַת בְּמַדְרֵגָה. אִם גְּבוֹהָה הַמַּדְרֵגָה מִן הָאָרֶץ עֲשָׂרָה טְפָחִים אֵינָם מִצְטָרְפִין. פָּחוֹת מִיכַּן מִצְטָרְפִין:","הַנּוֹטֵעַ חָמֵשׁ גְּפָנִים שְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת יוֹצֵאת זָנָב הֲרֵי זֶה נִקְרָא כֶּרֶם קָטָן וְצָרִיךְ לְהַרְחִיק מֵהֶן אַרְבַּע אַמּוֹת לְכָל רוּחַ. אֲבָל אִם נְטָעָן שְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת בָּאֶמְצַע אוֹ שָׁלֹשׁ בְּשׁוּרָה זוֹ וּשְׁתַּיִם כְּנֶגְדָּן בְּשׁוּרָה שְׁנִיָּה אֵינָם כֶּרֶם וְאֵינוֹ מַרְחִיק מֵהֶן אֶלָּא שִׁשָּׁה טְפָחִים לְכָל רוּחַ:","כֶּרֶם שֶׁחָרַב אִם יֵשׁ בּוֹ לְלַקֵּט עֶשֶׂר גְּפָנִים לְכָל בֵּית סְאָה וְיִהְיוּ נְטוּעוֹת שְׁתַּיִם כְּנֶגֶד שְׁתַּיִם וְאַחַת יוֹצְאָה זָנָב. אוֹ יֵשׁ בּוֹ לְכַוֵּן שָׁלֹשׁ כְּנֶגֶד שָׁלֹשׁ הֲרֵי זֶה נִקְרָא כֶּרֶם דַּל וְאָסוּר לִזְרֹעַ בְּכֻלּוֹ:","כֶּרֶם שֶׁאֵינוֹ נָטוּעַ שׁוּרוֹת שׁוּרוֹת אֶלָּא מְעֵרְבָּב. אִם יֵשׁ בּוֹ לְכַוֵּן שְׁתַּיִם כְּנֶגֶד שָׁלֹשׁ הֲרֵי זֶה כֶּרֶם וְאִם לָאו אֵינוֹ כֶּרֶם. אֶלָּא דַּיּוֹ לְהַרְחִיק שִׁשָּׁה טְפָחִים מִכָּל גֶּפֶן וְגֶפֶן וְזוֹרֵעַ:","הָיוּ הָעִקָּרִים מְכֻוָּנִין וְהַנּוֹף אֵינוֹ מְכֻוָּן הֲרֵי זֶה כֶּרֶם. הַנּוֹף מְכֻוָּן וְהָעִקָּר אֵינוֹ מְכֻוָּן אֵינוֹ כֶּרֶם. הָיוּ דַּקּוֹת וְאֵינָן מְכֻוָּנוֹת הֶעֱבוּ וַהֲרֵי הֵן מְכֻוָּנוֹת הֲרֵי זֶה כֶּרֶם. כֵּיצַד הוּא יוֹדֵעַ אִם הֵן מְכֻוָּנוֹת. מֵבִיא חוּט הַמִּדָּה וּמוֹתֵחַ מִזּוֹ לְזוֹ:","כֶּרֶם שֶׁחָרַב בְּאֶמְצָעוֹ וְנִשְׁאָר שָׁלֵם מִכָּל סְבִיבָיו. אִם יֵשׁ בַּקָּרַחַת שֶׁבְּאֶמְצָעוֹ שֵׁשׁ עֶשְׂרֵה אַמָּה הֲרֵי זֶה מַרְחִיק מֵעִקְּרֵי הַגְּפָנִים אַרְבַּע אַמּוֹת לְכָל רוּחַ וְזוֹרֵעַ בְּאֶמְצַע הַקָּרַחַת. וְאִם אֵין בָּהּ שֵׁשׁ עֶשְׂרֵה אַמָּה הֲרֵי זֶה לֹא יָבִיא זֶרַע לְשָׁם. וְאִם הֵבִיא הוֹאִיל וְהִרְחִיק אַרְבַּע אַמּוֹת לְכָל רוּחַ מִן הַגְּפָנִים שֶׁל כֶּרֶם הֲרֵי זֶה לֹא קִדֵּשׁ:","וְכֵן מָקוֹם שֶׁנִּשְׁאַר פָּנוּי בְּלֹא גְּפָנִים בֵּין סוֹף הַכֶּרֶם וּבֵין הַגָּדֵר שֶׁלּוֹ וְהוּא הַנִּקְרָא מְחוֹל הַכֶּרֶם אִם יֵשׁ בּוֹ שְׁתֵּים עֶשְׂרֵה אַמָּה מַרְחִיק מִן הַגְּפָנִים אַרְבַּע אַמּוֹת וְזוֹרֵעַ אֶת הִשָּׁאֵר:","הָיָה בּוֹ פָּחוֹת מִשְּׁתֵּים עֶשְׂרֵה אַמָּה לֹא יָבִיא זֶרַע לְשָׁם. וְאִם הֵבִיא הוֹאִיל וְהִרְחִיק אַרְבַּע אַמּוֹת הֲרֵי זֶה לֹא קִדֵּשׁ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכֶרֶם גָּדוֹל. אֲבָל בְּקָטָן אֵין לוֹ מָחוֹל אֶלָּא מַרְחִיק אַרְבַּע אַמּוֹת מִסּוֹף הַגְּפָנִים וְזוֹרֵעַ עַד הַגָּדֵר. וְכֵן כֶּרֶם גָּדוֹל שֶׁהָיָה בֵּין כָּל שׁוּרָה וְשׁוּרָה שְׁמוֹנֶה אַמּוֹת אוֹ יֶתֶר אֵין לוֹ מָחוֹל:","הָיָה הַגָּדֵר הַמַּקִּיף אֶת הַכֶּרֶם פָּחוֹת מֵעֲשָׂרָה טְפָחִים. אוֹ שֶׁהָיָה גָּבְהוֹ עֲשָׂרָה טְפָחִים וְאֵין בּוֹ רֹחַב אַרְבָּעָה טְפָחִים. אֵין לוֹ מָחוֹל. אֶלָּא מַרְחִיק מִסּוֹף הַגְּפָנִים אַרְבַּע אַמּוֹת וְזוֹרֵעַ עַד הַמְּחִצָּה. אֲפִלּוּ הָיָה בֵּין הַגְּפָנִים וּבֵין הַמְּחִצָּה אַרְבַּע אַמּוֹת וּמֶחֱצָה זוֹרֵעַ אֶת חֲצִי הָאַמָּה:","גָּדֵר שֶׁהוּא גָּבוֹהַּ עֲשָׂרָה טְפָחִים וְכֵן חָרִיץ שֶׁהוּא עָמֹק עֲשָׂרָה טְפָחִים וְרָחָב אַרְבַּע הֲרֵי זֶה מֻתָּר לִטַּע כֶּרֶם בְּצִדּוֹ מִכָּאן וִירָקוֹת בְּצִדּוֹ מִכָּאן. אֲפִלּוּ מְחִצָּה שֶׁל קָנִים אִם אֵין בֵּין קָנֶה לַחֲבֵרוֹ שְׁלֹשָׁה טְפָחִים הֲרֵי זוֹ מֻבְדֶּלֶת בֵּין הַכֶּרֶם וְהַיָּרָק בְּגָדֵר:","גָּדֵר הַמַּבְדִּיל בֵּין כֶּרֶם וְיָרָק שֶׁנִּפְרַץ עַד עֶשֶׂר אַמּוֹת הֲרֵי זֶה כְּפֶתַח וּמֻתָּר. הָיְתָה פְּרוּצָה יוֹתֵר מֵעֶשֶׂר כְּנֶגֶד הַפִּרְצָה אָסוּר עַד שֶׁיַּרְחִיק מִן הַגְּפָנִים כַּשִּׁעוּר. נִפְרְצוּ בּוֹ פְּרָצוֹת רַבּוֹת אִם הָיָה הָעוֹמֵד כְּפָרוּץ הֲרֵי זֶה מֻתָּר כְּאִלּוּ אֵין שָׁם פִּרְצָה. הָיָה פָּרוּץ מְרֻבֶּה עַל הָעוֹמֵד לֹא יִזְרַע כְּנֶגֶד כָּל הַמְּקוֹמוֹת הַפְּרוּצִים עַד שֶׁיַּרְחִיק כַּשִּׁעוּר:","מְחִצַּת הַכֶּרֶם שֶׁנִּפְרְצָה אוֹמְרִים לוֹ גְדֹר. גְּדָרָהּ וְנִפְרְצָה אוֹמְרִים לוֹ גְדֹר. נִתְיָאֵשׁ מִמֶּנָּה וְלֹא גְּדָרָהּ הֲרֵי זֶה קִדֵּשׁ:","בַּיִת שֶׁחֶצְיוֹ מְקֹרֶה וְחֶצְיוֹ אֵינוֹ מְקֹרֶה וּגְפָנִים נְטוּעוֹת בְּצַד זֶה מֻתָּר לִזְרֹעַ יְרָקוֹת בַּצַּד הָאַחֵר. שֶׁהֲרֵי פִּי תִּקְרָה כְּאִלּוּ יָרַד וְסָתַם וְנַעֲשָׂה בֵּינֵיהֶן כִּמְחִצָּה. וְאִם הִשְׁוָה אֶת קֵרוּיוֹ אָסוּר:","חָצֵר קְטַנָּה שֶׁנִּפְרְצָה בִּמְלוֹאָהּ לִגְדוֹלָה וְהָיוּ הַגְּפָנִים בַּגְּדוֹלָה אָסוּר לִזְרֹעַ בַּקְּטַנָּה. וְאִם זָרַע הַזְּרָעִים אֲסוּרִין וְהַגְּפָנִים מֻתָּרִין. הָיוּ הַגְּפָנִים בַּקְּטַנָּה מֻתָּר לִזְרֹעַ בַּגְּדוֹלָה הוֹאִיל וְיֵשׁ בַּגְּדוֹלָה פַּסִּין מִכָּאן וּמִכָּאן הֲרֵי הִיא כְּמֻבְדֶּלֶת מִן הַקְּטַנָּה וְאֵין הַקְּטַנָּה מֻבְדֶּלֶת מִן הַגְּדוֹלָה:","חָרִיץ שֶׁהוּא עוֹבֵר בַּכֶּרֶם עָמֹק עֲשָׂרָה וְרָחָב אַרְבָּעָה אִם הָיָה מְפֻלָּשׁ מֵרֹאשׁ הַכֶּרֶם וְעַד סוֹפוֹ הֲרֵי זֶה נִרְאֶה כְּבֵין שְׁנֵי הַכְּרָמִים וּמֻתָּר לִזְרֹעַ בְּתוֹכוֹ. וּבִלְבַד שֶׁלֹּא יִהְיוּ הַגְּפָנִים מְסַכְּכִין עָלָיו כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם לֹא הָיָה מְפֻלָּשׁ הֲרֵי הוּא כְּגַת שֶׁבְּאֶמְצַע הַכֶּרֶם שֶׁאַף עַל פִּי שֶׁהִיא עֲמֻקָּה עֲשָׂרָה וּרְחָבָה אַרְבָּעָה אוֹ יֶתֶר אָסוּר לוֹ לִזְרֹעַ בְּתוֹכָהּ אֶלָּא אִם כֵּן הָיָה בַּקָּרַחַת שֵׁשׁ עֶשְׂרֵה אַמָּה:","שְׁבִיל שֶׁבֵּין שְׁנֵי הַכְּרָמִים הֲרֵי הוּא כְּכֶרֶם שֶׁחָרַב מֵאֶמְצָעוֹ. אִם יֵשׁ בֵּינֵיהֶם שֵׁשׁ עֶשְׂרֵה אַמָּה מַרְחִיק מִזֶּה אַרְבַּע אַמּוֹת וּמִזֶּה אַרְבַּע אַמּוֹת וְזוֹרֵעַ אֶת הַמּוֹתָר. וְאִם הָיָה פָּחוֹת מִכָּאן לֹא יָבִיא זֶרַע לְשָׁם:","שׁוֹמֵרָה שֶׁבַּכֶּרֶם אִם גְּבוֹהָה עֲשָׂרָה וּרְחָבָה אַרְבָּעָה מֻתָּר לִזְרֹעַ בְּרֹאשָׁהּ יָרָק. וּבִלְבַד שֶׁלֹּא יִהְיוּ הַשָּׂרִיגִין נוֹגְעִין בָּהּ כְּדֵי שֶׁלֹּא יֵרָאֶה יָרָק בְּתוֹךְ הַכֶּרֶם מִלְּמַעְלָה. בַּמֶּה דְּבָרִים אֲמוּרִים בִּמְרֻבַּעַת. אֲבָל אִם הָיְתָה הַשּׁוֹמֵרָה עֲגֻלָּה צְרִיכָה שֶׁיִּהְיֶה בְּתוֹכָהּ חָלָל אַרְבָּעָה טְפָחִים כְּדֵי שֶׁתִּהְיֶה מֻפְלֶגֶת מִן הָאָרֶץ. וּצְרִיכָה עָפָר עַל רֹאשָׁהּ מִלְּמַעְלָה שְׁלֹשָׁה טְפָחִים:","הַבַּיִת שֶׁבַּכֶּרֶם אִם הָיָה יוֹתֵר מִשְּׁלֹשָׁה טְפָחִים עַל שְׁלֹשָׁה טְפָחִים עַד אַרְבָּעָה זוֹרְעִין בְּתוֹכוֹ יָרָק. וְאִם הָיָה פָּחוֹת מִשְּׁלֹשָׁה עַל שְׁלֹשָׁה הֲרֵי הוּא כְּסָתוּם וְאֵין זוֹרְעִין בְּתוֹכוֹ:","גֶּפֶן יְחִידִית שֶׁהָיְתָה נְטוּעָה בְּתוֹךְ הַנֶּקַע אוֹ בְּתוֹךְ הֶחָרִיץ מַרְחִיק מִמֶּנָּה שִׁשָּׁה טְפָחִים לְכָל רוּחַ וְזוֹרֵעַ אֶת כָּל הֶחָרִיץ כְּדֶרֶךְ שֶׁעוֹשֶׂה בַּמִּישׁוֹר. וְאִם הָיָה עָמֹק עֲשָׂרָה וְהָיָה רֹחַב שְׂפַת הֶחָרִיץ לְמַעְלָה אַרְבָּעָה אָסוּר לִזְרֹעַ בְּתוֹכוֹ אַף עַל פִּי שֶׁהִרְחִיק שִׁשָּׁה:","וְכֵן גֶּפֶן יְחִידִית שֶׁהָיְתָה מֻקֶּפֶת גָּדֵר גָּבוֹהַּ עֲשָׂרָה וְרָחָב אַרְבָּעָה לֹא יִזְרַע בְּכָל הַמְּחִצָּה וְאַף עַל פִּי שֶּׁהִרְחִיק שִׁשָּׁה. וְאִם הִרְחִיק שִׁשָּׁה וְזָרַע לֹא קִדֵּשׁ. וְכַמָּה יַרְחִיק לְכַתְּחִלָּה וְיִזְרַע אַרְבַּע אַמּוֹת לְכָל רוּחַ וְאַחַר כָּךְ יִזְרַע שְׁאָר הֶחָרִיץ אוֹ שְׁאָר הַמָּקוֹם הַמֻּקָּף גָּדֵר:"],"Mishneh Torah, Divorce 6":["הַשָׁלִיחַ שֶׁעוֹשָׂה הָאִשָּׁה לְקַבֵּל לָהּ גִּטָּהּ מִיַּד בַּעְלָהּ הוּא הַנִּקְרָא שְׁלִיחַ קַבָּלָה. וּמִשֶּׁיַגִּיעַ הַגֵּט לְיַד שְׁלוּחָהּ תִּתְגָּרֵשׁ כְּאִלּוּ הִגִּיעַ לְיָדָהּ. וּצְרִיכָה לַעֲשׂוֹתוֹ בִּשְׁנֵי עֵדִים. וּצְרִיכָה שְׁנֵי עֵדִים שֶׁיָּעִידוּ שֶׁהִגִּיעַ הַגֵּט לְיַד שְׁלוּחָהּ. וַאֲפִלּוּ הֵם הָרִאשׁוֹנִים אוֹ אֶחָד מִן הָרִאשׁוֹנִים הֲרֵי זוֹ עֵדוּת גְּמוּרָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאָבַד הַגֵּט אוֹ נִקְרַע. אֲבָל אִם הָיָה הַגֵּט יוֹצֵא מִתַּחַת יְדֵי שְׁלִיחַ קַבָּלָה אֵינוֹ צָרִיךְ עֵדִים. בֵּין שֶׁנְּתָנוֹ לוֹ הַבַּעַל בֵּינוֹ לְבֵינוֹ בֵּין שֶׁנִּמְסַר לוֹ בְּעֵדִים. יְצִיאָתוֹ מִתַּחַת יָדוֹ כִּיצִיאָתוֹ מִתַּחַת יְדֵי הָאִשָּׁה. וְאַף עַל פִּי כֵן לֹא יִתֵּן לוֹ הַגֵּט לְכַתְּחִלָּה אֶלָּא בְּעֵדֵי מְסִירָה כְּמוֹ הָאִשָּׁה עַצְמָהּ:","הַבַּעַל אֵינוֹ יָכוֹל לַעֲשׂוֹת שָׁלִיחַ לְקַבֵּל גֵּט לְאִשְׁתּוֹ. אֲבָל יָכוֹל לַעֲשׂוֹת שָׁלִיחַ לְהוֹלִיךְ הַגֵּט לְאִשְׁתּוֹ וְזֶה הוּא הַנִּקְרָא שְׁלִיחַ הוֹלָכָה:","וְכֵן הָאִשָּׁה שׁוֹלַחַת שָׁלִיחַ לְהָבִיא לָהּ גֵּט מִיַּד בַּעְלָהּ וְזֶה הוּא הַנִּקְרָא שְׁלִיחַ הֲבָאָה. וְאֵין שְׁלִיחַ הוֹלָכָה וַהֲבָאָה צָרִיךְ עֵדִים:","וְאֵין הָאִשָּׁה מִתְגָּרֶשֶׁת בְּגֵט שֶׁשָּׁלַח הַבַּעַל אוֹ שֶׁהֵבִיא לָהּ שְׁלִיחַ הֲבָאָה עַד שֶׁיַּגִּיעַ גֵּט לְיָדָהּ. וְכָל מָקוֹם שֶׁנֶּאֱמַר בְּעִנְיַן גִּטִּין שָׁלִיחַ סְתָם הוּא שְׁלִיחַ הוֹלָכָה אוֹ שְׁלִיחַ הֲבָאָה:","הַכּל כְּשֵׁרִין לִשְׁלִיחוּת הַגֵּט בֵּין לִשְׁלִיחַ קַבָּלָה בֵּין לִשְׁלִיחַ הוֹלָכָה וַהֲבָאָה חוּץ מִן הַחֲמִשָּׁה. הָעַכּוּ״‎ם וְהָעֶבֶד וְהַחֵרֵשׁ וְהַשּׁוֹטֶה וְהַקָּטָן. וְאִם קִבֵּל אוֹ הֵבִיא אֶחָד מֵהֶן אֵינוֹ גֵּט:","אֲבָל הַנָּשִׁים וְהַקְּרוֹבִים כְּשֵׁרִים. וַאֲפִלּוּ הַפְּסוּלִין מִדִּבְרֵי סוֹפְרִים בַּעֲבֵרָה כְּשֵׁרִין לִשְׁלִיחוּת גֵּט. אֲבָל הַפְּסוּלִין בַּעֲבֵרָה מִדִּבְרֵי תּוֹרָה פְּסוּלִין לַהֲבָאַת הַגֵּט. וְאִם הֵבִיאוּ הֲרֵי זֶה פָּסוּל. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנִּתְקַיֵּם הַגֵּט בְּחוֹתְמָיו אֲבָל אִם לֹא נִסְמֹךְ בּוֹ אֶלָּא עַל דִּבְרֵי פָּסוּל בַּעֲבֵרָה מִן הַתּוֹרָה אֵינוֹ גֵּט:","הָיָה הַשָּׁלִיחַ קָטָן כְּשֶׁנָּתַן לוֹ הַגֵּט וְגָדַל כְּשֶׁהֱבִיאוֹ. חֵרֵשׁ וְנִתְפַּקֵּחַ. שׁוֹטֶה וְנִשְׁתַּפָּה. עַכּוּ״‎ם וְנִתְגַּיֵּר. עֶבֶד וְנִשְׁתַּחְרֵר. הֲרֵי זֶה בָּטֵל. אֲבָל אִם נָתַן לוֹ הַגֵּט וְהוּא פִּקֵּחַ וְנִתְחָרֵשׁ וְחָזַר וְנִתְפַּקֵּחַ. הָיָה שָׁפוּי כְּשֶׁנָּתַן לוֹ הַגֵּט וְנִשְׁתַּטָּה וְחָזַר וְנִשְׁתַּפָּה כְּשֶׁהֵבִיא הַגֵּט לְיַד הָאִשָּׁה הֲרֵי זֶה גֵּט כָּשֵׁר מִפְּנֵי שֶׁתְּחִלָּתוֹ וְסוֹפוֹ בְּדַעַת:","הָאִשָּׁה שֶׁעָשְׂתָה שָׁלִיחַ בְּעֵדִים וְאָמְרָה לוֹ טֹל לִי גִּטִּי וִיהֵא לִי בְּיָדְךָ הֲרֵי זֶה שָׁלִיחַ לְקַבָּלָה וּכְאִלּוּ אָמְרָה לוֹ הִתְקַבֵּל לִי גִּטִּי. וְיֵשׁ לָאִשָּׁה לַעֲשׂוֹת שְׁלִיחַ קַבָּלָה לְקַבֵּל לָהּ גִּטָּהּ מִיַּד שְׁלוּחוֹ שֶׁל בַּעְלָהּ. וּקְטַנָּה אֵינָהּ עוֹשָׂה שָׁלִיחַ לְקַבָּלָה. אַף עַל פִּי שֶׁחֲצֵרָהּ קוֹנָה לָהּ גִּטָּהּ כִּגְדוֹלָה. מִפְּנֵי שֶׁשְּׁלִיחַ קַבָּלָה צָרִיךְ עֵדִים וְאֵין מְעִידִין עַל הַקָּטָן שֶׁאֵינוֹ בֶּן דֵּעָה גְּמוּרָה:","הָאִשָּׁה שֶׁעָשְׂתָה שָׁלִיחַ לְקַבָּלָה וְאָמַר לוֹ הַבַּעַל אֵין רְצוֹנִי שֶׁתְּקַבֵּל לָהּ גִּטָּהּ אֶלָּא הֲרֵי זֶה גִּטָּהּ הוֹלֵךְ אוֹתוֹ לָהּ. הָרְשׁוּת בְּיַד הַבַּעַל וְנַעֲשָׂה זֶה שָׁלִיחַ לְהוֹלָכָה וְלֹא שָׁלִיחַ לְקַבָּלָה. אֲבָל אִם אָמַר לוֹ הִתְקַבֵּל לָהּ גִּטָּהּ [אוֹ הֵא לְךָ] אוֹ זְכֵה לָהּ לֹא עָקַר שְׁלִיחוּת הַקַּבָּלָה. אֲבָל אִם אָמַר לוֹ הוֹלֵךְ לָהּ עָקַר שְׁלִיחוּת הַקַּבָּלָה וְנַעֲשָׂה שְׁלִיחַ הַבַּעַל. וְכֵן אִם אָמַר לוֹ הוֹלֵךְ וְתֵן לָהּ עָקַר שְׁלִיחוּת הַקַּבָּלָה:","שְׁלִיחַ הָאִשָּׁה שֶׁבָּא לְקַבֵּל גֵּט מִן הַבַּעַל וְאָמַר לוֹ שְׁלִיחַ קַבָּלָה אָנִי וְאוֹמֵר לוֹ הַבַּעַל הוֹלֵךְ גֵּט זֶה כְּמוֹ שֶׁאָמְרָה כְּלוֹמַר אֵינִי עוֹקֵר שְׁלִיחוּתְךָ אֶלָּא בֵּין שֶׁעָשְׂתָה אוֹתְךָ שְׁלִיחַ קַבָּלָה אוֹ שְׁלִיחַ הֲבָאָה הֲרֵי אַתָּה כְּמוֹ שֶׁאָמְרָה. וְהֵבִיא אֶת הַגֵּט. וְאָמְרָה לוֹ לֹא [שָׁלִיחַ לְקַבָּלָה] שַׂמְתִּיךָ אֶלָּא שְׁלִיחַ הֲבָאָה אֲפִלּוּ הִגִּיעַ לְיָדָהּ אֵינָהּ מְגֹרֶשֶׁת. שֶׁהֲרֵי עָקַר הַשָּׁלִיחַ שְׁלִיחוּת שֶׁאָמְרָה הִיא וְאָמַר לַבַּעַל מֵעוֹלָם לֹא נַעֲשֵׂיתִי שְׁלִיחַ הֲבָאָה לָהּ:","אָמַר שָׁלִיחַ לַבַּעַל שְׁלִיחַ הֲבָאָה אֲנִי וְאָמַר לוֹ הַבַּעַל הוֹלֵךְ כְּמוֹ שֶׁאָמְרָה. וְהֵבִיא אֶת הַגֵּט. וְאָמְרָה לוֹ שָׁלִיחַ לְקַבָּלָה שַׂמְתִּיךָ. כֵּיוָן שֶׁהִגִּיעַ גֵּט לְיָדָהּ מְגֹרֶשֶׁת שֶׁהֲרֵי לֹא עָקַר שְׁלִיחוּת שֶׁאָמְרָה אֶלָּא גָּרַע אוֹתָהּ שֶׁהֲרֵי הִיא אוֹמֶרֶת לְקַבָּלָה וְהוּא אוֹמֵר לַבַּעַל לַהֲבָאָה בִּלְבַד:","הַבַּעַל שֶׁשָּׁלַח גֵּט לְאִשְׁתּוֹ. בָּא שָׁלִיחַ לִתְּנוֹ לָהּ וְלֹא נְטַלְתּוֹ. אֶלָּא אָמְרָה לוֹ בִּפְנֵי עֵדִים יִהְיֶה (לִי) גֵּט זֶה פִּקָּדוֹן אֶצְלְךָ. אוֹ שֶׁאָמְרָה לוֹ הֲרֵי אַתְּ שָׁלִיחַ לְקַבְּלוֹ לִי. הֲרֵי זוֹ מְגֹרֶשֶׁת בְּסָפֵק עַד שֶׁיַּגִּיעַ גֵּט לְיָדָהּ. וּמִשֶּׁיַגִּיעַ הַגֵּט לְיָדָהּ תִּתְגָּרֵשׁ וַדַּאי:","שָׁלִיחַ שֶׁהֵבִיא גֵּט כְּשֶׁהוּא נוֹתְנוֹ לָהּ נוֹתְנוֹ לָהּ בִּפְנֵי שְׁנַיִם וְאוֹתָן הַשְּׁנַיִם צְרִיכִין לִקְרוֹתוֹ וְאַחַר כָּךְ יִנָּתֵן לָהּ בִּפְנֵיהֶם. שֶׁדִּין הַשָּׁלִיחַ עִם הָאִשָּׁה כְּדִין הַבַּעַל עִמָּהּ שֶׁתַּחְתָּיו הוּא קָם. לְפִיכָךְ אִם נְתָנוֹ הַשָּׁלִיחַ לָהּ וְלֹא קְרָאוּהוּ עֵדֵי מְסִירָה וּנְטַלְתּוֹ וּזְרַקְתּוֹ לַיָּם הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","עָבַר הַשָּׁלִיחַ וְנָתַן הַגֵּט בֵּינוֹ לְבֵינָהּ יִטְּלֶנּוּ מִמֶּנָּה וְיַחֲזֹר וְיִתְּנוֹ לָהּ בִּפְנֵי שְׁנַיִם. וְאִם מֵת הוֹאִיל וְהַגֵּט יוֹצֵא מִתַּחַת יָדָהּ מְקֻיָּם בְּחוֹתְמָיו הֲרֵי זֶה גֵּט כָּשֵׁר:","שָׁלִיחַ שֶׁנָּטַל הַגֵּט וְקֹדֶם שֶׁיַּגִּיעַ לְיַד הָאִשָּׁה חָזַר הַבַּעַל וְאָמַר לוֹ גֵּט שֶׁשָּׁלַחְתִּי עִמְּךָ בָּטֵל הוּא. אוֹ שֶׁקָּדַם וְאָמַר לָאִשָּׁה גֵּט שֶׁשָּׁלַחְתִּי לִיךְ בָּטֵל הוּא. אוֹ שֶׁשָּׁלַח שָׁלִיחַ אַחֵר לְבַטְּלוֹ. אוֹ שֶׁאָמַר לַאֲחֵרִים גֵּט שֶׁשָּׁלַחְתִּי לְאִשְׁתִּי בָּטֵל הוּא. הֲרֵי זֶה בָּטֵל וְאַף עַל פִּי שֶׁהִגִּיעַ גֵּט לְיָדָהּ. וְכָל הַמְבַטֵּל בִּפְנֵי אֲחֵרִים צָרִיךְ שֶׁיְּבַטֵּל בִּפְנֵי שְׁנַיִם. וְאִם אַחַר שֶׁהִגִּיעַ גֵּט לְיָדָהּ אוֹ לְיַד שְׁלִיחַ קַבָּלָה אֵינוֹ יָכוֹל לְבַטְּלוֹ וְאַף עַל פִּי שֶׁחָזַר בְּתוֹךְ כְּדֵי דִּבּוּר וּבִטְּלוֹ הוֹאִיל וְאַחַר שֶׁהִגִּיעַ לְיָדָהּ אוֹ לְיַד שְׁלִיחַ קַבָּלָה אוֹ לַחֲצֵרָהּ בִּטְּלוֹ אֵינוֹ בָּטֵל וַהֲרֵי זֶה גֵּט כָּשֵׁר:","הָיָה מְחַזֵּר וּמְבַקֵּשׁ שָׁלִיחַ כְּדֵי לְבַטְּלוֹ. אוֹ שֶׁהָיָה מְבַקֵּשׁ שְׁנַיִם שֶׁיְּבַטְּלֶנּוּ בִּפְנֵיהֶם וּבֵין שֶׁהוּא מְחַזֵּר וְרוֹדֵף הִגִּיעַ גֵּט לְיָדָהּ וְאַחַר כָּךְ בִּטְּלוֹ אֵינוֹ בָּטֵל. אַף עַל פִּי שֶׁהָיָה מְחַזֵּר לְבַטְּלוֹ קֹדֶם שֶׁהִגִּיעַ הַגֵּט לְיָדָהּ:","אָמַר לַעֲשָׂרָה כִּתְבוּ גֵּט וּתְנוּ לְאִשְׁתִּי יָכוֹל לְבַטֵּל לָזֶה שֶׁלֹּא בִּפְנֵי זֶה וַאֲפִלּוּ בִּפְנֵי שְׁנַיִם אֲחֵרִים. שָׁלַח הַגֵּט בְּיַד שְׁנַיִם הֲרֵי זֶה יָכוֹל לְבַטֵּל זֶה שֶׁלֹּא בִּפְנֵי זֶה. וַאֲפִלּוּ הָיוּ עֲשָׂרָה מִשֶּׁבִּטְּלוֹ בִּפְנֵי אֶחָד מֵהֶם בָּטֵל הַגֵּט:","וְכֵן מִי שֶׁאָמַר לִשְׁנַיִם גֵּט שֶׁאֲנִי כּוֹתֵב לְאִשְׁתִּי בָּטֵל הוּא וְכָתַב אַחַר כָּךְ גֵּט וּנְתָנוֹ לָהּ בִּפְנֵי שְׁנַיִם אֲחֵרִים הֲרֵי זֶה בָּטֵל. וְזוֹ הִיא מְסִירַת הַמּוֹדָעָא עַל הַגֵּט. וְכֵן אִם אָמַר לָהֶם כָּל גֵּט שֶׁיִּכְתֹּב לִי פְּלוֹנִי בָּטֵל. אוֹ כָּל גֵּט שֶׁאֶכְתֹּב בְּבֵית דִּינוֹ שֶׁל פְּלוֹנִי הֲרֵי זֶה גֵּט בָּטֵל. אוֹ כָּל גֵּט שֶׁאֶכְתֹּב מִכָּאן וְעַד עֶשְׂרִים שָׁנָה בָּטֵל. הֲרֵי גֵּט בָּטֵל. וְכֵן אִם אָמַר בִּפְנֵי שְׁנַיִם כָּל גֵּט שֶׁאֶכְתֹּב לִפְלוֹנִית אִשְׁתִּי בָּטֵל הוּא וְכָל דָּבָר שֶׁאֲבַטֵּל בּוֹ מוֹדָעָא זֹאת הֲרֵי הוּא בָּטֵל וְכָתַב אַחַר כָּךְ גֵּט וּנְתָנוֹ לָהּ אַף עַל פִּי שֶׁבִּטֵּל הַמּוֹדָעָא קֹדֶם שֶׁיִּכְתֹּב הַגֵּט הֲרֵי הַגֵּט בָּטֵל:","אִם כֵּן מַהוּ תַּקָּנַת דָּבָר זֶה. שֶׁיֹּאמְרוּ לוֹ הָעֵדִים קֹדֶם כְּתִיבַת הַגֵּט אֱמֹר בְּפָנֵינוּ שֶׁכָּל הַדְּבָרִים שֶׁמָּסַרְתָּ שֶׁגּוֹרְמִין כְּשֶׁיִּתְקַיְּמוּ אוֹתָן הַדְּבָרִים לְבַטֵּל גֵּט הֲרֵי הֵן בְּטֵלִים וְהוּא אוֹמֵר הֵן. וְאַחַר כָּךְ אוֹמֵר לָהֶם לִכְתֹּב וְלַחְתֹּם וְלִתֵּן לָהּ וְלֹא יְנִיחוּהוּ לֵילֵךְ עַד שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ כְּדֵי שֶׁלֹּא יֵצֵא וִיבַטְּלוֹ. וְאֵין הַמּוֹסֵר מוֹדָעָא וְלֹא הַמְבַטֵּל מוֹדָעָא צָרִיךְ קִנְיָן:","הַשּׁוֹלֵחַ גֵּט בְּיַד הַשָּׁלִיחַ וּבִטֵּל הַגֵּט הֲרֵי חוֹזֵר וּמְגָרֵשׁ בּוֹ כְּשֶׁיִּרְצֶה. שֶׁלֹּא בִּטְּלוֹ מִתּוֹרַת גֵּט אֶלָּא מִתּוֹרַת שְׁלִיחוּת. לְפִיכָךְ אִם הָיָה הַגֵּט בְּיַד הַבַּעַל וּבִטְּלוֹ כְּגוֹן שֶׁאָמַר גֵּט זֶה בָּטֵל הוּא אֵינוֹ מְגָרֵשׁ בּוֹ לְעוֹלָם וַהֲרֵי הוּא כְּחֶרֶס הַנִּשְׁבָּר. וְאִם גֵּרֵשׁ בּוֹ אֵינָהּ מְגֹרֶשֶׁת. וְכֵן אִם פֵּרֵשׁ בְּעֵת שֶׁבִּטְּלוֹ וְהוּא בְּיַד הַשָּׁלִיחַ וְאָמַר גֵּט שֶׁשָּׁלַחְתִּי הֲרֵי הוּא בָּטֵל מִלִּהְיוֹת גֵּט אֵין מְגָרֵשׁ בּוֹ לְעוֹלָם:","בְּאֵי זֶה לְשׁוֹנוֹת מְבַטֵּל הַגֵּט. אָמַר בָּטֵל הוּא. אִי אֶפְשִׁי בּוֹ. גֵּט זֶה לֹא יוֹעִיל. לֹא יַתִּיר. וְלֹא יַעֲזֹב. וְלֹא יְשַׁלֵּחַ. וְלֹא יְגָרֵשׁ. יְהֵא כְּחֶרֶס. יְהִי חֶרֶס. הֲרֵי הוּא כְּחֶרֶס. וְאִם אָמַר אֶחָד מֵאֵלּוּ וְכָל הַדּוֹמֶה לָהֶן הֲרֵי זֶה בִּטְּלוֹ:","אֲבָל אִם אָמַר גֵּט זֶה אֵינוֹ. גֵּט פָּסוּל הוּא. אֵינוֹ מוֹעִיל. אֵינוֹ מַתִּיר. אֵינוֹ מְשַׁלֵּחַ. אֵינוֹ מְגָרֵשׁ. חֶרֶס הוּא. לֹא אָמַר כְּלוּם. שֶׁאֵין זֶה לָשׁוֹן מְבַטֵּל אֶלָּא לְשׁוֹן מוֹדִיעַ אֲמִתַּת הַדָּבָר וַהֲרֵי הוֹדִיעַ לָנוּ דָּבָר שֶׁאֵינוֹ כֵּן. כְּמִי שֶׁאוֹמֵר עַל דָּבָר אָסוּר שֶׁהוּא מֻתָּר אוֹ עַל דָּבָר הַטָּמֵא שֶׁהוּא טָהוֹר:","אָמַר גֵּט זֶה בָּטַל שֶׁמַּשְׁמָעוֹ פֹּעַל שֶׁעָבַר כְּגוֹן (שיר השירים ה ו) “‎חָמַק עָבַר״‎ הֲרֵי זֶה סָפֵק. לְפִיכָךְ אִם נִתְגָּרְשָׁה בְּגֵט זֶה הֲרֵי סָפֵק מְגֹרֶשֶׁת:","מִי שֶׁשָּׁלַח גֵּט לְאִשְׁתּוֹ וּבָא שָׁלִיחַ וְאָמַר לוֹ לֹא מְצָאתִיהָ אוֹ לֹא רָצְתָה לִקַּח. וְאָמַר הַבַּעַל בָּרוּךְ הַטּוֹב וְהַמֵּיטִיב אוֹ כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁמַּשְׁמִיעִין שֶׁאֵין בְּדַעְתּוֹ לְגָרְשָׁהּ שֶׁהֲרֵי שָׂמֵחַ בְּעִכּוּב הַגֵּט. לֹא בָּטֵל הַגֵּט אֶלָּא יִתֵּן וְתִהְיֶה מְגֹרֶשֶׁת. עַד שֶׁיֹּאמַר לוֹ בְּפֵרוּשׁ לֹא תִּתֵּן לָהּ אוֹ יְבַטֵּל בְּפֵרוּשׁ:","מִי שֶׁשָּׁלַח גֵּט לְאִשְׁתּוֹ וְחָזַר וּבִטְּלוֹ בִּפְנֵי שְׁנַיִם אֲחֵרִים. וְכֵן מִי שֶׁמָּסַר מוֹדָעָא עַל הַגֵּט מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִפְּנֵי שֶׁגּוֹרֵם לִהְיוֹת מַמְזֵרִים. שֶׁהֲרֵי יַגִּיעַ גֵּט לְיָדָהּ וְתִנָּשֵׂא בּוֹ וְאַחַר זְמַן יֵצְאוּ עֵדִים שֶׁבִּטֵּל בִּפְנֵיהֶם אוֹ שֶׁמָּסַר מוֹדָעָא בִּפְנֵיהֶם קֹדֶם שֶׁיִּכְתֹּב הַגֵּט וְנִמְצָא הַוָּלָד מַמְזֵר:","שָׁלִיחַ שֶׁהֵבִיא גֵּט וּנְתָנוֹ לָאִשָּׁה אֵין אוֹמְרִין שֶׁמָּא בִּטְּלוֹ הַבַּעַל אֶלָּא נוֹתְנִין אוֹתוֹ לָהּ בְּחֶזְקַת שֶׁהוּא כָּשֵׁר וְתִנָּשֵׂא בּוֹ. וְאִם נִמְצָא אַחַר כֵּן שֶׁבִּטְּלוֹ תֵּצֵא וְהַוָּלָד מַמְזֵר. וְכֵן הַכּוֹתֵב גֵּט וּנְתָנוֹ לְאִשְׁתּוֹ אֵין אוֹמְרִין שֶׁמָּא מָסַר מוֹדָעָא עַל גֵּט זֶה אֶלָּא הֲרֵי הוּא בְּחֶזְקַת כַּשְׁרוּת וְתִנָּשֵׂא בּוֹ:","וְכֵן הַמֵּבִיא גֵּט וְהִנִּיחַ הַבַּעַל חוֹלֶה אוֹ שֶׁהָיָה זָקֵן נוֹתְנוֹ לָהּ בְּחֶזְקַת שֶׁהוּא קַיָּם. אֲבָל אִם הִנִּיחוֹ גּוֹסֵס שֶׁרֹב גּוֹסְסִין לְמִיתָה וְאַף עַל פִּי שֶׁנְּתָנוֹ לָהּ הֲרֵי זֶה סְפֵק גֵּרוּשִׁין שֶׁאֵין גֵּט לְאַחַר מִיתָה. וְכֵן עִיר שֶׁהִקִּיפָהּ הַחַיִל וְהִיא בְּמָצוֹר וּסְפִינָה הַמּוּטְרֶפֶת בַּיָּם וְהַיּוֹצֵא לָדוּן הֲרֵי אֵלּוּ בְּחֶזְקַת חַיִּים. וְאִם הָיָה גֵּט אֶחָד מֵהֶן בְּיַד הַשָּׁלִיחַ נוֹתְנוֹ לְאִשְׁתּוֹ וְתִהְיֶה בְּחֶזְקַת מְגֹרֶשֶׁת:","אֲבָל עִיר שֶׁכְּבָשָׁהּ הַגַּיִס וְהֻבְקְעָה וּסְפִינָה שֶׁאָבְדָה בַּיָּם וְהַיּוֹצֵא לֵהָרֵג מִבֵּית דִּין שֶׁל עַכּוּ״‎ם. וּמִי שֶׁגְּרָרַתּוּ חַיָּה אוֹ שְׁטָפוֹ נָהָר אוֹ נָפְלָה עָלָיו מַפּלֶת נוֹתְנִים עֲלֵיהֶם חֻמְרֵי חַיִּים וְחֻמְרֵי מֵתִים. וְאִם הָיָה גֵּט אֶחָד מֵהֶן בְּיַד הַשָּׁלִיחַ אֵינוֹ נוֹתְנוֹ לְאִשְׁתּוֹ וְאִם נְתָנוֹ לָהּ הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת. וְאִם נוֹדַע שֶׁמֵּת הַבַּעַל קֹדֶם שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ אֵינוֹ גֵּט:","הַבַּעַל שֶׁשָּׁלַח גֵּט לְאִשְׁתּוֹ הֲרֵי הוּא חַיָּב בִּמְזוֹנוֹתֶיהָ וּבְכָל תְּנָאֵי כְּתֻבָּה עַד שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ אוֹ לְיַד שְׁלִיחַ קַבָּלָה:"],"Mishneh Torah, Fasts 1":["מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לִזְעֹק וּלְהָרִיעַ בַּחֲצוֹצְרוֹת עַל כָּל צָרָה שֶׁתָּבוֹא עַל הַצִּבּוּר. שֶׁנֶּאֱמַר (במדבר י ט) \"עַל הַצַּר הַצֹּרֵר אֶתְכֶם וַהֲרֵעֹתֶם בַּחֲצֹצְרוֹת\". כְּלוֹמַר כָּל דָּבָר שֶׁיָּצֵר לָכֶם כְּגוֹן בַּצֹּרֶת וְדֶבֶר וְאַרְבֶּה וְכַיּוֹצֵא בָּהֶן זַעֲקוּ עֲלֵיהֶן וְהָרִיעוּ:","וְדָבָר זֶה מִדַּרְכֵי הַתְּשׁוּבָה הוּא. שֶׁבִּזְמַן שֶׁתָּבוֹא צָרָה וְיִזְעֲקוּ עָלֶיהָ וְיָרִיעוּ יֵדְעוּ הַכּל שֶׁבִּגְלַל מַעֲשֵׂיהֶם הָרָעִים הוּרַע לָהֶן כַּכָּתוּב (ירמיה ה כה) \"עֲוֹנוֹתֵיכֶם הִטּוּ\" וְגוֹ'. וְזֶה הוּא שֶׁיִּגְרֹם לָהֶם לְהָסִיר הַצָּרָה מֵעֲלֵיהֶם:","אֲבָל אִם לֹא יִזְעֲקוּ וְלֹא יָרִיעוּ אֶלָּא יֹאמְרוּ דָּבָר זֶה מִמִּנְהַג הָעוֹלָם אֵרַע לָנוּ וְצָרָה זוֹ נִקְרָה נִקְרֵית. הֲרֵי זוֹ דֶּרֶךְ אַכְזָרִיּוּת וְגוֹרֶמֶת לָהֶם לְהִדַּבֵּק בְּמַעֲשֵׂיהֶם הָרָעִים. וְתוֹסִיף הַצָּרָה צָרוֹת אֲחֵרוֹת. הוּא שֶׁכָּתוּב בַּתּוֹרָה (ויקרא כו כז) \"וַהֲלַכְתֶּם עִמִּי בְּקֶרִי\" (ויקרא כו כח) \"וְהָלַכְתִּי גַּם אֲנִי עִמָּכֶם בַּחֲמַת קֶרִי\". כְּלוֹמַר כְּשֶׁאָבִיא עֲלֵיכֶם צָרָה כְּדֵי שֶׁתָּשׁוּבוּ אִם תֹּאמְרוּ שֶׁהִיא קֶרִי אוֹסִיף לָכֶם חֲמַת אוֹתוֹ קֶרִי:","וּמִדִּבְרֵי סוֹפְרִים לְהִתְעַנּוֹת עַל כָּל צָרָה שֶׁתָּבוֹא עַל הַצִּבּוּר עַד שֶׁיְּרֻחֲמוּ מִן הַשָּׁמַיִם. וּבִימֵי הַתַּעֲנִיּוֹת הָאֵלּוּ זוֹעֲקִין בִּתְפִלּוֹת וּמִתְחַנְּנִים וּמְרִיעִין בַּחֲצוֹצְרוֹת בִּלְבַד. וְאִם הָיוּ בַּמִּקְדָּשׁ מְרִיעִין בַּחֲצוֹצְרוֹת וּבְשׁוֹפָר. הַשּׁוֹפָר מְקַצֵּר וְהַחֲצוֹצְרוֹת מַאֲרִיכוֹת. שֶׁמִּצְוַת הַיּוֹם בַּחֲצוֹצְרוֹת. וְאֵין תּוֹקְעִין בַּחֲצוֹצְרוֹת וְשׁוֹפָר כְּאֶחָד אֶלָּא בַּמִּקְדָּשׁ שֶׁנֶּאֱמַר (תהילים צח ו) \"בַּחֲצֹצְרוֹת וְקוֹל שׁוֹפָר הָרִיעוּ לִפְנֵי הַמֶּלֶךְ ה'\":","תַּעֲנִיּוֹת אֵלּוּ שֶׁגּוֹזְרִין עַל הַצִּבּוּר מִפְּנֵי הַצָּרוֹת אֵינָן יוֹם אַחַר יוֹם. שֶׁאֵין רֹב הַצִּבּוּר יְכוֹלִים לַעֲמֹד בְּדָבָר זֶה. וְאֵין גּוֹזְרִין בַּתְּחִלָּה תַּעֲנִית אֶלָּא בְּשֵׁנִי בְּשַׁבָּת וּבַחֲמִישִׁי שֶׁלְּאַחֲרָיו וּבְשֵׁנִי שֶׁלְּאַחֲרָיו וְכֵן עַל הַסֵּדֶר הַזֶּה שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי עַד שֶׁיְּרֻחֲמוּ:","אֵין גּוֹזְרִין תַּעֲנִית עַל הַצִּבּוּר לֹא בְּשַׁבָּתוֹת וְלֹא בְּיָמִים טוֹבִים. וְכֵן אֵין תּוֹקְעִין בָּהֶן לֹא בְּשׁוֹפָר וְלֹא בַּחֲצוֹצְרוֹת וְלֹא זוֹעֲקִים וּמִתְחַנְּנִים בָּהֶם בַּתְּפִלָּה. אֶלָּא אִם כֵּן הָיְתָה עִיר שֶׁהִקִּיפוּהָ עַכּוּ\"ם אוֹ נָהָר אוֹ סְפִינָה הַמִּטָּרֶפֶת בַּיָּם. אֲפִלּוּ יָחִיד הַנִּרְדָּף מִפְּנֵי עַכּוּ\"ם מִפְּנֵי לִסְטִים וּמִפְּנֵי רוּחַ רָעָה (מִתְעַנִּין עֲלֵיהֶם בְּשַׁבָּת וְ) זוֹעֲקִין וּמִתְחַנְּנִים עֲלֵיהֶם בַּתְּפִלָּה. אֲבָל אֵין תּוֹקְעִין אֶלָּא אִם כֵּן תָּקְעוּ לְקַבֵּץ אֶת הָעָם לַעֲזֹר אוֹתָם וּלְהַצִּילָן:","וְכֵן אֵין גּוֹזְרִין תַּעֲנִית בַּתְּחִלָּה בְּרָאשֵׁי חֳדָשִׁים אוֹ בַּחֲנֻכָּה וּפוּרִים אוֹ בְּחֻלּוֹ שֶׁל מוֹעֵד. וְאִם הִתְחִילוּ לְהִתְעַנּוֹת עַל הַצָּרָה אֲפִלּוּ יוֹם אֶחָד וּפָגַע בָּהֶן יוֹם מֵאֵלּוּ מִתְעַנִּין וּמַשְׁלִימִין הַיּוֹם בְּתַעֲנִית:","תַּעֲנִיּוֹת אֵלּוּ שֶׁמִּתְעַנִּין עַל הַצָּרוֹת אֵין מִתְעַנִּין בָּהֶן לֹא עֻבָּרוֹת וְלֹא מֵינִיקוֹת וְלֹא קְטַנִּים. וּמֻתָּרִין לֶאֱכל בַּלַּיְלָה אַף עַל פִּי שֶׁמִּתְעַנִּין לְמָחָר חוּץ מִתַּעֲנִיּוֹת הַמָּטָר כְּמוֹ שֶׁיִּתְבָּאֵר. וְכָל תַּעֲנִית שֶׁאוֹכְלִין בָּהּ בַּלַּיְלָה בֵּין צִבּוּר בֵּין יָחִיד הֲרֵי זֶה אוֹכֵל וְשׁוֹתֶה עַד שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר. וְהוּא שֶׁלֹּא יָשֵׁן אֲבָל אִם יָשֵׁן אֵינוֹ חוֹזֵר וְאוֹכֵל:","כְּשֵׁם שֶׁהַצִּבּוּר מִתְעַנִּים עַל צָרָתָן כָּךְ הַיָּחִיד מִתְעַנֶּה עַל צָרָתוֹ. כֵּיצַד. הֲרֵי שֶׁהָיָה לוֹ חוֹלֶה אוֹ תּוֹעֶה בַּמִּדְבָּר אוֹ אָסוּר בְּבֵית הָאֲסוּרִין. יֵשׁ לוֹ לְהִתְעַנּוֹת עָלָיו וּלְבַקֵּשׁ רַחֲמִים בִּתְפִלָּתוֹ. וְאוֹמֵר עֲנֵנוּ וְכוּ' בְּכָל תְּפִלָּה שֶׁמִּתְפַּלֵּל. וְלֹא יִתְעַנֶּה בְּשַׁבָּתוֹת וְלֹא בְּמוֹעֲדוֹת וְלֹא בְּרָאשֵׁי חֳדָשִׁים וְלֹא בַּחֲנֻכָּה וּפוּרִים:","כָּל תַּעֲנִית שֶׁלֹּא קִבְּלָהּ עָלָיו הַיָּחִיד מִבְּעוֹד יוֹם אֵינוֹ תַּעֲנִית. כֵּיצַד מְקַבְּלָהּ. כְּשֶׁיִּתְפַּלֵּל תְּפִלַּת מִנְחָה אוֹמֵר אַחַר הַתְּפִלָּה מָחָר אֱהֵא בְּתַעֲנִית וְגוֹמֵר בְּלִבּוֹ לְהִתְעַנּוֹת לְמָחָר. וְאַף עַל פִּי שֶׁהוּא אוֹכֵל בַּלַּיְלָה לֹא הִפְסִיד כְּלוּם. וְכֵן אִם גָּמַר בְּלִבּוֹ וְקִבֵּל עָלָיו לְהִתְעַנּוֹת שְׁלֹשָׁה אוֹ אַרְבָּעָה יָמִים זֶה אַחַר זֶה אַף עַל פִּי שֶׁהוּא אוֹכֵל כָּל לַיְלָה וְלַיְלָה לֹא הִפְסִיד תַּעֲנִיתוֹ. וְאֵינוֹ צָרִיךְ כַּוָּנָה לְכָל יוֹם וָיוֹם מִבְּעוֹדוֹ:","קִבֵּל עָלָיו מִבְּעוֹד יוֹם לְהִתְעַנּוֹת לְמָחָר בִּלְבַד וְהִתְעַנָּה. וּבַלַּיְלָה נִמְלַךְ לְהִתְעַנּוֹת בְּיוֹם שֵׁנִי. אַף עַל פִּי שֶׁלָּן בְּתַעֲנִיתוֹ אֵינָהּ תַּעֲנִית מִפְּנֵי שֶׁלֹּא קִבְּלָהּ עָלָיו מִבְּעוֹד יוֹם. וְאֵין צָרִיךְ לוֹמַר שֶׁהָיָה אוֹכֵל וְשׁוֹתֶה בַּלַּיְלָה וְהִשְׁכִּים בַּבֹּקֶר וְנִמְלַךְ לְהִתְעַנּוֹת שֶׁאֵין זוֹ תַּעֲנִית כְּלָל:","הָרוֹאֶה חֲלוֹם רַע צָרִיךְ לְהִתְעַנּוֹת לְמָחָר. כְּדֵי שֶׁיָּשׁוּב וְיֵעוֹר בְּמַעֲשָׂיו וִיחַפֵּשׂ בָּהֶן וְיַחֲזֹר בִּתְשׁוּבָה. וּמִתְעַנֶּה וַאֲפִלּוּ בְּשַׁבָּת. וּמִתְפַּלֵּל עֲנֵנוּ בְּכָל תְּפִלָּה אַף עַל פִּי שֶׁלֹּא קִבְּלָהּ מִבְּעוֹד יוֹם. וְהַמִּתְעַנֶּה בְּשַׁבָּת מִתְעַנֶּה יוֹם אַחֵר מִפְּנֵי שֶׁבִּטֵּל עֹנֶג שַׁבָּת:","מִתְעַנֶּה אָדָם שָׁעוֹת וְהוּא שֶׁלֹּא יֹאכַל כְּלוּם שְׁאָר הַיּוֹם. כֵּיצַד. הֲרֵי שֶׁהָיָה טָרוּד בַּחֲפָצָיו ומִתְעַסֵּק בִּצְרָכָיו וְלֹא אָכַל עַד חֲצוֹת אוֹ עַד תֵּשַׁע שָׁעוֹת וְנִמְלַךְ לְהִתְעַנּוֹת בַּשָּׁעוֹת שֶׁנִּשְׁאֲרוּ מִן הַיּוֹם. הֲרֵי זֶה מִתְעַנֶּה אוֹתָן שָׁעוֹת וּמִתְפַּלֵּל בָּהֶן עֲנֵנוּ. שֶׁהֲרֵי קִבֵּל עָלָיו הַתַּעֲנִית קֹדֶם שְׁעוֹת הַתַּעֲנִית. וְכֵן אִם אָכַל וְשָׁתָה וְאַחַר כָּךְ הִתְחִיל לְהִתְעַנּוֹת שְׁאָר הַיּוֹם הֲרֵי זֶה תַּעֲנִית שָׁעוֹת:","כָּל הַשָּׁרוּי בְּתַעֲנִית. בֵּין שֶׁהָיָה מִתְעַנֶּה עַל צָרָתוֹ אוֹ עַל חֲלוֹמוֹ בֵּין שֶׁהָיָה מִתְעַנֶּה עִם הַצִּבּוּר עַל צָרָתָם. הֲרֵי זֶה לֹא יִנְהֹג עִדּוּנִין בְּעַצְמוֹ וְלֹא יָקֵל רֹאשׁוֹ וְלֹא יִהְיֶה שָׂמֵחַ וְטוֹב לֵב אֶלָּא דּוֹאֵג וְאוֹנֵן כָּעִנְיָן שֶׁנֶּאֱמַר (איכה ג לט) \"מַה יִּתְאוֹנֵן אָדָם חָי גֶּבֶר עַל חֲטָאָיו\". וּמֻתָּר לוֹ לִטְעֹם אֶת הַתַּבְשִׁיל וַאֲפִלּוּ בִּכְדֵי רְבִיעִית וְהוּא שֶׁלֹּא יִבְלַע אֶלָּא טוֹעֵם וּפוֹלֵט. שָׁכַח וְאָכַל מַשְׁלִים תַּעֲנִיתוֹ:","יָחִיד שֶׁהָיָה מִתְעַנֶּה עַל הַחוֹלֶה וְנִתְרַפֵּא. עַל צָרָה וְעָבְרָה. הֲרֵי זֶה מַשְׁלִים תַּעֲנִיתוֹ. הַהוֹלֵךְ מִמָּקוֹם שֶׁמִּתְעַנִּין לְמָקוֹם שֶׁאֵין מִתְעַנִּין הֲרֵי זֶה מִתְעַנֶּה וּמַשְׁלִים תַּעֲנִיתוֹ. הָלַךְ מִמָּקוֹם שֶׁאֵין מִתְעַנִּין לְמָקוֹם שֶׁמִּתְעַנִּין הֲרֵי זֶה מִתְעַנֶּה עִמָּהֶן. שָׁכַח וְאָכַל וְשָׁתָה אַל יִתְרָאֶה בִּפְנֵיהֶם וְאַל יִנְהֹג עִדּוּנִין בְּעַצְמוֹ:","צִבּוּר שֶׁהָיוּ מִתְעַנִּין עַל הַגְּשָׁמִים וְיָרְדוּ לָהֶן גְּשָׁמִים. אִם קֹדֶם חֲצוֹת יָרְדוּ לֹא יַשְׁלִימוּ אֶלָּא אוֹכְלִין וְשׁוֹתִין וּמִתְכַּנְּסִין וְקוֹרְאִין הַלֵּל הַגָּדוֹל. שֶׁאֵין אוֹמְרִין הַלֵּל הַגָּדוֹל אֶלָּא בְּנֶפֶשׁ שְׂבֵעָה וְכֶרֶס מְלֵאָה. וְאִם אַחַר חֲצוֹת הוֹאִיל וְעָבַר רֹב הַיּוֹם בִּקְדֻשָּׁה יַשְׁלִימוּ תַּעֲנִיתָן. וְכֵן אִם הָיוּ מִתְעַנִּין עַל צָרָה וְעָבְרָה אוֹ עַל גְּזֵרָה וּבָטְלָה. אִם קֹדֶם חֲצוֹת לֹא יַשְׁלִימוּ וְאִם אַחַר חֲצוֹת יַשְׁלִימוּ:","בְּכָל יוֹם תַּעֲנִית שֶׁגּוֹזְרִין עַל הַצִּבּוּר מִפְּנֵי הַצָּרוֹת. בֵּית דִּין וְהַזְּקֵנִים יוֹשְׁבִין בְּבֵית הַכְּנֶסֶת וּבוֹדְקִים עַל מַעֲשֵׂי אַנְשֵׁי הָעִיר מֵאַחַר תְּפִלַּת שַׁחֲרִית עַד חֲצוֹת הַיּוֹם. וּמְסִירִין הַמִּכְשׁוֹלוֹת שֶׁל עֲבֵרוֹת. וּמַזְהִירִין וְדוֹרְשִׁין וְחוֹקְרִין עַל בַּעֲלֵי חָמָס וַעֲבֵרוֹת וּמַפְרִישִׁין אוֹתָן. וְעַל בַּעֲלֵי זְרוֹעַ וּמַשְׁפִּילִין אוֹתָן. וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. וּמֵחֲצִי הַיּוֹם וְלָעֶרֶב רְבִיעַ הַיּוֹם קוֹרְאִין בִּבְרָכוֹת וּקְלָלוֹת שֶׁבַּתּוֹרָה שֶׁנֶּאֱמַר (משלי ג יא) \"מוּסַר ה' בְּנִי אַל תִּמְאָס וְאַל תָּקֹץ בְּתוֹכַחְתּוֹ\". וּמַפְטִירִין בַּנָּבִיא בְּתוֹכָחוֹת מֵעִנְיַן הַצָּרָה. וּרְבִיעַ הַיּוֹם הָאַחֲרוֹן מִתְפַּלְּלִים מִנְחָה וּמִתְחַנְּנִים וְזוֹעֲקִים וּמִתְוַדִּים כְּפִי כֹּחָם:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 2":["מִצְוַת עֲשֵׂה לְהָבִיא בִּכּוּרִים לַמִּקְדָּשׁ. וְאֵינָם נוֹהֲגִין אֶלָּא בִּפְנֵי הַבַּיִת וּבְאֶרֶץ יִשְׂרָאֵל בִּלְבַד שֶׁנֶּאֱמַר (שמות כג יט) (שמות לד כו) \"רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ תָּבִיא בֵּית ה' אֱלֹהֶיךָ\". וּמְבִיאִין בִּכּוּרִים שֶׁל דִּבְרֵיהֶם מֵעָרֵי סִיחוֹן וְעוֹג וּמִסּוּרְיָא. שֶׁהַקּוֹנֶה בְּסוּרְיָא כַּקּוֹנֶה בִּירוּשָׁלַיִם. [אֲבָל עַמּוֹן וּמוֹאָב וּבָבֶל] אַף עַל פִּי שֶׁהֵן חַיָּבִין בִּתְרוּמָה וּבְמַעַשְׂרוֹת מִדִּבְרֵיהֶם אֵין מְבִיאִין מֵהֶן בִּכּוּרִים. וְאִם הֵבִיא בִּכּוּרִים מִחוּץ לָאָרֶץ אֵינָן בִּכּוּרִים:","אֵין מְבִיאִין בִּכּוּרִים אֶלָּא מִשִּׁבְעַת הַמִּינִין הָאֲמוּרִים בְּשֶׁבַח הָאָרֶץ. וְהֵם הַחִטִּים וְהַשְּׂעוֹרִים וְהָעֲנָבִים וְהַתְּאֵנִים וְהָרִמּוֹנִים וְהַזֵּיתִים וְהַתְּמָרִים. וְאִם הֵבִיא חוּץ מִשִּׁבְעַת הַמִּינִין לֹא נִתְקַדְּשׁוּ:","אֵין מְבִיאִין לֹא מִתְּמָרִים שֶׁבֶּהָרִים. וְלֹא מִפֵּרוֹת שֶׁבָּעֲמָקִים. וְלֹא מִזֵּיתֵי שֶׁמֶן שֶׁאֵינָן מִן הַמֻּבְחָר. אֶלָּא מִתְּמָרִים שֶׁבָּעֲמָקִים וּמִפֵּרוֹת שֶׁבֶּהָרִים לְפִי שֶׁהֵן מִן הַמֻּבְחָר [וְאִם הֵבִיא שֶׁלֹּא מִן הַמֻּבְחָר] כְּגוֹן תְּמָרִים שֶׁבֶּהָרִים וּתְאֵנִים סוּרוֹת וּמְרֻקָּבוֹת וַעֲנָבִים מְאֻבָּקוֹת וּמְעֻשָּׁנוֹת לֹא נִתְקַדְּשׁוּ:","אֵין מְבִיאִין בִּכּוּרִים מַשְׁקִין חוּץ מִזֵּיתִים וַעֲנָבִים בִּלְבַד שֶׁנֶּאֱמַר (דברים כו ב) (דברים כו י) \"פְּרִי הָאֲדָמָה\" [וְלֹא מַשְׁקֶה]. וְאִם הֵבִיא מַשְׁקִין אֵין מְקַבְּלִין מִמֶּנּוּ:","הַקְּרוֹבִים לִירוּשָׁלַיִם מְבִיאִין תְּאֵנִים וַעֲנָבִים לַחִים. וְהָרְחוֹקִין מְבִיאִין אוֹתָן גְּרוֹגָרוֹת וְצִמּוּקִין:","אֵין מְבִיאִין בִּכּוּרִים קֹדֶם לַעֲצֶרֶת שֶׁנֶּאֱמַר (שמות כג טז) \"וְחַג הַקָּצִיר בִּכּוּרֵי מַעֲשֶׂיךָ\". וְאִם הֵבִיא אֵין מְקַבְּלִין מִמֶּנּוּ אֶלָּא יַנִּיחֵם שָׁם עַד שֶׁתָּבוֹא עֲצֶרֶת וְיִקְרָא עֲלֵיהֶן. וְכֵן אֵין מְבִיאִין בִּכּוּרִים אַחַר חֲנֻכָּה. שֶׁהַבִּכּוּרִים שֶׁבִּכְּרוּ אַחַר חֲנֻכָּה הֵן חֲשׁוּבִין מִשָּׁנָה הַבָּאָה. וְיַנִּיחֵם עַד אַחַר עֲצֶרֶת:","אֵין מְבִיאִין בִּכּוּרִים לֹא מִן הֶחָדָשׁ עַל הַיָּשָׁן וְלֹא מִן הַיָּשָׁן עַל הֶחָדָשׁ. כֵּיצַד. לֹא יָבִיא מִפֵּרוֹת שֶׁחָנְטוּ קֹדֶם חֲמִשָּׁה עָשָׂר בִּשְׁבָט עַל פֵּרוֹת שֶׁחָנְטוּ אַחַר חֲמִשָּׁה עָשָׂר בּוֹ. אֶחָד הַנָּטוּעַ וְאֶחָד הָעוֹלֶה מֵאֵלָיו שֶׁנֶּאֱמַר (במדבר יח יג) \"בִּכּוּרֵי כָּל אֲשֶׁר בְּאַרְצָם\":","הַפֵּרוֹת שֶׁל שֻׁתָּפִין חַיָּבִים בְּבִכּוּרִים שֶׁנֶּאֱמַר (במדבר יח יג) \"בִּכּוּרֵי כָּל אֲשֶׁר בְּאַרְצְךָ\" [אֲשֶׁר יָבִיאוּ]:","הַגָּדֵל בְּעָצִיץ אַף עַל פִּי שֶׁהוּא נָקוּב וְהַגָּדֵל בִּסְפִינָה אֵינוֹ מֵבִיא מִמֶּנּוּ כָּל עִקַּר שֶׁנֶּאֱמַר (במדבר יח יג) \"בְּאַרְצָם\". אֲבָל מֵבִיא מִן הַגָּדֵל בַּגַּג אוֹ בַּחֻרְבָּה:","הַנּוֹטֵעַ אִילָן בְּתוֹךְ שָׂדֵהוּ וְהִבְרִיכוֹ לְתוֹךְ שְׂדֵה חֲבֵרוֹ אוֹ לִרְשׁוּת הָרַבִּים. אוֹ שֶׁהָיָה נוֹטֵעַ בִּשְׂדֵה חֲבֵרוֹ אוֹ בִּרְשׁוּת הָרַבִּים וְהִבְרִיכוֹ בְּתוֹךְ שָׂדֵהוּ. אוֹ שֶׁהָיָה עִקָּרוֹ בְּתוֹךְ שָׂדֵהוּ וְהִבְרִיךְ קְצָתוֹ בְּתוֹךְ שָׂדֵהוּ וְדֶרֶךְ הָרַבִּים אוֹ דֶּרֶךְ הַיָּחִיד מַפְסֶקֶת בָּאֶמְצַע בֵּין הָעִקָּר וְהַצַּד הַמֻּבְרָךְ. אֵינוֹ מֵבִיא בִּכּוּרִים לֹא מִמַּה שֶּׁהוֹצִיא בִּרְשׁוּת זוֹ וְלֹא מִן הַצַּד שֶׁבִּרְשׁוּת הָאַחֲרוֹן שֶׁנֶּאֱמַר (שמות כג יט) (שמות לד כו) \"בִּכּוּרֵי אַדְמָתְךָ\" עַד שֶׁיִּהְיוּ כָּל הַגִּדּוּלִין מֵאַדְמָתְךָ:","נָתַן לוֹ חֲבֵרוֹ רְשׁוּת לְהַבְרִיךְ בְּתוֹךְ שֶׁלּוֹ אֲפִלּוּ לְשָׁעָה הֲרֵי זֶה מֵבִיא בִּכּוּרִים. וְאִם הָיָה הָאִילָן סָמוּךְ לְמֵצַר חֲבֵרוֹ אוֹ נוֹטֶה לִשְׂדֵה חֲבֵרוֹ אַף עַל פִּי שֶׁחַיָּב לְהַרְחִיק הֲרֵי זֶה מֵבִיא מִמֶּנּוּ וְקוֹרֵא שֶׁעַל מְנָת כֵּן הִנְחִיל יְהוֹשֻׁעַ אֶת הָאָרֶץ:","הָאֲרִיסִין וְהַחֲכִירִין וּבַעֲלֵי זְרוֹעַ שֶׁאוֹנְסִין אֶת הַבְּעָלִים וְלוֹקְחִין מֵהֶן אַרְצוֹתָם בְּפָחוֹת וְהַגַּזְלָנִין אֵינָן מְבִיאִין בִּכּוּרִים. וַאֲפִלּוּ נִתְיָאֲשׁוּ הַבְּעָלִים שֶׁנֶּאֱמַר (שמות כג יט) (שמות לד כו) \"בִּכּוּרֵי אַדְמָתְךָ\":","הַקּוֹנֶה אִילָן בְּתוֹךְ שְׂדֵה חֲבֵרוֹ אֵינוֹ מֵבִיא לְפִי שֶׁאֵין לוֹ קַרְקַע. שְׁלֹשָׁה יֵשׁ לוֹ קַרְקַע וְאַף עַל פִּי שֶׁאֵין לוֹ אֶלָּא אִילָנוֹת בִּלְבַד הֲרֵי הוּא כְּמִי שֶׁקָּנָה קַרְקַע. קָנָה אִילָן אֶחָד וְקַרְקָעוֹ הֲרֵי זֶה מֵבִיא:","הַלּוֹקֵחַ פֵּרוֹת תְּלוּשִׁין וְלָקַח הַקַּרְקַע הֲרֵי זֶה מֵבִיא בִּכּוּרִים שֶׁהֲרֵי יֵשׁ לוֹ קַרְקַע וּפֵרוֹתֶיהָ. מָכַר לוֹ פֵּרוֹת חוּץ מִן הַקַּרְקַע אֲפִלּוּ מְחֻבָּרִים. מוֹכֵר אֵינוֹ מֵבִיא שֶׁהֲרֵי אֵין לוֹ פֵּרוֹת וְלוֹקֵחַ אֵינוֹ מֵבִיא שֶׁהֲרֵי אֵין לוֹ קַרְקַע. חָזַר הַמּוֹכֵר וְלָקַח הַפֵּרוֹת מִן הַלּוֹקֵחַ הֲרֵי זֶה מֵבִיא שֶׁהֲרֵי יֵשׁ לוֹ קַרְקַע וּפֵרוֹתֶיהָ:","הַמּוֹכֵר שָׂדֵהוּ לְעַכּוּ\"ם וְחָזַר וּלְקָחָהּ מִמֶּנּוּ הֲרֵי זֶה מֵבִיא מִמֶּנָּה בִּכּוּרִים מִן הַתּוֹרָה. שֶׁאֵינָהּ נִפְקַעַת מִן הַמִּצְוָה בְּקִנְיַן הָעַכּוּ\"ם כְּמוֹ שֶׁבֵּאַרְנוּ:","אֲשֵׁרָה שֶׁבִּטְּלָהּ אֵין מְבִיאִין מִמֶּנָּה בִּכּוּרִים שֶׁהַבִּכּוּרִים כְּקָדְשֵׁי מִקְדָּשׁ הֵן:","הַבִּכּוּרִים אֵין לָהֶם שִׁעוּר מִן הַתּוֹרָה אֲבָל מִדִּבְרֵיהֶם צָרִיךְ לְהַפְרִישׁ אֶחָד מִשִּׁשִּׁים. וְהָרוֹצֶה לַעֲשׂוֹת כָּל שָׂדֵהוּ בִּכּוּרִים עוֹשֵׂהוּ:","הִפְרִישׁ בִּכּוּרָיו וְחָזַר וְהוֹסִיף עֲלֵיהֶן אוֹ עִטְּרָן הֲרֵי הַתּוֹסֶפֶת כְּבִכּוּרִים. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֵבִיא מֵאֶרֶץ יִשְׂרָאֵל. אֲבָל אִם הֵבִיא מֵעֵבֶר הַיַּרְדֵּן אוֹ מִסּוּרְיָא אֵינָהּ כְּבִכּוּרִים. וְאַף עַל פִּי שֶׁאֵינָהּ כְּבִכּוּרִים אֵינָהּ נֶאֱכֶלֶת אֶלָּא בְּטָהֳרָה. וְאֵין מְעַטְּרִין אֶת הַבִּכּוּרִים בְּכָל מָקוֹם אֶלָּא מִשִּׁבְעַת הַמִּינִים:","כֵּיצַד מַפְרִישִׁין הַבִּכּוּרִים. יוֹרֵד אָדָם לְתוֹךְ שָׂדֵהוּ וְרוֹאֶה תְּאֵנָה שֶׁבִּכְּרָה אֶשְׁכּוֹל עֲנָבִים שֶׁבִּכְּרוּ רִמּוֹן שֶׁבִּכֵּר קוֹשְׁרָן בְּגֶמִי וְאוֹמֵר הֲרֵי אֵלּוּ בִּכּוּרִים. וְהֵם נַעֲשִׂים בִּכּוּרִים בִּמְחֻבָּר מִשֶּׁקָּרָא לָהֶן שֵׁם. וְאַף עַל פִּי שֶׁעֲדַיִן לֹא בָּשְׁלוּ כָּל צָרְכָּן. וּמִשֶּׁיִּגָּמְרוּ וְיִתְלְשֵׁם מִן הַקַּרְקַע אֵינוֹ צָרִיךְ לַחֲזֹר וְלִקְרוֹת לָהֶם שֵׁם. לֹא הִפְרִישָׁן בִּמְחֻבָּר וְלֹא קָרָא לָהֶם שֵׁם וּתְלָשָׁם הֲרֵי זֶה מַפְרִישָׁם אַחַר שֶׁנִּתְלְשׁוּ. וְאִם נִטְמְאוּ הַפֵּרוֹת כֻּלָּן אֵינוֹ מַפְרִישׁ בִּכּוּרִים בְּטֻמְאָה. אֶלָּא מַפְרִישׁ מִן הַטָּהוֹר עַל הַטָּמֵא לְכַתְּחִלָּה. וְאִם אֵין לוֹ פֵּרוֹת אֲחֵרוֹת לְהַפְרִישׁ מֵהֶן יֵרָאֶה לִי שֶׁאֵינוֹ מַפְרִישׁ בְּטֻמְאָה שֶׁאֵין מַפְרִישִׁין לְאִבּוּד. וְכֵן יֵרָאֶה לִי שֶׁהַבִּכּוּרִים שֶׁנִּטְמְאוּ אֵינוֹ מַסִּיק בָּהֶן הַתַּנּוּר כִּתְרוּמָה טְמֵאָה מִפְּנֵי שֶׁהֵן כְּקָדְשֵׁי מִקְדָּשׁ:","הַמַּפְרִישׁ בִּכּוּרָיו וְנָמַקּוּ אוֹ נִבְזְזוּ אוֹ אָבְדוּ אוֹ שֶׁנִּגְנְבוּ אוֹ שֶׁנִּטְמְאוּ חַיָּב לְהַפְרִישׁ אֲחֵרִים תַּחְתֵּיהֶם שֶׁנֶּאֱמַר (שמות כג יט) (שמות לד כו) \"תָּבִיא בֵּית ה' אֱלֹהֶיךָ\" מְלַמֵּד שֶׁהוּא חַיָּב בְּאַחְרָיוּתָן עַד שֶׁיְּבִיאֵם לְהַר הַבַּיִת:","הַמַּפְרִישׁ בִּכּוּרָיו לְהַעֲלוֹתָן בְּיָדוֹ לִירוּשָׁלַיִם לֹא יִשְׁלָחֵם בְּיַד שָׁלִיחַ. וְאִם לִקְּטָן מִתְּחִלָּה עַל מְנָת לְשַׁלְּחָם בְּיַד שָׁלִיחַ הֲרֵי זֶה מֻתָּר לְשַׁלְּחָם:"],"Mishneh Torah, Firstlings 5":["רָחֵל שֶׁלֹּא בִּכְּרָה וְיָלְדָה שְׁנֵי זְכָרִים. אֲפִלּוּ יָצְאוּ שְׁנֵי רָאשֵׁיהֶן כְּאֶחָד אִי אֶפְשָׁר שֶׁלֹּא קָדַם אֶחָד. הוֹאִיל וְאֵין יָדוּעַ אֵי זֶה מֵהֶם יָצָא רִאשׁוֹן הַכֹּהֵן נוֹטֵל אֶת הַכָּחוּשׁ וְהַשֵּׁנִי סְפֵק בְּכוֹר. מֵת אֶחָד מֵהֶן אֵין לַכֹּהֵן כְּלוּם שֶׁזֶּה הַחַי סָפֵק הוּא וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְכֵן אִם יָלְדָה זָכָר וּנְקֵבָה הֲרֵי הַזָּכָר סָפֵק שֶׁמָּא הַנְּקֵבָה יָצָאת תְּחִלָּה לְפִיכָךְ אֵין לַכֹּהֵן כְּלוּם שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","שְׁתֵּי רְחֵלוֹת שֶׁלֹּא בִּכְּרוּ וְיָלְדוּ שְׁנֵי זְכָרִים. שְׁנֵיהֶן לַכֹּהֵן. זָכָר וּנְקֵבָה הַזָּכָר לַכֹּהֵן. שְׁנֵי זְכָרִים וּנְקֵבָה הַכֹּהֵן נוֹטֵל אֶת הַכָּחוּשׁ וְהַשֵּׁנִי סְפֵק בְּכוֹר. וְאִם מֵת אֶחָד מֵהֶן אֵין לַכֹּהֵן כְּלוּם. שֶׁזֶּה הַזָּכָר הַחַי סְפֵק בְּכוֹר הוּא וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. יָלְדוּ שְׁתֵּי נְקֵבוֹת וְזָכָר אוֹ שְׁנֵי זְכָרִים וּשְׁתֵּי נְקֵבוֹת הֲרֵי הַזְּכָרִים סְפֵק בְּכוֹר. שֶׁאֲנִי אוֹמֵר שֶׁמָּא הַנְּקֵבָה נוֹלְדָה תְּחִלָּה וְאַחַר כָּךְ הַזָּכָר. לְפִיכָךְ אֵין כָּאן לַכֹּהֵן כְּלוּם שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. אַחַת בִּכְּרָה וְאַחַת שֶׁלֹּא בִּכְּרָה וְיָלְדוּ לוֹ שְׁנֵי זְכָרִים. אֶחָד לוֹ וְאֶחָד לַכֹּהֵן וְכָל אֶחָד מֵהֶן סְפֵק בְּכוֹר וְהַכֹּהֵן נוֹטֵל אֶת הַכָּחוּשׁ. מֵת אֶחָד מֵהֶן אֵין כָּאן לַכֹּהֵן כְּלוּם שֶׁזֶּה הַחַי סָפֵק הוּא. וְכֵן אִם יָלְדוּ זָכָר וּנְקֵבָה אֵין כָּאן לַכֹּהֵן כְּלוּם שֶׁזֶּה הַזָּכָר סְפֵק בְּכוֹר הוּא:","כָּל בְּכוֹר שֶׁהוּא סָפֵק דִּינוֹ שֶׁיִּרְעֶה עַד שֶׁיִּפּל בּוֹ מוּם וְיֵאָכֵל לִבְעָלָיו. וְאִם תְּפָשׂוֹ הַכֹּהֵן אֵין מוֹצִיאִין אוֹתוֹ מִיָּדוֹ וְאוֹכֵל אוֹתוֹ בְּמוּמוֹ. אֲבָל אֵינוֹ מַקְרִיבוֹ שֶׁאֵין מַקְרִיב לְעוֹלָם אֶלָּא בְּכוֹר וַדַּאי שֶׁמָּא יִשְׁחֹט חֻלִּין בָּעֲזָרָה:","מִי שֶׁהָיָה בְּעֶדְרוֹ מְבַכְּרוֹת וְשֶׁאֵינָן מְבַכְּרוֹת וְיָלְדוּ וְאֵין שָׁם אָדָם וְנִכְנַס וּמָצָא אֶת הַמְבַכְּרוֹת מֵינִיקוֹת נְקֵבוֹת וְאֶת שֶׁאֵינָן מְבַכְּרוֹת מֵינִיקוֹת זְכָרִים. אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא בְּנָהּ שֶׁל זוֹ בָּא לוֹ אֵצֶל זוֹ וּבְנָהּ שֶׁל זוֹ בָּא לוֹ אֵצֶל זוֹ אֶלָּא הֲרֵי הַדָּבָר בְּחֶזְקָתוֹ שֶׁכָּל אַחַת מֵינִיקָה בְּנָהּ:","שְׁנַיִם שֶׁהִפְקִידוּ שְׁנֵי זְכָרִים אֵצֶל הָרוֹעֶה הָאֶחָד בְּכוֹר וְהַשֵּׁנִי פָּשׁוּט וּמֵת אֶחָד מֵהֶן. מַנִּיחַ הָרוֹעֶה הַשֵּׁנִי בֵּינֵיהֶן וּמִסְתַּלֵּק וַהֲרֵי הוּא סְפֵק בְּכוֹר וּשְׁנֵיהֶן חוֹלְקִין אוֹתוֹ שֶׁאֵין אֶחָד מֵהֶן מַכִּיר אֶת שֶׁלּוֹ:","הִפְקִיד בְּכוֹר אֵצֶל בַּעַל הַבַּיִת וְהִנִּיחוֹ בַּעַל הַבַּיִת עִם פָּשׁוּט שֶׁלּוֹ וּמֵת אֶחָד מֵהֶן וְאֵין יָדוּעַ אֵיזֶהוּ. הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וַהֲרֵי הוּא סְפֵק בְּכוֹר. וַאֲפִלּוּ רוֹעֶה כֹּהֵן שֶׁהִנִּיחַ בְּכוֹרוֹ בַּחֲצַר בַּעַל הַבַּיִת עִם פָּשׁוּט שֶׁל בַּעַל הַבַּיִת וּמֵת אֶחָד מֵהֶן הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְאֵין מוֹצִיאִין מֵחֲצַר בַּעַל הַבַּיִת אֶלָּא בִּרְאָיָה. שֶׁהֲרֵי מִדַּעַת בַּעַל הַבְּכוֹר הִנִּיחוּ עִמּוֹ הַפָּשׁוּט שֶׁל בַּעַל הַבַּיִת:","לֹא נֶחְשְׁדוּ יִשְׂרָאֵל עַל הַבְּכוֹרוֹת לְפִיכָךְ נֶאֱמָן הַיִּשְׂרָאֵל לוֹמַר זֶה סְפֵק בְּכוֹר הוּא וְרוֹאִין לוֹ מוּמוֹ וְאוֹכֵל אוֹתוֹ בְּמוּמוֹ:","כָּל הַקָּדָשִׁים שֶׁקָּדַם לָהֶם מוּם קָבוּעַ לְהֶקְדֵּשָׁן וְנִפְדּוּ חַיָּבִין בִּבְכוֹרָה. וְאִם קָדַם מוּם עוֹבֵר לְהֶקְדֵּשָׁן אוֹ שֶׁהִקְדִּישָׁן תְּמִימִים וְאַחַר כָּךְ נוֹלַד לָהֶם מוּם קָבוּעַ וְנִפְדּוּ פְּטוּרִין מִן הַבְּכוֹרָה. שֶׁהֲרֵי לֹא יָצְאוּ לְחֻלִּין לְכָל דָּבָר מִפְּנֵי שֶׁהֵן אֲסוּרִין בְּגִזָּה וַעֲבוֹדָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מְעִילָה:","הַלּוֹקֵחַ בְּהֵמָה מִמְּעוֹת מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם חַיֶּבֶת בִּבְכוֹרָה. אֲבָל הַלּוֹקֵחַ בְּהֵמָה מִפֵּרוֹת שְׁבִיעִית הֲרֵי זוֹ פְּטוּרָה מִן הַבְּכוֹרָה לְפִי שֶׁאֵינוֹ רַשַּׁאי לַעֲשׂוֹת סְחוֹרָה בְּפֵרוֹת שְׁבִיעִית שֶׁהֲרֵי נֶאֱמַר בָּהּ (ויקרא כה ו) \"לְאָכְלָהּ\" לְאָכְלָהּ וְלֹא לִסְחוֹרָה. וְאִם תִּהְיֶה חַיֶּבֶת בִּבְכוֹרָה הֲרֵי זֶה מִשְׂתַּכֵּר בִּבְכוֹר שֶׁהֲרֵי יָצָא מִתּוֹרַת פֵּרוֹת שְׁבִיעִית. וּכְבָר בֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת שֶׁאָסוּר לַעֲשׂוֹת סְחוֹרָה בִּדְבָרִים הָאֲסוּרִים בַּאֲכִילָה וְכֵן בֵּאַרְנוּ בִּתְרוּמוֹת שֶׁאָסוּר לַעֲשׂוֹת סְחוֹרָה בִּתְרוּמוֹת וְכֵן אָסוּר לַעֲשׂוֹת סְחוֹרָה בִּבְכוֹרוֹת אַף עַל פִּי שֶׁמֻּתָּר לְמָכְרָן עַל דֶּרֶךְ שֶׁבֵּאַרְנוּ:","לָקַח בְּכוֹר לְמִשְׁתֵּה בְּנוֹ אוֹ לָרֶגֶל וְלֹא צָרִיךְ לוֹ מֻתָּר לְמָכְרוֹ:","אֵין שָׁמִין בְּכוֹרוֹת תְּמִימִים לְיִשְׂרָאֵל אֲבָל שָׁמִין לָהֶן בְּכוֹרוֹת בַּעֲלֵי מוּמִין. וְשָׁמִין בְּכוֹרוֹת תְּמִימִים לַכֹּהֲנִים בַּזְּמַן הַזֶּה שֶׁהֵן עוֹמְדִין לְהֵאָכֵל בְּמוּמָן. וְאֵין צָרִיךְ לוֹמַר שֶׁשָּׁמִין לָהֶן בַּעֲלֵי מוּמִים:"],"Mishneh Torah, Forbidden Foods 17":["קְדֵרָה שֶׁל חֶרֶס שֶׁנּתִבַּשֵּׁל בָּהּ בְּשַׂר נְבֵלָה אוֹ בְּשַׂר שְׁקָצִים וּרְמָשִׂים לֹא יְבַשֵּׁל בָּהּ בְּשַׂר שְׁחוּטָה בְּאוֹתוֹ הַיּוֹם. וְאִם בִּשֵּׁל בָּהּ מִין בָּשָׂר הַתַּבְשִׁיל אָסוּר. בִּשֵּׁל בָּהּ מִין אַחֵר בְּנוֹתֵן טַעַם:","וְלֹא אָסְרָה תּוֹרָה אֶלָּא קְדֵרָה בַּת יוֹמָהּ בִּלְבַד הוֹאִיל וַעֲדַיִן לֹא נִפְגַּם הַשֻּׁמָּן שֶׁנִּבְלָע בַּקְּדֵרָה. וּמִדִּבְרֵי סוֹפְרִים לֹא יְבַשֵּׁל בָּהּ לְעוֹלָם. לְפִיכָךְ אֵין לוֹקְחִין כְּלֵי חֶרֶס יְשָׁנִים מִן הָעַכּוּ\"ם שֶׁנִּשְׁתַּמְּשׁוּ בָּהֶן בְּחַמִּין כְּגוֹן קְדֵרוֹת וּקְעָרוֹת לְעוֹלָם. וַאֲפִלּוּ הָיוּ שׁוֹעִין בַּאֲבָר. וְאִם לָקַח וּבִשֵּׁל בָּהֶן מִיּוֹם שֵׁנִי וָהָלְאָה הַתַּבְשִׁיל מֻתָּר:","הַלּוֹקֵחַ כְּלֵי תַּשְׁמִישׁ סְעֻדָּה מִן הָעַכּוּ\"ם מִכְּלֵי מַתָּכוֹת וּכְלֵי זְכוּכִית. דְּבָרִים שֶׁלֹּא נִשְׁתַּמֵּשׁ בָּהֶן כָּל עִקָּר מַטְבִּילָן בְּמֵי מִקְוֶה וְאַחַר כָּךְ יִהְיוּ מֻתָּרִין לֶאֱכֹל בָּהֶן וְלִשְׁתּוֹת. וּדְבָרִים שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן עַל יְדֵי צוֹנֵן כְּגוֹן כּוֹסוֹת וּצְלוֹחִיּוֹת וְקִיתוֹנִיּוֹת מְדִיחָן וּמַטְבִּילָן וְהֵן מֻתָּרוֹת. וּדְבָרִים שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן עַל יְדֵי חַמִּין כְּגוֹן יוֹרוֹת וְקֻמְקְמוֹסִין וּמְחַמְּמֵי חַמִּין מַגְעִילָן וּמַטְבִּילָן וְהֵן מֻתָּרִין. וּדְבָרִים שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן עַל יְדֵי הָאוּר כְּגוֹן שִׁפּוּדִין וְאַסְכְּלָאוֹת מְלַבְּנָן בָּאוּר עַד שֶׁתִּנְשַׁר קְלִפָּתָן וּמַטְבִּילָן וְהֵן מֻתָּרִין:","כֵּיצַד מַגְעִילָן. נוֹתֵן יוֹרָה קְטַנָּה לְתוֹךְ יוֹרָה גְּדוֹלָה וּמְמַלֵּא עָלֶיהָ מַיִם עַד שֶׁיָּצוּפוּ עַל הַקְּטַנָּה וּמַרְתִּיחָהּ יָפֶה יָפֶה. וְאִם הָיְתָה יוֹרָה גְּדוֹלָה מַקִּיף עַל שְׂפָתָהּ בָּצֵק אוֹ טִיט וּמְמַלֵּא מַיִם עַד שֶׁיָּצוּפוּ הַמַּיִם עַל שְׂפָתָהּ וּמַרְתִּיחַ. וְכֻלָּן שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן עַד שֶׁלֹּא הִרְתִּיחַ אוֹ עַד שֶׁלֹּא הֵדִיחַ וְעַד שֶׁלֹּא הִלְבִּין וְעַד שֶׁלֹּא הִטְבִּיל מֻתָּר. שֶׁכָּל הַשֻּׁמָּן שֶׁבָּהֶן נוֹתֵן טַעַם לִפְגָם הוּא כְּמוֹ שֶׁבֵּאַרְנוּ:","טְבִילָה זוֹ שֶׁמַּטְבִּילִין כְּלֵי הַסְּעֻדָּה הַנִּלְקָחִים מִן הָעַכּוּ\"ם וְאַחַר כָּךְ יֻתְּרוּ לַאֲכִילָה וּשְׁתִיָּה אֵינָן לְעִנְיַן טֻמְאָה וְטָהֳרָה אֶלָּא מִדִּבְרֵי סוֹפְרִים. וְרֶמֶז לָהּ (במדבר לא כג) \"כָּל דָּבָר אֲשֶׁר יָבֹא בָאֵשׁ תַּעֲבִירוּ בָאֵשׁ וְטָהֵר\" וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בְּטָהֳרָתָן מִידֵי גִּעוּלֵי עַכּוּ\"ם לֹא מִידֵי טֻמְאָה. שֶׁאֵין לְךָ טֻמְאָה עוֹלָה עַל יְדֵי הָאֵשׁ וְכָל הַטְּמֵאִים בִּטְבִילָה עוֹלִין מִטֻּמְאָתָן. וְטֻמְאַת מֵת בְּהַזָּאָה וּטְבִילָה וְאֵין שָׁם אֵשׁ כְּלָל. אֶלָּא לְעִנְיַן גִּעוּלֵי עַכּוּ\"ם. וְכֵיוָן שֶׁכָּתוּב וְטָהֵר אָמְרוּ חֲכָמִים הוֹסֵיף לוֹ טָהֳרָה אַחַר עֲבִירָתוֹ בָּאֵשׁ לְהַתִּירוֹ מִגִּעוּלֵי עַכּוּ\"ם:","לֹא חִיְּבוּ בִּטְבִילָה זוֹ אֶלָּא כְּלֵי מַתָּכוֹת שֶׁל סְעֻדָּה הַנִּלְקָחִין מִן הָעַכּוּ\"ם. אֲבָל הַשּׁוֹאֵל מִן הָעַכּוּ\"ם. אוֹ שֶׁמִּשְׁכֵּן הָעַכּוּ\"ם אֶצְלוֹ כְּלֵי מַתָּכוֹת. מֵדִיחַ אוֹ מַרְתִּיחַ אוֹ מְלַבֵּן וְאֵינוֹ צָרִיךְ לְהַטְבִּיל. וְכֵן אִם לָקַח כְּלֵי עֵץ אוֹ כְּלֵי אֲבָנִים מֵדִיחַ אוֹ מַרְתִּיחַ וְאֵינוֹ צָרִיךְ לְהַטְבִּיל. וְכֵן כְּלֵי חָרָשִׂים אֵינוֹ צָרִיךְ לְהַטְבִּיל. אֲבָל הַשּׁוֹעִין בַּאֲבָר הֲרֵי הֵן כִּכְלֵי מַתָּכוֹת וּצְרִיכִין טְבִילָה:","הַלּוֹקֵחַ סַכִּין מִן הָעַכּוּ\"ם מְלַבְּנָהּ בָּאֵשׁ אוֹ מַשְׁחִיזָהּ בָּרֵחַיִם שֶׁלָּהּ. וְאִם הָיְתָה סַכִּין יָפָה שֶׁאֵין בָּהּ פְּגִימוֹת דַּי לוֹ אִם נְעָצָהּ בְּקַרְקַע קָשָׁה עֶשֶׂר פְּעָמִים וְאוֹכֵל בָּהּ צוֹנֵן. וְאִם הָיוּ בָּהּ פְּגִימוֹת אוֹ שֶׁהָיְתָה יָפָה וְרָצָה לֶאֱכֹל בָּהּ חַמִּין אוֹ לִשְׁחֹט בָּהּ מְלַבְּנָהּ אוֹ מַשְׁחִיזָהּ כֻּלָּהּ. שָׁחַט בָּהּ קֹדֶם שֶׁיְּטַהֲרֶנָּה מֵדִיחַ מְקוֹם הַשְּׁחִיטָה. וְאִם קִלֵּף הֲרֵי זֶה מְשֻׁבָּח:","סַכִּין שֶׁשָּׁחַט בָּהּ טְרֵפָה לֹא יִשְׁחֹט בָּהּ עַד שֶׁיְּדִיחָהּ אֲפִלּוּ בְּצוֹנֵן אוֹ מְקַנְּחָהּ בִּבְלָיוֹת שֶׁל בְּגָדִים:","וְיֵשׁ שָׁם דְּבָרִים אֲחֵרִים אָסְרוּ אוֹתָן חֲכָמִים וְאַף עַל פִּי שֶׁאֵין לְאִסּוּרָן עִקָּר מִן הַתּוֹרָה גָּזְרוּ עֲלֵיהֶן כְּדֵי לְהִתְרַחֵק מִן הָעַכּוּ\"ם עַד שֶׁלֹּא יִתְעָרְבוּ בָּהֶן יִשְׂרָאֵל וְיָבוֹאוּ לִידֵי חַתְנוּת. וְאֵלּוּ הֵן. אָסְרוּ לִשְׁתּוֹת עִמָּהֶן וַאֲפִלּוּ בְּמָקוֹם שֶׁאֵין לָחוּשׁ לְיֵין נֶסֶךְ. וְאָסְרוּ לֶאֱכֹל פִּתָּן אוֹ בִּשּׁוּלֵיהֶן וַאֲפִלּוּ בְּמָקוֹם שֶׁאֵין לָחוּשׁ לְגִעוּלֵיהֶן:","כֵּיצַד. לֹא יִשְׁתֶּה אָדָם בִּמְסִבָּה שֶׁל עַכּוּ\"ם. וְאַף עַל פִּי שֶׁהוּא יַיִן מְבֻשָּׁל שֶׁאֵינוֹ נֶאֱסָר. אוֹ שֶׁהָיָה שׁוֹתֶה מִכֵּלָיו לְבַדּוֹ. וְאִם הָיָה רֹב הַמְּסִבָּה יִשְׂרָאֵל מֻתָּר. וְאֵין שׁוֹתִין שֵׁכָר שֶׁלָּהֶן שֶׁעוֹשִׂין מִן הַתְּמָרִים וְהַתְּאֵנִים וְכַיּוֹצֵא בָּהֶן. וְאֵינוֹ אָסוּר אֶלָּא בִּמְקוֹם מְכִירָתוֹ. אֲבָל אִם הֵבִיא הַשֵּׁכָר לְבֵיתוֹ וְשָׁתָהוּ שָׁם מֻתָּר שֶׁעִקַּר הַגְּזֵרָה שֶׁמָּא יִסְעֹד אֶצְלוֹ:","יֵין תַּפּוּחִים וְיֵין רִמּוֹנִים וְכַיּוֹצֵא בָּהֶן מֻתָּר לִשְׁתּוֹתָן בְּכָל מָקוֹם. דָּבָר שֶׁאֵינוֹ מָצוּי לֹא גָּזְרוּ עָלָיו. יֵין צִמּוּקִים הֲרֵי הוּא כְּיַיִן וּמִתְנַסֵּךְ:","אַף עַל פִּי שֶׁאָסְרוּ פַּת עַכּוּ\"ם. יֵשׁ מְקוֹמוֹת שֶׁמְּקִלִּין בַּדָּבָר וְלוֹקְחִין פַּת הַנַּחְתּוֹם הָעַכּוּ\"ם בְּמָקוֹם שֶׁאֵין שָׁם נַחְתּוֹם יִשְׂרָאֵל וּבַשָּׂדֶה מִפְּנֵי שֶׁהוּא שְׁעַת הַדְּחָק. אֲבָל פַּת בַּעֲלֵי בָּתִּים אֵין שָׁם מִי שֶׁמּוֹרֶה בָּהּ לְהָקֵל שֶׁעִקַּר הַגְּזֵרָה מִשּׁוּם חַתְנוּת וְאִם יֹאכַל פַּת בַּעֲלֵי בָּתִּים יָבוֹא לִסְעֹד אֶצְלָן:","הִדְלִיק הָעַכּוּ\"ם אֶת הַתַּנּוּר וְאָפָה בּוֹ יִשְׂרָאֵל. אוֹ שֶׁהִדְלִיק יִשְׂרָאֵל וְאָפָה עַכּוּ\"ם. אוֹ שֶׁהִדְלִיק הָעַכּוּ\"ם וְאָפָה הָעַכּוּ\"ם וּבָא יִשְׂרָאֵל וְנִעֵר הָאֵשׁ מְעַט אוֹ כְּבָשׁוֹ לָאֵשׁ הוֹאִיל וְנִשְׁתַּתֵּף בִּמְלֶאכֶת הַפַּת הֲרֵי זוֹ מֻתֶּרֶת. וַאֲפִלּוּ לֹא זָרַק אֶלָּא עֵץ לְתוֹךְ הַתַּנּוּר הִתִּיר כָּל הַפַּת שֶׁבּוֹ. שֶׁאֵין הַדָּבָר אֶלָּא לִהְיוֹת הֶכֵּר שֶׁהַפַּת שֶׁלָּהֶן אֲסוּרָה:","עַכּוּ\"ם שֶׁבִּשֵּׁל לָנוּ יַיִן אוֹ חָלָב אוֹ דְּבַשׁ אוֹ פְּרִישִׁין וְכַיּוֹצֵא בְּאֵלּוּ (מִכָּל) דָּבָר הַנֶּאֱכָל כְּמוֹת שֶׁהוּא חַי הֲרֵי אֵלּוּ מֻתָּרִין. וְלֹא גָּזְרוּ אֶלָּא עַל דָּבָר שֶׁאֵינוֹ נֶאֱכָל כְּמוֹת שֶׁהוּא חַי. כְּגוֹן בָּשָׂר וְדָג תָּפֵל וּבֵיצָה וִירָקוֹת. אִם בִּשְּׁלָן הָעַכּוּ\"ם מִתְּחִלָּה וְעַד סוֹף וְלֹא נִשְׁתַּתֵּף יִשְׂרָאֵל עִמּוֹ בְּבִשּׁוּלָן הֲרֵי אֵלּוּ אֲסוּרִין מִשּׁוּם בִּשּׁוּלֵי עַכּוּ\"ם:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁהוּא עוֹלֶה עַל שֻׁלְחַן מְלָכִים לֶאֱכֹל בּוֹ אֶת הַפַּת. כְּגוֹן בָּשָׂר וּבֵיצִים וְדָגִים וְכַיּוֹצֵא בָּהֶם. אֲבָל דָּבָר שֶׁאֵינוֹ עוֹלֶה עַל שֻׁלְחַן מְלָכִים לֶאֱכֹל בּוֹ אֶת הַפַּת כְּגוֹן תֻּרְמוֹסִין שֶׁשָּׁלְקוּ אוֹתָן עַכּוּ\"ם אַף עַל פִּי שֶׁאֵינָן נֶאֱכָלִין חַיִּין הֲרֵי אֵלּוּ מֻתָּרִין. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן. שֶׁעִקַּר הַגְּזֵרָה מִשּׁוּם חַתְנוּת שֶׁלֹּא יְזַמְּנוֹ הָעַכּוּ\"ם אֶצְלוֹ בַּסְּעֻדָּה. וְדָבָר שֶׁאֵינוֹ עוֹלֶה עַל שֻׁלְחַן מְלָכִים לֶאֱכֹל בּוֹ אֶת הַפַּת אֵין אָדָם מְזַמֵּן אֶת חֲבֵרוֹ עָלָיו:","וְדָגִים קְטַנִּים שֶׁמְּלָחָן יִשְׂרָאֵל אוֹ עַכּוּ\"ם הֲרֵי הֵן כְּמוֹ שֶׁנִּתְבַּשְּׁלוּ מִקְצָת בִּשּׁוּל. וְאִם צְלָאָן עַכּוּ\"ם אַחַר כֵּן מֻתָּרִין. וְכָל שֶׁבִּשְּׁלוֹ יִשְׂרָאֵל מְעַט בִּשּׁוּלוֹ בֵּין בַּתְּחִלָּה בֵּין בַּסּוֹף מֻתָּר. לְפִיכָךְ אִם הִנִּיחַ הָעַכּוּ\"ם בָּשָׂר אוֹ קְדֵרָה עַל גַּבֵּי הָאֵשׁ וְהָפַךְ יִשְׂרָאֵל בַּבָּשָׂר וְהֵגִיס בַּקְּדֵרָה אוֹ שֶׁהִנִּיחַ יִשְׂרָאֵל וְגָמַר הָעַכּוּ\"ם הֲרֵי זֶה מֻתָּר:","דָּג שֶׁמְּלָחוֹ עַכּוּ\"ם וּפֵרוֹת שֶׁעִשְּׁנָן עַד שֶׁהִכְשִׁירָן לַאֲכִילָה הֲרֵי אֵלּוּ מֻתָּרִין. מָלִיחַ אֵינוֹ כְּרוֹתֵחַ בִּגְזֵרָה זוֹ וְהַמְעֵשָּׁן אֵינוֹ כִּמְבֻשָּׁל. וְכֵן קְלָיוֹת שֶׁל עַכּוּ\"ם מֻתָּרִין וְלֹא גָּזְרוּ עֲלֵיהֶם שֶׁאֵין אָדָם מְזַמֵּן חֲבֵרוֹ עַל הַקְּלָיוֹת:","פּוֹלִין וַאֲפוּנִין וַעֲדָשִׁים וְכַיּוֹצֵא בָּהֶן שֶׁשּׁוֹלְקִין אוֹתָן הָעַכּוּ\"ם וּמוֹכְרִין אוֹתָן אֲסוּרִין מִשּׁוּם בִּשּׁוּלֵי עַכּוּ\"ם בְּמָקוֹם שֶׁעוֹלִין עַל שֻׁלְחַן מְלָכִים מִשּׁוּם פַּרְפֶּרֶת. וּמִשּׁוּם גִּעוּלֵי עַכּוּ\"ם בְּכָל מָקוֹם שֶׁמָּא יְבַשְּׁלוּ אוֹתָן עִם הַבָּשָׂר אוֹ בִּקְדֵרָה שֶׁבִּשְּׁלוּ בָּהּ בָּשָׂר. וְכֵן הַסֻּפְגָּנִין שֶׁקּוֹלִין אוֹתָן הָעַכּוּ\"ם בְּשֶׁמֶן אֲסוּרִין אַף מִשּׁוּם גִּעוּלֵי עַכּוּ\"ם:","עַכּוּ\"ם שֶׁבִּשֵּׁל וְלֹא נִתְכַּוֵּן לְבִשּׁוּל הֲרֵי זֶה מֻתָּר. כֵּיצַד. עַכּוּ\"ם שֶׁהִצִּית אוּר בַּאֲגַם כְּדֵי לְהַעֲבִיר הֶחָצִיר וְנִתְבַּשְּׁלוּ בָּהּ חֲגָבִים הֲרֵי אֵלּוּ מֻתָּרִין. וַאֲפִלּוּ בְּמָקוֹם שֶׁהֵן עוֹלִין עַל שֻׁלְחַן מְלָכִים מִשּׁוּם פַּרְפֶּרֶת. וְכֵן אִם חָרַךְ הָרֹאשׁ לְהַעֲבִיר הַשֵּׂעָר מֻתָּר לֶאֱכֹל מִן הַדִּלְדּוּלִין וּמִן רֹאשׁ אָזְנַיִם שֶׁנִּצְּלוּ בִּשְׁעַת חֲרִיכָה:","תְּמָרִים שֶׁשָּׁלְקוּ אוֹתָן עַכּוּ\"ם אִם הָיוּ מְתוּקִין מִתְּחִלָּתָן הֲרֵי אֵלּוּ מֻתָּרִין. וְאִם הָיוּ מָרִין וּמְתַקְּנִין הַבִּשּׁוּל הֲרֵי אֵלּוּ אֲסוּרִין. הָיוּ בֵּינוֹנִיִּים הֲרֵי אֵלּוּ אֲסוּרִין:","קָלִי שֶׁל עֲדָשִׁים שֶׁלָּשׁוֹ בֵּין בְּמַיִם בֵּין בְּחֹמֶץ הֲרֵי זֶה אָסוּר. אֲבָל קָלִי שֶׁל חִטִּים וּשְׂעוֹרִים שֶׁלָּשִׁין אוֹתָן בְּמַיִם הֲרֵי זֶה מֻתָּר:","שֶׁמֶן שֶׁל עַכּוּ\"ם מֻתָּר. וּמִי שֶׁאוֹסְרוֹ הֲרֵי זֶה עוֹמֵד בְּחֵטְא גָּדוֹל. מִפְּנֵי שֶׁמַּמְרֶה עַל פִּי בֵּית דִּין שֶׁהִתִּירוּהוּ. וַאֲפִלּוּ נִתְבַּשֵּׁל הַשֶּׁמֶן הֲרֵי זֶה מֻתָּר. וְאֵינוֹ נֶאֱסָר לֹא מִפְּנֵי בִּשּׁוּלֵי עַכּוּ\"ם מִפְּנֵי שֶׁנֶּאֱכָל כְּמוֹת שֶׁהוּא חַי. וְלֹא מִפְּנֵי גִּעוּלֵי עַכּוּ\"ם מִפְּנֵי שֶׁהַבָּשָׂר פּוֹגֵם אֶת הַשֶּׁמֶן וּמַסְרִיחוֹ:","וְכֵן דְּבַשׁ שֶׁל עַכּוּ\"ם שֶׁנִּתְבַּשֵּׁל וְעָשׂוּ מִמֶּנּוּ מִינֵי מְתִיקָה מֻתָּר מִטַּעַם זֶה:","כּוֹסְפָן שֶׁל עַכּוּ\"ם שֶׁהוּחַמּוּ חַמִּין בֵּין בְּיוֹרָה גְּדוֹלָה בֵּין בְּיוֹרָה קְטַנָּה מֻתָּר מִפְּנֵי שֶׁנּוֹתֵן טַעַם לִפְגָם הוּא. וְכֵן כְּבָשִׁין שֶׁאֵין דַּרְכָּן לָתֵת לְתוֹכָן חֹמֶץ אוֹ יַיִן אוֹ זֵיתִים הַכְּבוּשִׁין וַחֲגָבִים הַכְּבוּשִׁין שֶׁבָּאִין מִן הָאוֹצָר מֻתָּרִין. אֲבָל חֲגָבִים וּכְבָשִׁים שֶׁמְּזַלְּפִין עֲלֵיהֶן יַיִן אֲסוּרִין. וְכֵן אִם הָיוּ מְזַלְּפִין עֲלֵיהֶן חֹמֶץ וַאֲפִלּוּ חֹמֶץ שֵׁכָר אֲסוּרִין:","וּמִפְּנֵי מָה אָסְרוּ חֹמֶץ שֵׁכָר שֶׁל עַכּוּ\"ם מִפְּנֵי שֶׁמַּשְׁלִיכִין לְתוֹכוֹ שִׁמְרֵי יַיִן. לְפִיכָךְ הַנִּלְקָח מִן הָאוֹצָר מֻתָּר:","הַמּוּרְיָס בְּמָקוֹם שֶׁדַּרְכָּן לָתֵת לְתוֹכוֹ יַיִן אָסוּר. וְאִם הָיָה הַיַּיִן יָקָר מִן הַמּוּרְיָס מֻתָּר. וְכָזֶה מוֹרִין בְּכָל דָּבָר שֶׁחוֹשְׁשִׁין לוֹ שֶׁמָּא עֵרְבוּ בּוֹ הָעַכּוּ\"ם דָּבָר אָסוּר. שֶׁאֵין אָדָם מְעָרֵב דָּבָר הַיָּקָר בְּזוֹל שֶׁהֲרֵי מַפְסִיד. אֲבָל מְעָרֵב הַזּוֹל בְּיָקָר כְּדֵי לְהִשְׂתַּכֵּר:","קָטָן שֶׁאָכַל אֶחָד מִמַּאֲכָלוֹת אֲסוּרוֹת. אוֹ שֶׁעָשָׂה מְלָאכָה בְּשַׁבָּת. אֵין בֵּית דִּין מְצֻוִּין עָלָיו לְהַפְרִישׁוֹ לְפִי שֶׁאֵינוֹ בֶּן דַּעַת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁעָשָׂה מֵעַצְמוֹ. אֲבָל לְהַאֲכִילוֹ בְּיָדַיִם אָסוּר וַאֲפִלּוּ דְּבָרִים שֶׁאִסּוּרָן מִדִּבְרֵי סוֹפְרִים. וְכֵן אָסוּר לְהַרְגִּילוֹ בְּחִלּוּל שַׁבָּת וּמוֹעֵד וַאֲפִלּוּ בִּדְבָרִים שֶׁהֵן מִשּׁוּם שְׁבוּת:","אַף עַל פִּי שֶׁאֵין בֵּית דִּין מְצֻוִּין לְהַפְרִישׁ אֶת הַקָּטָן. מִצְוָה עַל אָבִיו לִגְעֹר בּוֹ וּלְהַפְרִישׁוֹ כְּדֵי לְחַנְּכוֹ בִּקְדֻשָּׁה. שֶׁנֶּאֱמַר (משלי כב ו) \"חֲנֹךְ לַנַּעַר עַל פִּי דַרְכּוֹ\" וְגוֹ':","אָסְרוּ חֲכָמִים מַאֲכָלוֹת וּמַשְׁקִין שֶׁנֶּפֶשׁ רֹב בְּנֵי אָדָם קִהָה מֵהֶן כְּגוֹן מַאֲכָלוֹת וּמַשְׁקִין שֶׁנִּתְעָרֵב בָּהֶן קִיא אוֹ צוֹאָה וְלֵחָה סְרוּחָה וְכַיּוֹצֵא בָּהֶן. וְכֵן אָסְרוּ חֲכָמִים לֶאֱכֹל וְלִשְׁתּוֹת בְּכֵלִים הַצּוֹאִים שֶׁנַּפְשׁוֹ שֶׁל אָדָם מִתְאוֹנֶנֶת מֵהֶם. כְּגוֹן כְּלֵי בֵּית הַכִּסֵּא וּכְלֵי זְכוּכִית שֶׁל סַפָּרִין שֶׁגּוֹרְעִין בָּהֶם אֶת הַדָּם וְכַיּוֹצֵא בָּהֶן:","וְכֵן אָסְרוּ לֶאֱכֹל בְּיָדַיִם מְסֹאָבוֹת מְזֹהָמוֹת. וְעַל גַּבֵּי כֵּלִים מְלֻכְלָכִים. שֶׁכָּל דְּבָרִים אֵלּוּ בִּכְלַל (ויקרא יא מג) \"אַל תְּשַׁקְּצוּ אֶת נַפְשֹׁתֵיכֶם\". וְהָאוֹכֵל מַאֲכָלוֹת אֵלּוּ מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","וְכֵן אָסוּר לְאָדָם שֶׁיַּשְׁהֶה אֶת נְקָבָיו כְּלָל בֵּין גְּדוֹלִים בֵּין קְטַנִּים. וְכָל הַמַּשְׁהֶה נְקָבָיו הֲרֵי זֶה בִּכְלַל מְשַׁקֵּץ נַפְשׁוֹ. יֶתֶר עַל חֳלָאִים רָעִים שֶׁיָּבִיא עַל עַצְמוֹ וְיִתְחַיֵּב בְּנַפְשׁוֹ. אֶלָּא רָאוּי לוֹ לְהַרְגִּיל עַצְמוֹ בְּעִתִּים מְזֻמָּנִים כְּדֵי שֶׁלֹּא יִתְרַחֵק בִּפְנֵי בְּנֵי אָדָם וְלֹא יְשַׁקֵּץ נַפְשׁוֹ:","וְכָל הַנִּזְהָר בִּדְבָרִים אֵלּוּ מֵבִיא קְדֻשָּׁה וְטָהֳרָה יְתֵרָה לְנַפְשׁוֹ. וּמְמָרֵק נַפְשׁוֹ לְשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנֶּאֱמַר (ויקרא יא מד) \"וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי קָדוֹשׁ אָנִי\":"],"Mishneh Torah, Forbidden Intercourse 12":["יִשְׂרָאֵל שֶׁבָּעַל עַכּוּ\"ם מִשְּׁאָר הָאֻמּוֹת דֶּרֶךְ אִישׁוּת. אוֹ יִשְׂרְאֵלִית שֶׁנִּבְעֲלָה לְעַכּוּ\"ם דֶּרֶךְ אִישׁוּת הֲרֵי אֵלּוּ לוֹקִין מִן הַתּוֹרָה שֶׁנֶּאֱמַר (דברים ז ג) \"לֹא תִתְחַתֵּן בָּם בִּתְּךָ לֹא תִתֵּן לִבְנוֹ וּבִתּוֹ לֹא תִקַּח לִבְנֶךָ\". אֶחָד שִׁבְעָה עֲמָמִין וְאֶחָד כָּל אֻמּוֹת בְּאִסּוּר זֶה. וְכֵן מְפֹרָשׁ עַל יְדֵי עֶזְרָא (נחמיה י לא) \"וַאֲשֶׁר לֹא נִתֵּן בְּנֹתֵינוּ לְעַמֵּי הָאָרֶץ וְאֶת בְּנֹתֵיהֶם לֹא נִקַּח לְבָנֵינוּ\":","וְלֹא אָסְרָה תּוֹרָה אֶלָּא דֶּרֶךְ חַתְנוּת אֲבָל הַבָּא עַל הַכּוּתִית דֶּרֶךְ זְנוּת מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵי סוֹפְרִים. גְּזֵרָה שֶׁמָּא יָבוֹא לְהִתְחַתֵּן. וְאִם יִחֲדָהּ לוֹ בִּזְנוּת חַיָּב עָלֶיהָ מִשּׁוּם נִדָּה וּמִשּׁוּם שִׁפְחָה וּמִשּׁוּם כּוּתִית וּמִשּׁוּם זוֹנָה. וְאִם לֹא יִחֲדָהּ לוֹ אֶלָּא נִקְרֵאת מִקְרֶה אֵינוֹ חַיָּב אֶלָּא מִשּׁוּם כּוּתִית [ג.] וְכָל חִיּוּבִין אֵלּוּ מִדִּבְרֵיהֶן:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַבּוֹעֵל יִשְׂרָאֵל. אֲבָל כֹּהֵן הַבָּא עַל הַכּוּתִית לוֹקֶה מִן הַתּוֹרָה מִשּׁוּם זוֹנָה. וְאֶחָד זוֹנָה כּוּתִית וְאֶחָד זוֹנָה יִשְׂרְאֵלִית. וּבִבְעִילָה בִּלְבַד לוֹקֶה שֶׁהֲרֵי אֵינָהּ בַּת קִדּוּשִׁין:","כָּל הַבּוֹעֵל כּוּתִית בֵּין דֶּרֶךְ חַתְנוּת בֵּין דֶּרֶךְ זְנוּת אִם בְּעָלָהּ בְּפַרְהֶסְיָא וְהוּא שֶׁיִּבְעל לְעֵינֵי עֲשָׂרָה מִיִּשְׂרָאֵל אוֹ יֶתֶר אִם פָּגְעוּ בּוֹ קַנָּאִין וַהֲרָגוּהוּ הֲרֵי אֵלּוּ מְשֻׁבָּחִין וּזְרִיזִין [ו.] וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי הוּא. רְאָיָה לְדָבָר זֶה מַעֲשֶׂה פִּינְחָס בְּזִמְרִי:","וְאֵין הַקַּנַּאי רַשַּׁאי לִפְגֹּעַ בָּהֶן אֶלָּא בִּשְׁעַת מַעֲשֶׂה כְּזִמְרִי שֶׁנֶּאֱמַר (במדבר כה ח) \"וְאֶת הָאִשָּׁה אֶל קֳבָתָהּ\". אֲבָל אִם פֵּרַשׁ אֵין הוֹרְגִין אוֹתוֹ. וְאִם הֲרָגוֹ נֶהֱרַג עָלָיו. וְאִם בָּא הַקַּנַּאי לִטּל רְשׁוּת מִבֵּית דִּין לְהָרְגוֹ אֵין מוֹרִין לוֹ וְאַף עַל פִּי שֶׁהוּא בִּשְׁעַת מַעֲשֶׂה. וְלֹא עוֹד אֶלָּא אִם בָּא הַקַּנַּאי לַהֲרֹג אֶת הַבּוֹעֵל וְנִשְׁמַט הַבּוֹעֵל וְהָרַג הַקַּנַּאי כְּדֵי לְהַצִּיל עַצְמוֹ מִיָּדוֹ אֵין הַבּוֹעֵל נֶהֱרַג עָלָיו. וְהַבָּא עַל בַּת גֵּר תּוֹשָׁב אֵין הַקַּנָּאִין פּוֹגְעִים בּוֹ אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","לֹא פָּגְעוּ בּוֹ קַנָּאִים וְלֹא הִלְקוּהוּ בַּיִת דִּין הֲרֵי עָנְשׁוֹ מְפֹרָשׁ בְּדִבְרֵי קַבָּלָה שֶׁהוּא בְּכָרֵת שֶׁנֶּאֱמַר (מלאכי ב יא) \"כִּי חִלֵּל יְהוּדָה קֹדֶשׁ ה' אֲשֶׁר אָהֵב וּבָעַל בַּת אֵל נֵכָר\" (מלאכי ב יב) \"יַכְרֵת ה' לָאִישׁ אֲשֶׁר יַעֲשֶׂנָּה עֵר וְעֹנֶה\". אִם יִשְׂרָאֵל הוּא לֹא יִהְיֶה לוֹ עֵר בַּחֲכָמִים וְלֹא עוֹנֶה בַּתַּלְמִידִים וְאִם כֹּהֵן הוּא לֹא יִהְיֶה לוֹ מַגִּישׁ מִנְחָה לַה' צְבָאוֹת. הִנֵּה לָמַדְתָּ שֶׁהַבּוֹעֵל כּוּתִית כְּאִלּוּ נִתְחַתֵּן לְעַכּוּ\"ם שֶׁנֶּאֱמַר \"בָעַל בַּת אֵל נֵכָר וְנִקְרָא מְחַלֵּל קֹדֶשׁ ה':\"","עָוֹן זֶה אַף עַל פִּי שֶׁאֵין בּוֹ מִיתַת בֵּית דִּין אַל יְהִי קַל בְּעֵינֶיךָ. אֶלָּא יֵשׁ בּוֹ הֶפְסֵד שֶׁאֵין בְּכָל הָעֲרָיוֹת כְּמוֹתוֹ. שֶׁהַבֵּן מִן הָעֶרְוָה בְּנוֹ הוּא לְכָל דָּבָר וּבִכְלַל יִשְׂרָאֵל נֶחְשָׁב אַף עַל פִּי שֶׁהוּא מַמְזֵר וְהַבֵּן מִן הַכּוּתִית אֵינוֹ בְּנוֹ שֶׁנֶּאֱמַר (דברים ז ד) \"כִּי יָסִיר אֶת בִּנְךָ מֵאַחֲרַי\" מֵסִיר אוֹתוֹ מִלִּהְיוֹת אַחֲרֵי ה':","וְדָבָר זֶה גּוֹרֵם לְהִדָּבֵק בְּעַכּוּ\"ם שֶׁהִבְדִּילָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהֶם וְלָשׁוּב מֵאַחֲרֵי ה' וְלִמְעל בּוֹ:","עַכּוּ\"ם הַבָּא עַל בַּת יִשְׂרָאֵל אִם אֵשֶׁת אִישׁ הִיא נֶהֱרַג עָלֶיהָ וְאִם פְּנוּיָה הִיא אֵינוֹ נֶהֱרַג:","אֲבָל יִשְׂרָאֵל הַבָּא עַל הַכּוּתִית בֵּין קְטַנָּה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד בֵּין גְּדוֹלָה בֵּין פְּנוּיָה בֵּין אֵשֶׁת אִישׁ וַאֲפִלּוּ הָיָה קָטָן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד כֵּיוָן שֶׁבָּא עַל הַכּוּתִית בְּזָדוֹן הֲרֵי זוֹ נֶהֱרֶגֶת מִפְּנֵי שֶׁבָּא לְיִשְׂרָאֵל תַּקָּלָה עַל יָדֶיהָ כִּבְהֵמָה. וְדָבָר זֶה מְפֹרָשׁ בַּתּוֹרָה שֶׁנֶּאֱמַר (במדבר לא טז) \"הֵן הֵנָּה הָיוּ לִבְנֵי יִשְׂרָאֵל בִּדְבַר בִּלְעָם\" (במדבר לא יז) \"וְכָל אִשָּׁה יֹדַעַת אִישׁ לְמִשְׁכַּב זָכָר הֲרֹגוּ\":","הָעֲבָדִים שֶׁהִטְבִּילוּ אוֹתָם לְשֵׁם עַבְדוּת וְקִבְּלוּ עֲלֵיהֶם מִצְוֹת שֶׁהָעֲבָדִים חַיָּבִים בָּהֶם יָצְאוּ מִכְּלַל הָעַכּוּ\"ם וְלִכְלַל יִשְׂרָאֵל לֹא בָּאוּ. לְפִיכָךְ הַשִּׁפְחָה אֲסוּרָה לְבֶן חוֹרִין. אֶחָד שִׁפְחָתוֹ וְאֶחָד שִׁפְחַת חֲבֵרוֹ. וְהַבָּא עַל הַשִּׁפְחָה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵי סוֹפְרִים. שֶׁהֲרֵי מְפֹרָשׁ בַּתּוֹרָה שֶׁהָאָדוֹן נוֹתֵן שִׁפְחָה כְּנַעֲנִית לְעַבְדּוֹ הָעִבְרִי וְהִיא מֻתֶּרֶת לוֹ שֶׁנֶּאֱמַר (שמות כא ד) \"אִם אֲדֹנָיו יִתֶּן לוֹ אִשָּׁה\":","וְלֹא גָּזְרוּ חֲכָמִים בְּדָבָר זֶה וְלֹא חִיְּבָה תּוֹרָה מַלְקוֹת בְּשִׁפְחָה אֶלָּא אִם כֵּן הָיְתָה נֶחֱרֶפֶת לְאִישׁ כְּמוֹ שֶׁבֵּאַרְנוּ:","אַל יְהִי עָוֹן זֶה קַל בְּעֵינֶיךָ מִפְּנֵי שֶׁאֵין בּוֹ מַלְקוֹת מִן הַתּוֹרָה. שֶׁגַּם זֶה גּוֹרֵם לַבֵּן לָסוּר מֵאַחֲרֵי ה'. שֶׁהַבֵּן מִן הַשִּׁפְחָה הוּא עֶבֶד וְאֵינוֹ מִיִּשְׂרָאֵל וְנִמְצָא גּוֹרֵם לְזֶרַע הַקֹּדֶשׁ לְהִתְחַלֵּל וְלִהְיוֹתָם עֲבָדִים. הֲרֵי אֻנְקְלוֹס הַמְתַרְגֵּם כָּלַל בְּעִילַת עֶבֶד וְשִׁפְחָה בִּכְלַל (דברים כג יח) \"לֹא יִהְיֶה קָדֵשׁ\" (דברים כג יח) \"וְלֹא תִהְיֶה קְדֵשָׁה\":","הַבָּא עַל שִׁפְחָה וַאֲפִלּוּ בְּפַרְהֶסְיָא וּבִשְׁעַת עֲבֵרָה אֵין הַקַּנָּאִין פּוֹגְעִין בּוֹ. וְכֵן אִם לָקַח שִׁפְחָה דֶּרֶךְ חַתְנוּת אֵינוֹ לוֹקֶה מִן הַתּוֹרָה. שֶׁמֵּעֵת שֶׁטָּבְלָה וְקִבְּלָה מִצְוֹת יָצְתָה מִכְּלַל הָעַכּוּ\"ם:","נִתְעָרֵב וְלַד יִשְׂרְאֵלִית בִּוְלַד שִׁפְחָה הֲרֵי שְׁנֵיהֶן סָפֵק וְכָל אֶחָד מֵהֶן סְפֵק עֶבֶד וְכוֹפִין בַּעַל הַשִּׁפְחָה וּמְשַׁחְרֵר אֶת שְׁנֵיהֶם. וְאִם הָיָה הַבֵּן הַהוּא (בֶּן) הָאָדוֹן שֶׁל עֶבֶד כְּשֶׁיִּגְדְּלוּ יְשַׁחְרְרוּ זֶה אֶת זֶה וְיִהְיוּ מֻתָּרִין לָבֹא בַּקָּהָל:","הָיוּ הַתַּעֲרוֹבוֹת בָּנוֹת הֲרֵי שְׁתֵּיהֶן סְפֵק שְׁפָחוֹת וְהַבָּא עַל כָּל אַחַת מֵהֶן הַוָּלָד סְפֵק עֶבֶד. וְכֵן אִם נִתְעָרֵב וְלַד עַכּוּ\"ם בִּוְלַד יִשְׂרְאֵלִית מַטְבִּילִים אֶת שְׁנֵיהֶן לְשֵׁם גֵּרוּת וְכָל אַחַת מֵהֶן סְפֵק גִּיֹּרֶת:","כָּל הָעַכּוּ\"ם כֻּלָּם כְּשֶׁיִּתְגַּיְּרוּ וִיקַבְּלוּ עֲלֵיהֶן כָּל הַמִּצְוֹת שֶׁבַּתּוֹרָה וְהָעֲבָדִים כְּשֶׁיִּשְׁתַּחְרְרוּ הֲרֵי הֵן כְּיִשְׂרָאֵל לְכָל דָּבָר שֶׁנֶּאֱמַר (במדבר טו טו) \"הַקָּהָל חֻקָּה אַחַת יִהְיֶה לָכֶם\". וּמֻתָּרִין לְהִכָּנֵס בִּקְהַל ה' מִיָּד. וְהוּא שֶׁיִּשָּׂא הַגֵּר אוֹ הַמְשֻׁחְרָר בַּת יִשְׂרָאֵל וְיִשָּׂא הַיִּשְׂרְאֵלִי גִּיֹּרֶת וּמְשֻׁחְרֶרֶת. חוּץ מֵאַרְבָּעָה עֲמָמִין בִּלְבַד וְהֵם עַמּוֹן וּמוֹאָב וּמִצְרַיִם וֶאֱדוֹם שֶׁהָאֻמּוֹת הָאֵלּוּ כְּשֶׁיִּתְגַּיֵּר אֶחָד מֵהֶן הֲרֵי הוּא כְּיִשְׂרָאֵל לְכָל דָּבָר אֶלָּא לְעִנְיַן בִּיאָה בַּקָּהָל:","וְכֵיצַד דִּינָן. עַמּוֹן וּמוֹאָב אִסּוּרָן אִסּוּר עוֹלָם זְכָרִים וְלֹא נְקֵבוֹת שֶׁנֶּאֱמַר (דברים כג ד) \"לֹא יָבֹא עַמּוֹנִי וּמוֹאָבִי בִּקְהַל ה'\" וְגוֹ'. הֲלָכָה לְמשֶׁה מִסִּינַי שֶׁהָעַמּוֹנִי הַזָּכָר וְהַמּוֹאָבִי הַזָּכָר הוּא שֶׁאָסוּר לְעוֹלָם לִשָּׂא בַּת יִשְׂרָאֵל אֲפִלּוּ בֶּן בְּנוֹ עַד סוֹף הָעוֹלָם. אֲבָל עַמּוֹנִית וּמוֹאָבִית מֻתֶּרֶת מִיָּד כִּשְׁאָר הָאֻמּוֹת:","מִצְרִי וֶאֱדוֹמִי אֶחָד זְכָרִים וְאֶחָד נְקֵבוֹת דּוֹר רִאשׁוֹן וְדוֹר שֵׁנִי אֲסוּרִין לָבֹא בְּיִשְׂרָאֵל וְדוֹר שְׁלִישִׁי מֻתָּר שֶׁנֶּאֱמַר (דברים כג ט) \"בָּנִים אֲשֶׁר יִוָּלְדוּ לָהֶם\" וְגוֹ':","מִצְרִית מְעֻבֶּרֶת שֶׁנִּתְגַּיְּרָה בְּנָהּ שֵׁנִי. מִצְרִי שֵׁנִי שֶׁנָּשָׂא מִצְרִית רִאשׁוֹנָה אוֹ מִצְרִי רִאשׁוֹן שֶׁנָּשָׂא מִצְרִית שְׁנִיָּה הַוָּלָד שֵׁנִי שֶׁנֶּאֱמַר (דברים כג ט) \"בָּנִים אֲשֶׁר יִוָּלְדוּ לָהֶם\" הַכָּתוּב תְּלָאָן בְּלֵדָה:","גֵּר עַמּוֹנִי שֶׁנָּשָׂא מִצְרִית הַוָּלָד עַמּוֹנִי. גֵּר מִצְרִי שֶׁנָּשָׂא עַמּוֹנִית הַוָּלָד מִצְרִי. זֶה הַכְּלָל. בָּאֻמּוֹת הַלֵּךְ אַחַר הַזָּכָר. נִתְגַּיְּרוּ הַלֵּךְ אַחַר הַפָּחוּת:","מִי שֶׁנִּתְגַּיֵּר מִשִּׁבְעָה עֲמָמִין אֵינָן אֲסוּרִין מִן הַתּוֹרָה לָבוֹא בַּקָּהָל. וְהַדָּבָר יָדוּעַ שֶׁלֹּא נִתְגַּיְּרוּ מֵהֶן אֶלָּא הַגִּבְעוֹנִים וִיהוֹשֻׁעַ גָּזַר עֲלֵיהֶם שֶׁיִּהְיוּ אֲסוּרִים לָבֹא בַּקָּהָל אֶחָד זְכָרִים וְאֶחָד נְקֵבוֹת. וְלֹא אָסַר אוֹתָם אֶלָּא בִּזְמַן שֶׁיֵּשׁ מִקְדָּשׁ שֶׁנֶּאֱמַר (יהושע ט כג) \"וְחֹטְבֵי עֵצִים וְשֹׁאֲבֵי מַיִם לְבֵית אֱלֹהָי\". תָּלָה הַרְחָקָתָם בַּמִּקְדָּשׁ:","וְהֵם הַנִּקְרָאִים נְתִינִים לְפִי שֶׁנְּתָנָם לַעֲבוֹדַת הַמִּקְדָּשׁ. בָּא דָּוִד וְגָזַר עֲלֵיהֶם שֶׁלֹּא יִכָּנְסוּ בַּקָּהָל לְעוֹלָם וַאֲפִלּוּ בִּזְמַן שֶׁאֵין מִקְדָּשׁ. וְכֵן מְפֹרָשׁ בְּעֶזְרָא (עזרא ח כ) \"וּמִן הַנְּתִינִים שֶׁנָּתַן דָּוִיד וְהַשָּׂרִים לַעֲבֹדַת הַלְוִיִּם\". הָא לָמַדְתָּ שֶׁלֹּא תָּלָה אוֹתָם בַּמִּקְדָּשׁ:","וְלָמָּה גָּזַר עֲלֵיהֶם הוּא וּבֵית דִּינוֹ לְפִי שֶׁרָאָה עַזּוּת וְאַכְזָרִיּוּת שֶׁהָיְתָה בָּהֶם בְּעֵת שֶׁבִּקְּשׁוּ שִׁבְעַת בְּנֵי שָׁאוּל בְּחִיר ה' לִתְלוֹתָם וַהֲרָגוּם וְלֹא רִחֲמוּ עֲלֵיהֶם:","כְּשֶׁעָלָה סַנְחֵרִיב מֶלֶךְ אַשּׁוּר בִּלְבֵּל כָּל הָאֻמּוֹת וְעֵרְבָם זֶה בָּזֶה וְהִגְלָה אוֹתָם מִמְּקוֹמָם. וְאֵלּוּ הַמִּצְרִים שֶׁבְּאֶרֶץ מִצְרַיִם עַתָּה אֲנָשִׁים אֲחֵרִים הֵם. וְכֵן הָאֱדוֹמִים שֶׁבִּשְׂדֵה אֱדוֹם. וְהוֹאִיל וְנִתְעָרְבוּ אַרְבַּע אֻמּוֹת הָאֲסוּרִים בְּכָל אֻמּוֹת הָעוֹלָם שֶׁהֵן מֻתָּרִים הֻתַּר הַכּל. שֶׁכָּל הַפּוֹרֵשׁ מֵהֶן לְהִתְגַּיֵּר חֶזְקָתוֹ שֶׁפֵּרַשׁ מִן הָרֹב. לְפִיכָךְ כְּשֶׁיִּתְגַּיֵּר הַגֵּר בַּזְּמַן הַזֶּה בְּכָל מָקוֹם בֵּין אֱדוֹמִי בֵּין מִצְרִי בֵּין עַמּוֹנִי בֵּין מוֹאָבִי בֵּין כּוּשִׁי בֵּין שְׁאָר הָאֻמּוֹת אֶחָד הַזְּכָרִים וְאֶחָד הַנְּקֵבוֹת מֻתָּרִין לָבֹא בַּקָּהָל מִיָּד:"],"Mishneh Torah, Forbidden Intercourse 3":["הַבָא עַל אֵשֶׁת קָטָן אֲפִלּוּ הָיְתָה יְבָמָה שֶׁבָּא עָלֶיהָ בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד הֲרֵי זֶה פָּטוּר. וְכֵן הַבָּא עַל אֵשֶׁת חֵרֵשׁ וְשׁוֹטֶה וְאֵשֶׁת טֻמְטוּם וְאַנְדְּרוֹגִינוּס וְעַל הַחֵרֶשֶׁת וְעַל הַשּׁוֹטָה אֵשֶׁת הַפִּקֵּחַ וְעַל אִשָּׁה שֶׁהִיא מְקֻדֶּשֶׁת בְּסָפֵק אוֹ מְגֹרֶשֶׁת בְּסָפֵק כֻּלָּן פְּטוּרִין. וְאִם הָיוּ מְזִידִין מַכִּין אוֹתָן מַכַּת מַרְדּוּת:","הַבָּא עַל הַקְּטַנָּה אֵשֶׁת הַגָּדוֹל אִם קִדְּשָׁהּ אָבִיהָ הֲרֵי זֶה בְּחֶנֶק וְהִיא פְּטוּרָה מִכְּלוּם וְנֶאֶסְרָה עַל בַּעְלָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת סוֹטָה. וְאִם הִיא בַּת מֵאוּן מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת וְהִיא מֻתֶּרֶת לְבַעְלָהּ. וַאֲפִלּוּ הָיָה כֹּהֵן:","בַּת כֹּהֵן שֶׁזִּנְּתָה כְּשֶׁהִיא אֵשֶׁת אִישׁ. בֵּין שֶׁהָיָה בַּעְלָהּ כֹּהֵן בֵּין שֶׁהָיָה יִשְׂרָאֵל וַאֲפִלּוּ הָיָה בַּעְלָהּ מַמְזֵר אוֹ נָתִין אוֹ שְׁאָר מֵחַיָּבֵי לָאוִין הֲרֵי זוֹ בִּשְׂרֵפָה שֶׁנֶּאֱמַר (ויקרא כא ט) \"וּבַת כֹּהֵן כִּי תֵחֵל לִזְנוֹת\". וּבוֹעֲלָהּ בְּחֶנֶק. וְכֵן בַּת יִשְׂרָאֵל אֵשֶׁת כֹּהֵן בְּחֶנֶק כְּדִין כָּל אֵשֶׁת אִישׁ:","הַבָּא עַל נַעֲרָה מְאֹרָשָׂה שְׁנֵיהֶן בִּסְקִילָה. וְאֵינָן חַיָּבִין סְקִילָה עַד שֶׁתִּהְיֶה נַעֲרָה בְּתוּלָה מְאֹרָשָׂה וְהִיא בְּבֵית אָבִיהָ. הָיְתָה בּוֹגֶרֶת אוֹ שֶׁנִּכְנְסָה לְחֻפָּה אַף עַל פִּי שֶׁלֹּא נִבְעֲלָה אֲפִלּוּ מְסָרָהּ הָאָב לִשְׁלוּחֵי הַבַּעַל וְזִנְּתָה בַּדֶּרֶךְ הֲרֵי זוֹ בְּחֶנֶק:","וְהַבָּא עַל קְטַנָּה מְאֹרָשָׂה בְּבֵית אָבִיהָ הוּא בִּסְקִילָה וְהִיא פְּטוּרָה. וְנַעֲרָה מְאֹרָשָׂה בַּת כֹּהֵן שֶׁזִּנְּתָה בִּסְקִילָה:","בָּאוּ עָלֶיהָ עֲשָׂרָה וְהִיא בְּתוּלָה בִּרְשׁוּת אָבִיהָ זֶה אַחַר זֶה הֲרֵי הָרִאשׁוֹן בִּסְקִילָה וְכֻלָּן בְּחֶנֶק (בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁבָּאוּ עָלֶיהָ כְּדַרְכָּהּ אֲבָל אִם בָּאוּ עָלֶיהָ שֶׁלֹּא כְּדַרְכָּהּ עֲדַיִן הִיא בְּתוּלָה וְכֻלָּן בִּסְקִילָה):","נַעֲרָה מְאֹרָשָׂה שֶׁהָיְתָה מְשֻׁחְרֶרֶת אוֹ גִּיֹּרֶת אַף עַל פִּי שֶׁנִּשְׁתַּחְרְרָה וְנִתְגַּיְּרָה וְהִיא פְּחוּתָה מִבַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד הֲרֵי זוֹ בְּחֶנֶק כְּכָל אֵשֶׁת אִישׁ:","דִּין חָדָשׁ יֵשׁ בְּמוֹצִיא שֵׁם רַע. וּמַה הוּא הַחִדּוּשׁ. שֶׁאִם נִמְצָא הַדָּבָר אֱמֶת וּבָאוּ עֵדִים שֶׁזִּנְּתָה כְּשֶׁהָיְתָה נַעֲרָה מְאֹרָשָׂה אַף עַל פִּי שֶׁזִּנְּתָה אַחַר שֶׁיָּצְאָה מִבֵּית אָבִיהָ וַאֲפִלּוּ שֶׁזִּנְּתָה אַחַר שֶׁנִּכְנְסָה לַחֻפָּה קֹדֶם בְּעִילַת הַבַּעַל סוֹקְלִין אוֹתָהּ עַל פֶּתַח בֵּית אָבִיהָ. אֲבָל שְׁאָר נְעָרוֹת מְאֹרָסוֹת שֶׁלֹּא הָיָה לָהֶן דִּין הוֹצָאַת שֵׁם רַע שֶׁזָּנוּ מֵאַחַר שֶׁיָּצְאוּ מִבֵּית הָאָב הֲרֵי הֵן בְּחֶנֶק כְּמוֹ שֶׁבֵּאַרְנוּ. הָא לָמַדְתָּ שֶׁבְּאֵשֶׁת אִישׁ שָׁלֹשׁ מִיתוֹת. יֵשׁ אֵשֶׁת אִישׁ שֶׁהִיא בְּחֶנֶק. וְיֵשׁ אֵשֶׁת אִישׁ שֶׁהִיא בִּשְׂרֵפָה. וְיֵשׁ אֵשֶׁת אִישׁ שֶׁהִיא בִּסְקִילָה:","וְהֵיכָן סוֹקְלִין נַעֲרָה מְאֹרָשָׂה שֶׁזִּנְּתָה. אִם זִנְּתָה בְּבֵית אָבִיהָ אַף עַל פִּי שֶׁלֹּא הֵעִידוּ עָלֶיהָ הָעֵדִים אֶלָּא אַחַר שֶׁבָּאָה לְבֵית חָמִיהָ (וְנִיסֵת) הֲרֵי זוֹ נִסְקֶלֶת עַל פֶּתַח בֵּית אָבִיהָ. זִנִּתָה בִּבֵית חָמִיהָ קֹדֵם שֵׁיִּמִסֹר אוֹתָהּ הָאָב אַף עַל פִּי שֶׁהֵעִידוּ עָלֶיהָ אַחַר שֶׁחָזְרָה לְבֵית אָבִיהָ הֲרֵי זוֹ נִסְקֶלֶת עַל פֶּתַח שַׁעַר הָעִיר הַהִיא:","בָּאוּ עֵדִים אַחַר שֶׁבָּגְרָה אוֹ אַחַר שֶׁבְּעָלָהּ בַּעְלָהּ אַף עַל פִּי שֶׁהֵעִידוּ שֶׁזִּנְּתָה בְּבֵית אָבִיהָ כְּשֶׁהָיְתָה נַעֲרָה הֲרֵי זוֹ נִסְקֶלֶת בְּבֵית הַסְּקִילָה:","הָיְתָה הוֹרָתָהּ שֶׁלֹּא בִּקְדֻשָּׁה וְלֵדָתָהּ בִּקְדֻשָּׁה נִסְקֶלֶת עַל פֶּתַח שַׁעַר הָעִיר. כָּל מִי שֶׁמִּצְוָתָהּ לִסְקל אוֹתָהּ עַל פֶּתַח שַׁעַר הָעִיר אִם הָיְתָה עִיר שֶׁרֻבָּהּ עַכּוּ\"ם סוֹקְלִין אוֹתָהּ עַל פֶּתַח בֵּית דִּין. וְכָל מִי שֶׁמִּצְוָתָהּ לִסְקל אוֹתָהּ עַל פֶּתַח בֵּית אָבִיהָ אִם לֹא הָיָה לָהּ אָב אוֹ שֶׁהָיָה לָהּ אָב וְלֹא הָיָה לוֹ בַּיִת הֲרֵי זוֹ נִסְקֶלֶת בְּבֵית הַסְּקִילָה. לֹא נֶאֱמַר (דברים כב כא) \"פֶּתַח בֵּית אָב\" אֶלָּא לְמִצְוָה:","הַבָּא עַל עֶרְוָה מִן הָעֲרָיוֹת בִּיאוֹת הַרְבֵּה חַיָּב כָּרֵת אוֹ מִיתַת בֵּית דִּין עַל כָּל בִּיאָה וּבִיאָה אַף עַל פִּי שֶׁאֵין בֵּית דִּין יְכוֹלִין לְהָמִית אֶלָּא מִיתָה אַחַת הֲרֵי הַבִּיאוֹת נֶחְשָׁבוֹת לוֹ כַּעֲבֵרוֹת הַרְבֵּה. וְכֵן אִם בָּא בִּיאָה אַחַת שֶׁחַיָּבִין עָלֶיהָ מִשֵּׁמוֹת הַרְבֵּה אִם הָיָה שׁוֹגֵג מֵבִיא קָרְבָּן עַל כָּל שֵׁם וְשֵׁם. אַף עַל פִּי שֶׁהִיא בִּיאָה אַחַת כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת שְׁגָגוֹת. וְאִם הָיָה מֵזִיד הֲרֵי זוֹ נֶחְשֶׁבֶת לוֹ כַּעֲבֵרוֹת הַרְבֵּה. וְכֵן יֵשׁ בָּא בִּיאָה אַחַת וְלוֹקֶה עָלֶיהָ מַלְקִיּוֹת הַרְבֵּה כְּמוֹ שֶׁיִּתְבָּאֵר:","שִׁפְחָה חֲרוּפָה הָאֲמוּרָה בַּתּוֹרָה הִיא שֶׁחֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חוֹרִין וּמְקֻדֶּשֶׁת לְעֶבֶד עִבְרִי שֶׁנֶּאֱמַר (ויקרא יט כ) \"לֹא יוּמְתוּ כִּי לֹא חֻפָּשָׁה\". הָא אִם נִשְׁתַּחְרְרָה כֻּלָּהּ חַיָּבִין עָלֶיהָ מִיתַת בֵּית דִּין שֶׁהֲרֵי נַעֲשֵׂית אֵשֶׁת אִישׁ גְּמוּרָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת:","בִּיאַת שִׁפְחָה זוֹ מְשֻׁנָּה מִכָּל בִּיאוֹת אֲסוּרוֹת שֶׁבַּתּוֹרָה. שֶׁהֲרֵי הִיא לוֹקָה שֶׁנֶּאֱמַר (ויקרא יט כ) \"בִּקֹּרֶת תִּהְיֶה\" וְהוּא חַיָּב קָרְבַּן אָשָׁם שֶׁנֶּאֱמַר (ויקרא יט כא) \"וְהֵבִיא אֶת אֲשָׁמוֹ\". אֶחָד שׁוֹגֵג אֶחָד מֵזִיד בְּשִׁפְחָה חֲרוּפָה מֵבִיא אָשָׁם. וְהַבָּא עָלֶיהָ בִּיאוֹת הַרְבֵּה בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה מֵבִיא אָשָׁם אֶחָד. אֲבָל הִיא חַיֶּבֶת מַלְקוֹת עַל כָּל בִּיאָה וּבִיאָה אִם הָיְתָה מְזִידָה כִּשְׁאָר חַיָּבֵי לָאוִין:","הַמְעָרֶה בְּשִׁפְחָה חֲרוּפָה וְלֹא גָּמַר בִּיאָתוֹ פָּטוּר עַד שֶׁיִּגְמֹר בִּיאָתוֹ. וְאֵינוֹ חַיָּב אֶלָּא עַל הַגְּדוֹלָה הַבְּעוּלָה הַמְּזִידָה וּבִרְצוֹנָהּ. אֲבָל אִם הָיְתָה קְטַנָּה אוֹ שֶׁלֹּא הָיְתָה בְּעוּלָה אוֹ הָיְתָה שׁוֹגֶגֶת אוֹ אֲנוּסָה אוֹ יְשֵׁנָה פָּטוּר [וְכֵן אִם בָּא עָלֶיהָ שֶׁלֹּא כְּדַרְכָּהּ פָּטוּר שֶׁבְּשִׁפְחָה חֲרוּפָה לֹא הִשְׁוָה בִּיאָה כְּדַרְכָּהּ לְבִיאָה שֶׁלֹּא כְּדַרְכָּהּ שֶׁנֶּאֱמַר (ויקרא יט כ) \"שִׁכְבַת זֶרַע\". אֲבָל בִּשְׁאָר בִּיאוֹת לֹא חָלַק בֵּין בִּיאָה לְבִיאָה שֶׁנֶּאֱמַר (ויקרא יח כב) (ויקרא כ יג) \"מִשְׁכְּבֵי אִשָּׁה\" מַגִּיד [לְךָ] הַכָּתוּב שֶׁשְּׁנֵי מִשְׁכָּבוֹת בְּאִשָּׁה]:","כָּל מָקוֹם שֶׁאָמַרְנוּ בְּשִׁפְחָה שֶׁהוּא פָּטוּר הוּא פָּטוּר מִן הַקָּרְבָּן וְהִיא פְּטוּרָה מִן הַמַּלְקוֹת. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת מִדִּבְרֵיהֶם אִם הָיוּ שְׁנֵיהֶן מְזִידִין וּגְדוֹלִים:","בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל שִׁפְחָה חֲרוּפָה הִיא לוֹקָה וְהוּא מֵבִיא קָרְבָּן. וְהוּא שֶׁתִּהְיֶה גְּדוֹלָה וּבְעוּלָה וּבִרְצוֹנָהּ כְּמוֹ שֶׁבֵּאַרְנוּ. שֶׁאֵין הָאִישׁ חַיָּב קָרְבָּן עַד שֶׁתִּתְחַיֵּב הִיא מַלְקוֹת שֶׁנֶּאֱמַר (ויקרא יט כ) \"בִּקֹּרֶת תִּהְיֶה\" (ויקרא יט כא) \"וְהֵבִיא אֶת אֲשָׁמוֹ\":"],"Mishneh Torah, Foreign Worship and Customs of the Nations 3":["כָּל הָעוֹבֵד כּוֹכָבִים בִּרְצוֹנוֹ בְּזָדוֹן חַיָּב כָּרֵת וְאִם הָיוּ שָׁם עֵדִים וְהַתְרָאָה נִסְקָל. וְאִם עָבַד בִּשְׁגָגָה מֵבִיא קָרְבַּן חַטָּאת קְבוּעָה:","עֲבוֹדוֹת הַרְבֵּה קָבְעוּ עוֹבְדֵי כּוֹכָבִים לְכָל צֶלֶם וְצֶלֶם וּלְכָל צוּרָה וְצוּרָה וַעֲבוֹדַת זֶה אֵינָהּ כַּעֲבוֹדַת זֶה כְּגוֹן פְּעוֹר שֶׁעֲבוֹדָתוֹ שֶׁפּוֹעֵר אָדָם עַצְמוֹ לוֹ וּמַרְקוּלִיס שֶׁעֲבוֹדָתוֹ שֶׁיִּזְרֹק לוֹ אֲבָנִים אוֹ יְסַקֵּל מִלְּפָנָיו אֲבָנִים וְהַרְבֵּה עֲבוֹדוֹת כְּגוֹן אֵלּוּ תִּקְּנוּ לִשְׁאָר צְלָמִים. לְפִיכָךְ הַפּוֹעֵר עַצְמוֹ לְמַרְקוּלִיס אוֹ שֶׁזָּרַק אֶבֶן לִפְעוֹר פָּטוּר עַד שֶׁיַּעֲבֹד אוֹתוֹ דֶּרֶךְ עֲבוֹדָתוֹ שֶׁנֶּאֱמַר (דברים יב ל) \"אֵיכָה יַעַבְדוּ הַגּוֹיִם הָאֵלֶּה אֶת אֱלֹהֵיהֶם וְאֶעֱשֶׂה כֵּן גַּם אָנִי\". וּמִפְּנֵי זֶה הָעִנְיָן צְרִיכִין בֵּית דִּין לֵידַע דַּרְכֵי הָעֲבוֹדוֹת, שֶׁאֵין סוֹקְלִין עוֹבֵד כּוֹכָבִים עַד שֶׁיֵּדְעוּ שֶׁזּוֹ הִיא דֶּרֶךְ עֲבוֹדָתוֹ:","וְאַזְהָרָה שֶׁל עֲבוֹדוֹת אֵלּוּ וְכַיּוֹצֵא בָּהֶן הוּא מַה שֶּׁכָּתוּב (שמות כ ה) \"וְלֹא תָעָבְדֵם\". בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר עֲבוֹדוֹת חוּץ מִמִּשְׁתַּחֲוְה וְזוֹבֵחַ וּמַקְטִיר וּמְנַסֵּךְ. אֲבָל הָעוֹבֵד בְּאַחַת מֵעֲבוֹדוֹת אֵלּוּ לְאֶחָד מִכָּל מִינֵי עֲבוֹדַת כּוֹכָבִים חַיָּב וְאַף עַל פִּי שֶׁאֵין דֶּרֶךְ עֲבוֹדָתוֹ בְּכָךְ. כֵּיצַד. הֲרֵי שֶׁנִּסֵּךְ לִפְעוֹר אוֹ שֶׁזָּבַח לְמַרְקוּלִיס חַיָּב שֶׁנֶּאֱמַר (שמות כב יט) \"זֹבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַה' לְבַדּוֹ\". זְבִיחָה בִּכְלַל עֲבוֹדָה הָיְתָה וְלָמָּה יָצָאת לוֹמַר לְךָ מַה זְּבִיחָה מְיֻחֶדֶת שֶׁעוֹבְדִין בָּהּ לַשֵּׁם וְחַיָּב הַזּוֹבֵחַ לְאֵל אַחֵר סְקִילָה עָלֶיהָ בֵּין הָיְתָה דֶּרֶךְ עֲבוֹדָתוֹ בִּזְבִיחָה אוֹ אֵינָהּ בִּזְבִיחָה. אַף כָּל עֲבוֹדָה שֶׁהִיא מְיֻחֶדֶת לַשֵּׁם אִם עָבַד בָּהּ לְאֵל אַחֵר בֵּין שֶׁהָיְתָה דֶּרֶךְ עֲבוֹדָתוֹ בְּכָךְ בֵּין שֶׁאֵינָהּ בְּכָךְ חַיָּב עָלֶיהָ. לְכָךְ נֶאֱמַר (שמות לד יד) \"לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר\" לְחַיֵּב עַל הַהִשְׁתַּחֲוָיָה אֲפִלּוּ אֵין דֶּרֶךְ עֲבוֹדָתוֹ בְּכָךְ. וְהוּא הַדִּין לִמְקַטֵּר וּמְנַסֵּךְ. וְזוֹרֵק וּמְנַסֵּךְ אֶחָד הוּא:","סָפַת לָהּ צוֹאָה אוֹ שֶׁנִּסֵּךְ לָהּ עֲבִיט שֶׁל מֵי רַגְלַיִם חַיָּב. שָׁחַט לָהּ חָגָב פָּטוּר אֶלָּא אִם כֵּן הָיְתָה עֲבוֹדָתָהּ בְּכָךְ. וְכֵן אִם שָׁחַט לָהּ בְּהֵמָה מְחֻסֶּרֶת אֵיבָר פָּטוּר אֶלָּא אִם כֵּן הָיְתָה דֶּרֶךְ עֲבוֹדָתָהּ בְּכָךְ. עֲבוֹדַת כּוֹכָבִים שֶׁעוֹבְדִין אוֹתָהּ בְּמַקֵּל. שָׁבַר מַקֵּל בְּפָנֶיהָ חַיָּב וְנֶאֱסֶרֶת. זָרַק מַקֵּל בְּפָנֶיהָ חַיָּב וְאֵינָהּ נֶאֱסֶרֶת. שֶׁאֵין זְרִיקַת הַמַּקֵּל כְּעֵין זְרִיקַת הַדָּם שֶׁהֲרֵי הַמַּקֵּל כְּמוֹ שֵׁהוּא וְהַדָּם מִתְפַּזֵּר. הַמְקַבֵּל עָלָיו אֶחָד מִכָּל מִינֵי עֲבוֹדַת כּוֹכָבִים בֵּאלוֹהַּ חַיָּב סְקִילָה. וַאֲפִלּוּ הִגְבִּיהַּ לְבֵנָה וְאָמַר לָהּ אֵלִי אַתָּה וְכֵן כָּל כַּיּוֹצֵא בְּדִבּוּר זֶה חַיָּב. וַאֲפִלּוּ חָזַר בּוֹ בְּתוֹךְ כְּדֵי דִּבּוּר וְאָמַר אֵין זֶה אֵלִי אֵין חֲזָרָתוֹ כְּלוּם אֶלָּא נִסְקָל:","הָעוֹבֵד עֲבוֹדַת כּוֹכָבִים כְּדַרְכָּהּ וַאֲפִלּוּ עָשָׂה דֶּרֶךְ בִּזָּיוֹן חַיָּב. כֵּיצַד. הַפּוֹעֵר עַצְמוֹ לִפְעוֹר כְּדֵי לְבַזּוֹתוֹ אוֹ זָרַק אֶבֶן לְמַרְקוּלִיס כְּדֵי לְבַזּוֹתוֹ הוֹאִיל וַעֲבוֹדָתוֹ בְּכָךְ חַיָּב. וּמֵבִיא קָרְבָּן עַל שִׁגְגָתוֹ:","הָעוֹבֵד עֲבוֹדַת כּוֹכָבִים מֵאַהֲבָה כְּגוֹן שֶׁחָשַׁק בְּצוּרָה זוֹ מִפְּנֵי מְלַאכְתָּהּ שֶׁהָיְתָה נָאָה בְּיוֹתֵר. אוֹ שֶׁעֲבָדָהּ מִיִּרְאָתוֹ לָהּ שֶׁמָּא תָּרֵעַ לוֹ כְּמוֹ שֶׁהֵן מְדַמִּים עוֹבְדֶיהָ שֶׁהִיא מֵיטִיבָה וּמְרֵעָה. אִם קִבְּלָהּ עָלָיו בֵּאלוֹהַּ חַיָּב סְקִילָה וְאִם עֲבָדָהּ דֶּרֶךְ עֲבוֹדָתָהּ אוֹ בְּאַחַת מֵאַרְבַּע עֲבוֹדוֹת מֵאַהֲבָה אוֹ מִיִּרְאָה פָּטוּר. הַמְגַפֵּף עֲבוֹדַת כּוֹכָבִים וְהַמְנַשֵּׁק לָהּ וְהַמְכַבֵּד וְהַמְרַבֵּץ לְפָנֶיהָ וְהַמַּרְחִיץ לָהּ וְהַסָּךְ וְהַמַּלְבִּישׁ וְהַמַּנְעִיל וְכָל כַּיּוֹצֵא בְּדִבְרֵי כָּבוֹד הָאֵלּוּ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר וְלֹא תָעָבְדֵם, וּדְבָרִים אֵלּוּ בִּכְלַל עֲבוֹדָה הֵן. וְאַף עַל פִּי כֵן אֵינוֹ לוֹקֶה עַל אַחַת מֵהֶן לְפִי שֶׁאֵינָן בְּפֵרוּשׁ. וְאִם הָיְתָה דֶּרֶךְ עֲבוֹדָתָהּ בְּאֶחָד מִכָּל הַדְּבָרִים הָאֵלּוּ וַעֲשָׂהוּ לְעָבְדָהּ חַיָּב:","יָשַׁב לוֹ קוֹץ בְּרַגְלוֹ לִפְנֵי עֲבוֹדַת כּוֹכָבִים לֹא יָשֹׁחַ וְיִטְּלֶנּוּ מִפְּנֵי שֶׁנִּרְאֶה כְּמִשְׁתַּחֲוֶה לָהּ. נִתְפַּזְּרוּ לוֹ מָעוֹת בְּפָנֶיהָ לֹא יָשֹׁחַ וְיִטְּלֵם מִפְּנֵי שֶׁנִּרְאֶה כְּמִשְׁתַּחֲוֶה לָהּ אֶלָּא יֵשֵׁב וְאַחַר כָּךְ יִטּל:","פַּרְצוּפוֹת הַמְקַלְּחוֹת מַיִם בִּפְנֵי עֲבוֹדַת כּוֹכָבִים לֹא יַנִּיחַ פִּיו עַל פִּיהֶם וְיִשְׁתֶּה מִפְּנֵי שֶׁנִּרְאֶה כִּמְנַשֵּׁק לַעֲבוֹדַת כּוֹכָבִים:","הָעוֹשֶׂה עֲבוֹדַת כּוֹכָבִים לְעַצְמוֹ אַף עַל פִּי שֶׁלֹּא עֲשָׂאָהּ בְּיָדוֹ וְלֹא עֲבָדָהּ לוֹקֶה שֶׁנֶּאֱמַר (שמות כ ד) \"לֹא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה\". וְכֵן הָעוֹשֶׂה עֲבוֹדַת כּוֹכָבִים בְּיָדוֹ לַאֲחֵרִים אֲפִלּוּ עֲשָׂאָהּ לְעוֹבֵד כּוֹכָבִים לוֹקֶה שֶׁנֶּאֱמַר (ויקרא יט ד) \"וֵאלֹהֵי מַסֵּכָה לֹא תַעֲשׂוּ לָכֶם\". לְפִיכָךְ הָעוֹשֶׂה עֲבוֹדַת כּוֹכָבִים בְּיָדוֹ לְעַצְמוֹ לוֹקֶה שְׁתַּיִם:","אָסוּר לַעֲשׂוֹת צוּרוֹת לְנוֹי וְאַף עַל פִּי שֶׁאֵינָהּ עֲבוֹדַת כּוֹכָבִים שֶׁנֶּאֱמַר (שמות כ כ) \"לֹא תַעֲשׂוּן אִתִּי\" כְּלוֹמַר צוּרוֹת שֶׁל כֶּסֶף וְזָהָב שֶׁאֵינָם אֶלָּא לְנוֹי כְּדֵי שֶׁלֹּא יִטְּעוּ בָּהֶן הַטּוֹעִים וִידַמּוּ שֶׁהֵם לַעֲבוֹדַת כּוֹכָבִים. וְאֵין אִסּוּר לָצוּר לְנוֹי אֶלָּא צוּרַת הָאָדָם בִּלְבַד. לְפִיכָךְ אֵין מְצַיְּרִים לֹא בְּעֵץ וְלֹא בְּסִיד וְלֹא בְּאֶבֶן צוּרַת הָאָדָם. וְהוּא שֶׁתִּהְיֶה הַצּוּרָה בּוֹלֶטֶת כְּגוֹן הַצִּיּוּר וְהַכִּיּוּר שֶׁבַּטְּרַקְלִין וְכַיּוֹצֵא בָּהֶן וְאִם צָר לוֹקֵה. אֲבָל אִם הָיִתָה הַצּוּרָה מֻשְׁקַעַת אוֹ צוּרָה שֶׁל סַמָּנִין כְּגוֹן הַצּוּרוֹת שֵׁעַל גַּבֵּי הַלּוּחוֹת וִהַטַּבְלִיּוֹת אוֹ צוּרוֹת שֶׁרוֹקְמִין בָּאָרִיג הֲרֵי אֵלּוּ מֻתָּרוֹת:","טַבַּעַת שֶׁיֵּשׁ עָלֶיהָ חוֹתָם שֶׁהוּא צוּרַת אָדָם אִם הָיְתָה הַצּוּרָה בּוֹלֶטֶת אָסוּר לְהַנִּיחָהּ וּמֻתָּר לַחְתֹּם בָּהּ. וְאִם הָיְתָה הַצּוּרָה שׁוֹקַעַת מֻתָּר לְהַנִּיחָהּ וְאָסוּר לַחְתֹּם בָּהּ מִפְּנֵי שֶׁהַנָּחָתָם תַּעֲשֶׂה בּוֹ הַצּוּרָה בּוֹלֶטֶת. וְכֵן אָסוּר לָצוּר דְּמוּת חַמָּה וּלְבָנָה כּוֹכָבִים מַזָּלוֹת וּמַלְאָכִים שֶׁנֶּאֱמַר (שמות כ כ) \"לֹא תַעֲשׂוּן אִתִּי\" (גמרא ראש השנה כד ב) \"לֹא תַעֲשׂוּן כִּדְמוּת שְׁמָשַׁי הַמְשַׁמְּשִׁין לְפָנַי בַּמָּרוֹם\" וַאֲפִלּוּ עַל הַלּוּחַ. צוּרוֹת הַבְּהֵמוֹת וּשְׁאָר נֶפֶשׁ חַיָּה חוּץ מִן הָאָדָם וְצוּרוֹת הָאִילָנוֹת וּדְשָׁאִים וְכַיּוֹצֵא בָּהֶן מֻתָּר לָצוּר אוֹתָם וַאֲפִלּוּ הָיְתָה הַצּוּרָה בּוֹלֶטֶת:"],"Mishneh Torah, Foundations of the Torah 5":["כָּל בֵּית יִשְׂרָאֵל מְצֻוִּין עַל קִדּוּשׁ הַשֵּׁם הַגָּדוֹל הַזֶּה שֶׁנֶּאֱמַר (ויקרא כב לב) \"וְנִקְדַּשְׁתִּי בְּתוֹךְ בְּנֵי יִשְׂרָאֵל\". וּמֻזְהָרִין שֶׁלֹּא לְחַלְּלוֹ שֶׁנֶּאֱמַר (ויקרא כב לב) \"וְלֹא תְחַלְּלוּ אֶת שֵׁם קָדְשִׁי\". כֵּיצַד. כְּשֶׁיַּעֲמֹד עוֹבֵד כּוֹכָבִים וְיֶאֱנֹס אֶת יִשְׂרָאֵל לַעֲבֹר עַל אַחַת מִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה אוֹ יַהַרְגֶּנּוּ יַעֲבֹר וְאַל יֵהָרֵג שֶׁנֶּאֱמַר בַּמִּצְוֹת (ויקרא יח ה) \"אֲשֶׁר יַעֲשֶׂה אוֹתָם הָאָדָם וָחַי בָּהֶם\". וָחַי בָּהֶם וְלֹא שֶׁיָּמוּת בָּהֶם. וְאִם מֵת וְלֹא עָבַר הֲרֵי זֶה מִתְחַיֵּב בְּנַפְשׁוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר מִצְוֹת חוּץ מֵעֲבוֹדַת כּוֹכָבִים וְגִלּוּי עֲרָיוֹת וּשְׁפִיכַת דָּמִים. אֲבָל שָׁלֹשׁ עֲבֵרוֹת אֵלּוּ אִם יֹאמַר לוֹ עֲבֹר עַל אַחַת מֵהֶן אוֹ תֵּהָרֵג. יֵהָרֵג וְאַל יַעֲבֹר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁהָעוֹבֵד כּוֹכָבִים מִתְכַּוֵּן לַהֲנָאַת עַצְמוֹ. כְּגוֹן שֶׁאֲנָסוֹ לִבְנוֹת לוֹ בֵּיתוֹ בְּשַׁבָּת אוֹ לְבַשֵּׁל לוֹ תַּבְשִׁילוֹ. אוֹ אָנַס אִשָּׁה לְבָעֳלָהּ וְכַיּוֹצֵא בָּזֶה. אֲבָל אִם נִתְכַּוֵּן לְהַעֲבִירוֹ עַל הַמִּצְוֹת בִּלְבַד. אִם הָיָה בֵּינוֹ לְבֵין עַצְמוֹ וְאֵין שָׁם עֲשָׂרָה מִיִּשְׂרָאֵל יַעֲבֹר וְאַל יֵהָרֵג. וְאִם אֲנָסוֹ לְהַעֲבִירוֹ בַּעֲשָׂרָה מִיִּשְׂרָאֵל יֵהָרֵג וְאַל יַעֲבֹר. וַאֲפִלּוּ לֹא נִתְכַּוֵּן לְהַעֲבִירוֹ אֶלָּא עַל מִצְוָה מִשְּׁאָר מִצְוֹת בִּלְבַד:","וְכָל הַדְּבָרִים הָאֵלּוּ שֶׁלֹּא בִּשְׁעַת הַגְּזֵרָה אֲבָל בִּשְׁעַת הַגְּזֵרָה וְהוּא שֶׁיַּעֲמֹד מֶלֶךְ רָשָׁע כִּנְבוּכַדְנֶצַּר וַחֲבֵרָיו וְיִגְזֹר גְּזֵרָה עַל יִשְׂרָאֵל לְבַטֵּל דָּתָם אוֹ מִצְוָה מִן הַמִּצְוֹת. יֵהָרֵג וְאַל יַעֲבֹר אֲפִלּוּ עַל אַחַת מִשְּׁאָר מִצְוֹת בֵּין נֶאֱנָס בְּתוֹךְ עֲשָׂרָה בֵּין נֶאֱנָס בֵּינוֹ לְבֵין עוֹבְדֵי כּוֹכָבִים:","כָּל מִי שֶׁנֶּאֱמַר בּוֹ יַעֲבֹר וְאַל יֵהָרֵג וְנֶהֱרַג וְלֹא עָבַר הֲרֵי זֶה מִתְחַיֵּב בְּנַפְשׁוֹ. וְכָל מִי שֶׁנֶּאֱמַר בּוֹ יֵהָרֵג וְאַל יַעֲבֹר וְנֶהֱרַג וְלֹא עָבַר הֲרֵי זֶה קִדֵּשׁ אֶת הַשֵּׁם. וְאִם הָיָה בַּעֲשָׂרָה מִיִּשְׂרָאֵל הֲרֵי זֶה קִדֵּשׁ אֶת הַשֵּׁם בָּרַבִּים כְּדָנִיֵּאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה וְרַבִּי עֲקִיבָא וַחֲבֵרָיו. וְאֵלּוּ הֵן הֲרוּגֵי מַלְכוּת שֶׁאֵין מַעֲלָה עַל מַעֲלָתָן. וַעֲלֵיהֶן נֶאֱמַר (תהילים מד כג) \"כִּי עָלֶיךָ הֹרַגְנוּ כָל הַיּוֹם נֶחְשַׁבְנוּ כְּצֹאן טִבְחָה\". וַעֲלֵיהֶם נֶאֱמַר (תהילים נ ה) \"אִסְפוּ לִי חֲסִידָי כֹּרְתֵי בְרִיתִי עֲלֵי זָבַח\". וְכָל מִי שֶׁנֶּאֱמַר בּוֹ יֵהָרֵג וְאַל יַעֲבֹר וְעָבַר וְלֹא נֶהֱרַג הֲרֵי זֶה מְחַלֵּל אֶת הַשֵּׁם. וְאִם הָיָה בַּעֲשָׂרָה מִיִּשְׂרָאֵל הֲרֵי זֶה חִלֵּל אֶת הַשֵּׁם בָּרַבִּים וּבִטֵּל מִצְוַת עֲשֵׂה שֶׁהִיא קִדּוּשׁ הַשֵּׁם וְעָבַר עַל מִצְוַת לֹא תַעֲשֶׂה שֶׁהִיא חִלּוּל הַשֵּׁם. וְאַף עַל פִּי כֵן מִפְּנֵי שֶׁעָבַר בְּאֹנֶס אֵין מַלְקִין אוֹתוֹ וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין מְמִיתִין אוֹתוֹ בֵּית דִּין אֲפִלּוּ הָרַג בְּאֹנֶס. שֶׁאֵין מַלְקִין וּמְמִיתִין אֶלָּא לְעוֹבֵר בִּרְצוֹנוֹ וּבְעֵדִים וְהַתְרָאָה שֶׁנֶּאֱמַר בְּנוֹתֵן מִזַּרְעוֹ לַמּלֶךְ (ויקרא כ ה) \"(וְנָתַתִּי) [וְשַׂמְתִּי] אֲנִי אֶת פָּנַי בָּאִישׁ הַהוּא\". מִפִּי הַשְּׁמוּעָה לָמְדוּ הַהוּא לֹא אָנוּס וְלֹא שׁוֹגֵג וְלֹא מֻטְעֶה. וּמָה אִם עֲבוֹדַת כּוֹכָבִים שֶׁהִיא חֲמוּרָה מִן הַכּל הָעוֹבֵד אוֹתָהּ בְּאֹנֶס אֵינוֹ חַיָּב כָּרֵת וְאֵין צָרִיךְ לוֹמַר מִיתַת בֵּית דִּין. קַל וָחֹמֶר לִשְׁאָר מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה. וּבַעֲרָיוֹת הוּא אוֹמֵר (דברים כב כו) \"וְלַנַּעֲרָה לֹא תַעֲשֶׂה דָבָר\". אֲבָל אִם יָכוֹל לְמַלֵּט נַפְשׁוֹ וְלִבְרֹחַ מִתַּחַת יַד הַמֶּלֶךְ הָרָשָׁע וְאֵינוֹ עוֹשֶׂה הִנֵּה הוּא כְּכֶלֶב שָׁב עַל קֵאוֹ. וְהוּא נִקְרָא עוֹבֵד עֲבוֹדַת כּוֹכָבִים בְּמֵזִיד וְהוּא נִטְרָד מִן הָעוֹלָם הַבָּא וְיוֹרֵד לַמַּדְרֵגָה הַתַּחְתּוֹנָה שֶׁל גֵּיהִנֹּם:","נָשִׁים שֶׁאָמְרוּ לָהֶם עוֹבְדֵי כּוֹכָבִים תְּנוּ לָנוּ אַחַת מִכֶּן וּנְטַמֵּא אוֹתָהּ וְאִם לָאו נְטַמֵּא אֶת כֻּלְּכֶן יִטָּמְאוּ כֻּלָּן וְאַל יִמְסְרוּ לָהֶם נֶפֶשׁ אַחַת מִיִּשְׂרָאֵל. וְכֵן אִם אָמְרוּ לָהֶם עוֹבְדֵי כּוֹכָבִים תְּנוּ לָנוּ אֶחָד מִכֶּם וְנַהַרְגֶּנּוּ וְאִם לָאו נַהֲרֹג כֻּלְּכֶם. יֵהָרְגוּ כֻּלָּם וְאַל יִמְסְרוּ לָהֶם נֶפֶשׁ אַחַת מִיִּשְׂרָאֵל. וְאִם יִחֲדוּהוּ לָהֶם וְאָמְרוּ תְּנוּ לָנוּ פְּלוֹנִי אוֹ נַהֲרֹג אֶת כֻּלְּכֶם. אִם הָיָה מְחֻיָּב מִיתָה כְּשֶׁבַע בֶּן בִּכְרִי יִתְּנוּ אוֹתוֹ לָהֶם. וְאֵין מוֹרִין לָהֶם כֵּן לְכַתְּחִלָּה. וְאִם אֵינוֹ חַיָּב מִיתָה יֵהָרְגוּ כֻּלָּן וְאַל יִמְסְרוּ לָהֶם נֶפֶשׁ אַחַת מִיִּשְׂרָאֵל:","כָּעִנְיָן שֶׁאָמְרוּ בָּאֳנָסִין כָּךְ אָמְרוּ בָּחֳלָאִים. כֵּיצַד. מִי שֶׁחָלָה וְנָטָה לָמוּת וְאָמְרוּ הָרוֹפְאִים שֶׁרְפוּאָתוֹ בְּדָבָר פְּלוֹנִי מֵאִסּוּרִין שֶׁבַּתּוֹרָה עוֹשִׂין. וּמִתְרַפְּאִין בְּכָל אִסּוּרִין שֶׁבַּתּוֹרָה בִּמְקוֹם סַכָּנָה חוּץ מֵעֲבוֹדַת כּוֹכָבִים וְגִלּוּי עֲרָיוֹת וּשְׁפִיכַת דָּמִים שֶׁאֲפִלּוּ בִּמְקוֹם סַכָּנָה אֵין מִתְרַפְּאִין בָּהֶן. וְאִם עָבַר וְנִתְרַפֵּא עוֹנְשִׁין אוֹתוֹ בֵּית דִּין עֹנֶשׁ הָרָאוּי לוֹ:","וּמִנַּיִן שֶׁאֲפִלּוּ בִּמְקוֹם סַכָּנַת נְפָשׁוֹת אֵין עוֹבְרִין עַל אַחַת מִשָּׁלֹשׁ עֲבֵרוֹת אֵלּוּ שֶׁנֶּאֱמַר (דברים ו ה) \"וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךָ בְּכָל לְבָבְךָ וּבְכָל נַפְשְׁךָ וּבְכָל מְאֹדֶךָ\" אֲפִלּוּ הוּא נוֹטֵל אֶת נַפְשְׁךָ. וַהֲרִיגַת נֶפֶשׁ מִיִּשְׂרָאֵל לְרַפְּאוֹת נֶפֶשׁ אַחֶרֶת אוֹ לְהַצִּיל אָדָם מִיַּד אַנָּס דָּבָר שֶׁהַדַּעַת נוֹטָה לוֹ הוּא שֶׁאֵין מְאַבְּדִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ. וַעֲרָיוֹת הֻקְּשׁוּ לִנְפָשׁוֹת שֶׁנֶּאֱמַר (דברים כב כו) \"כִּי כַּאֲשֶׁר יָקוּם אִישׁ עַל רֵעֵהוּ וּרְצָחוֹ נֶפֶשׁ כֵּן הַדָּבָר הַזֶּה\":","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵין מִתְרַפְּאִין בִּשְׁאָר אִסּוּרִים אֶלָּא בִּמְקוֹם סַכָּנָה. בִּזְמַן שֶׁהֵן דֶּרֶךְ הֲנָאָתָן כְּגוֹן שֶׁמַּאֲכִילִין אֶת הַחוֹלֶה שְׁקָצִים וּרְמָשִׂים אוֹ חָמֵץ בְּפֶסַח אוֹ שֶׁמַּאֲכִילִין אוֹתוֹ בְּיוֹם הַכִּפּוּרִים. אֲבָל שֶׁלֹּא דֶּרֶךְ הֲנָאָתָן כְּגוֹן שֶׁעוֹשִׂין לוֹ רְטִיָּה אוֹ מְלוּגְמָא מֵחָמֵץ אוֹ מֵעָרְלָה. אוֹ שֶׁמַּשְׁקִין אוֹתוֹ דְּבָרִים שֶׁיֵּשׁ בָּהֶן מַר מְעֹרָב עִם אִסּוּרֵי מַאֲכָל שֶׁהֲרֵי אֵין בָּהֶן הֲנָאָה לַחֵךְ הֲרֵי זֶה מֻתָּר וַאֲפִלּוּ שֶׁלֹּא בִּמְקוֹם סַכָּנָה. חוּץ מִכִּלְאֵי הַכֶּרֶם וּבָשָׂר בְּחָלָב שֵׁהֵן אֲסוּרִים אֲפִלּוּ שֵׁלֹּא דֵּרֵךְ הֲנָאָתָן. לְפִיכָךְ אֵין מִתְרַפְּאִין מֵהֶן אֲפִלּוּ שֶׁלֹּא דֶּרֵךְ הֲנָאָתָן אֵלָּא בִּמִקוֹם סַכָּנָה:","מִי שֶׁנָּתַן עֵינָיו בְּאִשָּׁה וְחָלָה וְנָטָה לָמוּת וְאָמְרוּ הָרוֹפְאִים אֵין לוֹ רְפוּאָה עַד שֶׁתִּבָּעֵל לוֹ. יָמוּת וְאַל תִּבָּעֵל לוֹ אֲפִלּוּ הָיְתָה פְּנוּיָה. וַאֲפִלּוּ לְדַבֵּר עִמָּהּ מֵאֲחוֹרֵי הַגָּדֵר אֵין מוֹרִין לוֹ בְּכָךְ וְיָמוּת וְלֹא יוֹרוּ לְדַבֵּר עִמָּהּ מֵאֲחוֹרֵי הַגָּדֵר שֶׁלֹּא יְהוּ בְּנוֹת יִשְׂרָאֵל הֶפְקֵר וְיָבוֹאוּ בִּדְבָרִים אֵלּוּ לִפְרֹץ בַּעֲרָיוֹת:","כָּל הָעוֹבֵר מִדַּעְתּוֹ בְּלֹא אֹנֶס עַל אַחַת מִכָּל מִצְוֹת הָאֲמוּרוֹת בַּתּוֹרָה בִּשְׁאָט בְּנֶפֶשׁ לְהַכְעִיס הֲרֵי זֶה מְחַלֵּל אֶת הַשֵּׁם. וּלְפִיכָךְ נֶאֱמַר בִּשְׁבוּעַת שֶׁקֶר (ויקרא יט יב) \"וְחִלַּלְתָּ אֶת שֵׁם אֱלֹהֶיךָ אֲנִי ה'\". וְאִם עָבַר בַּעֲשָׂרָה מִיִּשְׂרָאֵל הֲרֵי זֶה חִלֵּל אֶת הַשֵּׁם בָּרַבִּים. וְכֵן כָּל הַפּוֹרֵשׁ מֵעֲבֵרָה אוֹ עָשָׂה מִצְוָה לֹא מִפְּנֵי דָּבָר בָּעוֹלָם לֹא פַּחַד וְלֹא יִרְאָה וְלֹא לְבַקֵּשׁ כָּבוֹד אֶלָּא מִפְּנֵי הַבּוֹרֵא בָּרוּךְ הוּא כִּמְנִיעַת יוֹסֵף הַצַּדִּיק עַצְמוֹ מֵאֵשֶׁת רַבּוֹ הֲרֵי זֶה מְקַדֵּשׁ אֶת הַשֵּׁם:","וְיֵשׁ דְּבָרִים אֲחֵרִים שֶׁהֵן בִּכְלַל חִלּוּל הַשֵּׁם. וְהוּא שֶׁיַּעֲשֶׂה אוֹתָם אָדָם גָּדוֹל בַּתּוֹרָה וּמְפֻרְסָם בַּחֲסִידוּת דְּבָרִים שֶׁהַבְּרִיּוֹת מְרַנְּנִים אַחֲרָיו בִּשְׁבִילָם. וְאַף עַל פִּי שֶׁאֵינָן עֲבֵרוֹת הֲרֵי זֶה חִלֵּל אֶת הַשֵּׁם כְּגוֹן שֶׁלָּקַח וְאֵינוֹ נוֹתֵן דְּמֵי הַמִּקָּח לְאַלְתַּר. וְהוּא שֶׁיֵּשׁ לוֹ וְנִמְצְאוּ הַמּוֹכְרִים תּוֹבְעִין וְהוּא מַקִּיפָן. אוֹ שֶׁיַּרְבֶּה בִּשְׂחוֹק אוֹ בַּאֲכִילָה וּשְׁתִיָּה אֵצֶל עַמֵּי הָאָרֶץ וּבֵינֵיהֶן. אוֹ שֶׁדִּבּוּרוֹ עִם הַבְּרִיּוֹת אֵינוֹ בְּנַחַת וְאֵינוֹ מְקַבְּלָן בְּסֵבֶר פָּנִים יָפוֹת אֶלָּא בַּעַל קְטָטָה וְכַעַס. וְכַיּוֹצֵא בַּדְּבָרִים הָאֵלּוּ הַכּל לְפִי גָּדְלוֹ שֶׁל חָכָם צָרִיךְ שֶׁיְּדַקְדֵּק עַל עַצְמוֹ וְיַעֲשֶׂה לִפְנִים מִשּׁוּרַת הַדִּין. וְכֵן אִם דִּקְדֵּק הֶחָכָם עַל עַצְמוֹ וְהָיָה דִּבּוּרוֹ בְּנַחַת עִם הַבְּרִיּוֹת וְדַעְתּוֹ מְעֹרֶבֶת עִמָּהֶם וּמְקַבְּלָם בְּסֵבֶר פָּנִים יָפוֹת וְנֶעֱלָב מֵהֶם וְאֵינוֹ עוֹלְבָם. מְכַבֵּד לָהֶן וַאֲפִלּוּ לַמְקִלִּין לוֹ. וְנוֹשֵׂא וְנוֹתֵן בֶּאֱמוּנָה. וְלֹא יַרְבֶּה בַּאֲרִיחוּת עַמֵּי הָאָרֶץ וִישִׁיבָתָן. וְלֹא יֵרָאֶה תָּמִיד אֶלָּא עוֹסֵק בַּתּוֹרָה עָטוּף בְּצִיצִית מֻכְתָּר בִּתְפִלִּין וְעוֹשֶׂה בְּכָל מַעֲשָׂיו לִפְנִים מִשּׁוּרַת הַדִּין. וְהוּא שֶׁלֹּא יִתְרַחֵק הַרְבֵּה וְלֹא יִשְׁתּוֹמֵם. עַד שֶׁיִּמָּצְאוּ הַכּל מְקַלְּסִין אוֹתוֹ וְאוֹהֲבִים אוֹתוֹ וּמִתְאַוִּים לְמַעֲשָׂיו. הֲרֵי זֶה קִדֵּשׁ אֶת ה' וְעָלָיו הַכָּתוּב אוֹמֵר (ישעיה מט ג) \"וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר\":"],"Mishneh Torah, Gifts to the Poor 4":["אֵיזֶהוּ לֶקֶט זֶה הַנּוֹפֵל מִתּוֹךְ הַמַּגָּל בִּשְׁעַת קְצִירָה אוֹ הַנּוֹפֵל מִתּוֹךְ יָדוֹ כְּשֶׁמְּקַבֵּץ הַשִּׁבֳּלִים וְיִקְצֹר. וְהוּא שֶׁיִּהְיֶה הַנּוֹפֵל שִׁבּלֶת אַחַת אוֹ שְׁתַּיִם. אֲבָל אִם נָפְלוּ שָׁלֹשׁ כְּאֶחָד הֲרֵי שְׁלָשְׁתָּן לְבַעַל הַשָּׂדֶה. וְהַנּוֹפֵל מֵאַחַר הַמַּגָּל אוֹ מֵאַחַר הַיָּד אֲפִלּוּ שִׁבּלֶת אַחַת אֵינָהּ לֶקֶט:","הָיָה קוֹצֵר בַּיָּד בְּלֹא מַגָּל הַנּוֹפֵל מִתּוֹךְ יָדוֹ אֵינוֹ לֶקֶט. אֲבָל הַתּוֹלֵשׁ דְּבָרִים הַתּוֹלְשִׁים אוֹתָם הַנּוֹפֵל מִתַּחַת יָדוֹ לֶקֶט. הָיָה קוֹצֵר אוֹ תּוֹלֵשׁ דָּבָר שֶׁדַּרְכּוֹ לְהִתָּלֵשׁ וְאַחַר שֶׁקָּצַר מְלֹא זְרוֹעוֹ אוֹ תָּלַשׁ מְלֹא קֻמְצוֹ הִכָּהוּ קוֹץ וְנָפַל מִיָּדוֹ עַל הָאָרֶץ הֲרֵי זֶה שֶׁל בַּעַל הַבַּיִת:","הָיָה קוֹצֵר וְנִשְׁאֲרָה שִׁבּלֶת אַחַת שֶׁלֹּא נִקְצְרָה וְנִקְצַר כָּל שֶׁסְּבִיבוֹתֶיהָ. אִם הָיָה רֹאשָׁהּ מַגִּיעַ לַקָּמָה שֶׁבְּצִדָּהּ וִיכוֹלָה לְהִקָּצֵר עִם הַקָּמָה הֲרֵי הִיא שֶׁל בַּעַל הַשָּׂדֶה וְאִם לָאו הֲרֵי הִיא שֶׁל עֲנִיִּים:","הָיוּ שְׁתֵּי שִׁבּוֹלוֹת זוֹ בְּצַד זוֹ. הַפְּנִימִית יְכוֹלָה לְהִקָּצֵר עִם הַקָּמָה וְהַחִיצוֹנָה יְכוֹלָה לְהִקָּצֵר עִם הַפְּנִימִית וְאֵינָהּ יְכוֹלָה לְהִקָּצֵר עִם הַקָּמָה. הַפְּנִימִית נִצֶּלֶת וּמַצֶּלֶת אֶת הַחִיצוֹנָה שֶׁהֲרֵי הִיא כְּנוֹפֶלֶת מִתּוֹךְ הַמַּגָּל וְאַף עַל פִּי שֶׁעֲדַיִן לֹא נִקְצְרָה. וְהַשִּׁבֳּלִים שֶׁבִּקֵּשׁ הֲרֵי הֵן שֶׁל בַּעַל הַשָּׂדֶה:","הָרוּחַ שֶׁפִּזְּרָה אֶת הָעֳמָרִים וְנִתְעָרֵב קָצִיר שֶׁל בַּעַל הַשָּׂדֶה עִם הַלֶּקֶט אוֹמְדִין אֶת הַשָּׂדֶה כַּמָּה לֶקֶט הִיא רְאוּיָה לַעֲשׂוֹת וְנוֹתֵן לָעֲנִיִּים מִפְּנֵי שֶׁזֶּה אֹנֶס. וְכַמָּה הוּא שִׁעוּר זֶה אַרְבָּעָה קַבִּין תְּבוּאָה לְכָל בֵּית כּוֹר:","לֶקֶט שֶׁנָּפַל לָאָרֶץ וְלֹא לְקָטוּהוּ עֲנִיִּים וּבָא בַּעַל הַשָּׂדֶה וְהִגְדִּישׁ אֶת הַקָּצִיר שֶׁלּוֹ עַל הָאָרֶץ כֵּיצַד הוּא עוֹשֶׂה. מְפַנֶּה הַגָּדִישׁ שֶׁלּוֹ כֻּלּוֹ לְמָקוֹם אַחֵר וְכָל הַשִּׁבֳּלִים הַנּוֹגְעוֹת בָּאָרֶץ כֻּלָּן לָעֲנִיִּים. מִפְּנֵי שֶׁאֵין אָנוּ יוֹדְעִים אֵי זוֹ הִיא מֵהֶם שֶׁהָיְתָה לֶקֶט וּסְפֵק מַתְּנוֹת עֲנִיִּים לָעֲנִיִּים שֶׁנֶּאֱמַר (ויקרא כג כב) \"תַּעֲזֹב\" הַנַּח לִפְנֵיהֶם מִשֶּׁלְּךָ:","וְלָמָּה אֵין אוֹמְדִין אוֹתָהּ וְלִתֵּן לָעֲנִיִּים מַה שֶּׁרְאוּיָה לַעֲשׂוֹת לֶקֶט. מִפְּנֵי שֶׁעָבַר וְהִגְדִּישׁ עַל הַלֶּקֶט קְנָסוּהוּ. וַאֲפִלּוּ הָיָה שׁוֹגֵג וַאֲפִלּוּ הָיָה הַלֶּקֶט שְׂעוֹרִים וְהִגְדִּישׁ עָלָיו חִטִּין. וַאֲפִלּוּ קָרָא לָעֲנִיִּים וְלֹא בָּאוּ אֲפִלּוּ הִגְדִּישׁוּהוּ אֲחֵרִים שֶׁלֹּא מִדַּעְתּוֹ כָּל הַנּוֹגְעוֹת בָּאָרֶץ הֲרֵי הֵן לָעֲנִיִּים:","הַצָּרִיךְ לְרַבֵּץ אֶת שָׂדֵהוּ קֹדֶם שֶׁיִּלְקְטוּ הָעֲנִיִּים לֶקֶט שֶׁבָּהּ אִם הֶזֵּקוֹ מְרֻבֶּה עַל הֶפְסֵד הַלֶּקֶט מֻתָּר לְרַבֵּץ. וְאִם הֶפְסֵד הַלֶּקֶט מְרֻבֶּה עַל הֶפְסֵדוֹ אָסוּר לְרַבֵּץ. וְאִם קִבֵּץ אֶת כָּל הַלֶּקֶט וְהִנִּיחוֹ עַל הַגָּדֵר עַד שֶׁיָּבוֹא הֶעָנִי וְיִטְּלֶנּוּ הֲרֵי זֶה מִדַּת חֲסִידוּת:","זְרָעִים הַנִּמְצָאִים בְּחוֹרֵי הַנְּמָלִים. אִם הָיוּ הַחוֹרִים בְּתוֹךְ הַקָּמָה הֲרֵי הוּא שֶׁל בַּעַל הַשָּׂדֶה. שֶׁאֵין לָעֲנִיִּים מַתָּנָה בְּתוֹךְ הַקָּמָה. וְאִם הָיוּ בְּמָקוֹם שֶׁנִּקְצַר הֲרֵי זֶה שֶׁל עֲנִיִּים שֶׁמָּא מִן הַלֶּקֶט גְּרָרוּהוּ. וְאַף עַל פִּי שֶׁנִּמְצָא שָׁחוֹר אֵין אוֹמְרִים הֲרֵי זֶה מִשָּׁנָה שֶׁעָבְרָה שֶׁסְּפֵק הַלֶּקֶט לֶקֶט:","שִׁבּלֶת שֶׁל לֶקֶט שֶׁנִּתְעָרְבָה בְּגָדִישׁ הֲרֵי זֶה מַפְרִישׁ שְׁתֵּי שִׁבּוֹלוֹת וְאוֹמֵר עַל אַחַת מֵהֶן אִם הַלֶּקֶט הִיא זוֹ הֲרֵי הִיא לָעֲנִיִּים וְאִם אֵינָהּ לֶקֶט הֲרֵי הַמַּעַשְׂרוֹת (שֶׁהִיא) שֶׁחַיֶּבֶת בָּהֶן שִׁבּלֶת זוֹ קְבוּעִים בְּשִׁבּלֶת שְׁנִיָּה. וְחוֹזֵר וּמַתְנֶה כֵּן עַל שִׁבּלֶת שְׁנִיָּה וְנוֹתֵן אַחַת מֵהֶן לֶעָנִי וְהָאַחֶרֶת תִּהְיֶה מַעֲשֵׂר:","לֹא יִשְׂכֹּר אָדָם אֶת הַפּוֹעֵל עַל מְנָת שֶׁיְּלַקֵּט בְּנוֹ אַחֲרָיו. אֲבָל הָאֲרִיסִין וְהַחֲכִירִין וְהַמּוֹכֵר קָמָתוֹ לַחֲבֵרוֹ לִקְצֹר יְלַקֵּט בְּנוֹ אַחֲרָיו. וְיֵשׁ לַפּוֹעֵל לְהָבִיא אִשְׁתּוֹ וּבָנָיו לְלַקֵּט אַחֲרָיו. וַאֲפִלּוּ שְׂכָרוֹ לִטּל חֲצִי הַקָּצִיר אוֹ שָׁלִישׁוֹ אוֹ רְבִיעוֹ בִּשְׂכָרוֹ:","מִי שֶׁאֵינוֹ מַנִּיחַ אֶת הָעֲנִיִּים לְלַקֵּט אוֹ שֶׁהוּא מַנִּיחַ אֶחָד וּמוֹנֵעַ אֶחָד אוֹ שֶׁמְּסַיֵּעַ אֶת אֶחָד מֵהֶן עַל חֲבֵרוֹ הֲרֵי זֶה גּוֹזֵל אֶת הָעֲנִיִּים:","וְאָסוּר לְאָדָם לְהַרְבִּיץ אֲרִי וְכַיּוֹצֵא בּוֹ בְּתוֹךְ שָׂדֵהוּ כְּדֵי שֶׁיִּרְאוּ הָעֲנִיִּים וְיִבְרְחוּ. הָיוּ שָׁם עֲנִיִּים שֶׁאֵינָן רְאוּיִין לִטּל לֶקֶט אִם יָכוֹל בַּעַל הַבַּיִת לִמְחוֹת בְּיָדָן מְמַחֶה וְאִם לָאו מְנִיחָן מִפְּנֵי דַּרְכֵי שָׁלוֹם:","הַמַּפְקִיר אֶת הַלֶּקֶט עִם נְפִילַת רֻבּוֹ אֵינוֹ הֶפְקֵר מֵאַחֵר שֶׁנָּשַׁר רֻבּוֹ אֵין לוֹ בּוֹ רְשׁוּת:","אֵי זֶהוּ פֶּרֶט זֶה גַּרְגֵּר אֶחָד אוֹ שְׁנֵי גַּרְגְּרִים הַנִּפְרָטִים מִן הָאֶשְׁכּוֹל בִּשְׁעַת הַבְּצִירָה. נָפְלוּ שְׁלֹשָׁה גַּרְגְּרִים בְּבַת אַחַת אֵינוֹ פֶּרֶט:","הָיָה בּוֹצֵר וְכָרַת אֶת הָאֶשְׁכּוֹל וְהֻסְבַּךְ בְּעָלָיו וְנָפַל לָאָרֶץ וְנִפְרַט אֵינוֹ פֶּרֶט. הָיָה בּוֹצֵר וּמַשְׁלִיךְ לָאָרֶץ כְּשֶׁמְּפַנֶּה הָאֶשְׁכּוֹלוֹת אֲפִלּוּ חֲצִי אֶשְׁכּוֹל הַנִּמְצָא שָׁם הֲרֵי הוּא פֶּרֶט (וְכֵן אֶשְׁכּוֹל שָׁלֵם שֶׁנִּפְרַט שָׁם הֲרֵי הוּא פֶּרֶט). וְהַמַּנִּיחַ אֶת הַכַּלְכָּלָה תַּחַת הַגֶּפֶן בְּשָׁעָה שֶׁהוּא בּוֹצֵר הֲרֵי זֶה גּוֹזֵל אֶת הָעֲנִיִּים:","אֵי זוֹ הִיא עוֹלֶלֶת זֶה אֶשְׁכּוֹל הַקָּטָן שֶׁאֵינוֹ מְעֻבֶּה כְּאֶשְׁכּוֹל שֶׁאֵין לוֹ כָּתֵף. וְאֵין עֲנָבָיו נוֹטְפוֹת זוֹ עַל זוֹ אֶלָּא מְפֻזָּרוֹת. יֵשׁ לָהּ כָּתֵף וְאֵין לָהּ נֶטֶף אוֹ יֵשׁ לָהּ נֶטֶף וְאֵין לָהּ כָּתֵף הֲרֵי הִיא שֶׁל בַּעַל הַכֶּרֶם. וְאִם סָפֵק לָעֲנִיִּים:","אֵי זוֹ הִיא כָּתֵף פְּסִיגִין הַמְחֻבָּרוֹת בְּשִׁדְרָה זוֹ עַל גַּבֵּי זוֹ. נֶטֶף עֲנָבִים הַמְחֻבָּרוֹת בְּשִׁדְרָה וְיוֹרְדוֹת. וְהוּא שֶׁיִּהְיוּ כָּל הָעֲנָבִים שֶׁבָּעוֹלֵלוֹת נוֹגְעִין בְּפַס יָדוֹ. וְלָמָּה נִקְרָא שְׁמוֹ עוֹלָל מִפְּנֵי שֶׁהוּא לִשְׁאָר הָאֶשְׁכּוֹלוֹת כְּעוֹלָל לְאִישׁ:","וְאֵין בַּעַל הַבַּיִת חַיָּב לִבְצֹר הָעוֹלֵלוֹת וְלִתְּנָן לָעֲנִיִּים. אֶלָּא הֵן בּוֹצְרִין אוֹתָן לְעַצְמָן וְגַרְגֵּר יְחִידִי הֲרֵי הִיא עוֹלֶלֶת:","זְמוֹרָה שֶׁהָיָה בָּהּ אֶשְׁכּוֹל וּבָאַרְכֻּבָּה שֶׁל זְמוֹרָה עוֹלֶלֶת אִם נִקְרְצָה עִם הָאֶשְׁכּוֹל הֲרֵי הִיא שֶׁל בַּעַל הַכֶּרֶם וְאִם לָאו הֲרֵי הִיא לָעֲנִיִּים:","כֶּרֶם שֶׁכֻּלּוֹ עוֹלֵלוֹת הֲרֵי הוּא לָעֲנִיִּים שֶׁנֶּאֱמַר (ויקרא יט י) \"וְכַרְמְךָ לֹא תְעוֹלֵל\" אֲפִלּוּ כֻּלּוֹ עוֹלֵלוֹת. וְאֵין הַפֶּרֶט וְהָעוֹלֵלוֹת נוֹהֲגִין אֶלָּא בְּכֶרֶם בִּלְבַד:","אֵין הָעֲנִיִּים זוֹכִין לִקַּח פֶּרֶט וְעוֹלֵלוֹת עַד שֶׁיַּתְחִיל בַּעַל הַכֶּרֶם לִבְצֹר כַּרְמוֹ שֶׁנֶּאֱמַר (דברים כד כא) \"וְכִי תִבְצֹר כַּרְמְךָ לֹא תְעוֹלֵל\". וְכַמָּה יִבְצֹר וְיִהְיוּ זוֹכִין בָּהֶן שְׁלֹשָׁה אֶשְׁכּוֹלוֹת שֶׁהֵן עוֹשִׂין רְבִיעַ:","הַמַּקְדִּישׁ כַּרְמוֹ עַד שֶׁלֹּא נוֹדְעוּ הָעוֹלֵלוֹת אֵין הָעוֹלֵלוֹת לָעֲנִיִּים. וְאִם מִשֶּׁנּוֹדְעוּ הָעוֹלֵלוֹת הָעוֹלֵלוֹת לָעֲנִיִּים וְיִתְּנוּ שְׂכַר גִּדּוּלָם לַהֶקְדֵּשׁ:","הַזּוֹמֵר אֶת הַגֶּפֶן אַחַר שֶׁנּוֹדְעוּ הָעוֹלֵלוֹת הֲרֵי זֶה זוֹמֵר כְּדַרְכּוֹ וּכְשֵׁם שֶׁכּוֹרֵת הָאֶשְׁכּוֹלוֹת כָּךְ כּוֹרֵת הָעוֹלֵלוֹת:","נָכְרִי שֶׁמָּכַר כַּרְמוֹ לְיִשְׂרָאֵל לִבְצֹר חַיָּב בְּעוֹלֵלוֹת. יִשְׂרָאֵל וְנָכְרִי שֶׁהָיוּ שֻׁתָּפִים בְּכֶרֶם חֶלְקוֹ שֶׁל יִשְׂרָאֵל חַיָּב וְשֶׁל נָכְרִי פָּטוּר:","בֶּן לֵוִי שֶׁנָּתְנוּ לוֹ מַעֲשֵׂר טֶבֶל וּמָצָא בּוֹ עוֹלֵלוֹת נוֹתְנָן לְעָנִי. וְאִם נִקְרֶצֶת עִם הָאֶשְׁכּוֹל יֵשׁ לוֹ לַעֲשׂוֹת תְּרוּמַת מַעֲשֵׂר עַל מָקוֹם אַחֵר:","מִי שֶׁהָיוּ לוֹ חָמֵשׁ גְּפָנִים וּבְצָרָם לְתוֹךְ בֵּיתוֹ. אִם לֶאֱכל עֲנָבִים פָּטוּר מִן הַפֶּרֶט וּמִן הַשִּׁכְחָה וּמִן הָרְבָעִי וְחַיָּב בְּעוֹלֵלוֹת. וְאִם בְּצָרָן לַעֲשׂוֹת יַיִן חַיָּב בַּכּל אֶלָּא אִם כֵּן שִׁיֵּר מִקְצָתָן:"],"Mishneh Torah, Heave Offerings 15":["חָבִית סְתוּמָה מְדַמַּעַת בִּכָל שֶׁהוּא. כֵּיצַד. חָבִית סְתוּמָה שֶׁל תְּרוּמָה שֶׁנִּתְעָרְבָה בְּכַמָּה אֲלָפִים חָבִיּוֹת סְתוּמוֹת נִדְמַע הַכּל. נִפְתְּחוּ הֶחָבִיּוֹת תַּעֲלֶה בְּאֶחָד וּמֵאָה:","חָבִית סְתוּמָה שֶׁנִּתְעָרְבָה בַּמֵּאָה חָבִיּוֹת וְנָפְלָה אַחַת מֵהֶם לַיָּם הַגָּדוֹל הֻתְּרוּ כֻּלָּן וְאוֹמְרִין שֶׁל תְּרוּמָה הִיא שֶׁנָּפְלָה. מַה שֶּׁאֵין כֵּן בִּתְאֵנָה שֶׁנָּפְלָה לְמֵאָה וְנָפְלָה אַחַת מֵהֶן לַיָּם הַגָּדוֹל אֶלָּא צָרִיךְ לְהַפְרִישׁ אַחַת. לְפִי שֶׁהֶחָבִית נְפִילָתָהּ נִכֶּרֶת וּתְאֵנָה וְכַיּוֹצֵא בָּהּ אֵין נְפִילָתָהּ נִכֶּרֶת:","חָבִית סְתוּמָה שֶׁנִּתְעָרְבָה בְּמֵאָה חָבִיּוֹת וְנִפְתְּחָה אַחַת מֵהֶן נוֹטֵל מִמֶּנָּה אֶחָד מִמֵּאָה וְשׁוֹתֶה אוֹתָהּ הֶחָבִית. אֲבָל שְׁאָר הֶחָבִיּוֹת אֲסוּרוֹת עַד שֶׁיִּפָּתְחוּ. וְכָל אַחַת וְאַחַת שֶׁתִּפָּתַח מֵהֶן נוֹטֵל מִמֶּנָּה כְּדֵי דִּמּוּעָהּ וְשׁוֹתֶה הַמֵּאָה הַשְּׁאָר. נִתְעָרְבָה חָבִית בְּמֵאָה וַחֲמִשִּׁים חָבִיּוֹת וְנִפְתְּחוּ מֵהֶם מֵאָה נוֹטֵל מֵהֶם כְּדֵי דִּמּוּעַ חָבִית אַחַת וְשׁוֹתֶה הַמֵּאָה וּשְׁאָר הַחֲמִשִּׁים אֲסוּרוֹת וְאֵין מַחֲזִיקִין לְאוֹתָהּ חָבִית שֶׁל תְּרוּמָה שֶׁהִיא בְּרֹב אֲפִלּוּ הָיוּ כַּמָּה אֲלָפִים חָבִיּוֹת כֻּלָּן מְדֻמָּע וְכָל מַה שֶּׁיִּפְתַּח נוֹטֵל הֵימֶנּוּ אֶחָד מִמֵּאָה וְהַשְּׁיָרִים שׁוֹתֶה וְהַשְּׁאָר מְדֻמָּע:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מַאֲכָלוֹת שֶׁהַמְחַמֵּץ וְהַמְתַבֵּל אוֹסֵר בְּכָל שֶׁהוּא. לְפִיכָךְ אִם רִסֵּק תַּפּוּחַ שֶׁל תְּרוּמָה וּנְתָנוֹ לְתוֹךְ הָעִסָּה וְהֶחְמִיצָה כָּל הָעִסָּה מְדֻמַּעַת וַאֲסוּרָה לְזָרִים:","בֵּיצָה שֶׁנִּתְבְּלָה בְּתַבְלִין שֶׁל תְּרוּמָה אֲפִלּוּ חֶלְמוֹן שֶׁלָּהּ אָסוּר מִפְּנֵי שֶׁהוּא בּוֹלֵעַ:","שְׂאוֹר שֶׁל תְּרוּמָה שֶׁנָּפַל לְתוֹךְ הָעִסָּה וְהִגְבִּיהוֹ וְאַחַר כָּךְ נִתְחַמְּצָה הֲרֵי זוֹ מֻתֶּרֶת:","כְּבָר בֵּאַרְנוּ שֶׁאִם נִתְעָרֵב (תְּרוּמָה) מִין בְּשֶׁאֵינוֹ מִינוֹ בְּנוֹתֵן טַעַם לְפִיכָךְ בָּצָל מְחֻתָּךְ שֶׁנִּתְבַּשֵּׁל עִם הַתַּבְשִׁיל אִם הַבָּצָל תְּרוּמָה וְהַתַּבְשִׁיל חֻלִּין וְיֵשׁ בּוֹ טַעַם הַבָּצָל הֲרֵי הַתַּבְשִׁיל אָסוּר לְזָרִים. וְאִם הַבָּצָל חֻלִּין וְהַתַּבְשִׁיל תְּרוּמָה וְנִמְצָא טַעַם הַתַּבְשִׁיל בַּבָּצָל הֲרֵי הַבָּצָל אָסוּר:","עֲדָשִׁים שֶׁנִּתְבַּשְּׁלוּ וְאַחַר כָּךְ הִשְׁלִיךְ לְתוֹכָן בָּצָל יָבֵשׁ אִם הָיָה שָׁלֵם הֲרֵי זֶה מֻתָּר. וְאִם הָיָה מְחֻתָּךְ בְּנוֹתֵן טַעַם. וְאִם בִּשֵּׁל הַבָּצָל עִם הָעֲדָשִׁים בֵּין שָׁלֵם בֵּין מְחֻתָּךְ מְשַׁעֲרִין אוֹתוֹ בְּנוֹתֵן טַעַם. וּשְׁאָר כָּל הַתַּבְשִׁיל בֵּין שֶׁהִשְׁלִיךְ הַבָּצָל אַחַר שֶׁנִּתְבַּשֵּׁל בֵּין שֶׁבִּשְּׁלוֹ עִם הַתַּבְשִׁיל בֵּין שָׁלֵם בֵּין מְחֻתָּךְ מְשַׁעֲרִין אוֹתוֹ בְּנוֹתֵן טַעַם. וּמִפְּנֵי מָה בָּצָל שָׁלֵם לְתוֹךְ עֲדָשִׁים שֶׁנִּתְבַּשְּׁלוּ אֵין מְשַׁעֲרִין אוֹתוֹ. מִפְּנֵי שֶׁאֵינוֹ שׁוֹאֵב מֵהֶן שֶׁהֲרֵי הוּא שָׁלֵם וְלֹא פּוֹלֵט לְתוֹכָן שֶׁכְּבָר נִתְבַּשְּׁלוּ. וְאִם הָיוּ בְּצָלִים רַכִּים הֲרֵי הֵן כִּמְחֻתָּךְ. וְכֵן אִם נוֹטֵל פִּטְמָתוֹ וּקְלִפָּתוֹ הַחִיצוֹנָה אוֹ שֶׁהָיָה לַח הֲרֵי הוּא כִּמְחֻתָּךְ. וְהָקַפְלוּט בֵּין לַח בֵּין יָבֵשׁ בֵּין שָׁלֵם בֵּין מְחֻתָּךְ בְּנוֹתֵן טַעַם:","הַכּוֹבֵשׁ יָרָק שֶׁל חֻלִּין עִם יָרָק שֶׁל תְּרוּמָה הֲרֵי זֶה מֻתָּר לְזָרִים. חוּץ מִמִּינֵי בְּצָלִים וְחָצִיר וְשׁוּמִים. שֶׁאִם כָּבַשׁ יָרָק שֶׁל חֻלִּין עִם בְּצָלִים שֶׁל תְּרוּמָה אוֹ בְּצָלִים חֻלִּין עִם בְּצָלִים שֶׁל תְּרוּמָה הֲרֵי אֵלּוּ אֲסוּרִין. כָּבַשׁ יָרָק שֶׁל תְּרוּמָה עִם בָּצָל שֶׁל חֻלִּין הֲרֵי הַבָּצָל מֻתָּר לְזָרִים:","זֵיתֵי חֻלִּין שֶׁכְּבָשָׁן עִם זֵיתֵי תְּרוּמָה. אִם הָיוּ פְּצוּעִין אֵלּוּ וְאֵלּוּ. אוֹ שֶׁהָיוּ חֻלִּין פְּצוּעִין וְשֶׁל תְּרוּמָה שְׁלֵמִין. אוֹ שֶׁכְּבָשָׁן בְּמֵי תְּרוּמָה. הֲרֵי אֵלּוּ אֲסוּרִין. אֲבָל אִם הָיוּ שְׁנֵיהֶן שְׁלֵמִין. אוֹ שֶׁהָיוּ זֵיתֵי תְּרוּמָה פְּצוּעִין וְזֵיתֵי הַחֻלִּין שְׁלֵמִין. הֲרֵי אֵלּוּ מֻתָּרִין לְפִי שֶׁהַפְּצוּעִין שׁוֹאֲבוֹת מִן הַשְּׁלֵמִין:","מֵי כְּבָשִׁים וּמֵי שְׁלָקוֹת שֶׁל תְּרוּמָה הֲרֵי הֵן אֲסוּרִין לְזָרִים:","הַשֶּׁבֶת עַד שֶׁלֹּא נָתְנָה טַעַם בַּקְּדֵרָה יֵשׁ בָּהּ מִשּׁוּם תְּרוּמָה. מִשֶּׁנָּתְנָה טַעַם בַּקְּדֵרָה אֵין בָּהּ מִשּׁוּם תְּרוּמָה:","הָרוֹדֶה פַּת חַמָּה וּנְתָנָהּ עַל פִּי חָבִית שֶׁל יֵין תְּרוּמָה. אִם הָיְתָה פַּת חִטִּים הֲרֵי זוֹ מֻתֶּרֶת. וְשֶׁל שְׂעוֹרִים אֲסוּרִים מִפְּנֵי שֶׁשּׁוֹאֲבוֹת:","תַּנּוּר שֶׁהִסִּיקוֹ בְּכַמּוֹן שֶׁל תְּרוּמָה וְאָפָה בּוֹ אֶת הַפַּת הַפַּת מֻתֶּרֶת שֶׁאֵין בָּהּ טַעַם כַּמּוֹן אֶלָּא רֵיחוֹ וְהָרֵיחַ אֵינוֹ אָסוּר:","שְׂעוֹרִין שֶׁל תְּרוּמָה שֶׁנָּפְלוּ לְבוֹר שֶׁל מַיִם אַף עַל פִּי שֶׁהִבְאִישׁוּ מֵימָיו הֲרֵי הֵן מֻתָּרִין שֶׁאֵין נוֹתֵן טַעַם לִפְגָם אוֹסֵר:","תִּלְתָּן שֶׁל תְּרוּמָה הוּא וְעֵצוֹ שֶׁנָּפַל לְתוֹךְ בּוֹר שֶׁל יַיִן אִם יֵשׁ בְּזֶרַע הַתִּלְתָּן כְּדֵי לִתֵּן לְבַדּוֹ טַעַם בַּיַּיִן הֲרֵי הַיַּיִן אָסוּר לְזָרִים:","שְׁנֵי כּוֹסוֹת שֶׁל יַיִן אֶחָד תְּרוּמָה וְאֶחָד חֻלִּין מָזַג כָּל אֶחָד בְּמַיִם וְאַחַר כָּךְ עֵרְבָן. רוֹאִין אֶת יֵין הַחֻלִּין כְּאִלּוּ אֵינוֹ וּכְאִלּוּ יֵין הַתְּרוּמָה שֶׁנִּתְעָרֵב בְּמַיִם שֶׁהֲרֵי אֵינוֹ מִינוֹ. אִם רָאוּי אוֹתוֹ הַמַּיִם לְבַטֵּל טַעַם יֵין הַתְּרוּמָה הֲרֵי הַכּל מֻתָּר לְזָרִים. וְאִם לָאו אָסוּר. שֶׁכְּבָר בֵּאַרְנוּ שֶׁאֵין הַמַּיִם מַעֲלִין אֶת הַיַּיִן:","יַיִן שֶׁל תְּרוּמָה שֶׁנָּפַל עַל גַּבֵּי פֵּרוֹת יְדִיחֵם וְהֵם מֻתָּרוֹת. וְכֵן שֶׁמֶן שֶׁל תְּרוּמָה שֶׁנָּפַל עַל גַּבֵּי פֵּרוֹת יְדִיחֵם וְהֵם מֻתָּרוֹת. נָפַל הַשֶּׁמֶן עַל גַּבֵּי יַיִן יַקְפֶּה אוֹתוֹ וְהַיַּיִן מֻתָּר לְזָרִים. נָפַל עַל גַּבֵּי הַצִּיר יַקְפֶּה אוֹתוֹ וְיִטּל קְלִפָּה מֵעַל הַצִּיר כְּדֵי שֶׁיָּסִיר כָּל הַצִּיר שֶׁבּוֹ טַעַם הַשֶּׁמֶן:","קְדֵרָה שֶׁבִּשֵּׁל בָּהּ תְּרוּמָה לֹא יְבַשֵּׁל בָּהּ חֻלִּין. וְאִם בִּשֵּׁל בְּנוֹתֵן טַעַם. וְאִם שָׁטַף הַקְּדֵרָה בְּמַיִם אוֹ בְּיַיִן הֲרֵי זֶה מֻתָּר לְבַשֵּׁל בָּהּ. בִּשֵּׁל בְּמִקְצָת הַכְּלִי אֵין צָרִיךְ לִשְׁטֹף אֶת כֻּלּוֹ אֶלָּא שׁוֹטֵף מְקוֹם הַבִּשּׁוּל בִּלְבַד:","תְּרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר וְהַחַלָּה וְהַבִּכּוּרִים כֻּלָּן נִקְרְאוּ תְּרוּמָה. בִּתְרוּמַת מַעֲשֵׂר נֶאֱמַר (במדבר יח כו) \"וַהֲרֵמֹתֶם מִמֶּנּוּ תְּרוּמַת ה'\" וְאוֹמֵר (במדבר טו כ) \"כִּתְרוּמַת גֹּרֶן\". וּבְחַלָּה נֶאֱמַר (במדבר טו כ) \"חַלָּה תָּרִימוּ תְרוּמָה\". וְנֶאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ\" וְגוֹ' (דברים יב יז) \"וּתְרוּמַת יָדְךָ\". וְאֵין לְךָ דָּבָר שֶׁטָּעוּן הֲבָאַת מָקוֹם שֶׁלֹּא פֵּרְטוֹ בְּפָסוּק זֶה חוּץ מִן הַבִּכּוּרִים וּבָהֶן נֶאֱמַר וּתְרוּמַת יָדְךָ הָא לָמַדְתָּ שֶׁהֵן קְרוּאִין תְּרוּמָה:","לְפִיכָךְ דִּין אַרְבַּעְתָּן לְעִנְיַן אֲכִילָה וְדִמּוּעַ אֶחָד הוּא כֻּלָּן עוֹלִין בְּאֶחָד וּמֵאָה וּמִצְטָרְפִין זֶה עִם זֶה וְאִם נִטְמְאוּ יִשָּׂרְפוּ. וְדִין תְּרוּמַת מַעֲשֵׂר שֶׁל דְּמַאי בְּכָל אֵלּוּ הַדְּרָכִים כִּתְרוּמַת מַעֲשֵׂר שֶׁל וַדַּאי אֶלָּא שֶׁאֵין לוֹקִין עַל אֲכִילָתָהּ:","כָּל הָאוֹכֵל תְּרוּמָה מְבָרֵךְ בִּרְכַּת אוֹתוֹ מַאֲכָל וְאַחַר כָּךְ מְבָרֵךְ אֲשֶׁר קִדְּשָׁנוּ בִּקְדֻשָּׁתוֹ שֶׁל אַהֲרֹן וְצִוָּנוּ לֶאֱכל תְּרוּמָה. וְכָךְ קִבַּלְנוּ וְרָאִינוּ אוֹתָם מְבָרְכִין אֲפִלּוּ בְּחַלַּת חוּצָה לָאָרֶץ שֶׁגַּם אֲכִילַת קָדְשֵׁי הַגְּבוּל כַּעֲבוֹדָה שֶׁנֶּאֱמַר (במדבר יח ז) \"עֲבוֹדַת מַתָּנָה אֶתֵּן אֶת כְּהֻנַּתְכֶם\": סָלִיק הִלְכוֹת תְּרוּמוֹת בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Hiring 12":["הַפּוֹעֲלִים שֶׁהֵן עוֹשִׂין בְּדָבָר שֶׁגִּדּוּלוֹ מִן הָאָרֶץ וַעֲדַיִן לֹא נִגְמְרָה מְלַאכְתּוֹ בֵּין בְּתָלוּשׁ בֵּין בִּמְחֻבָּר וְיִהְיוּ מַעֲשֵׂיהֶן גְּמִירַת הַמְּלָאכָה הֲרֵי עַל בַּעַל הַבַּיִת מִצְוָה שֶׁיַּנִּיחַ אוֹתָן לֶאֱכל מִמַּה שֶּׁהֵן עוֹשִׂין בּוֹ. שֶׁנֶּאֱמַר (דברים כג כה) \"כִּי תָבֹא בְּכֶרֶם רֵעֶךָ\" וְגוֹ' וְכָתוּב (דברים כג כו) \"כִּי תָבֹא בְּקָמַת רֵעֶךָ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵין הַכָּתוּב מְדַבֵּר אֶלָּא בְּשָׂכִיר וְכִי אִלּוּ לֹא שְׂכָרוֹ מִי הִתִּיר לוֹ שֶׁיָּבוֹא בְּכֶרֶם רֵעֵהוּ בַּקָּמָה שֶׁלּוֹ שֶׁלֹּא מִדַּעְתּוֹ אֶלָּא כָּךְ הוּא אוֹמֵר כִּי תָבֹא לִרְשׁוּת בְּעָלִים לַעֲבוֹדָה תֹּאכַל:","מַה בֵּין הָעוֹשֶׂה בְּתָלוּשׁ לְעוֹשֶׂה בִּמְחֻבָּר. שֶׁהָעוֹשֶׂה בְּתָלוּשׁ אוֹכֵל בַּדָּבָר עַד שֶׁלֹּא נִגְמַר מְלַאכְתּוֹ וּמִשֶּׁתִּגָּמֵר מְלַאכְתּוֹ אָסוּר לוֹ לֶאֱכל. וְהָעוֹשֶׂה בִּמְחֻבָּר כְּגוֹן בּוֹצֵר וְקוֹצֵר אֵינוֹ אוֹכֵל אֶלָּא כְּשֶׁיִּגְמֹר עֲבוֹדָתוֹ כְּגוֹן שֶׁיִּבְצֹר וְיִתֵּן בַּסַּל עַד שֶׁיְּמַלְּאֶנּוּ וִינַפֵּץ הַסַּל לְמָקוֹם אַחֵר וְיַחְזֹר וְיִבְצֹר וִימַלְּאֶנּוּ וְאֵינוֹ אוֹכֵל אֶלָּא עַד אַחַר שֶׁיְּמַלֵּא הַסַּל. אֲבָל מִפְּנֵי הֶשֵּׁב אֲבֵדָה לַבְּעָלִים אָמְרוּ חֲכָמִים שֶׁיִּהְיוּ הַפּוֹעֲלִין אוֹכְלִין בַּהֲלִיכָתָן מֵאֹמֶן לְאֹמֶן וּבַחֲזִירָתָן מִן הַגַּת כְּדֵי שֶׁלֹּא יִבָּטְלוּ מִמְּלַאכְתָּן וְיֵשְׁבוּ לֶאֱכל אֶלָּא אוֹכְלִין בְּתוֹךְ הַמְּלָאכָה כְּשֶׁהֵן מְהַלְּכִין וְאֵינָן מְבַטְּלִין:","הַמְבַטֵּל מִמְּלַאכְתּוֹ וְאָכַל אוֹ שֶׁאָכַל שֶׁלֹּא בִּשְׁעַת גְּמַר מְלָאכָה הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כג כו) \"וְחֶרְמֵשׁ לֹא תָנִיף\" וְגוֹ'. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁכָּל זְמַן שֶׁהוּא עוֹסֵק בִּקְצִירָה לֹא יָנִיף חֶרְמֵשׁ לַאֲכִילָתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן פּוֹעֵל שֶׁהוֹלִיךְ בְּיָדוֹ מִמַּה שֶּׁעָשָׂה אוֹ שֶׁלָּקַח יֶתֶר עַל אֲכִילָתוֹ וְנוֹתֵן לַאֲחֵרִים עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כג כה) \"וְאֶל כֶּלְיְךָ לֹא תִתֵּן\". וְאֵין לוֹקִין עַל שְׁנֵי לָאוִין אֵלּוּ שֶׁאִם אָכַל אוֹ הוֹלִיךְ חַיָּב לְשַׁלֵּם:","הַחוֹלֵב וְהַמְחַבֵּץ וְהַמְגַבֵּן אֵינוֹ אוֹכֵל מִפְּנֵי שֶׁאֵינָן גִּדּוּלֵי קַרְקַע. הַמְנַכֵּשׁ בִּבְצָלִים וּבְשׁוּמִין אַף עַל פִּי שֶׁתּוֹלְשִׁין קְטַנִּים מִבֵּין הַגְּדוֹלִים וְכָל כַּיּוֹצֵא בָּזֶה אֵינוֹ אוֹכֵל מִפְּנֵי שֶׁאֵין מַעֲשֵׂיהֶם גְּמַר מְלָאכָה. וְאֵין צָרִיךְ לוֹמַר שׁוֹמְרֵי גִּנּוֹת וּפַרְדֵּסִים וְכָל דָּבָר הַמְחֻבָּר כַּמִּקְשָׁאוֹת וְהַמִּדְלָעוֹת שֶׁאֵין אוֹכְלִין כְּלָל:","הַבּוֹדֵל בִּתְמָרִים וּבִגְרוֹגָרוֹת אֵינוֹ אוֹכֵל מִפְּנֵי שֶׁנִּגְמְרָה מְלַאכְתָּן לְמַעֲשֵׂר. הָעוֹשֶׂה בְּחִטִּים וְכַיּוֹצֵא בָּהֶן אַחַר שֶׁעָשׂוּ כְּגוֹן שֶׁשְּׂכָרָן לָבוּר צְרוֹרוֹת אוֹ לְנַפֵּחַ אוֹתָן אוֹ לִטְחֹן הֲרֵי אֵלּוּ אוֹכְלִין שֶׁעֲדַיִן לֹא נִגְמְרָה מְלַאכְתָּן לְחַלָּה. אֲבָל הַלָּשׁ וְהַמְקַטֵּף וְהָאוֹפֶה אֵינוֹ אוֹכֵל מִפְּנֵי שֶׁנִּגְמְרָה מְלַאכְתָּן לְחַלָּה וְאֵין הַפּוֹעֵל אוֹכֵל אֶלָּא מִדָּבָר שֶׁעֲדַיִן לֹא נִגְמְרָה מְלַאכְתּוֹ לְחַלָּה וּלְמַעֲשֵׂר:","נִתְפָּרְסוּ עִגּוּלָיו וְנִתְפַּתְּחוּ חָבִיּוֹתָיו [וְנֶחְתְּכוּ דְּלוּעָיו] וּשְׂכָרָן לַעֲשׂוֹת בָּהֶן הֲרֵי אֵלּוּ לֹא יֹאכְלוּ שֶׁהֲרֵי נִגְמְרוּ מְלַאכְתָּן וְנִקְבְּעוּ לְמַעֲשֵׂר וַהֲרֵי הֵן טֶבֶל. וְאִם לֹא הוֹדִיעָן מְעַשֵּׂר וּמַאֲכִילָן. אֵין הַפּוֹעֲלִים אוֹכְלִין בְּשֶׁל הֶקְדֵּשׁ שֶׁנֶּאֱמַר (דברים כג כה) \"בְּכֶרֶם רֵעֶךָ\":","שָׂכַר פּוֹעֲלִין לַעֲשׂוֹת בְּנֶטַע רְבָעִי שֶׁלּוֹ הֲרֵי אֵלּוּ לֹא יֹאכְלוּ. וְאִם לֹא הוֹדִיעָם פּוֹדֶה וּמַאֲכִילָן:","הַקּוֹצֵר וְהַדָּשׁ וְהַזּוֹרֶה וְהַבּוֹרֵר וְהַמּוֹסֵק וְהַבּוֹצֵר וְהַדּוֹרֵךְ וְכָל כַּיּוֹצֵא בִּמְלָאכוֹת אֵלּוּ הֲרֵי הֵם אוֹכְלִין מִן הַתּוֹרָה:","שׁוֹמְרֵי גִּתּוֹת וַעֲרֵמוֹת וְכָל דָּבָר הַתָּלוּשׁ מִן הַקַּרְקַע שֶׁעֲדַיִן לֹא נִגְמְרָה מְלַאכְתָּן לְמַעֲשֵׂר אוֹכְלִין מֵהִלְכוֹת מְדִינָה שֶׁהַשּׁוֹמֵר אֵינוֹ כְּעוֹשֶׂה מַעֲשֶׂה. אֲבָל אִם עָשָׂה בְּאֵיבָרָיו בֵּין בְּיָדָיו בֵּין בְּרַגְלָיו אֲפִלּוּ בִּכְתֵפָיו הֲרֵי זֶה אוֹכֵל מִן הַתּוֹרָה:","הָיָה עוֹשֶׂה בִּתְאֵנִים לֹא יֹאכַל בַּעֲנָבִים בַּעֲנָבִים לֹא יֹאכַל בִּתְאֵנִים שֶׁנֶּאֱמַר (דברים כג כה) \"בְּכֶרֶם\" \"וְאָכַלְתָּ עֲנָבִים\". וְהָעוֹשֶׂה בְּגֶפֶן זוֹ אֵינוֹ אוֹכֵל בְּגֶפֶן אַחֶרֶת. וְלֹא יֹאכַל עֲנָבִים וְדָבָר אַחֵר. וְלֹא יֹאכַל בְּפַת וְלֹא בְּמֶלַח וְאִם קָצַץ עַל בַּעַל הַבַּיִת עַל שִׁעוּר מַה שֶּׁיֹּאכַל אוֹכֵל אוֹתוֹ בֵּין בְּמֶלַח בֵּין בְּפַת בֵּין בְּכָל דָּבָר שֶׁיִּרְצֶה. אָסוּר לְפוֹעֵל לָמֹץ בַּעֲנָבִים שֶׁנֶּאֱמַר וְאָכַלְתָּ עֲנָבִים. וְלֹא יִהְיוּ בָּנָיו אוֹ אִשְׁתּוֹ מְהַבְהֲבִין לוֹ הַשִּׁבֳּלִין בָּאוּר שֶׁנֶּאֱמַר (דברים כג כה) \"וְאָכַלְתָּ עֲנָבִים כְּנַפְשְׁךָ\" עֲנָבִים כְּמוֹת שֶׁהֵן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אָסוּר לַפּוֹעֵל לֶאֱכל מִמַּה שֶּׁהוּא אוֹכֵל אֲכִילָה גַּסָּה שֶׁנֶּאֱמַר כְּנַפְשְׁךָ שָׂבְעֶךָ. וּמֻתָּר לוֹ לִמְנֹעַ אֶת עַצְמוֹ עַד מְקוֹם הַיָּפוֹת וְאוֹכֵל. וְיֵשׁ לוֹ לֶאֱכל קִישׁוּת אֲפִלּוּ בְּדִינָר וְכוֹתֶבֶת אֲפִלּוּ בְּדִינָר אַף עַל פִּי שֶׁשְּׂכָרוֹ בְּמָעָה כֶּסֶף שֶׁנֶּאֱמַר (דברים כג כה) \"כְּנַפְשְׁךָ שָׂבְעֶךָ\". אֲבָל מְלַמְּדִין אֶת הָאָדָם שֶׁלֹּא יִהְיֶה רְעַבְתָּן וְיִהְיֶה סוֹתֵם אֶת הַפֶּתַח בְּפָנָיו. הָיָה מְשַׁמֵּר אַרְבַּע אוֹ חָמֵשׁ עֲרֵמוֹת לֹא יְמַלֵּא כְּרֵסוֹ מֵאַחַת מֵהֶן אֶלָּא אוֹכֵל מִכָּל אַחַת וְאַחַת לְפִי חֶשְׁבּוֹן:","הַפּוֹעֲלִים שֶׁלֹּא הָלְכוּ שְׁתִי וָעֵרֶב בַּגַּת אוֹכְלִין עֲנָבִים וְאֵין שׁוֹתִין יַיִן שֶׁעֲדַיִן אֵינָן עוֹשִׂין אֶלָּא בַּעֲנָבִים בִּלְבַד. וּמִשֶּׁיִּדְרְכוּ בַּגַּת וִיהַלְּכוּ בָּהּ שְׁתִי וָעֵרֶב יֵשׁ לָהֶן לֶאֱכל מִן הָעֲנָבִים וְלִשְׁתּוֹת מִן הַתִּירוֹשׁ שֶׁהֲרֵי הֵן עוֹשִׂין בָּעֲנָבִים וּבַיַּיִן:","פּוֹעֵל שֶׁאָמַר תְּנוּ לְאִשְׁתִּי וּבָנַי מַה שֶּׁאֲנִי אוֹכֵל אוֹ שֶׁאָמַר הֲרֵינִי נוֹתֵן מְעַט מִזֶּה שֶׁנָּטַלְתִּי לֶאֱכל לְאִשְׁתִּי וּבָנַי אֵין שׁוֹמְעִין לוֹ שֶׁלֹּא זִכְּתָה תּוֹרָה אֶלָּא לַפּוֹעֵל עַצְמוֹ. אֲפִלּוּ נָזִיר שֶׁהָיָה עוֹשֶׂה בָּעֲנָבִים וְאָמַר תְּנוּ לְאִשְׁתִּי וּבָנַי אֵין שׁוֹמְעִין לוֹ:","פּוֹעֵל שֶׁהָיָה עוֹשֶׂה הוּא וְאִשְׁתּוֹ וּבָנָיו וַעֲבָדָיו וְהִתְנָה עִם הַבַּעַל הַבַּיִת שֶׁלֹּא יֹאכְלוּ מִמַּה שֶּׁהֵן עוֹשִׂין לֹא הוּא וְלֹא הֵם הֲרֵי אֵלּוּ אֵינָן אוֹכְלִין. בַּמֶּה דְּבָרִים אֲמוּרִים בִּגְדוֹלִים מִפְּנֵי שֶׁיֵּשׁ בָּהֶם דַּעַת וַהֲרֵי מָחֲלוּ אֲבָל קְטַנִּים אֵינוֹ יָכוֹל לִפְסֹק עֲלֵיהֶם שֶׁלֹּא יֹאכְלוּ שֶׁאֵינָן אוֹכְלִין מִשֶּׁל אֲבִיהֶן אוֹ מִשֶּׁל אֲדוֹנֵיהֶם אֶלָּא מִשֶּׁל שָׁמַיִם:"],"Mishneh Torah, Human Dispositions 3":["שֶׁמָּא יֹאמַר אָדָם הוֹאִיל וְהַקִּנְאָה וְהַתַּאֲוָה וְהַכָּבוֹד וְכַיּוֹצֵא בָּהֶם דֶּרֶךְ רָעָה הֵן וּמוֹצִיאִין אֶת הָאָדָם מִן הָעוֹלָם. אֶפְרשׁ מֵהֶן בְּיוֹתֵר וְאֶתְרַחֵק לַצַּד הָאַחֲרוֹן. עַד שֶׁלֹּא יֹאכַל בָּשָׂר וְלֹא יִשְׁתֶּה יַיִן וְלֹא יִשָּׂא אִשָּׁה וְלֹא יֵשֵׁב בְּדִירָה נָאָה וְלֹא יִלְבַּשׁ מַלְבּוּשׁ נָאֶה אֶלָּא הַשַּׂק וְהַצֶּמֶר הַקָּשֶׁה וְכַיּוֹצֵא בָּהֶן כְּגוֹן כֹּהֲנֵי הָעוֹבְדֵי כּוֹכָבִים. גַּם זֶה דֶּרֶךְ רָעָה הִיא וְאָסוּר לֵילֵךְ בָּהּ. הַמְהַלֵּךְ בְּדֶרֶךְ זוֹ נִקְרָא חוֹטֵא. שֶׁהֲרֵי הוּא אוֹמֵר בְּנָזִיר (במדבר ו יא) \"וְכִפֶּר עָלָיו מֵאֲשֶׁר חָטָא עַל הַנָּפֶשׁ\". אָמְרוּ חֲכָמִים וּמָה אִם נָזִיר שֶׁלֹּא פֵּרַשׁ אֶלָּא מִן הַיַּיִן צָרִיךְ כַּפָּרָה הַמּוֹנֵעַ עַצְמוֹ מִכָּל דָּבָר וְדָבָר עַל אַחַת כַּמָּה וְכַמָּה. לְפִיכָךְ צִוּוּ חֲכָמִים שֶׁלֹּא יִמְנַע אָדָם עַצְמוֹ אֶלָּא מִדְּבָרִים שֶׁמְּנַעְתּוֹ הַתּוֹרָה בִּלְבַד. וְלֹא יְהֵא אוֹסֵר עַצְמוֹ בִּנְדָרִים וּבִשְׁבוּעוֹת עַל דְּבָרִים הַמֻּתָּרִים. כָּךְ אָמְרוּ חֲכָמִים לֹא דַּיֶּךָ מַה שֶּׁאָסְרָה תּוֹרָה אֶלָּא שֶׁאַתָּה אוֹסֵר עָלֶיךָ דְּבָרִים אֲחֵרִים. וּבַכְּלָל הַזֶּה אֵלּוּ שֶׁמִּתְעַנִּין תָּמִיד אֵינָן בְּדֶרֶךְ טוֹבָה. וְאָסְרוּ חֲכָמִים שֶׁיְּהֵא אָדָם מְסַגֵּף עַצְמוֹ בְּתַעֲנִית. וְעַל כָּל הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן צִוָּה שְׁלֹמֹה וְאָמַר (קהלת ז טז) \"אַל תְּהִי צַדִּיק הַרְבֵּה וְאַל תִּתְחַכַּם יוֹתֵר לָמָּה תִּשּׁוֹמֵם\":","צָרִיךְ הָאָדָם שֶׁיְּכַוִּן לִבּוֹ וְכָל מַעֲשָׂיו כֻּלָּם לֵידַע אֶת הַשֵּׁם בָּרוּךְ הוּא בִּלְבַד, וְיִהְיֶה שִׁבְתּוֹ וְקוּמוֹ וְדִבּוּרוֹ הַכּל לְעֻמַּת זֶה הַדָּבָר. כֵּיצַד? כְּשֶׁיִּשָּׂא וְיִתֵּן אוֹ יַעֲשֶׂה מְלָאכָה לִטּל שָׂכָר, לֹא יִהְיֶה בְּלִבּוֹ לִקְבֹּץ מָמוֹן בִּלְבַד, אֶלָּא יַעֲשֶׂה דְּבָרִים הָאֵלּוּ כְּדֵי שֶׁיִּמְצָא דְּבָרִים שֶׁהַגּוּף צָרִיךְ לָהֶם מֵאֲכִילָה וּשְׁתִיָּה וִישִׁיבַת בַּיִת וּנְשִׂיאַת אִשָּׁה. וְכֵן כְּשֶׁיֹּאכַל וְיִשְׁתֶּה וְיִבְעל לֹא יָשִׂים בְּלִבּוֹ לַעֲשׂוֹת דְּבָרִים הָאֵלּוּ כְּדֵי לֵהָנוֹת בִּלְבַד עַד שֶׁנִּמְצָא שֶׁאֵינוֹ אוֹכֵל וְשׁוֹתֶה אֶלָּא הַמָּתוֹק לַחֵךְ וְיִבְעל כְּדֵי לֵהָנוֹת, אֶלָּא יָשִׂים עַל לִבּוֹ שֶׁיֹּאכַל וְיִשְׁתֶּה כְּדֵי לְהַבְרוֹת גּוּפוֹ וְאֵיבָרָיו בִּלְבַד. לְפִיכָךְ לֹא יֹאכַל כָּל שֶׁהַחֵךְ מִתְאַוֶּה כְּכֶלֶב וַחֲמוֹר אֶלָּא יֹאכַל דְּבָרִים הַמּוֹעִילִים לַגּוּף אִם מָרִים אִם מְתוּקִים. וְלֹא יֹאכַל דְּבָרִים הָרָעִים לַגּוּף אַף עַל פִּי שֶׁהֵן מְתוּקִים לַחֵךְ. כֵּיצַד? מִי שֶׁהָיָה בְּשָׂרוֹ חַם לֹא יֹאכַל בָּשָׂר וְלֹא דְּבַשׁ וְלֹא יִשְׁתֶּה יַיִן, כָּעִנְיָן שֶׁאָמַר שְׁלֹמֹה דֶּרֶךְ מָשָׁל (משלי כה כז) \"אָכל דְּבַשׁ\" וְגוֹ'. וְשׁוֹתֶה מֵי הָעֳלָשִׁין אַף עַל פִּי שֶׁהוּא מַר שֶׁנִּמְצָא שׁוֹתֶה וְאוֹכֵל דֶּרֶךְ רְפוּאָה בִּלְבַד כְּדֵי שֶׁיַּבְרִיא וְיַעֲמֹד שָׁלֵם הוֹאִיל וְאִי אֶפְשָׁר לָאָדָם לִחְיוֹת אֶלָּא בַּאֲכִילָה וּשְׁתִיָּה. וְכֵן כְּשֶׁיִּבְעל לֹא יִבְעל אֶלָּא כְּדֵי לְהַבְרוֹת גּוּפוֹ וּכְדֵי לְקַיֵּם אֶת הַזֶּרַע. לְפִיכָךְ אֵינוֹ בּוֹעֵל כָּל זְמַן שֶׁיִּתְאַוֶּה אֶלָּא כָּל עֵת שֶׁיֵּדַע שֶׁהוּא צָרִיךְ לְהוֹצִיא שִׁכְבַת זֶרַע כְּמוֹ דֶּרֶךְ הָרְפוּאָה אוֹ לְקַיֵּם אֶת הַזֶּרַע:","הַמַּנְהִיג עַצְמוֹ עַל פִּי הָרְפוּאָה. אִם שָׂם עַל לִבּוֹ שֶיִּהְיֶה כָּל גּוּפוֹ וְאֵיבָרָיו שְׁלֵמִים בִּלְבַד וְשֶׁיִּהְיוּ לוֹ בָּנִים עוֹשִׂין מְלַאכְתּוֹ וַעֲמֵלִין לְצָרְכּוֹ אֵין זוֹ דֶּרֶךְ טוֹבָה. אֶלָּא יָשִׂים עַל לִבּוֹ שֶׁיְּהֵא גּוּפוֹ שָׁלֵם וְחָזָק כְּדֵי שֶׁתִּהְיֶה נַפְשׁוֹ יְשָׁרָה לָדַעַת אֶת ה'. שֶׁאִי אֶפְשָׁר שֶׁיָּבִין וְיִשְׂתַּכֵּל בַּחָכְמוֹת וְהוּא רָעֵב וְחוֹלֶה אוֹ אֶחָד מֵאֵיבָרָיו כּוֹאֵב. וְיָשִׂים עַל לִבּוֹ שֶׁיִּהְיֶה לוֹ בֵּן אוּלַי יִהְיֶה חָכָם וְגָדוֹל בְּיִשְׂרָאֵל. נִמְצָא הַמְהַלֵּךְ בְּדֶרֶךְ זוֹ כָּל יָמָיו עוֹבֵד אֶת ה' תָּמִיד. אֲפִלּוּ בְּשָׁעָה שֶׁנּוֹשֵׂא וְנוֹתֵן וַאֲפִלּוּ בְּשָׁעָה שֶׁבּוֹעֵל. מִפְּנֵי שֶׁמַּחֲשַׁבְתּוֹ בַּכּל כְּדֵי שֶׁיִּמְצָא צְרָכָיו עַד שֶׁיִּהְיֶה גּוּפוֹ שָׁלֵם לַעֲבֹד אֶת ה'. וַאֲפִלּוּ בְּשָׁעָה שֶׁהוּא יָשֵׁן אִם יָשֵׁן לְדַעַת כְּדֵי שֶׁתָּנוּחַ דַּעְתּוֹ עָלָיו וְיָנוּחַ גּוּפוֹ כְּדֵי שֶׁלֹּא יֶחֱלֶה וְלֹא יוּכַל לַעֲבֹד אֶת ה' וְהוּא חוֹלֶה, נִמְצֵאת שֵׁנָה שֶׁלּוֹ עֲבוֹדָה לַמָּקוֹם בָּרוּךְ הוּא. וְעַל עִנְיָן זֶה צִוּוּ חֲכָמִים וְאָמְרוּ (משנה אבות ב יב) \"וְכָל מַעֲשֶׂיךָ יִהְיוּ לְשֵׁם שָׁמַיִם\". וְהוּא שֶׁאָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (משלי ג ו) \"בְּכָל דְּרָכֶיךָ דָעֵהוּ וְהוּא יְיַשֵּׁר אֹרְחֹתֶיךָ\":"],"Mishneh Torah, Immersion Pools 6":["כָּל הַכֵּלִים הַמְקַבְּלִין שֶׁהָלְכוּ הַמַּיִם עֲלֵיהֶן אוֹ שֶׁנָּפְלוּ מִתּוֹכָן הֲרֵי אֵלּוּ שְׁאוּבִין וּפוֹסְלִין אֶת הַמִּקְוֶה. וְהוּא שֶׁיֵּעָשׂוּ לְקַבָּלָה. אֲפִלּוּ הָיוּ כֵּלִים שֶׁאֵין מְקַבְּלִין טֻמְאָה כְּגוֹן כְּלֵי אֲבָנִים וּכְלֵי אֲדָמָה הֲרֵי אֵלּוּ פּוֹסְלִין:","כָּל כְּלִי שֶׁלֹּא נַעֲשָׂה לְקַבָּלָה אַף עַל פִּי שֶׁהוּא מְקַבֵּל אֵינוֹ פּוֹסֵל אֶת הַמִּקְוֶה. כְּגוֹן הַסִּילוֹנוֹת שֶׁהַמַּיִם נִמְשָׁכִין מֵהֶן אַף עַל פִּי שֶׁהֵן רְחָבִים בְּאֶמְצַע וּמְקַבְּלִין אֵין פּוֹסְלִין אֶת הַמִּקְוֶה בֵּין שֶׁהָיוּ שֶׁל מַתֶּכֶת אוֹ שֶׁל חֶרֶס:","הַשֹּׁקֶת שֶׁבַּסֶּלַע אֵינוֹ פּוֹסֵל אֶת הַמִּקְוֶה לְפִי שֶׁאֵינָהּ כְּלִי. אֲבָל כְּלִי שֶׁחִבְּרוֹ בַּסֶּלַע פּוֹסֵל אֶת הַמִּקְוֶה אַף עַל פִּי שֶׁחִבְּרוֹ בְּסִיד. נִקְּבָה מִלְּמַטָּה אוֹ מִן הַצַּד כִּשְׁפוֹפֶרֶת הַנּוֹד כְּשֵׁרָה וְאֵינָהּ פּוֹסֶלֶת אֶת הַמִּקְוֶה:","הַלּוֹקֵחַ כְּלִי גָּדוֹל כְּגוֹן חָבִית גְּדוֹלָה אוֹ עֲרֵבָה גְּדוֹלָה וְנִקְּבוֹ נֶקֶב הַמְטַהֲרוֹ וּקְבָעוֹ בָּאָרֶץ וַעֲשָׂאָהוּ מִקְוֶה הֲרֵי זֶה כָּשֵׁר. וְכֵן אִם פָּקַק אֶת הַנֶּקֶב בְּסִיד וּבְבִנְיָן אֵינוֹ פּוֹסֵל וְהַמַּיִם הַנִּקְוִין בְּתוֹכוֹ מִקְוֶה כָּשֵׁר. סְתָמוֹ בְּסִיד אוֹ בְּגִפְּסִיס עֲדַיִן הוּא פּוֹסֵל אֶת הַמִּקְוֶה עַד שֶׁיִּקְבָּעֶנּוּ בָּאָרֶץ אוֹ יִבְנֶה. וְאִם הוֹלִיכוֹ עַל גַּב הָאָרֶץ וְעַל גַּב הַסִּיד וּמֵרֵחַ בְּטִיט מִן הַצְּדָדִין הֲרֵי זֶה כָּשֵׁר:","הַמַּנִּיחַ טַבְלָא תַּחַת הַצִּנּוֹר וַהֲרֵי הַמַּיִם נִמְשָׁכִין עַל הַטַּבְלָא וְיוֹרְדִין לַמִּקְוֶה אִם הָיָה לַטַּבְלָא דֹּפֶן הֲרֵי זוֹ פּוֹסֶלֶת אֶת הַמִּקְוֶה וְאִם לָאו אֵינָהּ פּוֹסֶלֶת. זְקָפָהּ תַּחַת הַצִּנּוֹר כְּדֵי לַהֲדִיחָהּ אַף עַל פִּי שֶׁיֵּשׁ לָהּ דֹּפֶן אֵינָהּ פּוֹסֶלֶת שֶׁהֲרֵי לֹא עֲשָׂאָהּ לְקַבֵּל:","הַחוֹטֵט בְּצִנּוֹר מָקוֹם לְקַבֵּל בּוֹ הַצְּרוֹרוֹת הַמִּתְגַּלְגְּלִין בַּמַּיִם כְּדֵי שֶׁלֹּא יֵרְדוּ עִם הַמַּיִם אִם הָיָה הַצִּנּוֹר שֶׁל עֵץ וְחָפַר בּוֹ כָּל שֶׁהוּא פּוֹסֵל שֶׁהֲרֵי כָּל הַמַּיִם שֶׁיּוֹרְדִין בָּאִין מִתּוֹךְ כְּלִי שֶׁנַּעֲשָׂה לְקַבָּלָה. וַאֲפִלּוּ שֶׁקְּבָעוֹ אַחַר שֶׁחָקַק בּוֹ הוֹאִיל וְהָיָה עָלָיו תּוֹרַת כְּלִי כְּשֶׁהָיָה תָּלוּשׁ. אֲבָל אִם קְבָעוֹ בַּקַּרְקַע וְאַחַר כָּךְ חָקַק בּוֹ בֵּית קִבּוּל אֵינוֹ פּוֹסֵל. וְאִם הָיָה צִנּוֹר שֶׁל חֶרֶס אֵינוֹ פּוֹסֵל עַד שֶׁיִּהְיֶה בַּחֲקָק כְּדֵי לְקַבֵּל רְבִיעִית. אַף עַל פִּי שֶׁנִּתְמַלֵּא הַמָּקוֹם הֶחָקוּק שֶׁבַּצִּנּוֹר צְרוֹרוֹת הַמִּתְחַלְחֲלִין בְּתוֹכוֹ הֲרֵי הוּא בְּפִסּוּלוֹ וְאֵינוֹ כְּסָתוּם. יָרַד לְתוֹךְ הַמָּקוֹם שֶׁחָקַק עָפָר אוֹ צְרוֹרוֹת וּסְתָמוֹ וְנִכְבַּשׁ הֲרֵי זֶה כָּשֵׁר:","הַסְּפוֹג וְהַדְּלִי שֶׁהָיוּ בָּהֶן שְׁלֹשֶׁת לוֹגִין מַיִם וְנָפְלוּ לַמִּקְוֶה לֹא פְּסָלוּהוּ שֶׁלֹּא אָמְרוּ אֶלָּא שְׁלֹשֶׁת לוֹגִין שֶׁנָּפְלוּ לֹא כְּלִי שֶׁנָּפְלוּ בּוֹ מַיִם שְׁאוּבִין:","הַשִּׁדָּה וְהַתֵּבָה שֶׁבַּיָּם אֵין מַטְבִּילִין בָּהֶן אֶלָּא אִם כֵּן הָיוּ נְקוּבִים כִּשְׁפוֹפֶרֶת הַנּוֹד. וְאִם הָיוּ שַׂק אוֹ קֻפָּה מַטְבִּילִין בָּהֶן. וְכֵן הַמַּנִּיחַ שַׂק אוֹ קֻפָּה תַּחַת הַצִּנּוֹר אֵין הַמַּיִם הַנִּמְשָׁכִין מֵהֶן פּוֹסְלִין אֶת הַמִּקְוֶה:","גִּסְטְרָא טְמֵאָה שֶׁהִיא בְּתוֹךְ הַמִּקְוֶה וּשְׂפָתָהּ לְמַעְלָה מִן הַמַּיִם וְהִטְבִּיל בָּהּ הַכֵּלִים טִהֲרוּ מִטֻּמְאָתָן. אֲבָל כְּשֶׁיַּגְבִּיהֵם מִן הַמַּיִם עַד שֶׁהֵן בָּאֲוִיר הַגִּסְטְרָא מִתְטַמֵּא הַמַּיִם שֶׁעַל גַּבָּן מֵאֲוִיר הַגִּסְטְרָא וְחוֹזֵר וּמְטַמֵּא אוֹתָן. וְכֵן מַעְיָן הַיּוֹצֵא מִתַּחַת הַתַּנּוּר הַטָּמֵא וְיָרַד וְטָבַל בְּתוֹכוֹ הוּא טָהוֹר וְיָדָיו טְמֵאוֹת מֵאֲוִיר הַתַּנּוּר אֶלָּא אִם כֵּן הָיוּ הַמַּיִם לְמַעְלָה מִן הַתַּנּוּר כְּרוּם יָדָיו שֶׁנִּמְצָא כְּשֶׁטָּבַל יָדָיו לְמַעְלָה מִן הַתַּנּוּר שֶׁאֵין כְּלֵי חֶרֶס מִתְטַהֲרִין בְּמִקְוֶה כְּמוֹ שֶׁבֵּאַרְנוּ:","חָבִית מְלֵאָה מַיִם שֶׁנָּפְלָה לַיָּם אֲפִלּוּ לַיָּם הַגָּדוֹל הַטּוֹבֵל שָׁם לֹא עָלְתָה לוֹ טְבִילָה. אִי אֶפְשָׁר לִשְׁלֹשָׁה לוֹגִין שֶׁלֹּא יִהְיוּ בְּמָקוֹם אֶחָד. וְכִכָּר שֶׁל תְּרוּמָה שֶׁנָּפַל לְשָׁם נִטְמָא בַּמַּיִם הַשְּׁאוּבִין שֶׁהֲרֵי הַמַּיִם עוֹמְדִין שָׁם. אֲבָל הַנְּהָרוֹת וְכַיּוֹצֵא בָּהֶן הוֹאִיל וְהֵם נִמְשָׁכִין הֲרֵי זֶה טוֹבֵל שָׁם:","מַיִם שְׁאוּבִין שֶׁהָיוּ בְּצַד הַמִּקְוֶה אַף עַל פִּי שֶׁהַמַּיִם נוֹגְעִין בְּמֵי הַמִּקְוֶה לֹא פְּסָלוּהוּ מִפְּנֵי שֶׁהֵן כְּמִקְוֶה סָמוּךְ לְמִקְוֶה. הָיוּ הַשְּׁאוּבִין בָּאֶמְצַע פּוֹסְלִין אֶת הַמִּקְוֶה:","שְׁתֵּי בְּרֵכוֹת זוֹ לְמַעְלָה מִזּוֹ וְכֹתֶל בֵּינֵיהֶן וְהָעֶלְיוֹנָה מְלֵאָה מַיִם כְּשֵׁרִים וְהַתַּחְתּוֹנָה מְלֵאָה מַיִם שְׁאוּבִין וְנֶקֶב בַּכֹּתֶל שֶׁבֵּין הָעֶלְיוֹנָה לַתַּחְתּוֹנָה. אִם יֵשׁ כְּנֶגֶד הַנֶּקֶב שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין נִפְסְלָה הָעֶלְיוֹנָה מִפְּנֵי שֶׁהַנֶּקֶב כְּאִלּוּ הוּא בְּאֶמְצַע הָעֶלְיוֹנָה לֹא בְּצִדָּהּ:","כַּמָּה יִהְיֶה בַּנֶּקֶב וְיִהְיֶה בּוֹ שְׁלֹשָׁה לוֹגִין הַכּל לְפִי הַבְּרֵכָה. אִם הָיְתָה הַבְּרֵכָה הַתַּחְתּוֹנָה אַרְבָּעִים סְאָה צָרִיךְ שֶׁיִּהְיֶה הַנֶּקֶב אֶחָד מִשְּׁלֹשׁ מֵאוֹת וְעֶשְׂרִים לַבְּרֵכָה. הָיְתָה עֶשְׂרִים סְאָה צָרִיךְ לִהְיוֹת הַנֶּקֶב אֶחָד מִמֵּאָה וְשִׁשִּׁים לַבְּרֵכָה. וְצֵא וַחֲשֹׁב לְפִי חֶשְׁבּוֹן זֶה. שֶׁהַסְּאָה שִׁשָּׁה קַבִּין וְהַקַּב אַרְבָּעָה לוֹגִין וְהַלּוֹג שֵׁשׁ בֵּיצִים:","שְׁלֹשָׁה מִקְוָאוֹת זֶה בְּצַד זֶה בְּכָל אֶחָד מֵהֶן עֶשְׂרִים סְאָה מְכֻוָּנוֹת וְאֶחָד מֵהֶן שָׁאוּב מִן הַצַּד וְיָרְדוּ שְׁלֹשָׁה וְטָבְלוּ שְׁלָשְׁתָּן וְנֶעֶרְמוּ הַמַּיִם מִכֻּלָּן וְנִתְעָרְבוּ מִלְּמַעְלָה. הַמִּקְוָאוֹת כְּשֵׁרִים וְהַטּוֹבְלִים טְהוֹרִים שֶׁהֲרֵי נַעֲשָׂה הַכּל שִׁשִּׁים סְאָה מֵהֶן אַרְבָּעִים כְּשֵׁרִים זֶה בְּצַד זֶה וְאֵין הַמַּיִם הַשְּׁאוּבִים פּוֹסְלִין מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה כְּמוֹ שֶׁבֵּאַרְנוּ. הָיָה הַשָּׁאוּב בְּאֶמְצַע וְיָרְדוּ וְטָבְלוּ בָּהֶן וְנֶעֶרְמוּ הַמַּיִם וְנִתְעָרְבוּ הַמִּקְוָאוֹת. הֲרֵי הַמִּקְוָאוֹת כְּשֶׁהָיוּ וְהַטּוֹבְלִין טְמֵאִין כְּשֶׁהָיוּ שֶׁהֲרֵי לֹא נִתְעָרְבוּ אַרְבָּעִים סְאָה הַכְּשֵׁרִין לְפִי שֶׁאֵינָן זֶה בְּצַד זֶה שֶׁהַשָּׁאוּב מַבְדִּיל בֵּינֵיהֶן:"],"Mishneh Torah, Inheritances 7":["אֵין הַיּוֹרְשִׁין נוֹחֲלִין עַד שֶׁיָּבִיאוּ רְאָיָה בְּרוּרָה שֶׁמֵּת מוֹרִישָׁן. אֲבָל אִם שָׁמְעוּ בּוֹ שֶׁמֵּת אוֹ שֶׁבָּאוּ עַכּוּ\"ם מְשִׂיחִין לְפִי תֻּמָּן. אַף עַל פִּי שֶׁמַּשִּׂיאִין אֶת אִשְׁתּוֹ עַל פִּיהֶם וְנוֹטֵל כְּתֻבָּתָהּ אֵין הַיּוֹרְשִׁין נוֹחֲלִין עַל פִּיהֶם:","הָאִשָּׁה שֶׁבָּאת וְאָמְרָה מֵת בַּעְלִי אַף עַל פִּי שֶׁהִיא נֶאֱמֶנֶת וְתִנָּשֵׂא וְתִטּל כְּתֻבָּתָהּ אֵין הַיּוֹרְשִׁין נִכְנָסִין לַנַּחֲלָה עַל פִּיהָ. אָמְרָה מֵת בַּעְלִי וְנִתְיַבְּמָה הֲרֵי יְבָמָהּ נִכְנַס לַנַּחֲלָה עַל פִּיהָ שֶׁנֶּאֱמַר (דברים כה ו) \"יָקוּם עַל שֵׁם אָחִיו הַמֵּת\" וַהֲרֵי קָם:","מִי שֶׁטָּבַע בְּמַיִם שֶׁאֵין לָהֶם סוֹף וּבָאוּ עֵדִים שֶׁטָּבַע בִּפְנֵיהֶם וְאָבַד זִכְרוֹ. אַף עַל פִּי שֶׁאֵין מַשִּׂיאִין אֶת אִשְׁתּוֹ לְכַתְּחִלָּה הֲרֵי הַיּוֹרְשִׁין נוֹחֲלִין עַל פִּיהֶם. וְכֵן אִם בָּאוּ עֵדִים שֶׁרָאוּהוּ שֶׁנָּפַל לְגוֹב אֲרָיוֹת וּנְמֵרִים אוֹ שֶׁרָאוּהוּ צָלוּב וְהָעוֹף אוֹכֵל בּוֹ. אוֹ שֶׁנִּדְקַר בַּמִּלְחָמָה וּמֵת אוֹ שֶׁנֶּהֱרַג וְלֹא הִכִּירוּ פָּנָיו אֲבָל הָיוּ לוֹ סִימָנִים מֻבְהָקִין בְּגוּפוֹ וְהִכִּירוּ אוֹתָם. בְּכָל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן אִם אָבַד זִכְרוֹ אַחַר כָּךְ יוֹרְדִין לַנַּחֲלָה בְּעֵדוּת זוֹ אַף עַל פִּי שֶׁאֵין מַשִּׂיאִין אֶת אִשְׁתּוֹ. שֶׁאֲנִי אוֹמֵר שֶׁלֹּא הֶחְמִירוּ בִּדְבָרִים אֵלּוּ אֶלָּא מִפְּנֵי אִסּוּר כָּרֵת. אֲבָל לְעִנְיַן מָמוֹן אִם הֵעִידוּ הָעֵדִים בִּדְבָרִים שֶׁחֶזְקָתָן לְמִיתָה וְהֵעִידוּ שֶׁרָאוּ אוֹתָן הַדְּבָרִים וְאָבַד זִכְרוֹ וְאַחַר כָּךְ נִשְׁמַע שֶׁמֵּת הֲרֵי אֵלּוּ נוֹחֲלִין עַל פִּיהֶן. וְכָזֶה מַעֲשִׂים בְּכָל יוֹם בְּכָל בָּתֵּי דִּינִין וְלֹא שָׁמַעְנוּ מִי שֶׁחָלַק בְּדָבָר זֶה:","שָׁבוּי שֶׁנִּשְׁבָּה וְשָׁמְעוּ שֶׁמֵּת וְיָרְדוּ יוֹרְשָׁיו לַנַּחֲלָה וְחָלְקוּ אוֹתָהּ בֵּינֵיהֶם אֵין מוֹצִיאִין אוֹתָהּ מִיָּדָן. וְכֵן הַבּוֹרֵחַ מֵחֲמַת סַכָּנָה. אֲבָל הַיּוֹצֵא לְדַעַת שֶׁשָּׁמְעוּ בּוֹ שֶׁמֵּת וְיָרְדוּ יוֹרְשָׁיו לִנְכָסָיו וְחִלְּקוּם מוֹצִיאִין מִיָּדָן עַד שֶׁיָּבִיאוּ רְאָיָה שֶׁמֵּת מוֹרִישָׁן:","שָׁבוּי שֶׁנִּשְׁבָּה וּבָרַח מֵחֲמַת סַכָּנַת נְפָשׁוֹת חַיָּבִין בֵּית דִּין לְהִתְעַסֵּק בְּנִכְסֵיהֶן. כֵּיצַד עוֹשִׂין. כָּל הַמִּטַּלְטְלִין יִהְיוּ מֻפְקָדִין בְּיַד נֶאֱמָן עַל פִּי בֵּית דִּין וּמוֹרִידִין לְתוֹךְ הַקַּרְקָעוֹת קְרוֹבִין הָרְאוּיִין לִירֻשָּׁה כְּדֵי לַעֲבֹד אֶת הַקַּרְקָעוֹת וּלְהִתְעַסֵּק בָּהֶן עַד שֶׁיִּוָּדַע שֶׁמֵּתוּ אוֹ עַד שֶׁיָּבוֹאוּ. וְלִכְשֶׁיָּבוֹא הַשָּׁבוּי וְהַבּוֹרֵחַ שָׁמִין אֵלּוּ הַקְּרוֹבִים שֶׁהוּרְדוּ מַה שֶּׁעָשׂוּ וּמַה שֶּׁאָכְלוּ כְּמִנְהַג כָּל הָאֲרִיסִין שֶׁל אוֹתָהּ הַמְּדִינָה. וְלָמָּה לֹא יַעֲמִידוּ בֵּית דִּין אַפּוֹטְרוֹפּוֹס לְעוֹלָם בֵּין בְּמִטַּלְטְלִים בֵּין בְּקַרְקָעוֹת עַד שֶׁיָּבוֹאוּ הַבְּעָלִים אוֹ עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁמֵּתוּ. לְפִי שֶׁאֵין בֵּית דִּין חַיָּבִין לְהַעֲמִיד אַפּוֹטְרוֹפּוֹס לִגְדוֹלִים שֶׁהֵן בְּנֵי דַּעַת:","נִשְׁבָּה הַשָּׁבוּי וּבָרַח הַמְסֻכָּן וְהִנִּיחַ קָמָה לִקְצֹר וַעֲנָבִים לִבְצֹר תְּמָרִים לִגְדֹּר וְזֵיתִים לִמְסֹק. בֵּית דִּין יוֹרְדִים לִנְכָסָיו וּמַעֲמִידִין לָהֶן אַפּוֹטְרוֹפּוֹס וְקוֹצֵר וּבוֹצֵר וְגוֹדֵר וּמוֹסֵק וּמוֹכֵר הַפֵּרוֹת. וּמַנִּיחִין דְּמֵיהֶן עִם שְׁאָר הַמִּטַּלְטְלִין בְּבֵית דִּין וְאַחַר כָּךְ מוֹרִידִין הַקָּרוֹב לִנְכָסָיו. שֶׁאִם יֵרֵד תְּחִלָּה שֶׁמָּא יִתְלֹשׁ אֵלּוּ הַפֵּרוֹת שֶׁהֵן כִּתְלוּשִׁין וְיֹאכַל אוֹתָן. וְהוּא הַדִּין בַּחֲצֵרוֹת וּפֻנְדָּקִיּוֹת וַחֲנֻיּוֹת הָעֲשׂוּיוֹת לְשָׂכָר וְאֵינָן צְרִיכִין עֲבוֹדָה וְלֹא טוֹרַח וְאֵין אָדָם נוֹתֵן אוֹתָן בַּאֲרִיסוּת. אֵין מוֹרִידִין לָהֶם יוֹרֵשׁ שֶׁהֲרֵי גּוֹבֶה הַשָּׂכָר וְאוֹכֵל. אֶלָּא כֵּיצַד עוֹשִׂין. בֵּית דִּין מַעֲמִידִין לָהֶן גַּבַּאי וְיִהְיֶה הַשָּׂכָר מֻנָּח בְּבֵית דִּין עַד שֶׁיָּבִיא רְאָיָה שֶׁמֵּת אוֹ עַד שֶׁיָּבוֹא וְיִטּל שֶׁלּוֹ:","וְאֵין מוֹרִידִין הַקָּרוֹב לְעוֹלָם אֶלָּא לְשָׂדוֹת וּלְגַנּוֹת וּכְרָמִים וְכַיּוֹצֵא בָּהֶן שֶׁיִּהְיֶה בָּהֶן כְּאָרִיס כְּדֵי שֶׁלֹּא יֻפְסְדוּ וְנִמְצְאוּ בּוּרִים וּנְשַׁמִּים:","מִי שֶׁיָּצָא לְדַעַת וְהִנִּיחַ נְכָסָיו וְאֵין יָדוּעַ לְהֵיכָן הָלַךְ וְלֹא מָה אֵרַע לוֹ. אֵין מוֹרִידִין קָרוֹב לִנְכָסָיו. וְאִם יָרַד מְסַלְּקִין אוֹתוֹ. וְאֵין בֵּית דִּין צְרִיכִין לְהִטַּפֵּל בּוֹ וּלְהַעֲמִיד לוֹ אַפּוֹטְרוֹפּוֹס לֹא לַקַּרְקַע וְלֹא לַמִּטַּלְטְלִין שֶׁהֲרֵי לְדַעְתּוֹ יָצָא וְהִנִּיחַ נְכָסָיו. וְכֵיצַד יִהְיֶה דִּין נִכְסֵי זֶה. מִטַּלְטְלִין יַעַמְדוּ בְּיַד זֶה שֶׁהֵן תַּחַת יָדוֹ עַד שֶׁיָּבוֹא זֶה וְיִתְבַּע אוֹ עַד שֶׁיָּמוּת וְיִתְבְּעוּ הַיּוֹרְשִׁין:","וְהַקַּרְקָעוֹת מִי שֶׁהִנִּיחוּ שָׁכֵן אֵין לוֹקְחִין מִמֶּנּוּ שָׂכָר. וְשָׂדֶה אוֹ כֶּרֶם שֶׁהָיָה בָּהֶן אָרִיס יִשָּׁאֲרוּ כְּמוֹ שֶׁהִנִּיחוֹ עַד שֶׁיָּבוֹא. וְשָׂדֶה אוֹ כֶּרֶם שֶׁהִנִּיחָם בּוּרִים יִשָּׁאֲרוּ בּוּרִים שֶׁהֲרֵי הוּא בִּרְצוֹנוֹ אִבֵּד מָמוֹנוֹ וַאֲבֵדָה לְדַעַת אֵין אָנוּ מְצֻוִּין לְהַחְזִירָהּ:","שָׁמְעוּ בּוֹ שֶׁמֵּת הֲרֵי בֵּית דִּין מוֹצִיאִין כָּל הַמִּטַּלְטְלִין וּמַנִּיחִין אוֹתָן אֵצֶל נֶאֱמָן עַל פִּיהֶן וּמוֹרִידִין הַקָּרוֹב לַשָּׂדוֹת וְלַכְּרָמִים בָּהֶן כְּאָרִיס עַד שֶׁיָּבִיא רְאָיָה בְּרוּרָה שֶׁמֵּת אוֹ עַד שֶׁיָּבוֹא:"],"Mishneh Torah, Kings and Wars 7":["אֶחָד מִלְחֶמֶת מִצְוָה וְאֶחָד מִלְחֶמֶת הָרְשׁוּת מְמַנִּין כֹּהֵן לְדַבֵּר אֶל הָעָם בִּשְׁעַת הַמִּלְחָמָה. וּמוֹשְׁחִין אוֹתוֹ בְּשֶׁמֶן הַמִּשְׁחָה וְזֶהוּ הַנִּקְרָא מְשׁוּחַ מִלְחָמָה:","שְׁתֵּי פְּעָמִים מְדַבֵּר מְשׁוּחַ מִלְחָמָה אֶל הָעָם. אַחַת בַּסְּפַר בְּעֵת שֶׁיּוֹצְאִין קֹדֶם שֶׁיַּעַרְכוּ הַמִּלְחָמָה. אוֹמֵר לָעָם (דברים כ, ו) \"מִי הָאִישׁ אֲשֶׁר נָטַע כֶּרֶם וְלֹא חִלְּלוֹ\" וְגוֹ'. כְּשֶׁיִּשְׁמַע דְּבָרָיו יַחְזֹר מֵעוֹרְכֵי הַמִּלְחָמָה. וְאַחַת בְּעוֹרְכֵי הַמִּלְחָמָה אוֹמֵר (דברים כ, ג) \"אַל תִּירְאוּ וְאַל תַּחְפְּזוּ\":","עֵת שֶׁעוֹרְכִין הַמַּעֲרָכוֹת וְהֵם קְרֵבִים לְהִלָּחֵם. מְשׁוּחַ מִלְחָמָה עוֹמֵד בְּמָקוֹם גָּבוֹהַּ וְכָל הַמַּעֲרָכוֹת לְפָנָיו. וְאוֹמֵר לָהֶם בִּלְשׁוֹן הַקֹּדֶשׁ (דברים כ, ג) \"שְׁמַע יִשְׂרָאֵל אַתֶּם קְרֵבִים הַיּוֹם לַמִּלְחָמָה עַל אֹיְבֵיכֶם\". (דברים כ, ג) \"אַל יֵרַךְ לְבַבְכֶם אַל תִּירְאוּ וְאַל תַּחְפְּזוּ וְאַל תַּעַרְצוּ מִפְּנֵיהֶם\". (דברים כ, ד) \"כִּי ה' אֱלֹהֵיכֶם הַהלֵךְ עִמָּכֶם לְהִלָּחֵם לָכֶם עִם אֹיְבֵיכֶם לְהוֹשִׁיעַ אֶתְכֶם\". עַד כָּאן אוֹמֵר מְשׁוּחַ מִלְחָמָה וְכֹהֵן אַחֵר תַּחְתָּיו מַשְׁמִיעַ אוֹתוֹ לְכָל הָעָם בְּקוֹל רָם. וְאַחַר כָּךְ מְדַבֵּר מְשׁוּחַ מִלְחָמָה (דברים כ, ה) \"מִי הָאִישׁ אֲשֶׁר בָּנָה בַיִת חָדָשׁ\" וְגוֹ' (דברים כ, ו) \"וּמִי הָאִישׁ אֲשֶׁר נָטַע כֶּרֶם\" וְגוֹ' (דברים כ, ז) \"וּמִי הָאִישׁ אֲשֶׁר אֵרַשׂ\" וְגוֹ'. עַד כָּאן מְשׁוּחַ מִלְחָמָה מְדַבֵּר וְהַשּׁוֹטֵר מַשְׁמִיעַ לְכָל הָעָם בְּקוֹל רָם. וְאַחַר כָּךְ מְדַבֵּר הַשּׁוֹטֵר מֵעַצְמוֹ וְאוֹמֵר (דברים כ, ח) \"מִי הָאִישׁ הַיָּרֵא וְרַךְ הַלֵּבָב\" וְשׁוֹטֵר אַחֵר מַשְׁמִיעַ לְכָל הָעָם:","וְאַחַר שֶׁחוֹזְרִין כָּל הַחוֹזְרִין מֵעוֹרְכֵי הַמִּלְחָמָה. מְתַקְּנִין אֶת הַמַּעֲרָכוֹת. וּפוֹקְדִים שָׂרֵי צְבָאוֹת בְּרֹאשׁ הָעָם. וּמַעֲמִידִין מֵאָחוֹר כָּל מַעֲרָכָה וּמַעֲרָכָה שׁוֹטְרִים חֲזָקִים וְעַזִּים. וְכַשִּׁילִין שֶׁל בַּרְזֶל בִּידֵיהֶם. הָרוֹצֶה לַחְזֹר מִן הַמִּלְחָמָה הָרְשׁוּת בְּיָדָן לַחְתֹּךְ אֶת שׁוֹקוֹ. שֶׁתְּחִלַּת נְפִילָה נִיסָה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמַּחְזִירִין אֲנָשִׁים אֵלּוּ מֵעוֹרְכֵי הַמִּלְחָמָה בְּמִלְחֶמֶת הָרְשׁוּת. אֲבָל בְּמִלְחֶמֶת מִצְוָה הַכּל יוֹצְאִין וַאֲפִלּוּ חָתָן מֵחַדְרוֹ וְכַלָּה מֵחֻפָּתָהּ:","אֶחָד הַבּוֹנֶה בַּיִת לִישִׁיבָתוֹ. וְאֶחָד הַבּוֹנֶה בֵּית הַבָּקָר. בֵּית הָעֵצִים. בֵּית הָאוֹצָרוֹת. הוֹאִיל וְרָאוּי לְדִירָה. וְאֶחָד הַבּוֹנֶה. וְאֶחָד הַלּוֹקֵחַ. וְאֶחָד שֶׁנִּתָּן לוֹ בְּמַתָּנָה אוֹ הַיּוֹרֵשׁ. הֲרֵי זֶה חוֹזֵר. אֲבָל הַבּוֹנֶה [בֵּית הַתֶּבֶן] וּבֵית שַׁעַר. אַכְסַדְרָה וּמִרְפֶּסֶת. אוֹ בַּיִת שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת. אוֹ הַגּוֹזֵל בַּיִת. הֲרֵי זֶה אֵינוֹ חוֹזֵר:","אֶחָד הַנּוֹטֵעַ כֶּרֶם. וְאֶחָד הַנּוֹטֵעַ חֲמִשָּׁה אִילָנֵי מַאֲכָל. וַאֲפִלּוּ מֵחֲמֵשֶׁת מִינֵי מַאֲכָל. אֶחָד הַנּוֹטֵעַ. וְאֶחָד הַמַּבְרִיךְ וְאֶחָד הַמַּרְכִּיב הַבְרָכָה וְהַרְכָּבָה שֶׁהִיא חַיֶּבֶת בְּעָרְלָה. אֶחָד הַלּוֹקֵחַ. וְאֶחָד הַיּוֹרֵשׁ. וְאֶחָד שֶׁנִּתָּן לוֹ בְּמַתָּנָה. אֲבָל הַנּוֹטֵעַ אַרְבָּעָה אִילָנֵי מַאֲכָל. אוֹ חֲמִשָּׁה אִילָנֵי סְרָק. אוֹ שֶׁגָּזַל כֶּרֶם. אֵינוֹ חוֹזֵר עָלָיו. וְכֵן כֶּרֶם שֶׁל שְׁנֵי שֻׁתָּפִין אֵין חוֹזְרִין עָלָיו:","אֶחָד הַמְאָרֵס אֶת הַבְּתוּלָה. וְאֶחָד הַמְאָרֵס אֶת הָאַלְמָנָה. וְכֵן אִם נָפְלָה לוֹ יְבָמָה אֲפִלּוּ חֲמִשָּׁה אַחִים וּמֵת אֶחָד מֵהֶן כֻּלָּן חוֹזְרִין. קִדֵּשׁ אִשָּׁה מֵעַכְשָׁו וּלְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ וְשָׁלַם הַזְּמַן בַּמִּלְחָמָה חוֹזֵר וּבָא לוֹ:","הַמַּחֲזִיר אֶת גְּרוּשָׁתוֹ. וְהַמְאָרֵס אִשָּׁה הָאֲסוּרָה עָלָיו. כְּגוֹן אַלְמָנָה לְכֹהֵן גָּדוֹל. גְּרוּשָׁה וַחֲלוּצָה לְכֹהֵן הֶדְיוֹט. מַמְזֶרֶת וּנְתִינָה לְיִשְׂרָאֵל. בַּת יִשְׂרָאֵל לְמַמְזֵר וּלְנָתִין. אֵינוֹ חוֹזֵר:","כָּל אֵלּוּ שֶׁחוֹזְרִין מֵעוֹרְכֵי הַמִּלְחָמָה. כְּשֶׁשּׁוֹמְעִין אֶת דִּבְרֵי הַכֹּהֵן חוֹזְרִין. וּמְסַפְּקִין מַיִם וּמָזוֹן לַאֲחֵיהֶם שֶׁבַּצָּבָא. וּמְתַקְּנִין אֶת הַדְּרָכִים:","וְאֵלּוּ שֶׁאֵין יוֹצְאִין לְעוֹרְכֵי הַמִּלְחָמָה כָּל עִקָּר. וְאֵין מַטְרִיחִין אוֹתָם לְשׁוּם דָּבָר בָּעוֹלָם. הַבּוֹנֶה בַּיִת וַחֲנָכוֹ. וְהַנּוֹשֵׂא אֲרוּסָתוֹ אוֹ שֶׁיִּבֵּם. וּמִי שֶׁחִלֵּל כַּרְמוֹ. אֵין יוֹצְאִין עַד תֹּם שָׁנָה. שֶׁנֶּאֱמַר (דברים כד, ה) \"נָקִי יִהְיֶה לְבֵיתוֹ שָׁנָה אֶחָת וְשִׂמַּח אֶת אִשְׁתּוֹ אֲשֶׁר לָקָח\". מִפִּי הַקַּבָּלָה לָמְדוּ שֶׁיִּהְיֶה נָקִי שָׁנָה בֵּין לַבַּיִת שֶׁקָּנָה בֵּין לָאִשָּׁה שֶׁנָּשָׂא בֵּין לַכֶּרֶם שֶׁהִתְחִיל לֶאֱכל פִּרְיוֹ:","כָּל הַשָּׁנָה אֵין מְסַפֵּק מַיִם וּמָזוֹן. וְלֹא מְתַקֵּן דֶּרֶךְ. וְלֹא שׁוֹמֵר בַּחוֹמָה. וְלֹא נוֹתֵן לְפַסֵּי הָעִיר. וְלֹא יַעֲבֹר עָלָיו שׁוּם דָּבָר בָּעוֹלָם. שֶׁנֶּאֱמַר (דברים כד, ה) \"לֹא יֵצֵא בַּצָּבָא וְלֹא יַעֲבֹר עָלָיו לְכָל דָּבָר\" לַעֲבֹר בִּשְׁנֵי לָאוִין. לֹא לְצָרְכֵי הָעִיר וְלֹא לְצָרְכֵי הַגְּדוּד:","בָּנָה בַּיִת וְהִשְׂכִּירוֹ לַאֲחֵרִים וְהִקְדִּים לוֹ שְׂכָרוֹ הֲרֵי זֶה כְּמִי שֶׁחֲנָכוֹ. נָתַן לוֹ שְׂכָרוֹ לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ הֲרֵי הוּא כְּמִי שֶׁלֹּא חֲנָכוֹ עַד עַתָּה:","בָּנָה בַּיִת וְנָתַן בּוֹ חֲפָצָיו וְנָעַל עֲלֵיהֶם. אִם הָיָה צָרִיךְ לְבַטֵּל עַל שְׁמִירָתָן הֲרֵי זֶה כְּמִי שֶׁחֲנָכוֹ וְהִתְחִיל לֵישֵׁב בּוֹ. וְאִם אֵינָן צְרִיכִין לֵישֵׁב וּלְשָׁמְרָן הֲרֵי זֶה כְּמִי שֶׁלֹּא חֲנָכוֹ:","וְכָל הַבּוֹנֶה בַּיִת אוֹ נוֹטֵעַ כֶּרֶם בְּחוּצָה לָאָרֶץ אֵינוֹ חוֹזֵר עֲלֵיהֶן:","(דברים כ, ח) \"מִי הָאִישׁ הַיָּרֵא וְרַךְ הַלֵּבָב\" כְּמַשְׁמָעוֹ. שֶׁאֵין בְּלִבּוֹ כֹּחַ לַעֲמֹד בְּקִשְׁרֵי הַמִּלְחָמָה. וּמֵאַחַר שֶׁיִּכָּנֵס בְּקִשְׁרֵי הַמִּלְחָמָה יִשָּׁעֵן עַל מִקְוֵה יִשְׂרָאֵל וּמוֹשִׁיעוֹ בְּעֵת צָרָה וְיֵדַע שֶׁעַל יִחוּד הַשֵּׁם הוּא עוֹשֶׂה מִלְחָמָה וְיָשִׂים נַפְשׁוֹ בְּכַפּוֹ וְלֹא יִירָא וְלֹא יִפְחָד וְלֹא יַחְשֹׁב לֹא בְּאִשְׁתּוֹ וְלֹא בְּבָנָיו אֶלָּא יִמְחֶה זִכְרוֹנָם מִלִּבּוֹ וְיִפָּנֶה מִכָּל דָּבָר לַמִּלְחָמָה. וְכָל הַמַּתְחִיל לַחְשֹׁב וּלְהַרְהֵר בַּמִּלְחָמָה וּמַבְהִיל עַצְמוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה. שֶׁנֶּאֱמַר (דברים כ, ג) \"אַל יֵרַךְ לְבַבְכֶם אַל תִּירְאוּ וְאַל תַּחְפְּזוּ וְאַל תַּעַרְצוּ מִפְּנֵיהֶם\". וְלֹא עוֹד אֶלָּא שֶׁכָּל דְּמֵי יִשְׂרָאֵל תְּלוּיִין בְּצַוָּארוֹ. וְאִם לֹא נִצֵּחַ וְלֹא עָשָׂה מִלְחָמָה בְּכָל לִבּוֹ וּבְכָל נַפְשׁוֹ. הֲרֵי זֶה כְּמִי שֶׁשָּׁפַךְ דְּמֵי הַכּל. שֶׁנֶּאֱמַר (דברים כ, ח) \"וְלֹא יִמַּס אֶת לְבַב אֶחָיו כִּלְבָבוֹ\". וַהֲרֵי מְפֹרָשׁ בַּקַּבָּלָה (ירמיה מח, י) \"אָרוּר עשֶֹׁה מְלֶאכֶת ה' רְמִיָּה\" וְאָרוּר מֹנֵעַ חַרְבּוֹ מִדָּם. וְכָל הַנִּלְחָם בְּכָל לִבּוֹ בְּלֹא פַּחַד וְתִהְיֶה כַּוָּנָתוֹ לְקַדֵּשׁ אֶת הַשֵּׁם בִּלְבַד. מֻבְטָח לוֹ שֶׁלֹּא יִמְצָא נֵזֶק וְלֹא תַּגִּיעֵהוּ רָעָה. וְיִבְנֶה לוֹ בַּיִת נָכוֹן בְּיִשְׂרָאֵל וְיִזְכֶּה לוֹ וּלְבָנָיו עַד עוֹלָם וְיִזְכֶּה לְחַיֵּי הָעוֹלָם הַבָּא. שֶׁנֶּאֱמַר (שמואל א כה, כח) \"כִּי עָשֹׂה יַעֲשֶׂה ה' לַאדֹנִי בַּיִת נֶאֱמָן כִּי מִלְחֲמוֹת ה' אֲדֹנִי נִלְחָם וְרָעָה לֹא תִמָּצֵא בְךָ\" וְגוֹ' (שמואל א כה, כט) \"וְהָיְתָה נֶפֶשׁ אֲדֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים אֵת ה' אֱלֹהֶיךָ\":"],"Mishneh Torah, Levirate Marriage and Release 1":["מִצְוַת עֲשֵׂה מִן הַתּוֹרָה שֶׁיְּיַבֵּם אָדָם אֵשֶׁת אָחִיו מֵאָבִיו בֵּין מִן הַנִּשּׂוּאִין בֵּין מִן הָאֵרוּסִין אִם מֵת בְּלֹא זֶרַע שֶׁנֶּאֱמַר (דברים כה ה) ״וּבֵן אֵין לוֹ״‎‎ (דברים כה ה) ״יְבָמָהּ יָבֹא עָלֶיהָ״‎‎. וּמִן הַתּוֹרָה אֵין צָרִיךְ לְקַדֵּשׁ יְבִמְתּוֹ שֶׁזּוֹ אִשְׁתּוֹ הִיא שֶׁהִקְנוּ אוֹתָהּ לוֹ מִן הַשָּׁמַיִם אֶלָּא יָבוֹא עָלֶיהָ. וּכְתֻבָּתָהּ עַל נִכְסֵי בַּעְלָהּ שֶׁמֵּת:","לֹא רָצָה לְיַבֵּם אוֹ שֶׁלֹּא רָצְתָה הִיא. הֲרֵי זֶה חוֹלֵץ לָהּ וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לְהִנָּשֵׂא לְאַחֵר. וּמִצְוַת עֲשֵׂה מִן הַתּוֹרָה לַחֲלֹץ אִם לֹא רָצָה לְיַבֵּם שֶׁנֶּאֱמַר (דברים כה ט) ״וְחָלְצָה נַעֲלוֹ״‎‎ וְגוֹ'. וּמִצְוַת יִבּוּם קוֹדֶמֶת לְמִצְוַת חֲלִיצָה:","זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (דברים כה ה) ״וּבֵן אֵין לוֹ״‎‎ אֶחָד הַבֵּן וְאֶחָד הַבַּת אוֹ זֶרַע הַבֵּן אוֹ זֶרַע הַבַּת הוֹאִיל וְיֵשׁ לוֹ זֶרַע מִכָּל מָקוֹם. וּבֵין מֵאִשָּׁה זוֹ בֵּין מֵאַחֶרֶת הֲרֵי זֶה פּוֹטֵר אֶת אִשְׁתּוֹ מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. אֲפִלּוּ הָיָה לוֹ זֶרַע מַמְזֵר אוֹ עוֹבֵד עֲבוֹדָה זָרָה הֲרֵי זֶה פּוֹטֵר אֶת אִשְׁתּוֹ מִן הַחֲלִיצָה וּמִן הַיִּבּוּם:","אֲבָל בְּנוֹ מִן הַשִּׁפְחָה וּמִן הַכּוּתִית אֵינוֹ פּוֹטֵר אֶת אִשְׁתּוֹ שֶׁזֶּרַע הַבָּא מִן הַשִּׁפְחָה עֲבָדִים וְהַבָּא מִן כּוּתִית כּוּתִי וּכְאִלּוּ אֵינָם. הֲרֵי הוּא אוֹמֵר בְּשִׁפְחָה (שמות כא ד) ״הָאִשָּׁה וִילָדֶיהָ תִּהְיֶה לַאדֹנֶיהָ״‎‎ מְלַמֵּד שֶׁוְּלָדָהּ כְּמוֹתָהּ. וּבְכוּתִית הוּא אוֹמֵר (דברים ז ד) ״כִּי יָסִיר אֶת בִּנְךָ מֵאַחֲרַי״‎‎ מֵסִיר אוֹתוֹ מִלֵּחָשֵׁב בַּקָּהָל. וְאַף עַל פִּי שֶׁנִּשְׁתַּחְרֵר בְּנוֹ מִן הַשִּׁפְחָה אוֹ נִתְגַּיֵּר בְּנוֹ מִן הַכּוּתִית הֲרֵי הֵן כִּשְׁאָר הַגֵּרִים וְהַמְשֻׁחְרָרִין וְאֵינָם פּוֹטְרִין אֶת אִשְׁתּוֹ. הֲרֵי שֶׁהָיָה לוֹ בֵּן מִן הַשִּׁפְחָה שֶׁלּוֹ וְשִׁחְרְרוֹ וְשִׁחְרְרָהּ וּנְשָׂאָהּ וּמֵת בְּלֹא זֶרַע הֲרֵי זוֹ תִּתְיַבֵּם לְאָחִיו וְאַף עַל פִּי שֶׁבְּנָהּ מִמֶּנּוּ קַיָּם שֶׁכְּבָר שִׁחְרְרוֹ:","מִי שֶׁמֵּת וְהִנִּיחַ אִשְׁתּוֹ מְעֻבֶּרֶת. אִם הִפִּילָה אַחַר מוֹתוֹ הֲרֵי זוֹ תִּתְיַבֵּם. וְאִם יָלְדָה וְיָצָא הַוָּלָד חַי לַאֲוִיר הָעוֹלָם אֲפִלּוּ מֵת בְּשָׁעָה שֶׁנּוֹלַד הֲרֵי אִמּוֹ פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. אֲבָל מִדִּבְרֵי סוֹפְרִים עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁכָּלוּ לוֹ חֳדָשָׁיו וְנוֹלַד לְתִשְׁעָה חֳדָשִׁים גְּמוּרִים. אֲבָל אִם לֹא נוֹדַע לְכַמָּה נוֹלַד. אִם חַי שְׁלֹשִׁים יוֹם הֲרֵי זֶה וְלַד קַיָּמָא וּפוֹטֵר נְשֵׁי אָבִיו מִן הַחֲלִיצָה וּמִן הַיִּבּוּם. וְאִם מֵת בְּתוֹךְ הַשְּׁלֹשִׁים אֲפִלּוּ בְּיוֹם הַשְּׁלֹשִׁים בֵּין שֶׁמֵּת מֵחלִי בֵּין שֶׁנָּפַל מִן הַגַּג אוֹ אֲכָלוֹ אֲרִי הֲרֵי זֶה סָפֵק נֵפֶל סָפֵק בֶּן קַיָּמָא וּצְרִיכָה חֲלִיצָה מִדִּבְרֵי סוֹפְרִים. אֲבָל לֹא תִּתְיַבֵּם:","מִי שֶׁיֵּשׁ לוֹ אָח מִכָּל מָקוֹם אֲפִלּוּ מַמְזֵר אוֹ עוֹבֵד עֲבוֹדָה זָרָה בֵּין קָטָן בֵּין גָּדוֹל מִשֶּׁיָּצָא רֹאשׁוֹ וְרֻבּוֹ לַאֲוִיר הָעוֹלָם קֹדֶם שֶׁיָּמוּת אָחִיו הֲרֵי זֶה זוֹקֵק אֶת אִשְׁתּוֹ לְיִבּוּם. וְאִם הָיָה לוֹ אָח מִן הַשִּׁפְחָה אוֹ מִן הַכּוּתִית אֵינוֹ אָחִיו לְדָבָר מִן הַדְּבָרִים וְאֵינוֹ זוֹקֵק אֶת אִשְׁתּוֹ. וְאַף עַל פִּי שֶׁהָיְתָה לֵדָתוֹ בִּקְדֻשָּׁה הוֹאִיל וְהָיְתָה הוֹרָתוֹ שֶׁלֹּא בִּקְדֻשָּׁה אֵינוֹ אָחִיו:","אַחִים מִן הָאֵם אֵינָן חֲשׁוּבִין אַחִים (אֶלָּא לַאֲבֵלוּת וּלְעֵדוּת אֲבָל) לְעִנְיַן יְרֻשָּׁה אוֹ לְעִנְיַן יִבּוּם וַחֲלִיצָה הֲרֵי הֵן כְּמִי שֶׁאֵינָן. שֶׁאֵין אַחְוָה אֶלָּא מֵאָב:","גֵּרִים שֶׁנִּתְגַיְּרוּ וַעֲבָדִים שֶׁנִּשְׁתַּחְרְרוּ אֵין לָהֶן אַחְוָה כְּלָל וַהֲרֵי הֵן כְּזָרִים זֶה לָזֶה. וַאֲפִלּוּ אֶחָד מֵהֶם הוֹרָתוֹ שֶׁלֹּא בִּקְדֻשָּׁה וְלֵדָתוֹ בִּקְדֻשָּׁה וְהַשֵּׁנִי הוֹרָתוֹ וְלֵדָתוֹ בִּקְדֻשָּׁה הֲרֵי הֵן כְּזָרִים. וַאֲפִלּוּ תְּאוֹמִים וְנוֹלְדוּ בִּקְדֻשָּׁה אֵין בֵּינֵיהֶן אַחְוָה עַד שֶׁתְּהֵא הוֹרָתָן וְלֵדָתָן בִּקְדֻשָּׁה:","מִי שֶׁהָיוּ לוֹ נָשִׁים רַבּוֹת וָמֵת. בִּיאָתָהּ אוֹ חֲלִיצָתָהּ שֶׁל אַחַת מֵהֶן פּוֹטֶרֶת אֶת הַשְּׁאָר וְאֵינוֹ מְיַבֵּם לִשְׁתַּיִם שֶׁנֶּאֱמַר (דברים כה ט) ״אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו״‎‎ בַּיִת אֶחָד הוּא בּוֹנֶה וְאֵינוֹ בּוֹנֶה שְׁנֵי בָּתִּים. וְכֵן אִם הָיוּ לוֹ אַחִים רַבִּים אֶחָד מֵהֶן חוֹלֵץ אוֹ מְיַבֵּם לְאַחַת מִן הַיְבָמוֹת וְיֻתְּרוּ שְׁאָר הַצָּרוֹת:","הָיוּ בִּיבָמוֹת אֵלּוּ כְּשֵׁרוֹת לִכְהֻנָּה וּפְסוּלוֹת. אִם הָיָה מְיַבֵּם מְיַבֵּם לְאֵי זוֹ שֶׁיִּרְצֶה. וְאִם הָיָה חוֹלֵץ יַחֲלֹץ לַפְּסוּלָה כְּדֵי שֶׁלֹּא יִפְסל אֶת הַכְּשֵׁרָה לִכְהֻנָּה בַּחֲלִיצָה:","מֵתוּ לוֹ אַחִין רַבִּים וְנָפְלוּ נְשׁוֹתֵיהֶן לְפָנָיו. אִם אֶפְשָׁר לוֹ לְיַבֵּם אֶת כֻּלָּן מְיַבֵּם וְאִם לָאו חוֹלֵץ. אוֹ חוֹלֵץ לְמִי שֶׁיִּרְצֶה מֵהֶן וּמְיַבֵּם לְמִי שֶׁיִּרְצֶה אַחַת מִכָּל בַּיִת וּבַיִת:","הַכּוֹנֵס אֶת יְבִמְתּוֹ נֶאֶסְרוּ צָרוֹתֶיהָ עָלָיו וְעַל שְׁאָר הָאַחִין וְאִם בָּא הוּא אוֹ אֶחָד מֵהָאַחִין עַל צָרָתָהּ הֲרֵי זֶה עוֹבֵר בַּעֲשֵׂה שֶׁנֶּאֱמַר (דברים כה ה) ״יְבָמָהּ יָבֹא עָלֶיהָ״‎‎ וְלֹא עָלֶיהָ וְעַל צָרָתָהּ וְלָאו הַבָּא מִכְּלַל עֲשֵׂה עֲשֵׂה. וְכֵן הַחוֹלֵץ לִיבִמְתּוֹ נֶאֶסְרָה הַחֲלוּצָה הִיא וְכָל צָרוֹתֶיהָ עַל הַחוֹלֵץ וְעַל שְׁאָר אַחִין. וְכֻלָּן אֲסוּרוֹת עֲלֵיהֶן מִדִּבְרֵי סוֹפְרִים כִּשְׁנִיּוֹת. שֶׁמֵּאַחַר שֶׁמֵּת אָחִיו בְּלֹא וָלָד נִסְתַּלֵּק אִסּוּר עֶרְוָה מֵעַל כָּל נָשָׁיו לְפִיכָךְ תּוֹפְסִין בָּהֶן הַקִּדּוּשִׁין כִּשְׁנִיּוֹת:","הַחוֹלֵץ לִיבִמְתּוֹ כְּשֵׁם שֶׁהִיא אֲסוּרָה עָלָיו כָּךְ קְרוֹבוֹתֶיהָ אֲסוּרוֹת עָלָיו. כְּגוֹן אִמָּהּ וּבִתָּהּ. וְכֵן הִיא אֲסוּרָה לִבְנוֹ וּלְאֶחָיו. וַאֲפִלּוּ שְׁנִיּוֹת שֶׁלָּהּ אֲסוּרוֹת כְּגוֹן בַּת בַּת בִּתָּהּ. וְכֵן הִיא אֲסוּרָה לְבֶן בֶּן בְּנוֹ. כְּלָלוֹ שֶׁל דָּבָר הֲרֵי הִיא כְּאִשְׁתּוֹ שֶׁגֵּרְשָׁהּ. וְכֵן אִם מֵתָה יְבִמְתּוֹ וַעֲדַיִן הִיא זְקוּקָה לוֹ אָסוּר בִּקְרוֹבוֹתֶיהָ כְּאִלּוּ הָיְתָה אִשְׁתּוֹ וּמֵתָה תַּחְתָּיו. וְכָל הָאִסּוּרִין הָאֵלּוּ מִדִּבְרֵיהֶן. וּמֻתָּר אָדָם לִשָּׂא אֲחוֹת צָרַת חֲלוּצָתוֹ וּשְׁאָר קְרוֹבוֹתֶיהָ:","אָסוּר לְיָבָם לִשָּׂא קְרוֹבַת זְקוּקָתוֹ כְּגוֹן אִמָּהּ אוֹ בִּתָּהּ עַד שֶׁיְּיַבֵּם אֶחָד מֵאֶחָיו לָהּ אוֹ יַחֲלֹץ לָהּ וְתָסוּר זִקָּתוֹ מֵעָלֶיהָ וְיִשָּׂא אִמָּהּ אוֹ בִּתָּהּ אוֹ שְׁאָר קְרוֹבוֹתֶיהָ. אַף עַל פִּי שֶׁהֵן כֻּלָּן אֲסוּרוֹת עַל אָחִיו שֶׁחָלַץ אוֹ יִבֵּם כְּמוֹ שֶׁבֵּאַרְנוּ:","הַכּוֹנֵס אֶת יְבִמְתּוֹ וְגֵרְשָׁהּ אִם רָצָה לְהַחֲזִיר יַחֲזִיר מִפְּנֵי שֶׁהִיא אִשְׁתּוֹ לְכָל דָּבָר וְלֹא נִשְׁאַר עָלֶיהָ שֵׁם אִסּוּר מִפְּנֵי אָחִיו כְּלָל לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת שֶׁבֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד בִּיאָתוֹ בִּיאָה וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה. לְפִיכָךְ יָבָם קָטָן שֶׁבָּא עַל יְבִמְתּוֹ אִם הָיָה בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד יְקַיֵּם. אֲבָל אֵינוֹ חוֹלֵץ עַד שֶׁיִּגְדַּל וְיִבָּדֵק שֶׁהֲרֵי (דברים כה ז) ״אִישׁ״‎‎ כָּתוּב בַּפָּרָשָׁה לְעִנְיַן חֲלִיצָה. וְאִם הָיָה פָּחוֹת מִזֶּה אֵין בִּיאָתוֹ בִּיאָה. וּבִיאַת בֶּן תֵּשַׁע שָׁנִים אֵינָהּ קוֹנָה קִנְיָן גָּמוּר. לְפִיכָךְ אֵין יְבִמְתּוֹ נִתֶּרֶת לְזָר עַד שֶׁיָּבוֹא עָלֶיהָ אַחַר שֶׁיִּגְדַּל אוֹ עַד שֶׁתַּחֲלֹץ כְּמוֹ שֶׁיִּתְבָּאֵר:","וְכֵן הַיְבָמָה הַקְּטַנָּה אִם רָצָה הַיָּבָם לְיַבֵּם אוֹתָהּ מְיַבֵּם אֲבָל אֵינָהּ חוֹלֶצֶת עַד שֶׁתַּגְדִּיל וְתִבָּדֵק. וַאֲפִלּוּ נִבְעֲלָה אַחַר י״‎ב שָׁנָה אֵינָהּ חוֹלֶצֶת עַד שֶׁתִּבְדֹּק וְיִמְצְאוּ בָּהּ הַסִּימָנִין:","כְּשֵׁם שֶׁאֵין הַיָּבָם חוֹלֵץ עַד שֶׁיֵּעָשֶׂה אִישׁ כָּךְ אֵין הַיְבָמָה חוֹלֶצֶת עַד שֶׁתֵּעָשֶׂה אִשָּׁה גְּדוֹלָה. וְיָבָם קָטָן שֶׁבָּא עַל יְבָמָה קְטַנָּה יִגְדְּלוּ זֶה עִם זֶה:","הַיְבָמָה לֹא תִּתְיַבֵּם וְלֹא תַּחֲלֹץ עַד שֶׁתַּמְתִּין תִּשְׁעִים יוֹם חוּץ מִיּוֹם הַמִּיתָה וּמִיּוֹם הַיִּבּוּם וּמִיּוֹם הַחֲלִיצָה כִּשְׁאָר כָּל הַנָּשִׁים. וּמִפְּנֵי מָה לֹא תַּחֲלֹץ בְּתוֹךְ תִּשְׁעִים יוֹם מִפְּנֵי שֶׁאֵינָהּ רְאוּיָה לְיִבּוּם וְנֶאֱמַר (דברים כה ז) ״אִם לֹא יַחְפֹּץ הָאִישׁ לָקַחַת אֶת יְבִמְתּוֹ״‎‎ (דברים כה ט) ״וְחָלְצָה נַעֲלוֹ״‎‎ וְגוֹ' בְּעֵת שֶׁהִיא עוֹלָה לְיִבּוּם עוֹלָה לַחֲלִיצָה וְכָל זְמַן שֶׁאֵינָהּ עוֹלָה לְיִבּוּם אֵינָהּ עוֹלָה לַחֲלִיצָה. וְאִם יִבֵּם אוֹתָהּ אוֹ חָלַץ בְּתוֹךְ הַשְּׁלֹשָׁה חֳדָשִׁים הוֹאִיל וְאֵינָהּ מְעֻבֶּרֶת הֲרֵי זוֹ נִפְטְרָה וְאֵינָהּ צְרִיכָה כְּלוּם:","הַחוֹלֵץ לִיבִמְתּוֹ וְנִמְצֵאת מְעֻבֶּרֶת וְיָלְדָה. אִם הָיָה וָלָד שֶׁל קַיָּמָא הֲרֵי זוֹ כְּמִי שֶׁלֹּא נֶחְלְצָה לוֹ מֵעוֹלָם וּמֻתֶּרֶת לִכְהֻנָּה וּמֻתָּר בִּקְרוֹבוֹתֶיהָ. וְאִם הִפִּילָה אוֹ שֶׁלֹּא שָׁהָה שְׁלֹשִׁים יוֹם אַחַר שֶׁנּוֹלַד חוֹזֵר וְחוֹלֵץ לָהּ הוּא אוֹ אֶחָד מֵאֶחָיו. שֶׁחֲלִיצַת הַמְעֻבֶּרֶת אֵינָהּ חֲלִיצָה וּבִיאַת הַמְעֻבֶּרֶת אֵינָהּ יִבּוּם:","לְפִיכָךְ הַכּוֹנֵס אוֹ הַחוֹלֵץ לִיבִמְתּוֹ הַמְעֻבֶּרֶת לֹא תִּנָּשֵׂא צָרָתָהּ עַד שֶׁתֵּלֵד זוֹ. שֶׁאֵין הַוָּלָד מַתִּיר עַד שֶׁיֵּצֵא לַאֲוִיר הָעוֹלָם:","הַכּוֹנֵס אֶת יְבִמְתּוֹ וְנִמְצֵאת מְעֻבֶּרֶת מַפְרִישִׁין אוֹתָן וּמַמְתִּינִין לָהּ. אִם הִפִּילָה יַחֲזֹר וִיקַיֵּם. וְאִם יָלְדָה אֲפִלּוּ מֵת בַּיּוֹם שֶׁנּוֹלַד הֲרֵי זֶה מוֹצִיאָהּ בְּגֵט וְחוֹלֵץ לָהּ וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לַאֲחֵרִים. וְאִם נִתְקַיֵּם הַוָּלָד שְׁלֹשִׁים יוֹם אַחַר שֶׁנּוֹלַד הֲרֵי זֶה וָלָד שֶׁל קַיָּמָא וְאֵינָהּ צְרִיכָה מִמֶּנּוּ גֵּט מִפְּנֵי שֶׁהִיא עֶרְוָה עָלָיו:","יָלְדָה לְאַחַר שִׁשָּׁה חֳדָשִׁים מִשֶּׁנִּתְיַבְּמָה וָלָד שֶׁל קַיָּמָא הֲרֵי זֶה הַוָּלָד סָפֵק אִם בֶּן תִּשְׁעָה לָרִאשׁוֹן אִם בֶּן שִׁבְעָה לָאַחֲרוֹן לְפִיכָךְ יוֹצִיא בְּגֵט וְהַוָּלָד כָּשֵׁר. וְאִם בָּא עָלֶיהָ אַחַר שֶׁיָּלְדָה הַבָּנִים שֶׁיָּבֹאוּ אַחֲרָיו סָפֵק מַמְזֵרִים:"],"Mishneh Torah, Marriage 13":["כַּמָּה הַכְּסוּת שֶׁהוּא חַיָּב לִתֵּן לָהּ. בְּגָדים שֶׁל חֲמִשִּׁים זוּז מִשָּׁנָה לְשָׁנָה מִמַּטְבֵּעַ אוֹתָן הַיָּמִים שֶׁנִּמְצְאוּ הַחֲמִשִּׁים שִׁשָּׁה דִּינָרִין וּרְבִיעַ דִּינַר כֶּסֶף. נוֹתְנִין לָהּ חֲדָשִׁים בִּימוֹת הַגְּשָׁמִים וְלוֹבֶשֶׁת בְּלָאוֹתֵיהֶן בִּימוֹת הַחַמָּה. וְהַשְּׁחָקִים וְהֵם מוֹתַר הַכְּסוּת הֲרֵי הֵן שֶׁלָּהּ כְּדֵי שֶׁתִּתְכַּסֶּה בָּהֶם בִּימֵי נִדָּתָהּ. וְנוֹתְנִין לָהּ חֲגוֹרָה לְמָתְנֶיהָ וְכִפָּה לְרֹאשָׁהּ וּמִנְעָל מִמּוֹעֵד לְמוֹעֵד:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאוֹתָן הַיָּמִים וּבְאֶרֶץ יִשְׂרָאֵל אֲבָל בִּשְׁאָר זְמַנִּים וּשְׁאָר הַמְּקוֹמוֹת אֵין הַדָּמִים עִקָּר. יֵשׁ מְקוֹמוֹת שֶׁיִּהְיוּ שָׁם הַבְּגָדִים בְּיֹקֶר הַרְבֵּה אוֹ בְּזוֹל הַרְבֵּה. אֶלָּא הָעִקָּר שֶׁסּוֹמְכִין עָלָיו שֶׁמְּחַיְּבִין אוֹתוֹ לִתֵּן לָהּ בְּגָדִים הָרְאוּיִים בִּימוֹת הַגְּשָׁמִים וּבִימוֹת הַחַמָּה בְּפָחוֹת שֶׁלּוֹבֶשֶׁת כָּל אִשָּׁה בַּעֲלַת בַּיִת שֶׁבְּאוֹתָהּ הַמְּדִינָה:","וּבִכְלַל הַכְּסוּת שֶׁהוּא חַיָּב לִתֵּן לָהּ כְּלֵי בַּיִת וּמָדוֹר שֶׁיּוֹשֶׁבֶת בּוֹ. וּמַה הֵן כְּלֵי בַּיִת מִטָּה מֻצַּעַת וּמַפָּץ אוֹ מַחְצֶלֶת לֵישֵׁב עָלֶיהָ. וּכְלֵי אֲכִילָה וּשְׁתִיָּה כְּגוֹן קְדֵרָה וּקְעָרָה וְכוֹס וּבַקְבּוּק וְכַיּוֹצֵא בָּהֶן. וְהַמָּדוֹר שֶׁשּׂוֹכֵר לָהּ בַּיִת שֶׁל אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת וְתִהְיֶה רְחָבָה חוּצָה לוֹ כְּדֵי לְהִשְׁתַּמֵּשׁ בָּהּ. וְיִהְיֶה לוֹ בֵּית הַכִּסֵּא חוּץ מִמֶּנּוּ:","וְכֵן מְחַיְּבִין אוֹתוֹ לִתֵּן לָהּ תַּכְשִׁיטִים כְּגוֹן בִּגְדֵי צִבְעוֹנִין לְהַקִּיף עַל רֹאשָׁהּ וּפַדַּחְתָּהּ וּפוּךְ וְשָׂרָק וְכַיּוֹצֵא בָּהּ כְּדֵי שֶׁלֹּא תִּתְגַּנֶּה עָלָיו:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּעָנִי שֶׁבְּיִשְׂרָאֵל אֲבָל בְּעָשִׁיר הַכּל לְפִי עָשְׁרוֹ. וַאֲפִלּוּ הָיָה רָאוּי לִקְנוֹת לָהּ כְּלֵי מֶשִׁי וְרִקְמָה וּכְלֵי זָהָב כּוֹפִין אוֹתוֹ וְנוֹתֵן. וְכֵן הַמָּדוֹר לְפִי עָשְׁרוֹ וְהַתַּכְשִׁיט וּכְלֵי הַבַּיִת הַכּל לְפִי עָשְׁרוֹ. וְאִם קָצְרָה יָדוֹ לִתֵּן לָהּ אֲפִלּוּ כְּעָנִי שֶׁבְּיִשְׂרָאֵל כּוֹפִין אוֹתוֹ לְהוֹצִיא וְתִהְיֶה הַכְּתֻבָּה עָלָיו חוֹב עַד שֶׁיַּעֲשִׁיר:","וְלֹא הָאִשָּׁה בִּלְבַד אֶלָּא בָּנָיו וּבְנוֹתָיו הַקְּטַנִּים בְּנֵי שֵׁשׁ אוֹ פָּחוֹת חַיָּב לִתֵּן לָהֶם כְּסוּת הַמַּסְפֶּקֶת לָהֶם וּכְלֵי תַּשְׁמִישׁ וּמָדוֹר לִשְׁכֹּן בּוֹ. וְאֵינוֹ נוֹתֵן לָהֶם לְפִי עָשְׁרוֹ אֶלָּא כְּפִי צָרְכָּן בִּלְבַד. זֶה הַכְּלָל כָּל מִי שֶׁיֵּשׁ לוֹ עָלָיו מְזוֹנוֹת בֵּין בְּחַיָּיו בֵּין אַחַר מוֹתוֹ יֵשׁ לוֹ כְּסוּת וּכְלֵי בֵּית וּמָדוֹר. וְכָל שֶׁבֵּית דִּין מוֹכְרִין לִמְזוֹנוֹתָיו כָּךְ מוֹכְרִין לִכְסוּתוֹ וּכְלֵי בֵּיתוֹ וּמְדוֹרוֹ:","הָאִשָּׁה שֶׁהָלַךְ בַּעְלָהּ וּפָסְקוּ לָהּ בֵּית דִּין מְזוֹנוֹת וּכְסוּת וּכְלֵי בַּיִת וּשְׂכַר מָדוֹר אֵין פּוֹסְקִין לָהּ תַּכְשִׁיט שֶׁהֲרֵי אֵין לָהּ בַּעַל שֶׁתִּתְקַשֵּׁט לוֹ. אֲבָל מִי שֶׁנִּשְׁתַּטָּה בַּעְלָהּ אוֹ שֶׁנִּתְחָרֵשׁ פּוֹסְקִין לָהּ תַּכְשִׁיט. וְדִין הַבַּעַל עִם אִשְׁתּוֹ בְּטַעֲנַת הַכְּסוּת וְהַכֵּלִים וּשְׂכַר הַמָּדוֹר כְּדִינָם בְּטַעֲנַת הַמְּזוֹנוֹת אִם אָמַר הוּא נָתַתִּי וְהִיא אוֹמֶרֶת לֹא נָתַתָּ דִּין אֶחָד לַכּל:","הַמַּדִּיר אֶת אִשְׁתּוֹ שֶׁלֹּא תִּתְקַשֵּׁט בְּאֶחָד מִכָּל הַמִּינִין. בָּעֲנִיּוֹת שָׁנָה אַחַת יְקַיֵּם. יֶתֶר עַל כֵּן אוֹ יַתִּיר אֶת נִדְרוֹ אוֹ יוֹצִיא וְיִתֵּן כְּתֻבָּה. וּבַעֲשִׁירוֹת שְׁלֹשִׁים יוֹם יְקַיֵּם. יֶתֶר עַל כֵּן יַתִּיר אֶת נִדְרוֹ אוֹ יוֹצִיא וְיִתֵּן כְתוּבָה:","הִדִּירָהּ שֶׁלֹּא תֵּלֵךְ לְמֶרְחָץ. בִּכְרַכִּים שַׁבָּת אַחַת בִּכְפָרִים שְׁתֵּי שַׁבָּתוֹת. שֶׁלֹּא תִּנְעל מִנְעָל. בִּכְפָרִים שְׁלֹשָׁה יָמִים וּבִכְרַכִּים מֵעֵת לְעֵת. יֶתֶר עַל זֶה יַתִּיר אֶת נִדְרוֹ אוֹ יוֹצִיא וְיִתֵּן כְּתֻבָּה:","הִדִּירָהּ שֶׁלֹּא תִּשְׁאַל וְלֹא תַּשְׁאִיל מִכְּלֵי הַבַּיִת שֶׁדֶּרֶךְ כָּל הַשְּׁכֵנוֹת לִשְׁאל אוֹתָן וּלְהַשְׁאִילָן כְּגוֹן נָפָה וּכְבָרָה רֵחַיִם וְתַנּוּר וְכַיּוֹצֵא בָּהֶם. יַתִּיר אֶת נִדְרוֹ אוֹ יוֹצִיא וְיִתֵּן כְּתֻבָּה מִפְּנֵי שֶׁמַּשִּׁיאָהּ שֵׁם רַע בִּשְׁכֵנוֹתֶיהָ. וְכֵן הִיא שֶׁנָּדְרָה שֶׁלֹּא תִּשְׁאַל וְלֹא תַּשְׁאִיל נָפָה וּכְבָרָה וְרֵחַיִם וְתַנּוּר וְכַיּוֹצֵא בָּהֶם וְשֶׁלֹּא תֶּאֱרֹג בְּגָדִים נָאִים לְבָנִים בְּמָקוֹם שֶׁדַּרְכָּן לֶאֱרֹג אוֹתָם לְבָנִים תֵּצֵא בְּלֹא כְּתֻבָּה מִפְּנֵי שֶׁמַּשִּׁיאָתוֹ שֵׁם רַע בִּשְׁכוּנָתוֹ שֶׁהוּא כִּילַי:","מָקוֹם שֶׁדַּרְכָּן שֶׁלֹּא תֵּצֵא אִשָּׁה לַשּׁוּק בְּכִפָּה שֶׁעַל רֹאשָׁהּ בִּלְבַד עַד שֶׁיִּהְיֶה עָלֶיהָ רְדִיד הַחוֹפֶה אֶת כָּל גּוּפָהּ כְּמוֹ טַלִּית נוֹתֵן לָהּ בִּכְלַל הַכְּסוּת רְדִיד הַפָּחוּת מִכָּל הָרְדִידִין. וְאִם הָיָה עָשִׁיר נוֹתֵן לָהּ לְפִי עָשְׁרוֹ כְּדֵי שֶׁתֵּצֵא בּוֹ לְבֵית אָבִיהָ אוֹ לְבַיִת הָאָבֵל אוֹ לְבֵית הַמִּשְׁתֶּה. לְפִי שֶׁכָּל אִשָּׁה יֵשׁ לָהּ לָצֵאת וְלֵילֵךְ לְבֵית אָבִיהָ לְבַקְּרוֹ וּלְבֵית הָאָבֵל וּלְבֵית הַמִּשְׁתֶּה לִגְמל חֶסֶד לְרֵעוֹתֶיהָ אוֹ לִקְרוֹבוֹתֶיהָ כְּדֵי שֶׁיָּבוֹאוּ הֵם לָהּ. שֶׁאֵינָהּ בְּבֵית הַסֹּהַר עַד שֶׁלֹּא תֵּצֵא וְלֹא תָּבוֹא. אֲבָל גְּנַאי הוּא לְאִשָּׁה שֶׁתִּהְיֶה יוֹצְאָה תָּמִיד פַּעַם בַּחוּץ פַּעַם בָּרְחוֹבוֹת. וְיֵשׁ לַבַּעַל לִמְנֹעַ אִשְׁתּוֹ מִזֶּה וְלֹא יְנִיחֶנָּהּ לָצֵאת אֶלָּא כְּמוֹ פַּעַם אַחַת בְּחֹדֶשׁ אוֹ כְּמוֹ פַּעֲמַיִם בְּחֹדֶשׁ לְפִי הַצֹּרֶךְ. שֶׁאֵין יֹפִי לָאִשָּׁה אֶלָּא לֵישֵׁב בְּזָוִית בֵּיתָהּ שֶׁכָּךְ כָּתוּב (תהילים מה יד) \"כָּל כְּבוּדָּה בַת מֶלֶךְ פְּנִימָה:\"","הַמַּדִּיר אֶת אִשְׁתּוֹ שֶׁלֹּא תֵּלֵךְ לְבֵית אָבִיהָ. בִּזְמַן שֶׁהוּא עִמָּהּ בָּעִיר חֹדֶשׁ אֶחָד מַמְתִּינִין לוֹ שְׁנַיִם יוֹצִיא וְיִתֵּן כְּתֻבָּה. וּבִזְמַן שֶׁהוּא בְּעִיר אַחֶרֶת רֶגֶל אֶחָד מַמְתִּינִין לוֹ שְׁנַיִם יוֹצִיא וְיִתֵּן כְּתֻבָּה:","הַמַּדִּיר אֶת אִשְׁתּוֹ שֶׁלֹּא תֵּלֵךְ לְבַיִת הָאָבֵל אוֹ לְבֵית הַמִּשְׁתֶּה. אוֹ יַתִּיר אֶת נִדְרוֹ אוֹ יוֹצִיא וְיִתֵּן כְּתֻבָּה שֶׁזֶּה כְּמִי שֶׁאֲסָרָהּ בְּבֵית הַסֹּהַר וְנָעַל בְּפָנֶיהָ. וְאִם הָיָה טוֹעֵן מִפְּנֵי בְּנֵי אָדָם פְּרוּצִים שֶׁיֵּשׁ בְּאוֹתוֹ בֵּית הָאָבֵל אוֹ בְּבֵית הַמִּשְׁתֶּה וְהֻחְזְקוּ שָׁם פְּרוּצִים שׁוֹמְעִין לוֹ:","הָאוֹמֵר לְאִשְׁתּוֹ אֵין רְצוֹנִי שֶׁיָּבוֹאוּ לְבֵיתִי אָבִיךְ וְאִמֵּךְ אַחַיִךְ וְאַחְיוֹתַיִךְ שׁוֹמְעִין לוֹ וְתִהְיֶה הִיא הוֹלֶכֶת לָהֶם כְּשֶׁיֶּאֱרַע לָהֶם דָּבָר. וְתֵלֵךְ לְבֵית אָבִיהָ פַּעַם בְּחֹדֶשׁ וּבְכָל רֶגֶל וְרֶגֶל. וְלֹא יִכָּנְסוּ הֵם לָהּ אֶלָּא אִם אֵרַע לָהּ דָּבָר כְּגוֹן חלִי אוֹ לֵדָה. שֶׁאֵין כּוֹפִין אֶת הָאָדָם שֶׁיִּכָּנְסוּ אֲחֵרִים בִּרְשׁוּתוֹ. וְכֵן הִיא שֶׁאָמְרָה אֵין רְצוֹנִי שֶׁיִּכָּנְסוּ אֶצְלִי אִמְּךָ וְאַחְיוֹתֶיךָ וְאֵינִי שׁוֹכֶנֶת עִמָּהֶם בְּחָצֵר אַחַת מִפְּנֵי שֶׁמְּרֵעִין לִי וּמְצֵרִין לִי שׁוֹמְעִין לָהּ. שֶׁאֵין כּוֹפִין אֶת הָאָדָם שֶׁיֵּשְׁבוּ אֲחֵרִים עִמּוֹ בִּרְשׁוּתוֹ:","הָאִישׁ שֶׁאָמַר אֵינִי דָּר בְּמָדוֹר זֶה מִפְּנֵי שֶׁבְּנֵי אָדָם רָעִים אוֹ פְּרוּצִים אוֹ עַכּוּ\"ם בִּשְׁכוּנָתִי וַאֲנִי מִתְיָרֵא מֵהֶם שׁוֹמְעִים לוֹ. וְאַף עַל פִּי שֶׁלֹּא הֻחְזְקוּ בִּפְרִיצוּת שֶׁכָּךְ צִוּוּ חֲכָמִים הַרְחֵק מִשָּׁכֵן רַע. וַאֲפִלּוּ הָיָה הַמָּדוֹר שֶׁלָּהּ מוֹצִיאִין אוֹתָהּ מִמֶּנּוּ וְשׁוֹכֵן בֵּין בְּנֵי אָדָם כְּשֵׁרִים. וְכָךְ הִיא שֶׁאָמְרָה כֵּן אַף עַל פִּי שֶׁהוּא אוֹמֵר אֲנִי אֵינִי מַקְפִּיד עֲלֵיהֶם שׁוֹמְעִין לָהּ מִפְּנֵי שֶׁהִיא אוֹמֶרֶת אֵין רְצוֹנִי שֶׁיֵּצֵא עָלַי שׁוּם רַע בִּשְׁכֵנוּת אֵלּוּ:","כָּל הַיִּשּׁוּב אֲרָצוֹת אֲרָצוֹת הוּא. כְּגוֹן אֶרֶץ כְּנַעַן וְאֶרֶץ מִצְרַיִם וְאֶרֶץ תֵּימָן וְאֶרֶץ כּוּשׁ וְאֶרֶץ שִׁנְעָר וְכַיּוֹצֵא בָּהֶן. וְכָל אֶרֶץ וְאֶרֶץ מִמְּדִינוֹת וּכְפָרִים. וְעָרֵי יִשְׂרָאֵל לְעִנְיַן נִשּׂוּאִין שָׁלֹשׁ אֲרָצוֹת הָיוּ. יְהוּדָה וְעֵבֶר הַיַּרְדֵּן וְהַגָּלִיל:","אִישׁ שֶׁהָיָה מֵאֶרֶץ מִן הָאֲרָצוֹת וְנָשָׂא אִשָּׁה בְּאֶרֶץ אַחֶרֶת כּוֹפִין אוֹתָהּ וְיוֹצְאָה עִמּוֹ לְאַרְצוֹ אוֹ תֵּצֵא בְּלֹא כְּתֻבָּה שֶׁעַל מְנָת כֵּן נִשְּׂאָה אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ. אֲבָל הַנּוֹשֵׂא אִשָּׁה בְּאַחַת מִן הָאֲרָצוֹת וְהִיא מֵאַנְשֵׁי אוֹתָהּ הָאָרֶץ אֵינוֹ יָכוֹל לְהוֹצִיאָהּ לְאֶרֶץ אַחֶרֶת. אֲבָל מוֹצִיאָהּ מִמְּדִינָה לִמְדִינָה וּמִכְּפָר לִכְפָר בְּאוֹתָהּ הָאָרֶץ. וְאֵינוֹ יָכוֹל לְהוֹצִיאָהּ מִמְּדִינָה לִכְפָר וְלֹא מִכְּפָר לִמְדִינָה שֶׁיֵּשׁ דְּבָרִים שֶׁיְּשִׁיבַת הַמְּדִינָה טוֹבָה לָהֶם וְיֵשׁ דְּבָרִים שֶׁיְּשִׁיבַת הַכְּפָרִים טוֹבָה לָהֶם:","וּכְשֶׁמּוֹצִיאָהּ מִמְּדִינָה לִמְדִינָה וּמִכְּפָר לִכְפָר בְּאוֹתָהּ הָאָרֶץ אֵינוֹ יָכוֹל לְהוֹצִיאָהּ מִנָּוֶה הַיָּפֶה לַנָּוֶה הָרַע וְלֹא מֵרַע לְיָפֶה. מִפְּנֵי שֶׁהִיא צְרִיכָה לְהִטָּפֵל וְלִבְדֹּק עַצְמָהּ בַּנָּוֶה הַיָּפֶה כְּדֵי שֶׁלֹּא תִּהְיֶה בּוֹ קַלָּה וּכְעוּרָה. וְכֵן לֹא יוֹצִיאָהּ מִמָּקוֹם שֶׁרֻבּוֹ יִשְׂרָאֵל לְמָקוֹם שֶׁרֻבּוֹ עַכּוּ\"ם. וּבְכָל מָקוֹם מוֹצִיאִין מִמָּקוֹם שֶׁרֻבּוֹ עַכּוּ\"ם לְמָקוֹם שֶׁרֻבּוֹ יִשְׂרָאֵל:","בַּמֶּה דְּבָרִים אֲמוּרִים מִחוּצָה לָאָרֶץ לְחוּצָה לָאָרֶץ אוֹ מֵאֶרֶץ יִשְׂרָאֵל לְאֶרֶץ יִשְׂרָאֵל אֲבָל מִחוּצָה לָאָרֶץ לְאֶרֶץ יִשְׂרָאֵל כּוֹפִין אוֹתָהּ לַעֲלוֹת אֲפִלּוּ מִנָּוֶה הַיָּפֶה לַנָּוֶה הָרַע וַאֲפִלּוּ מִמָּקוֹם שֶׁרֻבּוֹ יִשְׂרָאֵל לְמָקוֹם שֶׁרֻבּוֹ עַכּוּ\"ם מַעֲלִין. וְאֵין מוֹצִיאִין מֵאֶרֶץ יִשְׂרָאֵל לְחוּצָה לָאָרֶץ וַאֲפִלּוּ מִנָּוֶה הָרַע לַנָּוֶה הַיָּפֶה [וַאֲפִלּוּ מִמָּקוֹם] שֶׁרֻבּוֹ עַכּוּ\"ם לְמָקוֹם שֶׁרֻבּוֹ יִשְׂרָאֵל:","אָמַר הָאִישׁ לַעֲלוֹת לְאֶרֶץ יִשְׂרָאֵל וְהִיא אֵינָהּ רוֹצָה תֵּצֵא בְּלֹא כְּתֻבָּה. אָמְרָה הִיא לַעֲלוֹת וְהוּא אֵינוֹ רוֹצֶה יוֹצִיא וְיִתֵּן כְּתֻבָּה. וְהוּא הַדִּין לְכָל מָקוֹם מֵאֶרֶץ יִשְׂרָאֵל עִם יְרוּשָׁלַיִם. שֶׁהַכּל מַעֲלִין לְאֶרֶץ יִשְׂרָאֵל וְאֵין הַכּל מוֹצִיאִין מִשָּׁם. הַכּל מַעֲלִין לִירוּשָׁלַיִם וְאֵין הַכּל מוֹצִיאִין מִשָּׁם:"],"Mishneh Torah, Marriage 24":["הַנּוֹשֵׂא אֶת הָאַיְלוֹנִית וְלֹא הָיוּ לוֹ בָּנִים וְלֹא אִשָּׁה אַחֶרֶת לִפְרוֹת וְלִרְבּוֹת מִמֶּנָּה אַף עַל פִּי שֶׁכּוֹפִין אוֹתוֹ וּמוֹצִיא הֲרֵי הִיא כְּכָל הַנָּשִׁים וְיֵשׁ לָהּ כְּתֻבָּה וּשְׁאָר תְּנָאֵי כְּתֻבָּה. וְכֵן זוֹכֶה הַבַּעַל בְּמַה שֶּׁזָּכָה בִּשְׁאָר הַנָּשִׁים:","אֲבָל הַנּוֹשֵׂא אִשָּׁה וְלֹא הִכִּיר בָּהּ וְנִמְצֵאת אַיְלוֹנִית אוֹ מֵחַיָּבֵי לָאוִין. וְכֵן הַנּוֹשֵׂא שְׁנִיָּה בֵּין הִכִּיר בָּהּ בֵּין לֹא הִכִּיר בָּהּ. אֵין לָהּ עִקַּר כְּתֻבָּה וְלֹא תְּנַאי מִתְּנָאֵי כְּתֻבָּה. אֲבָל תּוֹסֶפֶת יֵשׁ לָהּ. וְאֵין לָהּ מְזוֹנוֹת וַאֲפִלּוּ לְאַחַר מוֹתוֹ. וּכְשֶׁכּוֹפִין אוֹתוֹ וּמַפְרִישִׁין בֵּינֵיהֶם אֵין מוֹצִיאִין מִן הַבַּעַל פֵּרוֹת שֶׁאָכַל:","וְלָמָּה אֵין לָהֶן עִקָּר וְיֵשׁ לָהֶן תּוֹסֶפֶת. הָעִקָּר שֶׁהוּא תַּקָּנַת חֲכָמִים כְּדֵי שֶׁלֹּא תִּהְיֶה קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ הוֹאִיל וְלֹא הִכִּיר בָּהּ אֵין לָהּ עִקָּר. אֲבָל תּוֹסֶפֶת שֶׁהוּא חִיֵּב עַצְמוֹ בָּהּ כָּל זְמַן שֶׁתִּרְצֶה וְתַעֲמֹד לְפָנָיו הֲרֵי עָמְדָה בַּתְּנַאי שֶׁלָּהּ וַהֲרֵי הִקְנֵית לוֹ הֲנָאָתָהּ וַהֲרֵי הִיא עוֹמֶדֶת [לְפָנָיו] אֲבָל הַתּוֹרָה אָסְרָה אוֹתָהּ עָלָיו וּמַה הִיא יְכוֹלָה לַעֲשׂוֹת. לְפִיכָךְ יֵשׁ לָהּ תּוֹסֶפֶת שֶׁאֵין מַעֲשֶׂיהָ הֵן הַגּוֹרְמִין לָהּ לְהֵאָסֵר אַחַר הַנִּשּׂוּאִין אֶלָּא אֲסוּרָה הָיְתָה מִקֹּדֶם:","וְלָמָּה לֹא חִלְּקוּ בַּשְּׁנִיָּה בֵּין שֶׁהִכִּיר בָּהּ בֵּין שֶׁלֹּא הִכִּיר בָּהּ אֶלָּא אָמְרוּ אֵין לָהּ עִקַּר כְּתֻבָּה בְּכָל מָקוֹם. מִפְּנֵי שֶׁהִיא מִדִּבְרֵי סוֹפְרִים עָשׂוּ בָּהּ חִזּוּק. אֲבָל אִם נָשָׂא אַחַת מֵחַיָּבֵי לָאוִין; וְהִכִּיר בָּהּ. אוֹ אַחַת מֵחַיָּבֵי עֲשֵׂה בֵּין הִכִּיר בָּהּ בֵּין שֶׁלֹּא הִכִּיר בָּהּ יֵשׁ לָהּ כְּתֻבָּה. שֶׁחַיָּבֵי לָאוִין שֶׁהִכִּיר בָּהּ רָצָה לָזוּן בִּנְכָסָיו וְחַיָּבֵי עֲשֵׂה אִסּוּרָן קַל. וְיֵשׁ לִשְׁתֵּיהֶן מְזוֹנוֹת לְאַחַר מוֹתוֹ. וְכֵן אִם לָוְתָה וְאָכְלָה חַיָּב לְשַׁלֵּם. וּכְשֶׁכּוֹפִין אוֹתָן לְהוֹצִיא מוֹצִיאִין מִן הַבַּעַל כָּל פֵּרוֹת שֶׁאָכַל מִכָּל נְכָסֶיהָ:","הַמְמָאֶנֶת אֵין לָהּ כְּתֻבָּה אֲבָל תּוֹסֶפֶת יֵשׁ לָהּ. וְאֵין מוֹצִיאִין מִן הַבַּעַל פֵּרוֹת שֶׁאָכַל. וְאִם לָוְתָה כְּשֶׁהָיְתָה תַּחְתָּיו וְאָכְלָה וְאַחַר כָּךְ מֵאֲנָה אֵין מוֹצִיאִין אוֹתָן מְזוֹנוֹת מִן הַבַּעַל:","מִי שֶׁזִּנְּתָה תַּחַת בַּעְלָהּ אֵין לָהּ כְּתֻבָּה לֹא עִקָּר וְלֹא תּוֹסֶפֶת וְלֹא אֶחָד מִתְּנָאֵי כְּתֻבָּה שֶׁהֲרֵי מַעֲשֶׂיהָ גָּרְמוּ לָהּ לְהֵאָסֵר עַל בַּעְלָהּ:","וְהֵיאַךְ דִּין נָשִׁים אֵלּוּ בִּנְדוּנְיָא שֶׁלָּהֶם. כָּל אִשָּׁה שֶׁנְּדֻנְיָתָהּ קַיֶּמֶת אֲפִלּוּ זִנְּתָה נוֹטֶלֶת שֶׁלָּהּ וְהוֹלֶכֶת. וְאִם הָיְתָה שְׁנִיָּה אוֹ אֶחָד מֵחַיָּבֵי עֲשֵׂה בֵּין הִכִּיר בָּהּ בֵּין שֶׁלֹּא הִכִּיר בָּהּ אוֹ שֶׁהָיְתָה אַיְלוֹנִית אוֹ מֵחַיָּבֵי לָאוִין וְהִכִּיר בָּהּ הֲרֵי הִיא בִּנְדֻנְיָתָהּ כְּכָל הַנָּשִׁים:","נִכְסֵי צֹאן בַּרְזֶל חַיָּב בְּאַחְרָיוּתָן. וְנִכְסֵי מְלוֹג מַה שֶּׁנִּגְנַב אוֹ שֶׁאָבַד אָבַד לָהּ וְאֵינוֹ חַיָּב לְשַׁלֵּם. הָיְתָה אַיְלוֹנִית אוֹ מֵחַיָּבֵי לָאוִין וְלֹא הִכִּיר בָּהּ כָּל מַה שֶּׁאָבַד אוֹ נִגְנַב אוֹ בָּלָה אוֹ שֶׁנִּשְׁחַק מִנִּכְסֵי צֹאן בַּרְזֶל אֵין הַבַּעַל חַיָּב לְשַׁלֵּם. שֶׁהֲרֵי הִיא נָתְנָה לוֹ רְשׁוּת לִהְיוֹתָן אֶצְלוֹ. וְכָל מַה שֶּׁאָבַד אוֹ נִגְנַב מִנִּכְסֵי מְלוֹג חַיָּב לְשַׁלֵּם. הֵפֶךְ מִכָּל הַנָּשִׁים מִפְּנֵי שֶׁאֵין שָׁם אִישׁוּת גְּמוּרָה לֹא זָכָה בְּנִכְסֵי מְלוֹג:","וְהַמְמָאֶנֶת אֵין לָהּ בְּלָיוֹת כְּלָל שֶׁאֵין מוֹצִיאִין מִן הַבַּעַל דָּבָר מִמַּה שֶּׁאָבַד אוֹ נִגְנַב מִנְּכָסֶיהָ בֵּין מִנִּכְסֵי מְלוֹג בֵּין מִנִּכְסֵי צֹאן בַּרְזֶל אֶלָּא נוֹטֶלֶת הַנִּמְצָא לָהּ וְיוֹצְאָה:","מִי שֶׁזִּנְּתָה תַּחַת בַּעְלָהּ אֵין לָהּ כְּתֻבָּה לֹא עִקָּר וְלֹא תּוֹסֶפֶת. וְאֵין מוֹצִיאִין מֵהַבַּעַל דָּבָר מִמַּה שֶּׁאָבַד אוֹ נִגְנַב מִנִּכְסֵי צֹאן בַּרְזֶל שֶׁלָּהּ. וְאֵין צָרִיךְ לוֹמַר נִכְסֵי מְלוֹג. וְלֹא הַמְזַנָּה בִּלְבַד אֶלָּא אַף הָעוֹבֶרֶת עַל דַּת משֶׁה אוֹ עַל דַּת יְהוּדִית אוֹ הַיּוֹצֵאת מִשּׁוּם שֵׁם רַע אֵין לָהּ כְּתֻבָּה לֹא עִקָּר וְלֹא תּוֹסֶפֶת וְלֹא תְּנַאי מִתְּנָאֵי כְּתֻבָּה. וְכָל אַחַת מֵהֶן נוֹטֶלֶת הַנִּמְצָא לָהּ מִנְּדֻנְיָתָהּ וְיוֹצְאָה וְאֵין הַבַּעַל חַיָּב לְשַׁלֵּם כְּלוּם לֹא מַה שֶּׁפִּחֵת וְלֹא מַה שֶּׁאָבַד:","וְאֵלּוּ הֵן הַדְּבָרִים שֶׁאִם עָשְׂתָה אַחַת מֵהֶן עָבְרָה עַל דַּת משֶׁה. יוֹצְאָה בַּשּׁוּק וּשְׂעַר רֹאשָׁהּ גָּלוּי. אוֹ שֶׁנּוֹדֶרֶת אוֹ שֶׁנִּשְׁבַּעַת וְאֵינָהּ מְקַיֶּמֶת. אוֹ שֶׁשִּׁמְּשָׁה מִטָּתָהּ וְהִיא נִדָּה. אוֹ שֶׁאֵינָהּ קוֹצָה לָהּ חַלָּה. אוֹ שֶׁהֶאֱכִילָה אֶת בַּעְלָהּ דְּבָרִים אֲסוּרִים, אֵין צָרִיךְ לוֹמַר שְׁקָצִים וּרְמָשִׂים וּנְבֵלוֹת, אֶלָּא דְּבָרִים שֶׁאֵינָן מְעֻשָּׂרִין. וְהֵיאַךְ יוֹדֵעַ דָּבָר זֶה כְּגוֹן שֶׁאָמְרָה לוֹ פֵּרוֹת אֵלּוּ פְּלוֹנִי כֹּהֵן תִּקְּנָם לִי וְעִסָּה זוֹ פְּלוֹנִית הִפְרִישָׁה לִי חַלָּתָהּ וּפְלוֹנִי הֶחָכָם טִהֵר לִי אֶת הַכֶּתֶם וְאַחַר שֶׁאָכַל אוֹ בָּא עָלֶיהָ שָׁאַל אוֹתוֹ פְּלוֹנִי וְאָמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם. וְכֵן אִם הֻחְזְקָה נִדָּה בִּשְׁכֵנוֹתֶיהָ וְאָמְרָה לְבַעְלָהּ טְהוֹרָה אֲנִי וּבָא עָלֶיהָ:","וְאֵי זוֹ הִיא דָּת יְהוּדִית הוּא מִנְהַג הַצְּנִיעוּת שֶׁנָּהֲגוּ בְּנוֹת יִשְׂרָאֵל. וְאֵלּוּ הֵן הַדְּבָרִים שֶׁאִם עָשְׂתָה אַחַת מֵהֶן עָבְרָה עַל דָּת יְהוּדִית. יוֹצְאָה לַשּׁוּק אוֹ לְמָבוֹי מְפֻלָּשׁ וְרֹאשָׁהּ פָּרוּעַ וְאֵין עָלֶיהָ רְדִיד כְּכָל הַנָּשִׁים. אַף עַל פִּי שֶׁשְּׂעָרָהּ מְכֻסֶּה בְּמִטְפַּחַת. אוֹ שֶׁהָיְתָה טוֹוָה בַּשּׁוּק וּוֶרֶד וְכַיּוֹצֵא בּוֹ כְּנֶגֶד פָּנֶיהָ עַל פַּדַּחְתָּהּ אוֹ עַל לְחָיֶיהָ כְּדֶרֶךְ שֶׁעוֹשׂוֹת הָעַכּוּ\"ם הַפְּרוּצוֹת. אוֹ שֶׁטּוֹוָה בַּשּׁוּק וּמַרְאֵית זְרוֹעוֹתֶיהָ לִבְנֵי אָדָם. אוֹ שֶׁהָיְתָה מְשַׂחֶקֶת עִם הַבַּחוּרִים. אוֹ שֶׁהָיְתָה תּוֹבַעַת הַתַּשְׁמִישׁ בְּקוֹל רָם מִבַּעְלָהּ עַד שֶׁשְּׁכֵנוֹתֶיהָ שׁוֹמְעוֹת אוֹתָהּ מְדַבֶּרֶת עַל עִסְקֵי תַּשְׁמִישׁ. אוֹ שֶׁהָיְתָה מְקַלֶּלֶת אֲבִי בַּעְלָהּ בִּפְנֵי בַּעְלָהּ:","עֶזְרָא תִּקֵּן שֶׁתִּהְיֶה אִשָּׁה חוֹגֶרֶת בְּסִנָּר תָּמִיד בְּתוֹךְ בֵּיתָהּ מִשּׁוּם צְנִיעוּת. וְאִם לֹא חָגְרָה אֵינָהּ עוֹבֶרֶת עַל דַּת משֶׁה וְלֹא הִפְסִידָה כְּתֻבָּתָהּ. וְכֵן אִם יָצְתָה בְּרֹאשָׁהּ פָּרוּעַ מֵחָצֵר לְחָצֵר בְּתוֹךְ הַמָּבוֹי הוֹאִיל וּשְׂעָרָהּ מְכֻסֶּה בְּמִטְפַּחַת אֵינָהּ עוֹבֶרֶת עַל דָּת:","הָעוֹבֶרֶת עַל דָּת צְרִיכָה הַתְרָאָה וְעֵדִים וְאַחַר כָּךְ תַּפְסִיד כְּתֻבָּתָהּ. עָבְרָה בֵּינוֹ לְבֵינָהּ וְיָדַע שֶׁהִיא עוֹבֶרֶת עַל דָּת וְהִתְרָה בָּהּ בְּלֹא עֵדִים וְחָזְרָה וְעָבְרָה הוּא טוֹעֵן וְאוֹמֵר אַחַר הַתְרָאָה עָבְרָה וְהִיא אוֹמֶרֶת לֹא עָבַרְתִּי כְּלָל אוֹ לֹא הִתְרָה בִּי. אִם רָצָה לְהוֹצִיא הֲרֵי זֶה נוֹתֵן כְּתֻבָּה אַחַר שֶׁתִּשָּׁבַע שֶׁלֹּא עָבְרָה. שֶׁאִם תּוֹדֶה שֶׁעָבְרָה אַחַר הַתְרָאָה זוֹ אֵין לָהּ כְּלוּם:","כֵּיצַד הִיא יוֹצְאָה מִשּׁוּם שֵׁם רַע. כְּגוֹן שֶׁהָיוּ שָׁם עֵדִים שֶׁעָשְׂתָה דָּבָר מְכֹעָר בְּיוֹתֵר שֶׁהַדְּבָרִים מַרְאִין שֶׁהָיְתָה שָׁם עֲבֵרָה אַף עַל פִּי שֶׁאֵין שָׁם עֵדוּת בְּרוּרָה בִּזְנוּת. כֵּיצַד. כְּגוֹן שֶׁהָיְתָה בֶּחָצֵר לְבַדָּהּ וְרָאוּ רוֹכֵל יוֹצֵא וְנִכְנְסוּ מִיָּד בִּשְׁעַת יְצִיאָתוֹ וּמָצְאוּ אוֹתָהּ עוֹמֶדֶת מֵעַל הַמִּטָּה וְהִיא לוֹבֶשֶׁת הַמִּכְנָסַיִם אוֹ חוֹגֶרֶת אֲזוֹרָהּ. אוֹ שֶׁמָּצְאוּ רֹק לַח לְמַעְלָה מִן הַכִּילָה. אוֹ שֶׁהָיוּ יוֹצְאִים מִמָּקוֹם אָפֵל. אוֹ מַעֲלִין זֶה אֶת זֶה מִן הַבּוֹר וְכַיּוֹצֵא בּוֹ. אוֹ שֶׁרָאוּהוּ מְנַשֵּׁק עַל פִּי חֲלוּקָהּ אוֹ שֶׁרָאוּ אוֹתָן מְנַשְּׁקִין זֶה אֶת זֶה אוֹ מְגַפְּפִין זֶה אֶת זֶה אוֹ שֶׁנִּכְנְסוּ זֶה אַחַר זֶה וְהֵגִיפוּ דְּלָתוֹת וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. אִם רָצָה הַבַּעַל לְהוֹצִיאָהּ תֵּצֵא בְּלֹא כְּתֻבָּה. וְאֵין זוֹ צְרִיכָה הַתְרָאָה:","עוֹבֶרֶת עַל דַּת משֶׁה אוֹ עַל דָּת יְהוּדִית וְכֵן זֹאת שֶׁעָשְׂתָה דָּבָר מְכֹעָר אֵין כּוֹפִין אֶת הַבַּעַל לְהוֹצִיא אֶלָּא אִם רָצָה לֹא יוֹצִיא. וְאַף עַל פִּי שֶׁלֹּא הוֹצִיא אֵין לָהֶן כְּתֻבָּה שֶׁהַכְּתֻבָּה תַּקָּנַת חֲכָמִים הִיא כְּדֵי שֶׁלֹּא תְּהֵא קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ. וְלֹא הִקְפִּידוּ אֶלָּא עַל בְּנוֹת יִשְׂרָאֵל הַצְּנוּעוֹת אֲבָל אֵלּוּ הַפְּרוּצוֹת אֵין לָהֶן תַּקָּנָה [זוֹ] אֶלָּא תְּהֵא קַלָּה בְּעֵינָיו לְהוֹצִיאָהּ:","מִי שֶׁרָאָה אִשְׁתּוֹ שֶׁזִּנְּתָה אוֹ שֶׁאָמְרָה לוֹ אַחַת מִקְּרוֹבוֹתָיו אוֹ מִקְּרוֹבוֹתֶיהָ שֶׁהוּא מַאֲמִינָם וְסוֹמֶכֶת דַּעְתּוֹ עֲלֵיהֶם שֶׁזִּנְּתָה אִשְׁתּוֹ. בֵּין שֶׁהָיָה הָאוֹמֵר אִישׁ בֵּין שֶׁהָיְתָה אִשָּׁה הוֹאִיל וְסָמְכָה דַּעְתּוֹ לְדָבָר זֶה שֶׁהוּא אֱמֶת הֲרֵי זֶה חַיָּב לְהוֹצִיא וְאָסוּר לוֹ לָבוֹא עָלֶיהָ וְיִתֵּן כְּתֻבָּה. וְאִם הוֹדֵית לוֹ שֶׁזִּנְּתָה תֵּצֵא בְּלֹא כְּתֻבָּה. לְפִיכָךְ מַשְׁבִּיעָהּ בִּנְקִיטַת חֵפֶץ שֶׁלֹּא זִנְּתָה תַּחְתָּיו אִם רָאָה אוֹתָהּ בְּעַצְמוֹ וְאַחַר כָּךְ תִּגְבֶּה כְּתֻבָּתָהּ. אֲבָל בִּדְבַר אַחֵר אֵינוֹ יָכוֹל לְהַשְׁבִּיעָהּ אֶלָּא עַל יְדֵי גִּלְגּוּל:","אָמְרָה לוֹ אִשְׁתּוֹ שֶׁזִּנְּתָה תַּחְתָּיו בִּרְצוֹנָהּ אֵין מַשְׁגִּיחִין לִדְבָרֶיהָ שֶׁמָּא עֵינֶיהָ נָתְנָה בְּאַחֵר. אֲבָל אִבְּדָה כְּתֻבָּתָהּ עִקָּר וְתוֹסֶפֶת וְאִבְּדָה הַבְּלָאוֹת שֶׁהֲרֵי הוֹדֵית בִּזְנוּת. וְאִם הָיָה מַאֲמִינָהּ וְסוֹמֵךְ דַּעְתּוֹ עַל דְּבָרֶיהָ הֲרֵי זֶה חַיָּב לְהוֹצִיאָהּ. וְאֵין בֵּית דִּין כּוֹפִין אֶת הָאִישׁ לְגָרֵשׁ אֶת אִשְׁתּוֹ בְּדָבָר מִדְּבָרִים אֵלּוּ עַד שֶׁיָּבוֹאוּ שְׁנֵי עֵדִים וְיָעִידוּ שֶׁזִּנְּתָה אִשְׁתּוֹ זֹאת בִּפְנֵיהֶם בִּרְצוֹנָהּ וְאַחַר כָּךְ כּוֹפִין אוֹתוֹ לְהוֹצִיא:","הָאִשָּׁה שֶׁזִּנְּתָה תַּחַת בַּעְלָהּ בִּשְׁגָגָה אוֹ בְּאֹנֶס הֲרֵי זוֹ מֻתֶּרֶת לְבַעְלָהּ שֶׁנֶּאֱמַר (במדבר ה יג) \"וְהִיא לֹא נִתְפָּשָׂה\" הָא נִתְפָּשָׂה מֻתֶּרֶת. בֵּין שֶׁאֲנָסָהּ עַכּוּ\"ם בֵּין שֶׁאֲנָסָהּ יִשְׂרָאֵל. וְכָל שֶׁתְּחִלַּת בִּיאָתָהּ בְּאֹנֶס אַף עַל פִּי שֶׁסּוֹפָהּ בְּרָצוֹן וַאֲפִלּוּ אָמְרָה הָנִיחוּ לוֹ שֶׁאִלְמָלֵי לֹא אָנַס אוֹתִי הָיִיתִי שׂוֹכַרְתּוֹ הֲרֵי זוֹ מֻתֶּרֶת. שֶׁהַיֵּצֶר לְבָשָׁהּ וּמִתְּחִלָּה [הָיְתָה] בְּאֹנֶס:","נָשִׁים שֶׁגָּנְבוּ אוֹתָן לִסְטִים הֲרֵי הֵן כִּשְׁבֻיּוֹת שֶׁהֵן אֲנוּסוֹת וּמֻתָּרוֹת לְבַעְלֵיהֶן. וְאִם הֱנִיחוּם וְהָלְכוּ לַלִּסְטִים מֵעַצְמָן הֲרֵי אֵלּוּ בְּרָצוֹן וַאֲסוּרוֹת לְבַעְלֵיהֶן. וְדִין הַשּׁוֹגֶגֶת וְדִין הַנֶּאֱנֶסֶת אֶחָד הוּא שֶׁהַשְּׁגָגָה צַד אֹנֶס יֵשׁ בָּהּ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה בַּעְלָהּ יִשְׂרָאֵל. אֲבָל אֵשֶׁת כֹּהֵן שֶׁשָּׁגְגָה אוֹ שֶׁנֶּאֶנְסָה אֲסוּרָה לְבַעְלָהּ שֶׁהֲרֵי נַעֲשֵׂית זוֹנָה מִכָּל מָקוֹם וְהוּא אָסוּר בְּזוֹנָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת אִסּוּרֵי בִּיאָה:","אֶחָד אֵשֶׁת יִשְׂרָאֵל אוֹ אֵשֶׁת כֹּהֵן שֶׁנֶּאֶנְסָה כְּתֻבָּתָהּ קַיֶּמֶת הָעִקָּר וְהַתּוֹסֶפֶת וְלֹא הִפְסִידָה מִכְּתֻבָּתָהּ כְּלוּם. וְכוֹפִין אֶת הַכֹּהֵן לִתֵּן לָהּ כְּתֻבָּתָהּ וּלְגָרְשָׁהּ:","אֵשֶׁת כֹּהֵן שֶׁאָמְרָה לְבַעְלָהּ נֶאֱנַסְתִּי אוֹ שָׁגַגְתִּי וְנִבְעַלְתִּי לְאַחֵר אֵינוֹ חוֹשֵׁשׁ לִדְבָרֶיהָ שֶׁמָּא עֵינֶיהָ נָתְנָה בְּאַחֵר. וְאִם הָיְתָה נֶאֱמֶנֶת לוֹ אוֹ שֶׁאָמַר לוֹ אָדָם שֶׁהוּא סוֹמֵךְ עַל דְּבָרָיו יוֹצִיא וְיִתֵּן כְּתֻבָּה:","הָאוֹמֵר לְאִשְׁתּוֹ בִּפְנֵי שְׁנַיִם אַל תִּסָּתְרִי עִם אִישׁ פְּלוֹנִי וְנִכְנְסָה עִמּוֹ לְסֵתֶר בִּפְנֵי שְׁנֵי עֵדִים וְשָׁהֲתָה כְּדֵי טֻמְאָה הֲרֵי זוֹ אֲסוּרָה עַל בַּעְלָהּ עַד שֶׁיַּשְׁקֶנָּה מֵי הַמָּרִים כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת סוֹטָה. וְאִם מֵת קֹדֶם שֶׁיַּשְׁקֶנָּה אֵין לָהּ כְּתֻבָּה. וְאַף עַל פִּי שֶׁלֹּא מָצְאוּ דָּבָר מְכֹעָר. שֶׁאֵין לְךָ דָּבָר יוֹתֵר מְכֹעָר מִזֶּה. וְהַיּוֹם שֶׁאֵין שָׁם מֵי סוֹטָה נֶאֶסְרָה עָלָיו אִסּוּר עוֹלָם וְתֵצֵא בְּלֹא כְּתֻבָּה לֹא עִקָּר וְלֹא תּוֹסֶפֶת שֶׁהֲרֵי מַעֲשֶׂיהָ הָרָעִים גָּרְמוּ לָהּ לְהֵאָסֵר:","אָמַר לָהּ בֵּינוֹ לְבֵינָהּ אַל תִּסָּתְרִי עִם אִישׁ פְּלוֹנִי וְרָאָה אוֹתָהּ שֶׁנִּסְתְּרָה עִמּוֹ וְשָׁהֲתָה כְּדֵי טֻמְאָה הֲרֵי זוֹ אֲסוּרָה עָלָיו בַּזְּמַן הַזֶּה שֶׁאֵין שָׁם מֵי סוֹטָה. וְחַיָּב לְהוֹצִיא וְיִתֵּן כְּתֻבָּה. וְאִם הוֹדֵית שֶׁנִּסְתְּרָה אַחַר שֶׁהִתְרָה בָּהּ תֵּצֵא בְּלֹא כְּתֻבָּה וּלְפִיכָךְ מַשְׁבִּיעָהּ עַל זֶה וְאַחַר כָּךְ יִתֵּן כְּתֻבָּה:"],"Mishneh Torah, Mourning 12":["הַהֶסְפֵּד כְּבוֹד הַמֵּת הוּא. לְפִיכָךְ כּוֹפִין אֶת הַיּוֹרְשִׁין לִתֵּן שְׂכַר מְקוֹנְנִים וְהַמְקוֹנְנוֹת וְסוֹפְדִין אוֹתוֹ. וְאִם צִוָּה שֶׁלֹּא יִסְפְּדוּהוּ אֵין סוֹפְדִין אוֹתוֹ. אֲבָל אִם צִוָּה שֶׁלֹּא יִקָּבֵר אֵין שׁוֹמְעִין לוֹ. שֶׁהַקְּבוּרָה מִצְוָה שֶׁנֶּאֱמַר (דברים כא כג) \"כִּי קָבוֹר תִּקְבְּרֶנּוּ\":","כָּל הַמִּתְעַצֵּל בְּהֶסְפֵּדוֹ שֶׁל חָכָם אֵינוֹ מַאֲרִיךְ יָמִים. וְכָל הַמִּתְעַצֵּל בְּהֶסְפֵּד אָדָם כָּשֵׁר רָאוּי לִקָּבֵר בְּחַיָּיו. וְכָל הַמּוֹרִיד דְּמָעוֹת עַל אָדָם כָּשֵׁר הֲרֵי שְׂכָרוֹ שָׁמוּר עַל כָּךְ אֵצֶל הַקָּדוֹשׁ בָּרוּךְ הוּא:","אֵין מַנִּיחִין סֵפֶר תּוֹרָה עַל מִטָּתוֹ שֶׁל חָכָם. וְאֵין מְשַׁנִּין אוֹתוֹ מִמִּטָּה לְמִטָּה. וְאֵין מוֹצִיאִין מִטָּתוֹ אֶלָּא דֶּרֶךְ פְּתָחִים. לֹא שֶׁיְּשַׁלְשְׁלוּהָ דֶּרֶךְ גַּגּוֹת. וּבִשְׁאָר הָעָם מֻתָּר לַעֲשׂוֹת:","אֵין פּוֹחֲתִין מִשִּׁבְעָה מַעֲמָדוֹת לְמֵת. וְאֵין עוֹשִׂין מַעֲמָד וּמוֹשָׁב בְּפָחוֹת מֵעֲשָׂרָה. וְאֵין עוֹשִׂין אֶלָּא בִּקְרוֹבִים. וְאֵין עוֹשִׂין אֶלָּא בְּיוֹם רִאשׁוֹן וּבְבֵית הַקְּבָרוֹת וּבְמָקוֹם שֶׁנָּהֲגוּ. כֵּיצַד עוֹשִׂין בְּמָקוֹם שֶׁנָּהֲגוּ. מַעֲמִידִין שְׁאָר הַקְּרוֹבִים וּבְנֵי מִשְׁפָּחָה שֶׁאֵינָן בְּנֵי אָבֵל. וְאוֹמְרִין לִפְנֵיהֶם דִּבְרֵי קִינוֹת וְכַיּוֹצֵא בָּהֶן. וְאַחַר כָּךְ אוֹמֵר שְׁבוּ יְקָרִים שְׁבוּ. וְאוֹמֵר לִפְנֵיהֶם דְּבָרִים אֲחֵרִים כְּשֶׁהֵן יוֹשְׁבִין וְאַחַר כָּךְ עִמְדוּ יְקָרִים עֲמֹדוּ. וְאוֹמֵר כְּשֶׁהֵן עוֹמְדִין וְחוֹזֵר וְאוֹמֵר כָּךְ [עַד] שֶׁבַע פְּעָמִים:","כְּדֶרֶךְ שֶׁעוֹשִׂין מַעֲמָד וּמוֹשָׁב לַאֲנָשִׁים בְּמָקוֹם שֶׁנָּהֲגוּ. כָּךְ עוֹשִׂין לְנָשִׁים. וּמַסְפִּידִין הַנָּשִׁים כַּאֲנָשִׁים בְּכָל מָקוֹם. אֲבָל אֵין מַנִּיחִין מִטַּת הָאִשָּׁה בָּרְחוֹב לְעוֹלָם שֶׁזֶּה גְּנַאי לָאִשָּׁה. אֶלָּא סָמוּךְ לְמִיתָתָהּ קְבוּרָתָהּ:","הַמְלַקֵּט עֲצָמוֹת אֵין אוֹמְרִים עֲלֵיהֶם קִינִים וּנְהִי. וְלֹא בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים. אֲבָל אוֹמְרִים עֲלֵיהֶן דִּבְרֵי שֶׁבַח לְהַקָּדוֹשׁ בָּרוּךְ הוּא וְדִבְרֵי כִּבּוּשִׁים:","הַמְפַנֶּה אֲרוֹנוֹ שֶׁל מֵת מִמָּקוֹם לְמָקוֹם. אִם שִׁדְרוֹ קַיֶּמֶת עוֹמְדִין עָלָיו בְּשׁוּרָה. וְאוֹמְרִים עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. וּמַסְפִּידִין אוֹתוֹ אַף עַל פִּי שֶׁהֶעֱבִירוּהוּ לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ. וְאִם אֵין שִׁדְרוֹ קַיֶּמֶת אֵין מַסְפִּידִין אוֹתוֹ. וְאֵין עוֹמְדִין עָלָיו בְּשׁוּרָה וְאֵין אוֹמְרִין עָלָיו בִּרְכַּת אֲבֵלִים וְלֹא תַּנְחוּמֵי אֲבֵלִים. וְאֵלּוּ הֵן בִּרְכַּת אֲבֵלִים דְּבָרִים שֶׁאוֹמְרִים בְּבֵית הָאָבֶל. תַּנְחוּמֵי אֲבֵלִים שֶׁאוֹמְרִים בַּשּׁוּרָה:","הַמְלַקֵּט עַצְמוֹת אָבִיו וְאִמּוֹ הֲרֵי זֶה מִתְאַבֵּל עֲלֵיהֶן כָּל הַיּוֹם כֻּלּוֹ. וְלָעֶרֶב אֵין מִתְאַבֵּל אֲפִלּוּ צְרוּרִין לוֹ בִּסְדִינוֹ. וְאֵין אוֹמְרִין עֲלֵיהֶן קִינוֹת:","אֵין מַסְפִּידִין אֶת הַקְּטַנִּים. וּבֶן כַּמָּה שָׁנִים יִהְיֶה רָאוּי לְהֶסְפֵּד. בְּנֵי עֲנִיִּים אוֹ בְּנֵי זְקֵנִים בְּנֵי חָמֵשׁ. וּבְנֵי עֲשִׁירִים בְּנֵי שֵׁשׁ. אֶחָד זְכָרִים וְאֶחָד נְקֵבוֹת:","תִּינוֹק שֶׁמֵּת כָּל שְׁלֹשִׁים יוֹצֵא בְּחֵיק וְנִקְבָּר בְּאִשָּׁה אַחַת וּבִשְׁנֵי אֲנָשִׁים. אֲבָל לֹא בְּאִישׁ אֶחָד וּבִשְׁתֵּי נָשִׁים מִפְּנֵי הַיִּחוּד. וְאֵין עוֹמְדִין עָלָיו בְּשׁוּרָה. וְאֵין אוֹמְרִין עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. בֶּן שְׁלֹשִׁים יוֹם גְּמוּרִים יוֹצֵא בִּגְלוּסְקְמָא קְטַנָּה הַנִּטֶּלֶת בַּאֲגַפַּיִים. וְעוֹמְדִין עָלָיו בְּשׁוּרָה. וְאוֹמְרִין עָלָיו בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. בֶּן שְׁנֵים עָשָׂר חֹדֶשׁ יוֹצֵא בְּמִטָּה:","כָּל הַיּוֹצֵא בְּמִטָּה רַבִּים מַצְהִיבִין עָלָיו. וְכָל שֶׁאֵינוֹ יוֹצֵא בְּמִטָּה אֵין רַבִּים מַצְהִיבִין עָלָיו. וכָּל הַנִּכָּר לָרַבִּים רַבִּים מִתְעַסְּקִין בּוֹ. וְכָל שֶׁאֵינוֹ נִכָּר לָרַבִּים אֵין רַבִּים חַיָּבִין לְהִתְעַסֵּק בּוֹ. וּמָקוֹם שֶׁנָּהֲגוּ נָשִׁים לָצֵאת לִפְנֵי הַמִּטָּה יוֹצְאוֹת לִפְנֵי הַמִּטָּה. לְאַחַר הַמִּטָּה יוֹצְאוֹת לְאַחַר הַמִּטָּה:","הָעֲבָדִים וְהַשְּׁפָחוֹת אֵין מַסְפִּידִין אוֹתָן וְאֵין עוֹמְדִין עֲלֵיהֶן בְּשׁוּרָה. וְאֵין אוֹמְרִים עֲלֵיהֶן בִּרְכַּת אֲבֵלִים וְתַנְחוּמֵי אֲבֵלִים. אֶלָּא אוֹמְרִין לוֹ כְּשֵׁם שֶׁאוֹמְרִין לוֹ עַל שׁוֹרוֹ וְעַל חֲמוֹרוֹ הַמָּקוֹם יְמַלֵּא חֶסְרוֹנְךָ:"],"Mishneh Torah, Murderer and the Preservation of Life 10":["אֵין דִּין עֶגְלָה עֲרוּפָה נוֹהֵג אֶלָּא בָּאָרֶץ יִשְׂרָאֵל וְכֵן בְּעֵבֶר הַיַּרְדֵּן:","עֶגְלָה עֲרוּפָה בַּת שְׁתֵּי שָׁנִים אוֹ פָּחוֹת. אֲבָל אִם הָיְתָה בַּת שְׁתֵּי שָׁנִים וְיוֹם אֶחָד פְּסוּלָה. וְאֵין הַמּוּמִין פּוֹסְלִין וְאַף עַל פִּי כֵן אִם הָיְתָה טְרֵפָה פְּסוּלָה. (דברים כא ח) \"כַּפָּרָה\" נֶאֱמַר בָּהּ כְּקָדָשִׁים:","כָּל הָעֲבוֹדוֹת פּוֹסְלוֹת אֶת הָעֶגְלָה כְּמוֹ שֶׁפּוֹסְלִין בְּפָרָה אֲדֻמָּה שֶׁנֶּאֱמַר (דברים כא ג) \"אֲשֶׁר לֹא עֻבַּד בָּהּ\". וְלָמָּה נֶאֱמַר עֹל אַחַר שֶׁנֶּאֱמַר אֲשֶׁר לֹא עֻבַּד בָּהּ שֶׁהוּא כּוֹלֵל הָעל עִם שְׁאָר עֲבוֹדוֹת. שֶׁהָעל פּוֹסֵל בֵּין בִּשְׁעַת מְלָאכָה בֵּין שֶׁלֹּא בִּשְׁעַת מְלָאכָה כֵּיוָן שֶׁמָּשְׁכָה בְּעל טֶפַח נִפְסְלָה אַף עַל פִּי שֶׁלֹּא חָרַשׁ בָּהּ וְלֹא עָשָׂה בָּהּ מְלָאכָה. וּשְׁאָר עֲבוֹדוֹת אֵין פּוֹסְלִין אֶלָּא עַד שְׁעַת מְלָאכָה:","כָּל מְלָאכָה שֶׁהִיא לְצָרְכָּהּ כְּגוֹן פֵּרַשׂ טַלִּיתוֹ עָלֶיהָ מִפְּנֵי הַזְּבוּבִים אֵינוֹ פּוֹסְלָהּ. וְכָל שֶׁהִיא שֶׁלֹּא לְצָרְכָּהּ כְּגוֹן שֶׁפֵּרַשׂ טַלִּיתוֹ עָלֶיהָ לְנוֹשְׂאָהּ פְּסוּלָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת פָּרָה אֲדֻמָּה:","אֵין עוֹרְפִין אֶת הָעֶגְלָה אֶלָּא בַּיּוֹם לְפִי שֶׁנֶּאֱמַר בָּהּ (דברים כא ח) \"כַּפָּרָה\" כְּקָדָשִׁים. וְכָל הַיּוֹם כָּשֵׁר לַעֲרִיפָתָהּ. וְאֵין עוֹרְפִין שְׁתֵּי עֶגְלוֹת כְּאַחַת שֶׁאֵין עוֹשִׂין מִצְוֹת חֲבִילוֹת חֲבִילוֹת:","עֶגְלָה עֲרוּפָה אֲסוּרָה בַּהֲנָאָה וְנִקְבֶּרֶת בִּמְקוֹם עֲרִיפָתָהּ וּמִשֶּׁתֵּרֵד לַנַּחַל תֵּאָסֵר בַּהֲנָאָה אַף עַל פִּי שֶׁעֲדַיִן לֹא נֶעֶרְפָה. וְאִם מֵתָה אוֹ נִשְׁחֲטָה אַחַר יְרִידָתָהּ הֲרֵי זוֹ אֲסוּרָה בַּהֲנָאָה וְתִקָּבֵר:","נִמְצְאוּ הָעֵדִים זוֹמְמִין הֲרֵי זוֹ מֻתֶּרֶת בַּהֲנָאָה. כֵּיצַד. כְּגוֹן שֶׁאָמַר עֵד אֶחָד אֲנִי רָאִיתִי אֶת הַהוֹרֵג וּבָאוּ שְׁנַיִם וְהִכְחִישׁוּהוּ וְאָמְרוּ לוֹ לֹא רָאִיתָ. וְהִפְרִישׁוּ אֶת הָעֶגְלָה וְהוֹרִידוּהָ לַנַּחַל לְעָרְפָהּ עַל פִּיהֶם. וְאַחַר כָּךְ הוּזַמּוּ הַשְּׁנַיִם. הֲרֵי זוֹ מֻתֶּרֶת בַּהֲנָאָה:","נִמְצָא הַהוֹרֵג עַד שֶׁלֹּא תֵּעָרֵף הָעֶגְלָה תֵּצֵא וְתִרְעֶה בָּעֵדֶר. נִמְצָא אַחַר שֶׁנֶּעֶרְפָה תִּקָּבֵר בִּמְקוֹמָהּ. שֶׁעַל הַסָּפֵק בָּאָה מִתְּחִלָּתָהּ כִּפְּרָה סְפֵקָהּ וְהָלְכָה לָהּ. וְאַף עַל פִּי שֶׁנִּמְצָא הָרוֹצֵחַ אַחַר עֲרִיפָתָהּ הֲרֵי זֶה יֵהָרֵג שֶׁנֶּאֱמַר (דברים כא ט) \"וְאַתָּה תְּבַעֵר הַדָּם הַנָּקִי\":","הַנַּחַל שֶׁנֶּעֶרְפָה בּוֹ הָעֶגְלָה אָסוּר בִּזְרִיעָה וַעֲבוֹדָה לְעוֹלָם. שֶׁנֶּאֱמַר (דברים כא ד) \"אֲשֶׁר לֹא יֵעָבֵד בּוֹ וְלֹא יִזָּרֵעַ\". וְכָל הָעוֹבֵד שָׁם עֲבוֹדָה בְּגוּפָהּ שֶׁל קַרְקַע כְּגוֹן שֶׁחָרַשׁ אוֹ חָפַר אוֹ זָרַע אוֹ נָטַע וְכַיּוֹצֵא בָּאֵלּוּ הֲרֵי זֶה לוֹקֶה. וּמֻתָּר לִסְרֹק שָׁם פִּשְׁתָּן וּלְנַקֵּר שָׁם אֲבָנִים שֶׁזֶּה כְּמִי שֶׁאָרַג שָׁם בֶּגֶד אוֹ תְּפָרוֹ שֶׁאֵינָהּ מְלָאכָה בְּגוּף הַקַּרְקַע. לְכָךְ נֶאֱמַר לֹא יֵעָבֵד וְלֹא יִזָּרֵעַ מָה זְרִיעָה בְּגוּפָהּ שֶׁל קַרְקַע אַף כָּל הָעֲבוֹדָה שֶׁנֶּאֶסְרָה שָׁם אֵינָהּ אֶלָּא בְּגוּפָהּ שֶׁל קַרְקַע:","אַנְשֵׁי עִיר קְרוֹבָה שֶׁנִּתְאַחֲרוּ וְלֹא הֵבִיאוּ עֶגְלָה עֲרוּפָה. כּוֹפִין אוֹתָן וּמְבִיאִין וַאֲפִלּוּ לְאַחַר כַּמָּה שָׁנִים. שֶׁחַיָּבֵי עֶגְלָה עֲרוּפָה שֶׁעָבַר עָלֶיהָ יוֹם הַכִּפּוּרִים חַיָּבִים לְהָבִיא אַחַר יוֹם הַכִּפּוּרִים:"],"Mishneh Torah, Nazariteship 1":["הַנְּזִירוּת הוּא נֵדֶר מִכְּלַל נִדְרֵי אִסָּר שֶׁנֶּאֱמַר (במדבר ו ב) \"כִּי יִדֹּר נֶדֶר נָזִיר\" וְגוֹ'. וּמִצְוַת עֲשֵׂה שֶׁיְּגַדֵּל שְׂעַר רֹאשׁוֹ שֶׁנֶּאֱמַר (במדבר ו ה) \"גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ\". וְאִם גִּלֵּחַ בִּימֵי נִזְרוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (במדבר ו ה) \"תַּעַר לֹא יַעֲבֹר עַל רֹאשׁוֹ\". וְכֵן אָסוּר לְהִטָּמֵא לַמֵּתִים אוֹ לֶאֱכל דְּבָרִים שֶׁאֲסָרָן הַכָּתוּב עָלָיו (במדבר ו ד) \"מִגֶּפֶן הַיַּיִן\" (במדבר ו ד) (במדבר ו ח) \"כָּל יְמֵי נִזְרוֹ\":","עָבַר וְגִלֵּחַ אוֹ נִטְמָא אוֹ אָכַל מִגֶּפֶן הַיַּיִן הֲרֵי זֶה לוֹקֶה שְׁתַּיִם. אַחַת מִשּׁוּם (במדבר ל ג) \"לֹא יַחֵל דְּבָרוֹ\" שֶׁכּוֹלֵל כָּל הַנְּדָרִים. וְאַחַת מִשּׁוּם דָּבָר שֶׁעָבַר עָלָיו מִדְּבָרִים שֶׁאֲסוּרִין אִסּוּר מְיֻחָד עַל הַנָּזִיר:","נָדַר בְּנָזִיר וְקִיֵּם נִדְרוֹ כְּמִצְוָתוֹ הֲרֵי זֶה עוֹשֶׂה שָׁלֹשׁ מִצְוֹת עֲשֵׂה. הָאַחַת (במדבר ל ג) \"כְּכָל הַיֹּצֵא מִפִּיו יַעֲשֶׂה\" וַהֲרֵי עָשָׂה. וְהַשְּׁנִיָּה (במדבר ו ה) \"גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ\" וַהֲרֵי גִּדֵּל. וְהַשְּׁלִישִׁית תִּגְלַחְתּוֹ עִם הֲבָאַת קָרְבְּנוֹתָיו שֶׁנֶּאֱמַר (במדבר ו יח) \"וְגִלַּח הַנָּזִיר פֶּתַח אֹהֶל מוֹעֵד\" וְגוֹ':","הָאוֹמֵר לֹא אֶפָּטֵר מִן הָעוֹלָם עַד שֶׁאֶהֱיֶה נָזִיר הֲרֵי זֶה נָזִיר מִיָּד שֶׁמָּא יָמוּת עַתָּה. וְאִם אֵחֵר נְזִירוּתוֹ הֲרֵי זֶה עוֹבֵר בְּבַל (דברים כג כב) \"תְּאַחֵר לְשַׁלְּמוֹ\" וְאֵין לוֹקִין עַל לָאו זֶה:","אֵין אוֹמְרִין בִּנְזִירוּת עַד שֶׁיּוֹצִיא בִּשְׂפָתָיו דָּבָר שֶׁמַּשְׁמָעוֹ אֵצֶל כָּל הָעָם כָּעִנְיָן שֶׁבְּלִבּוֹ. אֶלָּא כֵּיוָן שֶׁגָּמַר בְּלִבּוֹ וְהוֹצִיא בִּשְׂפָתָיו דְּבָרִים שֶׁעִנְיָנָם שֶׁיִּהְיֶה נָזִיר אַף עַל פִּי שֶׁהֵן עִנְיָנוֹת רְחוֹקוֹת וְאַף עַל פִּי שֶׁאֵין בְּמַשְׁמָעָן לְשׁוֹן נְזִירוּת הֲרֵי הוּא נָזִיר:","כֵּיצַד. הֲרֵי שֶׁהָיָה נָזִיר עוֹבֵר לְפָנָיו וְאָמַר אֶהְיֶה הֲרֵי זֶה נָזִיר הוֹאִיל וּבְלִבּוֹ הָיָה שֶׁיִּהְיֶה כְּמוֹ זֶה וְאַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ וְאָמַר אֶהְיֶה כְּמוֹ זֶה. וְכֵן אִם אָחַז בִּשְׂעָרוֹ וְאָמַר אֶהְיֶה נָאֶה אוֹ אֱהֵא מְכַלְכֵּל אוֹ אֲהָא מְסַלְסֵל אוֹ שֶׁאָמַר הֲרֵינִי מְסַלְסֵל אוֹ הֲרֵינִי מְכַלְכֵּל אוֹ הֲרֵי עָלַי לְשַׁלֵּחַ פֶּרַע הֲרֵי זֶה נָזִיר וְהוּא שֶׁיִּגְמֹר בְּלִבּוֹ לְהַזִּיר:","אָמַר הֲרֵי עָלַי צִפֳּרִים אַף עַל פִּי שֶׁהָיָה נָזִיר עוֹבֵר לְפָנָיו וְאַף עַל פִּי שֶׁהָיָה בְּלִבּוֹ לְהַזִּיר אֵינוֹ נָזִיר וַהֲרֵי זֶה כְּמִי שֶׁלֹּא הוֹצִיא בִּשְׂפָתָיו כְּלוּם:","כָּל כִּנּוּיֵי נְזִירוּת כִּנְזִירוּת. כֵּיצַד. מְקוֹמוֹת הָעִלְּגִים שֶׁמְּשַׁנִּין אֶת הַדִּבּוּר וְאָמַר שָׁם הֲרֵינִי נָזִיק נָזִיחַ פָּזִיחַ הֲרֵי זֶה נָזִיר:","הָאוֹמֵר הֲרֵינִי נָזִיר מִן הַחַרְצַנִּים בִּלְבַד אוֹ מִן הַזַּגִּים בִּלְבַד אוֹ הֲרֵינִי נָזִיר מִן הַתִּגְלַחַת אוֹ הֲרֵינִי נָזִיר מִן הַטֻּמְאָה בִּלְבַד הֲרֵי זֶה נָזִיר גָּמוּר וְכָל דִּקְדּוּקֵי נְזִירוּת עָלָיו וְאַף עַל פִּי שֶׁלֹּא הָיָה בְּלִבּוֹ לְהַזִּיר אֶלָּא מִדָּבָר זֶה בִּלְבַד הוֹאִיל וְדָבָר שֶׁנָּזַר מִמֶּנּוּ אָסוּר עַל הַנְּזִירִים הֲרֵי זֶה נָזִיר גָּמוּר:","אֲבָל הָאוֹמֵר הֲרֵינִי נָזִיר מִן הַגְּרוֹגָרוֹת אוֹ מִן הַדְּבֵלָה וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה אָסוּר בָּהֶן וְאֵינוֹ נָזִיר:","מָזְגוּ לוֹ כּוֹס שֶׁל יַיִן וְנָתְנוּ לוֹ לִשְׁתּוֹת וְאָמַר הֲרֵינִי נָזִיר מִמֶּנּוּ הֲרֵי זֶה נָזִיר גָּמוּר. וְאִם הָיָה מַר נֶפֶשׁ אוֹ כּוֹעֵס אוֹ מִתְאַבֵּל וְהָיוּ מְבַקְּשִׁין מִמֶּנּוּ שֶׁיִּשְׁתֶּה כְּדֵי לְשַׁכֵּחַ עֲמָלוֹ וְאָמַר הֲרֵי זֶה נָזִיר מִמֶּנּוּ הֲרֵי זֶה אָסוּר בְּאוֹתוֹ הַכּוֹס בִּלְבַד וְאֵינוֹ נָזִיר. שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא שֶׁלֹּא יִשְׁתֶּה כּוֹס זֶה:","וְכֵן שִׁכּוֹר שֶׁנָּתְנוּ לוֹ כּוֹס כְּדֵי לְרַוּוֹתוֹ וְאָמַר הֲרֵי זֶה נָזִיר מִמֶּנּוּ הֲרֵי זֶה אָסוּר בְּאוֹתוֹ הַכּוֹס בִּלְבַד וְאֵינוֹ חַיָּב בִּנְזִירוּת שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא שֶׁלֹּא יְשַׁכְּרוּ אוֹתוֹ יוֹתֵר מִדַּאי. וְאִם הִגִּיעַ לְשִׁכְרוּתוֹ שֶׁל לוֹט אֵין דְּבָרָיו כְּלוּם וְאֵינוֹ חַיָּב עַל כָּל עֲבֵרָה שֶׁיַּעֲשֶׂה שֶׁמִּשֶּׁהִגִּיעַ לְשִׁכְרוּתוֹ שֶׁל לוֹט אֵינוֹ בֶּן חִיּוּב:","הָאוֹמֵר הֲרֵינִי נָזִיר עַל מְנָת שֶׁאֶהֱיֶה שׁוֹתֶה יַיִן אוֹ מִטַּמֵּא לַמֵּתִים אוֹ מְגַלֵּחַ שְׂעָרִי הֲרֵי זֶה נָזִיר וְאָסוּר בְּכֻלָּם. מִפְּנֵי שֶׁהִתְנָה עַל מַה שֶּׁכָּתוּב בַּתּוֹרָה וְכָל הַמַּתְנֶה עַל הַכָּתוּב בַּתּוֹרָה תְּנָאוֹ בָּטֵל:","נָדַר בְּנָזִיר וְאָמַר לֹא הָיִיתִי יוֹדֵעַ שֶׁהַנָּזִיר אָסוּר בְּיַיִן אוֹ בְּטֻמְאָה אוֹ בְּתִגְלַחַת וְאִלּוּ הָיִיתִי יוֹדֵעַ כֵּן לֹא הָיִיתִי נוֹדֵר הֲרֵי זֶה נָזִיר וְחַיָּב בְּכֻלָּם. שֶׁהֲרֵי הוּא הָיָה יוֹדֵעַ שֶׁאָסַר עַצְמוֹ בְּאֶחָד מִשְּׁלֹשָׁה מִינִין וּכְבָר בֵּאַרְנוּ שֶׁאֲפִלּוּ לֹא נָדַר אֶלָּא מֵאֶחָד מֵהֶם אָסוּר בְּכֻלָּן:","אָמַר יוֹדֵעַ הָיִיתִי שֶׁהַנָּזִיר אָסוּר בְּכָל אֵלּוּ אֲבָל הָיָה בְּדַּעְתִּי שֶׁמֻּתָּר לִי לִשְׁתּוֹת אֲנִי הַיַּיִן מִפְּנֵי שֶׁאֵינִי יָכוֹל לִחְיוֹת בְּלֹא יַיִן אוֹ מִפְּנֵי שֶׁאֲנִי קוֹבֵר אֶת הַמֵּתִים הֲרֵי זֶה אֵינוֹ נָזִיר. מִפְּנֵי שֶׁאֵלּוּ בִּכְלַל נִדְרֵי שְׁגָגוֹת שֶׁאֵינָם צְרִיכִין שְׁאֵלָה לְחָכָם כְּמוֹ שֶׁבֵּאַרְנוּ:","הָאוֹמֵר הֲרֵי יָדִי נְזִירָה הֲרֵי רַגְלִי נְזִירָה לֹא אָמַר כְּלוּם. הֲרֵי רֹאשִׁי נָזִיר כְּבֵדִי נְזִירָה הֲרֵי זֶה נָזִיר. זֶה הַכְּלָל כָּל אֵיבָר שֶׁאִם יִנָּטֵל מִן הַחַי יָמוּת אִם אָמַר הֲרֵי הוּא נָזִיר הֲרֵי זֶה נָזִיר:","הָאוֹמֵר הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לִי בֵּן. אִם נוֹלַד לוֹ בֵּן זָכָר הֲרֵי זֶה נָזִיר. אֲבָל אִם נוֹלְדָה לוֹ בַּת אוֹ טֻמְטוּם אוֹ אַנְדְּרוֹגִינוּס אֵין זֶה נָזִיר. אָמַר הֲרֵינִי נָזִיר כְּשֶׁיִּהְיֶה לִי וָלָד אֲפִלּוּ נוֹלַד לוֹ בַּת אוֹ טֻמְטוּם וְאַנְדְּרוֹגִינוּס הֲרֵי זֶה נָזִיר. הִפִּילָה אִשְׁתּוֹ אֵינוֹ נָזִיר. חָזְרָה וְנִתְעַבְּרָה וְיָלְדָה הֲרֵי זֶה נָזִיר:"],"Mishneh Torah, Negative Mitzvot 100":["שלא להקריב אתנן ומחיר, שנאמר \"לא תביא אתנן זונה ומחיר כלב\" (דברים כג,יט)."],"Mishneh Torah, Negative Mitzvot 111":["שלא לפדות שדה החרם, שנאמר \"לא ייגאל\" (ויקרא כז,כח)."],"Mishneh Torah, Negative Mitzvot 122":["שלא לשבור עצם בפסח שני, שנאמר (שמות יב, מו): \"ועצם לא תשברו בו\"."],"Mishneh Torah, Negative Mitzvot 133":["שלא יאכל זר תרומות, שנאמר \"וכל זר, לא יאכל קודש\" (ויקרא כב,י)."],"Mishneh Torah, Negative Mitzvot 144":["שלא לאכול בכור תמים חוץ לירושלים, שנאמר \"לא תוכל . . . ובכורות\" (דברים יב,יז)."],"Mishneh Torah, Negative Mitzvot 155":["שלא לאחר הנדרים והנדבות שנדר ושנדב, שנאמר \"לא תאחר לשלמו\" (דברים כג,כב)."],"Mishneh Torah, Negative Mitzvot 166":["שלא ייטמא כוהן הדיוט לשאר מתים, שנאמר \"לנפש לא ייטמא בעמיו\" (ויקרא כא,א)."],"Mishneh Torah, Negative Mitzvot 177":["שלא לאכול רמש הארץ, שנאמר \"ולא תטמאו את נפשותיכם, בכל השרץ הרומש על הארץ\" (ויקרא יא,מד)."],"Mishneh Torah, Negative Mitzvot 188":["שלא לאכול בשר שור הנסקל, שנאמר \"ולא ייאכל את בשרו\" (שמות כא,כח)."],"Mishneh Torah, Negative Mitzvot 199":["שלא לאכול חמץ אחר חצות יום ארבעה עשר, שנאמר \"לא תאכל עליו חמץ\" (דברים טז,ג)."],"Mishneh Torah, Negative Mitzvot 209":["שלא יגלח הנזיר, שנאמר \"תער לא יעבור על ראשו\" (במדבר ו,ה)."],"Mishneh Torah, Negative Mitzvot 22":["שלא ליהנות בציפויי נעבד, שנאמר \"לא תחמוד כסף וזהב עליהם\" (דברים ז,כה)."],"Mishneh Torah, Negative Mitzvot 230":["שלא יתבע הלוואה שעברה עליה שביעית, שנאמר \"לא ייגוש את ריעהו ואת אחיו\" (דברים טו,ב)."],"Mishneh Torah, Negative Mitzvot 241":["שלא למשכן האלמנה, שנאמר \"ולא תחבול בגד אלמנה\" (דברים כד, יז)."],"Mishneh Torah, Negative Mitzvot 252":["שלא להונות את הגר בדברים, שנאמר \"וְגֵר לֹא תוֹנֶה\" (שמות כב, כ)."],"Mishneh Torah, Negative Mitzvot 263":["שלא למכור אשת יפת תואר, שנאמר \"ומכור לא תמכרנה\" (דברים כא, יד)."],"Mishneh Torah, Negative Mitzvot 274":["שלא ליקח שוחד, שנאמר \"וְשֹׁחַד לֹא תִקָּח\" (שמות כג, ח)."],"Mishneh Torah, Negative Mitzvot 285":["שלא להעיד בשקר, שנאמר \"לֹא תַעֲנֶה בְּרֵעֲךָ עֵד שָׁקֶר\" (שמות כ, יב)."],"Mishneh Torah, Negative Mitzvot 296":["שלא ליקח כופר בגלות רוצח בשגגה, שנאמר \"וְלֹא תִקְחוּ כֹּפֶר לָנוּס אֶל עִיר מִקְלָטוֹ\" (במדבר לה, לב)."],"Mishneh Torah, Negative Mitzvot 306":["שלא ליקח אם על הבנים, שנאמר \"לא תיקח האם, על הבנים\" (דברים כב,ו)."],"Mishneh Torah, Negative Mitzvot 317":["שלא לקלל אחד משאר ישראל, שנאמר \"לא תקלל חירש\" (ויקרא יט,יד)."],"Mishneh Torah, Negative Mitzvot 328":["שלא לעשות מלאכה בראשון של חג, שנאמר בו \"כל מלאכת עבודה, לא תעשו\" (ויקרא כג,לה; ויקרא כג,לו; במדבר כט,יב)."],"Mishneh Torah, Negative Mitzvot 339":["שלא לגלות ערוות אישה ובת בתה, שנאמר \"ואת בת בתה, לא תיקח\" (ויקרא יח,יז)."],"Mishneh Torah, Negative Mitzvot 35":["שלא לחבור חבר, שנאמר \"וחובר, חבר\" (דברים יח,יא)."],"Mishneh Torah, Negative Mitzvot 360":["שלא ייקח סריס בת ישראל, שנאמר \"לא יבוא פצוע דכא\" (דברים כג,ב)."],"Mishneh Torah, Negative Mitzvot 42":["שלא ללבוש שעטנז כמו שלובשין כומרי עבודה זרה, שנאמר \"לא תלבש שעטנז\" (דברים כב,יא)."],"Mishneh Torah, Negative Mitzvot 53":["שלא יישא עמוני ומואבי בת ישראל לעולם, שנאמר \"לא יבוא עמוני ומואבי, בקהל ה'\" (דברים כג,ד)."],"Mishneh Torah, Negative Mitzvot 64":["שלא לנסות את דבר ה', שנאמר \"לֹא תְנַסּוּ אֶת ה' אֱלֹהֵיכֶם\" (דברים ו, טז)."],"Mishneh Torah, Negative Mitzvot 75":["שלא יעבוד כהן טמא, שנאמר \"וְיִנָּזְרוּ מִקָּדְשֵׁי בְנֵי יִשְׂרָאֵל\" (ויקרא כב, ב)."],"Mishneh Torah, Negative Mitzvot 86":["שלא להוציא בדי הארון, שנאמר \"לֹא יָסֻרוּ מִמֶּנּוּ\" (שמות כה, טו)."],"Mishneh Torah, Negative Mitzvot 97":["שלא ייתן מום בקודשים, שנאמר \"מום לא יהיה בו\" (ויקרא כב,כא); כלומר, לא תיתן בו מום."],"Mishneh Torah, Neighbors 5":["חֲצַר הַשֻּׁתָּפִין כָּל אֶחָד מֵהֶן כּוֹפֶה אֶת חֲבֵרוֹ לַעֲשׂוֹת בָּהּ בֵּית שַׁעַר וְדֶלֶת. וְכֵן כָּל הַדְּבָרִים שֶׁהֶחָצֵר צְרִיכָה לָהֶם צֹרֶךְ גָּדוֹל. אוֹ דְּבָרִים שֶׁנָּהֲגוּ בְּנֵי הַמְּדִינָה לַעֲשׂוֹתָם. אֲבָל שְׁאָר הַדְּבָרִים כְּגוֹן צִיּוּר וְכִיּוּר וְכַיּוֹצֵא בּוֹ אֵינוֹ כּוֹפֵהוּ. עָשָׂה אֶחָד מֵהֶן מֵעַצְמוֹ אִם גִּלָּה הַשֵּׁנִי דַּעְתּוֹ שֶׁנּוֹחַ לוֹ בְּמַה שֶּׁעָשָׂה חֲבֵרוֹ מְגַלְגְּלִין עָלָיו אֶת הַכּל וְנוֹתֵן חֶלְקוֹ בַּהוֹצָאָה:","מִי שֶׁיֵּשׁ לוֹ בַּיִת בְּחָצֵר אַחֶרֶת בְּנֵי הֶחָצֵר מְשַׁעְבְּדִין אוֹתוֹ לַעֲשׂוֹת עִמָּהֶם דֶּלֶת וְנֶגֶר וּמַנְעוּל. אֲבָל בִּשְׁאָר הַדְּבָרִים אֵין מְשַׁעְבְּדִין אוֹתוֹ. וְאִם הָיָה שָׁרוּי עִמָּהֶם בְּאוֹתָהּ חָצֵר מְשַׁעְבְּדִין אוֹתוֹ עַל הַכּל:","אֶחָד מִן הַשֻּׁתָּפִין בְּחָצֵר שֶׁבִּקֵּשׁ לְהַעֲמִיד בָּהּ בְּהֵמָה אוֹ רֵחַיִם אוֹ לְגַדֵּל בָּהּ תַּרְנְגוֹלִין חֲבֵרוֹ מְעַכֵּב עָלָיו. וְכֵן שְׁאָר הַדְּבָרִים שֶׁאֵין דֶּרֶךְ אַנְשֵׁי הַמָּקוֹם לַעֲשׂוֹתָן בְּחַצְרוֹתֵיהֶן בְּכֻלָּן הַשֻּׁתָּפִין מְעַכְּבִין זֶה עַל זֶה. חוּץ מִן הַכְּבִיסָה לְפִי שֶׁאֵין דַּרְכָּן שֶׁל בְּנוֹת יִשְׂרָאֵל לְהִתְבַּזּוֹת עַל גַּב הַנָּהָר:","אֶחָד חֲצַר הַשֻּׁתָּפִין וְאֶחָד מָבוֹי שֶׁאֵינוֹ מְפֻלָּשׁ כָּל בְּנֵי הַמָּבוֹי מְעַכְּבִין זֶה עַל זֶה שֶׁלֹּא לְהִשְׁתַּמֵּשׁ בַּמָּבוֹי אֶלָּא בִּדְבָרִים שֶׁדֶּרֶךְ בְּנֵי הַמְּדִינָה לְהִשְׁתַּמֵּשׁ בָּהֶן בַּמְּבוֹאוֹת:","אֶחָד מִן הַשֻּׁתָּפִין בְּחָצֵר שֶׁהֶעֱמִיד בְּהֵמָה אוֹ רֵחַיִם וְכַיּוֹצֵא בָּהֶן בֶּחָצֵר וְלֹא מִחָה בּוֹ שֻׁתָּפוֹ הֲרֵי זֶה מְעַכֵּב עָלָיו כָּל זְמַן שֶׁיִּרְצֶה. וְאִם הֶעֱמִיד בִּפְנֵי בְּהֵמָה זוֹ וְכַיּוֹצֵא בָּהּ מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים הֶחֱזִיק. שֶׁהַשֻּׁתָּפִין מַקְפִּידִין עַל הַמְּחִצָּה וְהוֹאִיל וְהִנִּיחוֹ מָחַל. בַּמֶּה דְּבָרִים אֲמוּרִים בַּחֲצַר הַשֻּׁתָּפִין. אֲבָל בַּחֲצַר חֲבֵרוֹ אֲפִלּוּ הֶעֱמִיד בְּהֶמְתּוֹ וְעָשָׂה לוֹ מְחִצָּה לֹא הֶחֱזִיק שֶׁהַדָּבָר יָדוּעַ שֶׁאֵין זֶה אֶלָּא דֶּרֶךְ שְׁאֵלָה. וְהוּא הַדִּין לְכָל מַעֲמִיד תַּנּוּר וְכִירַיִם וּמִגְדַּל תַּרְנְגוֹלִין וְכַיּוֹצֵא בָּהֶן. שֶׁאִם תֹּאמַר הֶחֱזִיק אֵין לְךָ אָדָם שֶׁמַּשְׁאִיל מָקוֹם לַחֲבֵרוֹ:","אֶחָד מִן הַשֻּׁתָּפִין שֶׁבִּקֵּשׁ לִפְתֹּחַ לוֹ חַלּוֹן בְּתוֹךְ בֵּיתוֹ לַחֲצַר חֲבֵרוֹ מְעַכֵּב עָלָיו מִפְּנֵי שֶׁמִּסְתַּכֵּל בּוֹ מִמֶּנּוּ. וְאִם פָּתַח יִסְתֹּם. וְכֵן לֹא יִפְתְּחוּ הַשֻּׁתָּפִים בְּחָצֵר פֶּתַח בַּיִת כְּנֶגֶד פֶּתַח בַּיִת אוֹ חַלּוֹן כְּנֶגֶד חַלּוֹן. אֲבָל פּוֹתֵחַ אָדָם לִרְשׁוּת הָרַבִּים פֶּתַח כְּנֶגֶד פֶּתַח וְחַלּוֹן כְּנֶגֶד חַלּוֹן. מִפְּנֵי שֶׁאוֹמֵר לוֹ הֲרֵינִי כְּאֶחָד מִבְּנֵי רְשׁוּת הָרַבִּים שֶׁרוֹאִין אוֹתְךָ:","וְאַף עַל פִּי כֵן לֹא יִפְתַּח אָדָם חֲנוּת כְּנֶגֶד פֶּתַח חֲצַר חֲבֵרוֹ שֶׁזֶּה הֶזֵּק קָבוּעַ תָּמִיד. שֶׁהֲרֵי בְּנֵי רְשׁוּת הָרַבִּים עוֹבְרִים וְשָׁבִים וְזֶה יוֹשֵׁב בַּחֲנוּתוֹ כָּל הַיּוֹם וּמַבִּיט בְּפֶתַח חֲבֵרוֹ:","אֶחָד מִן הַשֻּׁתָּפִין בְּחָצֵר שֶׁלָּקַח בַּיִת בְּחָצֵר אַחֶרֶת אֵינוֹ יָכוֹל לִפְתֹּחַ פִּתְחוֹ לַחֲצַר הַשֻּׁתָּפִין שֶׁלּוֹ. אֲפִלּוּ בָּנָה עֲלִיָּה עַל גַּבֵּי בֵּיתוֹ לֹא יַעֲשֶׂה לָהּ פֶּתַח לְתוֹךְ הֶחָצֵר לְפִי שֶׁמַּרְבֶּה עֲלֵיהֶן אֶת הַדֶּרֶךְ נַעֲשָׂה כְּמִי שֶׁהָיָה לָזֶה שָׁכֵן אֶחָד וְנַעֲשׂוּ לוֹ שְׁכֵנִים הַרְבֵּה. אֲבָל פּוֹתֵחַ הוּא פֶּתַח עֲלִיָּה לְתוֹךְ בֵּיתוֹ. וְאִם רָצָה לַחְלֹק חַדְרוֹ לִשְׁנַיִם חוֹלֵק:","מִכָּאן אַתָּה לָמֵד שֶׁאֶחָד מִן הַשֻּׁתָּפִין שֶׁהֵבִיא אֶצְלוֹ לְבֵיתוֹ אַנְשֵׁי בַּיִת אַחֶרֶת יֵשׁ לַחֲבֵרוֹ לְעַכֵּב עָלָיו מִפְּנֵי שֶׁמַּרְבֶּה עָלָיו אֶת הַדֶּרֶךְ. וְכֵן הַמַּשְׂכִּיר בֵּיתוֹ לְבַעַל בַּיִת אֶחָד וְאַחַר כָּךְ הֵבִיא עִמּוֹ קְרוֹבָיו אוֹ מְיֻדָּעָיו לִשְׁכֹּן עִמּוֹ כְּאֶחָד בְּבַיִת זֶה הֲרֵי הַמַּשְׂכִּיר מְעַכֵּב עָלָיו:","הָיָה פֶּתַח שֶׁל אֶחָד מִן הַשֻּׁתָּפִין קָטָן אֵינוֹ יָכוֹל לְהַרְחִיבוֹ שֶׁהֲרֵי שֻׁתָּפוֹ אוֹמֵר לוֹ בְּפֶתַח קָטָן אֲנִי יָכוֹל לְהִסָּתֵר מִמְּךָ בִּשְׁעַת תַּשְׁמִישׁ וְאֵינִי יָכוֹל לְהִסָּתֵר מִמְּךָ בְּפֶתַח גָּדוֹל. וְאִם הָיָה הַפֶּתַח גָּדוֹל לֹא יַעֲשֶׂנּוּ שְׁנַיִם שֶׁהֲרֵי אוֹמֵר לוֹ בְּפֶתַח אֶחָד אֲנִי יָכוֹל לְהִסָּתֵר בִּשְׁנַיִם אֵינִי יָכוֹל:","אֲבָל מִי שֶׁהָיָה לוֹ פֶּתַח קָטָן לִרְשׁוּת הָרַבִּים וְרָצָה לְהַרְחִיבוֹ. אוֹ הָיָה רָחָב וְרָצָה לַעֲשׂוֹתוֹ שְׁנַיִם. אֵין חֲבֵרוֹ שֶׁכְּנֶגְדוֹ מְעַכֵּב עָלָיו. וְאֵין צָרִיךְ לוֹמַר בְּנֵי רְשׁוּת הָרַבִּים שֶׁאֵינָן יְכוֹלִין לְעַכֵּב עָלָיו:","כּוֹפִין בְּנֵי מָבוֹי זֶה אֶת זֶה לַעֲשׂוֹת לָהֶן לְחִי אוֹ קוֹרָה לַמָּבוֹי:","מִי שֶׁיֵּשׁ לוֹ פֶּתַח לַמָּבוֹי אֵין בְּנֵי מָבוֹי כּוֹפִין אוֹתוֹ לַעֲשׂוֹת דֶּלֶת לַמָּבוֹי שֶׁיָּכוֹל לוֹמַר רְצוֹנִי שֶׁאֶכָּנֵס בַּחֲבִילָתִי עַד פִּתְחִי. וּמָבוֹי הַמְפֻלָּשׁ לִרְשׁוּת הָרַבִּים וּבִקְּשׁוּ בְּנֵי הַמָּבוֹי לְהַעֲמִיד לָהֶם דְּלָתוֹת בְּנֵי רְשׁוּת הָרַבִּים מְעַכְּבִין עֲלֵיהֶם מִפְּנֵי שֶׁפְּעָמִים דּוֹחֲקִין הָרַבִּים וְנִכְנָסִין בּוֹ:","מִי שֶׁבִּקֵּשׁ לִפְתֹּחַ פֶּתַח בְּמָבוֹי שֶׁאֵינוֹ מְפֻלָּשׁ בְּנֵי מָבוֹי מְעַכְּבִין עָלָיו מִפְּנֵי שֶׁמַּרְבֶּה עֲלֵיהֶם אֶת הַדֶּרֶךְ. וְאִם הָיָה מָבוֹי מְפֻלָּשׁ פּוֹתֵחַ כָּל פֶּתַח שֶׁיִּרְצֶה לְכַתְּחִלָּה:","הָיָה לוֹ פֶּתַח סָתוּם בְּמָבוֹי שֶׁאֵינוֹ מְפֻלָּשׁ הֲרֵי זֶה פּוֹתְחוֹ בְּכָל עֵת שֶׁיִּרְצֶה. וְאִם פָּרַץ אֶת פְּצִימָיו בְּנֵי מָבוֹי מְעַכְּבִין עָלָיו. וְכֵן אֶחָד מִבְּנֵי מָבוֹי שֶׁבִּקֵּשׁ לִסְתֹּם פִּתְחוֹ וּלְהַחְזִירוֹ לְמָבוֹי אַחֵר בְּנֵי מָבוֹי מְעַכְּבִין עָלָיו שֶׁמָּא יָבוֹא עֲלֵיהֶם מַס וּמִתְמַעֵט מֵחֶלְקָן מִן הַמַּס הַקָּצוּב עַל בְּנֵי הַמָּבוֹי. לְפִיכָךְ מָקוֹם שֶׁאֵין הַמַּס קָצוּב עַל בְּנֵי הַמָּבוֹי הֲרֵי זֶה סוֹתֵם פִּתְחוֹ בְּכָל עֵת שֶׁיִּרְצֶה:","חָמֵשׁ חֲצֵרוֹת הַפְּתוּחוֹת לְמָבוֹי שֶׁאֵינוֹ מְפֻלָּשׁ כֻּלָּן מִשְׁתַּמְּשׁוֹת עִם הַחִיצוֹנָה וְהַחִיצוֹנָה מִשְׁתַּמֶּשֶׁת לְעַצְמָהּ. וְכֵן הַשְּׁנִיָּה מִשְׁתַּמֶּשֶׁת לְעַצְמָהּ וּמִשְׁתַּמֶּשֶׁת עִם הַחִיצוֹנָה וְאֵינָהּ מִשְׁתַּמֶּשֶׁת עִם הַשְּׁאָר. נִמְצֵאת הַפְּנִימִית מִשְׁתַּמֶּשֶׁת עִם כֻּלָּן וּמִשְׁתַּמֶּשֶׁת לְעַצְמָהּ. לְפִיכָךְ אִם בַּעַל הַשְּׁנִיָּה בָּנָה אִצְטַבָּא כְּנֶגֶד פִּתְחוֹ וּסְתָמוֹ אֵין הַחִיצוֹנָה יְכוֹלָה לְעַכֵּב עָלָיו. אֲבָל כָּל הַפְּנִימִיּוֹת מְעַכְּבִין עָלָיו מִפְּנֵי שֶׁמַּרְבֶּה עֲלֵיהֶן אֶת הַדֶּרֶךְ בָּאֹרֶךְ שֶׁהֲרֵי מַקִּיפִין הָאִצְטַבָּא. וְכֵן בַּעַל הַשְּׁנִיָּה שֶׁפָּתַח לַחֲצֵרוֹ פֶּתַח שֵׁנִי בֵּינוֹ וּבֵין הַחִיצוֹנָה אֵין הַחִיצוֹנָה מְעַכֶּבֶת עָלָיו שֶׁאֵין לוֹ לְהִשְׁתַּמֵּשׁ אֶלָּא מִפִּתְחוֹ וְלַחוּץ. אֲבָל אִם פָּתַח הַפֶּתַח הַשֵּׁנִי בֵּינוֹ וּבֵין הַשְּׁלִישִׁי הַפְּנִימִית מְעַכֶּבֶת עָלָיו שֶׁאֵין לוֹ לְהִשְׁתַּמֵּשׁ בַּמָּבוֹי אֶלָּא מִפֶּתַח חֲצֵרוֹ הָרִאשׁוֹן וְלַחוּץ. וְכֵן הַדִּין בְּכֻלָּן:"],"Mishneh Torah, Oaths 5":["מִי שֶׁנִּשְׁבַּע שֶׁזָּרַק אִישׁ פְּלוֹנִי צְרוֹר לַיָּם וְהוּא לֹא זָרַק. אוֹ שֶׁלֹּא זָרַק וְהוּא זָרַק. הֲרֵי זֶה חַיָּב בִּשְׁבוּעַת בִּטּוּי. וְאַף עַל פִּי שֶׁאֵינוֹ בִּלְהַבָּא שֶׁהֲרֵי אֵינוֹ יָכוֹל לְהִשָּׁבַע שֶׁיִּזְרֹק וְשֶׁלֹּא יִזְרֹק אִישׁ פְּלוֹנִי. וְכָל מִי שֶׁנִּשְׁבַּע עַל אֲחֵרִים שֶׁיַּעֲשׂוּ כָּךְ וְכָךְ אוֹ לֹא יַעֲשׂוּ אֲפִלּוּ הָיוּ בָּנָיו אוֹ אִשְׁתּוֹ אֵינוֹ חַיָּב בִּשְׁבוּעַת בִּטּוּי. שֶׁהֲרֵי אֵין בְּיָדוֹ לֹא לְקַיֵּם וְלֹא לְבַטֵּל. וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת שֶׁהֲרֵי אֵין בְּיָדוֹ לְקַיֵּם שְׁבוּעָה זוֹ וְנִמְצָא גּוֹרֵם לִשְׁבוּעַת שָׁוְא:","וְלָמָּה אֵינוֹ לוֹקֶה מִשּׁוּם שְׁבוּעַת שָׁוְא שֶׁהֲרֵי אֶפְשָׁר לְאוֹתָן אֲחֵרִים שֶׁיִּשְׁמְעוּ מִמֶּנּוּ וְתִתְקַיֵּם שְׁבוּעָתוֹ. וְנִמְצָא כְּשֶׁמַּתְרִים בּוֹ בְּעֵת שֶׁנִּשְׁבַּע הַתְרָאַת סָפֵק שֶׁאֵין לוֹקִין עָלֶיהָ אֶלָּא אִם כֵּן הָיָה לָאו שֶׁבּוֹ מְפֹרָשׁ בַּתּוֹרָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת סַנְהֶדְרִין. וְאֵין אוֹתָן אֲחֵרִים נִזְקָקִין לְקַיֵּם דִּבְרֵי זֶה הַנִּשְׁבָּע אֶלָּא אִם כֵּן עָנוּ אָמֵן כְּמוֹ שֶׁבֵּאַרְנוּ:","וְאִם קִיְּמוּ דְּבָרָיו הֲרֵי אֵלּוּ מְשֻׁבָּחִין שֶׁלֹּא הִרְגִּילוּ לְהוֹצִיא שְׁבוּעָה לַשָּׁוְא:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנִּשְׁבַּע עַל דָּבָר שֶׁאֵינוֹ בִּרְשׁוּתוֹ. כְּגוֹן שֶׁנִּשְׁבַּע רְאוּבֵן עַל שִׁמְעוֹן שֶׁלֹּא יֵלֵךְ בִּסְחוֹרָה אוֹ שֶׁלֹּא יֹאכַל בָּשָׂר וְכַיּוֹצֵא בָּזֶה. אֲבָל אִם נִשְׁבַּע רְאוּבֵן שֶׁלֹּא יִכָּנֵס שִׁמְעוֹן בְּבֵיתוֹ וְשֶׁלֹּא יֵהָנֶה מִנְּכָסָיו וְעָבַר שִׁמְעוֹן וְנִכְנַס לְבֵיתוֹ שֶׁל רְאוּבֵן וְנֶהֱנָה מִנְּכָסָיו שֶׁלֹּא מִדַּעַת רְאוּבֵן רְאוּבֵן פָּטוּר שֶׁהֲרֵי הוּא אָנוּס וְשִׁמְעוֹן חַיָּב שֶׁעָבַר עַל דָּבָר הָאָסוּר לוֹ לַעֲשׂוֹתוֹ. שֶׁלֹּא נִשְׁבַּע זֶה אֶלָּא עַל דָּבָר שֶׁהוּא בִּרְשׁוּתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שְׁבוּעָה שֶׁלֹּא אֹכַל וְאָכַל אֳכָלִין שֶׁאֵינָן רְאוּיִין לַאֲכִילָה וְשָׁתָה מַשְׁקִים שֶׁאֵינָן רְאוּיִין לִשְׁתִיָּה פָּטוּר. אָכַל דְּבָרִים הָאֲסוּרִין מִן הַתּוֹרָה בַּאֲכִילָה כְּגוֹן שֶׁאָכַל כְּזַיִת נְבֵלוֹת וּטְרֵפוֹת שְׁקָצִים וּרְמָשִׂים פָּטוּר מִשּׁוּם שְׁבוּעַת בִּטּוּי. שְׁבוּעָה שֶׁאֹכַל וְאָכַל אֳכָלִין שֶׁאֵינָן רְאוּיִים לַאֲכִילָה וְשָׁתָה מַשְׁקִין שֶׁאֵינָן רְאוּיִין לִשְׁתִיָּה אוֹ שֶׁאָכַל נְבֵלוֹת וּטְרֵפוֹת וְכַיּוֹצֵא בָּהֶן פָּטוּר מִשְּׁבוּעַת בִּטּוּי שֶׁהֲרֵי יָצָא יְדֵי אֲכִילָה מֵאַחַר שֶׁהֵן חֲשׁוּבִין אֶצְלוֹ אֲכִילָתָן שְׁמָהּ אֲכִילָה:","שְׁבוּעָה שֶׁלֹּא אָכַלְתִּי וְהוּא אָכַל דְּבָרִים שֶׁאֵינָן רְאוּיִין לַאֲכִילָה אוֹ נְבֵלוֹת וּטְרֵפוֹת חַיָּב שֶׁאֲכִילָתָן שְׁמָהּ אֲכִילָה שֶׁכְּבָר הֵן חֲשׁוּבִין אֶצְלוֹ שֶׁהֲרֵי אֲכָלָן. אֲבָל לְהַבָּא שֶׁנִּשְׁבַּע שֶׁלֹּא יֹאכַל וְנִקְרָה מִקְרֶה וַאֲכָלָן אֵינָהּ אֲכִילָה כְּמוֹ שֶׁבֵּאַרְנוּ:","שְׁבוּעָה שֶׁלֹּא אֹכַל כָּל שֶׁהוּא מִנְּבֵלוֹת וּטְרֵפוֹת וְאָכַל פָּחוֹת מִכְּזַיִת חַיָּב בִּשְׁבוּעָה שֶׁהֲרֵי אֵינוֹ מֻשְׁבָּע עַל חֲצִי שִׁעוּר מֵהַר סִינַי:","שְׁבוּעָה שֶׁאֹכַל פָּחוֹת מִכְּזַיִת נְבֵלָה וּטְרֵפָה חַיָּב בִּשְׁבוּעַת בִּטּוּי. שְׁבוּעָה שֶׁלֹּא אֹכַל עָפָר וְכַיּוֹצֵא בּוֹ מִדְּבָרִים שֶׁאֵינָן רְאוּיִין לַאֲכִילָה אִם אָכַל כְּזַיִת חַיָּב. אָכַל פָּחוֹת מִכְּזַיִת הֲרֵי זֶה סָפֵק שֶׁמָּא יִתְחַיֵּב בְּכָל שֶׁהוּא מִפְּנֵי שֶׁאֵין זֶה דַּרְכּוֹ לַאֲכִילָה כְּדֵי לְהַצְרִיכוֹ שִׁעוּר:","וְכֵן הַנִּשְׁבָּע שֶׁלֹּא לֶאֱכל חַרְצָן וְאָכַל מִמֶּנּוּ פָּחוֹת מִכְּזַיִת הֲרֵי זֶה סָפֵק. הָיָה הַנִּשְׁבָּע נָזִיר שֶׁהוּא אָסוּר בְּחַרְצָן בִּכְזַיִת וְאָכַל מִמֶּנּוּ פָּחוֹת מִכְּזַיִת אֵינוֹ חַיָּב בִּשְׁבוּעַת בִּטּוּי. שֶׁהֲרֵי אֵין דַּעְתּוֹ בִּשְׁבוּעָתוֹ אֶלָּא עַל (כָּל) כְּזַיִת שֶׁהוּא מֻשְׁבָּע עָלָיו וְאֵין שְׁבוּעָה חָלָה עָלָיו. לְפִיכָךְ אִם פֵּרֵשׁ וְאָמַר שְׁבוּעָה שֶׁלֹּא אֹכַל חַרְצָן אֶחָד וַאֲכָלוֹ חַיָּב:","שְׁבוּעָה שֶׁלֹּא אֹכַל תְּמָרִים וּנְבֵלוֹת וּטְרֵפוֹת וְאָכַל כְּזַיִת נְבֵלָה אוֹ טְרֵפָה חַיָּב אַף מִשּׁוּם שְׁבוּעַת בִּטּוּי שֶׁהֲרֵי כָּלַל דְּבָרִים הָאֲסוּרִין עִם דְּבָרִים הַמֻּתָּרִין. וּמִתּוֹךְ שֶׁחָלָה שְׁבוּעָה עַל הַתְּמָרִים חָלָה עַל דְּבָרִים הָאֲסוּרִים כְּמוֹ שֶׁבֵּאַרְנוּ:","אֲבָל אִם נִשְׁבַּע שֶׁלֹּא יֹאכַל נְבֵלָה וּטְרֵפָה וְכַיּוֹצֵא בָּהֶן בֵּין אָכַל בֵּין לֹא אָכַל אֵין כָּאן חִיּוּב שְׁבוּעָה כְּלָל לֹא שְׁבוּעַת בִּטּוּי וְלֹא שְׁבוּעַת שָׁוְא:","נִשְׁבַּע שֶׁיֹּאכַל נְבֵלָה וּטְרֵפָה וְכַיּוֹצֵא בָּהֶן מֵאִסּוּרֵי תּוֹרָה הֲרֵי זֶה לוֹקֶה מִשּׁוּם שְׁבוּעַת שָׁוְא בֵּין אָכַל בֵּין לֹא אָכַל:","שְׁבוּעָה שֶׁאֹכַל כִּכָּר זוֹ שְׁבוּעָה שֶׁלֹּא אֹכָלֶנָּה הַשְּׁנִיָּה שְׁבוּעַת שָׁוְא שֶׁהֲרֵי מִצְוָה עָלָיו לְאָכְלָהּ וְלוֹקֶה עַל שְׁבוּעָה שְׁנִיָּה בֵּין אָכַל בֵּין לֹא אָכַל. וְאִם לֹא אֲכָלָהּ חַיָּב אַף בִּשְׁבוּעַת בִּטּוּי:","שְׁבוּעָה שֶׁלֹּא אֹכַל כִּכָּר זוֹ שְׁבוּעָה שֶׁאֹכָלֶנָּה. הַשְּׁנִיָּה שְׁבוּעַת שָׁוְא שֶׁהֲרֵי זוֹ אֲסוּרָה עָלָיו לְאָכְלָהּ וְלוֹקֶה עַל שְׁבוּעָה שְׁנִיָּה זוֹ בֵּין אֲכָלָהּ בֵּין לֹא אֲכָלָהּ. וְאִם אֲכָלָהּ לוֹקֶה אַף מִשּׁוּם שְׁבוּעַת בִּטּוּי. וְכֵן כָּל הַנִּשְׁבָּע לְבַטֵּל אֶת הַמִּצְוָה וְלֹא בִּטֵּל פָּטוּר מִשְּׁבוּעַת בִּטּוּי וְלוֹקֶה מִשּׁוּם שְׁבוּעַת שָׁוְא וְעוֹשֶׂה הַמִּצְוָה שֶׁנִּשְׁבַּע לְבַטְּלָהּ:","כֵּיצַד. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יַעֲשֶׂה סֻכָּה וְשֶׁלֹּא יִלְבַּשׁ תְּפִלִּין וְשֶׁלֹּא יִתֵּן צְדָקָה. וְכֵן הַנִּשְׁבָּע לַחֲבֵרוֹ שֶׁלֹּא אָעִיד לְךָ עֵדוּת זוֹ שֶׁאֲנִי יוֹדְעָהּ אוֹ שֶׁלֹּא אָעִיד לְךָ אִם אֵדַע לְךָ עֵדוּת הֲרֵי זֶה לוֹקֶה מִשּׁוּם שְׁבוּעַת שָׁוְא מִפְּנֵי שֶׁהוּא מְצֻוֶּה לְהָעִיד. וְכֵן הָאוֹמֵר לַחֲבֵרוֹ שְׁבוּעָה שֶׁלֹּא אֵדַע לְךָ עֵדוּת הֲרֵי זוֹ שְׁבוּעַת שָׁוְא שֶׁאֵין בְּיָדוֹ שֶׁלֹּא יֵדַע לוֹ עֵדוּת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נִשְׁבַּע לְקַיֵּם אֶת הַמִּצְוָה וְלֹא קִיֵּם פָּטוּר מִשּׁוּם שְׁבוּעַת בִּטּוּי. כֵּיצַד. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁיַּעֲשֶׂה לוּלָב אוֹ סֻכָּה אוֹ שֶׁיִּתֵּן צְדָקָה לְעָנִי אוֹ שֶׁיָּעִיד לוֹ אִם יֵדַע לוֹ עֵדוּת וְלֹא עָשָׂה וְלֹא נָתַן וְלֹא הֵעִיד הֲרֵי זֶה פָּטוּר מִשּׁוּם שְׁבוּעַת בִּטּוּי. שֶׁאֵין שְׁבוּעַת בִּטּוּי חָלָה אֶלָּא עַל דִּבְרֵי הָרְשׁוּת שֶׁאִם רָצָה עוֹשֶׂה וְאִם לֹא רָצָה אֵינוֹ עוֹשֶׂה שֶׁנֶּאֱמַר (ויקרא ה ד) \"לְהָרַע אוֹ לְהֵיטִיב\". לְפִיכָךְ כָּל הַנִּשְׁבָּע לְהָרַע לַאֲחֵרִים פָּטוּר מִשְּׁבוּעַת בִּטּוּי כְּגוֹן שֶׁנִּשְׁבַּע שֶׁיַּכֶּה אֶת פְּלוֹנִי אוֹ יְקַלְּלֶנּוּ אוֹ יִגְזל מָמוֹנוֹ אוֹ יִמְסְרֶנּוּ בְּיַד אַנָּס מִפְּנֵי שֶׁהוּא מְצֻוֶּה שֶׁלֹּא לַעֲשׂוֹת. וְיֵרָאֶה לִי שֶׁהוּא לוֹקֶה מִשּׁוּם שְׁבוּעַת שָׁוְא:","נִשְׁבַּע לְהָרַע לְעַצְמוֹ כְּגוֹן שֶׁנִּשְׁבַּע שֶׁיַּחֲבל בְּעַצְמוֹ אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי שְׁבוּעָה חָלָה עָלָיו. וְאִם לֹא הֵרַע לְעַצְמוֹ חַיָּב מִשּׁוּם שְׁבוּעַת בִּטּוּי. נִשְׁבַּע לְהֵיטִיב לַאֲחֵרִים הֲטָבָה שֶׁבְּיָדוֹ לַעֲשׂוֹתָהּ כְּגוֹן שֶׁיְּדַבֵּר עָלָיו לַשִּׁלְטוֹן אוֹ יְכַבְּדֶנּוּ שְׁבוּעָה חָלָה עָלָיו. וְאִם עָבַר וְלֹא עָשָׂה חַיָּב מִשּׁוּם שְׁבוּעַת בִּטּוּי:","נִשְׁבַּע שֶׁלֹּא יֹאכַל מַצָּה שָׁנָה אוֹ שְׁנָתַיִם. הֲרֵי זֶה אָסוּר לֶאֱכל מַצָּה בְּלֵילֵי הַפֶּסַח וְאִם אָכַל חַיָּב מִשּׁוּם שְׁבוּעַת בִּטּוּי. וְאֵין זֶה שְׁבוּעַת שָׁוְא שֶׁהֲרֵי לֹא נִשְׁבַּע שֶׁלֹּא יֹאכַל מַצָּה בְּלֵילֵי הַפֶּסַח אֶלָּא כָּלַל עִתִּים שֶׁאֲכִילַת מַצָּה בָּהֶם רְשׁוּת עִם עֵת שֶׁאֲכִילָתָהּ בּוֹ מִצְוָה וּמִתּוֹךְ שֶׁחָלָה שְׁבוּעָה עַל שְׁאָר הַיָּמִים חָלָה עַל לֵיל הַפֶּסַח. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. כְּגוֹן שֶׁנִּשְׁבַּע שֶׁלֹּא יֵשֵׁב בְּצֵל סֻכָּה לְעוֹלָם אוֹ שֶׁלֹּא יַעֲלֶה עָלָיו בֶּגֶד שָׁנָה אוֹ שְׁנָתַיִם:","נִשְׁבַּע שֶׁהֵנִיחַ תְּפִלִּין הַיּוֹם אוֹ לֹא הֵנִיחַ. שֶׁנִּתְעַטֵּף בְּצִיצִית אוֹ לֹא נִתְעַטֵּף. הֲרֵי זֶה שְׁבוּעַת בִּטּוּי לְשֶׁעָבַר. שֶׁזֶּה מַגִּיד דָּבָר שֶׁנַּעֲשָׂה וְלֹא נִשְׁבַּע עַל הַמִּצְוָה לֹא לְקַיְּמָהּ וְלֹא לְבַטְּלָהּ:","נִשְׁבַּע שֶׁלֹּא יִישַׁן שְׁלֹשֶׁת יָמִים. אוֹ שֶׁלֹּא יֹאכַל כְּלוּם שִׁבְעַת יָמִים וְכַיּוֹצֵא בָּזֶה שֶׁהִיא שְׁבוּעַת שָׁוְא. אֵין אוֹמְרִין יֵעוֹר זֶה עַד שֶׁיִּצְטַעֵר וְיָצוּם עַד שֶׁיִּצְטַעֵר וְלֹא יִהְיֶה בּוֹ כֹּחַ לִסְבּל וְאַחַר כָּךְ יֹאכַל אוֹ יִישַׁן. אֶלָּא מַלְקִין אוֹתוֹ מִיָּד מִשּׁוּם שְׁבוּעַת שָׁוְא וְיִישַׁן וְיֹאכַל בְּכָל עֵת שֶׁיִּרְצֶה:","נִשְׁבַּע שֶׁרָאָה גָּמָל פּוֹרֵחַ בָּאֲוִיר. אָמְרוּ לוֹ הֵיאַךְ נִשְׁבַּעְתָּ לַשָּׁוְא וְאָמַר עוֹף גָּדוֹל רָאִיתִי וּמִגָּדְלוֹ קְרָאתִיו גָּמָל וְכָךְ הָיָה בְּדַעְתִּי אֵין זֶה כְּלוּם. שֶׁאֵין כָּל אָדָם קוֹרְאִין גָּמָל אֶלָּא לְגָמָל וּבָטְלָה דַּעְתּוֹ אֵצֶל כָּל אָדָם וְלוֹקֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","דָּבָר יָדוּעַ אֵצֶל הַחֲכָמִים בַּעֲלֵי שֵׂכֶל וּמַדָּע שֶׁהַשֶּׁמֶשׁ גְּדוֹלָה מִן הָאָרֶץ מֵאָה וְשִׁבְעִים פְּעָמִים. נִשְׁבַּע אֶחָד מִן הָעָם שֶׁהַשֶּׁמֶשׁ גְּדוֹלָה מִן הָאָרֶץ אֵינוֹ לוֹקֶה מִשּׁוּם שְׁבוּעַת שָׁוְא שֶׁאַף עַל פִּי שֶׁהַדָּבָר כֵּן הוּא אֵין דָּבָר זֶה גָּלוּי וְיָדוּעַ לְכָל הָעָם אֶלָּא לִגְדוֹלֵי הַחֲכָמִים בִּלְבַד. וְאֵינוֹ חַיָּב אֶלָּא אִם כֵּן נִשְׁבַּע עַל דָּבָר שֶׁגָּלוּי וְיָדוּעַ לִשְׁלֹשָׁה בְּנֵי אָדָם מִשְּׁאָר הָעָם כְּגוֹן אִישׁ שֶׁהוּא אִישׁ וְאֶבֶן שֶׁהוּא אֶבֶן. וְכֵן אִם נִשְׁבַּע שֶׁהַשֶּׁמֶשׁ קְטַנָּה מִן הָאָרֶץ אֵינוֹ לוֹקֶה. וְאַף עַל פִּי שֶׁאֵין הַדָּבָר כֵּן מִפְּנֵי שֶׁאֵין זֶה יָדוּעַ לְכָל אָדָם וְאֵינוֹ כְּמִי שֶׁנִּשְׁבַּע עַל הָאִישׁ שֶׁהוּא אִשָּׁה שֶׁהֲרֵי לֹא נִשְׁבַּע אֶלָּא עַל רְאִיַּת עֵינָיו שֶׁהֲרֵי הוּא רוֹאֶה אוֹתָהּ קְטַנָּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִדִּבְרֵי חֶשְׁבּוֹן תְּקוּפוֹת מַזָּלוֹת וְגִימַטְרִיָּאוֹת וְכַיּוֹצֵא בָּהֶן מִדִּבְרֵי חָכְמָה שֶׁאֵין נִכָּרִין אֶלָּא לַאֲנָשִׁים אֲחֵרִים:"],"Mishneh Torah, Offerings for Unintentional Transgressions 11":["שִׁנּוּי יֵשׁ בְּשִׁגְגַת טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו מַה שֶּׁאֵין כֵּן בִּשְׁאָר כְּרֵתוֹת. שֶׁכָּל הַכְּרֵתוֹת כֵּיוָן שֶׁשָּׁגַג וְנוֹדַע לוֹ בַּסּוֹף שֶׁחָטָא אַף עַל פִּי שֶׁלֹּא הָיְתָה לוֹ יְדִיעָה בַּתְּחִלָּה הֲרֵי זֶה חַיָּב חַטָּאת. אֲבָל בְּטֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו אֵינוֹ מֵבִיא קָרְבָּן עוֹלֶה וְיוֹרֵד עַד שֶׁתִּהְיֶה לוֹ יְדִיעָה לַטֻּמְאָה וִידִיעָה לַקֹּדֶשׁ אוֹ לַמִּקְדָּשׁ בַּתְּחִלָּה וִידִיעָה לַטֻּמְאָה וִידִיעָה לַקֹּדֶשׁ אוֹ לַמִּקְדָּשׁ בַּסּוֹף וְהֶעְלֵם בֵּינְתַיִם. כֵּיצַד. נִטְמָא וְנִכְנַס לַמִּקְדָּשׁ אוֹ אָכַל קֹדֶשׁ. וְאַחַר כָּךְ נוֹדַע לוֹ שֶׁנִּטְמָא וְשֶׁהָיָה טָמֵא בְּשָׁעָה שֶׁאָכַל אוֹ שֶׁנִּכְנַס. וְשֶׁקֹּדֶשׁ הָיָה זֶה שֶׁאֲכָלוֹ אוֹ מִקְדָּשׁ הָיָה זֶה שֶׁנִּכְנַס לוֹ. הֲרֵי זֶה פָּטוּר מִקָּרְבָּן עַד שֶׁיֵּדַע שֶׁנִּטְמָא [וְשֶׁזֶּה קֹדֶשׁ] וְשֶׁזֶּה מִקְדָּשׁ קֹדֶם שֶׁיִּכָּנֵס אוֹ קֹדֶם שֶׁיֹּאכַל. כֵּיצַד. נִטְמָא וְיָדַע שֶׁנִּטְמָא וְיָדַע שֶׁזֶּה מִקְדָּשׁ וְשֶׁזֶּה קֹדֶשׁ. וְאַחַר כָּךְ נֶעֶלְמָה מִמֶּנּוּ הַטֻּמְאָה וְשָׁכַח שֶׁנִּטְמָא וְנִכְנַס לַמִּקְדָּשׁ אוֹ אָכַל קֹדֶשׁ. וְהוּא יוֹדֵעַ שֶׁזֶּה מִקְדָּשׁ וְשֶׁזֶּה קֹדֶשׁ. אוֹ שֶׁשָּׁגַג וְשָׁכַח שֶׁזֶּה מִקְדָּשׁ אוֹ שֶׁזֶּה בְּשַׂר קֹדֶשׁ וְהוּא יוֹדֵעַ שֶׁהוּא טָמֵא וְנִכְנַס אוֹ אָכַל. אוֹ שֶׁשָּׁגַג אוֹ שָׁכַח שֶׁנִּטְמָא וְשָׁכַח שֶׁזֶּה בְּשַׂר קֹדֶשׁ וְשֶׁזֶּה מִקְדָּשׁ וְנִכְנַס אוֹ אָכַל וְאַחַר כָּךְ נוֹדַע לוֹ דְּבָרִים שֶׁנִּתְעַלְּמוּ מִמֶּנּוּ. הֲרֵי זֶה מֵבִיא קָרְבָּן עוֹלֶה וְיוֹרֵד בְּכָל צַד וְצַד מִשֵּׁשׁ מַחֲלוֹקוֹת אֵלּוּ. וּמִנַּיִן שֶׁדִּין שִׁגְגַת מִקְדָּשׁ וְקָדָשָׁיו כָּךְ הוּא. שֶׁהֲרֵי בִּשְׁאָר שְׁגָגוֹת נֶאֱמַר (ויקרא ד כז) \"בַּעֲשֹׂתָהּ אַחַת מִמִּצְוֹת ה' אֲשֶׁר לֹא תֵעָשֶׂינָה וְאָשֵׁם\" (ויקרא ד כח) \"אוֹ הוֹדַע אֵלָיו חַטָּאתוֹ אֲשֶׁר חָטָא\". כֵּיוָן שֶׁיָּדַע בַּסּוֹף אַף עַל פִּי שֶׁלֹּא יָדַע בַּתְּחִלָּה. וּבְטֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו נֶאֱמַר (ויקרא ה ג ד) \"וְנֶעְלַם מִמֶּנּוּ וְהוּא יָדַע וְאָשֵׁם\" מֵאַחַר שֶׁנֶּאֱמַר וְנֶעְלַם מִמֶּנּוּ מִכְּלָל שֶׁהָיְתָה שָׁם יְדִיעָה בַּתְּחִלָּה וְנֶאֱמַר וְהוּא יָדַע [וְאָשֵׁם] הָא לָמַדְתָּ שֶׁהוּא צָרִיךְ יְדִיעָה בַּתְּחִלָּה וִידִיעָה בַּסּוֹף וְהֶעְלֵם בֵּינְתַיִם:","נִטְמָא וְיָדַע שֶׁנִּטְמָא [וְיָדַע שֶׁזֶּה קֹדֶשׁ וְשֶׁזֶּה מִקְדָּשׁ] אֲבָל לֹא יָדַע בְּאֵי זֶה אָב נִטְמָא וְשָׁכַח שֶׁנִּטְמָא וְאַחַר כָּךְ נִכְנַס לַמִּקְדָּשׁ אוֹ אָכַל קֹדֶשׁ וְנוֹדַע לוֹ אַחַר שֶׁנִּכְנַס אוֹ אַחַר שֶׁאָכַל בְּאֵי זֶה אָב נִטְמָא [הֲרֵי זֶה חַיָּב קָרְבָּן] אַף עַל פִּי שֶׁלֹּא יָדַע בַּתְּחִלָּה בְּאֵי זֶה אָב נִטְמָא הוֹאִיל וְיָדַע שֶׁהוּא טָמֵא הֲרֵי הָיְתָה שָׁם יְדִיעַת טֻמְאָה בַּתְּחִלָּה. אֲבָל אִם נֶעֶלְמוּ מִמֶּנּוּ הִלְכוֹת טֻמְאָה. כְּגוֹן שֶׁנִּטְמָא בְּכַעֲדָשָׁה מִן הַשֶּׁרֶץ וְיָדַע שֶׁהַשֶּׁרֶץ מְטַמֵּא וְלֹא יָדַע בַּשִּׁעוּר וְשָׁכַח שֶׁנָּגַע בְּשֶׁרֶץ כְּלָל וְנִכְנַס אוֹ אָכַל וְאַחַר כָּךְ נוֹדַע לוֹ [שֶׁנָּגַע] בְּכַעֲדָשָׁה מִן הַשֶּׁרֶץ הֲרֵי זֶה סָפֵק אִם חַיָּב קָרְבָּן אוֹ פָּטוּר. וְכֵן מִי שֶׁלֹּא רָאָה הַמִּקְדָּשׁ מִיָּמָיו וְלֹא הֵבִין מְקוֹמוֹ. אִם נִטְמָא וְיָדַע שֶׁנִּטְמָא וְנִכְנַס לַמִּקְדָּשׁ וְלֹא יָדַע בַּתְּחִלָּה שֶׁזֶּהוּ מְקוֹמוֹ שֶׁהֲרֵי לֹא רָאָהוּ מֵעוֹלָם. וְאַחַר כָּךְ זָכַר הַטֻּמְאָה וְיָדַע שֶׁזֶּה מִקְדָּשׁ. הֲרֵי זֶה סָפֵק אִם יְדִיעָה שֶׁיֵּשׁ מִקְדָּשׁ בָּעוֹלָם יְדִיעָה. אוֹ עַד שֶׁיֵּדַע מְקוֹמוֹ תְּחִלָּה. יֵרָאֶה לִי שֶׁאֵלּוּ הַחַיָּבִים קָרְבָּן מִסָּפֵק אֵינָן מְבִיאִין קָרְבָּן שֶׁמָּא יַכְנִיסוּ חֻלִּין לַעֲזָרָה. וְאִם תֹּאמַר וַהֲלֹא חַטַּאת הָעוֹף בָּאָה עַל הַסָּפֵק וְאֵינָהּ נֶאֱכֶלֶת. מִפְּנֵי שֶׁהַמֵּבִיא אוֹתָהּ מְחֻסַּר כִּפּוּרִים אָסוּר לֶאֱכל בְּקָדָשִׁים עַד שֶׁיָּבִיא כַּפָּרָתוֹ. אֲבָל מִי שֶׁאֵינוֹ מְחֻסַּר כִּפּוּרִים אֵינוֹ מֵבִיא קָרְבָּן מִסָּפֵק:","מִי שֶׁנִּטְמָא בָּעֲזָרָה צָרִיךְ שֶׁיֵּדַע תְּחִלָּה שֶׁנִּטְמָא וְשֶׁזֶּה מִקְדָּשׁ. וְאִם נֶעְלָם מִמֶּנּוּ אַחֲרֵי כֵן שֶׁנִּטְמָא וַהֲרֵי הוּא זָכוּר שֶׁזֶּה מִקְדָּשׁ. אוֹ שֶׁנֶּעֱלַם מִמֶּנּוּ שֶׁזֶּה מִקְדָּשׁ וְלֹא שָׁכַח שֶׁנִּטְמָא. אוֹ שֶׁנִּתְעַלְּמוּ מִמֶּנּוּ זֶה וְזֶה. כְּשֶׁיִּוָּדַע לוֹ יָבִיא קָרְבָּן עוֹלֶה וְיוֹרֵד. וְהוּא שֶׁיִּשְׁהֶה כַּשִּׁעוּר כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בִּיאַת מִקְדָּשׁ:","מִי שֶׁטִּמֵּא עַצְמוֹ בְּמֵזִיד וְלֹא שָׁהָה כַּשִּׁעוּר. הֲרֵי זֶה סָפֵק אִם שִׁעוּר הִשְׁתַּחֲוָיָה לְאָנוּס בִּלְבַד אוֹ אַף לְמֵזִיד. וּלְפִיכָךְ אִם נֶעְלַם מִמֶּנּוּ וְיָצָא וְלֹא שָׁהָה אֵינוֹ מֵבִיא קָרְבָּן. וְכֵן אִם תָּלָה עַצְמוֹ בַּאֲוִיר עֲזָרָה. הַדָּבָר סָפֵק אִם אֲוִיר עֲזָרָה כַּעֲזָרָה אוֹ אֵינוֹ כַּעֲזָרָה:","מִי שֶׁנִּסְתַּפֵּק לוֹ אִם נִכְנַס לַמִּקְדָּשׁ אוֹ אָכַל קֹדֶשׁ בְּטֻמְאָה אוֹ לָאו אֵינוֹ מֵבִיא אָשָׁם תָּלוּי. שֶׁאֵין מְבִיאִין קָרְבָּן עַל לֹא הוֹדַע אֶלָּא בְּכָרֵת שֶׁחַיָּבִין עַל שִׁגְגָתוֹ חַטָּאת קְבוּעָה:","מִי שֶׁהָיוּ לְפָנָיו שְׁנֵי שְׁבִילִים אֶחָד טָמֵא וְאֶחָד טָהוֹר הָלַךְ בָּרִאשׁוֹן וְחָזַר וְהָלַךְ בַּשֵּׁנִי וּבְעֵת שֶׁהָלַךְ בַּשֵּׁנִי שָׁכַח שֶׁהָלַךְ בָּרִאשׁוֹן וְנֶעֶלְמָה מִמֶּנָּה טֻמְאָה זוֹ וְנִכְנַס לַמִּקְדָּשׁ אוֹ אָכַל קֹדֶשׁ חַיָּב. וְאַף עַל פִּי שֶׁלֹּא הָיְתָה לוֹ בַּתְּחִלָּה יְדִיעָה גְּמוּרָה לַטֻּמְאָה אֶלָּא מִקְצָת יְדִיעָה שֶׁהֲרֵי לֹא יָדַע שֶׁהָלַךְ בִּשְׁנֵי שְׁבִילִין שֶׁבְּהִלּוּךְ שְׁנֵיהֶן יְהֵא טָמֵא בְּוַדַּאי וְאַף עַל פִּי כֵן חַיָּב חַטָּאת שֶׁמִּקְצָת יְדִיעָה כְּכָל יְדִיעָה. הָלַךְ בָּרִאשׁוֹן וְנִכְנַס לַמִּקְדָּשׁ אוֹ אָכַל קֹדֶשׁ. פָּטוּר מִפְּנֵי שֶׁהוּא סְפֵק טָמֵא:","הִזָּה שְׁלִישִׁי וּשְׁבִיעִי וְטָבַל וְאַחַר שֶׁנִּכְנַס לַמִּקְדָּשׁ הָלַךְ בַּשֵּׁנִי וְחָזַר וְנִכְנַס לַמִּקְדָּשׁ חַיָּב. שֶׁהֲרֵי נִכְנַס כְּשֶׁהוּא טָמֵא לַמִּקְדָּשׁ בְּוַדַּאי אוֹ בְּפַעַם רִאשׁוֹנָה אוֹ בְּפַעַם שְׁנִיָּה. וְאַף עַל פִּי שֶׁכָּל יְדִיעָה מֵהֶן סְפֵק יְדִיעָה הִיא שֶׁהֲרֵי כָּל שְׁבִיל מֵהֶן סָפֵק הוּא כָּאן בְּטֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו עָשׂוּ סְפֵק יְדִיעָה כִּידִיעָה:","הָיָה טָמֵא וְאָמְרוּ לוֹ שְׁנַיִם נִכְנַסְתָּ לַמִּקְדָּשׁ וְהוּא אוֹמֵר לָהֶם לֹא נִכְנַסְתִּי נֶאֱמָן וְאֵינוֹ מֵבִיא קָרְבָּן שֶׁאִם יִרְצֶה יֹאמַר מֵזִיד הָיִיתִי. אָמְרוּ לוֹ שְׁנַיִם טָמֵא הָיִיתָ כְּשֶׁנִּכְנַסְתָּ לַמִּקְדָּשׁ וּבְפָנֵינוּ נִטְמֵאתָ וְיָדַעְתָּ שֶׁאַתָּה טָמֵא אַף עַל פִּי שֶׁהָיָה בֵּין טֻמְאָה זוֹ שֶׁמְּעִידִין בָּהּ וּבֵין כְּנִיסָתוֹ לַמִּקְדָּשׁ יָמִים רַבִּים שֶׁאֶפְשָׁר לוֹ שֶׁיֹּאמַר כְּבָר טָבַלְתִּי הוֹאִיל וְהִכְחִישׁ אֶת הָעֵדִים וְאָמַר לֹא נִטְמֵאתִי מֵעוֹלָם הֲרֵי אֵלּוּ נֶאֱמָנִים וּמֵבִיא קָרְבָּן עַל פִּיהֶם. אִם הֱבִיאוּהוּ שְׁנַיִם לִידֵי מִיתָה חֲמוּרָה קַל וָחֹמֶר שֶׁיְּבִיאוּהוּ לִידֵי קָרְבָּן הַקַּל שֶׁהֲרֵי הִכְחִישָׁן:","טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו שֶׁהָיָה לָהּ יְדִיעָה בַּתְּחִלָּה וְלֹא הָיָה לָהּ יְדִיעָה בַּסּוֹף שָׂעִיר שֶׁל יוֹם הַכִּפּוּרִים הַנַּעֲשֶׂה בִּפְנִים וְיוֹם הַכִּפּוּרִים תּוֹלִין עַד שֶׁיִּוָּדַע לוֹ וְיָבִיא קָרְבָּן עוֹלֶה וְיוֹרֵד. וְשֶׁאֵין בָּהּ יְדִיעָה בַּתְּחִלָּה אֲבָל יֵשׁ בָּהּ יְדִיעָה בַּסּוֹף שָׂעִיר הַנַּעֲשֶׂה בַּחוּץ בְּיוֹם הַכִּפּוּרִים וְיוֹם הַכִּפּוּרִים מְכַפְּרִין. וְעַל שֶׁאֵין בָּהּ יְדִיעָה לֹא בַּתְּחִלָּה וְלֹא בַּסּוֹף שְׂעִירֵי הָרְגָלִים וּשְׂעִירֵי רָאשֵׁי חֳדָשִׁים מְכַפְּרִין. וְעַל זְדוֹן טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו פַּר כֹּהֵן גָּדוֹל שֶׁל יוֹם הַכִּפּוּרִים מְכַפֵּר אִם הָיָה הַמֵּזִיד מִן הַכֹּהֲנִים. וְאִם הָיָה מִיִּשְׂרָאֵל דַּם שָׂעִיר הַנַּעֲשֶׂה בִּפְנִים וְיוֹם הַכִּפּוּרִים מְכַפֵּר. שֶׁנֶּאֱמַר (ויקרא טז טז) \"וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאֹת בְּנֵי יִשְׂרָאֵל\":"],"Mishneh Torah, Offerings for Unintentional Transgressions 9":["עַל חָמֵשׁ עֲבֵרוֹת מֵבִיא קָרְבַּן אָשָׁם וְהוּא הַנִּקְרָא אָשָׁם וַדַּאי שֶׁהֲרֵי אֵינוֹ בָּא מִשּׁוּם סָפֵק. וְאֵלּוּ הֵן. עַל שִׁפְחָה חֲרוּפָה וְעַל הַגֵּזֶל וְעַל הַמְּעִילָה וְעַל טֻמְאַת נָזִיר וְעַל הַצָּרַעַת כְּשֶׁיִּטְהַר מִמֶּנָּה. עַל שִׁפְחָה חֲרוּפָה כֵּיצַד. הַבָּא עַל שִׁפְחָה חֲרוּפָה בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה מֵבִיא אָשָׁם. וְהוּא שֶׁתִּהְיֶה גְּדוֹלָה וּמְזִידָה וּבִרְצוֹנָהּ וְתִהְיֶה בְּעוּלָה כְּדַרְכָּהּ וּבִגְמַר בִּיאָה כְּדֵי שֶׁתִּלְקֶה שֶׁנֶּאֱמַר (ויקרא יט כ) \"בִּקֹּרֶת תִּהְיֶה\" (ויקרא יט כא) \"וְהֵבִיא אֶת אֲשָׁמוֹ\" הִיא לוֹקָה וְהוּא מֵבִיא קָרְבָּן:","וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבִּזְמַן שֶׁהִיא חַיֶּבֶת מַלְקוֹת הוּא חַיָּב בְּקָרְבָּן וּבִזְמַן שֶׁהִיא פְּטוּרָה מִן הַמַּלְקוֹת הוּא פָּטוּר מִן הַקָּרְבָּן:","בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל שִׁפְחָה חֲרוּפָה. הִיא לוֹקָה וְהוּא מֵבִיא קָרְבָּן. וְיֵרָאֶה לִי שֶׁאֵינוֹ מֵבִיא עַד שֶׁיַּגְדִּיל וְיִהְיֶה בֶּן דַּעַת:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת בִּיאוֹת אֲסוּרוֹת מַה הִיא הַשִּׁפְחָה הַחֲרוּפָה הָאֲמוּרָה בַּתּוֹרָה. וְשֶׁאֵינָן חַיָּבִין עַד שֶׁיִּבְעל כְּדַרְכָּהּ וְיִגְמֹר. לְפִיכָךְ אִם אָמְרוּ לוֹ שְׁנַיִם בָּעַלְתָּ שִׁפְחָה חֲרוּפָה וְהוּא אוֹמֵר לֹא בָּעַלְתִּי נֶאֱמָן וְאֵינוֹ מֵבִיא קָרְבָּן עַל פִּיהֶן. שֶׁהֲרֵי הוּא יוֹדֵעַ אִם גָּמַר בִּיאָתוֹ אוֹ לֹא גָּמַר וְזֶה שֶׁאָמַר לֹא בָּעַלְתִּי כְּלוֹמַר לֹא גָּמַרְתִּי:","הַבָּא עַל הַשִּׁפְחָה בִּיאוֹת הַרְבֵּה אֵינוֹ חַיָּב אֶלָּא אָשָׁם אֶחָד. כֵּיצַד. הַבָּא עַל הַשִּׁפְחָה בִּיאוֹת הַרְבֵּה בְּזָדוֹן אוֹ שֶׁבָּא עָלֶיהָ בִּשְׁגָגָה וְנוֹדַע לוֹ וְחָזַר וּבָא עָלֶיהָ בִּשְׁגָגָה וְנוֹדַע לוֹ. אֲפִלּוּ מֵאָה פְּעָמִים בְּמֵאָה הַעֲלָמוֹת. מַקְרִיב אָשָׁם אֶחָד וּמִתְכַּפֵּר לוֹ עַל הַכּל עַל הַזְּדוֹנוֹת שֶׁבָּהּ וְעַל הַשְּׁגָגוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשִׁפְחָה אַחַת. אֲבָל הַבָּא עַל שְׁפָחוֹת הַרְבֵּה אֲפִלּוּ בְּהֶעְלֵם אַחַת חַיָּב אָשָׁם עַל כָּל שִׁפְחָה וְשִׁפְחָה:","בָּעַל שִׁפְחָה וְהִפְרִישׁ אֲשָׁמוֹ וְחָזַר וּבְעָלָהּ אַחַר שֶׁהִפְרִישׁ אֲשָׁמוֹ חַיָּב עַל כָּל אַחַת וְאַחַת שֶׁהַהַפְרָשָׁה מְחַלֶּקֶת וְנִמְצָא כְּמִי שֶׁהִקְרִיב וְאַחַר כָּךְ בָּעַל. וְכֵן אִם בָּעַל חָמֵשׁ בְּעִילוֹת בְּהֶעְלֵם אַחַת בְּשִׁפְחָה אַחַת וְנוֹדַע לוֹ עַל אַחַת מֵהֶן וְהִפְרִישׁ אֲשָׁמוֹ וְאַחַר כָּךְ נוֹדַע עַל הַשְּׁנִיָּה מַפְרִישׁ אָשָׁם אַחֵר אַף עַל פִּי שֶׁבְּהֶעְלֵם אַחַת הָיוּ כֻּלָּן הוֹאִיל וְלֹא נוֹדַע לוֹ אֶלָּא אַחַר שֶׁהִפְרִישׁ נִמְצָא כְּבוֹעֵל אַחַר שֶׁהִפְרִישׁ. שֶׁדִּין הַשּׁוֹגֵג וְהַמֵּזִיד בְּשִׁפְחָה אֶחָד הוּא:","עַל הַגֵּזֶל כֵּיצַד. כָּל מִי שֶׁיֵּשׁ בְּיָדוֹ מִשְּׁוֵה פְּרוּטָה וָמַעְלָה מִמָּמוֹן יִשְׂרָאֵל. בֵּין שֶׁגְּזָלוֹ בֵּין שֶׁגְּנָבוֹ בֵּין שֶׁהִפְקִידוּ אֶצְלוֹ אוֹ הִלְוָהוּ אוֹ מִשּׁוּם שֻׁתָּפוּת אוֹ מִשְּׁאָר דְּרָכִים. וְכָפַר בּוֹ וְנִשְׁבַּע לַשֶּׁקֶר בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה הֲרֵי זֶה מֵבִיא אָשָׁם עַל חֶטְאוֹ. וְזֶהוּ הַנִּקְרָא אֲשַׁם גְּזֵלוֹת. וּמְפֹרָשׁ בַּתּוֹרָה שֶׁאֵין מִתְכַּפֵּר לוֹ בְּאָשָׁם זֶה עַד שֶׁיָּשִׁיב הַמָּמוֹן שֶׁבְּיָדוֹ לִבְעָלָיו. אֲבָל הַחֹמֶשׁ אֵינוֹ מְעַכֵּב הַכַּפָּרָה. כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת שְׁבוּעוֹת אֵימָתַי יִהְיֶה חַיָּב בִּשְׁבוּעָה זוֹ שֶׁמַּקְרִיב עָלֶיהָ אָשָׁם זֶה וְאֵימָתַי יִהְיֶה פָּטוּר מִמֶּנָּה. וְעַל אֵי זוֹ דֶּרֶךְ יִתְחַיֵּב אֲשָׁמוֹת רַבּוֹת כְּמִנְיַן חִיּוּב הַשְּׁבוּעוֹת. וְעַל אֵי זוֹ דֶּרֶךְ לֹא יִהְיֶה חַיָּב אֶלָּא אָשָׁם אֶחָד:","עַל הַמְּעִילָה כֵּיצַד. כָּל הַנֶּהֱנֶה מִשְּׁוֵה פְּרוּטָה מִן הַהֶקְדֵּשׁ בִּשְׁגָגָה. מַחְזִיר מַה שֶּׁנֶּהֱנָה וְיוֹסִיף חֹמֶשׁ וְיַקְרִיב אָשָׁם וְיִתְכַּפֵּר לוֹ. וּכְבָר בֵּאַרְנוּ בְּהִלְכוֹת מְעִילָה שֶׁהַקָּרְבָּן וְהַקֶּרֶן מְעַכְּבִין הַכַּפָּרָה וְאֵין הַחֹמֶשׁ מְעַכֵּב:","הָאוֹכֵל מִדָּבָר שֶׁמּוֹעֲלִין בּוֹ בַּחֲמִשָּׁה תַּמְחוּיִין בְּהֶעְלֵם אַחַת. אַף עַל פִּי שֶׁהוּא מִזֶּבַח אֶחָד אִם יֵשׁ בְּכָל אֲכִילָה וַאֲכִילָה שְׁוֵה פְּרוּטָה חַיָּב אָשָׁם עַל כָּל אֶחָד וְאֶחָד. שֶׁהַתַּמְחוּיִין מְחַלְּקִין בִּמְעִילָה וַהֲרֵי הֵן כְּמִינִין הַרְבֵּה אַף עַל פִּי שֶׁאֵין מֻחְלָקִין בְּחִיּוּב הַכְּרֵתוֹת. חֻמְרָא יְתֵרָה יֵשׁ בִּמְעִילָה שֶׁהֲרֵי עָשָׂה בָּהּ הַמְהַנֶּה כְּנֶהֱנֶה וּמִצְטָרֶפֶת לִזְמַן מְרֻבֶּה. וְשָׁלִיחַ שֶׁעָשָׂה שְׁלִיחוּתוֹ חַיָּב הַמְשַׁלֵּחַ מַה שֶּׁאֵין דְּבָרִים אֵלּוּ בִּשְׁאָר הָאִסּוּרִין:","כָּל הַמְחֻיָּב אָשָׁם וַדַּאי צָרִיךְ שֶׁיִּוָּדַע לוֹ חֶטְאוֹ תְּחִלָּה וְאַחַר כָּךְ יַקְרִיב אֲשָׁמוֹ אֲבָל אִם הִקְרִיבוֹ קֹדֶם שֶׁיִּוָּדַע לוֹ וְנוֹדַע לוֹ אַחַר שֶׁהִקְרִיב אֵינוֹ עוֹלֶה לוֹ. וְכָל חֵטְא שֶׁחַיָּבִין עָלָיו אָשָׁם וַדַּאי אֶחָד הַמֶּלֶךְ וְאֶחָד כֹּהֵן מָשׁוּחַ אוֹ שְׁאָר עַם הָאָרֶץ שָׁוִין בּוֹ:","כָּל חֵטְא שֶׁחַיָּבִין עָלָיו אָשָׁם וַדַּאי אִם נִסְתַּפֵּק לוֹ אִם עֲשָׂאָהוּ אוֹ לֹא עֲשָׂאָהוּ פָּטוּר מִכְּלוּם. לְפִיכָךְ הַבָּא עַל יָדוֹ סְפֵק מְעִילָה אֵינוֹ חַיָּב כְּלוּם כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מְעִילָה:","הָיְתָה לְפָנָיו חֲתִיכָה שֶׁל חֻלִּין וַחֲתִיכָה שֶׁל הֶקְדֵּשׁ. אָכַל אַחַת מֵהֶן וְאֵין יָדוּעַ אֵי זוֹ הִיא פָּטוּר. חָזַר וְאָכַל אֶת הַשְּׁנִיָּה מֵבִיא אָשָׁם עַל מְעִילָתוֹ. אָכַל אַחֵר אֶת הַשְּׁנִיָּה שְׁנֵיהֶן פְּטוּרִין:","חֲתִיכָה שֶׁל חֵלֶב וַחֲתִיכָה שֶׁל הֶקְדֵּשׁ. אָכַל אַחַת מֵהֶן מֵבִיא אָשָׁם תָּלוּי מִשּׁוּם חֵלֶב. אָכַל אֶת הַשְּׁנִיָּה מֵבִיא חַטָּאת עַל הַחֵלֶב וְאָשָׁם וַדַּאי שֶׁל מְעִילָה עַל הַהֶקְדֵּשׁ. בָּא אַחֵר וְאָכַל אֶת הַשְּׁנִיָּה אַף הַשֵּׁנִי מֵבִיא אָשָׁם תָּלוּי. חֲתִיכָה שֶׁל חֵלֶב וַחֲתִיכָה שֶׁל חֵלֶב הֶקְדֵּשׁ. אָכַל אַחַת מֵהֶן מֵבִיא חַטָּאת. אָכַל אֶת הַשְּׁנִיָּה אַחַר שֶׁנּוֹדַע לוֹ עַל הָרִאשׁוֹנָה מֵבִיא שְׁתֵּי חַטָּאוֹת וְאָשָׁם וַדַּאי עַל מְעִילָתוֹ. בָּא אַחֵר וְאָכַל אֶת הַשְּׁנִיָּה זֶה מֵבִיא חַטָּאת וְזֶה מֵבִיא חַטָּאת בִּלְבַד. כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת מֵאֵיזֶה טַעַם נוֹסָף אִסּוּר הֶקְדֵּשׁ עַל אִסּוּר חֵלֶב. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ הָאִסּוּרִין:"],"Mishneh Torah, Other Sources of Defilement 12":["אַחַת עֶשְׂרֵה מַעֲלוֹת עָשׂוּ חֲכָמִים לַקֹּדֶשׁ עַל הַתְּרוּמָה וְאֵלּוּ הֵן. יֵשׁ לְאָדָם לְהַטְבִּיל כֵּלִים בְּתוֹךְ כֵּלִים לִתְרוּמָה אֲבָל לֹא לְקֹדֶשׁ. גְּזֵרָה שֶׁמָּא יִהְיֶה פִּי הַכְּלִי צַר וְלֹא יִהְיֶה בּוֹ כִּשְׁפוֹפֶרֶת הַנּוֹד וְנִמְצְאוּ הַכֵּלִים שֶׁבְּתוֹכוֹ כְּאִלּוּ טָבְלוּ בְּמַיִם שֶׁבַּכְּלִי לֹא בַּמִּקְוֶה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַכְּלִי הַגָּדוֹל שֶׁיֵּשׁ בְּתוֹכוֹ הַכֵּלִים הַטְּמֵאִין טָהוֹר. אֲבָל אִם הָיָה טָמֵא מִתּוֹךְ שֶׁעָלְתָה לוֹ טְבִילָה עָלְתָה טְבִילָה לַכֵּלִים שֶׁבְּתוֹכוֹ אֲפִלּוּ לְהִשְׁתַּמֵּשׁ בָּהֶן בַּקֹּדֶשׁ:","כְּלִי שֶׁנִּטְמְאוּ אֲחוֹרָיו בְּמַשְׁקִין לֹא נִטְמָא תּוֹכוֹ וְלֹא בֵּית אֶצְבַּע שֶׁבָּעֳבִי שְׂפָתוֹ. וְהַמַּשְׁקִין שֶׁבְּתוֹכוֹ אוֹ שֶׁבְּבֵית צְבִיעָתוֹ טְהוֹרִין. וְשׁוֹתֶה בּוֹ וְאֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יִגְּעוּ מַשְׁקִין שֶׁבְּפִיו בַּאֲחוֹרֵי הַכְּלִי וְיַחְזְרוּ וִיטַמְּאוּ תּוֹכוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים לִתְרוּמָה. אֲבָל לְקֹדֶשׁ נִטְמְאוּ אֲחוֹרָיו נִטְמָא כֻּלּוֹ:","הַנּוֹשֵׂא אֶת הַמִּדְרָס מֻתָּר לוֹ לִשָּׂא עִמּוֹ תְּרוּמָה כְּאֶחָד וְהוֹאִיל וְאֵין הַנּוֹשֵׂא נוֹגֵעַ בַּתְּרוּמָה וְלֹא תְּרוּמָה נוֹגַעַת בְּמִדְרָס הֲרֵי הִיא טְהוֹרָה אֲבָל לֹא הַקֹּדֶשׁ אַף עַל פִּי שֶׁלֹּא נָגַע בּוֹ. מַעֲשֵׂה הָיָה בְּאֶחָד שֶׁנָּשָׂא חָבִית שֶׁל קֹדֶשׁ טְמֵאָה בְּמִדְרָס שֶׁנָּשָׂא עִמָּהּ בְּאוֹתָהּ שָׁעָה גָּזְרוּ שֶׁהַנּוֹשֵׂא אֶת הַמִּדְרָס לֹא יִשָּׂא אֶת הַקֹּדֶשׁ. וְלֹא גָּזְרוּ אֶלָּא בְּמִדְרָס עִם הַקֹּדֶשׁ כְּמַעֲשֶׂה שֶׁהָיָה. וְאִם עָבַר וְנָשָׂא הוֹאִיל וְלֹא נָגַע בְּקֹדֶשׁ הֲרֵי הַקֹּדֶשׁ טָהוֹר:","בִּגְדֵי אוֹכְלֵי תְּרוּמָה אַף עַל פִּי שֶׁהֵן טְהוֹרִין וְנִזְהָרִין מִן הַטֻּמְאוֹת הֲרֵי בִּגְדֵיהֶן מִדְרָס לְקֹדֶשׁ:","כְּלִי שֶׁהוּא מְפֻצָּל וְלוּחוֹתָיו וְקוֹרוֹתָיו מְקֻשָּׁרוֹת כְּגוֹן מִטָּה וְכַיּוֹצֵא בָּהּ. אִם נִטְמָא וְצָרִיךְ לְהַטְבִּילוֹ לִתְרוּמָה יֵשׁ לוֹ לְהַטְבִּילוֹ כֻּלּוֹ כְּאֶחָד כְּשֶׁהוּא מְקֻשָּׁר. אֲבָל לְקֹדֶשׁ מַתִּיר וּמְנַגֵּב שֶׁמָּא יֵשׁ שָׁם דָּבָר הַחוֹצֵץ וּמַטְבִּיל וְאַחַר כָּךְ קוֹשֵׁר:","כֵּלִים הַנִּגְמָרִין בְּטָהֳרָה אֲפִלּוּ הָיָה הָעוֹשֶׂה אוֹתָן תַּלְמִיד חָכָם וְנִזְהָר בָּהֶן הֲרֵי אֵלּוּ צְרִיכִין טְבִילָה לְקֹדֶשׁ וְאֵינָן צְרִיכִין הַעֲרֵב שֶׁמֶשׁ. אֲבָל לִתְרוּמָה מִשְׁתַּמֵּשׁ בָּהֶן בְּלֹא טְבִילָה שֶׁהֲרֵי נַעֲשׂוּ בְּטָהֳרָה. וּמִפְּנֵי מָה הִצְרִיכוּם טְבִילָה לְקֹדֶשׁ גְּזֵרָה מִשּׁוּם רֹק עַם הָאָרֶץ שֶׁיִּגַּע בָּהֶן בִּשְׁעַת מְלָאכָה וַעֲדַיִן הוּא לַח:","אַחַר שֶׁנִּגְמַר הַכְּלִי מְצָרֵף מַה שֶּׁבְּתוֹכוֹ לְקֹדֶשׁ אֲבָל לֹא לִתְרוּמָה. כֵּיצַד. כְּלִי שֶׁהוּא מָלֵא פֵּרוֹת פְּרוּדִין זֶה מִזֶּה כְּגוֹן צִמּוּקִין וּגְרוֹגָרוֹת וְנָגְעָה טֻמְאָה בְּאֶחָד מֵהֶן. נִטְמָא כָּל מַה שֶּׁבַּכְּלִי לְקֹדֶשׁ אֲבָל לֹא לִתְרוּמָה. וְכָל הַמַּעֲלוֹת שֶׁל דִּבְרֵיהֶם הֵם. וְרֶמֶז יֵשׁ לְמַעֲלָה זוֹ בַּתּוֹרָה (במדבר ז יד) \"כַּף אַחַת עֲשָׂרָה זָהָב מְלֵאָה קְטֹרֶת\" אָמְרוּ חֲכָמִים כָּל מַה שֶּׁבַּכַּף הֲרֵי הוּא כְּגוּף אֶחָד. אֲפִלּוּ שֶׁאֵין לוֹ תּוֹךְ מְצָרֵף מַה שֶּׁעָלָיו לְקֹדֶשׁ. כְּגוֹן שֶׁהָיוּ צְבוּרִין עַל גַּבֵּי הַלּוּחַ אוֹ עַל גַּבֵּי הָעוֹר אַף עַל פִּי שֶׁאֵין הַפֵּרוֹת נוֹגְעִין זֶה בָּזֶה:","הָיוּ שְׁנֵי הַצִּבּוּרִין בְּתוֹךְ הַכְּלִי וְדָבָר אַחַר בֵּינֵיהֶן וְנִטְמָא אֶחָד מִשְּׁנֵיהֶן. אִם הָיָה הַדָּבָר שֶׁבֵּינֵיהֶן צָרִיךְ לַכְּלִי הַכְּלִי מְצָרְפָן וְנִטְמָא הַכּל. וְאִם אֵינוֹ צָרִיךְ לַכְּלִי לֹא נִטְמָא אֶלָּא זֶה שֶׁנָּגְעָה בּוֹ הַטֻּמְאָה בִּלְבַד:","הָיוּ שְׁנֵי צִבּוּרִין בִּכְלִי וְהַצִּבּוּר הָאֶחָד מְחֻבָּר לַמַּיִם שֶׁאֲחוֹרֵי הַכְּלִי וְנָגַע טָמֵא בַּצִּבּוּר הַשֵּׁנִי נִטְמְאוּ שְׁנֵיהֶן בְּצֵרוּף הַכְּלִי וְנִטְמְאוּ הַמַּיִם שֶׁאֲחוֹרֵי הַכְּלִי מֵחֲמַת זֶה הָאֹכֶל הַמְחֻבָּר לָהֶן אַף עַל פִּי שֶׁהֵן אֲחוֹרֵי הַכְּלִי. נָגַע הַטָּמֵא בְּמַיִם שֶׁאֲחוֹרֵי הַכְּלִי נִטְמָא הָאֹכֶל הַמְחֻבָּר לָהֶן. וְהַדָּבָר סָפֵק אִם נִטְמָא הָאֹכֶל הַשֵּׁנִי בְּצֵרוּף הַכְּלִי אוֹ לֹא נִטְמָא מֵחֲמַת הַצֵּרוּף:","אֹכֶל קדֶשׁ שֶׁנִּטְמָא וְהִנִּיחוֹ בִּכְלִי וּבְתוֹךְ הַכְּלִי אֹכֶל קֹדֶשׁ אַחֵר טָהוֹר וְאֵין נוֹגְעִין זֶה בָּזֶה. הַטָּהוֹר בְּטָהֳרָתוֹ וְהַטָּמֵא בְּטֻמְאָתוֹ. בָּא טְבוּל יוֹם וְנָגַע בָּאֹכֶל הַטָּמֵא יֵשׁ בְּדָבָר זֶה סָפֵק אִם נִפְסַל הַטָּהוֹר מֵחֲמַת מַגַּע טְבוּל יוֹם מִפְּנֵי צֵרוּף הַכְּלִי אוֹ לֹא נִפְסַל. שֶׁלֹּא נָגַע טְבוּל יוֹם אֶלָּא בָּאֹכֶל שֶׁשָּׂבַע מִן הַטֻּמְאָה וְלֹא הוֹסִיף לוֹ כְּלוּם:","הָרְבִיעִי בְּקֹדֶשׁ פָּסוּל אֲבָל בִּתְרוּמָה טָהוֹר. וְכֵן שְׁלִישִׁי בִּתְרוּמָה אִם נָגַע בְּמַשְׁקֵה קֹדֶשׁ הֲרֵי זֶה נִטְמָא כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַשְּׁלִישִׁי שֶׁבִּתְרוּמָה אוֹ שֶׁבְּקֹדֶשׁ אִם נָגַע בְּמַשְׁקֵה תְּרוּמָה לֹא פְּסָלוֹ:","מִי שֶׁנִּטְמֵאת יָדוֹ אַחַת וְנָגַע בָּהּ בְּיָדוֹ שְׁנִיָּה אוֹ בְּיַד חֲבֵרוֹ פָּסַל אֶת הַשְּׁנִיָּה וַהֲרֵי הִיא כִּשְׁלִישִׁי. וְאִם הָיְתָה יָדוֹ בְּלוּלָה בַּמַּשְׁקֶה אַף עַל פִּי שֶׁלֹּא נָגַע נִטְמֵאת חֲבֶרְתָּהּ וְצָרִיךְ לְהַטְבִּיל אֶת שְׁתֵּיהֶן וְאַחַר כָּךְ יִגַּע בְּקֹדֶשׁ. אֲבָל בִּתְרוּמָה אִם נִטְמֵאת יָדוֹ הָאַחַת לֹא נִטְמֵאת חֲבֶרְתָּהּ. וַאֲפִלּוּ נָגַע בָּהּ כְּשֶׁהִיא נְגוּבָה. וְאֵין צָרִיךְ לְהַטְבִּיל יָדוֹ שֶׁנִּטְמֵאת אֶלָּא נוֹטְלָהּ וְנוֹגֵעַ בִּתְרוּמָה:","אֳכָלִין נְגוּבִין שֶׁלֹּא הֻכְשְׁרוּ אוֹכְלִין אוֹתָם בְּיָדַיִם מְסֹאָבוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְרוּמָה. אֲבָל בְּקֹדֶשׁ חִבַּת הַקֹּדֶשׁ מַכְשַׁרְתָּן וְאָסוּר לְמִי שֶׁיָּדָיו טְמֵאוֹת לֶאֱכל קֹדֶשׁ שֶׁלֹּא הֻכְשַׁר. וַאֲפִלּוּ לֹא נָגַע בּוֹ אֶלָּא בְּכוּשׁ אוֹ שֶׁתָּחַב לוֹ חֲבֵרוֹ לְתוֹךְ פִּיו הֲרֵי זֶה אָסוּר. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם נָגְעָה טֻמְאָה בָּאֳכָלִין שֶׁל קֹדֶשׁ שֶׁלֹּא הֻכְשְׁרוּ שֶׁנִּטְמְאוּ מִפְּנֵי שֶׁחִבַּת הַקֹּדֶשׁ מַכְשַׁרְתָּן:","בַּמֶּה דְּבָרִים אֲמוּרִים לִפְסוֹל הָאוֹכֵל עַצְמוֹ וּלְאָסְרוֹ בַּאֲכִילָה. אֲבָל לִמְנוֹת בּוֹ רִאשׁוֹן וְשֵׁנִי הֲרֵי זֶה סָפֵק. כֵּיצַד. נָגַע אֹכֶל שֶׁנִּטְמָא בְּלֹא הֶכְשֵׁר בְּאֹכֶל שֵׁנִי שֶׁהֻכְשַׁר הֲרֵי זֶה הַשֵּׁנִי סָפֵק מִפְּנֵי שֶׁהָרִאשׁוֹן לֹא הֻכְשַׁר:","הָאוֹנֵן אַחַר שֶׁתָּם זְמַן אֲנִינוּתוֹ וּמְחֻסַּר כִּפּוּרִים אַחַר שֶׁהֵבִיא כַּפָּרָתוֹ צְרִיכִין טְבִילָה לַאֲכִילַת הַקֹּדֶשׁ אֲבָל לֹא לִתְרוּמָה שֶׁהָאוֹנֵן וּמְחֻסַּר כִּפּוּרִים מֻתָּרִין לֶאֱכל אֶת הַתְּרוּמָה. וּמִפְּנֵי מָה הִצְרִיכוּם טְבִילָה לַקֹּדֶשׁ שֶׁהֲרֵי עַד עַתָּה הָיוּ אֲסוּרִין לֶאֱכל אֶת הַקֹּדֶשׁ וְהִסִּיחוּ דַּעְתָּן וְשֶׁמָּא נִטְמְאוּ וְהֵם לֹא יָדְעוּ. וְלֹא עָשׂוּ מַעֲלָה זוֹ אֶלָּא לַאֲכִילָה אֲבָל לִנְגִיעָה נוֹגְעִים בְּקָדָשִׁים קֹדֶם טְבִילָה:","שֵׁשׁ מַעֲלוֹת הָרִאשׁוֹנוֹת עֲשָׂאוּם בֵּין לְקֹדֶשׁ בֵּין לְחֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַקֹּדֶשׁ. וַחֲמֵשׁ אַחֲרוֹנוֹת שֶׁהֵן מִן הַכְּלִי מְצָרֵף מַה שֶּׁבְּתוֹכוֹ וָהָלְאָה עֲשָׂאוּם בְּקֹדֶשׁ בִּלְבַד אֲבָל לֹא בְּחֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַקֹּדֶשׁ. אֶלָּא הֲרֵי הֵן בְּחָמֵשׁ אֵלּוּ כְּחֻלִּין לְפִיכָךְ חֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַקֹּדֶשׁ הָרִאשׁוֹן טָמֵא בָּהֶן וְהַשֵּׁנִי פָּסוּל. וְהַשְּׁלִישִׁי טָהוֹר בְּחֻלִּין כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Other Sources of Defilement 5":["שִׁכְבַת זֶרַע מֵאֲבוֹת הַטֻּמְאָה מְטַמְּאָה אָדָם וְכֵלִים בְּמַגָּע וּכְלֵי חֶרֶס בָּאֲוִיר וְאֵינָהּ מְטַמְּאָה בְּמַשָּׂא וְאֵין הַמִּתְטַמֵּא בָּהּ מְטַמֵּא בְּגָדִים בִּשְׁעַת מַגָּעוֹ. וְאֶחָד הַנּוֹגֵעַ בָּהּ וְאֶחָד הָרוֹאֶה אוֹתָהּ בִּבְשָׂרוֹ שְׁנֵיהֶן רִאשׁוֹן לְטֻמְאָה דִּין תּוֹרָה. וְכַמָּה שִׁעוּרָהּ לְנוֹגֵעַ בְּכַעֲדָשָׁה וְלָרוֹאֶה בְּכָל שֶׁהוּא. וְאֵין הָרוֹאֶה טָמֵא עַד שֶׁתֵּצֵא מִמֶּנּוּ וְיַחְתֹּם מִמֶּנּוּ פִּי אַמָּה שֶׁנֶּאֱמַר (ויקרא טו לב) (ויקרא כב ד) \"אֲשֶׁר תֵּצֵא מִמֶּנּוּ שִׁכְבַת זָרַע\". לְפִיכָךְ אֲפִלּוּ רָאָה בְּקֵיסָם הוֹאִיל וְהִגִּיעָה לְפִי אַמָּה נִטְמָא. וְאֶחָד הָרוֹאֶה מֵחֲמַת בְּשָׂרוֹ אוֹ הָרוֹאֶה בְּאֹנֶס טָמֵא:","אֵין שִׁכְבַת זֶרַע שֶׁל קָטָן מְטַמְּאָה עַד שֶׁיִּהְיֶה בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד:","שִׁכְבַת זֶרַע אֲדֻמָּה טְהוֹרָה עַד שֶׁתִּהְיֶה לְבָנָה וְנִמְשֶׁכֶת:","וְכָל שִׁכְבַת זֶרַע שֶׁאֵין גּוּפוֹ שֶׁל אָדָם מַרְגִּישׁ בָּהּ אֵינָהּ מְטַמְּאָה. לְפִיכָךְ אִם רָאָה בְּלֹא קִשּׁוּי וּבְלֹא תַּאֲוָה אֵינָהּ מְטַמְּאָה מִשּׁוּם שִׁכְבַת זֶרַע. נֶעֶקְרָה בְּהַרְגָּשָׁה אַף עַל פִּי שֶׁיָּצְתָה שֶׁלֹּא בְּהַרְגָּשָׁה טָמֵא:","הַמְהַרְהֵר בַּלַּיְלָה וְרָאָה שֶׁשִּׁמֵּשׁ מִטָּה בַּחֲלוֹם וְעָמַד וּמָצָא בְּשָׂרוֹ חַם אַף עַל פִּי שֶׁלֹּא מָצָא שִׁכְבַת זֶרַע הֲרֵי זֶה טָמֵא כֵּיוָן שֶׁהִרְגִּישׁ שֶׁשִּׁמֵּשׁ בַּחֲלוֹם כְּבָר רָאָה בְּהַרְגָּשָׁה וּלְפִיכָךְ מָצָא בְּשָׂרוֹ חַם וְהָיְתָה מְעַט וְנִתְקַנְּחָה בִּבְשָׂרוֹ אוֹ בְּכֵלָיו וּלְפִיכָךְ לֹא מָצָא לַחְלוּחִית. הִרְהֵר וְלֹא מָצָא בְּשָׂרוֹ חַם אוֹ שֶׁמָּצָא בְּשָׂרוֹ חַם וְלֹא הִרְהֵר טָהוֹר:","הַמֵּטִיל מַיִם וְרָאָה מַיִם חֲלוּקִין אוֹ עֲכוּרִים בַּתְּחִלָּה טָהוֹר. רָאָה אוֹתָם בָּאֶמְצַע אוֹ בַּסּוֹף הֲרֵי זֶה טָמֵא. הָיוּ הַמַּיִם שֶׁהֵטִיל כֻּלָּם מִתְּחִלָּה וְעַד סוֹף חֲלוּקִין אוֹ עֲכוּרִים הֲרֵי זֶה טָהוֹר. הָיוּ לְבָנִים וְנִמְשָׁכִין טָמֵא. וְהַמֵּטִיל טִפִּים עָבוֹת מִתּוֹךְ הָאַמָּה טָהוֹר:","בַּעַל קֶרִי שֶׁטָּבַל וְלֹא הֵטִיל מַיִם קֹדֶם שֶׁיִּטְבּל כְּשֶׁיָּטִיל מַיִם טָמֵא מִפְּנֵי צִחְצוּחֵי שִׁכְבַת זֶרַע שֶׁאֵינָן יוֹצְאִין אֶלָּא כְּשֶׁיָּטִיל מַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּחוֹלֶה אוֹ בְּזָקֵן. אֲבָל יֶלֶד בָּרִיא טָהוֹר מִפְּנֵי שֶׁהוּא יוֹרֶה שִׁכְבַת זֶרַע בְּחָזְקָה כְּחֵץ וְהִיא כֻּלָּהּ נִנְתֶּקֶת מִן הָאַמָּה. עַד כַּמָּה הוּא יֶלֶד כָּל זְמַן שֶׁהוּא עוֹמֵד עַל רַגְלוֹ אַחַת וְנוֹעֵל אוֹ חוֹלֵץ מִנְעָלוֹ וְאִם אֵינוֹ יָכוֹל לַעֲשׂוֹת כֵּן מִפְּנֵי חָלְיוֹ הֲרֵי זֶה חוֹלֶה לְעִנְיָן זֶה:","וְכָל אִשָּׁה שֶׁשִּׁמְּשָׁה מִטָּתָהּ וְיָרְדָה וְטָבְלָה קֹדֶם שֶׁתְּקַנֵּחַ עַצְמָהּ יָפֶה יָפֶה הֲרֵי הִיא בְּטֻמְאָתָהּ:","אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה שֶׁשִּׁמְּשׁוּ מִטָּתָן שְׁנֵיהֶן טְמֵאִים. וּשְׁנֵיהֶן רִאשׁוֹן לְטֻמְאָה דִּין תּוֹרָה. וְאֵין הָאִשָּׁה טְמֵאָה מִשּׁוּם נוֹגַעַת בְּשִׁכְבַת זֶרַע שֶׁנְּגִיעַת בֵּית הַסְּתָרִים אֵינָהּ נְגִיעָה. אֶלָּא הַמְשַׁמֶּשֶׁת הֲרֵי הִיא כְּרוֹאָה קֶרִי. וְהוּא שֶׁתִּהְיֶה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד שֶׁנֶּאֱמַר [(ויקרא טו יח) \"וְאִשָּׁה אֲשֶׁר יִשְׁכַּב אִישׁ אֹתָהּ\"]. הָיְתָה קְטַנָּה מִבַּת שָׁלֹשׁ שָׁנִים אֵינָהּ מִתְטַמְּאָה בִּשְׁכִיבָה. אֲבָל מִתְטַמְּאָה בִּנְגִיעַת שִׁכְבַת זֶרַע אִם נָגַע בִּבְשָׂרָהּ מִבַּחוּץ. [לְפִיכָךְ הַבּוֹעֵל גְּדוֹלָה שֶׁלֹּא כְּדַרְכָּהּ טְהוֹרָה]. שֶׁלֹּא טִמֵּא אוֹתָהּ הַכָּתוּב בְּטֻמְאַת בֵּית הַסְּתָרִים אֶלָּא כְּדַרְכָּהּ:","הַבּוֹעֵל אֶת הָאִשָּׁה וְלֹא הוֹצִיא שִׁכְבַת זֶרַע טָהוֹר אַף עַל פִּי שֶׁהֶעֱרָה. וְכֵן הָאִשָּׁה טְהוֹרָה עַד שֶׁיּוֹצִיא הָאִישׁ:","הָאִשָּׁה שֶׁפָּלְטָה שִׁכְבַת זֶרַע אִם פָּלְטָה אוֹתָהּ בְּתוֹךְ שָׁלֹשׁ עוֹנוֹת הֲרֵי הִיא טְמֵאָה כְּרוֹאָה קֶרִי. לְפִיכָךְ סוֹתֶרֶת יוֹם אֶחָד אִם הָיְתָה זָבָה כְּאִישׁ שֶׁרָאָה קֶרִי. וּמִטַּמְּאָהּ בְּכָל שֶׁהוּא אַף עַל פִּי שֶׁלֹּא יָצָאת לַחוּץ אֶלָּא נֶעֶקְרָה וְהִגִּיעָה לְבֵין הַשִּׁנַּיִם נִטְמְאָה שֶׁהֲרֵי שִׁכְבַת זֶרַע כְּדָמָהּ מַה דָּמָהּ מְטַמֵּא בִּפְנִים אַף שִׁכְבַת זֶרַע שֶׁתִּפְלֹט תְּטַמֵּא אוֹתָהּ בִּפְנִים:","שִׁכְבַת זֶרַע עַצְמָהּ שֶׁנִּפְלְטָה בְּתוֹךְ הַשָּׁלֹשׁ עוֹנוֹת מְטַמְּאָה אֲחֵרִים שֶׁנָּגְעוּ בָּהּ כְּדֶרֶךְ שֶׁטִּמְּאָה הָאִשָּׁה שֶׁפָּלְטָה אוֹתָהּ. וְאִם פָּלְטָה אַחַר שָׁלֹשׁ עוֹנוֹת הֲרֵי הָאִשָּׁה טְהוֹרָה וְכֵן שִׁכְבַת זֶרַע שֶׁנִּפְלְטָה טְהוֹרָה שֶׁכְּבָר נִפְסְדָה צוּרָתָהּ:","וְכַמָּה הִיא עוֹנָה. יוֹם אוֹ לַיְלָה. וְאֵין הָעוֹנָה שֶׁנִּבְעֲלָה בָּהּ מִן הַמִּנְיָן. כֵּיצַד. נִבְעֲלָה בְּלֵיל הַשַּׁבָּת שָׁלֹשׁ עוֹנוֹת שֶׁלָּהּ יוֹם הַשַּׁבָּת וְלֵיל אֶחָד בְּשַׁבָּת וְאֶחָד בְּשַׁבָּת אִם פָּלְטָה בְּתוֹךְ זְמַן זֶה טְמֵאָה. פָּלְטָה מִלֵּיל שֵׁנִי וָהָלְאָה טְהוֹרָה. וְהָאִישׁ שֶׁפֵּרְשָׁה מִמֶּנּוּ שִׁכְבַת זֶרַע אֲפִלּוּ לְאַחַר כַּמָּה עוֹנוֹת הֲרֵי זוֹ טְמֵאָה כָּל זְמַן שֶׁהִיא לֶחָה וְהַפּוֹרֵשׁ מִמֶּנּוּ טָמֵא:","שִׁכְבַת זֶרַע אֵינָהּ מְטַמְּאָה אֶלָּא כְּשֶׁהִיא לֶחָה. יָבְשָׁה כְּחֶרֶס טְהוֹרָה. וְאִם יְכוֹלָה לִשְׁרוֹת מֵעֵת לְעֵת בְּפוֹשְׁרִין וְלַחֲזֹר לִכְמוֹת שֶׁהָיְתָה הֲרֵי זוֹ טְמֵאָה:","כְּבָר בֵּאַרְנוּ בְּפֶרֶק זֶה שֶׁהָרוֹאֶה קֶרִי וְהָאִשָּׁה שֶׁשָּׁכַב אִישׁ אוֹתָהּ שִׁכְבַת זֶרַע וְהַנּוֹגֵעַ בְּשִׁכְבַת זֶרַע טְמֵאִים מִן הַתּוֹרָה. וְכֵן הָאִשָּׁה שֶׁפָּלְטָה בְּתוֹךְ שָׁלֹשׁ עוֹנוֹת הֲרֵי הִיא טְמֵאָה מִן הַתּוֹרָה כְּרוֹאָה קֶרִי. אֲבָל שְׁאָר הָאֲמוּרִין בְּפֶרֶק זֶה שֶׁהֵן טְמֵאִים כְּגוֹן מְהַרְהֵר וּמֵטִיל מַיִם אֵינָן טְמֵאִין אֶלָּא מִדִּבְרֵיהֶם וְלֹא גָּזְרוּ עֲלֵיהֶם טֻמְאָה אֶלָּא לִתְרוּמָה אֲבָל לְחֻלִּין טְהוֹרִין:","נָכְרִית שֶׁפָּלְטָה שִׁכְבַת זֶרַע שֶׁל יִשְׂרָאֵל בְּתוֹךְ הַשָּׁלֹשׁ עוֹנוֹת. וְכֵן הַבְּהֵמָה שֶׁפָּלְטָה שִׁכְבַת זֶרַע שֶׁל יִשְׂרָאֵל בְּתוֹךְ זְמַן זֶה הֲרֵי אוֹתָהּ הַנִּפְלֶטֶת טְמֵאָה. פְּלָטַתּוּ לְאַחַר זְמַן זֶה הֲרֵי הִיא סָפֵק נִסְרְחָה אוֹ עֲדַיִן לֹא נִסְרְחָה:","כְּבָר בֵּאַרְנוּ בְּהִלְכוֹת מְטַמְּאֵי מִשְׁכָּב וּמוֹשָׁב שֶׁשִּׁכְבַת זַרְעוֹ שֶׁל עַכּוּ\"ם טָהוֹר מִכְּלוּם לְפִיכָךְ בַּת יִשְׂרָאֵל שֶׁפָּלְטָה שִׁכְבַת זֶרַע שֶׁל עַכּוּ\"ם אֲפִלּוּ בְּתוֹךְ שָׁלֹשׁ עוֹנוֹת טְהוֹרָה:","עַכּוּ\"ם שֶׁהִרְגִּישׁ וְנִתְגַּיֵּר וְיָרַד וְטָבַל וְיָצָא מִמֶּנּוּ שִׁכְבַת זֶרַע שֶׁהִרְגִּישׁ בָּהּ אַחַר שֶׁטָּבַל הֲרֵי זֶה סְפֵק טָמֵא:","גְּדוֹלָה שֶׁשָּׁכַב אוֹתָהּ קָטָן פָּחוֹת מִבֶּן תֵּשַׁע [אוֹ עַכּוּ\"ם אוֹ בְּהֵמָה] הֲרֵי זוֹ טְהוֹרָה שֶׁנֶּאֱמַר [(ויקרא טו יח) \"וְאִשָּׁה אֲשֶׁר יִשְׁכַּב אִישׁ אֹתָהּ\"] עַד שֶׁיִּהְיֶה הַשּׁוֹכֵב אִישׁ וּמִיִּשְׂרָאֵל כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Overview of Mishneh Torah Contents 3":["ספר זמנים","הלכותיו עשר, וזה הוא סידורן: הלכות שבת, הלכות עירובין, הלכות שביתת עשור, הלכות שביתת יום טוב, הלכות חמץ ומצה, הלכות שופר וסוכה ולולב, הלכות שקלים, הלכות קידוש החודש, הלכות תענייות, הלכות מגילה וחנוכה.","הלכות שבת. יש בכללן חמש מצוות – שתי מצוות עשה, ושלוש מצוות לא תעשה; וזה הוא פרטן: (א) לשבות בשביעי; (ב) שלא לעשות בו מלאכה; (ג) שלא לענוש בשבת; (ד) שלא לצאת חוץ לגבול בשבת; (ה) לקדש היום בזכירה.","הלכות עירובין. מצות עשה אחת, והיא מדברי סופרים ואינה מן המניין.","הלכות שביתת עשור. יש בכללן ארבע מצוות – שתי מצוות עשה, ושתי מצוות לא תעשה; וזה הוא פרטן: (א) לשבות בו ממלאכה; (ב) שלא לעשות בו מלאכה; (ג) להתענות בו; (ד) שלא לאכול ולשתות בו.","הלכות שביתת יום טוב. יש בכללן שתים עשרה מצוות – שש מצוות עשה, ושש מצוות לא תעשה; וזה הוא פרטן: (א) לשבות בראשון של פסח; (ב) שלא לעשות בו מלאכה; (ג) לשבות בשביעי של פסח; (ד) שלא לעשות בו מלאכה; (ה) לשבות ביום חג השבועות; (ו) שלא לעשות בו מלאכה; (ז) לשבות בראש השנה; (ח) שלא לעשות בו מלאכה; (ט) לשבות בראשון של חג הסוכות; (י) שלא לעשות בו מלאכה; (יא) לשבות בשמיני של חג; (יב) שלא לעשות בו מלאכה.","הלכות חמץ ומצה. יש בכללן שמונה מצוות – שלוש מצוות עשה, וחמש מצוות לא תעשה; וזה הוא פרטן: (א) שלא לאכול חמץ ביום ארבעה עשר מחצות היום ולמעלה; (ב) להשבית שאור מארבעה עשר; (ג) שלא לאכול חמץ כל שבעה; (ד) שלא לאכול תערובת חמץ כל שבעה; (ה) שלא ייראה חמץ כל שבעה; (ו) שלא יימצא חמץ כל שבעה; (ז) לאכול מצה בלילי הפסח; (ח) לספר ביציאת מצריים באותו הלילה.","הלכות שופר וסוכה ולולב. יש בכללן שלוש מצוות עשה; וזה הוא פרטן: (א) לשמוע קול שופר באחד בתשרי; (ב) לישב בסוכה שבעת ימי החג; (ג) ליטול לולב במקדש כל שבעת ימי החג.","הלכות שקלים. מצות עשה אחת, והיא ליתן כל איש מחצית השקל בכל שנה.","הלכות קידוש החודש. מצות עשה אחת, והיא לחשוב ולידע ולקבוע באיזה יום הוא תחילת כל חודש וחודש מחודשי השנה.","הלכות תעניות. מצות עשה אחת, והיא להתענות ולזעוק לפני ה' בעת כל צרה גדולה שתבוא על הציבור.","הלכות מגילה וחנוכה. יש בכללן שתי מצוות עשה מדברי סופרים, ואינם מן המניין.","נמצאו כל המצוות של תורה הנכללות בספר זה, חמש ושלושים – תשע עשרה מהן מצוות עשה, ושש עשרה מצוות לא תעשה; ויש בו שלוש מצוות מדברי סופרים."],"Mishneh Torah, Ownerless Property and Gifts 3":["הַנּוֹתֵן מַתָּנָה לַחֲבֵרוֹ אֵין הַמְקַבֵּל זוֹכֶה בָּהּ אֶלָּא בְּאֶחָד מִן הַדְּרָכִים שֶׁהַקּוֹנֶה זוֹכֶה בָּהֶן בְּמִקָּחוֹ. אִם מִטַּלְטְלִין רוֹצֶה לִתֵּן לוֹ עַד שֶׁיַּגְבִּיהַּ אוֹ שֶׁיִּמְשֹׁךְ דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַגְבִּיהַּ אוֹ יִקְנֶה בְּאֶחָד מִשְּׁאָר הַדְּבָרִים שֶׁהַמִּטַּלְטְלִין נִקְנִין בָּהֶן. וְאִם קַרְקַע אוֹ עֲבָדִים נָתַן לוֹ עַד שֶׁיַּחְזִיק כְּדֶרֶךְ שֶׁמַּחְזִיק הַלּוֹקֵחַ אוֹ עַד שֶׁיַּגִּיעַ שְׁטַר מַתָּנָה לְיָדוֹ. אֲבָל בִּדְבָרִים לֹא זָכָה הַמְקַבֵּל אֶלָּא כָּל אֶחָד מֵהֶן עֲדַיִן יָכוֹל לַחְזֹר בּוֹ:","מָחַל לַחֲבֵרוֹ חוֹב שֶׁיֵּשׁ לוֹ עָלָיו. אוֹ נָתַן לוֹ הַפִּקָּדוֹן שֶׁהָיָה מֻפְקָד אֶצְלוֹ. הֲרֵי זוֹ מַתָּנָה הַנִּקְנֵית בִּדְבָרִים בִּלְבַד. וְאֵין צָרִיךְ דָּבָר אַחֵר כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן הָאוֹמֵר לַחֲבֵרוֹ מָנֶה שֶׁיֵּשׁ לִי בְּיָדְךָ תְּנֵהוּ לָזֶה קָנָה. וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ. בֵּין שֶׁנָּתַן הַמָּנֶה בְּחוֹב שֶׁיֵּשׁ לוֹ אֶצְלוֹ בֵּין שֶׁנְּתָנוֹ לוֹ מַתָּנָה בֵּין שֶׁהָיָה חוֹב אֶצְלוֹ בֵּין שֶׁהָיָה פִּקָּדוֹן אֶצְלוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","כְּשֵׁם שֶׁאֵין צְרִיכִים עֵדִים לְעִנְיַן מִקָּח וּמִמְכָּר אֶלָּא לְגַלּוֹת הַדָּבָר בִּלְבַד אִם הָיְתָה שָׁם טַעֲנָה וּכְפִירָה. כָּךְ בִּמְחִילוֹת וּמַתָּנוֹת אֵין צְרִיכִין עֵדִים אֶלָּא מִפְּנֵי הַמְשַׁקְּרִים:","כְּשֵׁם שֶׁמּוֹכֵר צָרִיךְ לְסַיֵּם הַמִּמְכָּר כְּמוֹ שֶׁבֵּאַרְנוּ כָּךְ הַנּוֹתֵן. כֵּיצַד. הַכּוֹתֵב לַחֲבֵרוֹ קַרְקַע מִנְּכָסַי נְתוּנָה לְךָ. אוֹ שֶׁכָּתַב לוֹ כָּל נְכָסַי קְנוּיִין לְךָ חוּץ מִמִּקְצָתָן. הוֹאִיל וְלֹא סִיֵּם הַדָּבָר שֶׁנָּתַן לוֹ וְאֵינוֹ יָדוּעַ לֹא קָנָה כְּלוּם. וְאֵינוֹ יָכוֹל לוֹמַר לוֹ תֵּן לִי פָּחוּת שֶׁבִּנְכָסֶיךָ עַד שֶׁסִּיֵּם לוֹ הַמָּקוֹם שֶׁנָּתַן לוֹ. אֲבָל אִם אָמַר לוֹ חֵלֶק כָּךְ וְכָךְ בְּשָׂדֶה פְּלוֹנִית הוֹאִיל וְסִיֵּם הַשָּׂדֶה אַף עַל פִּי שֶׁלֹּא סִיֵּם הַחֵלֶק נוֹטֵל אוֹתוֹ חֵלֶק מִן הַפָּחוּת שֶׁבְּאוֹתָהּ שָׂדֶה:","כָּל הַנּוֹתֵן מַתָּנָה עַל תְּנַאי. בֵּין שֶׁהִתְנָה נוֹתֵן בֵּין שֶׁהִתְנָה הַמְקַבֵּל. וְהֶחֱזִיק הַמְקַבֵּל וְזָכָה בָּהּ. אִם נִתְקַיֵּם הַתְּנַאי נִתְקַיֵּם הַמַּתָּנָה וְאִם לֹא נִתְקַיֵּם הַתְּנַאי בְּטֵלָה הַמַּתָּנָה וְיַחְזִיר פֵּרוֹת שֶׁאָכַל. וְהוּא שֶׁיִּהְיֶה הַתְּנַאי כָּרָאוּי:","כְּבָר בֵּאַרְנוּ שֶׁכָּל תְּנָאִין שֶׁיֵּשׁ בְּמַתָּנוֹת אוֹ בְּמִקָּח וּמִמְכָּר צָרִיךְ שֶׁיִּהְיֶה תְּנַאי כָּפוּל. וְהֵן קוֹדֵם לְלָאו. וּתְנַאי קוֹדֵם לְמַעֲשֶׂה. וְיִהְיֶה תְּנַאי שֶׁאֶפְשָׁר לְקַיְּמוֹ. וְאִם חָסֵר אֶחָד מֵאֵלּוּ הַתְּנָאִין בָּטֵל וּכְאִלּוּ אֵין שָׁם תְּנַאי:","וְכָל הָאוֹמֵר עַל מְנָת כְּאוֹמֵר מֵעַכְשָׁו דָּמִי וְאֵינוֹ צָרִיךְ לִכְפּל הַתְּנַאי. כָּךְ הוֹרוּ מִקְצָת הַגְּאוֹנִים וְלָזֶה דַּעְתִּי נוֹטָה. וְרַבּוֹתַי הוֹרוּ שֶׁאֵין צָרִיךְ לִכְפּל הַתְּנַאי וּלְהַקְדִּים הֵן לְלָאו אֶלָּא בְּגִטִּין וּבְקִדּוּשִׁין בִּלְבַד. וְאֵין לְדָבָר זֶה רְאָיָה:","הַנּוֹתֵן מַתָּנָה עַל מְנָת לְהַחְזִיר הֲרֵי זוֹ מַתָּנָה. בֵּין שֶׁהִתְנָה לְהַחְזִיר מִיָּד בֵּין שֶׁהִתְנָה לְהַחְזִירָהּ לִזְמַן קָצוּב. אוֹ כָּל יְמֵי חַיָּיו שֶׁל אֶחָד מֵהֶם. אוֹ כָּל יְמֵי חַיָּיו שֶׁל פְּלוֹנִי. הֲרֵי זוֹ מַתָּנָה בֵּין בְּמִטַּלְטְלִין בֵּין בְּקַרְקַע. וְאוֹכֵל פֵּרוֹת כָּל זְמַן הַמַּתָּנָה:","הָאוֹמֵר לַחֲבֵרוֹ שׁוֹר זֶה אֲנִי נוֹתֵן לְךָ בְּמַתָּנָה עַל מְנָת שֶׁתַּחְזִירֵהוּ. הִקְדִּישׁוֹ וְהֶחֱזִירוֹ הֲרֵי זֶה מֻקְדָּשׁ וּמֻחְזָר. אָמַר לוֹ עַל מְנָת שֶׁתַּחְזִירֵהוּ לִי אֵינוֹ קָדוֹשׁ. שֶׁלֹּא הִתְנָה עָלָיו אֶלָּא שֶׁיַּחְזִיר דָּבָר הָרָאוּי לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אָסוּר לְיִשְׂרָאֵל לִתֵּן לְעַכּוּ\"ם מַתְּנַת חִנָּם. אֲבָל נוֹתֵן הוּא לְגֵר תּוֹשָׁב. שֶׁנֶּאֱמַר (דברים יד כא) \"לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךָ תִּתְּנֶנָּה וַאֲכָלָהּ אוֹ מָכֹר לְנָכְרִי\", בִּמְכִירָה וְלֹא בְּמַתָּנָה. אֲבָל לְגֵר תּוֹשָׁב בֵּין בִּמְכִירָה בֵּין בִּנְתִינָה מִפְּנֵי שֶׁאַתָּה מְצֻוֶּה לְהַחְיוֹתוֹ. שֶׁנֶּאֱמַר (ויקרא כה לה) \"גֵּר וְתוֹשָׁב וָחַי עִמָּךְ\":","הַנּוֹתֵן מַתָּנָה לְעֶבֶד אוֹ לְאִשָּׁה קָנָה הַבַּעַל וְהָאָדוֹן. אֶלָּא שֶׁהָאָדוֹן קוֹנֶה לַגּוּף וְהַבַּעַל קוֹנֶה אוֹתָהּ לְפֵרוֹת:","נָתַן מַתָּנָה לְאִשָּׁה עַל מְנָת שֶׁאֵין לְבַעְלָהּ רְשׁוּת בָּהּ. וּלְעֶבֶד עַל מְנָת שֶׁאֵין לְרַבּוֹ רְשׁוּת בּוֹ. קָנָה הָאָדוֹן וְקָנָה הַבַּעַל. אֲבָל הַנּוֹתֵן מַתָּנָה לְאִשָּׁה אוֹ לְעֶבֶד וְהִתְנָה עִמָּהֶן הַנּוֹתֵן בְּגוּפָהּ שֶׁל מַתָּנָה שֶׁתִּהְיֶה לְכָךְ וְכָךְ. לֹא קָנָה הָאָדוֹן וְלֹא קָנָה הַבַּעַל:","כֵּיצַד. הַנּוֹתֵן מַתָּנָה לְאִשָּׁה וְאָמַר לָהּ הֲרֵי הַמָּעוֹת הָאֵלּוּ נְתוּנִים לְךָ בְּמַתָּנָה עַל מְנָת שֶׁתִּלְבְּשִׁי בָּהֶן אוֹ עַל מְנָת שֶׁתִּשְׁתִּי בָּהֶם וְתַעֲשִׂי מַה שֶּׁתִּרְצִי בְּלֹא רְשׁוּת הַבַּעַל. לֹא קָנָה הַבַּעַל. וְכֵן אִם אָמַר לְעֶבֶד עַל מְנָת שֶׁתֹּאכַל בָּהֶן וְתִשְׁתֶּה בָּהֶן. עַל מְנָת שֶׁתֵּצֵא בָּהֶם לְחֵרוּת. אוֹ עַל מְנָת שֶׁתַּעֲשֶׂה בָּהֶם כָּל מַה שֶּׁתִּרְצֶה בְּלֹא רְשׁוּת אָדוֹן שֶׁלְּךָ. לֹא קָנָה הָאָדוֹן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַנּוֹתֵן כָּל נְכָסָיו לְעַבְדּוֹ קָנָה עַצְמוֹ וְיָצָא בֶּן חוֹרִין וְקָנָה שְׁאָר הַנְּכָסִים. וְאִם שִׁיֵּר כָּל שֶׁהוּא אֲפִלּוּ מִטַּלְטְלִין לֹא קָנָה כְּלוּם שֶׁאֵין זֶה גֵּט חֵרוּת גָּמוּר שֶׁהֲרֵי שִׁיֵּר בּוֹ בְּגֵט וּמִתּוֹךְ שֶׁלֹּא נִשְׁתַּחְרֵר לֹא קָנָה כְּלוּם:"],"Mishneh Torah, Paschal Offering 5":["מִי שֶׁהָיָה טָמֵא בִּשְׁעַת שְׁחִיטַת הַפֶּסַח שֶׁאֵין שׁוֹחֲטִין עָלָיו. אוֹ שֶׁהָיָה בְּדֶרֶךְ רְחוֹקָה. אוֹ נֶאֱנַס בְּאֹנֶס אַחֵר. אוֹ שֶׁשָּׁגַג וְלֹא הִקְרִיב בָּרִאשׁוֹן. הֲרֵי זֶה מֵבִיא פֶּסַח בְּאַרְבָּעָה עָשָׂר לַחֹדֶשׁ הַשֵּׁנִי בֵּין הָעַרְבַּיִם. וּשְׁחִיטַת פֶּסַח זֶה מִצְוַת עֲשֵׂה בִּפְנֵי עַצְמוֹ וְדוֹחָה אֶת הַשַּׁבָּת שֶׁאֵין הַשֵּׁנִי תַּשְׁלוּמִין לָרִאשׁוֹן אֶלָּא רֶגֶל בִּפְנֵי עַצְמוֹ לְפִיכָךְ חַיָּבִין עָלָיו כָּרֵת:","כֵּיצַד. מִי שֶׁשָּׁגַג אוֹ נֶאֱנַס וְלֹא הִקְרִיב בָּרִאשׁוֹן אִם הֵזִיד וְלֹא הִקְרִיב בַּשֵּׁנִי חַיָּב כָּרֵת. וְאִם שָׁגַג אוֹ נֶאֱנַס אַף בַּשֵּׁנִי פָּטוּר. הֵזִיד וְלֹא הִקְרִיב בָּרִאשׁוֹן הֲרֵי זֶה מַקְרִיב בַּשֵּׁנִי. וְאִם לֹא הִקְרִיב בַּשֵּׁנִי אַף עַל פִּי שֶׁשָּׁגַג הֲרֵי זֶה חַיָּב כָּרֵת שֶׁהֲרֵי לֹא הִקְרִיב קָרְבַּן ה' בְּמוֹעֲדוֹ וְהָיָה מֵזִיד. אֲבָל מִי שֶׁהָיָה טָמֵא אוֹ בְּדֶרֶךְ רְחוֹקָה וְלֹא עָשָׂה אֶת הָרִאשׁוֹן. אַף עַל פִּי שֶׁהֵזִיד בַּשֵּׁנִי אֵינוֹ חַיָּב כָּרֵת. שֶׁכְּבָר נִפְטַר בְּפֶסַח רִאשׁוֹן מִן הַכָּרֵת:","וּמִי שֶׁהָיָה בְּדֶרֶךְ רְחוֹקָה וְשָׁחֲטוּ וְזָרְקוּ עָלָיו אֶת הַדָּם. אַף עַל פִּי שֶׁבָּא לָעֶרֶב לֹא הֻרְצָּה וְחַיָּב בְּפֶסַח שֵׁנִי:","טָמֵא שֶׁיָּכוֹל לִטַּהֵר בְּפֶסַח רִאשׁוֹן. שֶׁלֹּא טָבַל אֶלָּא יָשַׁב בְּטֻמְאָתוֹ עַד שֶׁעָבַר זְמַן הַקָּרְבָּן. וְכֵן עָרֵל שֶׁלֹּא מָל עַד שֶׁעָבַר זְמַן הַקָּרְבָּן. הֲרֵי זֶה מֵזִיד בָּרִאשׁוֹן. לְפִיכָךְ אִם לֹא עָשָׂה אֶת הַשֵּׁנִי אֲפִלּוּ בִּשְׁגָגָה חַיָּב כָּרֵת:","כְּשֵׁם שֶׁמִּילַת עַצְמוֹ מְעַכַּבְתּוֹ מִלַּעֲשׂוֹת פֶּסַח כָּךְ מִילַת בָּנָיו הַקְּטַנִּים וּמִילַת כָּל עֲבָדָיו בֵּין גְּדוֹלִים בֵּין קְטַנִּים מְעַכֶּבֶת אוֹתוֹ. שֶׁנֶּאֱמַר (שמות יב מח) \"הִמּוֹל לוֹ כָל זָכָר וְאָז יִקְרַב לַעֲשׂוֹתוֹ\". וְאִם שָׁחַט קֹדֶם שֶׁיָּמוּל אוֹתָם הַפֶּסַח פָּסוּל. וְכֵן טְבִילַת אַמְהוֹתָיו לְשֵׁם עַבְדוּת מְעַכַּבְתּוֹ. וְדָבָר זֶה מִפִּי הַקַּבָּלָה. שֶׁהַטְּבִילָה לִשְׁפָחוֹת כְּמִילָה לַעֲבָדִים:","הַקָּטָן אֵין מִילַת עֲבָדָיו וּטְבִילַת שִׁפְחוֹתָיו מְעַכַּבְתּוֹ מִלְּהִמָּנוֹת עַל הַפֶּסַח. שֶׁנֶּאֱמַר (שמות יב מד) \"וְכָל עֶבֶד אִישׁ\" לְהוֹצִיא אֶת הַקָּטָן:","גֵּר שֶׁנִּתְגַּיֵּר בֵּין פֶּסַח רִאשׁוֹן לְפֶסַח שֵׁנִי. וְכֵן קָטָן שֶׁהִגְדִּיל בֵּין שְׁנֵי פְּסָחִים. חַיָּבִין לַעֲשׂוֹת פֶּסַח שֵׁנִי. וְאִם שָׁחֲטוּ עָלָיו בָּרִאשׁוֹן פָּטוּר:","נָשִׁים שֶׁנִּדְּחוּ לַשֵּׁנִי. בֵּין מִפְּנֵי הָאֹנֶס וְהַשְּׁגָגָה. בֵּין מִפְּנֵי הַטֻּמְאָה וְדֶרֶךְ רְחוֹקָה. הֲרֵי פֶּסַח שֵׁנִי לָהֶם רְשׁוּת. רָצוּ שׁוֹחֲטִין רָצוּ אֵין שׁוֹחֲטִין. לְפִיכָךְ אֵין שׁוֹחֲטִין עֲלֵיהֶן בִּפְנֵי עַצְמָן בְּשַׁבָּת בְּפֶסַח שֵׁנִי. אֲבָל אִם הָיְתָה הָאִשָּׁה אַחַת מִבְּנֵי חֲבוּרָה מֻתָּר. וְאֵי זוֹ הִיא דֶּרֶךְ רְחוֹקָה. חֲמִשָּׁה עָשָׂר מִיל חוּץ לְחוֹמַת יְרוּשָׁלַיִם:","מִי שֶׁהָיָה בֵּינוֹ וּבֵין יְרוּשָׁלַיִם יוֹם אַרְבָּעָה עָשָׂר עִם עֲלִיַּת הַשָּׁמֶשׁ חֲמִשָּׁה עָשָׂר מִיל אוֹ יֶתֶר הֲרֵי זֶה דֶּרֶךְ רְחוֹקָה. הָיָה בֵּינוֹ וּבֵינָהּ פָּחוֹת מִזֶּה אֵינוֹ בְּדֶרֶךְ רְחוֹקָה מִפְּנֵי שֶׁהוּא יָכוֹל לְהַגִּיעַ לִירוּשָׁלַיִם אַחַר חֲצוֹת כְּשֶׁיְּהַלֵּךְ בְּרַגְלָיו בְּנַחַת. הָלַךְ וְלֹא הִגִּיעַ מִפְּנֵי שֶׁעִכְּבוּהוּ הַבְּהֵמוֹת בְּדָחֳקָם. אוֹ שֶׁהָיָה בִּירוּשָׁלַיִם וְהָיָה חוֹלֶה בְּרַגְלָיו וְלֹא הִגִּיעַ לָעֲזָרָה עַד שֶׁעָבַר זְמַן הַקָּרְבָּן. הֲרֵי זֶה אָנוּס וְאֵינוֹ בְּדֶרֶךְ רְחוֹקָה. מִי שֶׁהָיָה חָבוּשׁ חוּץ לְחוֹמַת יְרוּשָׁלַיִם וְהִבְטִיחוּהוּ לָצֵאת לָעֶרֶב. שׁוֹחֲטִין עָלָיו וּכְשֶׁיֵּצֵא לָעֶרֶב יֹאכַל. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה חָבוּשׁ בְּיַד יִשְׂרָאֵל. אֲבָל אִם הָיָה חָבוּשׁ בְּיַד עַכּוּ\"ם אֵין שׁוֹחֲטִין עָלָיו עַד שֶׁיֵּצֵא. וְאִם שָׁחֲטוּ עָלָיו וְיָצָא הֲרֵי זֶה אוֹכֵל. וְאִם לֹא יָצָא פָּטוּר מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי שֶׁהֲרֵי נִשְׁחַט עָלָיו. וְכֵן הָאוֹנֵן וְהַחוֹלֶה וְהַזָּקֵן שֶׁהֵם יְכוֹלִין לֶאֱכל שֶׁשָּׁחֲטוּ עֲלֵיהֶן וְאַחַר שֶׁנִּזְרַק הַדָּם נִטְמְאוּ בְּמֵת וַהֲרֵי אֵינָן יְכוֹלִין לֶאֱכל. הֲרֵי אֵלּוּ פְּטוּרִין מִלַּעֲשׂוֹת פֶּסַח שֵׁנִי:"],"Mishneh Torah, Plaintiff and Defendant 16":["רְאוּבֵן שֶׁמָּכַר לְשִׁמְעוֹן שָׂדֶה וְהָיָה לֵוִי מֵעֵדֵי הַשְּׁטָר וּבָא לֵוִי לְעַרְעֵר עַל הַשָּׂדֶה וְלִטְעֹן שֶׁרְאוּבֵן גָּזַל אוֹתָהּ מִמֶּנּוּ. אֵין שׁוֹמְעִין לוֹ וְאֵין מַשְׁגִּיחִין עַל רְאָיוֹת שֶׁיָּבִיא עַל אוֹתָהּ שָׂדֶה וַהֲרֵי אִבֵּד כָּל זְכוּתוֹ שֶׁאוֹמֵר לוֹ הֵיאַךְ תָּעִיד עַל הַמֶּכֶר וְתָבוֹא וּתְעַרְעֵר. וְכֵן אִם הֵעִיד לֵוִי בִּשְׁטָר שֶׁכָּתוּב בּוֹ הַשָּׂדֶה פְּלוֹנִי שֶׁל רְאוּבֵן מִצַּד מִזְרָח אוֹ מַעֲרָב הוֹאִיל וְעָשָׂה הַשָּׂדֶה סִימָן לְאַחֵר וְהֵעִיד בַּשְּׁטָר אִבֵּד אֶת זְכוּתוֹ וְאֵינוֹ יָכוֹל לַחְזֹר וּלְעַרְעֵר שֶׁאוֹמְרִים לוֹ הֵיאַךְ תָּעִיד בִּשְׁטָר זֶה שֶׁכָּתוּב בּוֹ הַשָּׂדֶה הַזֹּאת מִצַּד פְּלוֹנִי וְתַחְזֹר וּתְעַרְעֵר עָלֶיהָ:","טָעַן הָעֵד וְאָמַר תֶּלֶם אֶחָד הוּא שֶׁעָשִׂיתִי סִימָן וְלֹא כָּל הַשָּׂדֶה וְאוֹתוֹ הַתֶּלֶם הַסָּמוּךְ לַמֵּצַר בִּלְבַד הוּא שֶׁל רְאוּבֵן הֲרֵי זֶה טַעֲנָה הַנִּשְׁמַעַת וְיֵשׁ לוֹ לְעַרְעֵר עַל כָּל הַשָּׂדֶה חוּץ מֵאוֹתוֹ הַתֶּלֶם. וְאֵין כָּל הַדְּבָרִים אֲמוּרִים אֶלָּא בְּאֶחָד מֵעֵדֵי הַשְּׁטָר שֶׁבָּא לְעַרְעֵר. אֲבָל הַדַּיָּן שֶׁקִּיֵּם הַשְּׁטָר יֵשׁ לוֹ לְעַרְעֵר מִפְּנֵי שֶׁיָּכוֹל לִטְעֹן וְלוֹמַר לֹא יָדַעְתִּי מֶה הָיָה כָּתוּב בַּשְּׁטָר מִפְּנֵי שֶׁיֵּשׁ לַדַּיָּנִין לְקַיֵּם הַשְּׁטָר אַף עַל פִּי שֶׁלֹּא קְרָאוּהוּ. אֲבָל הָעֵדִים אֵין חוֹתְמִין עַל הַשְּׁטָר אֶלָּא אִם כֵּן קְרָאוּהוּ כֻּלּוֹ וִידַקְדֵּק בּוֹ:","בָּא שִׁמְעוֹן וְנִמְלַךְ בְּלֵוִי וְאָמַר לוֹ הֲרֵינִי קוֹנֶה שָׂדֶה פְּלוֹנִית מֵרְאוּבֵן וּבַעֲצָתְךָ אֶקְנֶה אוֹתָהּ. אָמַר לוֹ לֵוִי לֵךְ וּקְנֵה אוֹתָהּ טוֹבָה הִיא. יֵשׁ לוֹ לְלֵוִי לְעַרְעֵר עָלֶיהָ וְלֹא אִבֵּד זְכוּתוֹ שֶׁהֲרֵי לֹא עָשָׂה מַעֲשֶׂה וְיֵשׁ לוֹ לוֹמַר רְצוֹנִי הָיָה שֶׁתֵּצֵא מִתַּחַת יַד רְאוּבֵן שֶׁהוּא אַלָּם כְּדֵי שֶׁאֶתְבָּעֶנָּה בְּדִין וְאֶקַּח שָׂדִי:","רְאוּבֵן שֶׁעִרְעֵר עַל שִׁמְעוֹן וְשִׁמְעוֹן אָמַר אֵינִי יוֹדֵעַ מָה אַתָּה סָח אֶלָּא שָׂדֶה זוֹ מִלֵּוִי לְקַחְתִּיהָ וַהֲרֵי עֵדִים שֶׁאֲכַלְתִּיהָ שְׁנֵי חֲזָקָה. אָמַר לוֹ רְאוּבֵן וַהֲלֹא עֵדִים יֵשׁ לִי שֶׁבָּעֶרֶב בָּאתָ אֵלַי וְאָמַרְתָּ לִי מְכֹר לִי שָׂדֶה זוֹ אֵין זוֹ רְאָיָה. וְיֵשׁ לוֹ לְשִׁמְעוֹן לוֹמַר רָצִיתִי לִקְנוֹת מִמְּךָ כְּדֵי שֶׁלֹּא תְּעַרְעֵר וְלֹא תַּטְרִיחֵנִי בְּדִין אַף עַל פִּי שֶׁאֵינִי יוֹדֵעַ אִם הִיא שֶׁלְּךָ אוֹ אֵינָהּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם לֹא טָעַן שִׁמְעוֹן טַעֲנָה זוֹ אֵין טוֹעֲנִין לוֹ:","רְאוּבֵן שֶׁעִרְעֵר וְהֵבִיא עֵדִים שֶׁשָּׂדֶה זוֹ שֶׁלּוֹ וְשִׁמְעוֹן שֶׁבְּתוֹכָהּ טוֹעֵן אַתָּה מְכַרְתָּהּ לִי וַאֲכַלְתִּיהָ שְׁנֵי חֲזָקָה. וּרְאוּבֵן אָמַר בְּגֵזֶל אָכַלְתָּ. בֵּין שֶׁלֹּא הָיוּ עֵדִים שֶׁאָכַל כְּלָל בֵּין שֶׁהָיָה שָׁם עֵד אֶחָד שֶׁאֲכָלָהּ שָׁלֹשׁ שָׁנִים אֵינוֹ חַיָּב לְהַחְזִיר הַפֵּרוֹת שֶׁאָכַל שֶׁהֲרֵי הוּא אוֹמֵר שֶׁלִּי אָכַלְתִּי וְאֵין עָלָיו עֵדִים שֶׁמְּחַיְּבִין אוֹתוֹ בְּפֵרוֹת שֶׁהֲרֵי מֵעַצְמוֹ הוֹדָה. וְזֶה הָעֵד שֶׁהֵעִיד שֶׁאֲכָלָהּ שָׁלֹשׁ שָׁנִים לְיַפּוֹת כֹּחוֹ שֶׁל אוֹכֵל הוּא בָּא וְאִלּוּ הָיָה עִמּוֹ אַחֵר הָיְתָה הַשָּׂדֶה עוֹמֶדֶת בְּיָדוֹ. לְפִיכָךְ יִשָּׁבַע רְאוּבֵן הֶסֵּת שֶׁלֹּא מָכַר וְתַחְזֹר לוֹ הַשָּׂדֶה וְיִשָּׁבַע שִׁמְעוֹן הֶסֵּת שֶׁאֵינוֹ חַיָּב לוֹ כְּלוּם בַּפֵּרוֹת שֶׁאָכַל וְיִפָּטֵר:","הָיוּ שְׁנֵי עֵדִים מְעִידִים עַל שִׁמְעוֹן שֶׁאֲכָלָהּ פָּחוֹת מִשְּׁנֵי חֲזָקָה יַחְזִיר כָּל הַפֵּרוֹת שֶׁאָכַל וַאֲפִלּוּ הָיָה עֵד אֶחָד חַיָּב לְהַחְזִיר עַל פִּיו שֶׁהֲרֵי אֵינוֹ מַכְחִישׁ הָעֵד אֶלָּא אוֹמֵר אֱמֶת הֵעִיד וְאָכַלְתִּי שְׁתֵּי שָׁנִים וְשֶׁלִּי אָכַלְתִּי. נִמְצָא מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לְהִשָּׁבַע וּמְשַׁלֵּם:","כָּל הַמְחֻיָּב לְהַחְזִיר הַפֵּרוֹת אִם לֹא הָיוּ יְדוּעִין וְאֵין בֵּית דִּין יְכוֹלִין לְשַׁעֵר אוֹתָן כְּשַׁעַר הַבָּתִּים וְכַיּוֹצֵא בָּהֶן שֶׁהוּא יָדוּעַ. אֶלָּא הָיוּ פֵּרוֹת אִילָן אוֹ פֵּרוֹת שָׂדֶה שֶׁאֵינָן יְדוּעִין. הוֹאִיל וְאֵין כָּאן טַעֲנָה וַדָּאִית יְשַׁלֵּם מַה שֶּׁיּוֹדֶה בּוֹ שֶׁאֲכָלוֹ. וּמַחְרִימִין עַל מִי שֶׁאָכַל יוֹתֵר וְלֹא יְשַׁלֵּם:","כָּל הַמַּחֲזִיר קַרְקַע מִתַּחַת יָדוֹ אִם הִשְׂכִּירָהּ לַאֲחֵרִים כְּשֶׁהָיָה מַחֲזִיק בָּהּ וְהָיוּ הַשּׂוֹכְרִין קַיָּמִין מוֹצִיאִין מֵהֶן הַשָּׂכָר פַּעַם שְׁנִיָּה וְנוֹתְנִין לְבַעַל הַקַּרְקַע וְחוֹזְרִין וְתוֹבְעִין זֶה שֶׁהִשְׂכִּיר לָהֶם מָקוֹם שֶׁאֵינוֹ שֶׁלּוֹ:","אָסוּר לָאָדָם לִטְעֹן טַעֲנַת שֶׁקֶר כְּדֵי לְעַוֵּת הַדִּין אוֹ כְּדֵי לְעַכְּבוֹ. כֵּיצַד. הָיָה נוֹשֶׁה בַּחֲבֵרוֹ מָנֶה לֹא יִטְעָנֶנּוּ מָאתַיִם כְּדֵי שֶׁיּוֹדֶה בְּמָנֶה וְיִתְחַיֵּב שְׁבוּעָה. הָיָה נוֹשֶׁה מָנֶה וּטְעָנוֹ מָאתַיִם לֹא יֹאמַר אֶכְפֹּר הַכּל בְּבֵית דִּין וְאוֹדֶה לוֹ בְּמָנֶה בֵּינִי לְבֵינוֹ כְּדֵי שֶׁלֹּא אֶתְחַיֵּב לוֹ שְׁבוּעָה:","הָיוּ שְׁלֹשָׁה נוֹשִׁין מָנֶה בְּאֶחָד וְכָפַר בָּהֶן לֹא יִהְיֶה אֶחָד תּוֹבֵעַ וּשְׁנַיִם מְעִידִים וּכְשֶׁיּוֹצִיאוּ מִמֶּנּוּ יַחֲלֹקוּ. וְעַל דְּבָרִים אֵלּוּ וְכַיּוֹצֵא בָּהֶן הִזְהִיר הַכָּתוּב וְאָמַר מִדְּבַר שֶׁקֶר תִּרְחָק: סְלִיקוּ לְהוּ הִלְכוֹת טוֹעֵן וְנִטְעָן בְּסַ\"ד"],"Mishneh Torah, Positive Mitzvot 101":["להיות המצורע טמא ומטמא."],"Mishneh Torah, Positive Mitzvot 112":["להיות המצורע ידוע לכל בדברים האמורים בו \"בְּגָדָיו יִהְיוּ פְרֻמִים וְרֹאשׁוֹ יִהְיֶה פָרֻעַ וְעַל שָׂפָם יַעְטֶה וְטָמֵא טָמֵא יִקְרָא\" (ויקרא יג, מה). וכן כל שאר הטמאים צריכין להודיע את עצמן."],"Mishneh Torah, Positive Mitzvot 123":["להניח עוללות בכרם."],"Mishneh Torah, Positive Mitzvot 134":["להשמיט קרקע, שנאמר: \"והשביעית תשמטנה ונטשתה\" (שמות כג,יא)."],"Mishneh Torah, Positive Mitzvot 145":["לדון בדיני חרמים, מהם לה' ומהם לכוהן, שנאמר: \"אך כל חרם אשר יחרים\" (ויקרא כז,כח)."],"Mishneh Torah, Positive Mitzvot 156":["לבער חמץ, שנאמר: \"ביום הראשון, תשביתו שאור מבתיכם\" (שמות יב,טו)."],"Mishneh Torah, Positive Mitzvot 167":["לשבות בשמיני של חג, שנאמר: \"וביום השמיני מקרא קודש\" (ראה ויקרא כג,לו)."],"Mishneh Torah, Positive Mitzvot 178":["להעיד בבית דין למי שיש לו עדות, שנאמר: \"והוא עד, או ראה או ידע\" (ויקרא ה,א)."],"Mishneh Torah, Positive Mitzvot 189":["לזכור מה שעשה לנו עמלק תדיר, שנאמר: \"זכור, את אשר עשה לך עמלק\" (דברים כה,יז)."],"Mishneh Torah, Positive Mitzvot 2":["לְיַחֲדוֹ, שֶׁנֶּאֱמָר: \"ה' אֱלֹהֵינוּ, ה' אֶחָד\" (דברים ו, ד)."],"Mishneh Torah, Positive Mitzvot 21":["לְיִרְאָה מִבַּיִת זֶה, שֶׁנֶּאֱמָר: \"וּמִקְדָּשִׁי תִּירָאוּ\" (ויקרא יט ל; כו, ב)."],"Mishneh Torah, Positive Mitzvot 220":["לדון במפתה בחמישים שקל עם שאר דינין, שנאמר: \"כי יפתה איש\" (שמות כב,טו)."],"Mishneh Torah, Positive Mitzvot 231":["לקבור הנהרג ביומו, שנאמר: \"כי קבור תקברנו ביום ההוא\" (דברים כא,כג)."],"Mishneh Torah, Positive Mitzvot 242":["לדון בדין שומר חינם, שנאמר: \"כי ייתן איש אל ריעהו כסף או כלים\" (שמות כב,ו)."],"Mishneh Torah, Positive Mitzvot 3":["לְאָהֳבוֹ, שֶׁנֶּאֱמָר: \"וְאָהַבְתָּ, אֵת ה' אֱלֹהֶיךָ\" (דברים ו ה, יא א)."],"Mishneh Torah, Positive Mitzvot 40":["להקריב כהן גדול מנחה בכל יום, שנאמר: \"זֶה קָרְבַּן אַהֲרֹן וּבָנָיו\" (ויקרא ו, יג)."],"Mishneh Torah, Positive Mitzvot 51":["להוסיף קרבן ביום שמיני עצרת, כי רגל בפני עצמו הוא, שנאמר: \"בַּיּוֹם הַשְּׁמִינִי\" (במדבר כט, לה)."],"Mishneh Torah, Positive Mitzvot 62":["למלוח כל קרבן, שנאמר: \"עַל כָּל קָרְבָּנְךָ תַּקְרִיב מֶלַח\" (ויקרא ב, יג)."],"Mishneh Torah, Positive Mitzvot 73":["להתוודות לפני ה' מכל חטא שיעשה האדם, בשעת הקרבן ושלא בשעת הקרבן, שנאמר: \"והתוודו, את חטאתם אשר עשו\" (במדבר ה,ז)."],"Mishneh Torah, Positive Mitzvot 84":["להקריב כל הקרבנות בבית הבחירה, שנאמר: \"ושם תעשה, כול אשר אנוכי מצווך\" (דברים יב,יד)."],"Mishneh Torah, Positive Mitzvot 95":["לדון בהפרת נדרים בכל הדינים האמורין בפרשה."],"Mishneh Torah, Prayer and the Priestly Blessing 2":["בִימֵי רַבָּן גַּמְלִיאֵל רַבּוּ הָאֶפִּיקוֹרוֹסִין בְּיִשְׂרָאֵל וְהָיוּ מְצֵרִים לְיִשְׂרָאֵל וּמְסִיתִין אוֹתָן לָשׁוּב מֵאַחֲרֵי הַשֵּׁם. וְכֵיוָן שֶׁרָאָה שֶׁזּוֹ גְּדוֹלָה מִכָּל צָרְכֵי בְּנֵי אָדָם עָמַד הוּא וּבֵית דִּינוֹ וְהִתְקִין בְּרָכָה אַחַת שֶׁתִּהְיֶה בָּהּ שְׁאֵלָה מִלִּפְנֵי הַשֵּׁם לְאַבֵּד הָאֶפִּיקוֹרוֹסִין וְקָבַע אוֹתָהּ בַּתְּפִלָּה כְּדֵי שֶׁתִּהְיֶה עֲרוּכָה בְּפִי הַכּל. נִמְצְאוּ כָּל הַבְּרָכוֹת שֶׁבַּתְּפִלָּה תְּשַׁע עֶשְׂרֵה בְּרָכוֹת:","בְּכָל תְּפִלָּה שֶׁבְּכָל יוֹם מִתְפַּלֵּל אָדָם תְּשַׁע עֶשְׂרֵה בְּרָכוֹת אֵלּוּ עַל הַסֵּדֶר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁמָּצָא דַּעְתּוֹ מְכֻוֶּנֶת וּלְשׁוֹנוֹ תְּמַהֵר לִקְרוֹת. אֲבָל אִם הָיָה טָרוּד וְדָחוּק אוֹ שֶׁקָּצְרָה לְשׁוֹנוֹ מֵהִתְפַּלֵּל יִתְפַּלֵּל שָׁלֹשׁ רִאשׁוֹנוֹת וּבְרָכָה אַחַת מֵעֵין כָּל הָאֶמְצָעִיּוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וְיֵצֵא יְדֵי חוֹבָתוֹ:","וְזוֹהִי הַבְּרָכָה שֶׁתִּקְּנוּ מֵעֵין כָּל הָאֶמְצָעִיּוֹת. הֲבִינֵנוּ יְיָ׳‎ אֱלֹהֵינוּ לָדַעַת אֶת דְּרָכֶיךָ וּמוֹל אֶת לְבָבֵנוּ לְיִרְאָתְךָ לְסוֹלֵחַ הֱיֵה לָנוּ לִהְיוֹת גְּאוּלִים רַחֲקֵנוּ מִמַּכְאוֹב וְדַשְׁנֵנוּ וְשַׁכְּנֵנוּ בִּנְאוֹת אַרְצְךָ וּנְפוֹצִים מֵאַרְבַּע תְּקַבֵּץ וְהַתּוֹעִים בְּדַעְתְּךָ יִשָּׁפְטוּ וְעַל הָרְשָׁעִים תָּנִיף יָדְךָ וְיִשְׂמְחוּ צַדִּיקִים בְּבִנְיַן עִירֶךָ וּבְתִקּוּן הֵיכָלֶךָ וּבִצְמִיחַת קֶרֶן לְדָוִד עַבְדֶּךָ וּבַעֲרִיכַת נֵר לְבֶן יִשַּׁי מְשִׁיחֶךָ טֶרֶם נִקְרָא אַתָּה תַּעֲנֶה כַּדָּבָר שֶׁנֶּאֱמַר (ישעיה סה כד) ״וְהָיָה טֶרֶם יִקְרָאוּ וַאֲנִי אֶעֱנֶה עוֹד הֵם מְדַבְּרִים וַאֲנִי אֶשְׁמָע״ כִּי אַתָּה הוּא עוֹנֶה בְּכָל עֵת פּוֹדֶה וּמַצִּיל מִכָּל צוּקָה בָּרוּךְ אַתָּה יְיָ׳‎ שׁוֹמֵעַ תְּפִלָּה:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּימוֹת הַחַמָּה. אֲבָל בִּימוֹת הַגְּשָׁמִים אֵינוֹ מִתְפַּלֵּל הֲבִינֵנוּ מִפְּנֵי שֶׁצָּרִיךְ לוֹמַר שְׁאֵלָה בְּבִרְכַּת הַשָּׁנִים. וְכֵן בְּמוֹצָאֵי שַׁבָּתוֹת וְיָמִים טוֹבִים אֵינוֹ מִתְפַּלֵּל הֲבִינֵנוּ מִפְּנֵי שֶׁצָּרִיךְ לוֹמַר הַבְדָּלָה בְּחוֹנֵן הַדַּעַת:","וּבְשַׁבָּתוֹת וּבְיָמִים טוֹבִים מִתְפַּלֵּל שֶׁבַע בְּרָכוֹת בְּכָל תְּפִלָּה וּתְפִלָּה מֵאַרְבַּע תְּפִלּוֹת שֶׁל אוֹתוֹ הַיּוֹם. שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וּבְרָכָה אֶמְצָעִית מֵעֵין אוֹתוֹ הַיּוֹם. בְּשַׁבָּתוֹת חוֹתְמִין בִּבְרָכָה אֶמְצָעִית מְקַדֵּשׁ הַשַּׁבָּת. וּבָרְגָלִים חוֹתֵם בָּהּ מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים. וְאִם הָיָה שַׁבָּת וְיוֹם טוֹב חוֹתְמִים בָּהּ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְהַזְּמַנִּים. בְּרֹאשׁ הַשָּׁנָה חוֹתְמִין בָּהּ מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן. וְאִם הָיָה שַׁבָּת חוֹתֵם בָּהּ מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְפִלַּת עַרְבִית וְשַׁחֲרִית וּמִנְחָה. אֲבָל תְּפִלַּת הַמּוּסָפִין שֶׁל רֹאשׁ הַשָּׁנָה מִתְפַּלֵּל תֵּשַׁע בְּרָכוֹת שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת שֶׁל כָּל יוֹם וְשָׁלֹשׁ אֶמְצָעִיּוֹת. רִאשׁוֹנָה מִן הָאֶמְצָעִיּוֹת עִנְיָנָהּ מַלְכֻיּוֹת. שְׁנִיָּה זִכְרוֹנוֹת. שְׁלִישִׁית שׁוֹפָרוֹת. וְחוֹתֵם בְּכָל אַחַת מֵהֶן מֵעִנְיָנָהּ:","בְּיוֹם הַכִּפּוּרִים מִתְפַּלֵּל בְּכָל תְּפִלָּה מֵחָמֵשׁ תְּפִלּוֹת שֶׁבַע בְּרָכוֹת. שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וְאֶמְצָעִיּוֹת מֵעֵין הַיּוֹם. וְחוֹתֵם בְּכָל אַחַת מֵהֶן מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַכִּפּוּרִים. וְאִם חָל לִהְיוֹת בְּשַׁבָּת חוֹתֵם בְּכָל תְּפִלָּה מֵהֶן מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְיוֹם הַכִּפּוּרִים:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּיוֹם צוֹם שֶׁל כָּל שָׁנָה וְשָׁנָה אֲבָל בְּיוֹם צוֹם שֶׁל שְׁנַת הַיּוֹבֵל מִתְפַּלֵּל תְּפִלַּת הַמּוּסָפִים תֵּשַׁע בְּרָכוֹת כְּמוֹ שֶׁהִתְפַּלֵּל בְּמוּסַף רֹאשׁ הַשָּׁנָה וְהֵם אוֹתָן הַבְּרָכוֹת עַצְמָן לֹא פָּחוֹת וְלֹא יוֹתֵר וְאֵין מִתְפַּלְּלִין אוֹתָן אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג:","בְּכָל תְּפִלָּה מֵהַתְּפִלּוֹת פּוֹתֵחַ קֹדֶם לִבְרָכָה רִאשׁוֹנָה (תהילים נא יז) ״יְיָ׳‎ שְׂפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ״. וּכְשֶׁהוּא חוֹתֵם בְּסוֹף הַתְּפִלָּה אוֹמֵר (תהילים יט טו) ״יִהְיוּ לְרָצוֹן אִמְרֵי פִי״ וְגוֹ׳‎ וְאַחַר כָּךְ צוֹעֵד לַאֲחוֹרָיו:","בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד מִתְפַּלֵּל עַרְבִית שַׁחֲרִית וּמִנְחָה תְּשַׁע עֶשְׂרֵה בְּרָכוֹת כִּשְׁאָר הַיָּמִים וְאוֹמֵר בָּעֲבוֹדָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ יַעֲלֶה וְיָבוֹא. בְּמוּסָף בְּחֻלּוֹ שֶׁל מוֹעֵד מִתְפַּלֵּל תְּפִלַּת הַמּוּסָף כְּמוֹ שֶׁמִּתְפַּלֵּל בְּיוֹם טוֹב. וּבְרָאשֵׁי חֳדָשִׁים מִתְפַּלֵּל שֶׁבַע בְּרָכוֹת שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וְאֶמְצָעִית מֵעֵין קָרְבַּן רֹאשׁ חֹדֶשׁ וְחוֹתֵם בָּהּ מְקַדֵּשׁ יִשְׂרָאֵל וְרָאשֵׁי חֳדָשִׁים:","שַׁבָּת שֶׁחָלָה בְּחֻלּוֹ שֶׁל מוֹעֵד וְכֵן רֹאשׁ חֹדֶשׁ שֶׁחָל לִהְיוֹת בְּשַׁבָּת מִתְפַּלֵּל עַרְבִית וְשַׁחֲרִית וּמִנְחָה שֶׁבַע בְּרָכוֹת כִּשְׁאָר הַשַּׁבָּתוֹת וְאוֹמֵר יַעֲלֶה וְיָבוֹא בָּעֲבוֹדָה. בְּמוּסָף מַתְחִיל בִּבְרָכָה אֶמְצָעִית בְּעִנְיַן שַׁבָּת וּמַשְׁלִים בְּעִנְיַן שַׁבָּת וְאוֹמֵר קְדֻשַּׁת הַיּוֹם בְּאֶמְצַע בְּרָכָה וְחוֹתֵם בָּהּ בְּרָאשֵׁי חֳדָשִׁים מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְרָאשֵׁי חֳדָשִׁים. וּבְחֻלּוֹ שֶׁל מוֹעֵד חוֹתֵם בָּהּ כְּמוֹ שֶׁהוּא חוֹתֵם בְּיוֹם טוֹב שֶׁחָל לִהְיוֹת בְּשַׁבָּת:","וְיוֹם טוֹב שֶׁחָל לִהְיוֹת בְּאֶחָד בְּשַׁבָּת מִתְפַּלֵּל בִּבְרָכָה רְבִיעִית בַּלַּיְלָה וַתּוֹדִיעֵנוּ מִשְׁפְּטֵי צִדְקֶךָ וַתְּלַמְּדֵנוּ לַעֲשׂוֹת חֻקֵּי רְצוֹנֶךָ וַתִּתֶּן לָנוּ יְיָ׳‎ אֱלֹהֵינוּ קְדֻשַּׁת שַׁבָּת וּכְבוֹד מוֹעֵד וַחֲגִיגַת הָרֶגֶל בֵּין קְדֻשַּׁת שַׁבָּת לִקְדֻשַּׁת יוֹם טוֹב הִבְדַּלְתָּ וְאֶת יוֹם הַשְּׁבִיעִי מִשֵּׁשֶׁת יְמֵי הַמַּעֲשֶׂה הִקְדַּשְׁתָּ (וְהִבְדַּלְתָּ וְהִקְדַּשְׁתָּ אֶת עַמְּךָ יִשְׂרָאֵל בִּקְדֻשָּׁתְךָ) וַתִּתֵּן לָנוּ ה׳‎ אֱלֹהֵינוּ מוֹעֲדִים לְשִׂמְחָה חַגִּים וּזְמַנִּים לְשָׂשוֹן וְכוּ׳‎. וּבְמוֹצָאֵי שַׁבָּת וּבְמוֹצָאֵי יוֹם טוֹב שֶׁל כָּל הַשָּׁנָה מַבְדִּיל בְּאַתָּה חוֹנֵן אַף עַל פִּי שֶׁהוּא מַבְדִּיל עַל הַכּוֹס:","בַּחֲנֻכָּה וּבְפוּרִים מוֹסִיפִין בְּהוֹדָאָה עַל הַנִּסִּים. שַׁבָּת שֶׁחָלָה לִהְיוֹת בַּחֲנֻכָּה מַזְכִּיר עַל הַנִּסִּים בְּמוּסָף כְּמוֹ שֶׁמַּזְכִּיר בִּשְׁאָר תְּפִלּוֹת:","בִּימֵי הַתַּעֲנִית אֲפִלּוּ יָחִיד שֶׁהִתְעַנָּה מוֹסִיף בְּשׁוֹמֵעַ תְּפִלָּה עֲנֵנוּ וְכוּ׳‎. וּשְׁלִיחַ צִבּוּר אוֹמְרָהּ בְּרָכָה בִּפְנֵי עַצְמָהּ בֵּין גּוֹאֵל לְרוֹפֵא וְחוֹתֵם בָּהּ הָעוֹנֶה בְּעֵת צָרָה (וּמוֹשִׁיעַ). וְנִמְצָא מִתְפַּלֵּל עֶשְׂרִים בְּרָכוֹת. בְּתִשְׁעָה בְּאָב מוֹסִיפִין בְּבוֹנֵה יְרוּשָׁלָיִם רַחֵם יְיָ׳‎ אֱלֹהֵינוּ עָלֵינוּ וְעַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ וְעַל הָעִיר הָאֲבֵלָה כוּ׳‎:","כָּל יְמוֹת הַגְּשָׁמִים אוֹמֵר בִּבְרָכָה שְׁנִיָּה מוֹרִיד הַגֶּשֶׁם וּבִימוֹת הַחַמָּה מוֹרִיד הַטָּל. מֵאֵימָתַי אוֹמֵר מוֹרִיד הַגֶּשֶׁם מִתְּפִלַּת הַמּוּסָפִין שֶׁל יוֹם טוֹב הָאַחֲרוֹן שֶׁל חַג עַד תְּפִלַּת שַׁחֲרִית שֶׁל יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח. וּמִתְּפִלַּת הַמּוּסָפִין שֶׁל יוֹם טוֹב הָרִאשׁוֹן שֶׁל פֶּסַח אוֹמֵר מוֹרִיד הַטָּל:","מִשִּׁבְעָה יָמִים בְּמַרְחֶשְׁוָן שׁוֹאֲלִין אֶת הַגְּשָׁמִים בְּבִרְכַּת שָׁנִים כָּל זְמַן שֶׁמַּזְכִּיר הַגֶּשֶׁם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֶרֶץ יִשְׂרָאֵל. אֲבָל בְּשִׁנְעָר וּבְסוּרְיָא וּבְמִצְרַיִם וּבַמְּקוֹמוֹת הַסְּמוּכוֹת לְאֵלּוּ וְהַדּוֹמִין לָהֶן שׁוֹאֲלִין אֶת הַגְּשָׁמִים בְּיוֹם שִׁשִּׁים אַחַר תְּקוּפַת תִּשְׁרֵי:","מְקוֹמוֹת שֶׁהֵן צְרִיכִין לִגְשָׁמִים בִּימוֹת הַחַמָּה כְּגוֹן אִיֵּי הַיָּם הָרְחוֹקִים שׁוֹאֲלִין אֶת הַגְּשָׁמִים בְּעֵת שֶׁהֵן צְרִיכִין לָהֶן בְּשׁוֹמֵעַ תְּפִלָּה. וּמְקוֹמוֹת שֶׁהֵן עוֹשִׂין יוֹם טוֹב שְׁנֵי יָמִים אוֹמֵר מוֹרִיד הַגֶּשֶׁם בִּתְפִלַּת מוּסָף שֶׁל יוֹם רִאשׁוֹן שֶׁל שְׁמִינִי עֲצֶרֶת וּמִתְפַּלֵּל וְהוֹלֵךְ כָּל יְמוֹת הַגְּשָׁמִים:","כָּל הַשָּׁנָה כֻּלָּהּ חוֹתֵם בִּבְרָכָה שְׁלִישִׁית הָאֵל הַקָּדוֹשׁ וּבְבִרְכַּת עַשְׁתֵּי עֶשְׂרֵה מֶלֶךְ אוֹהֵב צְדָקָה וּמִשְׁפָּט וּבַעֲשֶׂרֶת הַיָּמִים שֶׁמֵּרֹאשׁ הַשָּׁנָה עַד מוֹצָאֵי יוֹם הַכִּפּוּרִים חוֹתֵם בַּשְּׁלִישִׁית הַמֶּלֶךְ הַקָּדוֹשׁ וּבְעַשְׁתֵּי עֶשְׂרֵה הַמֶּלֶךְ הַמִּשְׁפָּט:","יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְהוֹסִיף בַּעֲשֶׂרֶת יָמִים אֵלּוּ בִּבְרָכָה רִאשׁוֹנָה זָכְרֵנוּ לְחַיִּים כוּ׳‎ וּבַשְּׁנִיָּה מִי כָמוֹךָ אַב הָרַחֲמִים וְכוּ׳‎ וּבְהוֹדָאָה זְכֹר רַחֲמֶיךָ וְכוּ׳‎ וּמוֹסִיפִין בִּבְרָכָה אַחֲרוֹנָה בְּסֵפֶר חַיִּים וְכוּ׳‎. וְכֵן יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לְהוֹסִיף בַּעֲשֶׂרֶת יָמִים אֵלּוּ בִּבְרָכָה שְׁלִישִׁית וּבְכֵן תֵּן פַּחְדְּךָ וּבְכֵן וְכוּ׳‎ אֲבָל בְּרֹאשׁ הַשָּׁנָה וּבְיוֹם הַכִּפּוּרִים מִנְהָג פָּשׁוּט הוּא לְהוֹסִיף בַּשְּׁלִישִׁית וּבְכֵן תֵּן פַּחְדְּךָ וְכוּ׳‎:"],"Mishneh Torah, Rebels 1":["בֵּית דִּין הַגָּדוֹל שֶׁבִּירוּשָׁלַיִם הֵם עִקַּר תּוֹרָה שֶׁבְּעַל פֶּה. וְהֵם עַמּוּדֵי הַהוֹרָאָה וּמֵהֶם חֹק וּמִשְׁפָּט יוֹצֵא לְכָל יִשְׂרָאֵל. וַעֲלֵיהֶן הִבְטִיחָה תּוֹרָה שֶׁנֶּאֱמַר (דברים יז יא) \"עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ\" זוֹ מִצְוַת עֲשֵׂה. וְכָל הַמַּאֲמִין בְּמשֶׁה רַבֵּנוּ וּבְתוֹרָתוֹ חַיָּב לִסְמֹךְ מַעֲשֵׂה הַדָּת עֲלֵיהֶן וְלִשָּׁעֵן עֲלֵיהֶן:","כָּל מִי שֶׁאֵינוֹ עוֹשֶׂה כְּהוֹרָאָתָן עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים יז יא) \"לֹא תָסוּר מִכָּל הַדָּבָר אֲשֶׁר יַגִּידוּ לְךָ יָמִין וּשְׂמֹאל\". וְאֵין לוֹקִין עַל לָאו זֶה מִפְּנֵי שֶׁנִּתָּן לְאַזְהָרַת מִיתַת בֵּית דִּין. שֶׁכָּל חָכָם שֶׁמּוֹרֶה עַל דִּבְרֵיהֶם מִיתָתוֹ בְּחֶנֶק שֶׁנֶּאֱמַר (דברים יז יב) \"וְהָאִישׁ אֲשֶׁר יַעֲשֶׂה בְזָדוֹן\" וְגוֹ'. אֶחָד דְּבָרִים שֶׁלָּמְדוּ אוֹתָן מִפִּי הַשְּׁמוּעָה וְהֵם תּוֹרָה שֶׁבְּעַל פֶּה. וְאֶחָד דְּבָרִים שֶׁלְּמַּדוּם מִפִּי דַּעְתָּם בְּאַחַת מִן הַמִּדּוֹת שֶׁהַתּוֹרָה נִדְרֶשֶׁת בָּהֶן וְנִרְאָה בְּעֵינֵיהֶם שֶׁדָּבָר זֶה כָּךְ הוּא. וְאֶחָד דְּבָרִים שֶׁעֲשָׂאוּם סְיָג לַתּוֹרָה וּלְפִי מַה שֶּׁהַשָּׁעָה צְרִיכָה וְהֵן הַגְּזֵרוֹת וְהַתַּקָּנוֹת וְהַמִּנְהָגוֹת. כָּל אֶחָד וְאֶחָד מֵאֵלּוּ הַשְּׁלֹשָׁה דְּבָרִים מִצְוַת עֲשֵׂה לִשְׁמֹעַ לָהֶן. וְהָעוֹבֵר עַל כָּל אֶחָד מֵהֶן עוֹבֵר בְּלֹא תַּעֲשֶׂה. הֲרֵי הוּא אוֹמֵר (דברים יז יא) \"עַל פִּי הַתּוֹרָה אֲשֶׁר יוֹרוּךָ\" אֵלּוּ הַתַּקָּנוֹת וְהַגְּזֵרוֹת וְהַמִּנְהָגוֹת שֶׁיּוֹרוּ בָּהֶם לָרַבִּים כְּדֵי לְחַזֵּק הַדָּת וּלְתַקֵּן הָעוֹלָם. וְעַל הַמִּשְׁפָּט אֲשֶׁר יֹאמְרוּ אֵלּוּ דְּבָרִים שֶׁיִּלְמְדוּ אוֹתָן מִן הַדִּין בְּאַחַת מִן הַמִּדּוֹת שֶׁהַתּוֹרָה נִדְרֶשֶׁת בָּהֶן. מִכָּל הַדָּבָר אֲשֶׁר יַגִּידוּ לְךָ זוֹ הַקַּבָּלָה שֶׁקִּבְּלוּ אִישׁ מִפִּי אִישׁ:","דִּבְרֵי קַבָּלָה אֵין בָּהֶן מַחְלֹקֶת לְעוֹלָם וְכָל דָּבָר שֶׁתִּמְצָא בּוֹ מַחְלֹקֶת בְּיָדוּעַ שֶׁאֵינוֹ קַבָּלָה מִמּשֶׁה רַבֵּנוּ. וּדְבָרִים שֶׁלְּמֵדִין מִן הַדִּין אִם הִסְכִּימוּ עֲלֵיהֶן בֵּית דִּין הַגָּדוֹל כֻּלָּן הֲרֵי הִסְכִּימוּ. וְאִם נֶחְלְקוּ בָּהֶן הוֹלְכִין אַחַר הָרֹב וּמוֹצִיאִין הַדִּין אַחַר הָרַבִּים. וְכֵן הַגְּזֵרוֹת וְהַתַּקָּנוֹת וְהַמִּנְהָגוֹת אִם רָאוּ מִקְצָתָן שֶׁרָאוּי לִגְזֹר גְּזֵרָה אוֹ לְתַקֵּן תַּקָּנָה אוֹ שֶׁיָּנִיחוּ הָעָם הַמִּנְהָג הַזֶּה וְרָאוּ מִקְצָתָן שֶׁאֵין רָאוּי לִגְזֹר גְּזֵרָה זוֹ וְלֹא לְתַקֵּן תַּקָּנָה זוֹ וְלֹא לְהָנִיחַ מִנְהָג זֶה נוֹשְׂאִין וְנוֹתְנִין אֵלּוּ כְּנֶגֶד אֵלּוּ וְהוֹלְכִין אַחַר רֻבָּן וּמוֹצִיאִין הַדָּבָר אַחַר הָרַבִּים:","כְּשֶׁהָיָה בֵּית דִּין הַגָּדוֹל קַיָּם לֹא הָיְתָה מַחְלֹקֶת בְּיִשְׂרָאֵל. אֶלָּא כָּל דִּין שֶׁנּוֹלַד בּוֹ סָפֵק לְאֶחָד מִיִּשְׂרָאֵל שׁוֹאֵל לְבֵית דִּין שֶׁבְּעִירוֹ. אִם יָדְעוּ אָמְרוּ לוֹ. אִם לָאו הֲרֵי הַשּׁוֹאֵל עִם אוֹתוֹ בֵּית דִּין אוֹ עִם שְׁלוּחָיו עוֹלִין לִירוּשָׁלַיִם וְשׁוֹאֲלִין לְבֵית דִּין שֶׁבְּהַר הַבַּיִת. אִם יָדְעוּ אָמְרוּ לוֹ. אִם לָאו הַכּל בָּאִין לְבֵית דִּין שֶׁעַל פֶּתַח הָעֲזָרָה. אִם יָדְעוּ אָמְרוּ לָהֶן וְאִם לָאו הַכּל בָּאִין לְלִשְׁכַּת הַגָּזִית לְבֵית דִּין הַגָּדוֹל וְשׁוֹאֲלִין. אִם הָיָה הַדָּבָר שֶׁנּוֹלַד בּוֹ הַסָּפֵק לַכּל יָדוּעַ אֵצֶל בֵּית דִּין הַגָּדוֹל בֵּין מִפִּי הַקַּבָּלָה בֵּין מִפִּי הַמִּדָּה שֶׁדָּנוּ בָּהּ אוֹמְרִים מִיָּד. אִם לֹא הָיָה הַדָּבָר בָּרוּר אֵצֶל בֵּית דִּין הַגָּדוֹל דָּנִין בּוֹ בִּשְׁעָתָן וְנוֹשְׂאִין וְנוֹתְנִין בַּדָּבָר עַד שֶׁיַּסְכִּימוּ כֻּלָּן. אוֹ יַעַמְדוּ לְמִנְיָן וְיֵלְכוּ אַחַר הָרֹב וְיֹאמְרוּ לְכָל הַשּׁוֹאֲלִים כָּךְ הֲלָכָה וְהוֹלְכִין לָהֶן. מִשֶּׁבָּטַל בֵּית דִּין הַגָּדוֹל רָבְתָה מַחְלֹקֶת בְּיִשְׂרָאֵל זֶה מְטַמֵּא וְנוֹתֵן טַעַם לִדְבָרָיו וְזֶה מְטַהֵר וְנוֹתֵן טַעַם לִדְבָרָיו זֶה אוֹסֵר וְזֶה מַתִּיר:","שְׁנֵי חֲכָמִים אוֹ שְׁנֵי בָּתֵּי דִּינִין שֶׁנֶּחְלְקוּ שֶׁלֹּא בִּזְמַן הַסַּנְהֶדְרִין אוֹ עַד שֶׁלֹּא הָיָה הַדָּבָר בָּרוּר לָהֶן. בֵּין בִּזְמַן אֶחָד בֵּין בָּזֶה אַחַר זֶה. אֶחָד מְטַהֵר וְאֶחָד מְטַמֵּא אֶחָד אוֹסֵר וְאֶחָד מַתִּיר. אִם אֵינְךָ יוֹדֵעַ לְהֵיכָן הַדִּין נוֹטֶה. בְּשֶׁל תּוֹרָה הַלֵּךְ אַחַר הַמַּחְמִיר בְּשֶׁל סוֹפְרִים הַלֵּךְ אַחַר הַמֵּקֵל:"],"Mishneh Torah, Red Heifer 14":["כְּלִי חֶרֶס שֶׁהָיָה בּוֹ אֵפר חַטָּאת וְנָגַע בּוֹ שֶׁרֶץ מִצִּדּוֹ טָהוֹר שֶׁאֵין כְּלִי חֶרֶס מִטַּמֵּא מִגַּבּוֹ אֲפִלּוּ לְגַבֵּי חַטָּאת. הִנִּיחַ הַכְּלִי עַל גַּבֵּי הַשֶּׁרֶץ אַף עַל פִּי שֶׁלֹּא נִטְמָא הַכְּלִי הֲרֵי הָאֵפֶר טָמֵא שֶׁנֶּאֱמַר (במדבר יט ט) \"וְהִנִּיחַ מִחוּץ לַמַּחֲנֶה בְּמָקוֹם טָהוֹר\" וְאֵין זֶה מָקוֹם טָהוֹר. וְלֹא עַל גַּבֵּי הַשֶּׁרֶץ בִּלְבַד אֶלָּא אֲפִלּוּ הִנִּיחוֹ עַל גַּבֵּי אֹכֶל שֵׁנִי וְכַיּוֹצֵא בּוֹ מִדְּבָרִים שֶׁטֻּמְאָתָן טֻמְאָה קַלָּה וְהֵם מִדִּבְרֵי סוֹפְרִים הֲרֵי נִטְמָא הָאֵפֶר שֶׁנֶּאֱמַר בְּמָקוֹם טָהוֹר שֶׁלֹּא יִהְיֶה עַל [גַּבֵּי] שׁוּם טֻמְאָה בָּעוֹלָם. וְכֵן כְּלִי חֶרֶס שֶׁהָיָה בּוֹ אֵפֶר חַטָּאת וְנָתוּן עַל אֲרֻבָּה שֶׁבַּבַּיִת טָמֵא. אִם הָיָה הַכְּלִי מְשֻׁלְשָׁל לַבַּיִת נִטְמָא הָאֵפֶר וְאַף עַל פִּי שֶּׁאֵין בָּאֲרֻבָּה פּוֹתֵחַ טֶפַח. וְאִם לֹא הָיָה מְשֻׁלְשָׁל אִם הָיָה בָּאֲרֻבָּה פּוֹתֵחַ טֶפַח טָמֵא:","הָיָה הַכְּלִי שֶׁל אֶבֶן. בֵּין שֶׁיֵּשׁ בָּהּ פּוֹתֵחַ טֶפַח בֵּין שֶׁאֵין בָּהּ הָאֵפֶר טָהוֹר:","וְכֵן כְּלִי שֶׁיֵּשׁ בּוֹ אֵפֶר אוֹ מַיִם מְקֻדָּשִׁים וּמֻקָּף צָמִיד פָּתִיל וְנָתוּן בְּאֹהֶל הַמֵּת. הֲרֵי הָאֵפֶר וְהַמַּיִם טְמֵאִים שֶׁאֵין אֵפֶר הַחַטָּאת נִצֶּלֶת בְּצָמִיד פָּתִיל שֶׁנֶּאֱמַר (במדבר יט ט) \"בְּמָקוֹם טָהוֹר\" וְאֵין זֶה מָקוֹם טָהוֹר:","וְכֵן אֳכָלִין וּמַשְׁקִין שֶׁל קֹדֶשׁ אֵינָן נִצָּלִין בְּצָמִיד פָּתִיל. אֲבָל מַיִם שֶׁאֵינָן מְקֻדָּשִׁין וּכְלִי רֵיקָן הַטָּהוֹר לְחַטָּאת נִצָּל בְּצָמִיד פָּתִיל. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ הַבְּעָלִים טְהוֹרִים. אֲבָל אִם נִטְמְאוּ הַבְּעָלִים נִפְסְלוּ הַמַּיִם בְּכָל מָקוֹם שֶׁהֵן. כֵּיצַד. הָיוּ מֵימָיו מֻקָּפִין צָמִיד פָּתִיל וְהוּא וְהֵם בְּאֹהֶל הַמֵּת שְׁנֵיהֶן טְמֵאִים. הָיָה הוּא מִבַּחוּץ וְהַמַּיִם שֶׁאֵינָן מְקֻדָּשִׁין מִבִּפְנִים שְׁנֵיהֶן טְהוֹרִין. הוּא בִּפְנִים וְהַמַּיִם בַּחוּץ כְּשֵׁם שֶׁהוּא טָמֵא כָּךְ מֵימָיו פְּסוּלִין:","הַטָּהוֹר לְחַטָּאת שֶׁהָיָה עוֹמֵד עַל גַּבֵּי הַתַּנּוּר וְכַיּוֹצֵא בּוֹ מִכֵּלִים שֶׁאֵינָם טְהוֹרִים לְחַטָּאת וּפָשַׁט יָדוֹ חוּץ לַתַּנּוּר וּכְלִי שֶׁיֵּשׁ בּוֹ מֵי חַטָּאת בְּיָדוֹ. וְכֵן קָנֶה הַמֻּטָּל עַל גַּבֵּי הַתַּנּוּר וּשְׁנֵי כֵּלִים שֶׁיֵּשׁ בָּהֶן מֵי חַטָּאת תְּלוּיִין בּוֹ אֶחָד מִכָּאן וְאַחַד מִכָּאן הֲרֵי אֵלּוּ טְמֵאִין לְפִי שֶׁאֵינָן בְּמָקוֹם הַטָּהוֹר לְחַטָּאת. וְהוֹאִיל וְהֵם נִשְׁעָנִין עַל הַתַּנּוּר הֲרֵי הֵן כְּאִלּוּ מֻנָּחִין עַל גַּבָּיו. אֲבָל אִם הָיָה עוֹמֵד עַל הַתַּנּוּר וּבְיָדוֹ כְּלִי רֵיקָן הַטָּהוֹר לְחַטָּאת אוֹ מַיִם שֶׁאֵינָן מְקֻדָּשִׁין הֲרֵי אֵלּוּ טְהוֹרִין כְּמוֹת שֶׁהָיוּ. הָיָה עוֹמֵד חוּץ לַתַּנּוּר וּפָשַׁט יָדוֹ לַחַלּוֹן וְנָטַל כְּלִי שֶׁיֵּשׁ בּוֹ חַטָּאת וְהֶעֱבִירוֹ עַל גַּבֵּי הַתַּנּוּר הֲרֵי זֶה טָהוֹר. וְכֵן הַזָּיָה שֶׁעָבְרָה עַל גַּבֵּי טֻמְאָה כְּגוֹן מִשְׁכָּב וּמוֹשָׁב וְכַיּוֹצֵא בָּהֶן הֲרֵי זוֹ טְהוֹרָה:","כְּלִי שֶׁיֵּשׁ בּוֹ מֵי חַטָּאת וּכְלִי שֶׁיֵּשׁ בּוֹ קֹדֶשׁ שֶׁנָּגְעוּ זֶה בָּזֶה הֲרֵי נִטְמָא כְּלִי שֶׁל חַטָּאת וְכָל שֶׁיֵּשׁ בּוֹ אֲבָל כְּלִי הַקֹּדֶשׁ טָהוֹר כְּשֶׁהָיָה. וְכֵן אִם נָגַע הַטָּהוֹר לַחַטָּאת בִּשְׁנֵיהֶן בִּשְׁתֵּי יָדָיו כְּשֶׁהֵן מֻנָּחִין עַל הָאָרֶץ הֲרֵי נִטְמָא שֶׁל חַטָּאת שֶׁהֲרֵי הַטָּהוֹר לְחַטָּאת נִטְמָא בִּנְגִיעַת הַכְּלִי שֶׁאֵינוֹ טָהוֹר לְחַטָּאת כְּמוֹ שֶׁבֵּאַרְנוּ וְחָזַר וְטִמֵּא אֶת מֵי חַטָּאת:","הִגְבִּיהַּ שְׁנֵי הַכֵּלִים בִּשְׁתֵּי יָדָיו שְׁנֵיהֶן טְמֵאִין זֶה שֶׁל חַטָּאת נִטְמָא מִפְּנֵי שֶׁנָּגַע בּוֹ אָדָם שֶׁנָּגַע בִּכְלִי שֶׁאֵינוֹ טָהוֹר לְחַטָּאת וְשֶׁל קֹדֶשׁ נִטְמָא מִפְּנֵי זֶה שֶׁהִגְבִּיהוֹ וְהוּא טָמֵא בִּנְשִׂיאַת מֵי נִדָּה שֶׁהֵן מְטַמְּאִין בְּמַשָּׂא מִפְּנֵי שֶׁנִּטְמְאוּ מֵחֲמַת הַכְּלִי שֶׁל קֹדֶשׁ. לְפִיכָךְ אִם הָיָה הַכְּלִי שֶׁל קֹדֶשׁ כָּרוּךְ בִּנְיָר וְהִגְבִּיהַּ בַּנְּיָר וְלֹא נָגַע בּוֹ וְהִגְבִּיהַּ הַחַטָּאת בְּיָדוֹ שְׁנִיָּה שְׁנֵיהֶן טְהוֹרִין שֶׁהֲרֵי לֹא נָגַע בַּכְּלִי וְלֹא נִטְמָא לְחַטָּאת. אֲבָל אִם הָיָה נוֹגֵעַ בִּכְלִי הַקֹּדֶשׁ בְּיָדוֹ אֲפִלּוּ הָיָה שֶׁל חַטָּאת בִּנְיָר שְׁנֵיהֶם טְמֵאִין:","הֵסִיט אֶת שְׁנֵי הַכֵּלִים בְּיָדוֹ וְלֹא נָגַע בָּהֶן שְׁנֵיהֶן טְהוֹרִין שֶׁאֵין הַכְּלִי שֶׁאֵינוֹ טָהוֹר לְחַטָּאת מְטַמֵּא אֶת הַטָּהוֹר לְחַטָּאת עַד שֶׁיָּגַע בּוֹ בְּיָדוֹ אֶלָּא אִם כֵּן הָיָה רָאוּי לְמִדְרָס כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּל סְפֵק הַטֻּמְאוֹת שֶׁהוּא טָהוֹר לְגַבֵּי תְּרוּמָה כְּמוֹ שֶׁיִּתְבָּאֵר הֲרֵי הוּא טָהוֹר לְחַטָּאת. וְכָל הַסְּפֵקוֹת שֶׁתּוֹלִין בָּהֶן אֶת הַתְּרוּמָה אִם נוֹלְדוּ בְּחַטָּאת הֲרֵי אֵלּוּ נִשְׁפָּכִין. וְאִם נַעֲשׂוּ טָהֳרוֹת עַל גַּבֵּי אוֹתָן כֵּלִים וְאָדָם שֶׁנּוֹלְדוּ לָהֶן סְפֵקוֹת אֵלּוּ שֶׁהַחַטָּאוֹת נִשְׁפָּכִין עֲלֵיהֶן הֲרֵי אוֹתָן הַטָּהֳרוֹת תְּלוּיוֹת. וְהָרְפָפוֹת אֵינָן כְּכֵלִים וַהֲרֵי הֵן טְהוֹרוֹת לִתְרוּמָה וּלְקֹדֶשׁ וּלְחַטָּאת:","דְּבֵלָה שֶׁל תְּרוּמָה שֶׁנָּפְלָה לְתוֹךְ מֵי חַטָּאת וּנְטָלָהּ וַאֲכָלָהּ אִם יֵשׁ בָּהּ כְּבֵיצָה הַמַּיִם טְמֵאִין. בֵּין שֶׁהָיְתָה הַדְּבֵלָה טְמֵאָה בֵּין שֶׁהָיְתָה טְהוֹרָה. שֶׁכָּל הָאֳכָלִין אֲפִלּוּ אֹכֶל קֹדֶשׁ אֵינוֹ טָהוֹר לְחַטָּאת. וְהָאוֹכְלָהּ חַיָּב מִיתָה מִפְּנֵי שֶׁאָכַל תְּרוּמָה טְמֵאָה. וְאִם אֵין בָּהּ כְּבֵיצָה הַמַּיִם בְּטָהֳרָתָן. שֶׁאֵין הָאֹכֶל מְטַמֵּא אֲחֵרִים עַד שֶׁיִּהְיֶה בּוֹ כְּבֵיצָה בֵּין לִתְרוּמָה בֵּין לְקֹדֶשׁ בֵּין לְחַטָּאת:"],"Mishneh Torah, Repentance 2":["אֵי זוֹ הִיא תְּשׁוּבָה גְּמוּרָה. זֶה שֶׁבָּא לְיָדוֹ דָּבָר שֶׁעָבַר בּוֹ וְאֶפְשָׁר בְּיָדוֹ לַעֲשׂוֹתוֹ וּפֵרַשׁ וְלֹא עָשָׂה מִפְּנֵי הַתְּשׁוּבָה. לֹא מִיִּרְאָה וְלֹא מִכִּשְׁלוֹן כֹּחַ. כֵּיצַד. הֲרֵי שֶׁבָּא עַל אִשָּׁה בַּעֲבֵרָה וּלְאַחַר זְמַן נִתְיַחֵד עִמָּהּ וְהוּא עוֹמֵד בְּאַהֲבָתוֹ בָּהּ וּבְכֹחַ גּוּפוֹ וּבַמְּדִינָה שֶׁעָבַר בָּהּ וּפָרַשׁ וְלֹא עָבַר זֶהוּ בַּעַל תְּשׁוּבָה גְּמוּרָה. הוּא שֶׁשְּׁלֹמֹה אָמַר (קהלת יב א) \"וּזְכֹר אֶת בּוֹרְאֶיךָ בִּימֵי בְּחוּרֹתֶיךָ\". וְאִם לֹא שָׁב אֶלָּא בִּימֵי זִקְנוּתוֹ וּבְעֵת שֶׁאִי אֶפְשָׁר לוֹ לַעֲשׂוֹת מַה שֶּׁהָיָה עוֹשֶׂה אַף עַל פִּי שֶׁאֵינָהּ תְּשׁוּבָה מְעֻלָּה מוֹעֶלֶת הִיא לוֹ וּבַעַל תְּשׁוּבָה הוּא. אֲפִלּוּ עָבַר כָּל יָמָיו וְעָשָׂה תְּשׁוּבָה בְּיוֹם מִיתָתוֹ וּמֵת בִּתְשׁוּבָתוֹ כָּל עֲוֹנוֹתָיו נִמְחָלִין שֶׁנֶּאֱמַר (קהלת יב ב) \"עַד אֲשֶׁר לֹא תֶחְשַׁךְ הַשֶּׁמֶשׁ וְהָאוֹר וְהַיָּרֵחַ וְהַכּוֹכָבִים וְשָׁבוּ הֶעָבִים אַחַר הַגֶּשֶׁם\" שֶׁהוּא יוֹם הַמִּיתָה. מִכְּלָל שֶׁאִם זָכַר בּוֹרְאוֹ וְשָׁב קֹדֶם שֶׁיָּמוּת נִסְלַח לוֹ:","וּמַה הִיא הַתְּשׁוּבָה. הוּא שֶׁיַּעֲזֹב הַחוֹטֵא חֶטְאוֹ וִיסִירוֹ מִמַּחֲשַׁבְתּוֹ וְיִגְמֹר בְּלִבּוֹ שֶׁלֹּא יַעֲשֵׂהוּ עוֹד שֶׁנֶּאֱמַר (ישעיה נה ז) \"יַעֲזֹב רָשָׁע דַּרְכּוֹ\" וְגוֹ'. וְכֵן יִתְנַחֵם עַל שֶׁעָבַר שֶׁנֶּאֱמַר (ירמיה לא יט) \"כִּי אַחֲרֵי שׁוּבִי נִחַמְתִּי\". וְיָעִיד עָלָיו יוֹדֵעַ תַּעֲלוּמוֹת שֶׁלֹּא יָשׁוּב לְזֶה הַחֵטְא לְעוֹלָם שֶׁנֶּאֱמַר (הושע יד ד) \"וְלֹא נֹאמַר עוֹד אֱלֹהֵינוּ לְמַעֲשֵׂה יָדֵינוּ\" וְגוֹ'. וְצָרִיךְ לְהִתְוַדּוֹת בִּשְׂפָתָיו וְלוֹמַר עִנְיָנוֹת אֵלּוּ שֶׁגָּמַר בְּלִבּוֹ:","כָּל הַמִּתְוַדֶּה בִּדְבָרִים וְלֹא גָּמַר בְּלִבּוֹ לַעֲזֹב הֲרֵי זֶה דּוֹמֶה לְטוֹבֵל וְשֶׁרֶץ בְּיָדוֹ שֶׁאֵין הַטְּבִילָה מוֹעֶלֶת לוֹ עַד שֶׁיַּשְׁלִיךְ הַשֶּׁרֶץ. וְכֵן הוּא אוֹמֵר וּמוֹדֶה וְעֹזֵב יְרֻחָם (משלי כח יג). וְצָרִיךְ לִפְרֹט אֶת הַחֵטְא שֶׁנֶּאֱמַר (שמות לב לא) \"אָנָּא חָטָא הָעָם הַזֶּה חֲטָאָה גְדלָה וַיַּעֲשׂוּ לָהֶם אֱלֹהֵי זָהָב\":","מִדַּרְכֵי הַתְּשׁוּבָה לִהְיוֹת הַשָּׁב צוֹעֵק תָּמִיד לִפְנֵי הַשֵּׁם בִּבְכִי וּבְתַחֲנוּנִים וְעוֹשֶׂה צְדָקָה כְּפִי כֹּחוֹ וּמִתְרַחֵק הַרְבֵּה מִן הַדָּבָר שֶׁחָטָא בּוֹ וּמְשַׁנֶּה שְׁמוֹ כְּלוֹמַר אֲנִי אַחֵר וְאֵינִי אוֹתוֹ הָאִישׁ שֶׁעָשָׂה אוֹתָן הַמַּעֲשִׂים וּמְשַׁנֶּה מַעֲשָׂיו כֻּלָּן לְטוֹבָה וּלְדֶרֶךְ יְשָׁרָה וְגוֹלֶה מִמְּקוֹמוֹ. שֶׁגָּלוּת מְכַפֶּרֶת עָוֹן מִפְּנֵי שֶׁגּוֹרֶמֶת לוֹ לְהִכָּנַע וְלִהְיוֹת עָנָו וּשְׁפַל רוּחַ:","וְשֶׁבַח גָּדוֹל לַשָּׁב שֶׁיִּתְוַדֶּה בָּרַבִּים וְיוֹדִיעַ פְּשָׁעָיו לָהֶם וּמְגַלֶּה עֲבֵרוֹת שֶׁבֵּינוֹ לְבֵין חֲבֵרוֹ לַאֲחֵרִים וְאוֹמֵר לָהֶם אָמְנָם חָטָאתִי לִפְלוֹנִי וְעָשִׂיתִי לוֹ כָּךְ וְכָךְ וַהֲרֵינִי הַיּוֹם שָׁב וּמִתְנַחֵם. וְכָל הַמִּתְגָּאֶה וְאֵינוֹ מוֹדִיעַ אֶלָּא מְכַסֶּה פְּשָׁעָיו אֵין תְּשׁוּבָתוֹ גְּמוּרָה שֶׁנֶּאֱמַר (משלי כח יג) \"מְכַסֶּה פְשָׁעָיו לֹא יַצְלִיחַ\". בַּמֶּה דְּבָרִים אֲמוּרִים בַּעֲבֵרוֹת שֶׁבֵּין אָדָם לַחֲבֵרוֹ אֲבָל בַּעֲבֵרוֹת שֶׁבֵּין אָדָם לַמָּקוֹם אֵינוֹ צָרִיךְ לְפַרְסֵם עַצְמוֹ וְעַזּוּת פָּנִים הִיא לוֹ אִם גִּלָּם. אֶלָּא שָׁב לִפְנֵי הָאֵל בָּרוּךְ הוּא וּפוֹרֵט חֲטָאָיו לְפָנָיו וּמִתְוַדֶּה עֲלֵיהֶם לִפְנֵי רַבִּים סְתָם. וְטוֹבָה הִיא לוֹ שֶׁלֹּא נִתְגַּלָּה עֲוֹנוֹ שֶׁנֶּאֱמַר (תהילים לב א) \"אַשְׁרֵי נְשׂוּי פֶּשַׁע כְּסוּי חֲטָאָה\":","אַף עַל פִּי שֶׁהַתְּשׁוּבָה וְהַצְּעָקָה יָפָה לָעוֹלָם. בַּעֲשָׂרָה הַיָּמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים הִיא יָפָה בְּיוֹתֵר וּמִתְקַבֶּלֶת הִיא מִיָּד שֶׁנֶּאֱמַר (ישעיה נה ו) \"דִּרְשׁוּ ה' בְּהִמָּצְאוֹ\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּיָחִיד אֲבָל צִבּוּר כָּל זְמַן שֶׁעוֹשִׂים תְּשׁוּבָה וְצוֹעֲקִין בְּלֵב שָׁלֵם הֵם נַעֲנִין שֶׁנֶּאֱמַר (דברים ד ז) \"כַּה' אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו\":","יוֹם הַכִּפּוּרִים הוּא זְמַן תְּשׁוּבָה לַכּל לַיָּחִיד וְלָרַבִּים וְהוּא קֵץ מְחִילָה וּסְלִיחָה לְיִשְׂרָאֵל. לְפִיכָךְ חַיָּבִים הַכּל לַעֲשׂוֹת תְּשׁוּבָה וּלְהִתְוַדּוֹת בְּיוֹם הַכִּפּוּרִים. וּמִצְוַת וִדּוּי יוֹם הַכִּפּוּרִים שֶׁיַּתְחִיל מֵעֶרֶב הַיּוֹם קֹדֶם שֶׁיֹּאכַל שֶׁמָּא יֵחָנֵק בַּסְּעֻדָּה קֹדֶם שֶׁיִּתְוַדֶּה. וְאַף עַל פִּי שֶׁהִתְוַדָּה קֹדֶם שֶׁיֹּאכַל חוֹזֵר וּמִתְוַדֶּה בְּלֵילֵי יוֹם הַכִּפּוּרִים עַרְבִית וְחוֹזֵר וּמִתְוַדֶּה בְּשַׁחֲרִית וּבְמוּסָף וּבְמִנְחָה וּבִנְעִילָה. וְהֵיכָן מִתְוַדֶּה. יָחִיד אַחַר תְּפִלָּתוֹ וּשְׁלִיחַ צִבּוּר בְּאֶמְצַע תְּפִלָּתוֹ בִּבְרָכָה רְבִיעִית:","הַוִּדּוּי שֶׁנָּהֲגוּ בּוֹ כָּל יִשְׂרָאֵל אֲבָל אֲנַחְנוּ חָטָאנוּ (כֻּלָּנוּ) וְהוּא עִקַּר הַוִּדּוּי. עֲבֵרוֹת שֶׁהִתְוַדָּה עֲלֵיהֶם בְּיוֹם הַכִּפּוּרִים זֶה חוֹזֵר וּמִתְוַדֶּה עֲלֵיהֶן בְּיוֹם הַכִּפּוּרִים אַחֵר אַף עַל פִּי שֶׁהוּא עוֹמֵד בִּתְשׁוּבָתוֹ שֶׁנֶּאֱמַר (תהילים נא ה) \"כִּי פְשָׁעַי אֲנִי אֵדָע וְחַטָּאתִי נֶגְדִּי תָמִיד\":","אֵין הַתְּשׁוּבָה וְלֹא יוֹם הַכִּפּוּרִים מְכַפְּרִין אֶלָּא עַל עֲבֵרוֹת שֶׁבֵּין אָדָם לַמָּקוֹם כְּגוֹן מִי שֶׁאָכַל דָּבָר אָסוּר אוֹ בָּעַל בְּעִילָה אֲסוּרָה וְכַיּוֹצֵא בָּהֶן. אֲבָל עֲבֵרוֹת שֶׁבֵּין אָדָם לַחֲבֵרוֹ כְּגוֹן הַחוֹבֵל אֶת חֲבֵרוֹ אוֹ הַמְקַלֵּל חֲבֵרוֹ אוֹ גּוֹזְלוֹ וְכַיּוֹצֵא בָּהֶן אֵינוֹ נִמְחַל לוֹ לְעוֹלָם עַד שֶׁיִּתֵּן לַחֲבֵרוֹ מַה שֶּׁהוּא חַיָּב לוֹ וִירַצֵּהוּ. אַף עַל פִּי שֶׁהֶחֱזִיר לוֹ מָמוֹן שֶׁהוּא חַיָּב לוֹ צָרִיךְ לְרַצּוֹתוֹ וְלִשְׁאל מִמֶּנּוּ שֶׁיִּמְחל לוֹ. אֲפִלּוּ לֹא הִקְנִיט אֶת חֲבֵרוֹ אֶלָּא בִּדְבָרִים צָרִיךְ לְפַיְּסוֹ וְלִפְגֹּעַ בּוֹ עַד שֶׁיִּמְחל לוֹ. לֹא רָצָה חֲבֵרוֹ לִמְחל לוֹ מֵבִיא לוֹ שׁוּרָה שֶׁל שְׁלֹשָׁה בְּנֵי אָדָם מֵרֵעָיו וּפוֹגְעִין בּוֹ וּמְבַקְּשִׁין מִמֶּנּוּ. לֹא נִתְרַצָּה לָהֶן מֵבִיא לוֹ שְׁנִיָּה וּשְׁלִישִׁית. לֹא רָצָה מְנִיחוֹ וְהוֹלֵךְ לוֹ וְזֶה שֶׁלֹּא מָחַל הוּא הַחוֹטֵא. וְאִם הָיָה רַבּוֹ הוֹלֵךְ וּבָא אֲפִלּוּ אֶלֶף פְּעָמִים עַד שֶׁיִּמְחל לוֹ:","אָסוּר לָאָדָם לִהְיוֹת אַכְזָרִי וְלֹא יִתְפַּיֵּס אֶלָּא יְהֵא נוֹחַ לִרְצוֹת וְקָשֶׁה לִכְעֹס וּבְשָׁעָה שֶׁמְּבַקֵּשׁ מִמֶּנּוּ הַחוֹטֵא לִמְחל מוֹחֵל בְּלֵב שָׁלֵם וּבְנֶפֶשׁ חֲפֵצָה. וַאֲפִלּוּ הֵצֵר לוֹ וְחָטָא לוֹ הַרְבֵּה לֹא יִקֹּם וְלֹא יִטֹּר. וְזֶהוּ דַּרְכָּם שֶׁל זֶרַע יִשְׂרָאֵל וְלִבָּם הַנָּכוֹן. אֲבָל הָעוֹבְדֵי כּוֹכָבִים עַרְלֵי לֵב אֵינָן כֵּן אֶלָּא (וְעֶבְרָתָן) [וְעֶבְרָתוֹ] שְׁמָרָה נֶצַח. וְכֵן הוּא אוֹמֵר עַל הַגִּבְעוֹנִים לְפִי שֶׁלֹּא מָחֲלוּ וְלֹא נִתְפַּיְּסוּ וְהַגִּבְעֹנִים לֹא מִבְּנֵי יִשְׂרָאֵל הֵמָּה:","הַחוֹטֵא לַחֲבֵרוֹ וּמֵת חֲבֵרוֹ קֹדֶם שֶׁיְּבַקֵּשׁ מְחִילָה מֵבִיא עֲשָׂרָה בְּנֵי אָדָם וּמַעֲמִידָן עַל קִבְרוֹ וְיֹאמַר בִּפְנֵיהֶם חָטָאתִי לַה' אֱלֹהֵי יִשְׂרָאֵל וְלִפְלוֹנִי זֶה שֶׁכָּךְ וְכָךְ עָשִׂיתִי לוֹ. וְאִם הָיָה חַיָּב לוֹ מָמוֹן יַחֲזִירוֹ לַיּוֹרְשִׁים. לֹא הָיָה יוֹדֵעַ לוֹ יוֹרְשִׁין יַנִּיחֶנּוּ בְּבֵית דִּין וְיִתְוַדֶּה:"],"Mishneh Torah, Rest on a Holiday 5":["אַף עַל פִּי שֶׁהֻתְּרָה הוֹצָאָה בְּיוֹם טוֹב אֲפִלּוּ שֶׁלֹּא לְצֹרֶךְ לֹא יִשָּׂא מַשָּׂאוֹת גְּדוֹלוֹת כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל אֶלָּא צָרִיךְ לְשַׁנּוֹת. וְאִם אִי אֶפְשָׁר לְשַׁנּוֹת מֻתָּר. כֵּיצַד. הַמֵּבִיא כַּדֵּי יַיִן מִמָּקוֹם לְמָקוֹם לֹא יְבִיאֵם בְּסַל וּבְקֻפָּה אֲבָל מֵבִיא הוּא עַל כְּתֵפוֹ אוֹ לְפָנָיו. הַמּוֹלִיךְ אֶת הַתֶּבֶן לֹא יַפְשִׁיל אֶת הַקֻּפָּה לְאַחֲרָיו אֲבָל מוֹלִיכָהּ בְּיָדוֹ:","וְכֵן מַשּׂוֹאוֹת שֶׁדַּרְכָּן לִשָּׂא אוֹתָן בְּמוֹט יִשָּׂא אוֹתָן עַל גַּבּוֹ מֵאַחֲרָיו. וְשֶׁדַּרְכָּן לִשָּׂא אוֹתָן מֵאֲחוֹרָיו יִשָּׂא אוֹתָן עַל כְּתֵפוֹ. וְשֶׁדַּרְכָּן לְהִנָּשֵׂא עַל הַכָּתֵף יִשָּׂא אוֹתָן בְּיָדוֹ לְפָנָיו אוֹ יִפְרשׁ עֲלֵיהֶן בֶּגֶד וְכָל כַּיּוֹצֵא בָּזֶה מִשִּׁנּוּי הַמַּשָּׂא. וְאִם אִי אֶפְשָׁר לְשַׁנּוֹת נוֹשֵׂא וּמֵבִיא כְּדַרְכּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּנוֹשֵׂא עַל הָאָדָם אֲבָל עַל גַּבֵּי בְּהֵמָה לֹא יָבִיא כְּלָל שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל:","אֵין מַנְהִיגִין אֶת הַבְּהֵמָה בְּמַקֵּל. וְאֵין הַסּוּמָא יוֹצֵא בְּמַקְלוֹ וְלֹא הָרוֹעֶה בְּתַרְמִילוֹ. וְאֵין יוֹצְאִין בְּכִסֵּא אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. ואִישׁ שֶׁהָיוּ רַבִּים צְרִיכִין לוֹ יוֹצְאִין בְּכִסֵּא אַחֲרָיו וּמוֹצִיאִין אוֹתוֹ עַל הַכָּתֵף אֲפִלּוּ בְּאַפִּרְיוֹן:","אֵין מוֹלִיכִין אֶת הַסֻּלָּם שֶׁל שׁוֹבָךְ מִשּׁוֹבָךְ לְשׁוֹבָךְ בִּרְשׁוּת הָרַבִּים שֶׁמָּא יֹאמְרוּ לְתַקֵּן גַּגּוֹ הוּא מוֹלִיכוֹ. אֲבָל בִּרְשׁוּת הַיָּחִיד מוֹלִיכוֹ. אַף עַל פִּי שֶׁכָּל מָקוֹם שֶׁאָסְרוּ חֲכָמִים מִפְּנֵי מַרְאִית הָעַיִן אֲפִלּוּ בְּחַדְרֵי חֲדָרִים אָסוּר כָּאן הִתִּירוּ מִפְּנֵי שִׂמְחַת יוֹם טוֹב:","מִי שֶׁהָיוּ לוֹ פֵּרוֹת עַל גַּגּוֹ וְצָרִיךְ לְפַנּוֹתָם לְמָקוֹם אַחֵר לֹא יוֹשִׁיטֵם מִגַּג לְגַג וַאֲפִלּוּ בַּגַּגִּין הַשָּׁוִין. וְלֹא יְשַׁלְשְׁלֵם בְּחֶבֶל מִן הַחַלּוֹנוֹת וְלֹא יוֹרִידֵם בְּסֻלָּמוֹת שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. אֲבָל מַשִּׁילָן אֲפִלּוּ דֶּרֶךְ אֲרֻבָּה מִמָּקוֹם לְמָקוֹם בְּאוֹתוֹ הַגַּג. שָׁחַט בְּהֵמָה בַּשָּׂדֶה לֹא יְבִיאֶנָּה בְּמוֹט לָעִיר אוֹ בְּמוֹטָה אֲבָל מְבִיאָהּ אֵיבָרִים אֵיבָרִים:","כָּל שֶׁנֵּאוֹתִין בּוֹ אֲפִלּוּ בְּחל אַף עַל פִּי שֶׁאֵין נֵאוֹתִין בּוֹ בְּיוֹם טוֹב כְּגוֹן תְּפִלִּין מֻתָּר לְשָׁלְחָן לַחֲבֵרוֹ בְּיוֹם טוֹב. וְאֵין צָרִיךְ לוֹמַר דָּבָר שֶׁנֵּאוֹתִין בּוֹ בְּיוֹם טוֹב כְּגוֹן יֵינוֹת שְׁמָנִים וּסְלָתוֹת שֶׁמֻּתָּר לְשָׁלְחָן. וְכָל דָּבָר שֶׁאֵין נֵאוֹתִין בּוֹ בְּחל עַד שֶׁיַּעֲשֶׂה בּוֹ מַעֲשֶׂה שֶׁאָסוּר לַעֲשׂוֹתוֹ בְּיוֹם טוֹב אֵין מְשַׁלְּחִין אוֹתוֹ בְּיוֹם טוֹב:","כֵּיצַד. אֵין מְשַׁלְּחִין בְּיוֹם טוֹב תְּבוּאָה לְפִי שֶׁאֵין נֵאוֹתִין בָּהּ בְּחל אֶלָּא אִם כֵּן טָחַן וְאָסוּר לִטְחֹן בְּיוֹם טוֹב. אֲבָל מְשַׁלְּחִין קִטְנִיּוֹת מִפְּנֵי שֶׁמְּבַשְּׁלָן בְּיוֹם טוֹב אוֹ קוֹלֶה אוֹתָן וְאוֹכְלָן. וּמְשַׁלְּחִין חַיָּה בְּהֵמָה וְעוֹפוֹת אֲפִלּוּ חַיִּים מִפְּנֵי שֶׁמֻּתָּר לִשְׁחֹט בְּיוֹם טוֹב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל דָּבָר שֶׁמֻּתָּר לְשָׁלְחוֹ בְּיוֹם טוֹב כְּשֶׁיִּשְׁלָחֶנּוּ לַחֲבֵרוֹ תְּשׁוּרָה לֹא יִשְׁלָחֶנּוּ בְּשׁוּרָה וְאֵין שׁוּרָה פְּחוּתָה מִשְּׁלֹשָׁה בְּנֵי אָדָם. כֵּיצַד. הֲרֵי שֶׁשָּׁלַח לַחֲבֵרוֹ בְּהֵמוֹת אוֹ יֵינוֹת בְּיַד שְׁלֹשָׁה בְּנֵי אָדָם כְּאֶחָד אוֹ אַרְבָּעָה זֶה אַחַר זֶה וְכֻלָּן הוֹלְכִין בְּשׁוּרָה אַחַת הֲרֵי זֶה אָסוּר שֶׁלֹּא יַעֲשֶׂה כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחל. שָׁלַח שְׁלֹשָׁה מִינִין בְּיַד שְׁלֹשָׁה בְּנֵי אָדָם כְּאֶחָד הֲרֵי זֶה מֻתָּר:","הַמְעָרֵב עֵרוּבֵי תְּחוּמִין לְיוֹם טוֹב הֲרֵי בְּהֶמְתּוֹ וְכֵלָיו וּפֵרוֹתָיו כָּמוֹהוּ. וְאֵין מוֹלִיכִין אוֹתָן אֶלָּא בְּתוֹךְ אַלְפַּיִם אַמָּה לְכָל רוּחַ מִמְּקוֹם עֵרוּבוֹ:","חֶפְצֵי הֶפְקֵר הֲרֵי הֵן כְּרַגְלֵי מִי שֶׁזָּכָה בָּהֶן. וְחֶפְצֵי הַכּוּתִים קוֹנִין שְׁבִיתָה בִּמְקוֹמָן וְיֵשׁ לָהֶן אַלְפַּיִם אַמָּה לְכָל רוּחַ מִמְּקוֹמָן גְּזֵרָה בְּעָלִים כּוּתִים מִשּׁוּם בְּעָלִים יִשְׂרָאֵל. פֵּרוֹת שֶׁיָּצְאוּ חוּץ לִמְקוֹמָן וְחָזְרוּ אֲפִלּוּ בְּמֵזִיד לֹא הִפְסִידוּ אֶת מְקוֹמָן מִפְּנֵי שֶׁהֵן כְּאָדָם שֶׁיָּצָא בְּאֹנֶס וְחָזַר בְּאֹנֶס:","הַמּוֹסֵר בְּהֶמְתּוֹ לִבְנוֹ הֲרֵי הִיא כְּרַגְלֵי הָאָב. מְסָרָהּ לְרוֹעֶה וַאֲפִלּוּ נְתָנָהּ לוֹ בְּיוֹם טוֹב הֲרֵי הִיא כְּרַגְלֵי הָרוֹעֶה. מְסָרָהּ לִשְׁנֵי רוֹעִים הֲרֵי הִיא כְּרַגְלֵי בְּעָלֶיהָ מִפְּנֵי שֶׁלֹּא קָנָה אֶחָד מֵהֶן:","מִי שֶׁזִּמֵּן אֶצְלוֹ אוֹרְחִים בְּיוֹם טוֹב לֹא יוֹלִיכוּ בְּיָדָם מָנוֹת לְמָקוֹם שֶׁאֵין בַּעַל הַסְּעֻדָּה יָכוֹל לֵילֵךְ בּוֹ. שֶׁכָּל הַסְּעֻדָּה כְּרַגְלֵי בַּעַל הַסְּעֻדָּה לֹא כְּרַגְלֵי הָאוֹרְחִין. אֶלָּא אִם כֵּן זָכָה לָהֶן אַחֵר בְּמָנוֹת אֵלּוּ מֵעֶרֶב יוֹם טוֹב:","וְכֵן מִי שֶׁהָיוּ פֵּרוֹתָיו מֻפְקָדִין בְּעִיר אַחֶרֶת וְעֵרְבוּ בְּנֵי אוֹתָהּ הָעִיר לָבֹא אֶצְלוֹ לֹא יָבִיאוּ לוֹ מִפֵּרוֹתָיו שֶׁפֵּרוֹתָיו כָּמוֹהוּ אַף עַל פִּי שֶׁהֵן בְּיַד אֵלּוּ שֶׁעֵרְבוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁיִּחֵד לָהֶן קֶרֶן זָוִית אֲבָל אִם לֹא יִחֵד לָהֶן הֲרֵי הֵן כְּרַגְלֵי זֶה שֶׁהֵן מֻפְקָדִין אֶצְלוֹ:","בּוֹר שֶׁל יָחִיד כְּרַגְלֵי בְּעָלָיו. וְשֶׁל אוֹתָהּ הָעִיר כְּרַגְלֵי אַנְשֵׁי אוֹתָהּ הָעִיר. וְשֶׁל עוֹלֵי בָּבֶל שֶׁהֵן מְסוּרִין לַכּל כְּרַגְלֵי הַמְמַלֵּא מֵהֶן שֶׁכָּל מִי שֶׁמִּלֵּא מֵהֶן מוֹלִיכָן לְמָקוֹם שֶׁהוּא מְהַלֵּךְ. נְהָרוֹת הַמּוֹשְׁכִין וּמַעֲיָנוֹת הַנּוֹבְעִין כְּרַגְלֵי כָּל אָדָם וְאִם הָיוּ בָּאִין מִחוּץ לַתְּחוּם לְתוֹךְ הַתְּחוּם מְמַלְּאִין מֵהֶן בְּשַׁבָּת וְאֵין צָרִיךְ לוֹמַר בְּיוֹם טוֹב:","שׁוֹר שֶׁל רוֹעֶה כְּרַגְלֵי אַנְשֵׁי אוֹתָהּ הָעִיר. וְשׁוֹר שֶׁל פְּטָם כְּרַגְלֵי מִי שֶׁלְּקָחוֹ לְשָׁחֳטוֹ בְּיוֹם טוֹב. מִפְּנֵי שֶׁדַּעַת בְּעָלָיו לְמָכְרוֹ לַאֲנָשִׁים אֲחֵרִים חוּץ מֵאַנְשֵׁי אוֹתָהּ הָעִיר מִפְּנֵי שֶׁהוּא מְפֻטָּם וְהַכּל שׁוֹמְעִין שָׁמְעוֹ וּבָאִין לִקְנוֹתוֹ. וְכֵן אִם שְׁחָטוֹ בְּעָלָיו בְּיוֹם טוֹב וּמָכַר בְּשָׂרוֹ. כָּל אֶחָד וְאֶחָד מִן הַלֹּקְחִים מוֹלִיךְ מְנָתוֹ לְמָקוֹם שֶׁהוּא הוֹלֵךְ מִפְּנֵי שֶׁדַּעַת בְּעָלָיו מֵעֶרֶב יוֹם טוֹב כָּךְ הוּא שֶׁיִּקְחוּ מִמֶּנּוּ אַנְשֵׁי עֲיָרוֹת אֲחֵרוֹת וְנִמְצָא שׁוֹר זֶה כְּבוֹר שֶׁל עוֹלֵי בָּבֶל שֶׁהוּא מָסוּר לַכּל:","הַגַּחֶלֶת כְּרַגְלֵי בְּעָלֶיהָ לֹא כְּרַגְלֵי שׁוֹאֲלָהּ וְהַשַּׁלְהֶבֶת כְּרַגְלֵי מִי שֶׁהִיא בְּיָדוֹ. לְפִיכָךְ הַמַּדְלִיק נֵר אוֹ עֵץ מֵחֲבֵרוֹ מוֹלִיכוֹ לְכָל מָקוֹם שֶׁהוּא הוֹלֵךְ:","הַשּׁוֹאֵל כְּלִי מֵחֲבֵרוֹ מֵעֶרֶב יוֹם טוֹב אַף עַל פִּי שֶׁלֹּא נְתָנוֹ לוֹ אֶלָּא בְּיוֹם טוֹב הֲרֵי הוּא כְּרַגְלֵי הַשּׁוֹאֵל. שְׁאָלוֹ מִמֶּנּוּ בְּיוֹם טוֹב אַף עַל פִּי שֶׁדַּרְכּוֹ תָּמִיד לִשְׁאל מִמֶּנּוּ כְּלִי זֶה בְּכָל יוֹם טוֹב הֲרֵי הוּא כְּרַגְלֵי הַמַּשְׁאִיל:","שְׁנַיִם שֶׁשָּׁאֲלוּ חָלוּק אֶחָד הָאֶחָד שְׁאָלוֹ מִמֶּנּוּ שֶׁיִּתְּנוֹ לוֹ שַׁחֲרִית וְהַשֵּׁנִי שְׁאָלוֹ מִמֶּנּוּ שֶׁיִּתְּנוֹ לוֹ עַרְבִית הֲרֵי כְּלִי זֶה כְּרַגְלֵי שְׁנֵי הַשּׁוֹאֲלִים וְאֵינָם מוֹלִיכִים אוֹתוֹ אֶלָּא בְּמָקוֹם שֶׁשְּׁנֵיהֶם יְכוֹלִין לְהַלֵּךְ בּוֹ:","כֵּיצַד. הֲרֵי שֶׁעֵרֵב הָרִאשׁוֹן בְּרִחוּק אֶלֶף אַמָּה מִמְּקוֹם הֶחָלוּק לְמִזְרָח וְעֵרֵב הַשֵּׁנִי בְּרִחוּק חֲמֵשׁ מֵאוֹת אַמָּה מִמְּקוֹם הֶחָלוּק לַמַּעֲרָב. כְּשֶׁלּוֹקֵחַ הָרִאשׁוֹן הֶחָלוּק אֵינוֹ מוֹלִיכוֹ לַמִּזְרָח אֶלָּא עַד אֶלֶף אַמָּה וַחֲמֵשׁ מֵאוֹת אַמָּה מִמְּקוֹם הֶחָלוּק שֶׁהוּא סוֹף הַתְּחוּם שֶׁיָּכוֹל זֶה שֶׁעֵרֵב בַּמַּעֲרָב לְהַלֵּךְ בּוֹ. וּכְשֶׁיִּקַּח הַשֵּׁנִי כְּלִי זֶה אֵינוֹ מוֹלִיכוֹ בַּמַּעֲרָב אֶלָּא עַד אֶלֶף אַמָּה מִמְּקוֹם הַכְּלִי שֶׁהוּא סוֹף הַתְּחוּם שֶׁיָּכוֹל זֶה שֶׁעֵרֵב בַּמִּזְרָח לְהַלֵּךְ בּוֹ. לְפִיכָךְ אִם עֵרֵב זֶה בְּרִחוּק אַלְפַּיִם אַמָּה מִן הֶחָלוּק לַמִּזְרָח וְזֶה בְּרִחוּק אַלְפַּיִם אַמָּה לַמַּעֲרָב הֲרֵי אֵלּוּ לֹא יְזִיזוּהוּ מִמְּקוֹמוֹ:","וְכֵן הָאִשָּׁה שֶׁשָּׁאֲלָה מֵחֲבֶרְתָּהּ מַיִם אוֹ מֶלַח וְלָשָׁה בָּהֶן עִסָּתָהּ אוֹ בִּשְּׁלָה בָּהֶן תַּבְשִׁיל הֲרֵי הָעִסָּה אוֹ הַתַּבְשִׁיל כְּרַגְלֵי שְׁתֵּיהֶן. וְכֵן שְׁנַיִם שֶׁלָּקְחוּ בְּהֵמָה בְּשֻׁתָּפוּת וְשָׁחֲטוּ בְּיוֹם טוֹב אַף עַל פִּי שֶׁלָּקַח כָּל אֶחָד מְנָתוֹ הֲרֵי כָּל הַבָּשָׂר כְּרַגְלֵי שְׁנֵיהֶן. אֲבָל אִם לָקְחוּ חָבִית בְּשֻׁתָּפוּת וְחָלְקוּ אוֹתָהּ בְּיוֹם טוֹב הֲרֵי חֶלְקוֹ שֶׁל כָּל אֶחָד כְּרַגְלָיו. הוֹאִיל וּתְחוּמִין מִדִּבְרֵי סוֹפְרִים יֵשׁ בְּרֵרָה בָּהֶן וְנַחְשֹׁב כְּאִלּוּ חֵלֶק שֶׁהִגִּיעַ לָזֶה הָיָה בָּרוּר לוֹ וּמֻבְדָּל בֶּחָבִית מֵעֶרֶב יוֹם טוֹב וּכְאִלּוּ לֹא הָיָה מְעֹרָב. וְאֵין אַתָּה יָכוֹל לוֹמַר כֵּן בִּבְהֵמָה שֶׁחֵלֶק זֶה שֶׁהִגִּיעוֹ אֲפִלּוּ נַחְשֹׁב אוֹתוֹ שֶׁהָיָה מֻבְדָּל בִּבְהֵמָה מֵעֶרֶב יוֹם טוֹב וּכְאִלּוּ הָיָה בָּרוּר הֲרֵי יָנַק מֵחֶלְקוֹ שֶׁל חֲבֵרוֹ כְּשֶׁהָיְתָה הַבְּהֵמָה קַיֶּמֶת שֶׁכָּל אֵיבָרֶיהָ יוֹנְקִין זֶה מִזֶּה וְנִמְצָא כָּל אֵיבָר וְאֵיבָר מְעֹרָב מֵחֶלְקוֹ וְחֵלֶק חֲבֵרוֹ. לְפִיכָךְ הֵן כְּרַגְלֵי שְׁנֵיהֶן:"],"Mishneh Torah, Ritual Slaughter 14":["מִצְוַת עֲשֵׂה לְכַסּוֹת דָּם שִׁחִיטַת חַיָּה טְהוֹרָה אוֹ עוֹף טָהוֹר שֶׁנֶּאֱמַר (ויקרא יז יג) \"אֲשֶׁר יָצוּד צֵיד חַיָּה אוֹ עוֹף אֲשֶׁר יֵאָכֵל וְשָׁפַךְ אֶת דָּמוֹ וְכִסָּהוּ בֶּעָפָר\". לְפִיכָךְ חַיָּב לְבָרֵךְ קֹדֶם שֶׁיְּכַסֶּה בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל כִּסּוּי הַדָּם:","כִּסּוּי הַדָּם נוֹהֵג בִּמְזֻמָּן וּבְשֶׁאֵינוֹ מְזֻמָּן. לֹא נֶאֱמַר (ויקרא יז יג) \"אֲשֶׁר יָצוּד\" אֶלָּא בַּהוֹוֶה. וְנוֹהֵג בְּחֻלִּין וְלֹא בְּמֻקְדָּשִׁין. בֵּין קָדְשֵׁי הַמִּזְבֵּחַ בֵּין קָדְשֵׁי בֶּדֶק הַבַּיִת. וְאִם עָבַר וּשְׁחָטָן אֵינוֹ חַיָּב לְכַסּוֹת אֶת דָּמָן:","שָׁחַט חַיָּה וְעוֹף וְאַחַר כָּךְ הִקְדִּישָׁן אוֹ הִקְדִּישׁ אֶת הַדָּם חַיָּב לְכַסּוֹת:","כִּלְאַיִם הַבָּא מִבְּהֵמָה וְחַיָּה וְכֵן בְּרִיָּה שֶׁהִיא סְפֵק בְּהֵמָה אוֹ חַיָּה צָרִיךְ לְכַסּוֹת וְאֵינוֹ מְבָרֵךְ. הַשּׁוֹחֵט לְחוֹלֶה בְּשַׁבָּת חַיָּב לְכַסּוֹת לְאַחַר שַׁבָּת. וְכֵן הַשּׁוֹחֵט סָפֵק אוֹ כִּלְאַיִם בְּיוֹם טוֹב מְכַסֶּה דָּמוֹ לְאַחַר יוֹם טוֹב:","הַשּׁוֹחֵט עוֹפוֹת וּמִינֵי חַיָּה בְּמָקוֹם אֶחָד מְבָרֵךְ בְּרָכָה אַחַת לְכֻלָּן וְכִסּוּי אֶחָד לְכֻלָּן:","דָּם שֶׁנִּתְעָרֵב בַּמַּיִם אִם יֵשׁ בּוֹ מַרְאֵה דָּם חַיָּב לְכַסּוֹת וְאִם לָאו פָּטוּר. נִתְעָרֵב בְּיַיִן אוֹ בְּדַם בְּהֵמָה רוֹאִין אוֹתָן כְּאִלּוּ הֵם מַיִם. אִם אֶפְשָׁר שֶיֵרָאֶה מַרְאֵה הַדָּם שֶׁחַיָּב לְכַסּוֹתוֹ כְּשִׁעוּר זֶה אִלּוּ הָיָה מַיִם חַיָּב לְכַסּוֹת הַכּל וְאִם לָאו פָּטוּר:","כִּסָּהוּ וְנִתְגַּלָּה אֵינוֹ חַיָּב לְכַסּוֹתוֹ פַּעַם אַחֶרֶת. כִּסַּתְהוּ הָרוּחַ אֵינוֹ חַיָּב לְכַסּוֹת. חָזַר וְנִתְגַּלָּה אַחַר שֶׁכִּסַּתְהוּ הָרוּחַ חַיָּב לְכַסּוֹת:","דָּם הַנִּתָּז וְשֶׁעַל הַסַּכִּין אִם אֵין שָׁם דָּם אֶלָּא הוּא חַיָּב לְכַסּוֹת:","שָׁחַט וְנִבְלַע הַדָּם בַּקַּרְקַע אִם רִשּׁוּמוֹ נִכָּר חַיָּב לְכַסּוֹת. וְאִם לָאו הֲרֵי זֶה כְּמִי שֶׁכִּסַּתְהוּ הָרוּחַ וּפָטוּר מִלְּכַסּוֹת:","אֵין חַיָּב בְּכִסּוּי אֶלָּא דָּם שְׁחִיטָה הָרְאוּיָה לַאֲכִילָה שֶׁנֶּאֱמַר (ויקרא יז יג) \"אֲשֶׁר יֵאָכֵל\". לְפִיכָךְ הַשּׁוֹחֵט וְנִמְצֵאת טְרֵפָה. אוֹ הַשּׁוֹחֵט חֻלִּין בַּעֲזָרָה. אוֹ הַשּׁוֹחֵט חַיָּה וְעוֹף שֶׁנִּגְמַר דִּינָן לִסְקִילָה וְהַשּׁוֹחֵט וְנִתְנַבְּלָה בְּיָדוֹ פָּטוּר מִלְּכַסּוֹת. וְכֵן חֶרֶשׂ שׁוֹטֶה וְקָטָן שֶׁשָּׁחֲטוּ בֵּינָן לְבֵין עַצְמָן פְּטוּרִין מִלְּכַסּוֹת דַּם שְׁחִיטָתָן:","בַּמֶּה מְכַסִּין בְּסִיד וּבְגַפְסִית בְּזֶבֶל דַּק וּבְחוֹל דַּק שֶׁאֵין הַיּוֹצֵר צָרִיךְ לְכָתְשׁוֹ וּבִשְׁחִיקַת אֲבָנִים וַחֲרָשִׂים וּבִנְעֹרֶת שֶׁל פִּשְׁתָּן דַּקָּה וּבִנְסֹרֶת חָרָשִׂים דַּקָּה וּבִלְבֵנָה וְחַרְסִית וּמְגוּפָה שֶׁכְּתָשָׁהּ שֶׁכָּל אֵלּוּ מִין עָפָר הֵן. אֲבָל אִם כָּפָה עָלָיו כְּלִי אוֹ כִּסָּהוּ בַּאֲבָנִים אֵין זֶה כִּסּוּי שֶׁנֶּאֱמַר (ויקרא יז יג) \"בֶּעָפָר\":","לְפִיכָךְ אֵין מְכַסִּים בְּזֶבֶל גַּס וְחוֹל גַּס וְקֶמַח וְסֻבִּין וּמוֹרְסָן וּשְׁחִיקַת כְּלֵי מַתָּכוֹת לְפִי שֶׁאֵין אֵלּוּ מִין עָפָר. חוּץ מִשְּׁחִיקַת הַזָּהָב בִּלְבַד שֶׁמְּכַסִּין בָּהֶם מִפְּנֵי שֶׁנִּקְרָא עָפָר שֶׁנֶּאֱמַר (איוב כח ו) \"וְעַפְרֹת זָהָב לוֹ\" וְאוֹמֵר (דברים ט כא) \"עַד אֲשֶׁר דַּק לְעָפָר\":","מְכַסִּין בְּשִׁחוֹר וְהוּא פִּיחַ הַכִּבְשָׁן וּבְכוֹחַל וּבְנִקְרַת פְּסִילִים וּבְאֵפֶר בֵּין אֵפֶר עֵצִים בֵּין אֵפֶר בְּגָדִים אֲפִלּוּ אֵפֶר בָּשָׂר שֶׁנִּשְׂרַף שֶׁהֲרֵי כָּתוּב (במדבר יט יז) \"מֵעֲפַר שְׂרֵפַת הַחַטָּאת\". וּמֻתָּר לְכַסּוֹת בְּעָפָר עִיר הַנִּדַּחַת:","הַשּׁוֹחֵט צָרִיךְ לִתֵּן עָפָר לְמַטָּה וְאַחַר כָּךְ יִשְׁחֹט בּוֹ וְאַחַר כָּךְ יְכַסֶּה בְּעָפָר אֲבָל לֹא יִשְׁחֹט בִּכְלִי וִיכַסֶּה בְּעָפָר:","וּמִי שֶׁשָּׁחַט הוּא יְכַסֶּה שֶׁנֶּאֱמַר (ויקרא יז יג) \"וְכִסָּהוּ בֶּעָפָר\". וְאִם לֹא כִּסָּהוּ וְרָאָהוּ אַחֵר חַיָּב לְכַסּוֹת שֶׁזּוֹ מִצְוָה בִּפְנֵי עַצְמָהּ וְאֵינָהּ תְּלוּיָה בַּשּׁוֹחֵט לְבַד:","וּכְשֶׁמְּכַסֶּה לֹא יְכַסֶּה בְּרַגְלוֹ אֶלָּא בְּיָדוֹ אוֹ בְּסַכִּין אוֹ בִּכְלִי כְּדֵי שֶׁלֹּא יִנְהֹג בּוֹ מִנְהַג בִּזָּיוֹן וְיִהְיוּ מִצְוֹת בְּזוּיוֹת עָלָיו. שֶׁאֵין הַכָּבוֹד לְעַצְמָן שֶׁל מִצְוֹת אֶלָּא לְמִי שֶׁצִּוָּה בָּהֶן בָּרוּךְ הוּא וְהִצִּילָנוּ מִלְּמַשֵּׁשׁ בַּחשֶׁךְ וְעָרַךְ אוֹתָנוּ נֵר לְיַשֵּׁר הַמַּעֲקַשִּׁים וְאוֹר לְהוֹרוֹת נְתִיבוֹת הַיּשֶׁר. וְכֵן הוּא אוֹמֵר (תהילים קיט קה) \"נֵר לְרַגְלִי דְבָרֶךָ וְאוֹר לִנְתִיבָתִי\":","נגמר ספר חמישי והוא ספר קדושה ומנין פרקיו שלשה וחמשים:הלכות איסורי ביאה שנים ועשרים פרקים, הלכות מאכלות אסורות שבעה עשר פרקים, הלכות שחיטה ארבעה עשר פרקים. ובכאן נשלם החלק השני, ה' במעגלי צדק ינחני."],"Mishneh Torah, Robbery and Lost Property 12":["מִי שֶׁאָבְדָה לוֹ אֲבֵדָה וּפָגַע בַּאֲבֵדָתוֹ וַאֲבֵדַת חֲבֵרוֹ אִם יָכוֹל לְהַחְזִיר שְׁתֵּיהֶן חַיָּב לְהַחְזִיר שְׁתֵּיהֶן וְאִם אֵינוֹ יָכוֹל לְהַחְזִיר אֶלָּא אַחַת מֵהֶן אֲבֵדָתוֹ קוֹדֶמֶת וַאֲפִלּוּ לַאֲבֵדַת אָבִיו אוֹ שֶׁל רַבּוֹ שֶׁלּוֹ קוֹדֵם לְכָל אָדָם:","פָּגַע בַּאֲבֵדַת רַבּוֹ עִם אֲבֵדַת אָבִיו אִם הָיָה אָבִיו שָׁקוּל כְּנֶגֶד רַבּוֹ שֶׁל אָבִיו קוֹדֶמֶת וְאִם לָאו שֶׁל רַבּוֹ קוֹדֶמֶת. וְהוּא שֶׁיִּהְיֶה רַבּוֹ מֻבְהָק שֶׁרֹב חָכְמָתוֹ שֶׁל תּוֹרָה מִמֶּנּוּ לָמַד:","הֵנִיחַ אֲבֵדָתוֹ וְהֶחְזִיר אֲבֵדַת חֲבֵרוֹ אֵין לוֹ אֶלָּא שָׂכָר הָרָאוּי לוֹ. כֵּיצַד. שָׁטַף נָהָר חֲמוֹרוֹ וַחֲמוֹר חֲבֵרוֹ שֶׁלּוֹ יָפֶה מָנֶה וְשֶׁל חֲבֵרוֹ מָאתַיִם. הִנִּיחַ אֶת שֶׁלּוֹ וְהִצִּיל אֶת שֶׁל חֲבֵרוֹ אֵין לוֹ אֶלָּא שְׂכָרוֹ הָרָאוּי לוֹ. וְאִם אָמַר לוֹ אַצִּיל אֶת שֶׁלְּךָ וְאַתָּה נוֹתֵן לִי דְּמֵי שֶׁלִּי אוֹ שֶׁהִתְנָה בִּפְנֵי בֵּית דִּין חַיָּב לִתֵּן לוֹ דְּמֵי שֶׁלּוֹ. וְאַף עַל פִּי שֶׁחֲמוֹרוֹ עָלָה מֵאֵלָיו. הוֹאִיל וְלֹא נִתְעַסֵּק בּוֹ זָכָה בְּמַה שֶּׁהִתְנָה עִמּוֹ:","יָרַד לְהַצִּיל וְלֹא הִצִּיל אֵין לוֹ אֶלָּא שְׂכָרוֹ הָרָאוּי לוֹ. וְכֵן אִם הָיָה עוֹסֵק בִּמְלָאכָה וּבִטֵּל מִמְּלַאכְתּוֹ שֶׁשָּׁוָה דִּינָר וְהֶחְזִיר אֲבֵדָה שֶׁשָּׁוָה מֵאָה דִּינָר לֹא יֹאמַר לוֹ תֵּן לִי דִּינָר שֶׁהִפְסַדְתִּי אֶלָּא נוֹתֵן לוֹ שְׂכָרוֹ כְּפוֹעֵל בָּטֵל שֶׁיִּבָּטֵל מֵאוֹתָהּ מְלָאכָה שֶׁהָיָה עוֹסֵק בָּהּ. וְאִם הִתְנָה עִם הַבְּעָלִים אוֹ בִּפְנֵי בֵּית דִּין שֶׁיִּטּל מַה שֶּׁיַּפְסִיד וְהִרְשׁוּהוּ הֲרֵי זֶה נוֹטֵל. וְאִם אֵין שָׁם בְּעָלִים וְלֹא בֵּית דִּין שֶׁלּוֹ קוֹדֵם:","וְכֵן שְׁנַיִם שֶׁהָיוּ בָּאִים בְּדֶרֶךְ זֶה בְּחָבִית שֶׁל יַיִן וְזֶה בְּכַד שֶׁל דְּבַשׁ וְנִסְדַּק הַכַּד שֶׁל דְּבַשׁ וְקֹדֶם שֶׁיִּשָּׁפֵךְ הַדְּבַשׁ לָאָרֶץ שָׁפַךְ זֶה אֶת יֵינוֹ וְהִצִּיל אֶת הַדְּבַשׁ לְתוֹךְ הֶחָבִית אֵין לוֹ אֶלָּא שְׂכָרוֹ הָרָאוּי לוֹ. וְאִם אָמַר אַצִּיל אֶת שֶׁלְּךָ וְאַתָּה נוֹתֵן לִי דְּמֵי שֶׁלִּי אוֹ שֶׁהִתְנָה בִּפְנֵי בֵּית דִּין הֲרֵי זֶה חַיָּב לִתֵּן לוֹ. וְאִם נִשְׁפַּךְ הַדְּבַשׁ לָאָרֶץ הֲרֵי זֶה הֶפְקֵר וְכָל הַמַּצִּיל לְעַצְמוֹ מַצִּיל:","הָיָה זֶה בָּא בְּכַד שֶׁל דְּבַשׁ וְזֶה בָּא בְּקַנְקַנִּים רֵיקָנִים וְנִסְדְּקָה כַּד הַדְּבַשׁ וְאָמַר לוֹ בַּעַל הַקַּנְקַנִּים אֵינִי מַצִּיל לְךָ דְּבַשׁ זֶה בְּקַנְקַנַּי עַד שֶׁתִּתֵּן לִי חֶצְיוֹ אוֹ שְׁלִישׁוֹ אוֹ כָּךְ וְכָךְ דִּינָרִין וְקִבֵּל עָלָיו בַּעַל הַדְּבַשׁ וְאָמַר לוֹ הֵן הֲרֵי זֶה שָׂחַק בּוֹ וְאֵינוֹ נוֹתֵן לוֹ אֶלָּא שְׂכָרוֹ הָרָאוּי לוֹ שֶׁהֲרֵי לֹא הִפְסִידוֹ כְּלוּם:","וְכֵן מִי שֶׁבָּרַח מִבֵּית הָאֲסוּרִים וְהָיְתָה מַעְבֹּרֶת לְפָנָיו וְאָמַר לוֹ הַעֲבִירֵנִי וַאֲנִי נוֹתֵן לְךָ דִּינָר וְהֶעֱבִירוֹ אֵין לוֹ אֶלָּא שְׂכָרוֹ הָרָאוּי לוֹ. וְאִם הָיָה צַיָּד וְאָמַר לוֹ בַּטֵּל מְצוּדָתְךָ וְהַעֲבִירֵנִי נוֹתֵן לוֹ כָּל מַה שֶּׁהִתְנָה עִמּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שַׁיָּרָא שֶׁהָיְתָה הוֹלֶכֶת בַּמִּדְבָּר וְעָמַד עָלֶיהָ גַּיִס וּטְרָפָהּ אִם אֵינָן יְכוֹלִין לְהַצִּיל מִיָּדָם וְעָמַד אֶחָד מֵהֶן וְהִצִּיל הִצִּיל לְעַצְמוֹ. וְאִם יְכוֹלִין הֵן לְהַצִּיל מִיָּדָם וְקָדַם אֶחָד מֵהֶן וְהִצִּיל אַף עַל פִּי שֶׁאָמַר לְעַצְמִי אֲנִי מַצִּיל הִצִּיל לָאֶמְצַע:","הָיוּ יְכוֹלִין לְהַצִּיל עַל יְדֵי הַדְּחָק כָּל הַמַּצִּיל מַצִּיל לָאֶמְצַע אֶלָּא אִם כֵּן אָמַר לְעַצְמִי אֲנִי מַצִּיל הֲרֵי זֶה מַצִּיל לְעַצְמוֹ. שֶׁכֵּיוָן שֶׁשְּׁמָעוּהוּ אוֹמֵר לְעַצְמִי אֲנִי מַצִּיל הָיָה לָהֶן לִדְחֹק עַצְמָן וּלְהַצִּיל וְכֵיוָן שֶׁיָּשְׁבוּ וְלֹא הִצִּילוּ הֲרֵי נִתְיָאֲשׁוּ מִן הַכּל:","הָיוּ שְׁנֵי שֻׁתָּפִין וְהִצִּיל אֶחָד מֵהֶן הִצִּיל לָאֶמְצַע. וְאִם אָמַר לְעַצְמִי אֲנִי מַצִּיל הֲרֵי זֶה חָלַק מֵחֲבֵרוֹ וְהִצִּיל לְעַצְמוֹ. וְכֵן הַשּׂוֹכֵר אֶת הַפּוֹעֵל לְהַצִּיל כָּל שֶׁיַּצִּיל הֲרֵי הוּא לַמַּשְׂכִּיר וְאִם אָמַר לְעַצְמִי אֲנִי מַצִּיל הֲרֵי זֶה חוֹזֵר בּוֹ מִן הַשְּׂכִירוּת וְכָל שֶׁיַּצִּיל אַחַר שֶׁאָמַר כֵּן הֲרֵי הוּא שֶׁלּוֹ:","שַׁיָּרָא שֶׁחָנְתָה בַּמִּדְבָּר וְעָמַד עָלֶיהָ גַּיִס לְטָרְפָהּ וּפָסְקוּ עִם הַגַּיִס מָמוֹן וְנָתְנוּ לוֹ. מְחַשְּׁבִין לְפִי מָמוֹנָם וְאֵין מְחַשְּׁבִין לְפִי נְפָשׁוֹת. וְאִם שָׂכְרוּ תַּיָּר לִפְנֵיהֶם לְהוֹדִיעָם הַדֶּרֶךְ מְחַשְּׁבִין שְׂכָרוֹ לְפִי מָמוֹן וּלְפִי נְפָשׁוֹת. וְאַל יְשַׁנּוּ מִמִּנְהַג הַחַמָּרִים:","רַשָּׁאִין הַחַמָּרִים לְהַתְנוֹת בֵּינֵיהֶן כָּל מִי שֶׁתֹּאבַד מִמֶּנּוּ חֲמוֹר מִבְּנֵי הַשַּׁיָּרָא מַעֲמִידִין לוֹ חֲמוֹר אַחֶרֶת. וְאִם פָּשַׁע בָּהּ הוּא וְאָבְדָה אֵין חַיָּבִין לְהַעֲמִיד לוֹ:","אָבְדָה חֲמוֹרוֹ וְאָמַר תְּנוּ לִי דָּמֶיהָ וְאֵינִי רוֹצֶה לִקַּח חֲמוֹר וַהֲרֵינִי שׁוֹמֵר עִמָּכֶם אֵין שׁוֹמְעִין לוֹ אֶלָּא מַעֲמִידִין לוֹ חֲמוֹר אַחֶרֶת כְּדֵי שֶׁיִּזְדָּרֵז עַצְמוֹ וְיִשְׁמֹר בְּהֶמְתּוֹ. וַאֲפִלּוּ הָיְתָה לוֹ בְּהֵמָה אַחֶרֶת בַּשַּׁיָּרָא אֵינוֹ דּוֹמֶה שׁוֹמֵר אַחַת לְשׁוֹמֵר שְׁתַּיִם:","סְפִינָה שֶׁהָיְתָה מְהַלֶּכֶת בַּיָּם וְעָמַד עָלֶיהָ נַחְשׁוֹל לְטַבְּעָהּ וְהֵקֵלּוּ מִמַּשָּׂאָהּ. מְחַשְּׁבִין לְפִי מַשּׂאוֹי וְאֵין מְחַשְּׁבִין לְפִי מָמוֹן. וְאַל יְשַׁנּוּ מִמִּנְהַג הַסַּפָּנִים:","רַשָּׁאִין הַסַּפָּנִים לְהַתְנוֹת בֵּינֵיהֶן כָּל מִי שֶׁתֹּאבַד לוֹ סְפִינָה מַעֲמִידִים לוֹ סְפִינָה אַחֶרֶת. פָּשַׁע בָּהּ וְאָבְדָה אוֹ שֶׁפֵּרַשׁ לְמָקוֹם שֶׁאֵין הַסְּפִינוֹת הוֹלְכוֹת בּוֹ בְּאוֹתוֹ הַזְּמַן אֵין חַיָּבִין לְהַעֲמִיד לוֹ:"],"Mishneh Torah, Robbery and Lost Property 7":["כָּל מִי שֶׁנִּתְחַיֵּב מָמוֹן לַחֲבֵרוֹ הַיִּשְׂרָאֵל וְכָפַר בּוֹ וְנִשְׁבַּע עַל שֶׁקֶר הֲרֵי זֶה חַיָּב לְהַחְזִיר לוֹ הַקֶּרֶן שֶׁכָּפַר בּוֹ וְהוֹסָפַת חֹמֶשׁ. וְחַיָּב בְּקָרְבָּן וְהוּא הַנִּקְרָא אֲשַׁם גְּזֵלוֹת:","אֶחָד הַגּוֹזֵל אוֹ הָעוֹשֵׁק אוֹ הַגּוֹנֵב אוֹ שֶׁהִלְוָהוּ אוֹ שֶׁהִפְקִיד אֶצְלוֹ אוֹ מָצָא אֲבֵדָה וְכִחֵשׁ בָּהּ אוֹ שֶׁהָיְתָה בֵּינֵיהֶן שֻׁתָּפוּת וְנִשְׁאַר לוֹ אֶצְלוֹ מָמוֹן אוֹ שֶׁעָשָׂה לוֹ מְלָאכָה וְלֹא נָתַן לוֹ שְׂכָרוֹ. כְּלָלוֹ שֶׁל דָּבָר כָּל שֶׁאִלּוּ הוֹדָה חַיָּב לְשַׁלֵּם בְּדִין וְכָפַר וְנִשְׁבַּע מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ שֶׁנֶּאֱמַר (ויקרא ה כא) \"וְכִחֵשׁ בַּעֲמִיתוֹ בְּפִקָּדוֹן\":","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה חַיָּב לְשַׁלֵּם מֵחֲמַת עַצְמוֹ. אֲבָל אִם הָיָה חַיָּב לְשַׁלֵּם מֵחֲמַת אָבִיו אֵינוֹ מְשַׁלֵּם חֹמֶשׁ. כֵּיצַד. כְּגוֹן שֶׁגָּזַל אָבִיו אוֹ גָּנַב אוֹ שֶׁהָיָה חַיָּב לַאֲחֵרִים וְהַבֵּן יוֹדֵעַ וְכָפַר הַבֵּן וְנִשְׁבַּע וְאַחַר כָּךְ הוֹדָה מְשַׁלֵּם הַקֶּרֶן בִּלְבַד שֶׁנֶּאֱמַר (ויקרא ה כג) \"אֲשֶׁר גָּזָל\" עַל גְּזֵלוֹ הוּא מוֹסִיף חֹמֶשׁ וְאֵינוֹ מוֹסִיף חֹמֶשׁ עַל גֵּזֶל אָבִיו:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאֵין הַגְּזֵלָה קַיֶּמֶת. אֲבָל אִם גָּזַל אָבִיו וּמֵת וְהַגְּזֵלָה קַיֶּמֶת וְכָפַר הַיּוֹרֵשׁ וְנִשְׁבַּע וְאַחַר כָּךְ הוֹדָה מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ:","גָּזַל הָאָב וְנִשְׁבַּע הָאָב וְהוֹדָה וְאַחַר כָּךְ מֵת הֲרֵי הַיּוֹרֵשׁ מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ:","גָּזַל וְנִשְׁבַּע וּמֵת וְהוֹדָה הַיּוֹרֵשׁ מְשַׁלֵּם הַקֶּרֶן בִּלְבַד. וּבֵין כָּךְ וּבֵין כָּךְ הַיּוֹרֵשׁ פָּטוּר מִן הָאָשָׁם:","הַנִּשְׁבָּע לְעַכּוּ\"ם מְשַׁלֵּם אֶת הַקֶּרֶן וְאֵינוֹ חַיָּב בְּחֹמֶשׁ שֶׁנֶּאֱמַר (ויקרא ה כא) \"וְכִחֵשׁ בַּעֲמִיתוֹ\". וְכֵן הַגּוֹזֵל פָּחוֹת מִשְּׁוֵה פְּרוּטָה וְכָפַר וְנִשְׁבַּע אֵינוֹ חַיָּב בְּחֹמֶשׁ שֶׁאֵין פָּחוֹת מִשְּׁוֵה פְּרוּטָה מָמוֹן. כַּמָּה הוּא הַחֹמֶשׁ. אֶחָד מֵאַרְבָּעָה בְּקֶרֶן שֶׁאִם גָּזַל שְׁוֵה אַרְבָּעָה וְנִשְׁבַּע מְשַׁלֵּם חֲמִשָּׁה. וְאִם הָיְתָה הַגְּזֵלָה קַיֶּמֶת מַחְזִיר אוֹתָהּ וְנוֹתֵן דְּמֵי רְבִיעַ שֶׁלָּהּ:","אֵין הַנִּשְׁבָּע עַל כְּפִירַת מָמוֹן מְשַׁלֵּם חֹמֶשׁ עַד שֶׁיּוֹדֶה מֵעַצְמוֹ. אֲבָל אִם בָּאוּ עֵדִים וְהוּא עוֹמֵד בִּכְפִירָתוֹ מְשַׁלֵּם הַקֶּרֶן בִּלְבַד עַל פִּי עֵדִים וְאֵינוֹ מְשַׁלֵּם אֶת הַחֹמֶשׁ. שֶׁהַחֹמֶשׁ עִם הַקָּרְבָּן לְכַפָּרָה הֵם בָּאִים וְאֵינוֹ מְבִיאָן אֶלָּא עַל פִּי עַצְמוֹ:","הַגּוֹזֵל אֶת חֲבֵרוֹ אַף עַל פִּי שֶׁכָּפַר בּוֹ הוֹאִיל וְלֹא נִשְׁבַּע אִם חָזַר וְהוֹדָה אֵינוֹ חַיָּב לִרְדֹּף אַחַר הַבְּעָלִים עַד שֶׁיַּחְזִיר לָהֶם מָמוֹן שֶׁבְּיָדוֹ אֶלָּא יְהֵא בְּיַד הַגַּזְלָן עַד שֶׁיָּבוֹאוּ הַבְּעָלִים וְיִטְּלוּ שֶׁלָּהֶן. אֲבָל אִם נִשְׁבַּע עַל שְׁוֵה פְּרוּטָה וָמַעְלָה חַיָּב לִרְדֹּף אַחַר הַבְּעָלִים עַד שֶׁיַּחְזִיר לָהֶם אֲפִלּוּ הֵם בְּאִיֵּי הַיָּם. מִפְּנֵי שֶׁכְּבָר נִתְיָאֲשׁוּ מֵאַחַר שֶׁנִּשְׁבַּע וְאֵינָן בָּאִין עוֹד לְתָבְעוֹ:","אֲפִלּוּ הֶחְזִיר הַגְּזֵלָה כֻּלָּהּ חוּץ מִשְּׁוֵה פְּרוּטָה חַיָּב לְהוֹלִיכָהּ אַחַר הַנִּגְזָל. וְלֹא יִתֵּן לֹא לִבְנוֹ שֶׁל נִגְזָל וְלֹא לִשְׁלוּחוֹ אֶלָּא אִם כֵּן עָשָׂה הַנִּגְזָל הַשָּׁלִיחַ בְּעֵדִים. וְאִם הֵבִיא אֶת הַגְּזֵלָה וְאֶת הַחֹמֶשׁ לְבֵית דִּין שֶׁבְּעִירוֹ הֲרֵי זֶה מֵבִיא אָשָׁם וּמִתְכַּפֵּר לוֹ וּבֵית דִּין מְטַפְּלִין בָּהּ עַד שֶׁתַּגִּיעַ לְבַעֲלָהּ. וְכֵן נוֹתֵן הוּא לִשְׁלִיחַ בֵּית דִּין. וְכָל הַנּוֹתֵן הַגְּזֵלָה וְכַיּוֹצֵא בּוֹ לְבֵית דִּין יָצָא:","נָתַן לוֹ אֶת הַקֶּרֶן וְלֹא נָתַן לוֹ אֶת הַחֹמֶשׁ אוֹ שֶׁמָּחַל לוֹ עַל הַקֶּרֶן וְלֹא מָחַל לוֹ עַל הַחֹמֶשׁ אוֹ שֶׁמָּחַל לוֹ עַל זֶה וְעַל זֶה חוּץ מִפָּחוֹת מִשְּׁוֵה פְּרוּטָה בַּקֶּרֶן אֵינוֹ צָרִיךְ לְהוֹלִיךְ אַחֲרָיו אֶלָּא יָבוֹא הַנִּגְזָל וְיִטּל אֶת הַשְּׁאָר. וְאַף עַל פִּי שֶׁהַגְּזֵלָה עַצְמָהּ קַיֶּמֶת אֵין חוֹשְׁשִׁין שֶׁמָּא תִּתְיַקֵּר וְנִמְצָא הַנִּשְׁאָר שְׁוֵה פְּרוּטָה. אֲבָל אִם נָתַן לוֹ אֶת הַחֹמֶשׁ וְלֹא נָתַן לוֹ אֶת הַקֶּרֶן אוֹ שֶׁמָּחַל לוֹ עַל הַחֹמֶשׁ וְלֹא מָחַל לוֹ עַל הַקֶּרֶן אוֹ שֶׁמָּחַל לוֹ עַל זֶה וְעַל זֶה חוּץ מִשְּׁוֵה פְּרוּטָה בַּקֶּרֶן חַיָּב לְהוֹלִיכוֹ אַחֲרָיו אוֹ לָתֵת לְבֵית דִּין שֶׁבְּעִירוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמַּחֲזִיר אֶת הַקֶּרֶן לַבְּעָלִים וְכָפַר פַּעַם שְׁנִיָּה בַּחֹמֶשׁ וְנִשְׁבַּע עָלָיו נַעֲשָׂה הַחֹמֶשׁ כְּקֶרֶן לְכָל דָּבָר וּמְשַׁלֵּם עָלָיו חֹמֶשׁ אַחֵר שֶׁנֶּאֱמַר (ויקרא ה כד) \"וַחֲמִשִׁתָיו יֹסֵף עָלָיו\" מְלַמֵּד שֶׁהוּא מוֹסִיף חֹמֶשׁ עַל חֹמֶשׁ עַד שֶׁיִּתְמַעֵט הַחֹמֶשׁ שֶׁיִּכְפֹּר בּוֹ וְנִשְׁבַּע עָלָיו מִשְּׁוֵה פְּרוּטָה:","מִי שֶׁהָיָה אֶצְלוֹ פִּקָּדוֹן וְטָעַן שֶׁאָבַד וְנִשְׁבַּע וְחָזַר וְהוֹדָה שֶׁהוּא אֶצְלוֹ. וְחָזַר וְטָעַן שֶׁאָבַד וְנִשְׁבַּע וְחָזַר וְהוֹדָה שֶׁהוּא אֶצְלוֹ מְשַׁלֵּם חֹמֶשׁ לְכָל שְׁבוּעָה וּשְׁבוּעָה עִם הַקֶּרֶן הָאֶחָד שֶׁנֶּאֱמַר (ויקרא ה כד) \"וַחֲמִשִׁתָיו יֹסֵף עָלָיו\" מְלַמֵּד שֶׁהוּא מְשַׁלֵּם כַּמָּה חֳמָשִׁין עַל קֶרֶן אֶחָד:"],"Mishneh Torah, Sabbath 18":["הַמּוֹצִיא דָּבָר מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הרבִּים אוֹ מֵרְשׁוּת הָרַבִּים לִרְשׁוּת הַיָּחִיד אֵינוֹ חַיָּב עַד שֶׁיּוֹצִיא מִמֶּנּוּ שִׁעוּר שֶׁמּוֹעִיל כְּלוּם. וְאֵלּוּ הֵן שִׁעוּרֵי הַהוֹצָאָה. הַמּוֹצִיא אָכְלֵי אָדָם כִּגְרוֹגֶרֶת. וּמִצְטָרְפִין זֶה עִם זֶה. וְהוּא שֶׁיִּהְיֶה כִּגְרוֹגֶרֶת מִן הָאֹכֶל עַצְמוֹ חוּץ מִן הַקְּלִפִּים וְהַגַּרְעִינִין וְהָעֵקְצִין וְהַסֻּבִּין וְהַמֻּרְסָן:","יַיִן כְּדֵי רֹבַע רְבִיעִית וְאִם הָיָה קָרוּשׁ בִּכְזַיִת. חֲלֵב בְּהֵמָה טְהוֹרָה כְּדֵי גְּמִיעָה וַחֲלֵב טְמֵאָה כְּדֵי לִכְחל עַיִן אַחַת. חֲלֵב אִשָּׁה וְלֹבֶן בֵּיצָה כְּדֵי לִתֵּן בִּמְשִׁיפָה. שֶׁמֶן כְּדֵי לָסוּךְ אֶצְבַּע קְטַנָּה שֶׁל רֶגֶל קָטָן בֶּן יוֹמוֹ. טַל כְּדֵי לָשׁוּף אֶת הַקִּילוֹרִין. וְקִילוֹר כְּדֵי לָשׁוּף בַּמַּיִם. וּמַיִם כְּדֵי לִרְחֹץ פְּנֵי מְדוּכָה. דְּבַשׁ כְּדֵי לִתֵּן עַל רֹאשׁ הַכָּתִית. דָּם וּשְׁאָר כָּל הַמַּשְׁקִין וְכָל הַשּׁוֹפְכִין כְּדֵי רְבִיעִית:","תֶּבֶן תְּבוּאָה כִּמְלֹא פִּי פָּרָה. תֶּבֶן קִטְנִיּוֹת כִּמְלֹא פִּי גָּמָל. וְאִם הוֹצִיא תֶּבֶן קִטְנִיּוֹת לְהַאֲכִילוֹ לְפָרָה כִּמְלֹא פִּי פָּרָה. שֶׁהָאֲכִילָה עַל יְדֵי הַדְּחָק שְׁמָהּ אֲכִילָה. עָמִיר כִּמְלֹא פִּי טָלֶה. עֲשָׂבִים כִּמְלֹא פִּי גְּדִי. עֲלֵי שׁוּם וַעֲלֵי בְּצָלִים אִם הָיוּ לַחִים כִּגְרוֹגֶרֶת מִפְּנֵי שֶׁהֵן אָכְלֵי אָדָם. וִיבֵשִׁים כִּמְלֹא פִּי גְּדִי. וְאֵין מִצְטָרְפִין זֶה עִם זֶה לֶחָמוּר שֶׁבָּהֶן אֲבָל מִצְטָרְפִין לַקַּל שֶׁבָּהֶן. כֵּיצַד. הוֹצִיא תֶּבֶן תְּבוּאָה וְקִטְנִית. אִם יֵשׁ בִּשְׁנֵיהֶם כִּמְלֹא פִּי פָּרָה פָּטוּר. כִּמְלֹא פִּי גָּמָל חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה לְעִנְיַן הַשַּׁבָּת:","הַמּוֹצִיא עֵצִים כְּדֵי לְבַשֵּׁל כִּגְרוֹגֶרֶת מִבֵּיצַת הַתַּרְנְגוֹלִים טְרוּפָה בְּשֶׁמֶן וּנְתוּנָה בְּאִלְפָּס. הַמּוֹצִיא קָנֶה כְּדֵי לַעֲשׂוֹת קֻלְמוֹס הַמַּגִּיעַ לְרָאשֵׁי אֶצְבְּעוֹתָיו. וְאִם הָיָה עָבֶה אוֹ מְרֻצָּץ שִׁעוּרוֹ כְּעֵצִים:","הַמּוֹצִיא תַּבְלִין כְּדֵי לְתַבֵּל בֵּיצָה וּמִצְטָרְפִין זֶה עִם זֶה. פִּלְפֵּל כָּל שֶׁהוּא. עִטְרָן כָּל שֶׁהוּא. רֵיחַ טוֹב כָּל שֶׁהוּא. רֵיחַ רַע כָּל שֶׁהוּא. מִינֵי בְּשָׂמִים כָּל שֶׁהֵן. אַרְגָּמָן טוֹב כָּל שֶׁהוּא. בְּתוּלַת הַוֶּרֶד אַחַת. מִינֵי מַתָּכוֹת הַקָּשִׁים כְּגוֹן נְחשֶׁת וּבַרְזֶל כָּל שֶׁהֵן. מֵעֲפַר הַמִּזְבֵּחַ וּמֵאַבְנֵי הַמִּזְבֵּחַ וּמִמֶּקֶק סְפָרִים וּמִמֶּקֶק מִטְפָּחוֹת שֶׁלָּהֶן כָּל שֶׁהֵן. מִפְּנֵי שֶׁמַּצְנִיעִין אוֹתָם לִגְנִיזָה. גַּחֶלֶת כָּל שֶׁהוּא. וְהַמּוֹצִיא שַׁלְהֶבֶת פָּטוּר:","הַמּוֹצִיא זֵרְעוֹנֵי גִּנָּה שֶׁאֵינָן נֶאֱכָלִין לְאָדָם שִׁעוּרָן פָּחוֹת מִכִּגְרוֹגֶרֶת. מִזֶּרַע קִשּׁוּאִין שְׁנַיִם. וּמִזֶּרַע הַדְּלוּעִין שְׁנַיִם. מִזֶּרַע פּוֹל הַמִּצְרִי שְׁנַיִם. הַמּוֹצִיא סֻבִּין כְּדֵי לִתֵּן עַל פִּי כּוּר שֶׁל צוֹרְפֵי זָהָב. הַמּוֹצִיא מֻרְסָן אִם לַאֲכִילָה שִׁעוּרוֹ כִּגְרוֹגֶרֶת. לִבְהֵמָה שִׁעוּרוֹ כִּמְלֹא פִּי גְּדִי. לִצְבִיעָה כְּדֵי לִצְבֹּעַ בֶּגֶד קָטָן. לוּלְבֵי זְרָדִין וְהַחֲרוּבִין עַד שֶׁלֹּא יַמְתִּיקוּ כִּגְרוֹגֶרֶת. וּמִשֶּׁיַּמְתִּיקוּ כִּמְלֹא פִּי גְּדִי. אֲבָל הַלּוּף וְהַחַרְדָּל וְהַתֻּרְמוֹסִין וּשְׁאָר כָּל הַנִּכְבָּשִׁין בֵּין שֶׁיַּמְתִּיקוּ בֵּין עַד שֶׁלֹּא יַמְתִּיקוּ כִּגְרוֹגֶרֶת:","הַמּוֹצִיא גַּרְעִינִין. אִם לַאֲכִילָה חָמֵשׁ. וְאִם לְהַסָּקָה הֲרֵי הֵן כְּעֵצִים. וְאִם לְחֶשְׁבּוֹן שְׁתַּיִם. וְאִם לִזְרִיעָה שְׁתַּיִם. הַמּוֹצִיא אֵזוֹב לְאֳכָלִים כִּגְרוֹגֶרֶת. לִבְהֵמָה כִּמְלֹא פִּי גְּדִי. לְעֵצִים כְּשִׁעוּר הָעֵצִים. לַהֲזָיָה כְּשִׁעוּר הֲזָיָה:","הַמּוֹצִיא קְלִפֵּי אֱגוֹזִין וּקְלִפֵּי רִמּוֹנִים אִסְטִיס וּפוּאָה וּשְׁאָר הַצְּבָעִין כְּדֵי לִצְבֹּעַ בָּהֶן בֶּגֶד קָטָן כִּסְבָכָה שֶׁמַּנִּיחִין הַבָּנוֹת עַל רָאשֵׁיהֶן. וְכֵן הַמּוֹצִיא מֵי רַגְלַיִם בֶּן אַרְבָּעִים יוֹם אוֹ נֶתֶר אֲלֶכְּסַנְדְּרִיָּא אוֹ בֹּרִית קִימוֹנְיָא וְאַשְׁלָג וּשְׁאָר כָּל הַמְנַקִּין כְּדֵי לְכַבֵּס בָּהֶן בֶּגֶד קָטָן כִּסְבָכָה. הוֹצִיא סַמָּנִין שְׁרוּיִין כְּדֵי לִצְבֹּעַ בָּהֶן דֻּגְמָא לְאִירָא:","הַמּוֹצִיא דְּיוֹ עַל הַקֻּלְמוֹס שִׁעוּרוֹ כְּדֵי לִכְתֹּב מִמֶּנּוּ שְׁתֵּי אוֹתִיּוֹת. אֲבָל אִם הוֹצִיא הַדְּיוֹ בִּפְנֵי עַצְמוֹ אוֹ בְּקֶסֶת צָרִיךְ שֶׁיִּהְיֶה בּוֹ יֶתֶר עַל זֶה כְּדֵי שֶׁיַּעֲלֶה מִמֶּנּוּ עַל הַקֻּלְמוֹס כְּדֵי לִכְתֹּב שְׁתֵּי אוֹתִיּוֹת. הָיָה בַּקֶּסֶת כְּדֵי אוֹת אַחַת וּבַקֻּלְמוֹס כְּדֵי אוֹת אַחַת אוֹ בַּדְּיוֹ לְבַדּוֹ כְּדֵי אוֹת אַחַת וּבַקֻּלְמוֹס כְּדֵי אוֹת אַחַת הֲרֵי זֶה סָפֵק. הוֹצִיא שְׁתֵּי אוֹתִיּוֹת וּכְתָבָן כְּשֶׁהוּא מְהַלֵּךְ חַיָּב. כְּתִיבָתָן זוֹ הִיא הַנָּחָתָן. הוֹצִיא אוֹת אַחַת וּכְתָבָהּ וְחָזַר וְהוֹצִיא אוֹת שְׁנִיָּה וּכְתָבָהּ פָּטוּר. שֶׁכְּבָר חָסְרָה הָאוֹת הָרִאשׁוֹנָה:","הַמּוֹצִיא כְּחל בֵּין לִרְפוּאָה בֵּין לְתַכְשִׁיט כְּדֵי לִכְחל עַיִן אַחַת. וּבְמָקוֹם שֶׁאֵין דַּרְכָּן לְהִתְקַשֵּׁט אֶלָּא בִּכְחִילַת שְׁתֵּי עֵינַיִם וְהוֹצִיאוֹ לְהִתְקַשֵּׁט עַד שֶׁיּוֹצִיא כְּדֵי לִכְחל שְׁתֵּי עֵינַיִם. זֶפֶת וְגָפְרִית כְּדֵי לַעֲשׂוֹת נֶקֶב. שַׁעֲוָה כְּדֵי לִתֵּן עַל פִּי נֶקֶב קָטָן. דֶּבֶק כְּדֵי לִתֵּן בְּרֹאשׁ הַשַּׁפְשָׁף. רְבָב כְּדֵי לִמְשֹׁחַ תַּחַת רָקִיק כְּסֶלַע:","הַמּוֹצִיא אֲדָמָה כְּדֵי לַעֲשׂוֹת חוֹתַם הָאִגֶּרֶת. טִיט כְּדֵי לַעֲשׂוֹת פִּי כּוּר. זֶבֶל אוֹ חוֹל דַּק כְּדֵי לְזַבֵּל כְּרִישָׁה. חוֹל גַּס כְּדֵי לְעָרֵב עִם מְלֹא כַּף שֶׁל סַיָּדִין. חַרְסִית כְּדֵי לַעֲשׂוֹת פִּי כּוּר שֶׁל צוֹרְפֵי זָהָב. שֵׂעַר כְּדֵי לְגַבֵּל טִיט לַעֲשׂוֹת פִּי כּוּר שֶׁל צוֹרְפֵי זָהָב. סִיד כְּדֵי לָסוּד אֶצְבַּע קְטַנָּה שֶׁבַּבָּנוֹת. עָפָר וָאֵפֶר כְּדֵי לְכַסּוֹת דַּם צִפּוֹר קְטַנָּה. צְרוֹר אֶבֶן כְּדֵי לִזְרֹק בִּבְהֵמָה וְתַרְגִּישׁ. וְהוּא מִשְׁקַל עֲשָׂרָה זוּזִים. חֶרֶס כְּדֵי לְקַבֵּל בּוֹ רְבִיעִית:","הַמּוֹצִיא חֶבֶל כְּדֵי לַעֲשׂוֹת אֹזֶן לְקֻפָּה. גֶּמִי כְּדֵי לַעֲשׂוֹת תְּלַאי לְנָפָה וְלִכְבָרָה. הוּצִין כְּדֵי לַעֲשׂוֹת אֹזֶן לִכְפִיפָה מִצְרִית. סִיב כְּדֵי לִתֵּן עַל פִּי מַשְׁפֵּךְ קָטָן שֶׁל יַיִן. מוֹכִין כְּדֵי לַעֲשׂוֹת בּוֹ כַּדּוּר כֶּאֱגוֹז. עֶצֶם כְּדֵי לַעֲשׂוֹת תַּרְוָד. זְכוּכִית כְּדֵי לִגְרֹד בָּהּ רֹאשׁ הַכַּרְכָּר אוֹ עַד שֶׁיִּפְצַע שְׁתֵּי נִימִין כְּאַחַת:","הַמּוֹצִיא שְׁתֵּי נִימִין מִזְּנַב הַסּוּס וּמִזְּנַב הַפָּרָה חַיָּב. הוֹצִיא אַחַת מִן הַקָּשֶׁה שֶׁבַּחֲזִיר חַיָּב. נִצְרֵי דֶּקֶל וְהֵן חוּטֵי הָעֵץ שְׁתַּיִם. חוֹרֵי דֶּקֶל וְהֵן קְלִפֵּי הַחֲרָיוֹת אַחַת. מִצֶּמֶר גֶּפֶן וּמִצֶּמֶר כָּלָךְ וְצֶמֶר גְּמַלִּים וְאַרְנָבִים וְחַיָּה שֶׁבַּיָּם וּשְׁאָר כָּל הַנִּטְוִין כְּדֵי לִטְווֹת חוּט אֹרֶךְ אַרְבָּעָה טְפָחִים. הַמּוֹצִיא מִן הַבֶּגֶד אוֹ מִן הַשַּׂק אוֹ מִן הָעוֹר כְּשִׁעוּרָן לְטֻמְאָה כָּךְ שִׁעוּרָן לְהוֹצָאָה. הַבֶּגֶד שְׁלֹשָׁה עַל שְׁלֹשָׁה. הַשַּׂק אַרְבָּעָה עַל אַרְבָּעָה. הָעוֹר חֲמִשָּׁה עַל חֲמִשָּׁה:","הַמּוֹצִיא עוֹר שֶׁלֹּא נִתְעַבֵּד כְּלָל אֶלָּא עֲדַיִן הוּא רַךְ שִׁעוּרוֹ כְּדֵי לָצוּר מִשְׁקלֶת קְטַנָּה שֶׁמִּשְׁקָלָהּ שֶׁקֶל. הָיָה מָלוּחַ וַעֲדַיִן לֹא נַעֲשָׂה בְּקֶמַח וְלֹא בְּעַפְּצָה שִׁעוּרוֹ כְּדֵי לַעֲשׂוֹת קָמֵעַ. הָיָה עָשׂוּי בְּקֶמַח וַעֲדַיִן לֹא נִתְעַבֵּד בְּעַפְּצָה שִׁעוּרוֹ כְּדֵי לִכְתֹּב עָלָיו אֶת הַגֵּט. נִגְמַר עִבּוּדוֹ שִׁעוּרוֹ חֲמִשָּׁה עַל חֲמִשָּׁה:","הַמּוֹצִיא קְלָף מְעֻבָּד כְּדֵי לִכְתֹּב עָלָיו פָּרָשַׁת שְׁמַע עַד וּבִשְׁעָרֶיךָ. דּוּכְסוּסְטוּס כְּדֵי לִכְתֹּב עָלָיו מְזוּזָה. נְיָר כְּדֵי לִכְתֹּב עָלָיו שְׁתֵּי אוֹתִיּוֹת שֶׁל קֶשֶׁר מוֹכְסִין שֶׁהֵן גְּדוֹלוֹת מֵאוֹתִיּוֹת שֶׁלָּנוּ. הַמּוֹצִיא קֶשֶׁר מוֹכְסִין חַיָּב אַף עַל פִּי שֶׁכְּבָר הֶרְאָהוּ לַמּוֹכֵס וְנִפְטַר בּוֹ שֶׁהֲרֵי רְאָיָה הִיא לְעוֹלָם. הַמּוֹצִיא שְׁטָר פָּרוּעַ וּנְיָר מָחוּק כְּדֵי לִכְרֹךְ עַל פִּי צְלוֹחִית קְטַנָּה שֶׁל פְּלַיָּיטוֹן. וְאִם יֵשׁ בַּלֹּבֶן שֶׁלּוֹ כְּדֵי לִכְתֹּב שְׁתֵּי אוֹתִיּוֹת שֶׁל קֶשֶׁר מוֹכְסִין חַיָּב:","הַמּוֹצִיא בְּהֵמָה חַיָּה וְעוֹף אַף עַל פִּי שֶׁהֵן חַיִּים חַיָּב. אֲבָל אָדָם חַי אֵינוֹ מַשּׂאוֹי. וְאִם הָיָה כָּפוּת אוֹ חוֹלֶה הַמּוֹצִיא אוֹתוֹ חַיָּב. וְהָאִשָּׁה מְדַדָּה אֶת בְּנָהּ בִּזְמַן שֶׁנּוֹטֵל אַחַת וּמַנִּיחַ אַחַת:","הַמּוֹצִיא תִּינוֹק חַי וְכִיס תָּלוּי בְּצַוָּארוֹ חַיָּב מִשּׁוּם הַכִּיס שֶׁאֵין הַכִּיס טְפֵלָה לַתִּינוֹק. אֲבָל אִם הוֹצִיא אֶת הַגָּדוֹל אַף עַל פִּי שֶׁהוּא מְלֻבָּשׁ בְּכֵלָיו וְטַבְּעוֹתָיו בְּיָדוֹ פָּטוּר שֶׁהַכּל טְפֵלָה לוֹ. הָיוּ כֵּלָיו מְקֻפָּלִין עַל כְּתֵפוֹ הַנּוֹשֵׂא אוֹתוֹ חַיָּב:","הַמּוֹצִיא חָגָב חַי כָּל שֶׁהוּא. וּמֵת כִּגְרוֹגֶרֶת. צִפֹּרֶת כְּרָמִים בֵּין חַיָּה בֵּין מֵתָה כָּל שֶׁהוּא מִפְּנֵי שֶׁמַּצְנִיעִין אוֹתָהּ לִרְפוּאָה. וְכֵן כָּל כַּיּוֹצֵא בָּהּ. הַמֵּת וְהַנְּבֵלָה וְהַשֶּׁרֶץ כְּשִׁעוּר טֻמְאָתָן כָּךְ שִׁעוּר הוֹצָאָתָן. מֵת וּנְבֵלָה כְּזַיִת וְשֶׁרֶץ כַּעֲדָשָׁה:","הָיָה שָׁם כְּזַיִת מְצֻמְצָם וְהוֹצִיא מִמֶּנּוּ כַּחֲצִי זַיִת חַיָּב שֶׁהֲרֵי הוֹעִיל בְּמַעֲשָׂיו שֶׁנִּתְמַעֵט הַשִּׁעוּר מִלְּטַמֵּא. אֲבָל אִם הוֹצִיא כַּחֲצִי זַיִת מִכְּזַיִת וּמֶחֱצָה פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה בִּשְׁאָר הַטֻּמְאוֹת:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁאֵינוֹ חַיָּב אֶלָּא עַל הַהוֹצָאָה כַּשִּׁעוּר, כְּשֶׁהוֹצִיא סְּתָם. אֲבָל הַמּוֹצִיא לְזֶרַע אוֹ לִרְפוּאָה אוֹ לְהַרְאוֹת מִמֶּנּוּ דֻּגְמָא וּלְכָל כַּיּוֹצֵא בָּזֶה חַיָּב בְּכָל שֶׁהוּא:","הַמַּצְנִיעַ דָּבָר לִזְרִיעָה אוֹ לִרְפוּאָה אוֹ לְדֻגְמָא וְשָׁכַח לָמָּה הִצְנִיעוֹ וְהוֹצִיאוֹ סְתָם חַיָּב עָלָיו בְּכָל שֶׁהוּא שֶׁעַל דַּעַת מַחֲשָׁבָה רִאשׁוֹנָה הוֹצִיא. וּשְׁאָר הָאָדָם אֵין חַיָּבִין עָלָיו אֶלָּא כְּשִׁעוּרוֹ. זָרַק זֶה שֶׁהוֹצִיא כְּבָר לְתוֹךְ הָאוֹצָר אַף עַל פִּי שֶׁמְּקוֹמוֹ נִכָּר כְּבָר בָּטְלָה מַחֲשַׁבְתּוֹ הָרִאשׁוֹנָה. לְפִיכָךְ אִם חָזַר וְהִכְנִיסוֹ אֵינוֹ חַיָּב עַד שֶׁיַּכְנִיס כַּשִּׁעוּר:","דָּבָר שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהַצְנִיעוֹ וְאֵינוֹ רָאוּי לְהַצְנִיעַ כְּגוֹן דַּם הַנִּדָּה אִם הִצְנִיעוֹ אֶחָד וְהוֹצִיאוֹ חַיָּב. וּשְׁאָר הָאָדָם פְּטוּרִין עָלָיו. שֶׁאֵין חַיָּבִין אֶלָּא עַל הוֹצָאַת דָּבָר הַכָּשֵׁר לְהַצְנִיעַ וּמַצְנִיעִין כָּמוֹהוּ:","הַמּוֹצִיא חֲצִי שִׁעוּר פָּטוּר. וְכֵן כָּל הָעוֹשֶׂה מְלָאכָה מִן הַמְּלָאכוֹת חֲצִי שִׁעוּר פָּטוּר. הוֹצִיא חֲצִי שִׁעוּר וְהִנִּיחוֹ וְחָזַר וְהוֹצִיא הַחֵצִי הָאַחֵר חַיָּב. וְאִם קָדַם וְהִגְבִּיהַּ הַחֵצִי הָרִאשׁוֹן קֹדֶם הַנָּחַת הַחֵצִי הַשֵּׁנִי נַעֲשָׂה כְּמִי שֶׁנִּשְׂרַף וּפָטוּר. הוֹצִיא חֲצִי שִׁעוּר וְהִנִּיחוֹ וְחָזַר וְהוֹצִיא חֵצִי אַחֵר וְהֶעֱבִירוֹ עַל הָרִאשׁוֹן בְּתוֹךְ שְׁלֹשָׁה חַיָּב. שֶׁהַמַּעֲבִיר כְּמִי שֶׁהִנִּיחַ עַל גַּבֵּי מַשֶּׁהוּ. אֲבָל אִם זְרָקוֹ אֵינוֹ חַיָּב עַד שֶׁיָּנוּחַ שָׁם עַל גַּבֵּי מַשֶּׁהוּ:","הוֹצִיא חֲצִי שִׁעוּר וְחָזַר וְהוֹצִיא חֲצִי שִׁעוּר בְּהֵעָלֵם אַחַת לִרְשׁוּת אַחַת חַיָּב. לִשְׁתֵּי רְשׁוּיוֹת אִם יֵשׁ בֵּינֵיהֶן רְשׁוּת שֶׁחַיָּבִין עָלֶיהָ פָּטוּר. הָיְתָה בֵּינֵיהֶן כַּרְמְלִית הֲרֵי הֵן כִּרְשׁוּת אַחַת וְחַיָּב חַטָּאת:","הַמּוֹצִיא פָּחוֹת מִכַּשִּׁעוּר וְקֹדֶם שֶׁיַּנִּיחוֹ נִתְפַּח וְחָזַר כַּשִּׁעוּר. וְכֵן הַמּוֹצִיא כַּשִּׁעוּר וְקֹדֶם שֶׁיַּנִּיחַ צָמַק וְחָזַר פָּחוֹת מִכַּשִּׁעוּר פָּטוּר:","הַמּוֹצִיא כִּגְרוֹגֶרֶת לַאֲכִילָה וְצָמְקָה קֹדֶם הַנָּחָה וְחָשַׁב עָלֶיהָ לִזְרִיעָה אוֹ לִרְפוּאָה שֶׁאֵינוֹ צָרִיךְ שִׁעוּר הֲרֵי זֶה חַיָּב כְּמַחֲשַׁבְתּוֹ שֶׁל עֵת הַנָּחָה. הוֹצִיא פָּחוֹת מִכִּגְרוֹגֶרֶת לִזְרִיעָה וְקֹדֶם הַנָּחָה חָזַר וְחָשַׁב עָלֶיהָ לַאֲכִילָה פָּטוּר. וְאִם תָּפְחָה קֹדֶם הַנָּחָה וְנַעֲשֵׂית כִּגְרוֹגֶרֶת קֹדֶם שֶׁיִּמָּלֵךְ עָלֶיהָ לַאֲכִילָה חַיָּב. שֶׁאֲפִלּוּ לֹא חִשֵּׁב הָיָה מִתְחַיֵּב עַל מַחְשֶׁבֶת הַהוֹצָאָה:","הוֹצִיא כִּגְרוֹגֶרֶת לַאֲכִילָה וְצָמְקָה וְחָזְרָה וְתָפְחָה קֹדֶם הַנָּחָה הֲרֵי זֶה סָפֵק אִם נִדְחָה אוֹ לֹא נִדְחָה. זָרַק כְּזַיִת אֳכָלִין לְבַיִת טָמֵא וְהִשְׁלִים כְּזַיִת זֶה לָאֳכָלִים שֶׁהָיוּ שָׁם וְנַעֲשָׂה הַכּל כְּבֵיצָה הֲרֵי זֶה סָפֵק אִם נִתְחַיֵּב עַל כְּזַיִת מִפְּנֵי שֶׁהִשְׁלִים הַשִּׁעוּר לְעִנְיַן טֻמְאָה אוֹ לֹא נִתְחַיֵּב:","הַמּוֹצִיא פָּחוֹת מִכַּשִּׁעוּר אַף עַל פִּי שֶׁהוֹצִיאוֹ בִּכְלִי פָּטוּר. שֶׁהַכְּלִי טְפֵלָה לוֹ וְאֵין כַּוָּנָתוֹ לְהוֹצָאַת הַכְּלִי אֶלָּא לְהוֹצָאַת מַה שֶּׁבְּתוֹכוֹ וַהֲרֵי אֵין בּוֹ כַּשִּׁעוּר. לְפִיכָךְ אִם הוֹצִיא אָדָם חַי שֶׁאֵינוֹ כָּפוּת בְּמִטָּה פָּטוּר אַף עַל הַמִּטָּה שֶׁהַמִּטָּה טְפֵלָה לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הַמּוֹצִיא קֻפַּת הָרוֹכְלִים אַף עַל פִּי שֶׁיֵּשׁ בָּהּ מִינִין הַרְבֵּה וַאֲפִלּוּ הוֹצִיאָן בְּתוֹךְ כַּפּוֹ אֵינוֹ חַיָּב אֶלָּא אַחַת. שֵׁם הוֹצָאָה אַחַת הִיא:"],"Mishneh Torah, Sabbath 29":["מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לְקַדֵּשׁ אֶת יוֹם הַשַּׁבָּת בִּדְבָרִים שֶׁנֶּאֱמַר (שמות כ ח) \"זָכוֹר אֶת יוֹם הַשַּׁבָּת לְקַדְּשׁוֹ\". כְּלוֹמַר זָכְרֵהוּ זְכִירַת שֶׁבַח וְקִדּוּשׁ. וְצָרִיךְ לְזָכְרֵהוּ בִּכְנִיסָתוֹ וּבִיצִיאָתוֹ. בִּכְנִיסָתוֹ בְּקִדּוּשׁ הַיּוֹם וּבִיצִיאָתוֹ בְּהַבְדָּלָה:","וְזֶה הוּא נֹסַח קִדּוּשׁ הַיּוֹם. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְרָצָה בָנוּ וְשַׁבַּת קָדְשׁוֹ בְּאַהֲבָה וְרָצוֹן הִנְחִילָנוּ זִכָּרוֹן לְמַעֲשֵׂה בְרֵאשִׁית תְּחִלָּה לְמִקְרָאֵי קֹדֶשׁ זֵכֶר לִיצִיאַת מִצְרָיִם כִּי בָנוּ בָחַרְתָּ וְאוֹתָנוּ קִדַּשְׁתָּ מִכָּל הָעַמִּים וְשַׁבַּת קָדְשְׁךָ בְּאַהֲבָה וּבְרָצוֹן הִנְחַלְתָּנוּ בָּרוּךְ אַתָּה ה' מְקַדֵּשׁ הַשַּׁבָּת:","וְזֶה הוּא נֹסַח הַהַבְדָּלָה. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחל וּבֵין אוֹר לְחשֶׁךְ בֵּין יִשְׂרָאֵל לָעַמִּים וּבֵין יוֹם הַשְּׁבִיעִי לְשֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה בָּרוּךְ אַתָּה ה' הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחל:","עִקַּר הַקִּדּוּשׁ בַּלַּיְלָה. אִם לֹא קִדֵּשׁ בַּלַּיְלָה בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד מְקַדֵּשׁ וְהוֹלֵךְ כָּל הַיּוֹם כֻּלּוֹ. וְאִם לֹא הִבְדִּיל בַּלַּיְלָה מַבְדִּיל לְמָחָר וּמַבְדִּיל וְהוֹלֵךְ עַד סוֹף יוֹם שְׁלִישִׁי. אֲבָל אֵינוֹ מְבָרֵךְ עַל הָאוּר אֶלָּא בְּלֵיל מוֹצָאֵי שַׁבָּת בִּלְבַד:","אָסוּר לְאָדָם לֶאֱכל אוֹ לִשְׁתּוֹת יַיִן מִשֶּׁקָּדַשׁ הַיּוֹם עַד שֶׁיְּקַדֵּשׁ. וְכֵן מִשֶּׁיָּצָא הַיּוֹם אָסוּר לוֹ לְהַתְחִיל לֶאֱכל וְלִשְׁתּוֹת וְלַעֲשׂוֹת מְלָאכָה אוֹ לִטְעֹם כְּלוּם עַד שֶׁיַּבְדִּיל. וְלִשְׁתּוֹת מַיִם מֻתָּר. שָׁכַח אוֹ עָבַר וְאָכַל וְשָׁתָה קֹדֶם שֶׁיְּקַדֵּשׁ אוֹ קֹדֶם שֶׁיַּבְדִּיל הֲרֵי זֶה מְקַדֵּשׁ וּמַבְדִּיל אַחַר שֶׁאָכַל:","מִדִּבְרֵי סוֹפְרִים לְקַדֵּשׁ עַל הַיַּיִן וּלְהַבְדִּיל עַל הַיַּיִן. וְאַף עַל פִּי שֶׁהִבְדִּיל בַּתְּפִלָּה צָרִיךְ לְהַבְדִּיל עַל הַכּוֹס. וּמֵאַחַר שֶׁיַּבְדִּיל וְיֹאמַר בֵּין קֹדֶשׁ לְחל מֻתָּר לוֹ לַעֲשׂוֹת מְלָאכָה אַף עַל פִּי שֶׁלֹּא הִבְדִּיל עַל הַכּוֹס. וּמְבָרֵךְ עַל הַיַּיִן תְּחִלָּה וְאַחַר כָּךְ מְקַדֵּשׁ. וְאֵינוֹ נוֹטֵל אֶת יָדָיו עַד שֶׁיְּקַדֵּשׁ:","כֵּיצַד הוּא עוֹשֶׂה. לוֹקֵחַ כּוֹס שֶׁהוּא מַחֲזִיק רְבִיעִית אוֹ יֶתֶר וּמְדִיחוֹ מִבִּפְנִים וְשׁוֹטְפוֹ מִבַּחוּץ וּמְמַלְּאֵהוּ יַיִן וְאוֹחֲזוֹ בִּימִינוֹ וּמַגְבִּיהוֹ מִן הַקַּרְקַע טֶפַח אוֹ יֶתֶר וְלֹא יְסַיֵּעַ בִּשְׂמֹאל. וּמְבָרֵךְ עַל הַגֶּפֶן וְאַחַר כָּךְ מְקַדֵּשׁ. וּמִנְהָג פָּשׁוּט בְּכָל יִשְׂרָאֵל לִקְרוֹת בַּתְּחִלָּה פָּרָשַׁת (בראשית ב א) \"וַיְכֻלּוּ\" וְאַחַר כָּךְ מְבָרֵךְ עַל הַיַּיִן וְאַחַר כָּךְ מְקַדֵּשׁ וְשׁוֹתֶה מְלֹא לֻגְמָיו וּמַשְׁקֶה לְכָל בְּנֵי חֲבוּרָה וְאַחַר כָּךְ נוֹטֵל יָדָיו וּמְבָרֵךְ הַמּוֹצִיא וְאוֹכֵל:","אֵין קִדּוּשׁ אֶלָּא בִּמְקוֹם סְעֻדָּה. כֵּיצַד. לֹא יְקַדֵּשׁ בְּבַיִת זֶה וְיֹאכַל בְּבַיִת אַחֵר. אֲבָל אִם קִדֵּשׁ בְּזָוִית זוֹ אוֹכֵל בְּזָוִית שְׁנִיָּה. וְלָמָּה מְקַדְּשִׁין בְּבֵית הַכְּנֶסֶת מִפְּנֵי הָאוֹרְחִין שֶׁאוֹכְלִין וְשׁוֹתִין שָׁם:","הָיָה מִתְאַוֶּה לַפַּת יוֹתֵר מִן הַיַּיִן אוֹ שֶׁלֹּא הָיָה לוֹ יַיִן הֲרֵי זֶה נוֹטֵל יָדָיו תְּחִלָּה וּמְבָרֵךְ הַמּוֹצִיא וּמְקַדֵּשׁ וְאַחַר כָּךְ בּוֹצֵעַ וְאוֹכֵל. וְאֵין מַבְדִּילִין עַל הַפַּת אֶלָּא עַל הַכּוֹס:","מִי שֶׁנִּתְכַּוֵּן לְקַדֵּשׁ עַל הַיַּיִן בְּלֵילֵי שַׁבָּת וְשָׁכַח וְנָטַל יָדָיו קֹדֶם שֶׁיְּקַדֵּשׁ הֲרֵי זֶה מְקַדֵּשׁ עַל הַפַּת וְאֵינוֹ מְקַדֵּשׁ עַל הַיַּיִן אַחַר שֶׁנָּטַל יָדָיו לַסְּעֻדָּה. וּמִצְוָה לְבָרֵךְ עַל הַיַּיִן בְּיוֹם הַשַּׁבָּת קֹדֶם שֶׁיִּסְעֹד סְעֻדָּה שְׁנִיָּה. וְזֶה הוּא הַנִּקְרָא קִדּוּשָׁא רַבָּה. מְבָרֵךְ בּוֹרֵא פְּרִי הַגָּפֶן בִּלְבַד וְשׁוֹתֶה וְאַחַר כָּךְ יִטּל יָדָיו וְיִסְעֹד. וְאָסוּר לוֹ לְאָדָם שֶׁיִּטְעֹם כְּלוּם קֹדֶם שֶׁיְּקַדֵּשׁ. וְגַם קִדּוּשׁ זֶה לֹא יִהְיֶה אֶלָּא בִּמְקוֹם סְעֻדָּה:","יֵשׁ לוֹ לְאָדָם לְקַדֵּשׁ עַל הַכּוֹס עֶרֶב שַׁבָּת מִבְּעוֹד יוֹם אַף עַל פִּי שֶׁלֹּא נִכְנְסָה הַשַּׁבָּת. וְכֵן מַבְדִּיל עַל הַכּוֹס מִבְּעוֹד יוֹם אַף עַל פִּי שֶׁעֲדַיִן הִיא שַׁבָּת. שֶׁמִּצְוַת זְכִירָה לְאָמְרָהּ בֵּין בִּשְׁעַת כְּנִיסָתוֹ וִיצִיאָתוֹ בֵּין קֹדֶם לְשָׁעָה זוֹ כִּמְעַט:","מִי שֶׁהָיָה אוֹכֵל בְּעֶרֶב שַׁבָּת וְקָדַשׁ עָלָיו הַיּוֹם וְהוּא בְּתוֹךְ הַסְּעֻדָּה פּוֹרֵס מַפָּה עַל הַשֻּׁלְחָן וּמְקַדֵּשׁ וְגוֹמֵר סְעֻדָּתוֹ וְאַחַר כָּךְ מְבָרֵךְ בִּרְכַּת הַמָּזוֹן. הָיָה אוֹכֵל בְּשַׁבָּת וְיָצָא הַשַּׁבָּת וְהוּא בְּתוֹךְ סְעֻדָּתוֹ גּוֹמֵר סְעֻדָּתוֹ וְנוֹטֵל יָדָיו וּמְבָרֵךְ בִּרְכַּת הַמָּזוֹן עַל הַכּוֹס וְאַחַר כָּךְ מַבְדִּיל עָלָיו. וְאִם הָיָה בְּתוֹךְ הַשְּׁתִיָּה פּוֹסֵק וּמַבְדִּיל וְאַחַר כָּךְ חוֹזֵר לִשְׁתִיָּתוֹ:","הָיָה אוֹכֵל וְגָמַר אֲכִילָתוֹ עִם הַכְנָסַת שַׁבָּת מְבָרֵךְ בִּרְכַּת הַמָּזוֹן תְּחִלָּה וְאַחַר כָּךְ מְקַדֵּשׁ עַל כּוֹס שֵׁנִי. וְלֹא יְבָרֵךְ וַיְקַדֵּשׁ עַל כּוֹס אֶחָד שֶׁאֵין עוֹשִׂין שְׁתֵּי מִצְוֹת בְּכוֹס אֶחָד. שֶׁמִּצְוַת קִדּוּשׁ וּמִצְוַת בִּרְכַּת הַמָּזוֹן שְׁתֵּי מִצְוֹת שֶׁל תּוֹרָה הֵן:","אֵין מְקַדְּשִׁין אֶלָּא עַל הַיַּיִן הָרָאוּי לְנַסֵּךְ עַל גַּבֵּי הַמִּזְבֵּחַ. לְפִיכָךְ אִם נִתְעָרֵב בּוֹ דְּבַשׁ אוֹ שְׂאוֹר אֲפִלּוּ כְּטִפַּת הַחַרְדָּל בְּחָבִית גְּדוֹלָה אֵין מְקַדְּשִׁין עָלָיו. כָּךְ אָנוּ מוֹרִין בְּכָל הַמַּעֲרָב. וְיֵשׁ מִי שֶׁמַּתִּיר לְקַדֵּשׁ עָלָיו וְאוֹמֵר לֹא נֶאֱמַר הַיַּיִן הָרָאוּי לְנַסֵּךְ עַל גַּבֵּי הַמִּזְבֵּחַ אֶלָּא לְהוֹצִיא יַיִן שֶׁרֵיחוֹ רַע אוֹ מְגֻלֶּה אוֹ מְבֻשָּׁל שֶׁאֵין מְקַדְּשִׁין עַל אֶחָד מֵהֶן:","יַיִן שֶׁטַּעֲמוֹ טַעַם חֹמֶץ אַף עַל פִּי שֶׁרֵיחוֹ רֵיחַ יַיִן אֵין מְקַדְּשִׁין עָלָיו. וְכֵן שְׁמָרִים שֶׁנָּתַן עֲלֵיהֶן מַיִם אַף עַל פִּי שֶׁיֵּשׁ בָּהֶן טַעַם יַיִן אֵין מְקַדְּשִׁין עֲלֵיהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנָּתַן עַל הַשְּׁמָרִים שְׁלֹשָׁה מַיִם וְהוֹצִיא פָּחוֹת מֵאַרְבָּעָה. אֲבָל אִם הוֹצִיא אַרְבָּעָה הֲרֵי זֶה יַיִן מָזוּג וּמְקַדְּשִׁין עָלָיו:","כְּלִי שֶׁהָיָה מָלֵא יַיִן אֲפִלּוּ מַחֲזִיק כַּמָּה רְבִיעִיּוֹת אִם שָׁתָה מִמֶּנּוּ מְעַט הֲרֵי זֶה פְּגָמוֹ וְנִפְסַל וְאֵין מְקַדְּשִׁין עַל הַשְּׁאָר מִפְּנֵי שֶׁהוּא כְּשִׁיּוּרֵי כּוֹסוֹת:","יַיִן שֶׁרֵיחוֹ רֵיחַ הַחֹמֶץ וְטַעֲמוֹ טַעַם יַיִן מְקַדְּשִׁין עָלָיו. וְכֵן יַיִן מָזוּג. וְכֵן יֵין צִמּוּקִים מְקַדְּשִׁין עָלָיו וְהוּא שֶׁיִּהְיוּ צִמּוּקִים שֶׁיֵּשׁ בָּהֶן לַחְלוּחִית שֶׁאִם יִדְרֹךְ אוֹתָן יֵצֵא מֵהֶן דִּבְשָׁן. וְכֵן יַיִן חָדָשׁ מִגִּתּוֹ מְקַדְּשִׁין עָלָיו. וְסוֹחֵט אָדָם אֶשְׁכּוֹל שֶׁל עֲנָבִים וּמְקַדֵּשׁ עָלָיו בִּשְׁעָתוֹ. מְדִינָה שֶׁרֹב יֵינָהּ שֵׁכָר אַף עַל פִּי שֶׁהוּא פָּסוּל לְקִדּוּשׁ מֻתָּר לְהַבְדִּיל עָלָיו הוֹאִיל וְהוּא חֲמַר הַמְּדִינָה:","כְּשֵׁם שֶׁמְּקַדְּשִׁין בְּלֵילֵי שַׁבָּת וּמַבְדִּילִין בְּמוֹצָאֵי שַׁבָּת כָּךְ מְקַדְּשִׁין בְּלֵילֵי יָמִים טוֹבִים וּמַבְדִּילִין בְּמוֹצָאֵיהֶן וּבְמוֹצָאֵי יוֹם הַכִּפּוּרִים שֶׁכֻּלָּם שַׁבְּתוֹת ה' הֵן. וּמַבְדִּילִין בְּמוֹצָאֵי יָמִים טוֹבִים לְחֻלּוֹ שֶׁל מוֹעֵד וּבְמוֹצָאֵי שַׁבָּת לְיוֹם טוֹב. אֲבָל אֵין מַבְדִּילִים בְּמוֹצָאֵי יוֹם טוֹב לְשַׁבָּת:","נֹסַח קִדּוּשׁ יוֹם טוֹב. בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר בָּחַר בָּנוּ מִכָּל עָם וְרוֹמְמָנוּ מִכָּל לָשׁוֹן בָּחַר בָּנוּ וַיְּגַדְּלֵנוּ רָצָה בָּנוּ וַיְּפָאֲרֵנוּ. וַתִּתֵּן לָנוּ ה' אֱלֹהֵינוּ בְּאַהֲבָה מוֹעֲדִים לְשִׂמְחָה חַגִּים וּזְמַנִּים לְשָׂשׂוֹן אֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה אֶת יוֹם חַג הַמַּצּוֹת הַזֶּה אוֹ חַג הַשָּׁבוּעוֹת אוֹ חַג הַסֻּכּוֹת זְמַן חֵרוּתֵנוּ אוֹ זְמַן מַתַּן תּוֹרָתֵנוּ אוֹ זְמַן שִׂמְחָתֵנוּ בְּאַהֲבָה זֵכֶר לִיצִיאַת מִצְרָיִם כִּי בָנוּ בָחַרְתָּ וְאוֹתָנוּ קִדַּשְׁתָּ מִכָּל הָעַמִּים וּמוֹעֲדֵי קָדְשֶׁךָ בְּשִׂמְחָה וּבְשָׂשׂוֹן הִנְחַלְתָּנוּ בָּרוּךְ אַתָּה ה' מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים. וְאִם חָל לִהְיוֹת בְּשַׁבָּת מַזְכִּיר שַׁבָּת וְחוֹתֵם כְּדֶרֶךְ שֶׁחוֹתֵם בַּתְּפִלָּה מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְהַזְּמַנִּים:","בְּרֹאשׁ הַשָּׁנָה אוֹמֵר. וַתִּתֵּן לָנוּ ה' אֱלֹהֵינוּ בְּאַהֲבָה אֶת יוֹם טוֹב מִקְרָא קֹדֶשׁ הַזֶּה זִכְרוֹן תְּרוּעָה מִקְרָא קֹדֶשׁ בְּאַהֲבָה זֵכֶר לִיצִיאַת מִצְרָיִם כִּי בָנוּ בָחַרְתָּ וְאוֹתָנוּ קִדַּשְׁתָּ מִכָּל הָעַמִּים וּדְבָרְךָ אֱמֶת וְקַיָּם לָעַד בָּרוּךְ אַתָּה ה' מֶלֶךְ עַל כָּל הָאָרֶץ מְקַדֵּשׁ יִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן. וְאִם חָל לִהְיוֹת בְּשַׁבָּת חוֹתֵם מְקַדֵּשׁ הַשַּׁבָּת וְיִשְׂרָאֵל וְיוֹם הַזִּכָּרוֹן כְּדֶרֶךְ שֶׁחוֹתֵם בַּתְּפִלָּה:","בְּלֵילֵי יוֹם טוֹב מְקַדֵּשׁ עַל הַיַּיִן כִּבְשַׁבָּת. וְאִם אֵין לוֹ יַיִן אוֹ שֶׁהָיָה מִתְאַוֶּה לְפַת מְקַדֵּשׁ עַל הַפַּת. וְכֵן בְּיוֹם טוֹב מְקַדֵּשׁ קִדּוּשָׁא רַבָּא כְּדֶרֶךְ שֶׁמְּקַדֵּשׁ בְּשַׁבָּת:","כֵּיצַד מְבָרְכִין בְּלֵילֵי יוֹם טוֹב שֶׁחָל לִהְיוֹת בְּאֶחָד בְּשַׁבָּת. בַּתְּחִלָּה מְבָרֵךְ עַל הַגֶּפֶן. וְאַחַר כָּךְ מְקַדֵּשׁ קִדּוּשׁ יוֹם טוֹב. וְאַחַר כָּךְ מְבָרֵךְ עַל הַנֵּר. וְאַחַר כָּךְ מַבְדִּיל וְחוֹתֵם בְּהַבְדָּלָה הַמַּבְדִּיל בֵּין קֹדֶשׁ לְקֹדֶשׁ. וְאַחַר כָּךְ מְבָרֵךְ שֶׁהֶחֱיָנוּ:","כָּל לֵילֵי יוֹם טוֹב וּבְלֵיל יוֹם הַכִּפּוּרִים אוֹמְרִים שֶׁהֶחֱיָנוּ. וּבִשְׁבִיעִי שֶׁל פֶּסַח אֵין מְבָרְכִין שֶׁהֶחֱיָנוּ מִפְּנֵי שֶׁאֵינוֹ רֶגֶל בִּפְנֵי עַצְמוֹ וּכְבָר בֵּרֵךְ עַל הַזְּמַן בִּתְחִלַּת הַפֶּסַח:","סֵדֶר הַבְדָּלָה בְּמוֹצָאֵי שַׁבָּת. מְבָרֵךְ עַל הַיַּיִן וְאַחַר כָּךְ עַל הַבְּשָׂמִים וְאַחַר כָּךְ עַל הַנֵּר. וְכֵיצַד מְבָרֵךְ עַל הַנֵּר, בּוֹרֵא מְאוֹרֵי הָאֵשׁ. וְאַחַר כָּךְ מַבְדִּיל:","אֵין מְבָרְכִין עַל הַנֵּר עַד שֶׁיֵּאוֹתוּ לְאוֹרוֹ כְּדֵי שֶׁיַּכִּיר בֵּין מַטְבֵּעַ מְדִינָה זוֹ לְמַטְבֵּעַ מְדִינָה אַחֶרֶת. וְאֵין מְבָרְכִין עַל הַנֵּר שֶׁל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁסְּתַם מְסִבָּתָן לַעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וְאֵין מְבָרְכִין לֹא עַל הַנֵּר שֶׁל עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת וְלֹא עַל הַנֵּר שֶׁל מֵתִים:","יִשְׂרָאֵל שֶׁהִדְלִיק מֵעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת אוֹ עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת מִיִּשְׂרָאֵל מְבָרְכִין עָלָיו. עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת מֵעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֵין מְבָרְכִין עָלָיו. הָיָה מְהַלֵּךְ חוּץ לַכְּרַךְ וְרָאָה אוֹר אִם רֹב אַנְשֵׁי הַכְּרַךְ עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת אֵינוֹ מְבָרֵךְ וְאִם רֹב יִשְׂרָאֵל מְבָרֵךְ. אוּר שֶׁל כִּבְשָׁן שֶׁל תַּנּוּר וְשֶׁל כִּירַיִם לְכַתְּחִלָּה לֹא יְבָרֵךְ עָלָיו. הַגֶּחָלִים אִם כְּשֶׁיַּכְנִיס קֵיסָם בֵּינֵיהֶן דּוֹלֵק מֵאֵלָיו מְבָרְכִין עֲלֵיהֶן. אוּר שֶׁל בֵּית הַמִּדְרָשׁ אִם יֵשׁ שָׁם אָדָם חָשׁוּב שֶׁמַּדְלִיקִים בִּשְׁבִילוֹ מְבָרְכִין עָלָיו. שֶׁל בֵּית הַכְּנֶסֶת אִם יֵשׁ שָׁם חַזָּן שֶׁהוּא דָּר שָׁם מְבָרְכִין עָלָיו. וַאֲבוּקָה לְהַבְדָּלָה מִצְוָה מִן הַמֻּבְחָר. וְאֵין מְחַזְּרִין עַל הָאוּר כְּדֶרֶךְ שֶׁמְּחַזְּרִין עַל כָּל הַמִּצְוֹת אֶלָּא אִם יֵשׁ לוֹ מְבָרְכִין עָלָיו:","אוּר שֶׁהֻדְלַק בְּשַׁבָּת לְחוֹלֶה וּלְחַיָּה מְבָרְכִין עָלָיו בְּמוֹצָאֵי שַׁבָּת. אוּר שֶׁהֻקְדַּח מִן הָעֵצִים וּמִן הָאֲבָנִים מְבָרְכִין עָלָיו בְּמוֹצָאֵי שַׁבָּת שֶׁהִיא הָיְתָה תְּחִלַּת בְּרִיָּתוֹ בִּידֵי אָדָם. אֲבָל אֵין מְבָרְכִין עָלָיו בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים שֶׁאֵין מְבָרְכִין בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים אֶלָּא עַל אוּר שֶׁשָּׁבַת. אַף עַל פִּי שֶׁהֻדְלַק לְחוֹלֶה אוֹ לְחַיָּה בְּיוֹם הַכִּפּוּרִים מְבָרְכִין עָלָיו שֶׁהֲרֵי שָׁבַת מֵעֲבֵרָה:","יוֹם טוֹב שֶׁחָל לִהְיוֹת בְּאֶמְצַע שַׁבָּת אוֹמֵר בְּהַבְדָּלָה הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחל וּבֵין אוֹר לְחשֶׁךְ וּבֵין יִשְׂרָאֵל לָעַמִּים וּבֵין יוֹם הַשְּׁבִיעִי לְשֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה כְּדֶרֶךְ שֶׁאוֹמֵר בְּמוֹצָאֵי שַׁבָּת שֶׁסֵּדֶר הַהַבְדָּלוֹת הוּא מוֹנֶה. וְאֵינוֹ צָרִיךְ לְבָרֵךְ לֹא עַל הַבְּשָׂמִים וְלֹא עַל הַנֵּר. וְכֵן אֵינוֹ צָרִיךְ לְבָרֵךְ עַל הַבְּשָׂמִים בְּמוֹצָאֵי יוֹם הַכִּפּוּרִים:","וְלָמָּה מְבָרְכִים עַל הַבְּשָׂמִים בְּמוֹצָאֵי שַׁבָּת מִפְּנֵי שֶׁהַנֶּפֶשׁ דּוֹאֶבֶת לִיצִיאַת שַׁבָּת מְשַׂמְּחִין אוֹתָהּ וּמְיַשְּׁבִין אוֹתָהּ בְּרֵיחַ טוֹב:"],"Mishneh Torah, Sabbatical Year and the Jubilee 12":["הַמּוֹכֵר בַּיִת בְּתוֹךְ עִיר הַמֵּקֶּפֶת חוֹמָה הֲרֵי זֶה גּוֹאֲלָהּ כָּל י\"ב חֹדֶשׁ מִיּוֹם שֶׁמָּכַר בְּכָל עֵת שֶׁיִּרְצֶה. וַאֲפִלּוּ בַּיּוֹם שֶׁמָּכַר. וּכְשֶׁרוֹצֶה לִפְדּוֹת נוֹתֵן כָּל הַדָּמִים שֶׁלָּקַח וְאֵינוֹ גּוֹרֵעַ לַלּוֹקֵחַ כְּלוּם:","וְאֵין הַקְּרוֹבִים פּוֹדִין אוֹתָהּ אֶלָּא הַמּוֹכֵר עַצְמוֹ אִם הִשִּׂיגָה יָדוֹ. וְיֵשׁ לוֹ לִמְכֹּר מִנְּכָסָיו וְלִפְדּוֹתוֹ. אֲבָל לֹא יַלְוֶה וְיִגְאַל. וְלֹא יִגְאַל לַחֲצָאִין:","מֵת הַלּוֹקֵחַ יִפְדֶּה מִיַּד בְּנוֹ. וְכֵן אִם מֵת הַמּוֹכֵר יֵשׁ לִבְנוֹ לִפְדּוֹתָהּ כָּל י\"ב חֹדֶשׁ:","מָכַר לָרִאשׁוֹן וְרִאשׁוֹן לַשֵּׁנִי בְּתוֹךְ הַשָּׁנָה מוֹנִין לָרִאשׁוֹן. כֵּיוָן שֶׁשָּׁלְמָה שָׁנָה רִאשׁוֹנָה הֻחְלַט הַבַּיִת בְּיַד הַשֵּׁנִי. שֶׁהַמּוֹכֵר מָכַר לַשֵּׁנִי כָּל זְכוּת שֶׁתָּבוֹא לְיָדוֹ. הִגִּיעַ י\"ב חֹדֶשׁ וְלֹא גְּאָלָהּ הֲרֵי זוֹ נֶחְלֶטֶת בְּיַד הַלּוֹקֵחַ. וְכֵן אִם נָתַן הַבַּיִת מַתָּנָה וְלֹא גְּאָלוֹ כָּל י\"ב חֹדֶשׁ הֲרֵי זֶה נֶחְלָט בְּיַד זֶה שֶׁנָּתַן לוֹ מַתָּנָה:","הָיְתָה שָׁנָה מְעֻבֶּרֶת אֵינוֹ נֶחְלָט עַד סוֹפָהּ שֶׁנֶּאֱמַר (ויקרא כה ל) \"עַד מְלֹאת לוֹ שָׁנָה תְמִימָה\" לְהָבִיא חֹדֶשׁ הָעִבּוּר:","מָכַר שְׁנֵי בָּתִּים אֶחָד בַּחֲצִי אֲדָר רִאשׁוֹן וְאֶחָד בְּרֹאשׁ אֲדָר שֵׁנִי. זֶה שֶׁמָּכַר בְּרֹאשׁ אֲדָר שֵׁנִי כֵּיוָן שֶׁהִגִּיעַ אֶחָד בַּאֲדָר שֶׁל שָׁנָה הַבָּאָה עָלְתָה לוֹ שָׁנָה. וְזֶה שֶׁמָּכַר בַּחֲצִי אֲדָר רִאשׁוֹן לֹא עָלְתָה לוֹ שָׁנָה עַד חֲצִי אֲדָר שֶׁל שָׁנָה הַבָּאָה מִפְּנֵי שֶׁיָּרַד הַלּוֹקֵחַ בְּחֹדֶשׁ הָעִבּוּר:","הִגִּיעַ יוֹם י\"ב חֹדֶשׁ וְלֹא נִמְצָא הַלּוֹקֵחַ לִפְדּוֹת מִמֶּנּוּ הֲרֵי זֶה מַנִּיחַ מְעוֹתָיו בְּבֵית דִּין וְשׁוֹבֵר אֶת הַדֶּלֶת וְנִכְנָס לְבֵיתוֹ. וְאֵימָתַי שֶׁיָּבוֹא הַלּוֹקֵחַ יָבוֹא וְיִטּל מְעוֹתָיו:","הַמַּקְדִּישׁ בֵּית עִיר חוֹמָה וּגְאָלוֹ אַחֵר מִיַּד הַהֶקְדֵּשׁ כֵּיוָן שֶׁעָלְתָה לוֹ שָׁנָה מִשָּׁעָה שֶׁנִּגְאַל מִיַּד הַהֶקְדֵּשׁ וְלֹא גְּאָלוֹ בְּעָלָיו נֶחְלַט בְּיַד הַגּוֹאֵל. שֶׁאֵין הַהֶקְדֵּשׁ חוֹלֵט אֶלָּא הַלּוֹקֵחַ שֶׁנֶּאֱמַר (ויקרא כה ל) \"לַקּוֹנֶה אוֹתוֹ לְדוֹרוֹתָיו\":","מָכַר בֵּית עִיר חוֹמָה וְהִגִּיעַ יוֹבֵל בְּתוֹךְ שְׁנַת הַמֶּכֶר אֵינוֹ חוֹזֵר בְּיוֹבֵל. אֶלָּא יִהְיֶה בְּיַד הַלּוֹקֵחַ עַד שֶׁיִּרְצֶה הַמּוֹכֵר לִגְאל כָּל שְׁנַת הַמֶּכֶר אוֹ תִּמָּלֵא שָׁנָה וְיַחְלֹט:","הַמּוֹכֵר בַּיִת בְּבָתֵּי חֲצֵרִים אוֹ בְּעִיר שֶׁאֵינָהּ מֻקֶּפֶת חוֹמָה כָּרָאוּי הֲרֵי זֶה נִגְאָל בְּכֹחַ יָפֶה שֶׁבְּדִין הַשָּׂדֶה וְשֶׁבְּדִין הַבָּתִּים הַמֻּקָּפִין חוֹמָה. כֵּיצַד. אִם רָצָה לִגְאל מִיָּד גּוֹאֵל כְּדִין הַבָּתִּים. הִגִּיעַ י\"ב חֹדֶשׁ וְלֹא גָּאַל הֲרֵי זֶה גּוֹאֵל עַד שְׁנַת הַיּוֹבֵל כְּדִין הַשָּׂדוֹת. וּבְעֵת שֶׁגּוֹאֵל מְחַשֵּׁב עִם הַמּוֹכֵר וְגוֹרֵעַ לוֹ מַה שֶּׁאָכַל. הִגִּיעַ יוֹבֵל וְלֹא גָּאַל חוֹזֵר הַבַּיִת בְּלֹא דָּמִים כְּדִין הַשָּׂדוֹת:","כָּל שֶׁהוּא לְפָנִים מִן הַחוֹמָה כְּגוֹן הַגִּנּוֹת וְהַמֶּרְחֲצָאוֹת וְהַשּׁוֹבָכוֹת הֲרֵי הוּא כְּבָתִּים שֶׁנֶּאֱמַר (ויקרא כה ל) \"אֲשֶׁר בָּעִיר\". אֲבָל הַשָּׂדוֹת שֶׁבְּתוֹךְ הָעִיר נִגְאָלִין כְּדִין הַשָּׂדוֹת שֶׁחוּץ לָעִיר שֶׁנֶּאֱמַר (ויקרא כה ל) \"וְקָם הַבַּיִת אֲשֶׁר בָּעִיר\". בַּיִת וְכָל הַדּוֹמֶה לְבַיִת לֹא הַשָּׂדוֹת:","בַּיִת שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אֵינוֹ נֶחְלָט כְּבָתֵי עָרֵי חוֹמָה. וִירוּשָׁלַיִם אֵין הַבַּיִת נֶחְלָט בָּהּ. וּבַיִת הַבָּנוּי בַּחוֹמָה אֵינוֹ כְּבָתֵּי עָרֵי חוֹמָה:","עִיר שֶׁגַּגּוֹתֶיהָ חוֹמָתָהּ אוֹ שֶׁהַיָּם חוֹמָתָהּ אֵינָהּ כְּמֻקֶּפֶת חוֹמָה:","אֵין הַמָּקוֹם נִקְרָא עָרֵי חוֹמָה עַד שֶׁיִּהְיֶה בּוֹ שָׁלֹשׁ חֲצֵרוֹת אוֹ יֶתֶר וּבְכָל חָצֵר מֵהֶן שְׁנֵי בָּתִּים אוֹ יֶתֶר וְיַקִּיפוּהָ חוֹמָה תְּחִלָּה וְאַחַר כָּךְ יִבְנוּ הַחֲצֵרוֹת בְּתוֹכוֹ. אֲבָל מָקוֹם שֶׁיָּשַׁב וְאַחַר כָּךְ הֻקַּף אוֹ שֶׁלֹּא הָיוּ בּוֹ שָׁלֹשׁ חֲצֵרוֹת שֶׁל שְׁנֵי בָּתִּים אֵינוֹ (ויקרא כה כט) \"עִיר חוֹמָה\" אֶלָּא בָּתִּים שֶׁבּוֹ כְּבָתֵּי הַחֲצֵרִים:","אֵין סוֹמְכִין אֶלָּא עַל חוֹמָה הַמֻּקֶּפֶת בִּשְׁעַת כִּבּוּשׁ הָאָרֶץ. כֵּיצַד. עִיר שֶׁלֹּא הָיְתָה מֻקֶּפֶת חוֹמָה בְּשָׁעָה שֶׁכָּבַשׁ יְהוֹשֻׁעַ אֶת הָאָרֶץ אַף עַל פִּי שֶׁמֻּקֶּפֶת עַתָּה הֲרֵי הִיא כְּבָתֵּי הַחֲצֵרִים. וְעִיר שֶׁהָיְתָה מֻקֶּפֶת חוֹמָה בִּימֵי יְהוֹשֻׁעַ אַף עַל פִּי שֶׁאֵינָהּ מֻקֶּפֶת עַתָּה הֲרֵי הִיא כְּמֻקֶּפֶת. וְכֵיוָן שֶׁגָּלוּ בְּחֻרְבָּן רִאשׁוֹן בָּטְלָה קְדֻשַּׁת עָרֵי חוֹמָה שֶׁהָיוּ בִּימֵי יְהוֹשֻׁעַ. כֵּיוָן שֶׁעָלָה עֶזְרָא בַּבִּיאָה הַשְּׁנִיָּה נִתְקַדְּשׁוּ כָּל הֶעָרִים הַמֻּקָּפוֹת חוֹמָה בְּאוֹתוֹ הָעֵת מִפְּנֵי שֶׁבִּיאָתָן בִּימֵי עֶזְרָא שֶׁהִיא בִּיאָה שְׁנִיָּה כְּבִיאָתָן בִּימֵי יְהוֹשֻׁעַ. מָה בִּיאָתָן בִּימֵי יְהוֹשֻׁעַ מָנוּ שְׁמִטִּין וְיוֹבְלוֹת וְקִדְּשׁוּ בָּתֵּי עָרֵי חוֹמָה וְנִתְחַיְּבוּ בְּמַעֲשֵׂר. אַף בִּיאָתָם בִּימֵי עֶזְרָא מָנוּ שְׁמִטִּין וְיוֹבְלוֹת וְקִדְּשׁוּ בָּתֵּי עָרֵי חוֹמָה וְנִתְחַיְּבוּ בְּמַעֲשֵׂר:","וְכֵן לֶעָתִיד לָבוֹא בְּבִיאָה שְׁלִישִׁית בְּעֵת שֶׁיִּכָּנְסוּ לָאָרֶץ יַתְחִילוּ לִמְנוֹת שְׁמִטִּין וְיוֹבְלוֹת וִיקַדְּשׁוּ בָּתֵּי עָרֵי חוֹמָה וְיִתְחַיֵּב כָּל מָקוֹם שֶׁיִּכְבְּשׁוּהוּ בְּמַעַשְׂרוֹת שֶׁנֶּאֱמַר (דברים ל ה) \"וֶהֱבִיאֲךָ ה' אֱלֹהֶיךָ אֶל הָאָרֶץ אֲשֶׁר יָרְשׁוּ אֲבֹתֶיךָ וִירִשְׁתָּהּ\". מַקִּישׁ יְרֻשָּׁתְךָ לִירֻשַּׁת אֲבוֹתֶיךָ. מָה יְרֻשַּׁת אֲבוֹתֶיךָ אַתָּה נוֹהֵג [בָּהּ] בְּחִדּוּשׁ כָּל הַדְּבָרִים הָאֵלּוּ אַף יְרֻשָּׁתְךָ אַתָּה נוֹהֵג בָּהּ בְּחִדּוּשׁ כָּל הַדְּבָרִים הָאֵלּוּ:"],"Mishneh Torah, Sacrifices Rendered Unfit 11":["כָּל הַמְּנָחוֹת שֶׁקְּמָצָן אֶחָד מִן הַפְּסוּלִין לַעֲבוֹדָה הֲרֵי הֵם פְּסוּלוֹת. וְכֵן אִם לִקֵּט הַלְּבוֹנָה פָּסַל אַף עַל פִּי שֶׁלֹּא קָמַץ:","קָמַץ הַכָּשֵׁר וְנָתַן לַפָּסוּל. קָמַץ בִּימִינוֹ וְנָתַן לִשְׂמֹאלוֹ וְאַחַר כָּךְ נְתָנוֹ לִכְלִי. קָמַץ מִכְּלִי קֹדֶשׁ וְנָתַן לִכְלִי חֹל. פָּסַל:","קָמַץ וְעָלָה בְּיָדוֹ צְרוֹר אוֹ גַּרְגִּיר מֶלַח אוֹ קֹרֶט לְבוֹנָה פָּסוּל:","קָמַץ עַד שֶׁהוּא בַּחוּץ וְנִכְנַס לְפָנִים. יַחְזֹר וְיִקְמֹץ בִּפְנִים וְכָשֵׁר:","נִתְפַּזֵּר הַקֹּמֶץ עַל גַּבֵּי הָרִצְפָּה. יַחְזֹר וְיַאַסְפֶנּוּ:","הָיְתָה הַמִּנְחָה שֶׁלֹּא בִּכְלִי שָׁרֵת. אוֹ שֶׁהָיְתָה קֻמְצָהּ שֶׁלֹּא בִּכְלִי שָׁרֵת. אוֹ שֶׁהֶעֱלָהוּ לַמִּזְבֵּחַ שֶׁלֹּא בִּכְלִי שָׁרֵת. אוֹ שֶׁבְּלָלָהּ בְּשַׁמְנָהּ חוּץ לָעֲזָרָה. פְּסוּלָה עַד שֶׁתִּהְיֶה בְּלִילָתָהּ בִּפְנִים:","כָּל הַמְּנָחוֹת שֶׁיָּצַק עֲלֵיהֶן הַשֶּׁמֶן פָּסוּל לַעֲבוֹדָה כְּגוֹן הַזָּר וְכַיּוֹצֵא בּוֹ אוֹ שֶׁבְּלָלָן אוֹ פְּתָתָם אוֹ מְלָחָן כְּשֵׁרוֹת. הִגִּישָׁן אוֹ הֱנִיפָן חוֹזֵר הַכֹּהֵן וּמַגִּישׁ אוֹ מֵנִיף. וְאִם לֹא הִגִּישׁ וְלֹא הֵנִיף הַכֹּהֵן כְּשֵׁרוֹת. שֶׁנֶּאֱמַר (ויקרא ב ב) \"וֶהֱבִיאָהּ אֶל בְּנֵי אַהֲרֹן\" (ויקרא ב ב) \"וְקָמַץ\". מִקְּמִיצָה וְאֵילָךְ מִצְוַת כְּהֻנָּה לִמֵּד עַל יְצִיקָה וּבְלִילָה שֶׁכְּשֵׁרָה בְּזָר:","מִנְחָה שֶׁנָּפַל לְתוֹכָהּ שֶׁמֶן מִנְחָה אַחֶרֶת אוֹ שֶׁמֶן חֻלִּין כָּל שֶׁהוּא נִפְסְלָה. חִסֵּר שַׁמְנָהּ פְּסוּלָה. חִסֵּר לְבוֹנָתָהּ כְּשֵׁרָה. וְהוּא שֶׁיִּהְיוּ עָלֶיהָ שֵׁנִי קוֹרְטֵי לְבוֹנָה אֲבָל קֹרֶט אֶחָד פְּסוּלָה שֶׁנֶּאֱמַר אֶת כָּל לְבוֹנָתָהּ:","רִבָּה שַׁמְנָהּ וּלְבוֹנָתָהּ עַד שְׁנֵי לוֹגִין לְכָל עִשָּׂרוֹן וּשְׁנֵי קֻמְצֵי לְבוֹנָה לְכָל מִנְחָה כְּשֵׁרָה. שְׁנֵי לוֹגִין אוֹ שְׁנֵי קְמָצִין אוֹ יֶתֶר עַל זֶה פְּסוּלָה:","מִנְחַת חוֹטֵא שֶׁנָּתַן עָלֶיהָ שֶׁמֶן אוֹ עַל הַקֹּמֶץ שֶׁלָּהּ נִפְסְלָה. נָתַן עָלֶיהָ לְבוֹנָה יִלְקְטֶנָּה. הָיְתָה שְׁחוּקָה הֲרֵי זוֹ פְּסוּלָה מִסָּפֵק. שֶׁהֲרֵי אִי אֶפְשָׁר לְלַקֵּט:","נָתַן שֶׁמֶן עַל שְׁיָרֶיהָ אַחַר שֶׁקָּמַץ. אֵינוֹ לוֹקֶה וְלֹא פְּסָלָהּ שֶׁהֲרֵי הַקֹּמֶץ כָּשֵׁר:","נָתַן מַשֶּׁהוּ שֶׁמֶן עַל גַּבֵּי כְּזַיִת מִן הַמִּנְחָה פְּסָלָהּ מִסָּפֵק. אֲבָל אִם נָתַן הַשֶּׁמֶן עַל פָּחוֹת מִכְּזַיִת לֹא פְּסָלָהּ. וְאֵינוֹ פּוֹסֵל הַלְּבוֹנָה עַד שֶׁיִּתֵּן כְּזַיִת לְבוֹנָה:","אֲפִלּוּ נָתַן הַלְּבוֹנָה עַל כָּל שֶׁהוּא מִן הַמִּנְחָה פָּסַל עַד שֶׁיְּלַקֵּט:","גִּבְּלָהּ בְּמַיִם וְקָמַץ כְּשֵׁרָה. לֹא נֶאֱמַר (ויקרא ז י) \"חֲרֵבָה\" אֶלָּא מִשֶּׁמֶן:","מִנְחָה שֶׁקְּמָצָהּ פַּעֲמַיִם כְּשֵׁרָה, אֲפִלּוּ פְּעָמִים רַבּוֹת. וְהוּא שֶׁיַּקְטִיר כְּזַיִת בְּבַת אַחַת. שֶׁאֵין הַקְטָרָה פְּחוּתָה מִכְּזַיִת:","הִקְרִיב הַקֹּמֶץ בְּלֹא מֶלַח פְּסוּלָה. שֶׁהַמֶּלַח מְעַכֵּב בַּמִּנְחָה כְּמוֹ שֶׁבֵּאַרְנוּ. מִנְחָה שֶׁחָסְרָה קֹדֶם קְמִיצָה. יָבִיא מִתּוֹךְ בֵּיתוֹ וִימַלְּאֶנָּה. שֶׁהַקְּמִיצָה הִיא הַקּוֹבַעַת לֹא נְתִינָתָהּ בִּכְלִי שָׁרֵת:","הִתְנַדֵּב קֹמֶץ לְבוֹנָה בִּפְנֵי עַצְמוֹ. אִם חָסַר כָּל שֶׁהוּא פָּסוּל. וְכֵן שְׁנֵי בְּזִיכֵי לְבוֹנָה שֶׁעִם הַלֶּחֶם אִם חָסַר אֶחָד מֵהֶן כָּל שֶׁהוּא פְּסוּלִין. עַד שֶׁיִּהְיוּ שְׁנֵי קְמָצִין מִתְּחִלָּה וְעַד סוֹף:","הִפְרִישׁ שְׁנֵי קְמָצִין לְמִנְחָה אַחַת וְאָבַד אֶחָד מֵהֶן קֹדֶם קְמִיצָה לֹא הֻקְבַּע. לְאַחַר קְמִיצָה הֻקְבַּע וּפְסוּלָה מִפְּנֵי שֶׁרִבָּה לְבוֹנָתָהּ. וְכֵן אִם הִפְרִישׁ אַרְבָּעָה קְמָצִים לִשְׁנֵי בְּזִיכֵי לֶחֶם וְאָבְדוּ שְׁנַיִם מֵהֶם קֹדֶם סִלּוּק הַבְּזִיכִים לֹא הֻקְבְּעוּ וּכְשֵׁרִים. לְאַחַר סִלּוּק הַבְּזִיכִין הֻקְבְּעוּ וּפְסוּלִין מִפְּנֵי הָרִבּוּי:","קֹמֶץ מִנְחָה שֶׁנִּטְמָא וְהִקְטִירוֹ. הַצִּיץ מְרַצֶּה שֶׁנֶּאֱמַר (שמות כח לח) \"וְנָשָׂא אַהֲרֹן\". יָצָא הַקֹּמֶץ חוּץ לָעֲזָרָה וְהִכְנִיסוֹ וְהִקְטִירוֹ אֵין הַצִּיץ מְרַצֶּה. שֶׁהַצִּיץ מְרַצֶּה עַל הַטָּמֵא וְאֵינוֹ מְרַצֶּה עַל הַיּוֹצֵא:","קָמַץ אֶת הַמִּנְחָה וְאַחַר כָּךְ נִטְמְאוּ שְׁיָרֶיהָ כֻּלָּן אוֹ נִשְׂרְפוּ אוֹ יָצְאוּ חוּץ לָעֲזָרָה אוֹ אָבְדוּ. לֹא יַקְטִיר הַקֹּמֶץ וְאִם הִקְטִיר הֻרְצָה. נִשְׁאַר מְעַט מִן הַשְּׁיָרִים בְּכַשְׁרוּתָן. יַקְטִיר הַקֹּמֶץ וְאוֹתָן הַשְּׁיָרִים שֶׁנִּשְׁאֲרוּ אֲסוּרִין בַּאֲכִילָה:","הָיְתָה מְחִצָּה מִלְּמַטָּה בִּכְלִי שֶׁיֵּשׁ בּוֹ עִשָּׂרוֹן שֶׁל מִנְחָה. אַף עַל פִּי שֶׁהוּא מְעֹרָב מִלְמַעְלָה לֹא יִקְמֹץ. וְאִם קָמַץ פְּסוּלָה:","הָיָה הַכְּלִי חָלוּק בִּמְחִצָּה מִלְמַעְלָה וּמְעֹרָב מִלְּמַטָּה. קוֹמֵץ מִמֶּנּוּ:","חָלַק הָעִשָּׂרוֹן בִּכְלִי אֶחָד וְאֵין חֲלָקָיו נוֹגְעִין זֶה בָּזֶה וְאֵין בֵּינֵיהֶן מְחִצָּה. הֲרֵי זֶה סָפֵק אִם מְצָרֵף הַכְּלִי לַקְּמִיצָה אוֹ אֵינוֹ מְצָרֵף. לְפִיכָךְ לֹא יִקְמֹץ. וְאִם קָמַץ לֹא יַקְטִיר. וְאִם הִקְטִיר הֻרְצָה. וְלֹא יֵאָכְלוּ הַשְּׁיָרִים:","קָמַץ וְנָתַן הַקֹּמֶץ לְמַעְלָה עַל הַשֻּׁלְחָן כְּנֶגֶד גֹּבַהּ מַעֲרֶכֶת לֶחֶם הַפָּנִים קִדְּשׁוֹ הַשֻּׁלְחָן לְהִפָּסֵל. אֲבָל אֵינוֹ מְקַדְּשׁוֹ לִקָּרֵב. וְאֵינוֹ קָרֵב עַד שֶׁיִּתְקַדֵּשׁ בִּכְלִי שָׁרֵת הָרָאוּי לְקֹמֶץ:","הִדְבִּיק הַקֹּמֶץ לְדֹפֶן הַכְּלִי וְקָמַץ. אוֹ שֶׁהָפַךְ הַכְּלִי עַל יָדוֹ וְקָמַץ מִתּוֹכוֹ וּפִיו לְמַטָּה. לֹא יַקְטִיר וְאִם הִקְטִיר הֻרְצָה:","עִשָּׂרוֹן שֶׁחִלְּקוֹ וְאָבַד אֶחָד מֵחֲלָקָיו וְהִפְרִישׁ חֵלֶק אַחֵר תַּחְתָּיו וְנִמְצָא הָאָבוּד וַהֲרֵי שְׁלָשְׁתָּן מֻנָּחִין בִּכְלִי אֶחָד וְאֵין נוֹגְעִין זֶה בָּזֶה. נִטְמָא זֶה שֶׁאָבַד הֲרֵי הוּא מִצְטָרֵף עִם חֵלֶק רִאשׁוֹן וְנִפְסְלוּ. וְזֶה שֶׁהִפְרִישׁ אֵינוֹ מִצְטָרֵף אֶלָּא יַשְׁלִים עָלָיו. נִטְמָא הַמֻּפְרָשׁ. מֻפְרָשׁ וְרִאשׁוֹן מִצְטָרְפִין וְנִפְסְלוּ. וְזֶה שֶׁנִּמְצָא אֵינוֹ מִצְטָרֵף עִמָּהֶן. נִטְמָא הַחֵלֶק הָרִאשׁוֹן הֲרֵי הָאָבוּד וְהַמֻּפְרָשׁ תַּחְתָּיו מִצְטָרְפִין:","וְכֵן לְעִנְיַן קְמִיצָה. קָמַץ מִן הַנִּמְצָא. שְׁיָרָיו עִם הַחֵלֶק הָרִאשׁוֹן נֶאֱכָלִין. וְהַמֻּפְרָשׁ אֵינוֹ נֶאֱכָל. קָמַץ מִן הַמֻּפְרָשׁ. שְׁיָרָיו נֶאֱכָלִין וְהַנִּמְצָא אֵינוֹ נֶאֱכָל. קָמַץ מִן הָרִאשׁוֹן. שְׁנֵיהֶן אֵין נֶאֱכָלִין. לְפִי שֶׁשְּׁנֵיהֶן שְׁיָרִים יְתֵרִים שֶׁהֲרֵי הֵן עִשָּׂרוֹן שָׁלֵם וְדוֹמִין לְמִנְחָה שֶׁלֹּא נִקְמְצָה שֶׁהִיא אֲסוּרָה. וְהֵיאַךְ קָרֵב הַקֹּמֶץ הַזֶּה וַהֲרֵי לְפָנָיו עִשָּׂרוֹן וּמֶחֱצָה. מִפְּנֵי שֶׁהַקְּמִיצָה תְּלוּיָה בְּדַעַת הַכֹּהֵן וּבְעֵת שֶׁקּוֹמֵץ אֵין דַּעְתּוֹ אֶלָּא עַל הָעִשָּׂרוֹן בִּלְבַד. וַהֲרֵי הַחֲלָקִים אֵינָן נוֹגְעִין זֶה בָּזֶה:","קֹמֶץ מִנְחָה שֶׁנִּתְעָרֵב בְּקֹמֶץ מִנְחָה אַחֶרֶת. מַקְטִיר שְׁנֵיהֶן כְּאַחַת וְהֵן כְּשֵׁרוֹת. וְכֵן אִם נִתְעָרֵב הַקֹּמֶץ בְּמִנְחַת כֹּהֲנִים אוֹ בְּמִנְחַת הַנְּסָכִים אוֹ בַּחֲבִיתֵי כֹּהֵן גָּדוֹל. הֲרֵי אֵלּוּ כְּשֵׁרוֹת וְיַקְטִיר הַכּל כְּאֶחָד שֶׁהַכּל לָאִשִּׁים:","שְׁתֵּי מְנָחוֹת שֶׁלֹּא נִקְמְצוּ שֶׁנִּתְעָרְבוּ זוֹ בָּזוֹ אִם יָכוֹל לִקְמֹץ מִזּוֹ בִּפְנֵי עַצְמָהּ וּמִזּוֹ בִּפְנֵי עַצְמָהּ כְּשֵׁרוֹת וְאִם לָאו פְּסוּלוֹת:","קֹמֶץ שֶׁנִּתְעָרֵב בְּמִנְחָה שֶׁלֹּא נִקְמְצָה לֹא יַקְטִיר. וְאִם הִקְטִיר הַכּל. זוֹ שֶׁנִּקְמְצָה עָלְתָה לַבְּעָלִים. וְזוֹ שֶׁלֹּא נִקְמְצָה לֹא עָלְתָה לַבְּעָלִים:","נִתְעָרֵב קֻמְצָהּ בִּשְׁיָרֶיהָ. אוֹ שֶׁנִּתְעָרְבוּ שְׁיָרֶיהָ בִּשְׁיָרֵי חֲבֶרְתָּהּ. לֹא יַקְטִיר. וְאִם הִקְטִיר עָלְתָה לַבְּעָלִים:"],"Mishneh Torah, Sacrifices Rendered Unfit 5":["הַמַּפְרִישׁ מָעוֹת לְחַטָּאתוֹ וּמֵת יֵלְכוּ הַמָּעוֹת לְיָם הַמֶּלַח. וְכֵן הַמַּפְרִישׁ מָעוֹת לְחַטָּאתוֹ וְאָבְדוּ וְהִקְרִיב חַטָּאת תַּחְתֵּיהֶן וְנִמְצְאוּ הַמָּעוֹת אַחַר כַּפָּרָה יֵלְכוּ לְיָם הַמֶּלַח:","הִפְרִישׁ מָעוֹת לְחַטָּאתוֹ וְאָבְדוּ וְהִפְרִישׁ מָעוֹת אֲחֵרוֹת תַּחְתֵּיהֶן. וְלֹא הִסְפִּיק לִקַּח בָּהֶן חַטָּאת עַד שֶׁנִּמְצְאוּ מָעוֹת הָרִאשׁוֹנוֹת. יָבִיא מֵאֵלּוּ וְאֵלּוּ לְחַטָּאת וְהַשְּׁאָר יִפְּלוּ לִנְדָבָה:","הִפְרִישׁ מָעוֹת לְחַטָּאתוֹ וְאָבְדוּ וְהִפְרִישׁ חַטָּאת תַּחְתֵּיהֶן וְלֹא הִסְפִּיק לְהַקְרִיבָהּ עַד שֶׁנִּמְצְאוּ הַמָּעוֹת וַהֲרֵי הַחַטָּאת בַּעֲלַת מוּם. תִּמָּכֵר וְיָבִיא מֵאֵלּוּ וְאֵלּוּ חַטָּאת וְהַשְּׁאָר יִפְּלוּ לִנְדָבָה:","הִפְרִישׁ חַטָּאתוֹ וְאָבְדָה וְהִפְרִישׁ מָעוֹת תַּחְתֶּיהָ וְלֹא הִסְפִּיק לִקַּח בָּהֶם עַד שֶׁנִּמְצֵאת חַטָּאתוֹ וַהֲרֵי הִיא בַּעֲלַת מוּם. תִּמָּכֵר וְיָבִיא מֵאֵלּוּ וְאֵלּוּ חַטָּאת וְהַשְּׁאָר יִפְּלוּ לִנְדָבָה:","הִפְרִישׁ שְׁנֵי צִבּוּרֵי מָעוֹת לְאַחֲרָיוּת. מִתְכַּפֵּר בְּאֶחָד מֵהֶם וְהַשֵּׁנִי יִפּל לִנְדָבָה:","הַמַּפְרִישׁ חַטָּאתוֹ אוֹ דְּמֵי חַטָּאתוֹ וְכַסָּבוּר שֶׁהוּא חַיָּב וְנִמְצָא שֶׁאֵינוֹ חַיָּב. הֲרֵי אֵלּוּ חֻלִּין וְלֹא נִתְקַדְּשׁוּ. הִפְרִישׁ שְׁתַּיִם אוֹ דְּמֵי שְׁתַּיִם וְכַסָּבוּר שֶׁהוּא חַיָּב שְׁתַּיִם וְנִמְצָא שֶׁאֵינוֹ חַיָּב אֶלָּא אַחַת. יָבִיא אַחַת וְהַשְּׁאָר יִפְּלוּ לִנְדָבָה:","הַלּוֹקֵחַ מָעוֹת בְּיָדוֹ אוֹ שֶׁהָיָה מְלַקֵּט וְאָמַר אֵלּוּ אָבִיא מֵהֶם חַטָּאתִי. הַמּוֹתָר חֻלִּין. וְכֵן יֵרָאֶה לִי שֶׁהַדָּבָר קַל וָחֹמֶר בִּשְׁאָר הַקָּרְבָּנוֹת שֶׁהַמּוֹתָר חֻלִּין:","הַמַּפְרִישׁ מָעוֹת לְמִנְחַת חוֹטֵא וְהֵבִיא מֵהֶם מִנְחָתוֹ. אוֹ שֶׁהִפְרִישׁ מִנְחַת חוֹטֵא וְהוֹתִירָה. הַמּוֹתָר יָבִיא מִנְחַת נְדָבָה. אֲבָל מוֹתַר עֲשִׂירִית הָאֵיפָה שֶׁל כֹּהֵן גָּדוֹל שֶׁהִיא הַחֲבִיתִין יֵרָקֵב. וְכֵן מוֹתַר לַחְמֵי תּוֹדָה וּמוֹתַר לַחְמוֹ שֶׁל נָזִיר יֵרָקְבוּ. וּמוֹתַר דְּמֵי נְסָכָיו יִפְּלוּ לִנְדָבָה. כְּבָר בֵּאַרְנוּ בִּשְׁקָלִים שֶׁמּוֹתַר הַשְּׁקָלִים חֻלִּין:","מוֹתַר קִנֵּי זָבִים. קִנֵּי זָבוֹת. קִנֵּי יוֹלְדוֹת. חַטָּאוֹת וַאֲשָׁמוֹת. מוֹתְרֵיהֶם יִפְּלוּ לִנְדָבָה וְיִקָּרְבוּ עוֹלוֹת כְּמוֹ שֶׁבֵּאַרְנוּ. מוֹתַר עוֹלָה לְעוֹלָה. מוֹתַר שְׁלָמִים לִשְׁלָמִים. מוֹתַר מִנְחָה לְמִנְחָה. מוֹתַר פֶּסַח לִשְׁלָמִים. מוֹתַר נְזִירִים לִנְזִירִים. מוֹתַר נָזִיר לְאוֹתוֹ נָזִיר. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמּוֹתַר חַטָּאת לִנְדָבָה. בְּחַטָּאת קְבוּעָה. אֲבָל מִי שֶׁהוּא חַיָּב בְּקָרְבָּן עוֹלֶה וְיוֹרֵד שֶׁהִפְרִישׁ מָעוֹת לְחַטַּאת בְּהֵמָה וְהֶעֱנִי. מֵבִיא תַּחְתֵּיהֶם עוֹף וּמְחַלְּלָן עַל הָעוֹף וְיֵהָנֶה מֵהֶם. וְכֵן אִם הִפְרִישׁ דְּמֵי הָעוֹף וְהֶעֱנִי. מֵבִיא תַּחְתֵּיהֶם עֲשִׂירִית הָאֵיפָה וִיחַלֵּל הַמָּעוֹת עָלֶיהָ וְיֵהָנֶה בָּהֶם:","הִפְרִישׁ בְּהֵמָה וְנָפַל בָּהּ מוּם. תִּמָּכֵר וְיָבִיא בְּדָמֶיהָ עוֹף. אֲבָל אִם הִפְרִישׁ עוֹף וְנִפְסַל. לֹא יָבִיא בְּדָמָיו עֲשִׂירִית הָאֵיפָה. שֶׁאֵין לָעוֹף פִּדְיוֹן כְּמוֹ שֶׁבֵּאַרְנוּ בְּאִסּוּרֵי הַמִּזְבֵּחַ:","כָּל חַיָּבֵי קִנִּין שֶׁבַּתּוֹרָה שֶׁהִפְרִישׁוּ מָעוֹת לְקִנֵּיהֶן. רָצָה לְהָבִיא בְּכָל הַמָּעוֹת חַטַּאת הָעוֹף לְבַדָּהּ יָבִיא. רָצָה לְהָבִיא בָּהֶן עוֹלַת הָעוֹף לְבַדָּהּ יָבִיא. אֲפִלּוּ אָמַר אֵלּוּ דְּמֵי חַטָּאתִי וְאֵלּוּ דְּמֵי עוֹלָתִי. יֵשׁ לוֹ לְעָרֵב הַמָּעוֹת וְלִקַּח בָּהֶן כְּאֶחָד חַטָּאתוֹ וְעוֹלָתוֹ. אוֹ לִקַּח בַּכּל חַטָּאת אוֹ עוֹלָה. שֶׁאֵין הַקִּנִּין מִתְפָּרְשׁוֹת אֶלָּא בִּלְקִיחַת הַבְּעָלִים אוֹ בַּעֲשִׂיַּת כֹּהֵן:","לְפִיכָךְ אִם הִפְרִישׁ מָעוֹת לְקִנִּין סְתָם וּמֵת. יִפְּלוּ כָּל אוֹתָן הַמָּעוֹת הַסְּתוּמִין לִנְדָבָה. שֶׁהֲרֵי כֻּלָּן רְאוּיִין לָבוֹא עוֹלָה:","מִי שֶׁהָיָה מְחֻיָּב חַטָּאת וְאָמַר הֲרֵי עָלַי עוֹלָה וְהִפְרִישׁ מָעוֹת וְאָמַר אֵלּוּ לְחוֹבָתִי. רָצָה לְהָבִיא בָּהֶן חַטַּאת בְּהֵמָה יָבִיא. עוֹלַת בְּהֵמָה יָבִיא. מֵת וְהִנִּיחַ הַמָּעוֹת יֵלְכוּ לְיָם הַמֶּלַח:"],"Mishneh Torah, Sacrificial Procedure 16":["הַנּוֹדֵר גָּדוֹל וְהֵבִיא קָטָן לֹא יָצָא. קָטָן וְהֵבִיא גָּדוֹל יָצָא. כֵּיצַד. אָמַר הֲרֵי עָלַי עוֹלָה אוֹ שְׁלָמִים כֶּבֶשׂ וְהֵבִיא אַיִל. אוֹ שֶׁנָּדַר עֵגֶל וְהֵבִיא שׁוֹר. גְּדִי וְהֵבִיא שָׂעִיר יָצָא:","נָדַר עוֹלָה מִן הַכְּבָשִׂים אוֹ מִן הָאֵילִים וְהֵבִיא פִּלְגָּס הֲרֵי זֶה סָפֵק אִם יָצָא יְדֵי נִדְרוֹ אוֹ לֹא יָצָא. וְכֵן הַנּוֹדֵר עוֹלַת עוֹף מִן הַתּוֹרִים אוֹ מִן בְּנֵי הַיּוֹנָה וְהֵבִיא תְּחִלַּת הַצִּהוּב שֶׁבָּזֶה וְשֶׁבָּזֶה הֲרֵי זֶה סָפֵק. נָדַר שָׁחֹר וְהֵבִיא לָבָן לָבָן וְהֵבִיא שָׁחֹר זָכָר וְהֵבִיא נְקֵבָה נְקֵבָה וְהֵבִיא זָכָר לֹא יָצָא:","הַנּוֹדֵר סְתָם מֵבִיא מִן הַגְּדוֹלִים שֶׁבַּמִּין שֶׁנָּדַר. וְאִם אוֹתוֹ הַמָּקוֹם רְגִילִין לִקְרוֹת בִּסְתָם לְאֶחָד מִן הַמִּינִין מֵבִיא כְּאַנְשֵׁי הַמָּקוֹם. כֵּיצַד. נָדַר עוֹלָה מִן הַבָּקָר יָבִיא שׁוֹר. אָמַר הֲרֵי עָלַי עוֹלָה אִם דֶּרֶךְ אַנְשֵׁי הַמָּקוֹם לִקְרוֹת עוֹלָה סְתָם אֲפִלּוּ לְעוֹלַת הָעוֹף מֵבִיא פְּרֵדָה אַחַת תּוֹר אוֹ בֶּן יוֹנָה. וְאִם דַּרְכָּן שֶׁאֵין קוֹרִין עוֹלָה סְתָם אֶלָּא לְעוֹלַת בָּקָר יָבִיא שׁוֹר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁנָּדַר שׁוֹר אוֹ אַיִל אוֹ כֶּבֶשׂ אוֹ עֵגֶל וְכַיּוֹצֵא בָּהֶם לֹא יָבִיא כָּחוּשׁ בְּיוֹתֵר שֶׁבְּאוֹתוֹ הַמִּין מִפְּנֵי שֶׁדָּמָיו מוּעָטִין. וְאֵינוֹ חַיָּב לְהָבִיא הַיָּפֶה הַשָּׁמֵן בְּיוֹתֵר שֶׁאֵין שָׁם לְמַעְלָה מִמֶּנּוּ אֶלָּא יָבִיא הַבֵּינוֹנִי. וְאִם הֵבִיא הַכָּחוּשׁ יָצָא יְדֵי נִדְרוֹ:","הָאוֹמֵר הֲרֵי עָלַי שׁוֹר שְׁוֵה מָנֶה יָבִיא שׁוֹר שֶׁשָּׁוֶה מָנֶה בְּאוֹתוֹ מָקוֹם חוּץ מִנְּסָכָיו. הֵבִיא שְׁנַיִם בְּמָנֶה לֹא יָצָא:","הָאוֹמֵר שׁוֹר זֶה עוֹלָה וְנָפַל בּוֹ מוּם אִם רָצָה יָבִיא בְּדָמָיו שְׁנַיִם וַאֲפִלּוּ הֵבִיא בְּדָמָיו אַיִל אֶחָד יָצָא. אָמַר שְׁנֵי שְׁוָרִים אֵלּוּ עוֹלָה וְנָפַל בָּהֶם מוּם אִם רָצָה יָבִיא בִּדְמֵיהֶם אֶחָד. אַיִל זֶה עוֹלָה וְנָפַל בּוֹ מוּם אִם רָצָה יָבִיא בְּדָמָיו כֶּבֶשׂ. וְכֵן אִם נָדַר כֶּבֶשׂ וְנִפְסַל אִם רָצָה יָבִיא בְּדָמָיו אַיִל:","אָמַר הֲרֵי עָלַי עוֹלָה וְהִפְרִישׁ שׁוֹר וְנִגְנַב פּוֹטֵר עַצְמוֹ בְּשֶׂה. אָמַר שׁוֹר זֶה וְדָמָיו עָלַי עוֹלָה הֻקְבַּע וְאִם נִפְסַל לֹא יָבִיא בְּדָמָיו אֶלָּא שׁוֹר:","הָאוֹמֵר אֶחָד מִכְּבָשַׂי הֶקְדֵּשׁ וְאֶחָד מִשְּׁוָרַי הֶקְדֵּשׁ וְהָיוּ לוֹ שְׁנַיִם הַגָּדוֹל שֶׁבָּהֶן הֶקְדֵּשׁ. הָיוּ שְׁלֹשָׁה הַגָּדוֹל שֶׁבָּהֶן הֶקְדֵּשׁ וְחוֹשְׁשִׁין לַבֵּינוֹנִי. כֵּיצַד יַעֲשֶׂה. יַמְתִּין לַבֵּינוֹנִי עַד שֶׁיִּפּל בּוֹ מוּם וְתָחוּל הַקְּדֻשָּׁה עַל הַגָּדוֹל לְבַדּוֹ. וְאִם אָמַר שׁוֹר שֶׁבִּשְׁוָרַי הֶקְדֵּשׁ הַגָּדוֹל שֶׁבָּהֶם הֶקְדֵּשׁ וְאֵין חוֹשְׁשִׁין לַבֵּינוֹנִי:","פֵּרַשׁ אֶחָד מֵהֶן וְשָׁכַח אוֹ שֶׁאָמַר לוֹ אָבִיו אֶחָד מֵהֶן הֶקְדֵּשׁ הֲרֵי זֶה מַקְדִּישׁ גָּדוֹל שֶׁבָּהֶן וְאַחַר כָּךְ יֵצֵא יְדֵי חוֹבָתוֹ. וְכֵן הַנּוֹדֵר עוֹלָה מִן הַבָּקָר וְקָבַע נִדְרוֹ וְשָׁכַח מַה קָּבַע אִם שׁוֹר אִם עֵגֶל הֲרֵי זֶה יָבִיא שׁוֹר. וְכֵן אִם קָבַע בַּכְּבָשִׂים וְשָׁכַח מַה קָּבַע יָבִיא אַיִל. קָבַע בָּעִזִּים וְשָׁכַח יָבִיא שָׂעִיר. שָׁכַח בְּאֵיזֶה מִין מִן הַבְּהֵמָה קָבַע עוֹלָתוֹ יָבִיא שׁוֹר וְאַיִל וְשָׂעִיר. וְאִם נִסְתַּפֵּק לוֹ שֶׁמָּא קָבַע עוֹלָתוֹ בָּעוֹף יוֹסִיף תּוֹר וּבֶן יוֹנָה:","נָדַר תּוֹדָה אוֹ שְׁלָמִים וְקָבַע נִדְרוֹ בַּבָּקָר וְשָׁכַח בְּמִי קְבָעוֹ יָבִיא פַּר וּפָרָה. וְכֵן אִם נִסְתַּפֵּק לוֹ בַּכְּבָשִׂים יָבִיא אַיִל וְרָחֵל. נִסְתַּפֵּק לוֹ בָּעִזִּים יָבִיא שָׂעִיר וּשְׂעִירָה. שָׁכַח בְּאֵי זֶה מִין קָבַע נִדְרוֹ מֵבִיא פַּר וּפָרָה אַיִל וְרָחֵל שָׂעִיר וּשְׂעִירָה. הָאוֹמֵר הֲרֵי עָלַי עוֹלַת עוֹף מֵבִיא תּוֹר אוֹ בֶּן יוֹנָה. פֵּרֵשׁ וְשָׁכַח בְּאֵי זֶה מִין קָבַע נִדְרוֹ מֵבִיא תּוֹר וּבֶן יוֹנָה:","הָאוֹמֵר הֲרֵי עָלַי לַמִּזְבֵּחַ יָבִיא קֹמֶץ לְבוֹנָה שֶׁאֵין לְךָ דָּבָר שֶׁקָּרֵב כֻּלּוֹ לַמִּזְבֵּחַ כְּמוֹת שֶׁהוּא אֶלָּא לְבוֹנָה. פֵּרֵשׁ נִדְרוֹ וְשָׁכַח מַה פֵּרֵשׁ יָבִיא מִכָּל דָּבָר שֶׁקָּרֵב כֻּלּוֹ לַמִּזְבֵּחַ. לְפִיכָךְ מֵבִיא עוֹלַת בְּהֵמָה וְעוֹלַת הָעוֹף וּמִנְחַת נְסָכִים וּלְבוֹנָה וְיַיִן בִּפְנֵי עַצְמוֹ:","אָמַר הֲרֵי עָלַי בְּסֶלַע לַמִּזְבֵּחַ יָבִיא כֶּבֶשׂ. שֶׁאֵין לְךָ דָּבָר שֶׁקָּרֵב בְּסֶלַע לַמִּזְבֵּחַ אֶלָּא כֶּבֶשׂ. פֵּרֵשׁ וְשָׁכַח מַה שֶּׁפֵּרֵשׁ יָבִיא בְּסֶלַע מִכָּל דָּבָר וְדָבָר שֶׁקָּרֵב לַמִּזְבֵּחַ:","הָאוֹמֵר הֲרֵי עָלַי לְבוֹנָה לֹא יִפְחֹת מִקֹּמֶץ. הֲרֵי עָלַי עֵצִים לֹא יִפְחֹת מִשְּׁנֵי גְּזָרִים עָבִין כִּמְחוּקוֹת וְאָרְכָּן אַמָּה. הֲרֵי עָלַי עֵץ מֵבִיא גֶּזֶר אֶחָד אָרְכּוֹ אַמָּה. וְאִם רָצָה לְהָבִיא דְּמֵי הָעֵצִים יָבִיא:","מִי שֶׁנָּדַר אוֹ הִתְנַדֵּב שֶׁמֶן כֵּיצַד עוֹשִׂין בּוֹ. קוֹמֵץ מִמֶּנּוּ קֹמֶץ וְנוֹתֵן עָלָיו מֶלַח וְזוֹרְקוֹ עַל גַּבֵּי הָאִשִּׁים וְהַשְּׁאָר נֶאֱכָל לַכֹּהֲנִים כִּשְׁיָרֵי מְנָחוֹת. וְכֵיצַד עוֹשִׂין בְּיַיִן הַבָּא בִּפְנֵי עַצְמוֹ. נוֹתֵן עָלָיו מֶלַח וּמְנַסְּכוֹ כֻּלּוֹ עַל גַּבֵּי הַשִּׁיתִין כְּכָל הַנְּסָכִים. וְהַלְּבוֹנָה הַבָּאָה בִּפְנֵי עַצְמָהּ נוֹתֵן עָלֶיהָ מֶלַח וְכֻלָּהּ לָאִשִּׁים:","מִי שֶׁנָּדַר נֵדֶר לֹא יְבִיאֶנּוּ מִמְּעוֹת מַעֲשֵׂר שֵׁנִי שֶׁהֲרֵי נִתְחַיֵּב בְּקָרְבָּן זֶה וְכָל הַמְחֻיָּב בְּקָרְבָּן לֹא יָבִיא קָרְבָּנוֹ אֶלָּא מִן הַחֻלִּין:","אָמַר הֲרֵי עָלַי תּוֹדָה מִן הַחֻלִּין וְלַחְמָהּ מִן הַמַּעֲשֵׂר לֹא יָבִיא לַחְמָהּ אֶלָּא מִן הַחֻלִּין. שֶׁהֲרֵי נָדַר בְּקָרְבַּן תּוֹדָה וְהַתּוֹדָה אֵינָהּ בָּאָה אֶלָּא עִם הַלֶּחֶם מִן הַחֻלִּין:","פֵּרֵשׁ וְאָמַר הֲרֵי עָלַי לְהָבִיא תּוֹדָה מִמְּעוֹת מַעֲשֵׂר שֵׁנִי וְלַחְמָהּ מִן הַחֻלִּין יֵשׁ לוֹ לְהָבִיא כְּמוֹ שֶׁנָּדַר. וְאִם הֵבִיא הַכּל מִן הַחֻלִּין יָצָא. וְכֵן אִם פֵּרֵשׁ וְאָמַר הֲרֵי עָלַי תּוֹדָה הִיא וְלַחְמָהּ מִן הַמַּעֲשֵׂר יָבִיא. וְלֹא יָבִיא לַחְמָהּ מֵחִטֵּי מַעֲשֵׂר שֵׁנִי אֶלָּא מִמְּעוֹת מַעֲשֵׂר שֵׁנִי כְּמוֹ הַבְּהֵמָה שֶׁהִיא מִמְּעוֹת מַעֲשֵׂר שֵׁנִי. וְאַף עַל פִּי שֶׁפֵּרֵשׁ שֶׁיָּבִיא לַחְמָהּ מִן הַמַּעֲשֵׂר לֹא יָבִיא נְסָכֶיהָ מִמְּעוֹת מַעֲשֵׂר שֵׁנִי שֶׁאֵין הַנְּסָכִים בָּאִין לְעוֹלָם אֶלָּא מִן הַחֻלִּין כְּמוֹ שֶׁבֵּאַרְנוּ. לְפִי שֶׁנֶּאֱמַר בָּהֶן (במדבר טו ד) \"וְהִקְרִיב הַמַּקְרִיב קָרְבָּנוֹ\" עַד שֶׁיִּהְיוּ מִשֶּׁלּוֹ וְלֹא יִהְיֶה בָּהֶן צַד לְגָבוֹהַּ כְּלָל:"],"Mishneh Torah, Sales 1":["הַמִּקָח אֵינוֹ נִקְנֶה בִּדְבָרִים. וַאֲפִלּוּ הֵעִידוּ עֲלֵיהֶם עֵדִים. כֵּיצַד. בַּיִת זֶה אֲנִי מוֹכֵר לְךָ. יַיִן זֶה אֲנִי מוֹכֵר לְךָ. עֶבֶד זֶה אֲנִי מוֹכֵר לְךָ. וּפָסְקוּ הַדָּמִים וְרָצָה הַלּוֹקֵחַ וְאָמַר קָנִיתִי. וְרָצָה הַמּוֹכֵר וְאָמַר מָכַרְתִּי. וְאָמְרוּ לָעֵדִים הֱווּ עָלֵינוּ עֵדִים שֶׁמָּכַר זֶה וְשֶׁלָּקַח זֶה. הֲרֵי זֶה אֵינוֹ כְּלוּם וּכְאִלּוּ לֹא הָיוּ בֵּינֵיהֶם דְּבָרִים מֵעוֹלָם. וְכֵן בְּנוֹתֵן מַתָּנָה וּמְקַבְּלָהּ:","אֲבָל אִם נִקְנָה הַמִּקָּח בְּאֶחָד מֵהַדְּבָרִים שֶׁהוּא נִקְנֶה בָּהֶם קָנָה הַלּוֹקֵחַ וְאֵינָן צְרִיכִין לְעֵדִים כְּלָל וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ:","וּבְמָה יִקָּנֶה הַמִּקָּח. הַקַּרְקָעוֹת בְּאֶחָד מִשְּׁלֹשָׁה דְּבָרִים. בְּכֶסֶף. אוֹ בִּשְׁטָר. אוֹ בַּחֲזָקָה:","כֵּיצַד בְּכֶסֶף. מָכַר לוֹ בַּיִת מָכַר לוֹ שָׂדֶה וְנָתַן לוֹ הַדָּמִים קָנָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמָקוֹם שֶׁאֵין כּוֹתְבִין אֶת הַשְּׁטָר. אֲבָל בְּמָקוֹם שֶׁדַּרְכָּן לִכְתֹּב שְׁטַר מֶכֶר לֹא קָנָה עַד שֶׁיִּכְתֹּב אֶת הַשְּׁטָר. וְאֵין קַרְקַע נִקְנֵית בְּפָחוֹת מִשְּׁוֵה פְּרוּטָה:","הִתְנָה הַלּוֹקֵחַ וְאָמַר אִם רָצִיתִי אֶקְנֶה בְּכֶסֶף אוֹ אֶקְנֶה בִּשְׁטָר. וְנָתַן הַכֶּסֶף עַל תְּנַאי זֶה. הֲרֵי זֶה קַיָּם וְאֵין הַמּוֹכֵר יָכוֹל לַחְזֹר בּוֹ מִפְּנֵי הַתְּנַאי. וְהַלּוֹקֵחַ יָכוֹל לַחְזֹר בּוֹ עַד שֶׁיִּכְתֹּב אֶת הַשְּׁטָר. וְכֵן אִם הִתְנָה הַמּוֹכֵר כָּזֶה:","הָאוֹמֵר לַחֲבֵרוֹ תֵּן מָנֶה לִפְלוֹנִי וְיִקָּנֶה בֵּיתִי לְךָ. כֵּיוָן שֶׁנָּתַן קָנָה הַבַּיִת מִדִּין עָרֵב:","כֵּיצַד בִּשְׁטָר. כָּתַב לוֹ עַל הַנְּיָר אוֹ עַל הַחֶרֶס אוֹ עַל הֶעָלֶה שָׂדִי נְתוּנָה לְךָ שָׂדִי מְכוּרָה לְךָ כֵּיוָן שֶׁהִגִּיעַ הַשְּׁטָר לְיָדוֹ קָנָה. אַף עַל פִּי שֶׁאֵין שָׁם עֵדִים כְּלָל. וְאַף עַל פִּי שֶׁאֵין הַשְּׁטָר שָׁוֶה כְּלוּם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמוֹכֵר שָׂדֶה מִפְּנֵי רָעָתָהּ. אֲבָל בִּשְׁאָר קַרְקָעוֹת אַף עַל פִּי שֶׁהִגִּיעַ שְׁטָר שֶׁל מֶכֶר לְיָדוֹ וַאֲפִלּוּ הָיוּ בּוֹ עֵדִים לֹא קָנָה עַד שֶׁיִּתֵּן אֶת הַדָּמִים:","כֵּיצַד בַּחֲזָקָה. מָכַר לוֹ בַּיִת מָכַר לוֹ שָׂדֶה אוֹ שֶׁנָּתַן אוֹתָהּ בְּמַתָּנָה כֵּיוָן שֶׁנָּעַל אוֹ גָּדַר אוֹ פָּרַץ כָּל שֶׁהוּא וְהוּא שֶׁיּוֹעִיל בְּמַעֲשָׂיו הֲרֵי זֶה קָנָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֶחֱזִיק בִּפְנֵי הַמּוֹכֵר אוֹ הַנּוֹתֵן. אֲבָל שֶׁלֹּא בִּפְנֵי הַמּוֹכֵר אוֹ הַנּוֹתֵן צָרִיךְ שֶׁיֹּאמַר לוֹ לֵךְ חַזֵּק וּקְנֵה וְאַחַר כָּךְ אִם הֶחֱזִיק קָנָה אַף עַל פִּי שֶׁאֵינוֹ בִּפְנֵי הַבְּעָלִים:","הַמּוֹכֵר בַּיִת לַחֲבֵרוֹ וּמָסַר לוֹ אֶת הַמַּפְתֵּחַ הֲרֵי זֶה כְּמִי שֶׁאָמַר לוֹ לֵךְ חַזֵּק וּקְנֵה. וְכֵן הַמּוֹכֵר אֶת הַבּוֹר כֵּיוָן שֶׁמָּסַר לוֹ דִּלְיוֹ הֲרֵי זֶה כְּמִי שֶׁאָמַר לוֹ לֵךְ חַזֵּק וּקְנֵה, וּכְשֶׁהֶחֱזִיק יִקְנֶה:","כֵּיצַד הַמַּחֲזִיק בִּנְעִילָה קָנָה. כְּגוֹן שֶׁמָּכַר בַּיִת אוֹ חָצֵר וְהָיָה הַפֶּתַח פָּתוּחַ וְנָעַל הַלּוֹקֵחַ אֶת הַפֶּתַח וְחָזַר וּפְתָחוֹ הֲרֵי זֶה הֶחֱזִיק וְקָנָה. שֶׁהֲרֵי נִשְׁתַּמֵּשׁ בָּהּ שִׁמּוּשׁ הַמּוֹעִיל:","כֵּיצַד הַמַּחֲזִיק בִּגְדִירָה כָּל שֶׁהוּא קָנָה. כְּגוֹן שֶׁהָיָה שָׁם גָּדֵר וְהָיוּ עוֹלִין בְּנַחַת. וְהוֹסִיף עָלָיו כָּל שֶׁהוּא וְהִשְׁלִימוֹ לַעֲשָׂרָה וְנִמְצָא שֶׁאֵין עוֹלִין אֶלָּא בְּדֹחַק. הֲרֵי זֶה הוֹעִיל וְקָנָה. וְכֵן אִם הָיְתָה שָׁם פִּרְצָה וְהָיוּ נִכְנָסִים בָּהּ בְּדֹחַק וְהִרְחִיב הוּא בָּהּ כָּל שֶׁהוּא עַד שֶׁנִּמְצָא נִכְנַס בְּרֶוַח. הֲרֵי הוֹעִיל וְקָנָה:","נָתַן צְרוֹר וְהוֹעִיל. כְּגוֹן שֶׁחִבֵּר בּוֹ הַמַּיִם לַשָּׂדֶה. אוֹ נָטַל צְרוֹר וְהוֹעִיל כְּגוֹן שֶׁפָּתַח בִּנְטִילָתוֹ הַמַּיִם לַשָּׂדֶה. הֲרֵי זֶה קָנָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹכֵר שָׂדֶה לַחֲבֵרוֹ בְּצַד שָׂדֵהוּ. אוֹ שֶׁנְּתָנָהּ לוֹ בְּמַתָּנָה. כֵּיוָן שֶׁדָּשׁ אֶת הַמֵּצַר שֶׁבֵּין שְׁתֵּי הַשָּׂדוֹת וְנַעֲשׂוּ שְׁתֵּיהֶן כְּשָׂדֶה אַחַת קָנָה. אֲבָל אִם הָלַךְ בָּהּ לְאָרְכָּהּ וּלְרָחְבָּהּ אֵין הִלּוּךְ זֶה מוֹעִיל כְּלוּם. וְאִם שְׁבִיל שֶׁל כְּרָמִים מָכַר לוֹ הוֹאִיל וְנַעֲשָׂה לְהִלּוּךְ קָנָה בְּהִלּוּךְ:","וְכַמָּה שִׁעוּר רֹחַב הַדֶּרֶךְ שֶׁיִּקְנֶה בְּהִלּוּכוֹ. אִם הָיָה מְסֻיָּם בִּמְחִצּוֹת קָנָה כְּדֵי שֶׁיַּגְבִּיהַּ רֶגֶל וְיַנִּיחַ רֶגֶל בְּצִדָּהּ. וְאִם אֵין שָׁם מְחִצּוֹת קָנָה בָּרֹחַב כְּדֵי שֶׁתִּהְיֶה עַל רֹאשׁוֹ חֲבִילָה שֶׁל שָׂרִיגִים וְיָסֹב בָּהּ:","הָיְתָה הַקַּרְקַע צְחִיחַ סֶלַע שֶׁאֵין בָּהּ לֹא גָּדֵר וְלֹא פִּרְצָה. וְאֵינָהּ בַּת זְרִיעָה. הֲרֵי הַחֲזָקָה שֶׁקּוֹנָה אוֹתָהּ שְׁטִיחַת פֵּרוֹת אוֹ הַעֲמָדַת בְּהֵמָה שָׁם וְכַיּוֹצֵא בָּזֶה מִשְּׁאָר הַתַּשְׁמִישׁ:","הַמּוֹכֵר שָׂדֶה לַחֲבֵרוֹ וְנִכְנַס בָּהּ הַלּוֹקֵחַ וּזְרָעָהּ אוֹ נָרָהּ. אוֹ שֶׁאָסַף פֵּרוֹת הָאִילָן אוֹ זְמָרוֹ וְכָל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ הֲרֵי זֶה קָנָה שֶׁהֲרֵי הֶחֱזִיק. וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ. וְכֵן אִם אָסַף הַמּוֹכֵר סַל שֶׁל פֵּרוֹת וְנָתַן לַלּוֹקֵחַ. קָנָה לוֹקֵחַ מִיָּד בַּחֲזָקָה. שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁהִקְנָה לוֹ שָׂדֶה זוֹ קִנְיָן גָּמוּר וְנַעֲשׂוּ פֵּרוֹתֶיהָ שֶׁלּוֹ:","הָעַכּוּ\"ם אֵינוֹ קוֹנֶה בַּחֲזָקָה. אֶלָּא בִּשְׁטָר הוּא שֶׁקּוֹנֶה עִם נְתִינַת הַכֶּסֶף. וְיִשְׂרָאֵל הַבָּא מֵחֲמַת הָעַכּוּ\"ם הֲרֵי הוּא כְּעַכּוּ\"ם וְאֵינוֹ קוֹנֶה אֶלָּא בִּשְׁטָר. כָּל הַמְחֻבָּר לַקַּרְקַע הֲרֵי הוּא כְּקַרְקַע. וְנִקְנֶה אוֹ בְּכֶסֶף אוֹ בִּשְׁטָר אוֹ בַּחֲזָקָה. וְאִם אֵינוֹ צָרִיךְ לַקַּרְקַע כְּגוֹן עֲנָבִים הָעוֹמְדוֹת לִבָּצֵר הֲרֵי זֶה כְּמִטַּלְטְלִין לְקִנְיָן וְיֵשׁ לָהֶן אוֹנָאָה:","כְּשֵׁם שֶׁהַקַּרְקַע נִקְנֶה בְּכֶסֶף בִּשְׁטָר וּבַחֲזָקָה. כָּךְ שְׂכִירוּת הַקַּרְקַע נִקְנֶה בְּכֶסֶף לְבַדּוֹ אוֹ בִּשְׁטָר לְבַדּוֹ אוֹ בַּחֲזָקָה. וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ:","הַמּוֹכֵר לַחֲבֵרוֹ עֶשֶׂר שָׂדוֹת בְּעֶשֶׂר מְדִינוֹת. כֵּיוָן שֶׁהֶחְזִיק בְּאַחַת מֵהֶן קָנָה כֻּלָּן. וַאֲפִלּוּ הָיְתָה אַחַת מֵהֶן הַר גָּבוֹהַּ וְהַשֵּׁנִית מְצוּלָה שֶׁהֲרֵי תַּשְׁמִישׁ שֶׁל זוֹ אֵינָהּ תַּשְׁמִישׁ שֶׁל זוֹ. אַף עַל פִּי כֵן כֵּיוָן שֶׁהֶחְזִיק בְּאַחַת מֵהֶן קָנָה הַשְּׁאָר:","בַּמֶּה דְּבָרִים אֲמוּרִים. שֶׁנָּתַן דְּמֵי כֻּלָּן. אֲבָל אִם לֹא נָתַן דְּמֵי כֻּלָּן לֹא קָנָה אֶלָּא כְּנֶגֶד מְעוֹתָיו. לְפִיכָךְ אִם הָיוּ הַכּל בְּמַתָּנָה קָנָה כֻּלָּן. וְכֵן בִּשְׂכִירוּת כֵּיוָן שֶׁהֶחְזִיק בְּאַחַת מֵהֶן קָנָה כֻּלָּן כָּל זְמַן הַשְּׂכִירוּת. הָיוּ מִקְצָת הַקַּרְקָעוֹת בְּמֶכֶר וּמִקְצָתָן בִּשְׂכִירוּת. כֵּיוָן שֶׁהֶחְזִיק בֵּין בִּמְכִירָה בֵּין בִּשְׂכִירוּת קָנָה הַכּל:"],"Mishneh Torah, Sales 20":["הַמְבַקֵשׁ לִקְנוֹת מֵחֲבֵרוֹ מִקָּח. מוֹכֵר אוֹמֵר בְּמָאתַיִם אֲנִי מוֹכֵר לְךָ וְהַלּוֹקֵחַ אוֹמֵר אֵינִי קוֹנֶה אֶלָּא בְּמָנֶה. וְהָלַךְ זֶה לְבֵיתוֹ וְזֶה לְבֵיתוֹ וְאַחַר כָּךְ נִתְקַבְּצוּ וּמָשַׁךְ זֶה הַחֵפֶץ סְתָם. אִם הַמּוֹכֵר הוּא שֶׁתָּבַע הַלּוֹקֵחַ וְנָתַן לוֹ הַחֵפֶץ אֵינוֹ נוֹתֵן אֶלָּא מָנֶה. וְאִם הַלּוֹקֵחַ הוּא שֶׁבָּא וּמָשַׁךְ זֶה הַחֵפֶץ סְתָם חַיָּב לִתֵּן מָאתַיִם:","הַלּוֹקֵחַ מֵאֶחָד מֵחֲמִשָּׁה בְּנֵי אָדָם וְכָל אֶחָד מֵהֶן תּוֹבֵעַ אוֹתוֹ וְאוֹמֵר אֲנִי הוּא בַּעַל הַמִּקָּח. וְהוּא אֵינוֹ יוֹדֵעַ מִמִּי מֵהֶם לָקַח. מַנִּיחַ דְּמֵי הַמִּקָּח בֵּינֵיהֶם וּמִסְתַּלֵּק וְיִהְיוּ הַדָּמִים מֻנָּחִין עַד שֶׁיּוֹדוּ אוֹ עַד שֶׁיָּבוֹא אֵלִיָּהוּ. וְאִם הוּא חָסִיד נוֹתֵן דָּמִים לְכָל אֶחָד וְאֶחָד כְּדֵי לָצֵאת יְדֵי שָׁמַיִם:","לָקַח מִקָּח מֵאֶחָד מֵחֲמִשָּׁה בְּנֵי אָדָם וְכָפַר בּוֹ וְנִשְׁבַּע עַל שֶׁקֶר וְעָשָׂה תְּשׁוּבָה וַהֲרֵי הוּא רוֹצֶה לְשַׁלֵּם וְכָל אֶחָד וְאֶחָד תּוֹבֵעַ אוֹתוֹ וְאוֹמֵר אֲנִי הוּא שֶׁכָּפַרְתָּ בִּי וְנִשְׁבַּעְתָּ לִי וְהוּא אוֹמֵר אֵינִי יוֹדֵעַ. חַיָּב לְשַׁלֵּם לְכָל אֶחָד וְאֶחָד מִפְּנֵי שֶׁעָבַר עֲבֵרָה:","נֶאֱמָן בַּעַל הַמִּקָּח לוֹמַר לָזֶה מָכַרְתִּי וְלָזֶה לֹא מָכַרְתִּי. אֵימָתַי בִּזְמַן שֶׁהַמִּקָּח יוֹצֵא מִתַּחַת יָדוֹ. אֲבָל אִם אֵין הַמִּקָּח יוֹצֵא מִתַּחַת יָדוֹ הֲרֵי הוּא עֵד אֶחָד בִּלְבַד. וְדִינוֹ בְּעֵדוּת זוֹ כְּדִין כָּל אָדָם שֶׁהֲרֵי אֵינוֹ נוֹגֵעַ בְּעֵדוּתוֹ. לְפִיכָךְ אִם נָטַל הַדָּמִים מִשְּׁנַיִם וְנָטַל מֵאֶחָד מִדַּעְתּוֹ וּמֵאֶחָד בַּעַל כָּרְחוֹ וְלֹא יָדַע מִמִּי נָטַל מִדַּעְתּוֹ וּמִמִּי נָטַל בְּעַל כָּרְחוֹ. בֵּין שֶׁהָיָה הַמִּקָּח בְּיָדוֹ בֵּין שֶׁהָיוּ שְׁנֵיהֶן תּוֹפְסִין בּוֹ אֵין כָּאן עֵדוּת כְּלָל. וְכָל אֶחָד מֵהֶן נִשְׁבָּע בְּתַקָּנַת חֲכָמִים בִּנְקִיטַת חֵפֶץ וְנוֹטֵל חֲצִי הַמִּקָּח וַחֲצִי דָּמִים:","הֲרֵי שֶׁטָּעַן עַל חֲבֵרוֹ וְאָמַר מָכַרְתָּ לִי. וְזֶה אוֹמֵר לֹא מָכַרְתִּי. אוֹ מָכַרְתִּי וְלֹא נָתַתָּ לִי דָּמִים. אוֹ שֶׁטָּעַן הַלּוֹקֵחַ וְאָמַר שֶׁנָּתַן הַדָּמִים וַעֲדַיִן לֹא מָשַׁךְ. אוֹ מָשַׁכְתִּי וְלֹא רָאִיתִי מוּם זֶה. וְהַמּוֹכֵר אוֹמֵר לוֹ הוֹדַעְתִּיו לְךָ. אוֹ שֶׁאָמַר אֶחָד מֵהֶם כָּךְ וְכָךְ תְּנַאי הָיָה בֵּינֵינוּ וְהָאֶחָד אוֹמֵר לֹא הָיָה שָׁם תְּנַאי כְּלָל. בְּכָל אֵלּוּ הַטְּעָנוֹת וְכַיּוֹצֵא בָּהֶן הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","לֹא הָיְתָה שָׁם רְאָיָה. נִשְׁבַּע הַכּוֹפֵר שֶׁמְּבַקְּשִׁין לְהוֹצִיא מִיָּדוֹ שְׁבוּעַת הֶסֵּת. וְאִם הוֹדָה בְּמִקְצָת הַטַּעֲנָה אוֹ שֶׁיֵּשׁ עָלָיו עֵד אֶחָד נִשְׁבָּע שְׁבוּעַת הַתּוֹרָה כִּשְׁאָר הַטְּעָנוֹת כֻּלָּן:","אָמַר לְחֶנְוָנִי תֵּן לִי בְּדִינָר פֵּרוֹת וְנָתַן לוֹ וַהֲרֵי הַפֵּרוֹת מֻנָּחִין בִּרְשׁוּת הָרַבִּים. וְהַחֶנְוָנִי תּוֹבֵעַ אֶת הַדִּינָר וּבַעַל הַבַּיִת אוֹמֵר לוֹ נָתַתִּי לְךָ הַדָּמִים וְהִשְׁלַכְתָּ אוֹתָם לְתוֹךְ כִּיסְךָ. הֲרֵי הַלּוֹקֵחַ נִשְׁבָּע כְּתַקָּנַת חֲכָמִים בִּנְקִיטַת חֵפֶץ וְנוֹטֵל הַפֵּרוֹת הוֹאִיל וּכְבָר יָצְאוּ מֵרְשׁוּת הַמּוֹכֵר וַהֲרֵי הֵן בִּרְשׁוּת הָרַבִּים. וְאִלּוּ הָיוּ בִּרְשׁוּת הַלּוֹקֵחַ הָיָה נִשְׁבָּע שְׁבוּעַת הֶסֵּת וְנִפְטַר. וְאִלּוּ הָיוּ עֲדַיִן בִּרְשׁוּת הַחֶנְוָנִי הָיָה נִשְׁבָּע הֶסֵּת וְיִשָּׁאֲרוּ פֵּרוֹתָיו אֶצְלוֹ:","נָתַן הַלּוֹקֵחַ דִּינָר לְחֶנְוָנִי וּבָא לִטּל פֵּרוֹת הַמֻּנָּחִין בִּרְשׁוּת הָרַבִּים. וְאָמַר הַחֶנְוָנִי דִּינָר זֶה שֶׁנָּתַתָּ לִי עַכְשָׁו הוּא דְּמֵי פֵּרוֹת שֶׁכְּבָר נְתַתִּים לְךָ וְהוֹלַכְתָּם לְתוֹךְ בֵּיתְךָ אֲבָל פֵּרוֹת אֵלּוּ הַמֻּנָּחִין בִּרְשׁוּת הָרַבִּים לֹא מְכַרְתִּים לְךָ. הֲרֵי הַחֶנְוָנִי נִשְׁבָּע בִּנְקִיטַת חֵפֶץ שֶׁכָּךְ הָיָה הַדָּבָר וּמַחֲזִיר פֵּרוֹתָיו לָחֶנְוָנִי. שֶׁהֲרֵי לֹא הוֹדָה לוֹ שֶׁמְּכָרָן לוֹ מֵעוֹלָם. וְאִלּוּ הָיוּ בַּחֲנוּתוֹ הָיָה נִשְׁבָּע שְׁבוּעַת הֶסֵּת כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן הַדִּין בְּנוֹתֵן דִּינָר לְשֻׁלְחָנִי לִטּל מָעוֹת. בִּזְמַן שֶׁהַמָּעוֹת צְבוּרִין בִּרְשׁוּת הָרַבִּים. אִם הַשֻּׁלְחָנִי הוֹדָה שֶׁמְּכָרָן וַעֲדַיִן לֹא נָטַל הַדִּינָר נִשְׁבָּע הַלּוֹקֵחַ בִּנְקִיטַת חֵפֶץ שֶׁנָּתַן וְנוֹטֵל הַמָּעוֹת. וְאִם לֹא הוֹדָה שֶׁמְּכָרָן לוֹ אַף עַל פִּי שֶׁמּוֹדֶה שֶׁלָּקַח מִמֶּנּוּ דִּינָר עַתָּה וְטוֹעֵן שֶׁדִּינָר זֶה דְּמֵי הַמָּעוֹת שֶׁכְּבָר הוֹלִיכָן הַלּוֹקֵחַ לְתוֹךְ בֵּיתוֹ. הֲרֵי הַשֻּׁלְחָנִי נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְיַחְזִיר מְעוֹתָיו לַחֲנוּתוֹ:","הַמַּחְלִיף פָּרָה בַּחֲמוֹר וְיָלְדָה וְכֵן הַמּוֹכֵר שִׁפְחָתוֹ וְיָלְדָה. זֶה אוֹמֵר עַד שֶׁלֹּא מָכַרְתִּי יָלְדָה וְזֶה אוֹמֵר מִשֶּׁלָּקַחְתִּי יָלְדָה. אֲפִלּוּ אָמַר הַמּוֹכֵר אֵינִי יוֹדֵעַ. עַל הַלּוֹקֵחַ לְהָבִיא רְאָיָה. אַף עַל פִּי שֶׁהַפָּרָה עוֹמֶדֶת בַּאֲגַם וְהַשִּׁפְחָה עוֹמֶדֶת בְּסִמְטָא הֲרֵי הֵן בְּחֶזְקַת הַמּוֹכֵר עַד שֶׁיָּבִיא הַלּוֹקֵחַ רְאָיָה. לֹא הֵבִיא רְאָיָה יִשָּׁבַע הַמּוֹכֵר בִּנְקִיטַת חֵפֶץ עַל וְלַד הַפָּרָה. אֲבָל עַל וְלַד הַשִּׁפְחָה אֵינוֹ נִשְׁבָּע אֶלָּא הֶסֵּת. שֶׁאֵין נִשְׁבָּעִין בִּנְקִיטַת חֵפֶץ עַל הָעֲבָדִים וְלֹא עַל הַקַּרְקָעוֹת. כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת טוֹעֵן וְנִטְעָן:","זֶה אוֹמֵר אֵינִי יוֹדֵעַ וְזֶה אוֹמֵר אֵינִי יוֹדֵעַ וְאֵינָם בִּרְשׁוּת אֶחָד מֵהֶן יַחֲלֹקוּ. זֶה אוֹמֵר בִּרְשׁוּתִי יָלְדָה וְהָאַחֵר שׁוֹתֵק זָכָה הַטּוֹעֵן בַּוָּלָד:","מִי שֶׁהָיוּ לוֹ שְׁנֵי עֲבָדִים קָטָן וְגָדוֹל. אוֹ שְׁתֵּי שָׂדוֹת אַחַת גְּדוֹלָה וְאַחַת קְטַנָּה. הַלּוֹקֵחַ אוֹמֵר גְּדוֹלָה לָקַחְתִּי וְהַמּוֹכֵר אוֹמֵר קְטַנָּה הִיא שֶׁלָּקַחְתָּ. עַל הַלּוֹקֵחַ לְהָבִיא רְאָיָה. אוֹ יִשָּׁבַע הַמּוֹכֵר הֶסֵּת שֶׁלֹּא מָכַר אֶלָּא קָטָן:","אָמַר הַלּוֹקֵחַ גָּדוֹל לָקַחְתִּי וְהַמּוֹכֵר שׁוֹתֵק זָכָה הַלּוֹקֵחַ בַּגָּדוֹל. וְאִם אָמַר הַמּוֹכֵר אֵינִי יוֹדֵעַ עַל הַלּוֹקֵחַ לְהָבִיא רְאָיָה. אוֹ נִשְׁבָּע הַמּוֹכֵר הֶסֵּת שֶׁאֵינוֹ יוֹדֵעַ וְאֵין לָזֶה אֶלָּא קָטָן:","כָּל מִי שֶׁנּוֹלַד הַסָּפֵק בִּרְשׁוּתוֹ עָלָיו לְהָבִיא רְאָיָה. כֵּיצַד. הַמַּחְלִיף פָּרָה בַּחֲמוֹר וּמָשַׁךְ בַּעַל הַחֲמוֹר אֶת הַפָּרָה וְלֹא הִסְפִּיק בַּעַל הַפָּרָה לִמְשֹׁךְ זֶה הַחֲמוֹר עַד שֶׁמֵּת הַחֲמוֹר עַל בַּעַל הַחֲמוֹר לְהָבִיא רְאָיָה שֶׁהָיָה חֲמוֹרוֹ קַיָּם בִּשְׁעַת מְשִׁיכַת הַפָּרָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מַחַט הַנִּמְצָא בָּעֳבִי בֵּית הַכּוֹסוֹת וְנִקְּבָה אוֹתוֹ נֶקֶב מְפֻלָּשׁ. אִם נִמְצָא עָלֶיהָ קֹרֶט דָּם בְּיָדוּעַ שֶׁזּוֹ נִטְרְפָה קֹדֶם שְׁחִיטָה. לְפִיכָךְ אִם הִגְלִיד פִּי הַמַּכָּה בְּיָדוּעַ שֶׁזּוֹ נִטְרְפָה שְׁלֹשָׁה יָמִים קֹדֶם שְׁחִיטָה. לֹא הִגְלִיד פִּי הַמַּכָּה הֲרֵי הַדָּבָר סָפֵק וְעַל הַטַּבָּח לְהָבִיא רְאָיָה שֶׁקֹּדֶם לְקִיחָתוֹ נִטְרְפָה. שֶׁהֲרֵי בִּרְשׁוּתוֹ נוֹלַד הַסָּפֵק. וְאִם לֹא הֵבִיא רְאָיָה יְשַׁלֵּם הַדָּמִים לַמּוֹכֵר כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Sales 4":["כֶּלִיוֹ שֶׁל אָדָם כָּל מָקוֹם שֶׁיֵּשׁ לוֹ רְשׁוּת לְהַנִּיחוֹ קָנָה לוֹ. כֵּיוָן שֶׁנִּכְנְסוּ הַמִּטַּלְטְלִין בְּתוֹךְ הַכְּלִי אֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ וַהֲרֵי זֶה כְּמוֹ שֶׁהִגְבִּיהָן אוֹ כְּמוֹ שֶׁהֻנְּחוּ בְּתוֹךְ בֵּיתוֹ. לְפִיכָךְ אֵין כֶּלְיוֹ שֶׁל אָדָם קוֹנֶה לוֹ בִּרְשׁוּת הָרַבִּים וְלֹא בִּרְשׁוּת הַמּוֹכֵר. אֶלָּא אִם אָמַר לוֹ הַמַּקְנֶה לֵךְ וּקְנֵה בִּכְלִי זֶה. וְכֵן אִם קָנָה הַכְּלִי תְּחִלָּה וְהִגְבִּיהוֹ וְאַחַר כָּךְ הִנִּיחוֹ שָׁם בִּרְשׁוּת הַמּוֹכֵר וְחָזַר וְקָנָה מִמֶּנּוּ הַפֵּרוֹת. כֵּיוָן שֶׁנִּכְנְסוּ בְּתוֹךְ כְּלִי זֶה קָנָה אוֹתָם. מִפְּנֵי שֶׁהֲנָאַת הַמּוֹכֵר בִּמְכִירַת הַכְּלִי אֵינוֹ מַקְפִּיד עַל מְקוֹמוֹ:","כְּשֵׁם שֶׁאֵין כֶּלְיוֹ שֶׁל לוֹקֵחַ קוֹנֶה לוֹ בִּרְשׁוּת מוֹכֵר כָּךְ אֵין כֶּלְיוֹ שֶׁל מוֹכֵר קוֹנֶה לַלּוֹקֵחַ אַף עַל פִּי שֶׁהוּא בִּרְשׁוּת הַלּוֹקֵחַ:","מְסִירָה אֵינָהּ קוֹנָה אֶלָּא בִּרְשׁוּת הָרַבִּים וּבְחָצֵר שֶׁאֵינָהּ שֶׁל שְׁנֵיהֶם. וְהַמְּשִׁיכָה אֵינָהּ קוֹנָה אֶלָּא בְּסִמְטָא אוֹ בְּחָצֵר שֶׁל שְׁנֵיהֶם. וְהַגְבָּהָה קוֹנָה בְּכָל מָקוֹם:","דָּבָר הַנִּקְנֶה בִּמְשִׁיכָה אִם הָיָה בִּרְשׁוּת הָרַבִּים וּמְשָׁכוֹ הַלּוֹקֵחַ לִרְשׁוּתוֹ אוֹ לְסִמְטָא. כֵּיוָן שֶׁהוֹצִיא מִקְצָת הַחֵפֶץ מֵרְשׁוּת הָרַבִּים קָנָה:","טָעוּן שֶׁל פֵּרוֹת שֶׁהָיָה מֻנָּח בִּרְשׁוּת הָרַבִּים וּמְשָׁכוֹ לוֹקֵחַ לִרְשׁוּתוֹ אוֹ לְסִמְטָא אַחַר שֶׁפָּסַק הַדָּמִים קָנָה אַף עַל פִּי שֶׁעֲדַיִן לֹא מָדַד. וְכֵן אִם מְדָדָן הַלּוֹקֵחַ בִּרְשׁוּת הָרַבִּים קָנָה רִאשׁוֹן רִאשׁוֹן בְּהַגְבָּהָה:","הָיָה מוֹכֵר מוֹדֵד לְתוֹךְ כֶּלְיוֹ שֶׁל לוֹקֵחַ לֹא קָנָה שֶׁאֵין כֶּלְיוֹ שֶׁל לוֹקֵחַ קוֹנֶה לוֹ בִּרְשׁוּת הָרַבִּים. הָיוּ הַפֵּרוֹת בִּרְשׁוּת הַלּוֹקֵחַ כֵּיוָן שֶׁקִּבֵּל עָלָיו הַמּוֹכֵר לִמְכֹּר קָנָה לוֹקֵחַ וְאַף עַל פִּי שֶׁעֲדַיִן לֹא מָדַד. הָיוּ בִּרְשׁוּת הַמּוֹכֵר אוֹ בִּרְשׁוּת הַמֻּפְקָדִין אֶצְלוֹ לֹא קָנָה הַלּוֹקֵחַ עַד שֶׁיַּגְבִּיהַּ הַפֵּרוֹת אוֹ עַד שֶׁיּוֹצִיאֵם מֵרְשׁוּתוֹ בִּשְׂכִירוּת מְקוֹמָן וְכַיּוֹצֵא בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיוּ הַפֵּרוֹת בְּסִמְטָא אוֹ בְּחָצֵר שֶׁל שְׁנֵיהֶם. וַאֲפִלּוּ הָיוּ בִּרְשׁוּת לוֹקֵחַ וְהָיוּ בְּתוֹךְ כֶּלְיוֹ שֶׁל מוֹכֵר וְקִבֵּל עָלָיו הַמּוֹכֵר לִמְכֹּר וְהִתְחִיל הַמּוֹכֵר לִמְדֹּד בְּתוֹךְ כֶּלְיוֹ שֶׁל מוֹכֵר. אִם אָמַר לוֹ כּוֹר בִּשְׁלֹשִׁים סֶלַע אֲנִי מוֹכֵר לְךָ יָכוֹל לַחְזֹר בּוֹ אֲפִלּוּ בִּסְאָה אַחֲרוֹנָה הוֹאִיל וַעֲדַיִן הַפֵּרוֹת בְּכֵלָיו וְלֹא גָּמַר כָּל הַמִּדָּה וְכֵלָיו שֶׁל מוֹכֵר אֵינוֹ קוֹנֶה לַלּוֹקֵחַ אַף עַל פִּי שֶׁהוּא בִּרְשׁוּת הַלּוֹקֵחַ. וְאִם אָמַר לוֹ כּוֹר בִּשְׁלֹשִׁים סְאָה בְּסֶלַע רִאשׁוֹן רִאשׁוֹן קָנָה שֶׁכֵּיוָן שֶׁפָּסְקוּ הַדָּמִים עַל כָּל סְאָה וּסְאָה כָּל סְאָה שֶׁיַּגְבִּיהַּ הַמּוֹכֵר וִיעָרֶה אוֹתָהּ נִגְמְרָה מְכִירָתָהּ. הוֹאִיל וְאֵין הַפֵּרוֹת בִּרְשׁוּת הַמּוֹכֵר וְלֹא בִּרְשׁוּת הַלּוֹקֵחַ. וְאִלּוּ לֹא הָיָה הַפֵּרוֹת בְּכֵלָיו שֶׁל מוֹכֵר כֵּיוָן שֶׁהֵן בִּרְשׁוּת לוֹקֵחַ קָנָה מִשֶּׁפָּסַק אַף עַל פִּי שֶׁלֹּא מָדַד כְּמוֹ שֶׁבֵּאַרְנוּ:","וְכֵן הַמּוֹכֵר יַיִן אוֹ שֶׁמֶן לַחֲבֵרוֹ בְּסִמְטָא אוֹ בְּחָצֵר שֶׁל שְׁנֵיהֶם אוֹ בִּרְשׁוּת לוֹקֵחַ. וְהָיְתָה הַמִּדָּה שֶׁל סַרְסוּר. עַד שֶׁלֹּא נִתְמַלֵּאת הַמִּדָּה הֲרֵי הֵן שֶׁל מוֹכֵר. מִשֶּׁנִּתְמַלֵּאת הַמִּדָּה הֲרֵי הֵן בִּרְשׁוּת לוֹקֵחַ. וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ:","וְכֵן פֵּרוֹת שֶׁהָיוּ צְבוּרִין בְּסִמְטָא אוֹ בְּחָצֵר שֶׁל שְׁנֵיהֶם וְהַמִּדָּה אֵינָהּ שֶׁל אֶחָד מֵהֶן וְהָיָה הַמּוֹכֵר מוֹדֵד. עַד שֶׁלֹּא נִתְמַלֵּאת הַמִּדָּה הֲרֵי הִיא בִּרְשׁוּת הַמּוֹכֵר. וּמִשֶּׁנִּתְמַלֵּאת הַמִּדָּה הֲרֵי הִיא בִּרְשׁוּת לוֹקֵחַ:","הָיְתָה הַמִּדָּה שֶׁל אֶחָד מֵהֶן. וְהָיוּ בָּהּ רְשָׁמִין לֵידַע חֶצְיָהּ. שְׁלִישָׁהּ. וּרְבִיעָהּ. וְכַיּוֹצֵא בָּהֶן. כֵּיוָן שֶׁהִגִּיעַ לְרשֶׁם מִן הָרְשָׁמִים קָנָה רִאשׁוֹן רִאשׁוֹן. וְאַף עַל פִּי שֶׁלֹּא נִתְמַלֵּאת הַמִּדָּה. שֶׁכָּל רשֶׁם מֵהֶם כְּמִדָּה בִּפְנֵי עַצְמָהּ. שֶׁהֲרֵי שֶׁל אֶחָד מֵהֶן הִיא הַמִּדָּה וְהוּא סוֹמֵךְ עַל הָרְשָׁמִים שֶׁבָּהּ:","זֶה כְּלָל גָּדוֹל יִהְיֶה בְּיָדְךָ. הַקּוֹנֶה אֶת הַמִּטַּלְטְלִין אִם פָּסַק הַדָּמִים וְאַחַר כָּךְ הִגְבִּיהַּ קָנָה. וְאִם הִגְבִּיהַּ תְּחִלָּה וְהִנִּיחַ וְאַחַר כָּךְ פָּסַק הַדָּמִים לֹא קָנָה בְּאוֹתָהּ הַגְבָּהָה עַד שֶׁיַּגְבִּיהַּ אַחַר שֶׁפָּסַק. אוֹ יִמְשֹׁךְ דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַגְבִּיהַ:","הָיָה דָּבָר הַנִּמְכָּר דָּמָיו קְצוּבִין וִידוּעִין וְהִגְבִּיהוֹ קָנָהוּ. אַף עַל פִּי שֶׁפָּסַק אַחַר שֶׁהִגְבִּיהַּ. וְהוּא הַדִּין בִּשְׁאָר דְּבָרִים שֶׁקּוֹנִין בָּהֶם אֶת הַמִּטַּלְטְלִין שֶׁצָּרִיךְ לִקְנוֹת בָּהֶם אַחַר שֶׁיִּפְסֹק הַדָּמִים. אֶלָּא אִם כֵּן דָּמָיו קְצוּבִין כְּמוֹ שֶׁבֵּאַרְנוּ:","לְפִיכָךְ הַמּוֹשֵׁךְ חַמָּרִים וּפוֹעֲלִים וְהִכְנִיסָן לְתוֹךְ בֵּיתוֹ. אִם מָדַד עַד שֶׁלֹּא פָּסַק הַדָּמִים אֲפִלּוּ הָיָה הַלּוֹקֵחַ הוּא הַמּוֹדֵד. אוֹ שֶׁפָּסַק הַדָּמִים וְאַחַר כָּךְ מָדַד הַמּוֹכֵר. שְׁנֵיהֶם יְכוֹלִין לַחְזֹר בָּהֶן. פֵּרְקָן הַלּוֹקֵחַ וְהִכְנִיסָן לְתוֹךְ בֵּיתוֹ. אִם פָּסַק הַדָּמִים וְאַחַר כָּךְ מָדַד הַמּוֹכֵר אֵין שְׁנֵיהֶם יְכוֹלִין לַחְזֹר בָּהֶן שֶׁהֲרֵי סָמְכָה דַּעְתּוֹ לִמְכֹּר. וְאִם מָדַד עַד שֶׁלֹּא פָּסַק שְׁנֵיהֶם יְכוֹלִין לַחְזֹר בָּהֶם שֶׁהֲרֵי לֹא סָמְכָה דַּעְתּוֹ עֲדַיִן לִמְכֹּר. וַאֲפִלּוּ מָדַד הַלּוֹקֵחַ:","הַנּוֹטֵל כֵּלִים מִן הָאֻמָּן עַל מְנָת לְבַקְּרָן. אִם הָיוּ דָּמָיו קְצוּבִין וְנֶאֱנַס בְּיָדוֹ חַיָּב בְּדָמָיו. הוֹאִיל וְדָמָיו קְצוּבִין מֵעֵת שֶׁהִגְבִּיהוֹ נַעֲשָׂה בִּרְשׁוּתוֹ. וְהוּא שֶׁיַּגְבִּיהֶנּוּ כְּדֵי לִקְנוֹת אֶת כֻּלּוֹ וְיִהְיֶה אוֹתוֹ חֵפֶץ הַנִּמְכָּר חָבִיב עַל הַלּוֹקֵחַ. אֲבָל חֵפֶץ שֶׁהַמּוֹכֵר קָץ בּוֹ וְהוּא מְבַקֵּשׁ וְרוֹדֵף לְמָכְרוֹ הֲרֵי הוּא בִּרְשׁוּת הַמּוֹכֵר עַד שֶׁיִּפְסֹק הַדָּמִים וְיַגְבִּיהֶנּוּ הַלּוֹקֵחַ אַחַר שֶׁפָּסַק:","אֶחָד הַמּוֹשֵׁךְ אוֹ הַמַּגְבִּיהַּ אוֹ הַמַּחֲזִיק בְּעַצְמוֹ אוֹ שֶׁאָמַר לְאַחֵר לְהַגְבִּיהַּ אוֹ לִמְשֹׁךְ לוֹ אוֹ לְהַחֲזִיק לוֹ הֲרֵי זֶה זָכָה לוֹ. וְכֵן בִּשְׁאָר דַּרְכֵי הַקְּנִיָּה:"],"Mishneh Torah, Sanctification of the New Month 15":["אִם תִּרְצֶה לֵידַע מְקוֹם הַיָּרֵח הָאֲמִתִּי בְּכָל יוֹם שֶׁתִּרְצֶה. תּוֹצִיא תְּחִלָּה אֶמְצַע הַיָּרֵחַ לִשְׁעַת הָרְאִיָּה לְאוֹתוֹ הַלַּיְלָה שֶׁתִּרְצֶה. וְכֵן תּוֹצִיא אֶמְצַע הַמַּסְלוּל וְאֶמְצַע הַשֶּׁמֶשׁ לְאוֹתוֹ הָעֵת. וְתִגְרַע אֶמְצַע הַשֶּׁמֶשׁ מֵאֶמְצַע הַיָּרֵחַ. וְהַנִּשְׁאָר תִּכְפּל אוֹתוֹ. וְזֶה הוּא הַנִּקְרָא מֶרְחָק הַכָּפוּל:","וּכְבָר הוֹדַעְנוּ שֶׁלֹּא בָּאנוּ בְּכָל אֵלּוּ הַחֶשְׁבּוֹנוֹת שֶׁעָשִׂינוּ בִּפְרָקִים אֵלּוּ אֶלָּא לָדַעַת רְאִיַּת הַיָּרֵחַ. וּלְעוֹלָם אִי אֶפְשָׁר שֶׁיִּהְיֶה מֶרְחָק זֶה הַכָּפוּל בְּלֵיל הָרְאִיָּה שֶׁיִּרְאֶה בָּהּ הַיָּרֵחַ אֶלָּא מֵחָמֵשׁ מַעֲלוֹת עַד ס\"ב מַעֲלוֹת. וְאִי אֶפְשָׁר שֶׁיּוֹסִיף עַל זֶה וְלֹא יִגְרַע מִמֶּנּוּ:","וְהוֹאִיל וְהַדָּבָר כֵּן. הִתְבּוֹנֵן בְּמֶרְחָק זֶה הַכָּפוּל. אִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל חָמֵשׁ מַעֲלוֹת אוֹ קָרוֹב לְחָמֵשׁ אֵין חוֹשְׁשִׁין לְתוֹסֶפֶת וְלֹא תּוֹסִיף כְּלוּם. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִשֵּׁשׁ מַעֲלוֹת עַד אַחַת עֶשְׂרֵה מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל מַעֲלָה אַחַת. וְאִם יִהְיֶה מֶרְחָק הַכָּפוּל מִשְּׁתֵּים עֶשְׂרֵה מַעֲלוֹת עַד י\"ח מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל שְׁתֵּי מַעֲלוֹת. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִי\"ט מַעֲלוֹת עַד כ\"ד מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל שָׁלֹשׁ מַעֲלוֹת. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִכ\"ה מַעֲלוֹת עַד ל\"א מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל ד' מַעֲלוֹת. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִל\"ב מַעֲלוֹת עַד ל\"ח מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל ה' מַעֲלוֹת. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִל\"ט מַעֲלוֹת עַד מ\"ה מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל שֵׁשׁ מַעֲלוֹת. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִמ\"ו מַעֲלוֹת עַד נ\"א מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל שֶׁבַע מַעֲלוֹת. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִנ\"ב מַעֲלוֹת עַד נ\"ט מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל ח' מַעֲלוֹת. וְאִם יִהְיֶה הַמֶּרְחָק הַכָּפוּל מִס' מַעֲלוֹת עַד ס\"ג מַעֲלוֹת תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל ט' מַעֲלוֹת. וּמַה שֶּׁיִּהְיֶה אֶמְצַע הַמַּסְלוּל אַחַר שֶׁתּוֹסִיף עָלָיו מַעֲלוֹת אֵלּוּ הוּא הַנִּקְרָא מַסְלוּל הַנָּכוֹן:","וְאַחַר כָּךְ תִּרְאֶה כַּמָּה מַעֲלוֹת הוּא הַמַּסְלוּל הַנָּכוֹן. אִם הָיָה פָּחוֹת מִק\"פ מַעֲלוֹת תִּגְרַע מְנַת הַמַּסְלוּל הַזֶּה הַנָּכוֹן מֵאֶמְצַע הַיָּרֵחַ לִשְׁעַת הָרְאִיָּה. וְאִם הָיָה הַמַּסְלוּל הַנָּכוֹן יוֹתֵר עַל ק\"פ מַעֲלוֹת עַד ש\"ס תּוֹסִיף מְנַת זֶה הַמַּסְלוּל הַנָּכוֹן עַל אֶמְצַע הַיָּרֵחַ לִשְׁעַת הָרְאִיָּה. וּמַה שֶּׁיִּהְיֶה הָאֶמְצַע אַחַר שֶׁתּוֹסִיף עָלָיו אוֹ תִּגְרַע מִמֶּנּוּ הוּא מְקוֹם הַיָּרֵחַ הָאֲמִתִּי לִשְׁעַת הָרְאִיָּה:","וְדַע שֶׁאִם יִהְיֶה הַמַּסְלוּל הַנָּכוֹן ק\"פ בְּשָׁוֶה אוֹ ש\"ס בְּשָׁוֶה אֵין לוֹ מָנָה. אֶלָּא יִהְיֶה מְקוֹם הַיָּרֵחַ הָאֶמְצָעִי לִשְׁעַת הָרְאִיָּה הוּא מָקוֹם הָאֲמִתִּי:","וְכַמָּה הִיא מְנַת הַמַּסְלוּל. אִם יִהְיֶה הַמַּסְלוּל הַנָּכוֹן עֶשֶׂר מַעֲלוֹת תִּהְיֶה מְנָתוֹ נ' חֲלָקִים. וְאִם יִהְיֶה הַמַּסְלוּל הַנָּכוֹן כ' מַעֲלוֹת תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְל\"ח חֲלָקִים. וְאִם יִהְיֶה שְׁלֹשִׁים תִּהְיֶה מְנָתוֹ שְׁתֵּי מַעֲלוֹת וְכ\"ד חֲלָקִים. וְאִם יִהְיֶה מ' תִּהְיֶה מְנָתוֹ שָׁלֹשׁ מַעֲלוֹת וְשִׁשָּׁה חֲלָקִים. וְאִם יִהְיֶה נ' תִּהְיֶה מְנָתוֹ שָׁלֹשׁ מַעֲלוֹת וּמ\"ד חֲלָקִים. וְאִם יִהְיֶה ס' תִּהְיֶה מְנָתוֹ אַרְבַּע מַעֲלוֹת וְט\"ז חֲלָקִים. וְאִם יִהְיֶה ע' תִּהְיֶה מְנָתוֹ אַרְבַּע מַעֲלוֹת וּמ\"א חֲלָקִים. וְאִם יִהְיֶה פ' תִּהְיֶה מְנָתוֹ חָמֵשׁ מַעֲלוֹת. וְאִם יִהְיֶה צ' תִּהְיֶה מְנָתוֹ חָמֵשׁ מַעֲלוֹת וְה' חֲלָקִים. וְאִם יִהְיֶה ק' תִּהְיֶה מְנָתוֹ ה' מַעֲלוֹת וְח' חֲלָקִים. וְאִם יִהְיֶה ק\"י תִּהְיֶה מְנָתוֹ ד' מַעֲלוֹת וְנ\"ט חֲלָקִים. וְאִם יִהְיֶה ק\"כ תִּהְיֶה מְנָתוֹ ד' מַעֲלוֹת וְכ' חֲלָקִים. וְאִם יִהְיֶה ק\"ל תִּהְיֶה מְנָתוֹ ד' מַעֲלוֹת וְי\"א חֲלָקִים. וְאִם יִהְיֶה ק\"מ תִּהְיֶה מְנָתוֹ ג' מַעֲלוֹת וְל\"ג חֲלָקִים. וְאִם יִהְיֶה ק\"נ תִּהְיֶה מְנָתוֹ שָׁלֹשׁ מַעֲלוֹת וּמ\"ח חֲלָקִים. וְאִם יִהְיֶה ק\"ס תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְנ\"ו חֲלָקִים. וְאִם יִהְיֶה ק\"ע תִּהְיֶה מְנָתוֹ מַעֲלָה אַחַת וְנ\"ט חֲלָקִים. וְאִם יִהְיֶה ק\"פ בְּשָׁוֶה אֵין לוֹ מָנָה כְּמוֹ שֶׁאָמַרְנוּ אֶלָּא מְקוֹם הַיָּרֵחַ הָאֶמְצָעִי הוּא הַמָּקוֹם הָאֲמִתִּי:","וְאִם יִהְיֶה הַמַּסְלוּל הַנָּכוֹן יוֹתֵר עַל ק\"פ מַעֲלוֹת. תִּגְרַע אוֹתוֹ מִש\"ס וְתֵדַע מְנָתוֹ כְּדֶרֶךְ שֶׁעָשִׂיתָ בְּמַסְלוּל הַשֶּׁמֶשׁ. וְכֵן אִם יִהְיוּ בְּמִנְיַן הַמַּסְלוּל אֲחָדִים עִם הָעֲשָׂרוֹת תִּקַּח מִן הַיּוֹתֵר שֶׁבֵּין שְׁתֵּי הַמָּנוֹת הָאֲחָדִים. כְּדֶרֶךְ שֶׁבֵּאַרְנוּ בְּמַסְלוּל הַשֶּׁמֶשׁ בַּמָּנוֹת שֶׁלּוֹ כָּךְ תַּעֲשֶׂה בַּמַּסְלוּל הַנָּכוֹן בַּמָּנוֹת שֶׁלּוֹ:","כֵּיצַד. הֲרֵי שֶׁרָצִינוּ לֵידַע מְקוֹם הַיָּרֵחַ הָאֲמִתִּי בִּתְחִלַּת לֵיל עֶרֶב שַׁבָּת שֶׁיּוֹמוֹ שֵׁנִי לְחֹדֶשׁ אִיָּר מִשָּׁנָה זוֹ שֶׁהִיא שְׁנַת הָעִקָּר. וּמִנְיַן הַיָּמִים הַגְּמוּרִים מִתְּחִלַּת לֵיל הָעִקָּר עַד תְּחִלַּת לַיִל זֶה שֶׁאָנוּ רוֹצִים לֵידַע מְקוֹם הַיָּרֵחַ הָאֲמִתִּי בּוֹ כ\"ט יוֹם. תּוֹצִיא אֶמְצַע הַשֶּׁמֶשׁ תְּחִלַּת לַיִל זֶה. יֵצֵא לְךָ אֶמְצָעוֹ ל\"ה מַעֲלוֹת וְל\"ח חֲלָקִים וְל\"ג שְׁנִיּוֹת. סִימָנָם ל\"ה ל\"ח ל\"ג. וְתוֹצִיא אֶמְצַע הַיָּרֵחַ לִשְׁעַת הָרְאִיָּה לְעֵת זוֹ. יֵצֵא לְךָ אֶמְצָעוֹ נ\"ג מַעֲלוֹת וְל\"ו חֲלָקִים וְל\"ט שְׁנִיּוֹת. סִימָנָם נ\"ג ל\"ו ל\"ט. וְתוֹצִיא אֶמְצַע הַמַּסְלוּל לְעֵת זוֹ יֵצֵא לְךָ אֶמְצָעוֹ ק\"ג מַעֲלוֹת וְכ\"א חֲלָקִים וּמ\"ו שְׁנִיּוֹת. סִימָנָם ק\"ג כ\"א מ\"ו. תִּגְרַע אֶמְצַע הַשֶּׁמֶשׁ מֵאֶמְצַע הַיָּרֵחַ יִשָּׁאֵר י\"ז מַעֲלוֹת וְנ\"ח חֲלָקִים וְשֵׁשׁ שְׁנִיּוֹת. וְזֶה הוּא הַמֶּרְחָק. תִּכְפּל אוֹתוֹ יֵצֵא לְךָ הַמֶּרְחָק הַכָּפוּל ל\"ה מַעֲלוֹת וְנ\"ו חֲלָקִים וְי\"ב שְׁנִיּוֹת. סִימָנָם ל\"ה נ\"ו י\"ב. לְפִיכָךְ תּוֹסִיף עַל אֶמְצַע הַמַּסְלוּל חָמֵשׁ מַעֲלוֹת כְּמוֹ שֶׁהוֹדַעְנוּ וְיֵצֵא לְךָ הַמַּסְלוּל הַנָּכוֹן ק\"פ מַעֲלוֹת וְכ\"א חֲלָקִים. וְאֵין מַקְפִּידִין עַל הַחֲלָקִים בְּמַסְלוּל כְּדֶרֶךְ שֶׁבֵּאַרְנוּ בַּשֶּׁמֶשׁ:","וּבָאנוּ לַחְקֹר עַל מְנַת זֶה הַמַּסְלוּל הַנָּכוֹן שֶׁהוּא ק\"ח נִמְצֵאת מָנָה שֶׁלּוֹ חָמֵשׁ מַעֲלוֹת וְחֵלֶק אֶחָד. וּלְפִי שֶׁהַמַּסְלוּל הַנָּכוֹן הָיָה פָּחוֹת מִק\"פ תִּגְרַע הַמָּנָה שֶׁהוּא חָמֵשׁ מַעֲלוֹת וְחֵלֶק אֶחָד מִן אֶמְצַע הַיָּרֵחַ. יִשָּׁאֵר מ\"ח מַעֲלוֹת וְל\"ג חֲלָקִים וְל\"ט שְׁנִיּוֹת. תַּעֲשֶׂה הַשְּׁנִיּוֹת חֵלֶק וְתוֹסִיף עַל הַחֲלָקִים. וְנִמְצָא מְקוֹם הַיָּרֵחַ הָאֲמִתִּי בְּשָׁעָה זוֹ בְּמַזַּל שׁוֹר בְּי\"ח מַעֲלוֹת וְל\"ו חֲלָקִים מִמַּעֲלַת י\"ט. סִימָנָם י\"ח ל\"ו. וְעַל הַדֶּרֶךְ הַזֶּה תֵּדַע מְקוֹם הַיָּרֵחַ הָאֲמִתִּי בְּכָל עֵת רְאִיָּה שֶׁתִּרְצֶה מִתְּחִלַּת שָׁנָה זוֹ שֶׁהִיא הָעִקָּר עַד סוֹף הָעוֹלָם:"],"Mishneh Torah, Sanctification of the New Month 9":["שְׁנַּת הַחַמָּה יֵשׁ מֵחַכְמֵי יִשְׂרָאֵל שֶׁאוֹמְרִים שֶׁהִיא שְׁסַ\"ה יוֹם וּרְבִיעַ יוֹם שֶׁהוּא שֵׁשׁ שָׁעוֹת. וְיֵשׁ מֵהֶן שֶׁאוֹמְרִים שֶׁהוּא פָּחוֹת מֵרְבִיעַ הַיּוֹם. וְכֵן חַכְמֵי יָוָן וּפָרַס יֵשׁ בֵּינֵיהֶן מַחֲלֹקֶת בְּדָבָר זֶה:","מִי שֶׁהוּא אוֹמֵר שֶׁהִיא שְׁסַ\"ה יוֹם וּרְבִיעַ יוֹם. יִשָּׁאֵר מִכָּל מַחֲזוֹר שֶׁל תְּשַׁע עֶשְׂרֵה שָׁנָה שָׁעָה אַחַת וְתפ\"ה חֲלָקִים כְּמוֹ שֶׁאָמַרְנוּ. וְיִהְיֶה בֵּין תְּקוּפָה לִתְקוּפָה אֶחָד וְתִשְׁעִים יוֹם וְשֶׁבַע שָׁעוֹת וַחֲצִי שָׁעָה. וּמִשֶּׁתֵּדַע תְּקוּפָה אַחַת בְּאֵי זֶה יוֹם בְּאֵיזוֹ שָׁעָה הִיא תַּתְחִיל לִמְנוֹת מִמֶּנָּה לַתְּקוּפָה הַשְּׁנִיָּה שֶׁאַחֲרֶיהָ וּמִן הַשְּׁנִיָּה לַשְּׁלִישִׁית עַד סוֹף הָעוֹלָם:","תְּקוּפַת נִיסָן הִיא הַשָּׁעָה וְהַחֵלֶק שֶׁתִּכָּנֵס בּוֹ הַשֶּׁמֶשׁ בְּרֹאשׁ מַזַּל טָלֶה. וּתְקוּפַת תַּמּוּז הֱיוֹת הַשֶּׁמֶשׁ בְּרֹאשׁ מַזַּל סַרְטָן. וּתְקוּפַת תִּשְׁרֵי הֱיוֹת הַשֶּׁמֶשׁ בְּרֹאשׁ מַזַּל מֹאזְנַיִם. וּתְקוּפַת טֵבֵת הֱיוֹת הַשֶּׁמֶשׁ בְּרֹאשׁ מַזַּל גְּדִי. וּתְקוּפַת נִיסָן הָיְתָה בַּשָּׁנָה הָרִאשׁוֹנָה שֶׁל יְצִירָה לְפִי חֶשְׁבּוֹן זֶה קֹדֶם מוֹלַד נִיסָן בְּשִׁבְעָה יָמִים וְתֵשַׁע שָׁעוֹת וְתרמ\"ב חֲלָקִים, סִימָנָהּ ז\"ט תרמ\"ב:","דֶּרֶךְ חֶשְׁבּוֹן הַתְּקוּפָה כָּךְ הִיא. תֵּדַע תְּחִלָּה כַּמָּה מַחֲזוֹרִין שְׁלֵמִים מִשְּׁנַת הַיְצִירָה עַד מַחֲזוֹר שֶׁתִּרְצֶה. וְקַח לְכָל מַחֲזוֹר מֵהֶן שָׁעָה אַחַת וְתפ\"ה חֲלָקִים. קַבֵּץ כָּל הַחֲלָקִים שָׁעוֹת וְכָל הַשָּׁעוֹת יָמִים וְתִגְרַע מִן הַכּל שִׁבְעָה יָמִים וְתֵשַׁע שָׁעוֹת וְתרמ\"ב חֲלָקִים. וְהַשְּׁאָר תּוֹסִיף אוֹתוֹ עַל מוֹלַד נִיסָן שֶׁל שָׁנָה רִאשׁוֹנָה מִן הַמַּחֲזוֹר. יֵצֵא לְךָ בְּאֵי זוֹ שָׁעָה וּבְכַמָּה בַּחֹדֶשׁ תִּהְיֶה תְּקוּפַת נִיסָן שֶׁל אוֹתָהּ הַשָּׁנָה מִן הַמַּחֲזוֹר. וּמִמֶּנָּה תַּתְחִיל לִמְנוֹת אֶחָד וְתִשְׁעִים יוֹם וְשֶׁבַע שָׁעוֹת וּמֶחֱצָה לְכָל תְּקוּפָה וּתְקוּפָה. וְאִם תִּרְצֶה לֵידַע תְּקוּפַת נִיסָן שֶׁל שָׁנָה זוֹ שֶׁהִיא שְׁנַת כָּךְ וְכָךְ בַּמַּחֲזוֹר שֶׁאַתָּה עוֹמֵד בּוֹ. קַח לְכָל הַמַּחֲזוֹרִין הַשְּׁלֵמִים שָׁעָה וְתפ\"ה לְכָל מַחֲזוֹר. וּלְכָל הַשָּׁנִים הַגְּמוּרוֹת שֶׁשָּׁלְמוּ מִן הַמַּחֲזוֹר עֲשָׂרָה יָמִים וְכ\"א שָׁעוֹת וְר\"ד חֲלָקִים לְכָל שָׁנָה וְקַבֵּץ הַכּל. וְתִגְרַע מִמֶּנּוּ ז' יָמִים וְט' שָׁעוֹת וְתרמ\"ב חֲלָקִים. וְהַשְּׁאָר תַּשְׁלִיכֵם חָדְשֵׁי הַלְּבָנָה כ\"ט יוֹם וְי\"ב שָׁעוֹת וְז' מֵאוֹת וְצ\"ג חֲלָקִים. וְהַנִּשְׁאָר פָּחוֹת מֵחֹדֶשׁ הַלְּבָנָה תּוֹסִיף אוֹתוֹ עַל מוֹלַד נִיסָן שֶׁל אוֹתָהּ הַשָּׁנָה. וְתֵדַע זְמַן תְּקוּפַת נִיסָן שֶׁל אוֹתָהּ הַשָּׁנָה בְּכַמָּה יוֹם בַּחֹדֶשׁ הִיא וּבְכַמָּה שָׁעָה. תְּקוּפַת נִיסָן לְפִי חֶשְׁבּוֹן זֶה אֵינָהּ לְעוֹלָם אֶלָּא אוֹ בִּתְחִלַּת הַלַּיְלָה אוֹ בַּחֲצִי הַלַּיְלָה אוֹ בִּתְחִלַּת הַיּוֹם אוֹ בַּחֲצִי הַיּוֹם. וּתְקוּפַת תַּמּוּז לְעוֹלָם אֵינָהּ אֶלָּא אוֹ בְּז' שָׁעוֹת וּמֶחֱצָה אוֹ בְּשָׁעָה אַחַת וּמֶחֱצָה בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. וּתְקוּפַת תִּשְׁרֵי לְעוֹלָם אֵינָהּ אֶלָּא אוֹ בְּט' שָׁעוֹת אוֹ בְּג' שָׁעוֹת בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. וּתְקוּפַת טֵבֵת לְעוֹלָם אֵינָהּ אֶלָּא אוֹ בְּי' שָׁעוֹת וּמֶחֱצָה אוֹ בְּאַרְבַּע שָׁעוֹת וּמֶחֱצָה בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. אִם תִּרְצֶה לֵידַע בְּאֵי זֶה יוֹם מִימֵי הַשָּׁבוּעַ וּבְאֵי זוֹ שָׁעָה תִּהְיֶה הַתְּקוּפָה. קַח שָׁנִים גְּמוּרוֹת שֶׁעָבְרוּ מִשְּׁנַת הַיְצִירָה עַד שָׁנָה שֶׁתִּרְצֶה וְהַשְׁלֵךְ הַכּל כ\"ח כ\"ח וְהַנִּשְׁאָר יוֹתֵר מִכ\"ח קַח לְכָל שָׁנָה יוֹם אֶחָד ו' שָׁעוֹת. וְקַבֵּץ הַכּל וְהוֹסֵיף עָלָיו ג' וְהַשְׁלֵךְ הַכּל ז' ז'. וְהַנִּשְׁאָר מִן הַיָּמִים וּמִן הַשָּׁעוֹת תַּתְחִיל לִמְנוֹת מִתְּחִלַּת לֵיל אֶחָד בְּשַׁבָּת וְלַאֲשֶׁר יַגִּיעַ הַחֶשְׁבּוֹן בּוֹ תִּהְיֶה תְּקוּפַת נִיסָן. וְלָמָּה מוֹסִיפִין שְׁלֹשָׁה לְפִי שֶׁתְּקוּפָה רִאשׁוֹנָה שֶׁל שְׁנַת הַיְצִירָה הָיְתָה בִּתְחִלַּת לֵיל רְבִיעִי:","כֵּיצַד. הֲרֵי שֶׁרָצִינוּ לֵידַע תְּקוּפַת נִיסָן שֶׁל שְׁנַת תְּשַׁע מֵאוֹת שְׁלֹשִׁים וְאַרְבַּעַת אֲלָפִים לַיְצִירָה. כְּשֶׁתַּשְׁלִיךְ הַכּל כ\"ח כ\"ח תִּשָּׁאֵר שָׁנָה אַחַת. תִּקַּח לָהּ יוֹם אֶחָד וְשֵׁשׁ שָׁעוֹת וְתוֹסִיף עָלָיו ג' נִמְצֵאת תְּקוּפַת נִיסָן בְּלֵיל חֲמִישִׁי שֵׁשׁ שָׁעוֹת בַּלַּיְלָה. וּכְשֶׁתּוֹסִיף עָלֶיהָ שֶׁבַע שָׁעוֹת וּמֶחֱצָה הֲרֵי תִּהְיֶה תְּקוּפַת תַּמּוּז בְּשָׁעָה וּמֶחֱצָה מִיּוֹם ה'. וּכְשֶׁתּוֹסִיף עָלֶיהָ שֶׁבַע שָׁעוֹת וּמֶחֱצָה תִּהְיֶה תְּקוּפַת תִּשְׁרֵי בְּט' שָׁעוֹת מִיּוֹם ה'. וּכְשֶׁתּוֹסִיף עָלֶיהָ שֶׁבַע שָׁעוֹת וּמֶחֱצָה תִּהְיֶה תְּקוּפַת טֵבֵת בְּד' שָׁעוֹת וּמֶחֱצָה מִלֵּיל ז'. וּכְשֶׁתּוֹסִיף עָלֶיהָ שֶׁבַע שָׁעוֹת וּמֶחֱצָה תִּהְיֶה תְּקוּפַת נִיסָן הַבָּאָה בִּתְחִלַּת יוֹם ו'. וְעַל דֶּרֶךְ זוֹ עַד סוֹף הָעוֹלָם תְּקוּפָה אַחַר תְּקוּפָה:","אִם תִּרְצֶה לֵידַע בְּכַמָּה יוֹם בַּחֹדֶשׁ תִּהְיֶה תְּקוּפַת נִיסָן שֶׁל שָׁנָה זוֹ. תֵּדַע תְּחִלָּה בְּאֵי זֶה יוֹם מִימֵי הַשָּׁבוּעַ תִּהְיֶה וּבְאֵי זֶה יוֹם יִקְבְּעוּ נִיסָן שֶׁל שָׁנָה זוֹ וְכַמָּה שָׁנִים גְּמוּרוֹת עָבְרוּ מִן הַמַּחֲזוֹר. וְתִקַּח לְכָל שָׁנָה אַחַד עָשָׂר יוֹם וְתוֹסִיף עַל סִכּוּם הַיָּמִים ז' יָמִים בִּזְמַנִּים אֵלּוּ. וְהַשְׁלֵךְ הַכּל ל' ל' וְהַנִּשְׁאָר פָּחוֹת מִל' תַּתְחִיל לִמְנוֹתוֹ מֵרֹאשׁ חֹדֶשׁ נִיסָן. אִם יַגִּיעַ לְיוֹם הַתְּקוּפָה מוּטָב וְאִם לָאו הוֹסֵיף יוֹם אוֹ שְׁנֵי יָמִים אוֹ שְׁלֹשָׁה יָמִים עַל הַמִּנְיָן עַד שֶׁיַּגִּיעַ לְיוֹם הַתְּקוּפָה. וְאִם תִּהְיֶה הַשָּׁנָה מְעֵבֶּרֶת תַּתְחִיל לִמְנוֹת מֵרֹאשׁ חֹדֶשׁ אֲדָר שֵׁנִי וְלַיּוֹם שֶׁיַּגִּיעַ הַחֶשְׁבּוֹן בְּאוֹתוֹ הַיּוֹם מִן הַחֹדֶשׁ תִּהְיֶה הַתְּקוּפָה:","כֵּיצַד. הֲרֵי שֶׁרָצִינוּ לֵידַע בְּכַמָּה בַּחֹדֶשׁ תִּהְיֶה תְּקוּפַת נִיסָן שֶׁל שְׁנַת תתק\"ל. שֶׁהִיא שָׁנָה תְּשִׁיעִית מִמַּחֲזוֹר ר\"ס. מָצָאנוּ רֹאשׁ חֹדֶשׁ נִיסָן נִקְבָּע בָּהּ בַּחֲמִישִׁי וּתְקוּפַת נִיסָן בַּחֲמִישִׁי. וּלְפִי שֶׁהָיְתָה שָׁנָה זוֹ תְּשִׁיעִית לַמַּחֲזוֹר יִהְיוּ הַשָּׁנִים הַגְּמוּרוֹת שְׁמוֹנֶה. כְּשֶׁתִּקַּח לְכָל שָׁנָה מֵהֶן י\"א יוֹם יִהְיוּ כָּל הַיָּמִים פ\"ח. תּוֹסִיף ז' הֲרֵי הַכּל צ\"ה. תַּשְׁלִיךְ הַכּל ל' ל' נִשְׁאֲרוּ ה' יָמִים. כְּשֶׁתַּתְחִיל לִמְנוֹת ה' יָמִים מֵרֹאשׁ חֹדֶשׁ נִיסָן שֶׁהָיָה בַּחֲמִישִׁי יַגִּיעַ הַחֶשְׁבּוֹן לְיוֹם שֵׁנִי. וּכְבָר יָדַעְנוּ שֶׁאֵין הַתְּקוּפָה בְּשֵׁנִי בְּשַׁבָּת אֶלָּא בַּחֲמִישִׁי. לְפִיכָךְ תּוֹסִיף יוֹם אַחַר יוֹם עַד שֶׁתַּגִּיעַ לַחֲמִישִׁי שֶׁהוּא יוֹם הַתְּקוּפָה. נִמְצֵאת תְּקוּפַת נִיסָן בְּשָׁנָה זוֹ בְּיוֹם שְׁמִינִי מֵחֹדֶשׁ נִיסָן. וְעַל הַדֶּרֶךְ הַזֹּאת תַּעֲשֶׂה בְּכָל שָׁנָה וְשָׁנָה:","זֶה שֶׁאָמַרְנוּ תּוֹסִיף יוֹם אַחַר יוֹם עַד שֶׁתַּגִּיעַ לְיוֹם הַתְּקוּפָה. לְעוֹלָם לֹא תִּהְיֶה צָרִיךְ לְהוֹסִיף אֶלָּא יוֹם אֶחָד אוֹ ב' אוֹ ג'. וּפֶלֶא גָּדוֹל הוּא שֶׁתִּהְיֶה צָרִיךְ לְהוֹסִיף אַרְבָּעָה יָמִים. וְאִם מָצָאתָ שֶׁאַתָּה צָרִיךְ לְהוֹסִיף עַל זֶה תֵּדַע שֶׁטָּעִיתָ בַּחֶשְׁבּוֹן וְתַחֲזֹר וְתַחְשֹׁב בְּדִקְדּוּק:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 6":["מְעוֹת חֻלִּין וּמְעוֹת מַעֲשֵׂר שֶׁנִּתְפַּזְּרוּ וְלִקֵּט מִיכַּן וּמִיכַּן. מַה שֶּׁלִּקֵּט לִקֵּט לְמַעֲשֵׂר עַד שֶׁיַּשְׁלִים. וְהַשְּׁאָר חֻלִּין. וְאִם בָּלַל וְחָפַן אוֹ שֶׁלִּקֵּט מִצַּד אֶחָד וּמָצָא חָסֵר הֲרֵי זֶה לְפִי חֶשְׁבּוֹן. כֵּיצַד. הָיוּ מָאתַיִם מַעֲשֵׂר שֵׁנִי וּמֵאָה חֻלִּין. נִתְפַּזְּרוּ וּבְלָלָן וְחָפַן הַכּל נִמְצְאוּ מָאתַיִם וְשִׁבְעִים. הֲרֵי מֵאָה וּשְׁמוֹנִים מֵהֶן מַעֲשֵׂר וְתִשְׁעִים חֻלִּין. זֶה הַכְּלָל הַמִּתְלַקְּטִין לְמַעֲשֵׂר שֵׁנִי וְהַנִּבְלָלִין לְפִי חֶשְׁבּוֹן. מַתְנֶה וְאוֹמֵר אִם אֵלּוּ שֶׁבְּיָדִי הֵן הַמַּעֲשֵׂר הַשְּׁאָר חֻלִּין. וְאִם הֵן חֻלִּין הֲרֵי מְעוֹת הַמַּעֲשֵׂר בְּכָל מָקוֹם שֶׁהֵן מְחֻלָּלִין עֲלֵיהֶם:","סֶלַע שֶׁל מַעֲשֵׂר שֵׁנִי וְשֶׁל חֻלִּיִן שֶׁנִּתְעָרְבוּ מֵבִיא בַּסֶּלַע מָעוֹת וַאֲפִלּוּ מְעוֹת נְחשֶׁת וְאוֹמֵר סֶלַע שֶׁל מַעֲשֵׂר שֵׁנִי בְּכָל מָקוֹם שֶׁהִיא מְחֻלֶּלֶת עַל הַמָּעוֹת הָאֵלּוּ. וְאַחַר כָּךְ בּוֹרֵר אֶת הַיָּפֶה שֶׁבִּשְׁתֵּיהֶן וּמְחַלֵּל הַמָּעוֹת שֶׁל נְחשֶׁת עָלֶיהָ וְתַחֲזֹר הַסֶּלַע הַיָּפָה לְמַעֲשֵׂר:","הָאוֹמֵר לִבְנוֹ מַעֲשֵׂר שֵׁנִי בְּזָוִית זוֹ וְנִמְצָא בְּזָוִית אַחֶרֶת הֲרֵי אֵלּוּ חֻלִּין. אָמַר לוֹ הֲרֵי שָׁם מָנֶה וְנִמְצָא מָאתַיִם הַשְּׁאָר חֻלִּין. הֲרֵי שָׁם מָאתַיִם וְנִמְצָא מָנֶה הֲרֵי הוּא חֻלִּין. הִנִּיחַ מָנֶה מַעֲשֵׂר וְנִמְצָא מָאתַיִם. מָאתַיִם וְנִמְצָא מָנֶה. אֲפִלּוּ הֵן בִּשְׁנֵי כִּיסִין הַכּל חֻלִּין:","אָמַר לוֹ אָבִיו כִּיס מַעֲשֵׂר שֵׁנִי לִי בַּבַּיִת. הָלַךְ וּמָצָא שָׁם שְׁלֹשָׁה כִּיסִים. הַגָּדוֹל שֶׁבְּכֻלָּן מַעֲשֵׂר וְהַשְּׁאָר חֻלִּין. וְאַף עַל פִּי כֵן לֹא יֹאכַל מִן הַקְּטַנִּים עַד שֶׁיְּחַלְּלֵם עַל הַגָּדוֹל:","מִי שֶׁנִּשְׁתַּתֵּק וְאָמְרוּ לוֹ מַעֲשֵׂר שֵׁנִי שֶׁלְּךָ בְּמָקוֹם פְּלוֹנִי. וְהִרְכִּין בְּרֹאשׁוֹ. בּוֹדְקִין אוֹתוֹ שָׁלֹשׁ פְּעָמִים כְּדֶרֶךְ שֶׁבּוֹדְקִין לְגִטִּין וַהֲרֵי דְּבָרָיו קַיָּמִין:","אָמְרוּ לוֹ בַּחֲלוֹם מַעֲשֵׂר שֵׁנִי שֶׁל אָבִיךָ שֶׁאַתָּה מְבַקֵּשׁ הֲרֵי הוּא בְּמָקוֹם פְּלוֹנִי. אַף עַל פִּי שֶׁמָּצָא שָׁם מַה שֶּׁנֶּאֱמַר לוֹ אֵינוֹ מַעֲשֵׂר. דִּבְרֵי חֲלוֹמוֹת לֹא מַעֲלִין וְלֹא מוֹרִידִין:","הָאוֹמֵר לְבָנָיו אֲפִלּוּ אַתֶּם מֵתִים אַל תִּגְּעוּ בְּזָוִית זוֹ. וְנִמְצְאוּ שָׁם מָעוֹת הֲרֵי אֵלּוּ חֻלִּין. טָמַן מָעוֹת מִפְּנֵיהֶם וְאָמַר לָהֶם שֶׁל פְּלוֹנִי הֵן אוֹ שֶׁל מַעֲשֵׂר שֵׁנִי הֵן. אִם כְּמַעֲרִים אֵין חוֹשְׁשִׁין לִדְבָרָיו. וְאִם כְּמִתְכַּוֵּן דְּבָרָיו קַיָּמִין:","הַמּוֹצֵא כְּלִי וְכָתוּב עָלָיו מ' הֲרֵי מַה שֶּׁבְּתוֹכוֹ מַעֲשֵׂר שֵׁנִי. ד' דְּמַאי. ט' טֶבֶל. ת' תְּרוּמָה. ק' קָרְבָּן. וְאִם הָיָה שֶׁל מַתֶּכֶת הוּא וּמַה שֶּׁבְּתוֹכוֹ קָרְבָּן. שֶׁכֵּן הָיוּ כּוֹתְבִין אוֹת אַחַת מִן הַשֵּׁם בִּשְׁעַת הַסַּכָּנָה:","מָעוֹת הַנִּמְצָאוֹת בִּירוּשָׁלַיִם אֲפִלּוּ דִּינְרֵי זָהָב עִם הַכֶּסֶף וְעִם הַמָּעוֹת הֲרֵי אֵלּוּ חֻלִּין. הוֹאִיל וְשׁוּקֵי יְרוּשָׁלַיִם מִתְכַּבְּדִין בְּכָל יוֹם. מָצָא בְּתוֹכָן חֶרֶס וְכָתוּב בּוֹ מַעֲשֵׂר הֲרֵי אֵלּוּ מַעֲשֵׂר שֵׁנִי. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר יְמוֹת הַשָּׁנָה. אֲבָל בָּרֶגֶל הַכּל מַעֲשֵׂר:","מָעוֹת הַנִּמְצָאוֹת לִפְנֵי סוֹחֲרֵי בְּהֵמָה בִּירוּשָׁלַיִם לְעוֹלָם מַעֲשֵׂר. שֶׁחֶזְקַת רֹב הָעָם מְבִיאִין מְעוֹת מַעֲשֵׂר וְקוֹנִין בּוֹ בְּהֵמוֹת. וְהַנִּמְצָאוֹת בְּהַר הַבַּיִת לְעוֹלָם חֻלִּין. שֶׁחֶזְקָתָן מִתְּרוּמַת הַלִּשְׁכָּה שֶׁחִלְּלוּם הַגִּזְבָּרִין עַל בְּהֵמָה:","תֵּבָה שֶׁנִּשְׁתַּמֵּשׁ בָּהּ חֻלִּין וּמַעֲשֵׂר שֵׁנִי. וְנִמְצָא בְּתוֹכָהּ מָעוֹת. אִם רֹב מַנִּיחִין מַעֲשֵׂר הֲרֵי הַמָּעוֹת מַעֲשֵׂר. וְאִם רֹב מַנִּיחִין חֻלִּין חֻלִּין. מֶחֱצָה לְמֶחֱצָה חֻלִּין:","מָצָא פֵּרוֹת בֵּין פֵּרוֹת מַעֲשֵׂר לְפֵרוֹת תְּרוּמָה יִפְּלוּ לַקָּרוֹב. מֶחֱצָה לְמֶחֱצָה יֵאָכְלוּ כְּחֻמְרֵי שְׁנֵיהֶן. אֲסוּרִין לְזָרִים וּטְעוּנִין רְחִיצַת יָדַיִם וְהַעֲרֵב שֶׁמֶשׁ כִּתְרוּמָה. וַאֲסוּרִים לְאוֹנֵן וּטְעוּנִים הֲבָאַת מָקוֹם כְּמַעֲשֵׂר. וְכֵן הַמָּעוֹת הַנִּמְצָאוֹת בֵּין חֻלִּין לְמַעֲשֵׂר:","מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי וְשֶׁל וַדַּאי שֶׁנִּתְעָרְבוּ יֵאָכְלוּ כְּחָמוּר שֶׁבָּהֶן:","פֵּרוֹת מַעֲשֵׂר שֶׁנִּתְעָרְבוּ בְּפֵרוֹת חֻלִּין יֹאכַל הַכּל בְּטָהֳרָה בַּמָּקוֹם אוֹ יִפְדֶּה אֶת הַמַּעֲשֵׂר. לְפִיכָךְ אִם נִתְעָרְבוּ בִּירוּשָׁלַיִם אֲסוּרִין בְּכָל שֶׁהֵן כְּמִנְיָן. הוֹאִיל וְהוּא בִּירוּשָׁלַיִם הֲרֵי הוּא כְּדָבָר שֶׁיֵּשׁ לוֹ מַתִּירִין. וְיֵאָכֵל הַכּל בְּטָהֳרָה:","הַזּוֹרֵעַ מַעֲשֵׂר שֵׁנִי אַחַר שֶׁנִּכְנַס לִירוּשָׁלַיִם הַגִּדּוּלִים מַעֲשֵׂר שֵׁנִי. זְרָעוֹ קֹדֶם שֶׁיִּכָּנֵס הַגִּדּוּלִין חֻלִּין. וַאֲפִלּוּ בְּדָבָר שֶׁאֵין זַרְעוֹ כָּלֶה. וּפוֹדִין אוֹתוֹ בִּשְׁעַת זְרִיעָתוֹ:","מַעֲשֵׂר שֵׁנִי בָּטֵל בְּרֹב. בְּאֵיזֶה מַעֲשֵׂר אָמְרוּ בְּמַעֲשֵׂר שֶׁנִּכְנַס לִירוּשָׁלַיִם וְיָצָא וְנָפְלוּ מְחִצּוֹת. שֶׁהֲרֵי אֵין שָׁם מְחִצּוֹת לְהַחֲזִירוֹ לְשָׁם וְאִי אֶפְשָׁר לִפְדּוֹתוֹ מֵאַחַר שֶׁנִּכְנַס וְאַף עַל פִּי שֶׁאֵין בּוֹ שְׁוֵה פְּרוּטָה וְנִמְצָא דָּבָר שֶׁאֵין לוֹ מַתִּירִין וּבָטֵל בְּרֹב כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִסּוּרֵי מַאֲכָלוֹת:"],"Mishneh Torah, Sheqel Dues 4":["תְּרוּמַת הַלִּשְׁכָּה מַה יֵּעָשֶׂה בָּהּ. לוֹקְחִין מִמֶּנָּה תְּמִידִין שֶׁל כָּל יוֹם וְהַמּוּסָפִין וְכָל קָרְבְּנוֹת הַצִּבּוּר וְנִסְכֵּיהֶם וְהַמֶּלַח שֶׁמּוֹלְחִין בּוֹ כָּל הַקָּרְבָּנוֹת. וְכֵן הָעֵצִים אִם לֹא הֵבִיאוּ עֵצִים וְלֹא נִמְצְאוּ אֶלָּא בְּדָמִים. וְהַקְּטֹרֶת וּשְׂכַר עֲשִׂיָּתָהּ. וְלֶחֶם הַפָּנִים וּשְׂכַר עוֹשֵׂי לֶחֶם הַפָּנִים. וְהָעֹמֶר וּשְׁתֵּי הַלֶּחֶם וּפָרָה אֲדֻמָּה וְשָׂעִיר הַמִּשְׁתַּלֵּחַ וְלָשׁוֹן שֶׁל זְהוֹרִית שֶׁקּוֹשְׁרִין בֵּין קַרְנָיו. כָּל אֵלּוּ בָּאִין מִתְּרוּמַת הַלִּשְׁכָּה:","אֲבָל פַּר הֶעְלֵם דָּבָר שֶׁל צִבּוּר וּשְׂעִירֵי עֲבוֹדַת כּוֹכָבִים בַּתְּחִלָּה גּוֹבִין לָהֶן וְאֵינָן בָּאִין מִתְּרוּמַת הַלִּשְׁכָּה. פָּרוֹכוֹת שֶׁל הֵיכָל תַּחַת בִּנְיָן עֲשׂוּיוֹת וְאֵינָן בָּאִין מִתְּרוּמַת הַלִּשְׁכָּה אֶלָּא מִקָּדְשֵׁי בֶּדֶק הַבַּיִת. אֲבָל פָּרוֹכוֹת שֶׁל שְׁעָרִים בָּאִין מִתְּרוּמַת הַלִּשְׁכָּה. הַמְּנוֹרָה וּכְלֵי שָׁרֵת מִצְוָתָן שֶׁיָּבוֹאוּ מִמּוֹתַר הַנְּסָכִים. וּבְהִלְכוֹת כְּלֵי הַמִּקְדָּשׁ וְהָעוֹבְדִים בּוֹ יִתְבָּאֵר מַה הוּא מוֹתַר הַנְּסָכִים. וְאִם לֹא הָיָה לָהֶן מוֹתַר נְסָכִים יָבִיאוּ מִתְּרוּמַת הַלִּשְׁכָּה. בִּגְדֵי כְּהֻנָּה בֵּין בִּגְדֵי כֹּהֵן גָּדוֹל בֵּין שְׁאָר בִּגְדֵי הַכֹּהֲנִים שֶׁעוֹבְדִין בָּהֶן בַּמִּקְדָּשׁ הַכּל מִתְּרוּמַת הַלִּשְׁכָּה:","כָּל הַבְּהֵמוֹת הַנִּמְצָאוֹת בִּירוּשָׁלַיִם אוֹ בְּחוּצָה לָהּ בְּקָרוֹב מִמֶּנָּה בָּאוֹת עוֹלוֹת כְּמוֹ שֶׁיִּתְבָּאֵר בִּפְסוּלֵי הַמֻּקְדָּשִׁין. נִסְכֵּיהֶן בָּאִין מִתְּרוּמַת הַלִּשְׁכָּה. וְכֵן עוֹבֵד כּוֹכָבִים שֶׁשָּׁלַח עוֹלָתוֹ מִמְּדִינָה אַחֶרֶת וְלֹא שָׁלַח עִמָּהּ דְּמֵי נְסָכִים יָבִיאוּ נִסְכֵּיהֶם מִתְּרוּמַת הַלִּשְׁכָּה:","גֵּר שֶׁמֵּת וְהִנִּיחַ זְבָחִים אִם יֵשׁ לוֹ נְסָכִים קְרֵבִין מִשֶּׁלּוֹ וְאִם לָאו בָּאִין מִתְּרוּמַת הַלִּשְׁכָּה. כֹּהֵן גָּדוֹל שֶׁמֵּת וְלֹא מִנּוּ אַחֵר תַּחְתָּיו מַקְרִיבִין אֶת הַחֲבִיתִין מִתְּרוּמַת הַלִּשְׁכָּה. מְבַקְּרֵי מוּמִים שֶׁבִּירוּשָׁלַיִם וְתַלְמִידֵי חֲכָמִים הַמְלַמְּדִים הִלְכוֹת שְׁחִיטָה לַכֹּהֲנִים וְהִלְכוֹת קְמִיצָה וְנָשִׁים הַמְגַדְּלוֹת בְּנֵיהֶן לְפָרָה אֲדֻמָּה כֻּלָּן נוֹטְלִין שְׂכָרָן מִתְּרוּמַת הַלִּשְׁכָּה. וְכַמָּה הוּא שְׂכָרָן. כְּמוֹ שֶׁיִּפְסְקוּ לָהֶן בֵּית דִּין:","בִּשְׁנַת הַשְּׁמִטָּה שֶׁהִיא הֶפְקֵר שׂוֹכְרִין בֵּית דִּין שׁוֹמְרִין שֶׁיִּשְׁמְרוּ מִקְצָת סְפִיחִים שֶׁצָּמְחוּ כְּדֵי שֶׁיָּבִיאוּ מֵהֶן הָעֹמֶר וּשְׁתֵּי הַלֶּחֶם שֶׁאֵין בָּאִים אֶלָּא מִן הֶחָדָשׁ. וְאֵלּוּ הַשּׁוֹמְרִין נוֹטְלִין שְׂכָרָן מִתְּרוּמַת הַלִּשְׁכָּה:","מִי שֶׁהִתְנַדֵּב לִשְׁמֹר בְּחִנָּם אֵין שׁוֹמְעִין לוֹ מִשּׁוּם בַּעֲלֵי זְרוֹעַ שֶׁמָּא יָבוֹאוּ וְיִטְּלוּם מֵהֶן. לְפִיכָךְ תִּקְּנוּ לָהֶם חֲכָמִים שֶׁיִּטְּלוּ שָׂכָר מִן הַלִּשְׁכָּה כְּדֵי שֶׁיִּפְרְשׁוּ הַכּל מֵאוֹתוֹ מָקוֹם שֶׁאֵלּוּ שׁוֹמְרִים שָׁם:","מַגִּיהֵי סְפָרִים שֶׁבִּירוּשָׁלַיִם וְדַיָּנִין שֶׁדָּנִין אֶת הַגַּזְלָנִין בִּירוּשָׁלַיִם נוֹטְלִין שְׂכָרָן מִתְּרוּמַת הַלִּשְׁכָּה. וְכַמָּה הָיוּ נוֹטְלִים תִּשְׁעִים מָנֶה בְּכָל שָׁנָה. וְאִם לֹא הִסְפִּיקוּ לָהֶן אַף עַל פִּי שֶׁלֹּא רָצוּ מוֹסִיפִין לָהֶן כְּדֵי צָרְכָּן הֵם וּנְשֵׁיהֶם וּבְנֵיהֶם וּבְנֵי בֵּיתָן:","כֶּבֶשׁ הָיוּ בּוֹנִין מֵהַר הַבַּיִת לְהַר הַמִּשְׁחָה שֶׁעָלָיו מוֹצִיאִין פָּרָה אֲדֻמָּה. וְכֶבֶשׁ שֶׁמּוֹצִיאִין עָלָיו שָׂעִיר הַמִּשְׁתַּלֵּחַ. וּשְׁנֵיהֶם נַעֲשִׂין מִשְּׁיָרֵי הַלִּשְׁכָּה. וְכֵן מִזְבַּח הָעוֹלָה וְהַהֵיכָל וְהָעֲזָרוֹת נַעֲשִׂין מִשְּׁיָרֵי הַלִּשְׁכָּה. אַמַּת הַמַּיִם שֶׁבִּירוּשָׁלַיִם וְחוֹמַת יְרוּשָׁלַיִם וְכָל מִגְדְּלוֹתֶיהָ וְכָל צָרְכֵי הָעִיר בָּאִין מִשְּׁיָרֵי הַלִּשְׁכָּה. וְעוֹבֵד כּוֹכָבִים שֶׁהִתְנַדֵּב מָעוֹת לַדְּבָרִים הָאֵלּוּ אוֹ לַעֲשׂוֹת עִמָּהֶם בְּחִנָּם אֵין מְקַבְּלִין מִמֶּנּוּ וַאֲפִלּוּ גֵּר תּוֹשָׁב. שֶׁנֶּאֱמַר (עזרא ד ג) \"לֹא לָכֶם וָלָנוּ לִבְנוֹת\" וְגוֹ' וְנֶאֱמַר (נחמיה ב כ) \"וְלָכֶם אֵין חֵלֶק\" וְגוֹ':","מוֹתַר תְּרוּמַת הַלִּשְׁכָּה וּשְׁיָרֵי הַלִּשְׁכָּה לוֹקְחִין בּוֹ זְכָרִים וִיקָרְבוּ כֻּלָּן עוֹלוֹת שֶׁתְּנַאי בֵּית דִּין הוּא עַל כָּל הַמּוֹתָרוֹת שֶׁיִּקְרְבוּ עוֹלַת בְּהֵמָה. אֲבָל לֹא עוֹלַת הָעוֹף שֶׁאֵין בְּקָרְבְּנוֹת הַצִּבּוּר עוֹף. וְאֵלּוּ הָעוֹלוֹת הַבָּאִין מִמּוֹתַר הַשְּׁקָלִים הֵם הַנִּקְרָאִים קַיִץ לַמִּזְבֵּחַ:","שְׁקָלִים שֶׁלֹּא הִסְפִּיקוּ לָהֶן לְכָל קָרְבְּנוֹת הַצִּבּוּר מוֹצִיאִין אֶת הָרָאוּי לָהֶם מִקָּדְשֵׁי בֶּדֶק הַבַּיִת. אֲבָל אֵין בֶּדֶק הַבַּיִת מוֹצִיא אֶת הָרָאוּי לוֹ מִקָּדְשֵׁי הַמִּזְבֵּחַ:","מִשֶּׁיַגִּיעַ רֹאשׁ חֹדֶשׁ נִיסָן אֵין מַקְרִיבִין קָרְבְּנוֹת צִבּוּר אֶלָּא מִתְּרוּמָה חֲדָשָׁה. וְאִם לֹא בָּאָה הַחֲדָשָׁה לוֹקְחִין מִן הַיְשָׁנָה. לְפִיכָךְ אִם הִגִּיעַ רֹאשׁ חֹדֶשׁ נִיסָן וְיֵשׁ עִמָּהֶן בְּהֵמוֹת לִתְמִידִים מִתְּרוּמָה יְשָׁנָה פּוֹדִין אוֹתָן וְיוֹצְאִין לְחֻלִּין אַף עַל פִּי שֶׁהֵן תְּמִימִין וְיִפְּלוּ דְּמֵיהֶן לִתְרוּמָה יְשָׁנָה שֶׁמְּקִיצִין בָּהּ אֶת הַמִּזְבֵּחַ. שֶׁתְּנַאי בֵּית דִּין הוּא עַל כָּל הַבְּהֵמוֹת שֶׁלּוֹקְחִין לִתְמִידִין שֶׁאִם לֹא יִהְיוּ צְרִיכִין לָהֶן יֵצְאוּ לְחֻלִּין:","וְכָךְ הָיוּ עוֹשִׂין בְּמוֹתַר הַקְּטֹרֶת. מִשֶּׁיַגִּיעַ רֹאשׁ חֹדֶשׁ נִיסָן מְחַלְּלִין אוֹתוֹ עַל שְׂכַר הָאֻמָּנִין וְחוֹזְרִין מָעוֹת הַשָּׂכָר לְקֵיץ הַמִּזְבֵּחַ וְנוֹטְלִין הָאֻמָּנִין מוֹתַר הַקְּטֹרֶת בִּשְׂכָרָן וְחוֹזְרִין וְלוֹקְחִין אֶת הַקְּטֹרֶת מֵהֶן מִתְּרוּמָה חֲדָשָׁה כְּדֵי לְהַקְרִיבָהּ מִמְּעוֹת תְּרוּמָה חֲדָשָׁה. וְאִם אֵין לָהֶן תְּרוּמָה חֲדָשָׁה מַקְטִירִין אוֹתָהּ מִתְּרוּמָה יְשָׁנָה: סָלִיק לְהוּ הִלְכוֹת שְׁקָלִים"],"Mishneh Torah, Slaves 4":["אָמָה הָעִבְרִיָּה הִיא הַקְּטַנָּה שֶׁמְּכָרָהּ אָבִיהָ. וּמִשֶּׁתָּבִיא שְׁתֵּי שְׂעָרוֹת אַחַר שְׁתֵּים עֶשְׂרֵה שָׁנָה וְתֵעָשֶׂה נַעֲרָה אֵינוֹ יָכוֹל לְמָכְרָהּ אַף עַל פִּי שֶׁעֲדַיִן יֵשׁ לוֹ רְשׁוּת בָּהּ. וְיֵשׁ לוֹ לְקַדְּשָׁהּ לְכָל מִי שֶׁיִּרְצֶה. אַף הַקְּטַנָּה שֶׁהִיא אַיְלוֹנִית בְּסִימָנֶיהָ וְאֵינָהּ רְאוּיָה לַהֲבָאַת שְׁתֵּי שְׂעָרוֹת יֵשׁ לְאָבִיהָ לְמָכְרָהּ כָּל זְמַן שֶׁהִיא קְטַנָּה. אֲבָל הַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס אֵינוֹ נִמְכָּר לֹא כְּעֶבֶד עִבְרִי וְלֹא כְּדִין הָאָמָה הָעִבְרִיָּה:","אֵין הָאָב רַשַּׁאי לִמְכֹּר אֶת בִּתּוֹ אֶלָּא אִם כֵּן הֶעֱנִי וְלֹא נִשְׁאַר לוֹ כְּלוּם לֹא קַרְקַע וְלֹא מִטַּלְטְלִין וַאֲפִלּוּ כְּסוּת שֶׁעָלָיו. וְאַף עַל פִּי כֵן כּוֹפִין אֶת הָאָב לִפְדּוֹתָהּ אַחַר שֶׁמְּכָרָהּ מִשּׁוּם פְּגַם מִשְׁפָּחָה. בָּרַח הָאָב אוֹ שֶׁמֵּת אוֹ שֶׁלֹּא הָיָה לוֹ לִפְדּוֹתָהּ הֲרֵי זוֹ עוֹבֶדֶת עַד שֶׁתֵּצֵא:","אָמָה הָעִבְרִיָּה נִקְנֵית בְּכֶסֶף אוֹ בִּשְׁוֵה כֶּסֶף וּבִשְׁטָר וְאֵינָהּ נִקְנֵית בִּפְרוּטָה מִפְּנֵי שֶׁצָּרִיךְ לִקְנוֹתָהּ בְּדָמִים שֶׁרְאוּיִין לְגֵרָעוֹן כְּדֵי שֶׁתִּגְרַע פִּדְיוֹנָהּ וְתֵצֵא. כֵּיצַד בִּשְׁטָר. כּוֹתֵב עַל הַנְּיָר אוֹ עַל הַחֶרֶס בִּתִּי מְכוּרָה לְךָ בִּתִּי קְנוּיָה לְךָ וְנוֹתֵן בְּיַד הָאָדוֹן. וּשְׁטַר אָמָה הָעִבְרִיָּה הָאָב כּוֹתְבוֹ:","אָמָה הָעִבְרִיָּה עוֹבֶדֶת שֵׁשׁ שָׁנִים כְּעֶבֶד שֶׁמְּכָרוּהוּ בֵּית דִּין שֶׁנֶּאֱמַר (דברים טו יב) \"כִּי יִמָּכֵר לְךָ אָחִיךָ הָעִבְרִי אוֹ הָעִבְרִיָּה\". וְיוֹצֵאת בִּתְחִלַּת שֶׁבַע. וְאִם פָּגַע בָּהּ יוֹבֵל בְּתוֹךְ שֵׁשׁ יוֹצְאָה חִנָּם כְּעֶבֶד. מֵת הָאָדוֹן אַף עַל פִּי שֶׁהִנִּיחַ בֶּן יוֹצְאָה חִנָּם כְּנִרְצָע שֶׁנֶּאֱמַר (דברים טו יז) \"וְאַף לַאֲמָתְךָ תַּעֲשֶׂה כֵּן\". וְכֵן מְגָרַעַת מִפִּדְיוֹנָהּ וְיוֹצְאָה. וְאִם כָּתַב לָהּ שְׁטַר שִׁחְרוּר וּמָחַל עַל הַשְּׁאָר יוֹצְאָה חִנָּם כְּעֶבֶד:","יְתֵרָה אָמָה הָעִבְרִיָּה שֶׁהִיא יוֹצְאָה בְּסִימָנִין. כֵּיצַד. כְּגוֹן שֶׁהֵבִיאָה סִימָנִין וְנַעֲשֵׂית נַעֲרָה יוֹצְאָה לְחֵרוּת בְּלֹא כֶּסֶף אֲפִלּוּ הֵבִיאָה סִימָנִין מֵאַחַר יוֹם שֶׁלְּקָחָהּ הֲרֵי זוֹ יוֹצֵאת לְחֵרוּת שֶׁנֶּאֱמַר (שמות כא יא) \"וְיָצְאָה חִנָּם\" רִבָּה לָהּ הַכָּתוּב יְצִיאָה אַחֶרֶת בְּחִנָּם יֶתֶר עַל הָעֶבֶד. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהִיא הֲבָאַת סִימָנֵי נַעֲרוּת. וְתַחְזֹר לִרְשׁוּת אָבִיהָ עַד שֶׁתִּבְגֹּר וְתֵצֵא מֵרְשׁוּת אָבִיהָ. הָיְתָה הַבַּת אַיְלוֹנִית שֶׁאֵין לָהּ יְמֵי נַעֲרוּת אֶלָּא יוֹצֵאת מִקַּטְנוּתָהּ לְבֶגֶר כֵּיוָן שֶׁבָּגְרָה תֵּצֵא לְחֵרוּת:","אֵין אָמָה הָעִבְרִיָּה יוֹצְאָה בְּרָאשֵׁי אֵיבָרִים שֶׁנֶּאֱמַר (שמות כא ז) \"לֹא תֵצֵא כְּצֵאת הָעֲבָדִים\". וְכֵן עֶבֶד עִבְרִי אִם הִפִּיל לוֹ שִׁנּוֹ אוֹ סִמֵּא לוֹ עֵינוֹ מְשַׁלֵּם לוֹ כְּדִין הַחוֹבֵל בַּחֲבֵרוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת חוֹבֵל. נִמְצֵאתָ לָמֵד שֶׁאָמָה הָעִבְרִיָּה נִקְנֵית בִּשְׁנֵי דְּבָרִים בְּכֶסֶף אוֹ בִּשְׁטָר. וְקוֹנָה עַצְמָהּ בְּשִׁשָּׁה דְּבָרִים בְּשָׁנִים וּבְיוֹבֵל וּבְגִרְעוֹן כֶּסֶף וּבִשְׁטַר שִׁחְרוּר וּבְמִיתַת הָאָדוֹן וּבְסִימָנִין:","יִעֵד אוֹתָהּ הָאָדוֹן לְעַצְמוֹ אוֹ לִבְנוֹ הֲרֵי הִיא כִּשְׁאָר אֲרוּסוֹת וְאֵינָהּ יוֹצְאָה בְּאֶחָד מִכָּל אֵלּוּ אֶלָּא בְּמִיתַת הַבַּעַל אוֹ בְּגֵט. וּמִצְוַת יִעוּד קוֹדֶמֶת לְמִצְוַת פְּדִיָּה. כֵּיצַד מִצְוַת יִעוּד. אוֹמֵר לָהּ בִּפְנֵי שְׁנַיִם הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי הֲרֵי אַתְּ מְאֹרֶסֶת לִי הֲרֵי אַתְּ לִי לְאִשָּׁה אֲפִלּוּ בְּסוֹף שֵׁשׁ סָמוּךְ לִשְׁקִיעַת הַחַמָּה. וְאֵינוֹ צָרִיךְ לִתֵּן לָהּ כְּלוּם שֶׁמָּעוֹת הָרִאשׁוֹנוֹת לְקִדּוּשִׁין נִתְּנוּ וְנוֹהֵג בָּהּ מִנְהַג אִישׁוּת וְאֵינוֹ נוֹהֵג בָּהּ מִנְהַג שְׁפָחוֹת. וְאֵינוֹ מְיַעֵד שְׁתַּיִם כְּאַחַת שֶׁנֶּאֱמַר (שמות כא ח) \"יְעָדָהּ\". וְכֵיצַד מְיַעֲדָהּ לִבְנוֹ. אִם הָיָה בְּנוֹ גָּדוֹל וְנָתַן רְשׁוּת לְאָבִיו לְיַעֲדָהּ לוֹ הֲרֵי הָאָב אוֹמֵר לָהּ בִּפְנֵי שְׁנַיִם הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִבְנִי:","אֵין הָאָדוֹן מְיַעֵד אָמָה הָעִבְרִיָּה לֹא לוֹ וְלֹא לִבְנוֹ אֶלָּא מִדַּעְתָּהּ אַף עַל פִּי שֶׁכְּבָר קִבֵּל אָבִיהָ מְעוֹתֶיהָ שֶׁהֲרֵי הוּא אוֹמֵר (שמות כא ח) \"יְעָדָהּ\" מִדַּעְתָּהּ. וְאִם מֵת הָאָדוֹן אֵין בְּנוֹ יוּכַל לְיַעֲדָהּ לוֹ שֶׁהֲרֵי יוֹצְאָה לְחֵרוּת בְּמִיתַת הָאָדוֹן:","הַיִּעוּד כְּאֵרוּסִין וְאֵינוֹ כְּנִשּׂוּאִין לְפִיכָךְ אֵינוֹ מִתְטַמֵּא לָהּ וְלֹא יִירָשֶׁנָּה וְלֹא מֵפֵר נְדָרֶיהָ עַד שֶׁתִּכָּנֵס לְחֻפָּה. (שמות כא יא) \"וְאִם שְׁלָשׁ אֵלֶּה לֹא יַעֲשֶׂה לָהּ\", לֹא יִעֲדָהּ לוֹ וְלֹא יִעֲדָהּ לִבְנוֹ וְלֹא נִפְדֵּית בְּגִרְעוֹן כֶּסֶף, וְיָצְאָה חִנָּם בַּהֲבָאַת סִימָנִין כְּמוֹ שֶׁבֵּאַרְנוּ:","יֶתֶר עַל אוֹתָן הַדְּרָכִים שֶׁקּוֹנָה בָּהֶן עַצְמָהּ כְּעֶבֶד עִבְרִי. אֵין הָאָדוֹן יָכוֹל לִמְכֹּר אָמָה הָעִבְרִיָּה וְלֹא לִתְּנָהּ לְאִישׁ אַחֵר בֵּין רָחוֹק בֵּין קָרוֹב וְאִם מָכַר אוֹ נָתַן לֹא עָשָׂה כְּלוּם שֶׁנֶּאֱמַר (שמות כא ח) \"לְעַם נָכְרִי לֹא יִמְשׁל לְמָכְרָהּ בְּבִגְדוֹ בָהּ\". וְכֵן עֶבֶד עִבְרִי לֹא יָכוֹל לְמָכְרוֹ לְאַחֵר וְלֹא לִתְּנוֹ. וְיֵרָאֶה לִי שֶׁלֹּא הֻצְרַךְ הַכָּתוּב לֶאֱסֹר דָּבָר זֶה [בְּאָמָה] אֶלָּא מִפְּנֵי שֶׁיֵּשׁ לוֹ לְיַעֲדָהּ לִבְנוֹ לְכָךְ נֶאֱמַר לְעַם נָכְרִי לֹא יִמְשׁל לְמָכְרָהּ:","אֵין אָמָה הָעִבְרִיָּה נִמְכֶּרֶת אֶלָּא לְמִי שֶׁיֵּשׁ לָהּ עָלָיו אוֹ לִבְנוֹ קִדּוּשִׁין כְּדֵי שֶׁתְּהֵא רְאוּיָה לְיִעוּד. כֵּיצַד. מוֹכֵר אָדָם אֶת בִּתּוֹ לְאָבִיו שֶׁאַף עַל פִּי שֶׁאֵין הָאָדוֹן יָכוֹל לְיַעֲדָהּ לוֹ רְאוּיָה הִיא לִבְנוֹ שֶׁהֲרֵי הָאָמָה בַּת אָחִיו. אֲבָל אֵינוֹ יָכוֹל לִמְכֹּר אֶת בִּתּוֹ לִבְנוֹ מִפְּנֵי שֶׁאֵינָהּ רְאוּיָה לְאָדוֹן שֶׁהֲרֵי הִיא אֲחוֹתוֹ וְלֹא לִבְנוֹ מִפְּנֵי שֶׁהִיא אֲחוֹת אָבִיו:","יֵשׁ לְאָדָם לִמְכֹּר בִּתּוֹ לִפְסוּלִין כְּגוֹן אַלְמָנָה לְכֹהֵן גָּדוֹל גְּרוּשָׁה וַחֲלוּצָה לְכֹהֵן הֶדְיוֹט שֶׁאַף עַל פִּי שֶׁהֵן בְּלָאו קִדּוּשִׁין תּוֹפְסִין בָּהֶן:","הַמְקַדֵּשׁ אֶת בִּתּוֹ כְּשֶׁהִיא קְטַנָּה וְנִתְאַרְמְלָה אוֹ נִתְגָּרְשָׁה אֵינוֹ יָכוֹל לְמָכְרָהּ שֶׁאֵין אָדָם יָכוֹל לִמְכֹּר אֶת בִּתּוֹ לְשִׁפְחוּת אַחַר אִישׁוּת. אֲבָל מוֹכְרָהּ לְשִׁפְחָה אַחַר שִׁפְחוּת. כֵּיצַד. מְכָרָהּ לְשִׁפְחוּת תְּחִלָּה וְיִעֵד אוֹתָהּ הָאָדוֹן וּמֵת הָאָדוֹן אוֹ גֵּרְשָׁהּ וְחָזְרָה לִרְשׁוּת הָאָב כְּשֶׁהִיא קְטַנָּה הֲרֵי הָאָב מוֹכְרָהּ פַּעַם שְׁנִיָּה אֲפִלּוּ לְכֹהֵן. וְכֵן אִם נָפְלָה לִפְנֵי יָבָם מִן הַיִּעוּד וְחָלַץ לָהּ אַף עַל פִּי שֶׁהִיא חֲלִיצָה פְּסוּלָה מִפְּנֵי שֶׁהִיא קְטַנָּה הֲרֵי נִפְסְלָה מִן הַכְּהֻנָּה וְיֵשׁ לוֹ לְמָכְרָהּ לְכֹהֵן הוֹאִיל וְקִדּוּשִׁין תּוֹפְסִין בָּהּ כְּמוֹ שֶׁנִּתְבָּאֵר:","הַמּוֹכֵר אֶת בִּתּוֹ וְיָצְאָה בְּשָׁנִים אוֹ בְּיוֹבֵל אוֹ בְּגִרְעוֹן כֶּסֶף וַעֲדַיִן הִיא קְטַנָּה יֵשׁ לוֹ לַחְזֹר וּלְמָכְרָהּ פַּעַם שְׁנִיָּה כְּמוֹ שֶׁבֵּאַרְנוּ:","הַמּוֹכֵר אֶת בִּתּוֹ וְאַחַר כָּךְ הָלַךְ וְקִדְּשָׁהּ לְאַחֵר אִם רָצָה הָאָדוֹן לְיַעֵד מְיַעֵד וְאִם לֹא יִעֵד הָאָדוֹן לֹא לוֹ וְלֹא לִבְנוֹ כְּשֶׁתֵּצֵא מֵרְשׁוּת הָאָדוֹן יִגָּמְרוּ קִדּוּשֶׁיהָ וְתֵעָשֶׂה אֵשֶׁת אִישׁ:","הַמּוֹכֵר אֶת בִּתּוֹ וּפָסַק עַל הָאָדוֹן עַל מְנָת שֶׁלֹּא לְיַעֵד אוֹתָהּ אִם רָצָה הָאָדוֹן לְיַעֵד מְיַעֵד שֶׁהִתְנָה עַל מַה שֶּׁכָּתוּב בַּתּוֹרָה שֶׁתְּנָאוֹ בָּטֵל:"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 2":["כֵּיצַד כּוֹתְבִין אֶת הַתְּפִלִּין שֶׁל רֹאשׁ. כּוֹתְבִין אַרְבַּע פָּרָשִׁיּוֹת עַל אַרְבַּע קְלָפִין וְגוֹלְלִין כָּל אֶחָד וְאֶחָד לְבַדּוֹ וּמַנִּיחִין אוֹתָן בְּאַרְבַּע בָּתִּים שֶׁהֵן מְחֻבָּרִין בְּעוֹר אֶחָד. וְשֶׁל יָד כּוֹתְבִין אוֹתָן הָאַרְבַּע פָּרָשִׁיּוֹת בְּאַרְבַּע דַּפִּין עַל קְלָף אֶחָד וְגוֹלְּלוֹ כְּמִין סֵפֶר תּוֹרָה מִסּוֹפוֹ לִתְחִלָּתוֹ וּמַנִּיחוֹ בְּבַיִת אֶחָד:","וְצָרִיךְ לְהִזָּהֵר בַּפָּרָשִׁיּוֹת שֶׁאִם עָשָׂה הַסְּתוּמָה פְּתוּחָה אוֹ הַפְּתוּחָה סְתוּמָה פְּסָלָן. וּשְׁלֹשֶׁת הַפָּרָשִׁיּוֹת הָרִאשׁוֹנוֹת כֻּלָּן פְּתוּחוֹת וּפָרָשָׁה אַחֲרוֹנָה שֶׁהִיא (דברים יא יג) ״וְהָיָה אִם שָׁמֹעַ״ סְתוּמָה:","וְצָרִיךְ לְהִזָּהֵר בְּמָלֵא וְחָסֵר עַד שֶׁיִּהְיוּ אַרְבַּעְתָּן כְּתוּבוֹת כְּמוֹ שֶׁהֵן כְּתוּבוֹת בְּסֵפֶר תּוֹרָה הַבָּדוּק. שֶׁאִם כָּתַב הֶחָסֵר מָלֵא פָּסוּל עַד שֶׁיִּמְחֹק הַיָּתֵר. וְאִם כָּתַב הַמָּלֵא חָסֵר פָּסוּל וְאֵין לוֹ תַּקָּנָה. וְאֵלּוּ הֵן הַחֲסֵרוֹת וְהַמְּלֵאוֹת שֶׁיֵּשׁ בְּאַרְבַּע פָּרָשִׁיּוֹת אֵלּוּ:","פָּרָשָׁה רִאשׁוֹנָה (שמות יג ב) ״קַדֶּשׁ לִי כָל בְּכוֹר״ מָלֵא. זָכוֹר מָלֵא. בְּחֹזֶק חָסֵר. [הוֹצִיא מָלֵא. יֹצְאִים חָסֵר וָא״ו.] יְבִיאֲךָ מָלֵא. וְהָאֱמֹרִי חָסֵר. וְהַיְבוּסִי מָלֵא. לַאֲבֹתֶיךָ חָסֵר וָא״ו. הָעֲבֹדָה חָסֵר. מַצֹּת חָסֵר. הַשְּׁבִיעִי מָלֵא. מַצּוֹת מָלֵא. שְׂאֹר חָסֵר. גְּבֻלֶךָ חָסֵר. בַּעֲבוּר מָלֵא. לְאוֹת מָלֵא. וּלְזִכָּרוֹן מָלֵא. עֵינֶיךָ מָלֵא. תּוֹרַת מָלֵא. הוֹצִאֲךָ חָסֵר יוּ״ד. הַחֻקָּה חָסֵר. לְמוֹעֲדָהּ מָלֵא:","פָּרָשָׁה שְׁנִיָּה (שמות יג ה) ״וְהָיָה כִּי יְבִאֲךָ״ חָסֵר יוּ״ד. וְלַאֲבֹתֶיךָ חָסֵר וָא״ו. חֲמֹר חָסֵר. בְּכוֹר מָלֵא. בְּחֹזֶק חָסֵר. הוֹצִיאָנוּ מָלֵא. וַיַּהֲרֹג חָסֵר. בְּכוֹר מָלֵא. מִבְּכֹר חָסֵר. וְעַד בְּכוֹר מָלֵא. זֹבֵחַ חָסֵר וָא״ו. וְכָל בְּכוֹר מָלֵא. לְאוֹת מָלֵא. יָדְכָה כָּתוּב בְּהֵ״א. וּלְטוֹטָפֹת חָסֵר וָא״ו תִּנְיָנָא. עֵינֶיךָ מָלֵא. בְּחֹזֶק חָסֵר. הוֹצִיאָנוּ מָלֵא:","פָּרָשָׁה שְׁלִישִׁית (דברים ו ד) ״שְׁמַע״ עַיִ״ן שֶׁל שְׁמַע גְּדוֹלָה. דָּלֶ״ת שֶׁל אֶחָד גְּדוֹלָה. מְאֹדֶךָ חָסֵר. לְבָנֶיךָ מָלֵא. בְּבֵיתֶךָ בְּלֹא יוּ״ד שְׁנִיָּה. וּבְקוּמֶךָ מָלֵא. לְאוֹת מָלֵא. יָדֶךָ חָסֵר. לְטֹטָפֹת חָסֵר שְׁנֵי וָאוִי״ן. עֵינֶיךָ מָלֵא. מְזֻזוֹת חָסֵר וָא״ו רִאשׁוֹנָה. בֵּיתֶךָ בְּלֹא יוּ״ד שְׁנִיָּה. וּבִשְׁעָרֶיךָ מָלֵא:","פָּרָשָׁה רְבִיעִית (דברים יא יג) ״וְהָיָה אִם שָׁמֹעַ״ חָסֵר. מִצְוֹתַי בְּוָא״ו אַחַת. יוֹרֶה מָלֵא. וּמַלְקוֹשׁ מָלֵא. וְתִירשְׁךָ חָסֵר וָא״ו. וְהִשְׁתַּחֲוִיתֶם מָלֵא. יְבוּלָהּ מָלֵא. הַטֹּבָה חָסֵר. נֹתֵן חָסֵר. אֹתָם חָסֵר. לְאוֹת מָלֵא. לְטוֹטָפֹת חָסֵר וָא״ו שְׁנִיָּה. עֵינֵיכֶם מָלֵא. אֹתָם חָסֵר. בְּבֵיתֶךָ בְּלֹא יוּ״ד שְׁנִיָּה. וּבְקוּמֶךָ מָלֵא. מְזוּזוֹת מָלֵא. בֵּיתֶךָ בְּלֹא יוּ״ד שְׁנִיָּה. וּבִשְׁעָרֶיךָ מָלֵא. לַאֲבֹתֵיכֶם חָסֵר וָא״ו:","וְצָרִיךְ לְהִזָּהֵר בְּתָגִין שֶׁל אוֹתִיּוֹת וְהֵן כְּמוֹ זַיִנִּין זְקוּפוֹת שֶׁיֵּשׁ לָהֶן תָּג כְּמוֹ שֶׁהֵן כְּתוּבִין בְּסֵפֶר תּוֹרָה. וְאֵלּוּ הֵן הָאוֹתִיּוֹת הַמְתֻיָּגוֹת שֶׁבְּאַרְבַּע פָּרָשִׁיּוֹת אֵלּוּ:","פָּרָשָׁה רִאשׁוֹנָה יֵשׁ בָּהּ אוֹת אַחַת בִּלְבַד וְהִיא מֵ״ם סְתוּמָה שֶׁל (שמות יג י) ״מִיָּמִים״ עָלֶיהָ שָׁלֹשׁ זַיִנִּי״ן. פָּרָשָׁה שְׁנִיָּה יֵשׁ לָהּ חָמֵשׁ אוֹתִיּוֹת וְכָל אַחַת מֵהֶן הֵ״א וְעַל כָּל הֵ״א מֵחֲמִשְׁתָּן אַרְבַּע זַיִנִּי״ן. וְהֵן הֵ״א שֶׁל (שמות יג יא) ״וּנְתָנָהּ״. וְהֵ״א רִאשׁוֹנָה וְהֵ״א אַחֲרוֹנָה שֶׁל (שמות יג טו) ״הִקְשָׁה״. וְהֵ״א שֶׁל (שמות יג טו) ״וַיַּהֲרֹג״. וְהֵ״א שֶׁל (שמות יג טז) ״יָדְכָה״. פָּרָשָׁה שְׁלִישִׁית יֵשׁ בָּהּ חָמֵשׁ אוֹתִיּוֹת וְאֵלּוּ הֵן קוּ״ף שֶׁל (דברים ו ז) ״וּבְקוּמֶךָ״ יֵשׁ עָלֶיהָ שָׁלֹשׁ זַיִנִּי״ן. וְקוּ״ף שֶׁל (דברים ו ח) ״וּקְשַׁרְתָּם״ יֵשׁ עָלֶיהָ שָׁלֹשׁ זַיִנִּי״ן. וְטֵי״ת טֵי״ת פֵ״א שֶׁל (דברים ו ח) ״לְטֹטָפֹת״ עַל כָּל אוֹת מִשְּׁלָשְׁתָּן אַרְבַּע זַיִנִּי״ן. פָּרָשָׁה רְבִיעִית יֵשׁ בָּהּ חָמֵשׁ אוֹתִיּוֹת. פֵ״א שֶׁל (דברים יא יד) ״וְאָסַפְתָּ״ יֵשׁ עָלֶיהָ שָׁלֹשׁ זַיִנִּי״ן. וְתָי״ו שֶׁל וְאָסַפְתָּ יֵשׁ עָלֶיהָ זַיִ״ן אַחַת. וְטֵי״ת טֵי״ת פֵ״א שֶׁל (דברים יא יח) ״לְטוֹטָפֹת״ עַל כָּל אַחַת מִשְּׁלָשְׁתָּן אַרְבַּע זַיִנִּי״ן. כָּל הָאוֹתִיּוֹת הַמְתֻיָּגוֹת שֵׁשׁ עֶשְׂרֵה. וְאִם לֹא עָשָׂה הַתָּגִין אוֹ הוֹסִיף וְגָרַע בָּהֶן לֹא פָּסַל:","הַלּוֹקֵחַ תְּפִלִּין מִמִּי שֶׁאֵינוֹ מֻמְחֶה צָרִיךְ לְבָדְקָן. לָקַח מִמֶּנּוּ מֵאָה קְצִיצוֹת בּוֹדֵק מֵהֶן שָׁלֹשׁ קְצִיצוֹת. אוֹ שְׁתַּיִם שֶׁל רֹאשׁ וְאַחַת שֶׁל יָד אוֹ שְׁתַּיִם שֶׁל יָד וְאַחַת שֶׁל רֹאשׁ. אִם מְצָאָם כְּשֵׁרִים הֻחְזַק זֶה הָאִישׁ וַהֲרֵי כֻּלָּן כְּשֵׁרִים וְאֵין הַשְּׁאָר צָרִיךְ בְּדִיקָה. וְאִם לְקָחָם צְבָתִים צְבָתִים כֻּלָּן צְרִיכוֹת בְּדִיקָה שֶׁחֶזְקַת הַצְּבָתִים מֵאֲנָשִׁים הַרְבֵּה לְקוּחִים:","הַכּוֹתֵב תְּפִלִּין בִּכְתַב יָדוֹ אוֹ שֶׁלְּקָחָן מִן הַמֻּמְחֶה אוֹ מִשְּׁאָר אָדָם וּבְדָקָן וְהֶחֱזִירָן לְעוֹרָן לְעוֹלָם אֵינוֹ צָרִיךְ לְבָדְקָם פַּעַם אַחֶרֶת וַאֲפִלּוּ לְאַחַר כַּמָּה שָׁנִים. כָּל זְמַן שֶׁחִפּוּיָן שָׁלֵם הֲרֵי הֵן בְּחֶזְקָתָן. וְאֵין חוֹשְׁשִׁין לָהֶן שֶׁמָּא נִמְחֲקָה אוֹת מִתּוֹכָן אוֹ שֶׁנִּקְּבָה. הִלֵּל הַזָּקֵן הָיָה אוֹמֵר אֵלּוּ מִשֶּׁל אָבִי אִימָא:"],"Mishneh Torah, Testimony 13":["הַקְּרוֹבִים פְּסוּלִים לְעֵדוּת מִן הַתּוֹרָה שֶׁנֶּאֱמַר (דברים כד טז) \"לֹא יוּמְתוּ אָבוֹת עַל בָּנִים\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבִּכְלַל לָאו זֶה שֶׁלֹּא יוּמְתוּ אָבוֹת עַל פִּי בָּנִים וְלֹא בָּנִים עַל פִּי אָבוֹת. וְהוּא הַדִּין לִשְׁאָר קְרוֹבִים. אֵין פְּסוּלִין מִדִּין תּוֹרָה אֶלָּא קְרוֹבִים מִמִּשְׁפַּחַת אָב בִּלְבַד. וְהֵם הָאָב עִם הַבֵּן וְעִם בֶּן הַבֵּן. וְהָאַחִין מִן הָאָב זֶה עִם זֶה וּבְנֵיהֶן זֶה עִם זֶה וְאֵין צָרִיךְ לוֹמַר הַדּוֹדִים עִם בֶּן אָחִיו. אֲבָל שְׁאָר הַקְּרוֹבִים מִן הָאֵם אוֹ מִדֶּרֶךְ הָאִישׁוּת כֻּלָּן פְּסוּלִין מִדִּבְרֵיהֶם:","הַגֵּרִים אֵינָן בְּדִין הַקְּרוֹבִים. אֲפִלּוּ שְׁנֵי אַחִים תְּאוֹמִים שֶׁנִּתְגַּיְּרוּ מְעִידִין זֶה לָזֶה. שֶׁהַגֵּר שֶׁנִּתְגַּיֵּר כְּקָטָן שֶׁנּוֹלַד הוּא חָשׁוּב:","הָאַחִים זֶה עִם זֶה בֵּין מִן הָאֵם בֵּין מִן הָאָב הֲרֵי הֵן רִאשׁוֹן בְּרִאשׁוֹן. וּבְנֵיהֶם זֶה עִם זֶה שֵׁנִי בְּשֵׁנִי. וּבְנֵי בְּנֵיהֶם זֶה עִם זֶה שְׁלִישִׁי בִּשְׁלִישִׁי:","וּלְעוֹלָם שְׁלִישִׁי בְּרִאשׁוֹן כָּשֵׁר וְאֵין צָרִיךְ לוֹמַר שְׁלִישִׁי בְּשֵׁנִי. אֲבָל שֵׁנִי בְּשֵׁנִי וְאֵין צָרִיךְ לוֹמַר שֵׁנִי בְּרִאשׁוֹן שְׁנֵיהֶם פְּסוּלִים:","הָאָב עִם בְּנוֹ כְּרִאשׁוֹן בְּרִאשׁוֹן הוּא. לְפִיכָךְ הָאָב עִם בֶּן בְּנוֹ פָּסוּל. וְעִם בֶּן בֶּן בְּנוֹ שֶׁהוּא רְבִיעִי מִמֶּנּוּ כָּשֵׁר מִפְּנֵי שֶׁהוּא שְׁלִישִׁי בְּרִאשׁוֹן. וְכֵן הַדֶּרֶךְ בִּנְקֵבוֹת. כֵּיצַד. שְׁתֵּי אֲחָיוֹת אוֹ אָח וַאֲחוֹתוֹ בֵּין מִן הָאָב בֵּין מִן הָאֵם הֲרֵי הֵם רִאשׁוֹן בְּרִאשׁוֹן. בְּנֵיהֶם בֵּין זְכָרִים בֵּין נְקֵבוֹת שֵׁנִי בְּשֵׁנִי. בְּנֵי בְּנֵיהֶם אוֹ בְּנוֹת בְּנוֹתֵיהֶן שְׁלִישִׁי בִּשְׁלִישִׁי. כְּדֶרֶךְ שֶׁאַתָּה מוֹנֶה בִּזְכָרִים רִאשׁוֹן שֵׁנִי וּשְׁלִישִׁי כָּךְ אַתָּה מוֹנֶה בִּנְקֵבוֹת:","כָּל אִשָּׁה שֶׁאַתָּה פָּסוּל לָהּ כָּךְ אַתָּה פָּסוּל לְבַעְלָהּ שֶׁהַבַּעַל כְּאִשְׁתּוֹ. וְכָל בַּעַל שֶׁאַתָּה פָּסוּל לוֹ כָּךְ אַתָּה פָּסוּל לְאִשְׁתּוֹ שֶׁהָאִשָּׁה כְּבַעְלָהּ:","כָּל שְׁתֵּי נָשִׁים שֶׁהֵן זוֹ עִם זוֹ שֵׁנִי בְּשֵׁנִי בַּעְלֵיהֶן מְעִידִין זֶה לָזֶה. אֲבָל אִם הָיָה רִאשׁוֹן בְּרִאשׁוֹן כְּגוֹן שֶׁלָּקַח זֶה אִשָּׁה וְזֶה בִּתָּהּ אֵין מְעִידִין זֶה לָזֶה:","וְכֵן בַּעְלֵי אֲחָיוֹת פְּסוּלִין זֶה לָזֶה וַהֲרֵי הֵן רִאשׁוֹן בְּרִאשׁוֹן:","וְכֵן לֹא יָעִיד לְבֶן אֲחוֹת אִשְׁתּוֹ וְלֹא לְבַעַל בַּת אֲחוֹת אִשְׁתּוֹ. אֲבָל מֵעִיד הוּא לְבֶן בַּעַל אֲחוֹת אִשְׁתּוֹ שֶׁיֵּשׁ לוֹ מֵאִשָּׁה אַחֶרֶת:","כָּל אִישׁ שֶׁאֵין אַתָּה מֵעִיד לוֹ מִפְּנֵי שֶׁהוּא בַּעַל קְרוֹבָתְךָ הֲרֵי אַתָּה מֵעִיד לִשְׁאָר קְרוֹבָיו כְּגוֹן בְּנוֹ וְאָחִיו. וְכֵן כָּל אִשָּׁה שֶׁאֵין אַתָּה מֵעִיד לָהּ מִפְּנֵי שֶׁהִיא אֵשֶׁת קְרוֹבְךָ הֲרֵי אַתָּה מֵעִיד לִשְׁאָר קְרוֹבֶיהָ:","אֲבִי כַּלָּה וַאֲבִי חָתָן מְעִידִים זֶה לָזֶה:","אֲחֵי הָאָח מִן הָאֵם מְעִידִין זֶה לָזֶה שֶׁהֲרֵי אֵין בֵּינֵיהֶן קֻרְבָה כְּלָל. כֵּיצַד. רָחֵל שֶׁנִּשֵּׂאת לְיוֹסֵף וְיָלְדָה מִמֶּנָּה רְאוּבֵן. וְהָיָה לְיוֹסֵף בֵּן מֵאִשָּׁה אַחֶרֶת וְהוּא מְנַשֶּׁה. וּמֵת יוֹסֵף וְנִשֵּׂאת לְשִׁמְעוֹן וְיָלְדָה מִמֶּנּוּ יְהוּדָה. הֲרֵי מְנַשֶּׁה וִיהוּדָה מְעִידִין זֶה לָזֶה:","הָאִישׁ עִם אִשְׁתּוֹ רִאשׁוֹן בְּרִאשׁוֹן. לְפִיכָךְ אֵינוֹ מֵעִיד לֹא לִבְנָהּ. וְלֹא לְאֵשֶׁת בְּנָהּ. וְלֹא לְבִתָּהּ. וְלֹא לְבַעַל בִּתָּהּ. וְלֹא לְאָבִיהָ. וְלֹא לְאִמָּהּ. וְלֹא לְבַעַל אִמָּהּ. וְלֹא לְאֵשֶׁת אָבִיהָ:","אִשְׁתּוֹ אֲרוּסָה אַף עַל פִּי שֶׁלֹּא נִגְמְרָה הָאִישׁוּת הֲרֵי הִיא כִּנְשׂוּאָה לְעִנְיַן עֵדוּת. [בַּמֶּה דְּבָרִים אֲמוּרִים] בַּאֲרוּסָתוֹ עַצְמָהּ שֶׁאֵינוֹ מֵעִיד לָהּ. אֲבָל אִם הֵעִיד לִקְרוֹבֵי אֲרוּסָתוֹ כְּגוֹן בַּעַל אֲחוֹתָהּ אוֹ בְּנָהּ וּבִתָּהּ וְכַיּוֹצֵא בָּהֶן אֵין פּוֹסְלִין אוֹתָהּ עַד שֶׁיִּשָּׂאֶנָּה:","זֶה שֶׁפָּסְלָה תּוֹרָה עֵדוּת הַקְּרוֹבִים לֹא מִפְּנֵי שֶׁהֵן בְּחֶזְקַת אוֹהֲבִין זֶה אֶת זֶה. שֶׁהֲרֵי אֵינוֹ מֵעִיד לוֹ לֹא לְטוֹבָתוֹ וְלֹא לְרָעָתוֹ. אֶלָּא גְּזֵרַת הַכָּתוּב הוּא. לְפִיכָךְ הָאוֹהֵב וְהַשּׂוֹנֵא כָּשֵׁר לְעֵדוּת אַף עַל פִּי שֶׁהוּא פָּסוּל לְדַיָּנוּת. שֶׁלֹּא גָּזְרָה תּוֹרָה אֶלָּא עַל הַקְּרוֹבִים:"],"Mishneh Torah, Testimony 4":["עֵדֵי נְפָשׁוֹת צְרִיכִין שֶׁיִּהְיוּ שְׁנֵיהֶם רוֹאִים אֶת הָעוֹשֶׂה עֲבֵרָה כְּאֶחָד. וּצְרִיכִין לְהָעִיד כְּאֶחָד וּבְבֵית דִּין אֶחָד. אֲבָל דִּינֵי מָמוֹנוֹת אֵין צְרִיכִין לְכָךְ. כֵּיצַד. הָיָה אֶחָד רוֹאֵהוּ מֵחַלּוֹן זֶה כְּשֶׁעָבַר הָעֲבֵרָה וְהָעֵד הָאַחֵר רוֹאֵהוּ מֵחַלּוֹן אַחֵר. אִם הָיוּ שְׁנֵי הָעֵדִים רוֹאִין זֶה אֶת זֶה מִצְטָרְפִין וְאִם לָאו אֵין מִצְטָרְפִין. הָיָה זֶה הַמַּתְרֶה בּוֹ רוֹאֶה הָעֵדִים וְהָעֵדִים רוֹאִין אוֹתוֹ אַף עַל פִּי שֶׁאֵין רוֹאִין זֶה אֶת זֶה הַמַּתְרֶה מְצָרְפָן. הָיוּ שְׁנֵי הָעֵדִים בְּבַיִת אֶחָד וְהוֹצִיא אֶחָד מֵהֶן רֹאשׁוֹ מִן הַחַלּוֹן. וְרָאָהוּ זֶה שֶׁעוֹשֶׂה מְלָאכָה בְּשַׁבָּת וְאֶחָד מַתְרֶה בּוֹ. וְהִכְנִיס רֹאשׁוֹ וְחָזַר הָעֵד הַשֵּׁנִי וְהוֹצִיא רֹאשׁוֹ מֵאוֹתוֹ הַחַלּוֹן וְרָאָהוּ. אֵין מִצְטָרְפִין עַד שֶׁיִּרְאוּ שְׁנֵיהֶם כְּאֶחָד. הָיוּ שְׁנֵי עֵדִים רוֹאִין אוֹתוֹ מֵחַלּוֹן זֶה וּשְׁנֵי עֵדִים רוֹאִין אוֹתוֹ מֵחַלּוֹן אַחֵר וְאֶחָד מַתְרֶה בּוֹ בָּאֶמְצַע. בִּזְמַן שֶׁמִּקְצָתָן רוֹאִין אֵלּוּ אֶת אֵלּוּ הֲרֵי זוֹ עֵדוּת אַחַת וְאִם לֹא הָיוּ רוֹאִין אֵלּוּ אֶת אֵלּוּ וְלֹא צֵרֵף אוֹתָן הַמַּתְרֶה הֲרֵי אֵלּוּ שְׁתֵּי עֵדוּיוֹת. לְפִיכָךְ אִם נִמְצֵאת כַּת אַחַת מֵהֶן זוֹמְמִין הוּא וְהֵן נֶהֱרָגִין שֶׁהֲרֵי הוּא נֶהֱרָג בְּעֵדוּת הַכַּת הַשְּׁנִיָּה:","אֲבָל בְּדִינֵי מָמוֹנוֹת אַף עַל פִּי שֶׁלֹּא רָאוּ אֵלּוּ אֶת אֵלּוּ עֵדוּתָן מִצְטָרֶפֶת. כֵּיצַד. אָמַר הָאֶחָד בְּפָנַי הִלְוָהוּ בְּיוֹם פְּלוֹנִי אוֹ בְּפָנַי הוֹדָה לוֹ. וְאָמַר הָעֵד הַשֵּׁנִי וְכֵן אֲנִי מֵעִיד שֶׁהִלְוָהוּ בְּפָנַי אוֹ הוֹדָה בְּיוֹם אַחֵר. הֲרֵי אֵלּוּ מִצְטָרְפִין:","וְכֵן אִם אָמַר הָאֶחָד בְּפָנַי הִלְוָהוּ וְהַשֵּׁנִי אוֹמֵר בְּפָנַי הוֹדָה לוֹ. אוֹ שֶׁאָמַר הָרִאשׁוֹן בְּפָנַי הוֹדָה וְהַשֵּׁנִי שֶׁהֵעִיד אַחַר זְמַן אָמַר בְּפָנַי הִלְוָהוּ. הֲרֵי אֵלּוּ מִצְטָרְפִין:","וְכֵן בְּעֵת שֶׁמְּעִידִין בְּבֵית דִּין יָבוֹא אֶחָד וְשׁוֹמְעִין דְּבָרָיו הַיּוֹם וּכְשֶׁיָּבוֹא הָעֵד הַשֵּׁנִי לְאַחַר זְמַן שׁוֹמְעִין דְּבָרָיו וּמִצְטָרְפִין זֶה לָזֶה וּמוֹצִיאִין בָּהֶן הַמָּמוֹן:","וְכֵן אִם הָיָה עֵד אֶחָד בִּכְתָב וְאֶחָד עַל פֶּה מִצְטָרְפִין. וְאִם אָמַר זֶה שֶׁלֹּא כָּתַב עֵדוּתוֹ אֲנִי קָנִיתִי מִיָּדוֹ עַל דָּבָר זֶה וְלֹא בָּא הַמַּלְוֶה הַזֶּה וְלֹא שָׁאַל מִמֶּנִּי לִכְתֹּב שְׁנֵיהֶם מִצְטָרְפִין לַעֲשׂוֹת הַמִּלְוֶה בַּשְּׁטָר וְאֵינוֹ יָכוֹל לוֹמַר פָּרַעְתִּי:","הֵעִיד הָאֶחָד בְּבֵית דִּין זֶה וְהָעֵד הַשֵּׁנִי בְּבֵית דִּין אַחֵר יָבוֹא בֵּית דִּין אֵצֶל בֵּית דִּין וְיִצְטָרְפוּ עֵדוּתָן. וְכֵן אִם הֵעִידוּ שְׁנֵי הָעֵדִים בְּבֵית דִּין זֶה וְחָזְרוּ וְהֵעִידוּ בְּבֵית דִּין אַחֵר יָבוֹא אֶחָד מִכָּל בֵּית דִּין וְיִצְטָרְפוּ. אֲבָל הָעֵד עִם הַדַּיָּן שֶׁהֵעִידוּ שְׁנֵי הָעֵדִים בְּפָנָיו אֵין מִצְטָרְפִין:","אַף עַל פִּי שֶׁמִּצְטָרְפִין הָעֵדוּת בְּדִינֵי מָמוֹנוֹת צָרִיךְ שֶׁיָּעִיד כָּל אֶחָד מִשְּׁנֵיהֶם בְּכָל דָּבָר כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אִם הֵעִיד עֵד אֶחָד בְּמִקְצָת דָּבָר וְהֵעִיד הַשֵּׁנִי בְּמִקְצָתוֹ אֵין מְקַיְּמִין הַדָּבָר מֵעֵדוּת שְׁנֵיהֶם. שֶׁנֶּאֱמַר (משנה סוטה ו ג) \"עַל פִּי שְׁנַיִם עֵדִים יָקוּם דָּבָר\". כֵּיצַד. זֶה אוֹמֵר פְּלוֹנִי אָכַל שָׂדֶה זוֹ שָׁנָה פְּלוֹנִית וְזֶה הֵעִיד שֶׁאֲכָלָהּ שָׁנָה שְׁנִיָּה וְזֶה הֵעִיד שֶׁאֲכָלָהּ שָׁנָה שְׁלִישִׁית. אֵין מִצְטָרְפִין עֵדוּת שְׁלָשְׁתָּן וְאוֹמְרִים הֲרֵי אֲכָלָהּ שָׁלֹשׁ שָׁנִים שֶׁכָּל אֶחָד וְאֶחָד הֵעִיד בְּמִקְצָת הַדָּבָר. וְכֵן אִם הֵעִיד זֶה אֲנִי רָאִיתִי שַׂעֲרָה אַחַת בְּצַד יְמִינוֹ שֶׁל זֶה וְזֶה אוֹמֵר אֲנִי רָאִיתִי שַׂעֲרָה אַחַת בְּצַד שְׂמֹאלוֹ שֶׁל זֶה בְּאוֹתוֹ הַיּוֹם. אֵין מִצְטָרְפִין דִּבְרֵי שְׁנֵיהֶם כְּדֵי שֶׁנֹּאמַר הֲרֵי הֵעִידוּ שְׁנֵיהֶם שֶׁהָיָה זֶה גָּדוֹל בְּיוֹם פְּלוֹנִי לְפִי שֶׁכָּל אֶחָד מֵהֶם לֹא הֵעִיד אֶלָּא בְּמִקְצָת הַסִּימָנִין. אֲפִלּוּ הֵעִידוּ שְׁנַיִם בְּשַׂעֲרָה אַחַת וְהָעִידוּ שְׁנַיִם בְּשַׂעֲרָה אַחֶרֶת שֶׁהֲרֵי כָּל כַּת מֵהֶם הֵעִידָה עַל חֲצִי דָּבָר וְאֵין זוֹ עֵדוּת. אֲבָל אִם הֵעִידָה הָאַחַת שֶׁרָאֲתָה שְׁתֵּי שְׂעָרוֹת בְּצַד יָמִין וְהֵעִידָה הַשְּׁנִיָּה שֶׁרָאֲתָה שְׁתֵּי שְׂעָרוֹת בְּצַד שְׂמֹאל מִצְטָרְפִין. וְכֵן כָּל כַּיּוֹצֵא בּוֹ:"],"Mishneh Torah, The Chosen Temple 7":["מִצְוַת עֲשֵׂה לְיִרְאָה מִן הַמִּקְדָּשׁ שֶׁנֶּאֱמַר (ויקרא יט ל) (ויקרא כו ב) \"וּמִקְדָּשִׁי תִּירָאוּ\". וְלֹא מִן הַמִּקְדָּשׁ אַתָּה יָרֵא אֶלָּא מִמִּי שֶׁצִּוָּה עַל יִרְאָתוֹ:","וְאֵי זוֹ הִיא יִרְאָתוֹ לֹא יִכָּנֵס אָדָם לְהַר הַבַּיִת בְּמַקְלוֹ אוֹ בְּמִנְעָל שֶׁבְּרַגְלָיו אוֹ בַּאֲפֻנְדָּתוֹ אוֹ בָּאָבָק שֶׁעַל רַגְלָיו אוֹ בְּמָעוֹת הַצְּרוּרִין לוֹ בִּסְדִינוֹ וְאֵין צָרִיךְ לוֹמַר שֶׁאָסוּר לָרֹק בְּכָל הַר הַבַּיִת אֶלָּא אִם נִזְדַּמֵּן לוֹ רֹק מַבְלִיעוֹ בִּכְסוּתוֹ. וְלֹא יַעֲשֶׂה הַר הַבַּיִת דֶּרֶךְ שֶׁיִּכָּנֵס מִפֶּתַח זוֹ וְיֵצֵא מִפֶּתַח שֶׁכְּנֶגְדָהּ כְּדֵי לְקַצֵּר הַדֶּרֶךְ אֶלָּא יַקִּיפוֹ מִבַּחוּץ. וְלֹא יִכָּנֵס לוֹ אֶלָּא לִדְבַר מִצְוָה:","וְכָל הַנִּכְנָסִין לְהַר הַבַּיִת נִכְנָסִין דֶּרֶךְ יָמִין וּמַקִּיפִין וְיוֹצְאִין דֶּרֶךְ שְׂמֹאל חוּץ מִמִּי שֶׁאֵרְעוֹ דָּבָר שֶׁהוּא מַקִּיף עַל הַשְּׂמֹאל. לְפִיכָךְ הָיוּ שׁוֹאֲלִין לוֹ מַה לְּךָ מַקִּיף עַל הַשְּׂמֹאל. שֶׁאֲנִי אָבֵל. הַשּׁוֹכֵן בַּבַּיִת הַזֶּה יְנַחֶמְךָ. שֶׁאֲנִי מְנֻדֶּה. הַשּׁוֹכֵן בַּבַּיִת הַזֶּה יִתֵּן בִּלְבָבְךָ וְתִשְׁמַע לְדִבְרֵי חֲבֵרֶיךָ וִיקָרְבוּךָ:","כָּל שֶׁהִשְׁלִים עֲבוֹדָה וְנִסְתַּלֵּק לוֹ אֵינוֹ יוֹצֵא וַאֲחוֹרָיו לַהֵיכָל אֶלָּא מְהַלֵּךְ אֲחוֹרַנִּית מְעַט מְעַט וּמְהַלֵּךְ בְּנַחַת עַל צִדּוֹ עַד שֶׁיֵּצֵא מִן הָעֲזָרָה. וְכֵן אַנְשֵׁי מִשְׁמָר וְאַנְשֵׁי מַעֲמָד וּלְוִיִּם מִדּוּכָנָן כָּךְ הֵם יוֹצְאִין מִן הַמִּקְדָּשׁ כְּמִי שֶׁפּוֹסֵעַ אַחַר תְּפִלָּה לַאֲחוֹרָיו. כָּל זֶה לְיִרְאָה מִן הַמִּקְדָּשׁ:","לֹא יָקֵל אָדָם אֶת רֹאשׁוֹ כְּנֶגֶד שַׁעַר מִזְרָחִי שֶׁל עֲזָרָה שֶׁהוּא שַׁעַר נִיקָנוֹר. מִפְּנֵי שֶׁהוּא מְכֻוָּן כְּנֶגֶד בֵּית קֹדֶשׁ הַקָּדָשִׁים. וְכָל הַנִּכְנָס לָעֲזָרָה יְהַלֵּךְ בְּנַחַת בְּמָקוֹם שֶׁמֻּתָּר לוֹ לְהִכָּנֵס לְשָׁם. וְיִרְאֶה עַצְמוֹ שֶׁהוּא עוֹמֵד לִפְנֵי ה' כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ט ג) (דברי הימים ב ז טז) \"וְהָיוּ עֵינַי וְלִבִּי שָׁם כָּל הַיָּמִים\". וּמְהַלֵּךְ בְּאֵימָה וּבְיִרְאָה וּרְעָדָה שֶׁנֶּאֱמַר (תהילים נה טו) \"בְּבֵית אֱלֹהִים נְהַלֵּךְ בְּרָגֶשׁ\":","וְאָסוּר לְכָל אָדָם לֵישֵׁב בְּכָל הָעֲזָרָה וְאֵין יְשִׁיבָה בָּעֲזָרָה אֶלָּא לְמַלְכֵי בֵּית דָּוִד בִּלְבַד שֶׁנֶּאֱמַר (שמואל ב ז יח) (דברי הימים א יז טז) \"וַיָּבֹא הַמֶּלֶךְ דָּוִד וַיֵּשֶׁב לִפְנֵי ה'\". וְהַסַּנְהֶדְרִין שֶׁהָיוּ יוֹשְׁבִין בְּלִשְׁכַּת הַגָּזִית לֹא הָיוּ יוֹשְׁבִין אֶלָּא בְּחֶצְיָהּ שֶׁל חל:","אַף עַל פִּי שֶׁהַמִּקְדָּשׁ הַיּוֹם חָרֵב בַּעֲוֹנוֹתֵינוּ חַיָּב אָדָם בְּמוֹרָאוֹ כְּמוֹ שֶׁהָיָה נוֹהֵג בּוֹ בְּבִנְיָנוֹ. לֹא יִכָּנֵס אֶלָּא לְמָקוֹם שֶׁמֻּתָּר לְהִכָּנֵס לְשָׁם וְלֹא יֵשֵׁב בָּעֲזָרָה וְלֹא יָקֵל רֹאשׁוֹ כְּנֶגֶד שַׁעַר הַמִּזְרָח שֶׁנֶּאֱמַר (ויקרא יט ל) (ויקרא כו ב) \"אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ וּמִקְדָּשִׁי תִּירָאוּ\". מַה שְּׁמִירַת שַׁבָּת לְעוֹלָם אַף מוֹרָא מִקְדָּשׁ לְעוֹלָם שֶׁאַף עַל פִּי שֶׁחָרֵב בִּקְדֻשָּׁתוֹ עוֹמֵד:","בִּזְמַן שֶׁהַמִּקְדָּשׁ בָּנוּי אָסוּר לוֹ לְאָדָם לְהָקֵל אֶת רֹאשׁוֹ מִן הַצּוֹפִים שֶׁהוּא חוּץ לִירוּשָׁלַיִם וְלִפְנִים. וְהוּא שֶׁיִּהְיֶה רוֹאֶה אֶת הַמִּקְדָּשׁ. וְלֹא יִהְיֶה גָּדֵר מַפְסִיק בֵּינוֹ וּבֵין הַמִּקְדָּשׁ:","אָסוּר לְאָדָם לְעוֹלָם שֶׁיִּפָּנֶה אוֹ שֶׁיִּישַׁן בֵּין מִזְרָח לַמַּעֲרָב. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין קוֹבְעִין בֵּית הַכִּסֵּא בֵּין מִזְרָח לַמַּעֲרָב בְּכָל מָקוֹם מִפְּנֵי שֶׁהַהֵיכָל בְּמַעֲרָב. לְפִיכָךְ לֹא יִפָּנֶה לְמַעֲרָב וְלֹא לְמִזְרָח מִפְּנֵי שֶׁהוּא כְּנֶגֶד הַמַּעֲרָב. אֶלָּא בֵּין צָפוֹן לְדָרוֹם נִפְנִים וִישֵׁנִים. וְכָל הַמֵּטִיל מַיִם מִן הַצּוֹפִים וְלִפְנִים לֹא יֵשֵׁב וּפָנָיו כְּלַפֵּי הַקֹּדֶשׁ אֶלָּא לְצָפוֹן אוֹ לְדָרוֹם אוֹ יְסַלֵּק הַקֹּדֶשׁ לַצְּדָדִין:","וְאָסוּר לְאָדָם שֶׁיַּעֲשֶׂה בַּיִת תַּבְנִית הֵיכָל. אַכְסַדְרָא תַּבְנִית אוּלָם. חָצֵר כְּנֶגֶד הָעֲזָרָה. שֻׁלְחָן בְּצוּרַת שֻׁלְחָן. וּמְנוֹרָה בְּצוּרַת מְנוֹרָה. אֲבָל עוֹשֶׂה הוּא מְנוֹרָה שֶׁל חֲמִשָּׁה קָנִים אוֹ שֶׁל שְׁמוֹנָה קָנִים אוֹ מְנוֹרָה שֶׁאֵינָהּ שֶׁל מַתֶּכֶת אַף עַל פִּי שֶׁיֵּשׁ לָהּ שִׁבְעָה קָנִים:","שְׁלֹשָׁה מַחֲנוֹת הָיוּ בַּמִּדְבָּר. מַחֲנֵה יִשְׂרָאֵל וְהוּא אַרְבַּע מַחֲנוֹת. וּמַחֲנֵה לְוִיָּה שֶׁנֶּאֱמַר בָּהּ (במדבר א נ) \"וְסָבִיב לַמִּשְׁכָּן יַחֲנוּ\". וּמַחֲנֵה שְׁכִינָה וְהוּא מִפֶּתַח חֲצַר אֹהֶל מוֹעֵד וְלִפְנִים. וּכְנֶגְדָּן לְדוֹרוֹת. מִפֶּתַח יְרוּשָׁלַיִם עַד הַר הַבַּיִת כְּמַחֲנֵה יִשְׂרָאֵל. וּמִפֶּתַח הַר הַבַּיִת עַד פֶּתַח הָעֲזָרָה שֶׁהוּא שַׁעַר נִיקָנוֹר כְּמַחֲנֵה לְוִיָּה. וּמִפֶּתַח הָעֲזָרָה וְלִפְנִים מַחֲנֵה שְׁכִינָה. וְהַחֵיל וְעֶזְרַת הַנָּשִׁים מַעֲלָה יְתֵרָה בְּבֵית עוֹלָמִים:","כָּל אֶרֶץ יִשְׂרָאֵל מְקֻדֶּשֶׁת מִכָּל הָאֲרָצוֹת. וּמַה הִיא קְדֻשָּׁתָהּ שֶׁמְּבִיאִין מִמֶּנָּה הָעֹמֶר וּשְׁתֵּי הַלֶּחֶם וְהַבִּכּוּרִים מַה שֶּׁאֵין מְבִיאִין כֵּן מִשְּׁאָר אֲרָצוֹת:","עֶשֶׂר קְדֻשּׁוֹת הֵן בְּאֶרֶץ יִשְׂרָאֵל וְזוֹ לְמַעְלָה מִזּוֹ. עֲיָרוֹת הַמֻּקָּפוֹת חוֹמָה מְקֻדָּשׁוֹת מִשְּׁאָר הָאָרֶץ שֶׁמְּשַׁלְּחִין מִתּוֹכָן אֶת הַמְצֹרָעִים וְאֵין קוֹבְרִין בְּתוֹכָן מֵת עַד שֶׁיִּרְצוּ שִׁבְעָה טוֹבֵי הָעִיר אוֹ כָּל אַנְשֵׁי הָעִיר. וְאִם יָצָא הַמֵּת חוּץ לָעִיר אֵין מַחֲזִירִין אוֹתוֹ לְתוֹכָהּ אַף עַל פִּי שֶׁרָצוּ כֻּלָּן לְהַחְזִירוֹ. רָצוּ בְּנֵי הָעִיר לְהוֹצִיא הַקֶּבֶר מִן הַמְּדִינָה מְפַנִּין אוֹתוֹ. וְכָל הַקְּבָרוֹת מְפַנִּין חוּץ מִקֶּבֶר נָבִיא אוֹ מֶלֶךְ. קֶבֶר שֶׁהִקִּיפַתּוּ הָעִיר בֵּין מֵאַרְבַּע רוּחוֹתָיו בֵּין מִשְּׁתֵי רוּחוֹת זוֹ כְּנֶגֶד זוֹ אִם הָיְתָה בֵּינוֹ וּבֵין הָעִיר יֶתֶר מֵחֲמִשִּׁים אַמָּה לְכָאן וַחֲמִשִּׁים לְכָאן אֵין מְפַנִּין אוֹתוֹ עַד שֶׁיִּרְצוּ כֻּלָּן. פָּחוֹת מִכָּאן מְפַנִּין אוֹתוֹ:","יְרוּשָׁלַיִם מְקֻדֶּשֶׁת מִשְּׁאָר הָעֲיָרוֹת הַמֻּקָּפוֹת חוֹמָה. שֶׁאוֹכְלִין קָדָשִׁים קַלִּים וּמַעֲשֵׂר שֵׁנִי לְפָנִים מֵחוֹמָתָהּ. וְאֵלּוּ דְּבָרִים שֶׁנֶּאֶמְרוּ בִּירוּשָׁלַיִם. אֵין מְלִינִין בָּהּ אֶת הַמֵּת. וְאֵין מַעֲבִירִין בְּתוֹכָהּ עַצְמוֹת אָדָם. וְאֵין מַשְׂכִּירִין בְּתוֹכָהּ בָּתִּים. וְאֵין נוֹתְנִין בְּתוֹכָהּ מָקוֹם לְגֵר תּוֹשָׁב. וְאֵין מְקַיְּמִין בָּהּ קִבְרוֹת חוּץ מִקִּבְרֵי בֵּית דָּוִד וְקֶבֶר חֻלְדָּה שֶׁהָיוּ בָּהּ מִימוֹת נְבִיאִים הָרִאשׁוֹנִים. וְאֵין נוֹטְעִין בָּהּ גַּנּוֹת וּפַרְדֵּסִים. וְאֵינָהּ נִזְרַעַת וְאֵינָהּ נֶחֱרֶשֶׁת שֶׁמָּא תִּסְרַח. וְאֵין מְקַיְּמִין בָּהּ אִילָנוֹת חוּץ מִגִּנַּת וְרָדִים שֶׁהָיְתָה שָׁם מִימוֹת נְבִיאִים הָרִאשׁוֹנִים. וְאֵין מְקַיְּמִין בָּהּ אַשְׁפָּה מִפְּנֵי הַשְּׁרָצִים. וְאֵין מוֹצִיאִין הֵימֶנָּה זִיזִין וּגְזוּזְטְרָאוֹת לִרְשׁוּת הָרַבִּים מִפְּנֵי אֹהֶל הַטֻּמְאָה. וְאֵין עוֹשִׂין בָּהּ כִּבְשׁוֹנוֹת מִפְּנֵי הֶעָשָׁן. וְאֵין מְגַדְּלִין בָּהּ תַּרְנְגוֹלוֹת מִפְּנֵי הַקָּדָשִׁים. וְכֵן לֹא יְגַדְּלוּ הַכֹּהֲנִים תַּרְנְגוֹלִים בְּכָל אֶרֶץ יִשְׂרָאֵל מִפְּנֵי הַטָּהֳרוֹת. וְאֵין הַבַּיִת נֶחְלָט בָּהּ. וְאֵינוֹ מִטַּמֵּא בִּנְגָעִים. וְאֵינָהּ נַעֲשֵׂית עִיר הַנִּדַּחַת. וְאֵינָהּ מְבִיאָה עֶגְלָה עֲרוּפָה לְפִי שֶׁלֹּא נִתְחַלְּקָה לִשְׁבָטִים:","הַר הַבַּיִת מְקֻדָּשׁ מִמֶּנָּה שֶׁאֵין זָבִין וְזָבוֹת נִדּוֹת וְיוֹלְדוֹת נִכְנָסִין לְשָׁם. וּמֻתָּר לְהַכְנִיס הַמֵּת עַצְמוֹ לְהַר הַבַּיִת וְאֵין צָרִיךְ לוֹמַר טְמֵא מֵת שֶׁהוּא נִכְנָס לְשָׁם:","הַחֵיל מְקֻדָּשׁ מִמֶּנּוּ שֶׁאֵין עַכּוּ\"ם וּטְמֵא מֵת וּבוֹעֵל נִדָּה נִכְנָסִים לְשָׁם:","עֶזְרַת הַנָּשִׁים מְקֻדֶּשֶׁת מִן הַחֵיל שֶׁאֵין טְבוּל יוֹם נִכְנָס לְשָׁם. וְאִסּוּר זֶה מִדִּבְרֵיהֶם אֲבָל מִן הַתּוֹרָה מֻתָּר לִטְבוּל יוֹם לְהִכָּנֵס לְמַחֲנֵה לְוִיָּה. וּטְמֵא מֵת שֶׁנִּכְנַס לְעֶזְרַת הַנָּשִׁים אֵינוֹ חַיָּב חַטָּאת:","עֶזְרַת יִשְׂרָאֵל מְקֻדֶּשֶׁת מֵעֶזְרַת נָשִׁים שֶׁאֵין מְחֻסַּר כִּפּוּרִים נִכְנַס לְשָׁם. וְטָמֵא שֶׁנִּכְנַס לְשָׁם חַיָּב כָּרֵת:","עֶזְרַת הַכֹּהֲנִים מְקֻדֶּשֶׁת מִמֶּנָּה. שֶׁאֵין יִשְׂרָאֵל נִכְנָסִין לְשָׁם אֶלָּא בִּשְׁעַת צָרְכֵיהֶם לִסְמִיכָה וּלְכַפָּרָה וְלִשְׁחִיטָה וְלִתְנוּפָה:","בֵּין הָאוּלָם וְלַמִּזְבֵּחַ מְקֻדָּשׁ מִמֶּנָּה שֶׁאֵין בַּעֲלֵי מוּמִין וּפְרוּעֵי רֹאשׁ וּקְרוּעֵי בְּגָדִים נִכְנָסִין לְשָׁם:","הַהֵיכָל מְקֻדָּשׁ מִבֵּין הָאוּלָם וְלַמִּזְבֵּחַ. שֶׁאֵין נִכְנָס לְשָׁם אֶלָּא רְחוּץ יָדַיִם וְרַגְלַיִם:","בֵּית קֹדֶשׁ הַקָּדָשִׁים מְקֻדָּשׁ מִמֶּנּוּ שֶׁאֵין נִכְנָס לְשָׁם אֶלָּא כֹּהֵן גָּדוֹל בְּיוֹם הַכִּפּוּרִים בִּשְׁעַת הָעֲבוֹדָה:","מָקוֹם שֶׁהָיָה בַּעֲלִיָּה מְכֻוָּן עַל קֹדֶשׁ הַקָּדָשִׁים אֵין נִכְנָסִין לוֹ אֶלָּא פַּעַם אַחַת בְּשָׁבוּעַ לֵידַע מַה הוּא צָרִיךְ לְחַזֵּק בִּדְקוֹ. בְּשָׁעָה שֶׁנִּכְנָסִין הַבַּנָּאִים לִבְנוֹת וּלְתַקֵּן בַּהֵיכָל אוֹ לְהוֹצִיא מִשָּׁם אֶת הַטֻּמְאָה. מִצְוָה שֶׁיִּהְיוּ הַנִּכְנָסִין כֹּהֲנִים תְּמִימִים. לֹא מָצְאוּ תְּמִימִים יִכָּנְסוּ בַּעֲלֵי מוּמִין. וְאִם אֵין שָׁם כֹּהֲנִים יִכָּנְסוּ לְוִיִּם. לֹא מָצְאוּ לְוִיִּם יִכָּנְסוּ יִשְׂרָאֵל. מִצְוָה בִּטְהוֹרִים. לֹא מָצְאוּ טְהוֹרִים יִכָּנְסוּ טְמֵאִים. טָמֵא וּבַעַל מוּם יִכָּנֵס בַּעַל מוּם וְאַל יִכָּנֵס טָמֵא שֶׁהַטֻּמְאָה דְּחוּיָה בְּצִבּוּר. וְכָל הַנִּכְנָסִין לַהֵיכָל לְתַקֵּן יִכָּנְסוּ בְּתֵבוֹת. אִם אֵין שָׁם תֵּבוֹת אוֹ אִי אֶפְשָׁר לָהֶם שֶׁיַּעֲשׂוּ בְּתֵבוֹת יִכָּנְסוּ דֶּרֶךְ פְּתָחִים:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 14":["אַרְבַּע מִיתוֹת נִמְסרוּ לְבֵית דִּין. סְקִילָה וּשְׂרֵפָה וַהֲרִיגָה בְּסַיִף וְחֶנֶק. סְקִילָה וּשְׂרֵפָה מְפֹרָשִׁין הֵן בַּתּוֹרָה. וּמִפִּי משֶׁה רַבֵּנוּ לָמְדוּ שֶׁכָּל מִיתָה הָאֲמוּרָה בַּתּוֹרָה סְתָם הִיא חֶנֶק. וְהַהוֹרֵג אֶת חֲבֵרוֹ מִיתָתוֹ בְּסַיִף. וְכֵן אַנְשֵׁי עִיר הַנִּדַּחַת מִיתָתָן בְּסַיִף:","כָּל מִיתָה מֵהֶם מִצְוַת עֲשֵׂה הִיא לְבֵית דִּין לַהֲרֹג בָּהּ מִי שֶׁנִּתְחַיֵּב בָּהּ. וְאֵין רְשׁוּת לַמֶּלֶךְ לַהֲרֹג בְּאַחַת מֵהֶן אֶלָּא בְּסַיִף בִּלְבַד:","כָּל מְחֻיָּב מִיתַת בֵּית דִּין שֶׁלֹּא הֵמִיתוּ אוֹתוֹ בֵּית דִּין בִּטְּלוּ מִצְוַת עֲשֵׂה וְלֹא עָבְרוּ עַל מִצְוַת לֹא תַּעֲשֶׂה. חוּץ מִן הַמְכַשֵּׁף שֶׁאִם לֹא הֱמִיתוּהוּ עָבְרוּ עַל מִצְוַת לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כב יז) \"מְכַשֵּׁפָה לֹא תְחַיֶּה\":","סְקִילָה חֲמוּרָה מִן הַשְּׂרֵפָה וּשְׂרֵפָה חֲמוּרָה מִן הַסַּיִף וְהַסַּיִף חֲמוּרָה מִן הַחֶנֶק. וְכָל מִי שֶׁנִּתְחַיֵּב בִּשְׁתֵּי מִיתוֹת נִדּוֹן בַּחֲמוּרָה בֵּין שֶׁעָבַר שְׁתֵּי עֲבֵרוֹת זוֹ אַחַר זוֹ בֵּין שֶׁעָבַר עֲבֵרָה אַחַת שֶׁחַיָּב עָלֶיהָ שְׁתֵּי מִיתוֹת אֲפִלּוּ נִגְמַר דִּינוֹ לְקַלָּה וְאַחַר כָּךְ עָבַר עַל הַחֲמוּרָה וְנִגְמַר דִּינוֹ נִדּוֹן בַּחֲמוּרָה:","וְאֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה דָּנִין אוֹתָן בְּאַרְבַּע מִיתוֹת:","כָּל חַיָּבֵי מִיתוֹת שֶׁנִּתְעָרְבוּ זֶה בָּזֶה נִדּוֹן כָּל אֶחָד מֵהֶן בַּקַּלָּה שֶׁבָּהֶן:","מִי שֶׁנִּגְמַר דִּינוֹ שֶׁנִּתְעָרֵב עִם שְׁאָר הָעָם וְלֹא נוֹדַע מִי הוּא מֵאֵלּוּ. אוֹ מִי שֶׁלֹּא נִגְמַר דִּינוֹ שֶׁנִּתְעָרֵב עִם מִי שֶׁנִּגְמַר דִּינוֹ וְלֹא נוֹדַע מִי הוּא. כֻּלָּן פְּטוּרִין לְפִי שֶׁאֵין גּוֹמְרִין דִּינוֹ שֶׁל אָדָם אֶלָּא בְּפָנָיו:","מִי שֶׁעָמַד עַל נַפְשׁוֹ וְלֹא יָכְלוּ בֵּית דִּין לְאָסְרוֹ עַד שֶׁיְּמִיתוּהוּ בְּמִיתָה שֶׁהוּא חַיָּב בָּהּ הוֹרְגִין אוֹתוֹ עֵדָיו בְּכָל מִיתָה שֶׁיְּכוֹלִין לַהֲמִיתוֹ בָּהּ מֵאַחַר שֶׁנִּגְמַר דִּינוֹ. וְאֵין רְשׁוּת לִשְׁאָר הָעָם לַהֲמִיתוֹ תְּחִלָּה. לְפִיכָךְ אִם נִקְטְעָה יַד הָעֵדִים פָּטוּר. וְאִם הָיוּ הָעֵדִים גִּדְּמִין מִתְּחִלָּה יֵהָרֵג בְּיַד אֲחֵרִים. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר מְחֻיְּבֵי מִיתוֹת בֵּית דִּין חוּץ מִן הָרוֹצֵחַ. אֲבָל הוֹרֵג נֶפֶשׁ שֶׁנִּגְמַר דִּינוֹ רוֹדְפִין אַחֲרָיו בְּכָל דָּבָר וּבְיַד כָּל אָדָם עַד שֶׁמֵּמִיתִין אוֹתוֹ:","כָּל הֲרוּגֵי בֵּית דִּין אֵין קוֹבְרִין אוֹתָן בְּקִבְרֵי אֲבוֹתֵיהֶם בִּכְלַל יִשְׂרָאֵל. אֶלָּא שְׁנֵי קְבָרוֹת מְתַקְּנִין לָהֶן בֵּית דִּין אֶחָד לַנִּסְקָלִין וְלַנִּשְׂרָפִין וְאֶחָד לַנֶּהֱרָגִין וְלַנֶּחְנָקִין. וְדָבָר זֶה הֲלָכָה מִפִּי הַשְּׁמוּעָה. נִתְאַכֵּל הַבָּשָׂר הָיוּ מְלַקְּטִין אֶת הָעֲצָמוֹת וְקוֹבְרִין אוֹתָן בְּקִבְרוֹת אֲבוֹתֵיהֶן. וְיֵשׁ לִקְרוֹבֵיהֶן לַעֲשׂוֹת לָהֶן אָרוֹן וְתַכְרִיכִין:","צְרִיכִין בֵּית דִּין לְהִתְיַשֵּׁב בְּדִינֵי נְפָשׁוֹת וּלְהַמְתִּין וְלֹא יָאִיצוּ. וְכָל בֵּית דִּין שֶׁהָרְגוּ נֶפֶשׁ בְּשֶׁבַע שָׁנִים הֲרֵי אֵלּוּ חַבְּלָנִין. אַף עַל פִּי כֵן אִם אֵרַע לָהֶם לַהֲרֹג בְּכָל יוֹם וְיוֹם הוֹרְגִין. אֲבָל אֵין דָּנִין לְעוֹלָם שְׁנַיִם בְּיוֹם אֶחָד אֶלָּא דָּנִין זֶה הַיּוֹם וְהַשֵּׁנִי לְמָחָר. הָיוּ שְׁנֵיהֶם בַּעֲבֵרָה אַחַת וּמִיתָה אַחַת כְּגוֹן נוֹאֵף עִם נוֹאֶפֶת דָּנִין שְׁנֵיהֶם בְּיוֹם אֶחָד. לְפִיכָךְ אִם הָיָה הַנּוֹאֵף בּוֹעֵל בַּת כֹּהֵן הוֹאִיל וְהוּא בְּחֶנֶק וְהִיא בִּשְׂרֵפָה אֵין הוֹרְגִין שְׁנֵיהֶן בְּיוֹם אֶחָד:","אֵין דָּנִין דִּינֵי נְפָשׁוֹת אֶלָּא בִּפְנֵי הַבַּיִת וְהוּא שֶׁיִּהְיֶה בֵּית דִּין הַגָּדוֹל שָׁם בַּלִּשְׁכָּה שֶׁבַּמִּקְדָּשׁ שֶׁנֶּאֱמַר בְּזָקֵן מַמְרֵא (דברים יז יב) \"לְבִלְתִּי שְׁמֹעַ אֶל הַכֹּהֵן\" וְגוֹ' וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבִּזְמַן שֶׁיֵּשׁ כֹּהֵן מַקְרִיב עַל גַּבֵּי הַמִּזְבֵּחַ יֵשׁ דִּינֵי נְפָשׁוֹת וְהוּא שֶׁיִּהְיֶה בֵּית דִּין הַגָּדוֹל בִּמְקוֹמוֹ:","בַּתְּחִלָּה כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ הָיוּ בֵּית דִּין הַגָּדוֹל יוֹשְׁבִין בְּלִשְׁכַּת הַגָּזִית שֶׁהָיְתָה בְּעֶזְרַת יִשְׂרָאֵל וְהַמָּקוֹם שֶׁהָיוּ יוֹשְׁבִין בּוֹ חֹל הָיָה שֶׁאֵין יְשִׁיבָה בַּעֲזָרָה אֶלָּא לְמַלְכֵי בֵּית דָּוִד. וּכְשֶׁנִּתְקַלְקְלָה הַשּׁוּרָה גָּלוּ מִמָּקוֹם לְמָקוֹם וְלַעֲשָׂרָה מְקוֹמוֹת גָּלוּ וְסוֹפָן לִטְבֶרְיָא וּמִשָּׁם לֹא עָמַד בֵּית דִּין גָּדוֹל עַד עַתָּה. וְקַבָּלָה הִיא שֶׁבִּטְבֶרְיָא עֲתִידִין לַחְזֹר תְּחִלָּה וּמִשָּׁם נֶעֱתָקִין לַמִּקְדָּשׁ:","אַרְבָּעִים שָׁנָה קֹדֶם חֻרְבַּן בַּיִת שֵׁנִי בָּטְלוּ דִּינֵי נְפָשׁוֹת מִיִּשְׂרָאֵל אַף עַל פִּי שֶׁהָיָה הַמִּקְדָּשׁ קַיָּם. מִפְּנֵי שֶׁגָּלוּ הַסַּנְהֶדְרִין וְלֹא הָיוּ שָׁם בִּמְקוֹמָן בַּמִּקְדָּשׁ:","בִּזְמַן שֶׁדָּנִין דִּינֵי נְפָשׁוֹת בְּאֶרֶץ יִשְׂרָאֵל דָּנִין דִּינֵי נְפָשׁוֹת בְּחוּצָה לָאָרֶץ. וְהוּא שֶׁיִּהְיוּ הַסַּנְהֶדְרִין סְמוּכִין בָּאָרֶץ כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁהַסַּנְהֶדְרִין נוֹהֶגֶת בָּאָרֶץ וּבְחוּצָה לָאָרֶץ:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 25":["אָסוּר לָאָדָם לִנְהֹג בִּשְׂרָרָה עַל הַצִּבּוּר וּבְגַסּוּת הָרוּחַ אֶלָּא בַּעֲנָוָה וְיִרְאָה. וְכָל פַּרְנָס הַמַּטִּיל אֵימָה יְתֵרָה עַל הַצִּבּוּר שֶׁלֹּא לְשֵׁם שָׁמַיִם נֶעֱנָשׁ. וְאֵינוֹ רוֹאֶה לוֹ בֶּן תַּלְמִיד חָכָם שֶׁנֶּאֱמַר (איוב לז כד) \"לָכֵן יְרֵאוּהוּ אֲנָשִׁים לֹא יִרְאֶה כָּל חַכְמֵי לֵב\":","וְכֵן אָסוּר לוֹ לִנְהֹג בָּהֶן קַלּוּת רֹאשׁ אַף עַל פִּי שֶׁהֵן עַמֵּי הָאָרֶץ. וְלֹא יַפְסִיעַ עַל רָאשֵׁי עַם הַקֹּדֶשׁ. אַף עַל פִּי שֶׁהֵן הֶדְיוֹטוֹת וּשְׁפָלִים בְּנֵי אַבְרָהָם יִצְחָק וְיַעֲקֹב הֵם וְצִבְאוֹת הַשֵּׁם שֶׁהוֹצִיא מֵאֶרֶץ מִצְרַיִם בְּכֹחַ גָּדוֹל וּבְיַד חֲזָקָה. וְסוֹבֵל טֹרַח הַצִּבּוּר וּמַשָּׂאָן כְּמשֶׁה רַבֵּנוּ. שֶׁנֶּאֱמַר בּוֹ כַּאֲשֶׁר יִשָּׂא הָאֹמֵן אֶת הַיֹּנֵק. וַהֲרֵי הוּא אוֹמֵר (דברים א טז) \"וָאֲצַוֶּה אֶת שֹׁפְטֵיכֶם\" זוֹ אַזְהָרָה לַדַּיָּן שֶׁיִּסְבּל אֶת הַצִּבּוּר (במדבר יא יב) \"כַּאֲשֶׁר יִשָּׂא הָאוֹמֵן אֶת הַיּוֹנֵק\". צֵא וּלְמַד מִמּשֶׁה רַבָּן שֶׁל כָּל הַנְּבִיאִים כֵּיוָן שֶׁשְּׁלָחוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם וְנֶאֱמַר (שמות ו יג) \"וַיְצַוֵּם אֶל בְּנֵי יִשְׂרָאֵל\" אָמְרוּ מִפִּי הַקַּבָּלָה שֶׁאָמַר לָהֶם לְמשֶׁה וּלְאַהֲרֹן עַל מְנָת שֶׁיִּהְיוּ מְקַלְּלִים אֶתְכֶם וְסוֹקְלִין אֶתְכֶם בַּאֲבָנִים:","כְּדֶרֶךְ שֶׁנִּצְטַוָּה הַדַּיָּן לִנְהֹג בְּמִצְוָה זוֹ כָּךְ נִצְטַוּוּ הַצִּבּוּר לִנְהֹג כָּבוֹד בַּדַּיָּן. שֶׁנֶּאֱמַר (דברים א יח) \"וָאֲצַוֶּה אֶתְכֶם\" זוֹ אַזְהָרָה לַצִּבּוּר שֶׁתִּהְיֶה אֵימַת הַדַּיָּן עֲלֵיהֶן וְלֹא יִתְבַּזֶּה בִּפְנֵיהֶם וְלֹא יִנְהֹג קַלּוּת רֹאשׁ בְּעַצְמוֹ:","כֵּיוָן שֶׁנִּתְמַנָּה אָדָם פַּרְנָס עַל הַצִּבּוּר אָסוּר בַּעֲשִׂיַּת מְלָאכָה בִּפְנֵי שְׁלֹשָׁה כְּדֵי שֶׁלֹּא יִתְבַּזֶּה בִּפְנֵיהֶם. אִם הַמְּלָאכָה בָּרַבִּים אֲסוּרָה עָלָיו קַל וָחֹמֶר לֶאֱכל וְלִשְׁתּוֹת וּלְהִשְׁתַּכֵּר בִּפְנֵי רַבִּים וּבִכְנִיסַת עַמֵּי הָאָרֶץ וּבִסְעוּדַת מֵרֵעוּת. אוֹי לָהֶם לְאוֹתָן הַדַּיָּנִים שֶׁנָּהֲגוּ בְּכָךְ מֵעֶלְבּוֹן תּוֹרַת משֶׁה שֶׁבִּזּוּ דִּינֶיהָ וְהִשְׁפִּילוּהָ עַד אֶרֶץ וְהִגִּיעוּהָ עַד עָפָר וְגָרְמוּ רָעָה לָהֶן וְלִבְנֵי בְּנֵיהֶם בָּעוֹלָם הַזֶּה וְלָעוֹלָם הַבָּא:","אָסוּר לִנְהֹג קַלּוּת רֹאשׁ בְּשָׁלִיחַ בֵּית דִּין וַהֲרֵי הַשָּׁלִיחַ נֶאֱמָן כִּשְׁנַיִם לְעִנְיַן הַנִּדּוּי. שֶׁאִם אָמַר פְּלוֹנִי הִקְלַנִי אוֹ הִקְלָה הַדַּיָּן אוֹ לֹא רָצָה לָבוֹא לְדִין מְשַׁמְּתִין אוֹתוֹ עַל פִּיו. אֲבָל אֵין כּוֹתְבִין פִּיתְחָא עָלָיו עַד שֶׁיָּבוֹאוּ שְׁנַיִם וְיָעִידוּ עָלָיו שֶׁנִּמְנָע לָבוֹא לְבֵית דִּין:","אֵין שָׁלִיחַ בֵּית דִּין חַיָּב בַּאֲמִירַת דְּבָרִים מִשּׁוּם לָשׁוֹן הָרַע. וְכָל הַמְצַעֵר שָׁלִיחַ בֵּית דִּין יֵשׁ לְבֵית דִּין רְשׁוּת לְהַכּוֹתוֹ מַכַּת מַרְדּוּת:","שָׁלִיחַ שֶׁאָמַר פְּלוֹנִי שְׁלָחַנִי בְּשֵׁם אֶחָד מִן הַדַּיָּנִים וְלֹא רָצָה בַּעַל דִּין לָבוֹא אֵין כּוֹתְבִין עָלָיו פִּיתְחָא שֶׁל שַׁמְתָּא עַד שֶׁיֹּאמַר מִשֵּׁם שְׁלָשְׁתָּן. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁהָלַךְ הַשָּׁלִיחַ בְּיוֹם שֶׁאֵינוֹ יָדוּעַ לִישִׁיבַת הַדַּיָּנִים. אֲבָל בַּיּוֹם הַיָּדוּעַ שֶׁהַדַּיָּנִים יוֹשְׁבִים בּוֹ לְדִין הַכּל יוֹדְעִים שֶׁכָּל הַדַּיָּנִים מְקֻבָּצִין וְאַף עַל פִּי שֶׁבָּא הַשָּׁלִיחַ בְּשֵׁם אֶחָד כְּאִלּוּ בָּא בְּשֵׁם שְׁלָשְׁתָּן:","מִי שֶׁשָּׁלְחוּ לוֹ בֵּית דִּין לָבוֹא וְלֹא בָּא לַדִּין מְנַדִּין אוֹתוֹ וְכוֹתְבִין עָלָיו פִּיתְחָא וְנוֹתֵן שְׂכַר הַסּוֹפֵר וּבָעֵת שֶׁיָּבוֹא קוֹרְעִין הַפִּיתְחָא. כָּתְבוּ לוֹ פִּיתְחָא מִפְּנֵי שֶׁלֹּא קִבֵּל הַדִּין כֵּיוָן שֶׁאָמַר הֲרֵינִי מְקַבֵּל הַדִּין קוֹרְעִין נִדּוּיוֹ. קָבְעוּ לוֹ בֵּית דִּין זְמַן שֶׁיָּבוֹא הַיּוֹם וְלֹא בָּא כָּל אוֹתוֹ הַיּוֹם כּוֹתְבִין עָלָיו פִּיתְחָא לָעֶרֶב. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה בַּמְּדִינָה וּמָרַד וְלֹא בָּא. אֲבָל אִם הָיָה בַּכְּפָרִים וְיוֹצֵא וְנִכְנָס קוֹבְעִים לוֹ זְמַן שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. וְאִם שָׁלַם יוֹם שֵׁנִי וְלֹא בָּא אֵין כּוֹתְבִין עָלָיו פִּיתְחָא עַד לְמָחָר:","אֵין קוֹבְעִין זְמַן לֹא בִּימֵי נִיסָן וְלֹא בִּימֵי תִּשְׁרֵי מִפְּנֵי שֶׁהָעָם טְרוּדִין בְּמוֹעֲדוֹת. וְלֹא בְּעֶרֶב שַׁבָּת וְלֹא בְּעֶרֶב יוֹם טוֹב. אֲבָל קוֹבְעִין בְּנִיסָן שֶׁיָּבוֹא אַחַר נִיסָן וּבְתִשְׁרֵי שֶׁיָּבוֹא אַחַר תִּשְׁרֵי. אֲבָל לֹא קוֹבְעִין בְּעֶרֶב שַׁבָּת שֶׁיָּבוֹא אַחַר שַׁבָּת מִפְּנֵי שֶׁהַכּל טְרוּדִין בְּעֶרֶב שַׁבָּת:","מִי שֶׁהוּא בַּמְּדִינָה וְהָלַךְ שָׁלִיחַ בֵּית דִּין וְלֹא מְצָאוֹ אֵין קוֹבְעִין לוֹ זְמַן עַד שֶׁיִּמְצָא אוֹתוֹ הַשָּׁלִיחַ וְיֹאמַר לוֹ. הָיָה בִּכְפָר חוּץ לַמְּדִינָה אִם דַּרְכּוֹ לָבוֹא בְּאוֹתוֹ הַיּוֹם אוֹמֵר הַשָּׁלִיחַ אֲפִלּוּ לְאֶחָד מִן הַשְּׁכֵנִים אֲפִלּוּ לְאִשָּׁה אִם יָבוֹא פְּלוֹנִי הוֹדִיעוּהוּ שֶׁבֵּית דִּין קָבְעוּ לוֹ זְמַן שֶׁיָּבוֹא לְבֵית דִּין. וְאִם לֹא בָּא מְנַדִּין אוֹתוֹ לָעֶרֶב. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁאֵין הַדֶּרֶךְ שֶׁדַּרְכּוֹ לֵילֵךְ בָּהּ עַל מְקוֹם בֵּית דִּין אֲבָל אִם דַּרְכּוֹ עֲלֵיהֶן אֵין מְנַדִּין אוֹתוֹ עַד שֶׁיּוֹדִיעוֹ הַשָּׁלִיחַ בְּעַצְמוֹ שֶׁמָּא לֹא אָמְרוּ לוֹ הַשְּׁכֵנִים. שֶׁהֲרֵי הֵם אוֹמְרִין דַּרְכּוֹ עַל פֶּתַח בֵּית דִּין וּכְבָר הָלַךְ אֲלֵיהֶם וְנִפְטַר. וְכֵן אִם לֹא בָּא בַּמְּדִינָה עַד לְמָחָר אֵין סוֹמְכִין עַל הַשְּׁכֵנִים שֶׁמָּא שָׁכְחוּ וְלֹא אָמְרוּ לוֹ:","מִי שֶׁבָּא לְבֵית דִּין וְקִבֵּל הַדִּין וְאָמְרוּ לוֹ לְשַׁלֵּם וְהָלַךְ וְלֹא שִׁלֵּם אֵין מְנַדִּין אוֹתוֹ עַד שֶׁיַּתְרוּ בּוֹ שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. וְאַחַר כָּךְ מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן מַה שֶּׁהוּא חַיָּב. וְאִם עָמַד שְׁלֹשִׁים יוֹם וְלֹא תָּבַע לְהַתִּיר נִדּוּיוֹ מַחְרִימִין אוֹתוֹ:"],"Mishneh Torah, Theft 4":["הַטוֹעֵן שֶׁנִּגְנַב מִבֵּיתוֹ הַפִּקָּדוֹן אִם נִשְׁבַּע וְאַחַר כָּךְ בָּאוּ עֵדִים שֶׁשֶּׁקֶר טָעַן וְשֶׁהַפִּקָּדוֹן הַזֶּה אֶצְלוֹ הֲרֵי זֶה מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל שֶׁהֲרֵי הוּא עַצְמוֹ הַגַּנָּב. וְאִם טָבַח וּמָכַר אַחַר שֶׁנִּשְׁבַּע מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה. וְאֵינוֹ מֵבִיא אָשָׁם עַל פִּי עֵדִים עַל שְׁבוּעָתוֹ. וְאֵינוֹ מֵבִיא חֹמֶשׁ שֶׁאֵין הַחֹמֶשׁ מִשְׁתַּלֵּם עִם הַכֶּפֶל. וְאִם בָּאוּ עֵדִים קֹדֶם שֶׁיִּשָּׁבַע אֵינוֹ מְשַׁלֵּם אֶלָּא הַקֶּרֶן בִּלְבַד:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּשְׁבַּע קֹדֶם שֶׁיִּשְׁלַח בַּפִּקָּדוֹן יָד. אֲבָל אִם שָׁלַח בּוֹ יָד וְטָעַן טַעֲנַת גַּנָּב וְנִשְׁבַּע וּבָאוּ עֵדִים פָּטוּר מִן הַכֶּפֶל שֶׁכֵּיוָן שֶׁשָּׁלַח יָד נִתְחַיֵּב בּוֹ וְקָנָהוּ:","וְכֵן הַטּוֹעֵן טַעֲנַת אֲבֵדָה בְּפִקָּדוֹן וְנִשְׁבַּע וְחָזַר וְטָעַן טַעֲנַת גַּנָּב וְנִשְׁבַּע וְאַחַר כָּךְ בָּאוּ עֵדִים פָּטוּר מִן הַכֶּפֶל שֶׁכְּבָר יָצָא הַפִּקָּדוֹן מִידֵי הַבְּעָלִים מִשְּׁבוּעָה רִאשׁוֹנָה:","הַטּוֹעֵן טַעֲנַת גַּנָּב בָּאֲבֵדָה וְנִשְׁבַּע וְאַחַר כָּךְ בָּאוּ עֵדִים שֶׁהָאֲבֵדָה בִּרְשׁוּתוֹ וְשֶׁקֶר טָעַן מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל שֶׁנֶּאֱמַר (שמות כב ח) \"עַל כָּל אֲבֵדָה\". וְהוּא שֶׁיִּטְעֹן שֶׁנִּגְנְבָה בְּלִסְטִים מְזֻיָּן שֶׁהוּא אָנוּס וּפָטוּר. אֲבָל אִם טָעַן שֶׁנִּגְנְבָה בְּלֹא אֹנֶס פָּטוּר מִן הַכֶּפֶל מִפְּנֵי שֶׁהוּא חַיָּב לְשַׁלֵּם עַל פִּי טַעֲנָתוֹ שֶׁשּׁוֹמֵר אֲבֵדָה כְּשׁוֹמֵר שָׂכָר הוּא כְּמוֹ שֶׁיִּתְבָּאֵר:","הַטּוֹעֵן טַעֲנַת גַּנָּב בְּפִקָּדוֹן וְנִשְׁבַּע. וְאַחַר כָּךְ בָּאוּ עֵדִים שֶׁהוּא בִּרְשׁוּתוֹ. וְחָזַר וְטָעַן בּוֹ טַעֲנַת גַּנָּב וְנִשְׁבַּע וְאַחַר כָּךְ בָּאוּ עֵדִים שֶׁעֲדַיִן בִּרְשׁוּתוֹ הוּא. אֲפִלּוּ מֵאָה פְּעָמִים חַיָּב כֶּפֶל עַל כָּל טַעֲנָה וְטַעֲנָה. וְאִם נִשְׁבַּע חָמֵשׁ פְּעָמִים נִמְצָא מְשַׁלֵּם שִׁשָּׁה הַקֶּרֶן שֶׁהִפְקִיד אֶצְלוֹ וַחֲמִשָּׁה בְּקֶרֶן מִשּׁוּם חֲמִשָּׁה כְּפֵלוֹת שֶׁל חָמֵשׁ שְׁבוּעוֹת:","טָעַן טַעֲנַת גַּנָּב וְנִשְׁבַּע וְחָזַר וְטָעַן טַעֲנַת אֲבֵדָה וְנִשְׁבַּע. וּבָאוּ עֵדִים שֶׁלֹּא נִגְנַב וְהוֹדָה הוּא שֶׁלֹּא אָבַד הוֹאִיל וּמְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל עַל פִּי עֵדִים אֵינוֹ מְשַׁלֵּם חֹמֶשׁ עַל שְׁבוּעָה אַחֲרוֹנָה אַף עַל פִּי שֶׁהוֹדָה. שֶׁהַמָּמוֹן הַמְחַיְּבוֹ בְּכֶפֶל פּוֹטְרוֹ מִן הַחֹמֶשׁ:","מָסַר שׁוֹרוֹ לִשְׁנַיִם וְטָעֲנוּ טַעֲנַת גַּנָּב וְנִשְׁבְּעוּ וְהוֹדָה אֶחָד מֵהֶם וְהַשֵּׁנִי בָּאוּ עָלָיו עֵדִים. שְׁנֵיהֶן מְשַׁלְּמִין אֶת הַקֶּרֶן. וְאִם תָּפַשׂ בַּעַל הַפִּקָּדוֹן אֶת הַכֶּפֶל אֵין מוֹצִיאִין מִיָּדוֹ. וְזֶה שֶׁהוּא מְשַׁלֵּם חֹמֶשׁ כִּשְׁאָר הַנִּשְׁבָּעִין שְׁבוּעַת הַפִּקָּדוֹן שֶׁהוֹדוּ מֵעַצְמָן:","בַּעַל הַפִּקָּדוֹן שֶׁתָּבַע אֶת הַשּׁוֹמֵר וְנִשְׁבַּע שֶׁנִּגְנַב וְאַחַר כָּךְ הֻכַּר הַגַּנָּב וְתָבַע הַשּׁוֹמֵר אֶת הַגַּנָּב וְהוֹדָה לוֹ הַגַּנָּב שֶׁגָּנַב וְתָבַע בַּעַל הַפִּקָּדוֹן אֶת הַגַּנָּב וְכָפַר וּבָאוּ עֵדִים שֶׁגָּנַב. אִם בֶּאֱמֶת נִשְׁבַּע הַשּׁוֹמֵר כְּשֶׁטָּעַן שֶׁנִּגְנַב נִפְטַר הַגַּנָּב מִן הַכֶּפֶל בְּהוֹדָאָתוֹ לַשּׁוֹמֵר. וְאִם בְּשֶׁקֶר נִשְׁבַּע אֵין מוֹצִיאִין הַכֶּפֶל מִן הַגַּנָּב. וְאִם תָּפְשׂוּ הַבְּעָלִים הַכֶּפֶל אֵין מוֹצִיאִין מִיָּדָן. תָּבְעוּ הַבְּעָלִים אֶת הַשּׁוֹמֵר וְשִׁלֵּם וְאַחַר כָּךְ הֻכַּר הַגַּנָּב וּתְבָעוּהוּ הַבְּעָלִים וְהוֹדָה לָהֶן שֶׁגָּנַב וְאַחַר כָּךְ תְּבָעוֹ הַשּׁוֹמֵר וְכָפַר בּוֹ וּבָאוּ עֵדִים שֶׁגָּנַב אֵין מוֹצִיאִין הַכֶּפֶל מִן הַגַּנָּב וְאִם תָּפַשׂ הַשּׁוֹמֵר אֶת הַכֶּפֶל אֵין מוֹצִיאִין מִיָּדוֹ וְכֵן הַדִּין בְּתַשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה אִם טָבַח הַגַּנָּב אוֹ מָכַר:","הַטּוֹעֵן טַעֲנַת גַּנָּב בְּפִקָּדוֹן שֶׁל קָטָן אַף עַל פִּי שֶׁנָּתַן לוֹ כְּשֶׁהוּא קָטָן וּתְבָעוֹ כְּשֶׁהוּא גָּדוֹל וְנִשְׁבַּע וְאַחַר כָּךְ בָּאוּ עֵדִים הֲרֵי זֶה פָּטוּר מִן הַכֶּפֶל שֶׁנֶּאֱמַר (שמות כב ו) \"כִּי יִתֵּן אִישׁ\" וְאֵין נְתִינַת קָטָן כְּלוּם וְצָרִיךְ שֶׁתִּהְיֶה נְתִינָה וּתְבִיעָה שָׁוִין בַּגָּדוֹל:","שׁוֹמֵר שֶׁגָּנַב מֵרְשׁוּתוֹ כְּגוֹן שֶׁגָּנַב טָלֶה מֵעֵדֶר שֶׁהֻפְקַד אֶצְלוֹ וְסֶלַע מִכִּיס שֶׁהֻפְקַד אֶצְלוֹ. אִם יֵשׁ עָלָיו עֵדִים חַיָּב בְּכֶפֶל. וְאַף עַל פִּי שֶׁהֶחְזִיר הַסֶּלַע לִמְקוֹמוֹ וְהַטָּלֶה לְעֶדְרוֹ הֲרֵי זֶה חַיָּב בְּאַחֲרָיוּתָן עַד שֶׁיּוֹדִיעַ הַבְּעָלִים. שֶׁהֲרֵי כָּלְתָה שְׁמִירָתוֹ וּכְאִלּוּ לֹא הֶחְזִיר כְּלוּם עַד שֶׁיּוֹדִיעַ בְּעָלָיו. אֲבָל הַגּוֹנֵב סֶלַע מִכִּיס חֲבֵרוֹ אוֹ כְּלִי מִבֵּיתוֹ וְהֶחְזִיר דָּבָר הַגָּנוּב מִבֵּיתוֹ לִמְקוֹמוֹ אִם יָדְעוּ הַבְּעָלִים בִּגְנֵבָתוֹ וְלֹא יָדְעוּ בַּחֲזִירָתוֹ עֲדַיִן הַגַּנָּב חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיִּמְנֶה אֶת מְעוֹתָיו:","מָנָה אֶת כִּיסוֹ וּמְצָאוֹ שָׁלֵם הַמִּנְיָן פָּטוּר. וְאִם לֹא יָדְעוּ הַבְּעָלִים לֹא בִּגְנֵבָתוֹ וְלֹא בַּחֲזִירָתוֹ אֲפִלּוּ מִנְיָן אֵינוֹ צָרִיךְ אֶלָּא כֵּיוָן שֶׁהֶחֱזִירוֹ לִמְקוֹמוֹ נִפְטַר מֵאַחֲרָיוּתוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּדָבָר שֶׁאֵין בּוֹ רוּחַ חַיִּים. אֲבָל הַגּוֹנֵב טָלֶה מֵעֵדֶר חֲבֵרוֹ וְיָדְעוּ בּוֹ הַבְּעָלִים וְהֶחֱזִירוֹ לָעֵדֶר שֶׁלֹּא מִדַּעַת הַבְּעָלִים וּמֵת אוֹ נִגְנַב חַיָּב בְּאַחֲרָיוּתוֹ. וְאִם מָנוּ אֶת הַצֹּאן וְהִיא שְׁלֵמָה פָּטוּר. וְאִם לֹא יָדְעוּ הַבְּעָלִים לֹא בִּגְנֵבָתוֹ וְלֹא בַּחֲזִירָתוֹ אַף עַל פִּי שֶׁמָּנוּ אֶת הַצֹּאן וְהִיא שְׁלֵמָה חַיָּב בְּאַחֲרָיוּתוֹ עַד שֶׁיּוֹדִיעַ אֶת הַבְּעָלִים כְּדֵי שֶׁיִּשְׁמְרוּ אֶת הַטָּלֶה הַגָּנוּב שֶׁהֲרֵי לִמְדוֹ דֶּרֶךְ אַחֶרֶת חוּץ מִדֶּרֶךְ שְׁאָר הַצֹּאן שֶׁבְּעֵדֶר זֶה:"],"Mishneh Torah, Things Forbidden on the Altar 7":["לא כָּל דָּבָר שֶׁאֵינוֹ פָּסוּל מֵבִיא אוֹתוֹ לְכַתְּחִלָּה. כֵּיצַד. הָיָה חַיָּב עוֹלָה לֹא יָבִיא שֶׂה כָּחוּשׁ וְכָעוּר וְיֹאמַר הֲרֵי אֵין בּוֹ מוּם. וְעַל זֶה נֶאֱמַר (מלאכי א-יד) \"וְאָרוּר נוֹכֵל\" וְגוֹ'. אֶלָּא כָּל שֶׁיָּבִיא לְקָרְבָּן יָבִיא מִן הַמֻּבְחָר:","וְכָךְ הָיוּ עוֹשִׂין בִּזְמַן הַמִּקְדָּשׁ. מְבִיאִין אֵילִים מִמּוֹאָב. וּמְבִיאִין כְּבָשִׂים שֶׁגַּבֵּיהֶן רְחָבִים מֵחֶבְרוֹן. וּמְבִיאִין עֲגָלִים מִן הַשָּׁרוֹן. וְגוֹזָלוֹת מֵהַר הַמֶּלֶךְ. וּמְבִיאִין יַיִן מִקַּרְחִיִּין וְהַלּוֹטִיִּין. וְסלֶת מִמִּכְמָשׁ וְיוֹחָנָה. וּמְבִיאִין שֶׁמֶן מִתְּקוֹעַ:","כָּל הָעֵצִים הַחֲדָשִׁים כְּשֵׁרִים לַמַּעֲרָכָה. וְלֹא הָיוּ מְבִיאִין מִשֶּׁל זַיִת וְלֹא מִשֶּׁל גֶּפֶן מִשּׁוּם יִשּׁוּב אֶרֶץ יִשְׂרָאֵל. וּבְאֵלּוּ הָיוּ רְגִילִין בְּמֻרְבִּיּוֹת שֶׁל תְּאֵנָה שֶׁל חֲדָשִׁים שֶׁאֵינָן בַּיִּשּׁוּב. וּבְשֶׁל אֱגוֹז וּבְשֶׁל עֵץ שֶׁמֶן. וְהַגְּזָרִין שֶׁעָשָׂה משֶׁה אַמָּה אָרְכָּן וְאַמָּה רָחְבָּן וְעָבְיָן כְּמַחַק גָּדִישׁ שֶׁל סְאָה וּכְמוֹתָן עוֹשִׂין לְדוֹרוֹת:","וְכֵיצַד הָיוּ עוֹשִׂין בִּזְרִיעַת חִטֵּי הַמְּנָחוֹת וְהַנְּסָכִים. נָר חֲצִי הַשָּׂדֶה בְּשָׁנָה רִאשׁוֹנָה וְזָרַע חֶצְיָהּ. וּבְשָׁנָה שְׁנִיָּה נָר הַחֵצִי שֶׁזָּרַע בָּרִאשׁוֹנָה וְזָרַע הַחֵצִי הָאַחֵר קֹדֶם לַפֶּסַח שִׁבְעִים יוֹם. וְאִם לֹא הָיְתָה הַשָּׂדֶה עֲבוּדָּה חוֹרֵשׁ וְשׁוֹנֶה וְאַחַר כָּךְ זוֹרֵעַ. וּבוֹרֵר הַחִטִּים יָפֶה יָפֶה וְאַחַר כָּךְ שָׁף אֶת הַחִטִּים וּבוֹעֵט בָּהֶן הַרְבֵּה עַד שֶׁיִּתְקַלְּפוּ:","כָּל הַחִטִּים שֶׁל מְנָחוֹת טְעוּנוֹת שְׁלֹשׁ מֵאוֹת שִׁיפָה וַחֲמֵשׁ מֵאוֹת בְּעִיטָה. שָׁף אַחַת וּבוֹעֵט שְׁתַּיִם. שָׁף שְׁתַּיִם וּבוֹעֵט שָׁלֹשׁ. נִמְצְאוּ שָׁלֹשׁ שִׁיפוֹת וַחֲמֵשׁ בְּעִיטוֹת. וְחוֹזֵר חֲלִילָה עַד שֶׁיִּגְמֹר שְׁלֹשׁ מֵאוֹת שִׁיפָה וַחֲמֵשׁ מֵאוֹת בְּעִיטָה כְּדֵי שֶׁיִּתְקַלְּפוּ הַרְבֵּה. וְחוֹשֵׁב הַהוֹבָאָה וְהַהוֹלָכָה בְּשִׁיפָה אַחַת לְהַחְמִיר וְאַחַר כָּךְ טוֹחֵן וּמְרַקֵּד יָפֶה יָפֶה:","הַיַּיִן. מֵבִיא עֲנָבִים מִן הָרַגְלִיּוֹת מִן הַכְּרָמִים הָעֲבוּדִּים פַּעֲמַיִם בְּשָׁנָה. וְדוֹרֵךְ וְכוֹנְסִין אוֹתוֹ בְּחָבִיּוֹת קְטַנּוֹת. וְאֵין מַנִּיחִין אוֹתָן אַחַת אַחַת וְלֹא שְׁתַּיִם שְׁתַּיִם אֶלָּא שָׁלֹשׁ שָׁלֹשׁ. וְאֵינוֹ מְמַלֵּא אֶת הֶחָבִית עַד פִּיהָ כְּדֵי שֶׁיִּהְיֶה רֵיחוֹ נוֹדֵף. וְאֵינוֹ מֵבִיא לֹא מִפִּי הֶחָבִית מִפְּנֵי הַקְּמָחִין הָעוֹלֶה עַל פְּנֵי הַיַּיִן. וְלֹא מִשּׁוּלֶיהָ מִפְּנֵי הַשְּׁמָרִים. אֶלָּא מִשְּׁלִישָׁהּ וּמֵאֶמְצָעָהּ שֶׁל אֶמְצָעִית:","הָיָה הַגִּזְבָּר יוֹשֵׁב וְהַיַּיִן יוֹצֵא מִן הַנֶּקֶב שֶׁבְּצַד הֶחָבִית כֵּיוָן שֶׁיִּרְאֶה שִׁנּוּי הַשְּׁמָרִים מַתְחִיל לָצֵאת פּוֹסֵק וְאֵינוֹ לוֹקֵחַ. וּמֵאֵימָתַי מֵבִיא. מֵאַחַר אַרְבָּעִים יוֹם לִדְרִיכָתוֹ עַד שְׁתֵּי שָׁנִים אוֹ יֶתֶר מְעַט. וְאִם הֵבִיא יַיִן יָשָׁן מִכַּמָּה שָׁנִים הֲרֵי זֶה כָּשֵׁר וְהוּא שֶׁלֹּא יִפָּסֵד טַעֲמוֹ:","תִּשְׁעָה מִינִין בְּשֶׁמֶן מִפְּנֵי שִׁנּוּי מַעֲשָׂיו. כֵּיצַד. זַיִת שֶׁגִּרְגְּרוֹ בְּרֹאשׁ הַזַּיִת וּבֵרְרוֹ אַחַת אַחַת וּכְתָשׁוֹ וּנְתָנוֹ לְסַל הַשֶּׁמֶן שֶׁיֵּצֵא מִמֶּנּוּ הוּא הָרִאשׁוֹן. חָזַר אַחַר כָּךְ וּטְעָנוֹ בְּקוֹרָה הַשֶּׁמֶן שֶׁיֵּצֵא מִמֶּנּוּ הוּא הַשֵּׁנִי. וְאִם חָזַר אַחַר שֶׁטְּעָנוֹ וּטְחָנוֹ וּטְעָנוֹ שְׁנִיָּה הַשֶּׁמֶן שֶׁיֵּצֵא מִמֶּנּוּ הוּא הַשְּׁלִישִׁי. זֵיתִים שֶׁמְּסָקָן כֻּלָּן בְּעִרְבּוּבְיָא וְהֶעֱלָן לַגַּג וְחָזַר וּבֵרֵר גַּרְגֵּר גַּרְגֵּר וּכְתָשָׁן וּנְתָנָן לְסַל הַשֶּׁמֶן שֶׁיֵּצֵא מִמֶּנּוּ הוּא הָרְבִיעִי. וְאִם טְעָנוֹ בְּקוֹרָה אַחַר כָּךְ הַשֶּׁמֶן שֶׁיֵּצֵא הוּא הַחֲמִישִׁי. וְחָזַר וְטָחַן וְטָעַן פַּעַם שְׁנִיָּה הַשֶּׁמֶן שֶׁיֵּצֵא הוּא הַשִּׁשִּׁי. זֵיתִים שֶׁמְּסָקָן וּטְעָנָן בְּתוֹךְ הַבַּיִת עַד שֶׁיִּלְקוּ וְהֶעֱלָן וּנִגְּבָן וְאַחַר כָּךְ כָּתַשׁ וְנָתַן לְסַל הַשֶּׁמֶן שֶׁיֵּצֵא הוּא הַשְּׁבִיעִי. חָזַר וְטָעַן בַּקּוֹרָה הַשֶּׁמֶן שֶׁיֵּצֵא הוּא הַשְּׁמִינִי. חָזַר וְטָחַן וְטָעַן פַּעַם שְׁנִיָּה הַשֶּׁמֶן שֶׁיֵּצֵא הוּא הַתְּשִׁיעִי:","אַף עַל פִּי שֶׁכֻּלָּן כְּשֵׁרִין לִמְנָחוֹת. הָרִאשׁוֹן אֵין לְמַעְלָה מִמֶּנּוּ. וְאַחֲרָיו הַשֵּׁנִי וְהָרְבִיעִי וּשְׁנֵיהֶן שָׁוִין. וְאַחֲרֵיהֶם הַשְּׁלִישִׁי וְהַחֲמִישִׁי וְהַשְּׁבִיעִי וּשְׁלָשְׁתָּן שָׁוִין. וְאַחֲרֵיהֶם הַשִּׁשִּׁי וְהַשְּׁמִינִי וּשְׁנֵיהֶם שָׁוִין. וְהַתְּשִׁיעִי אֵין לְמַטָּה מִמֶּנּוּ:","אֵין כָּשֵׁר לַמְּנוֹרָה אֶלָּא רִאשׁוֹן וּרְבִיעִי וּשְׁבִיעִי בִּלְבַד שֶׁנֶּאֱמַר (שמות כז-כ) (ויקרא כז-כ) \"כָּתִית לַמָּאוֹר\", אֵין כָּשֵׁר לַמְּנוֹרָה אֶלָּא הַיּוֹצֵא מִן הַכָּתוּשׁ בִּלְבַד. אֲבָל לַמְּנָחוֹת כֻּלָּן כְּשֵׁרִין:","וּמֵאַחַר שֶׁכֻּלָּן כְּשֵׁרִין לַמְּנָחוֹת לָמָּה נִמְנוּ. כְּדֵי לֵידַע יָפֶה שֶׁאֵין לְמַעְלָה מִמֶּנּוּ וְהַשָּׁוֶה וְהַפָּחוֹת שֶׁהָרוֹצֶה לִזְכּוֹת עַצְמוֹ יָכֹף יִצְרוֹ הָרַע וְיַרְחִיב יָדוֹ וְיָבִיא קָרְבָּנוֹ מִן הַיָּפֶה הַמְּשֻׁבָּח בְּיוֹתֵר שֶׁבְּאוֹתוֹ הַמִּין שֶׁיָּבִיא מִמֶּנּוּ. הֲרֵי נֶאֱמַר בַּתּוֹרָה (בראשית ד-ד) \"וְהֶבֶל הֵבִיא גַם הוּא מִבְּכֹרוֹת צֹאנוֹ וּמֵחֶלְבֵהֶן וַיִּשַׁע ה' אֶל הֶבֶל וְאֶל מִנְחָתוֹ\". וְהוּא הַדִּין בְּכָל דָּבָר שֶׁהוּא לְשֵׁם הָאֵל הַטּוֹב שֶׁיִּהְיֶה מִן הַנָּאֶה וְהַטּוֹב. אִם בָּנָה בֵּית תְּפִלָּה יִהְיֶה נָאֶה מִבֵּית יְשִׁיבָתוֹ. הֶאֱכִיל רָעֵב יַאֲכִיל מִן הַטּוֹב וְהַמָּתוֹק שֶׁבְּשֻׁלְחָנוֹ. כִּסָּה עָרֹם יְכַסֶּה מִן הַיָּפֶה שֶׁבִּכְסוּתוֹ. הִקְדִּישׁ דָּבָר יַקְדִּישׁ מִן הַיָּפֶה שֶׁבִּנְכָסָיו וְכֵן הוּא אוֹמֵר (ויקרא ג-טז) \"כָּל חֵלֶב לַה'\" וְגוֹ':"],"Mishneh Torah, Those Who Defile Bed or Seat 8":["כְּבָר בֵּאַרְנוּ בִּתְחִלַּת סֵפֶר זֶה שֶׁאִם הֵסִיט הָאָדָם אֶת הַטֻּמְאָה שֶׁהִיא מְטַמְּאָה בְּמַשָּׂא נִטְמָא מִשּׁוּם נוֹשֵׂא אֲבָל אִם הֵסִיטָה הַטֻּמְאָה אֶת הָאָדָם לֹא נִטְמָא:","אֵין בְּכָל אֲבוֹת הַטֻּמְאוֹת כֻּלָּן טֻמְאָה שֶׁאִם תָּסִיט אֶת הָאָדָם הַטָּהוֹר אוֹ אֶת הַכְּלִי הַטָּהוֹר תְּטַמֵּא אוֹתָן אֶלָּא הַזָּב אוֹ חֲבֵרָיו בִּלְבַד. וְזוֹ הִיא הַטֻּמְאָה הַיְתֵרָה בְּזָב שֶׁלֹּא מָצִינוּ כְּמוֹתָהּ בְּכָל הַתּוֹרָה שֶׁאִם הֵסִיט אֶת הַטְּהוֹרִין טְמֵאִין. כֵּיצַד. הָיְתָה קוֹרָה מֻטֶּלֶת עַל רֹאשׁ הַגָּדֵר וְאָדָם טָהוֹר אוֹ כֵּלִים אֲפִלּוּ כְּלִי חֶרֶס עַל קְצָתָהּ וְהֵנִיד הַזָּב אֶת הַקָּצֶה הַשֵּׁנִי הוֹאִיל וְנִתְנַדְנְדוּ מֵחֲמַת הַזָּב הֲרֵי זֶה כְּמִי שֶׁנָּגַע בָּהֶן וּטְמֵאִין וְנַעֲשׂוּ רִאשׁוֹן לְטֻמְאָה דִּין תּוֹרָה. וְאֵין צָרִיךְ לוֹמַר שֶׁאִם נָשָׂא הַזָּב אֶת הָאָדָם אוֹ אֶת הַכֵּלִים שֶׁטִּמְּאָן. וְאֶחָד זָב וְזָבָה נִדָּה וְיוֹלֶדֶת בְּכָל הַדְּבָרִים הָאֵלּוּ. הִנֵּה לָמַדְתָּ שֶׁהָאָדָם הַטָּהוֹר שֶׁהֵסִיט אֶת הַזָּב נִטְמָא מִשּׁוּם נוֹשֵׂא זָב. וְהַזָּב שֶׁהֵסִיט אֶת הַטָּהוֹר בֵּין אָדָם בֵּין כֵּלִים אֲפִלּוּ כְּלֵי חֶרֶס טְמֵאִין. מִפְּנֵי שֶׁהַנָדַת הַזָּב לַאֲחֵרִים כְּאִלּוּ נָגַע בָּהֶן:","חֹמֶר בְּהֶסֵּט הַזָּב מִמַּגָּעוֹ שֶׁאִם נָגַע בִּכְלִי חֶרֶס הַמֻּקָּף צָמִיד פָּתִיל טָהוֹר וְאִם הֱסִיטוֹ טִמְּאָהוּ. וְכֵן כְּלִי חֶרֶס שֶׁהוּא נָבוּב כְּכַדּוּר וַעֲדַיִן לֹא נַעֲשָׂה לוֹ פֶּה כְּמוֹ אִלְפָּסִין אִירְנִיוֹת אִם הֱסִיטָן הַזָּב טְמֵאִים וְאַף עַל פִּי שֶׁהֵן טְהוֹרִין בְּאֹהֶל הַמֵּת שֶׁהֲרֵי הֵן כִּכְלִי חֶרֶס הַמֻּקָּף צָמִיד פָּתִיל שֶׁפִּתְחוֹ סָתוּם. וְכֵן מַחַט שֶׁהָיְתָה בְּלוּעָה בְּתוֹךְ הָעֵץ וְטַבַּעַת הַבְּלוּעָה בְּתוֹךְ הַלְּבֵנָה וְהֵסִיט הַזָּב אֶת הָעֵץ אוֹ הַלְּבֵנָה נִטְמְאוּ הַכֵּלִים הַבְּלוּעִים שֶׁבְּתוֹכָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","זָב שֶׁהִכְנִיס יָדוֹ אוֹ רַגְלוֹ לַאֲוִיר כְּלִי חֶרֶס הוֹאִיל וְלֹא נָגַע בּוֹ מִתּוֹכוֹ וְלֹא הֱנִידוֹ הֲרֵי זֶה טָהוֹר שֶׁאֵין הַנִּדָּה וְכַיּוֹצֵא בָּהּ מְטַמְּאִין לְאֵיבָרִים:","זָב שֶׁהָיָה קָנֶה אָחוּז בְּתוֹךְ קֻמְטוֹ וְהֵסִיט וְהוֹצִיא בִּקְצֵה הַקָּנֶה אָדָם אוֹ כְּלִי הֲרֵי הֵן טְהוֹרִין שֶׁנֶּאֱמַר (ויקרא טו יא) \"וְכָל אֲשֶׁר יִגַּע בּוֹ הַזָּב וְיָדָיו לֹא שָׁטַף בַּמָּיִם\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהַכָּתוּב הַזֶּה מְדַבֵּר בְּהֶסֵּט הַזָּב וְהוֹצִיאוֹ בִּלְשׁוֹן נְגִיעָה לוֹמַר מָה נְגִיעָה בְּיָדָיו וְהַדּוֹמֶה לְיָדָיו מִשְּׁאָר גּוּפוֹ הַגָּלוּי אֵצֶל הַנְּגִיעָה אַף הֶסֵּטוֹ עַד שֶׁיָּסִיט בְּגָלוּי שֶׁבְּגוּפוֹ לֹא שֶׁיָּסִיט בְּבֵית הַסְּתָרִים. הָיָה הַקָּנֶה בְּקֻמְטוֹ שֶׁל טָהוֹר וְהֵסִיט בּוֹ אֶת הַזָּב טָמֵא שֶׁהַמֵּסִיט אֶת הַטֻּמְאָה כְּנוֹשֵׂא אוֹתָהּ וּכְשֵׁם שֶׁהַנּוֹשֵׂא בְּבֵית הַסְּתָרִים טָמֵא כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְחִלַּת סֵפֶר זֶה כָּךְ הַמֵּסִיט בְּבֵית הַסְּתָרִים טָמֵא:","הַזָּב בְּכַף מֹאזְנַיִם וּכְלִי הֶעָשׂוּי לְמִשְׁכָּב אוֹ לְמֶרְכָּב בְּכַף שְׁנִיָּה כְּנֶגְדּוֹ. כָּרַע הַזָּב הֲרֵי הֵן כְּכֵלִים שֶׁנָּגַע בָּהֶן שֶׁהֲרֵי הֱסִיטָן. כָּרְעוּ הֵן טְמֵאִין מִשּׁוּם מִשְׁכָּב וְנַעֲשׂוּ אָב שֶׁהֲרֵי נָשְׂאוּ הַזָּב וּכְאִלּוּ עָמַד עֲלֵיהֶן. הָיָה בְּכַף שְׁנִיָּה שְׁאָר הַכֵּלִים אוֹ אֳכָלִין וּמַשְׁקִין אוֹ אָדָם בֵּין שֶׁכָּרְעוּ הֵן בֵּין שֶׁכָּרַע הַזָּב כֻּלָּן רִאשׁוֹן לְטֻמְאָה:","הַזָּב וְהַטָּהוֹר שֶׁיָּשְׁבוּ עַל הַסַּפְסָל אוֹ עַל הַנֶּסֶר בִּזְמַן שֶׁהֵן מַחְגִּירִין. אוֹ שֶׁעָלוּ בְּאִילָן שֶׁכֹּחוֹ רַע וְהוּא הָאִילָן שֶׁאֵין בָּעֳבִי עִקָּרוֹ כְּדֵי לָחֹק רֹבַע הַקַּב. אוֹ שֶׁעָלוּ בְּסֻכָּה שֶׁכֹּחָהּ רַע וְהוּא שֶׁנֶּחְבָּא בָּהּ וְדוֹחֵק אוֹתָהּ תָּזוּז בּוֹ. אוֹ שֶׁעָלוּ בְּסֻלָּם מִצְרִי שֶׁאֵינוֹ קָבוּעַ בְּמַסְמֵר. אוֹ שֶׁעָלוּ עַל הַכֶּבֶשׁ וְעַל הַקּוֹרָה וְעַל הַדֶּלֶת בִּזְמַן שֶׁאֵינָן מְחֻבָּרִין בְּטִיט. הֲרֵי זֶה טָמֵא מִפְּנֵי שֶׁהֵן מִתְנַדְנְדִין בָּהֶן וּכְאִלּוּ הֵסִיט הַזָּב אֶת הַטָּהוֹר שֶׁעִמּוֹ. אֲבָל אִם יָשְׁבוּ בִּסְפִינָה גְּדוֹלָה שֶׁאֵינָהּ יְכוֹלָה לְהָסִיט בָּאָדָם. אוֹ עַל הַנֶּסֶר אוֹ עַל הַסַּפְסָל בִּזְמַן שֶׁאֵינָם מַחְגִּירִין. אוֹ שֶׁעָלוּ בְּאִילָן וּבְסֻכָּה שֶׁכֹּחָן יָפֶה. אוֹ בְּסֻלָּם מִצְרִי הַקָּבוּעַ בְּמַסְמֵר. אוֹ בְּכֶבֶשׁ וּבְקוֹרָה וּבְדֶלֶת שֶׁמְּחֻבָּרִים בְּטִיט. אֲפִלּוּ עָלוּ מִצַּד אֶחָד הֲרֵי זֶה טָהוֹר:","זָב וְטָהוֹר שֶׁהָיוּ שְׁנֵיהֶם כְּאֶחָד מְגִיפִין אֶת הַדָּלֶת אוֹ פּוֹתְחִין הֲרֵי זֶה טָהוֹר. הָיָה אֶחָד מֵגִיף וְאֶחָד פּוֹתֵחַ נִטְמָא. הֶעֱלוּ זֶה אֶת זֶה מִן הַבּוֹר אִם הַטָּמֵא הֶעֱלָה אֶת הַטָּהוֹר טִמְּאָהוּ מִפְּנֵי שֶׁהֱסִיטוֹ. וְאִם הַטָּהוֹר הֶעֱלָה אֶת הַטָּמֵא נִטְמָא בְּמַשָּׂאוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","זָב וְטָהוֹר שֶׁהָיוּ מַפְשִׁילִין בַּחֲבָלִים אִם הָיָה זֶה מוֹשֵׁךְ אֵילָךְ וְזֶה מוֹשֵׁךְ אֵילָךְ נִטְמָא. הָיוּ אוֹרְגִין בֵּין בְּעוֹמְדִין בֵּין בְּיוֹשְׁבִין אוֹ טוֹחֲנִין אוֹ פּוֹרְקִין מִן הַחֲמוֹר אוֹ טוֹעֲנִין. בִּזְמַן שֶׁמַּשָּׂאָן כָּבֵד הֲרֵי זֶה טָמֵא וְאִם הָיָה מַשּׂוֹי קַל טָהוֹר:","טָהוֹר שֶׁהָיָה מַכֶּה אֶת הַזָּב הֲרֵי זֶה טָהוֹר. וְזָב שֶׁהִכָּה אֶת הַטָּהוֹר טִמְּאָהוּ. שֶׁאִם יִמָּשֵׁךְ הַטָּהוֹר וַהֲרֵי הַטָּמֵא נוֹפֵל וְנִמְצָא כְּאִלּוּ נִשְׁעָן עָלָיו. וּלְפִיכָךְ אַף בִּגְדֵי הַטָּהוֹר טְמֵאִין:","זָב שֶׁנִּשָּׂא מִקְצָתוֹ עַל הַטָּהוֹר אוֹ טָהוֹר שֶׁנִּשָּׂא מִקְצָתוֹ עַל הַזָּב נִטְמָא. כֵּיצַד. אֶצְבָּעוֹ שֶׁל זָב שֶׁהִנִּיחָהּ לְמַעְלָה מִן הַטָּהוֹר אוֹ הַטָּהוֹר שֶׁהִנִּיחַ אֶצְבָּעוֹ לְמַעְלָה מִן הַזָּב אַף עַל פִּי שֶׁיֵּשׁ בֵּינֵיהֶן אֶבֶן אוֹ קוֹרָה וְכַיּוֹצֵא בָּהֶם הֲרֵי זֶה טָמֵא. וְכֵן חִבּוּרֵי הַזָּב שֶׁנִּשְּׂאוּ עַל הַטָּהוֹר אוֹ חִבּוּרֵי טָהוֹר שֶׁנִּשְּׂאוּ עַל הַזָּב הֲרֵי זֶה טָמֵא. וּכְאִלּוּ נָשָׂא כָּל אֶחָד מֵהֶם עַצְמוֹ שֶׁל חֲבֵרוֹ. וְאֵלּוּ הֵם הַחִבּוּרִים. הַשִּׁנַּיִם הַצִּפָּרְנַיִם וְהַשֵּׂעָר שֶׁלָּהֶן. וְיֵרָאֶה לִי שֶׁטֻּמְאָה זוֹ מִדִּבְרֵיהֶם:"],"Mishneh Torah, Tithes 6":["מַחְלִיקִין בִּתְאֵנִים וַעֲנָבִים שֶׁל טֶבֶל וְאֵין בָּזֶה מִשּׁוּם הֶפְסֵד. וְכָל שֶׁאָסוּר לְזָרִים לְאָכְלוֹ בִּתְרוּמָה כְּגוֹן הַגַּרְעִינִין וְכַיּוֹצֵא בָּהֶן כָּךְ אָסוּר לְאָכְלוֹ מִן הַטֶּבֶל וּמִן הַמַּעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ וּמִמַּעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ. וְכָל שֶׁמֻּתָּר לְזָרִים לְאָכְלוֹ בִּתְרוּמָה מִדְּבָרִים אֵלּוּ כָּךְ מֻתָּר בְּטֶבֶל וּבְמַעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ וּמַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ:","אֵין מַדְלִיקִין בְּטֶבֶל טָמֵא אֲפִלּוּ בְּחל וְאֵין צָרִיךְ לוֹמַר בְּשַׁבָּת שֶׁנֶּאֱמַר (במדבר יח ח) \"אֶת מִשְׁמֶרֶת תְּרוּמֹתָי\" מַה תְּרוּמָה טְהוֹרָה אֵין לְךָ בָּהּ אֶלָּא מִשְּׁעַת הֲרָמָתָהּ אַף תְּרוּמָה טְמֵאָה אֵין לְךָ לֵהָנוֹת בָּהּ אֶלָּא מִשְּׁעַת הֲרָמָתָהּ וְאֵילָךְ:","אֵין מְחַפִּין בְּטֶבֶל וְאֵין זוֹרְעִין אֶת הַטֶּבֶל וַאֲפִלּוּ פֵּרוֹת שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן אָסוּר לִזְרֹעַ מֵהֶן עַד שֶׁיְּעַשֵּׂר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְבוּאָה וְקִטְנִיּוֹת וְכַיּוֹצֵא בָּהֶן. אֲבָל הָעוֹקֵר שְׁתִילִים שֶׁיֵּשׁ בָּהֶן פֵּרוֹת מִמָּקוֹם לְמָקוֹם בְּתוֹךְ שָׂדֵהוּ הֲרֵי זֶה מֻתָּר וְאֵינוֹ כְּזוֹרֵעַ טֶבֶל שֶׁהֲרֵי לֹא אָסַף הַפֵּרוֹת. וְכֵן הָעוֹקֵר לֶפֶת וּצְנוֹנוֹת וּשְׁתָלָם בְּמָקוֹם אַחֵר אִם נִתְכַּוֵּן לְהוֹסִיף בְּגוּפָן מֻתָּר. וְאִם שְׁתָלָן כְּדֵי שֶׁיְּקַשּׁוּ וְיִקַּח הַזֶּרַע שֶׁלָּהֶן אָסוּר מִפְּנֵי שֶׁהוּא כְּזוֹרֵעַ חִטִּים אוֹ שְׂעוֹרִים שֶׁל טֶבֶל:","לִיטְרָא מַעֲשֵׂר טָבוּל שֶׁזְּרָעָהּ וְהִשְׁבִּיחָהּ וַהֲרֵי הִיא עֶשֶׂר לִיטְרִין חַיֶּבֶת בְּמַעֲשֵׂר. וְאוֹתָהּ לִיטְרָא מְעַשֵּׂר עָלֶיהָ מִמָּקוֹם אַחֵר לְפִי חֶשְׁבּוֹן. לִיטְרָא בְּצָלִים שֶׁתִּקְּנָם וּזְרָעָם אֵינוֹ מְעַשֵּׂר לְפִי חֶשְׁבּוֹן הַתּוֹסֶפֶת אֶלָּא מְעַשֵּׂר לְפִי כֻּלּוֹ:","זֵרְעוֹנִים שֶׁהֵבִיאוּ שְׁלִישׁ וּמְרָחָן וְעִשְּׂרָן וְאַחַר כָּךְ זְרָעָן וְהוֹסִיפוּ וְאֵין זַרְעָם כָּלֶה הֲרֵי זֶה סָפֵק אִם חַיָּבִין בְּמַעֲשֵׂר מִדִּבְרֵיהֶם הוֹאִיל וְהוֹסִיפוּ. אוֹ אֵין חַיָּבִין שֶׁהֲרֵי הַזֶּרַע שֶׁעֲדַיִן הוּא קַיָּם וְלֹא אָבַד מְעֻשָּׂר הוּא. וְאֵין אֵלּוּ דּוֹמִים לִבְצָלִים שֶׁהַבְּצָלִים אֵין דַּרְכָּן לְהִזָּרַע:","הַזּוֹרֵעַ אֶת הַטֶּבֶל בֵּין דָּבָר שֶׁזַּרְעוֹ כָּלֶה בֵּין דָּבָר שֶׁאֵין זַרְעוֹ כָּלֶה אִם אֶפְשָׁר לְלָקְטוֹ קוֹנְסִין אוֹתוֹ וּמְלַקְּטוֹ. וְאִם צָמַח אֵין מְחַיְּבִין אוֹתוֹ לַעֲקֹר וְהַגִּדּוּלִין חֻלִּין. וְאִם הָיָה דָּבָר שֶׁאֵין זַרְעוֹ כָּלֶה אֲפִלּוּ גִּדּוּלֵי גִּדּוּלִין אֲסוּרִין עַד שָׁלֹשׁ גֳּרָנוֹת וְהָרְבִיעִי מֻתָּר. וּמִפְּנֵי מָה הַגִּדּוּלִין אֲסוּרִין מִפְּנֵי תְּרוּמַת מַעֲשֵׂר וּתְרוּמָה גְּדוֹלָה שֶׁבָּהּ. וְכֵן הַדִּין בְּזוֹרֵעַ מַעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ. אֵין מוֹכְרִין אֶת הַטֶּבֶל אֶלָּא לְצֹרֶךְ וּלְחָבֵר. וְאָסוּר לִשְׁלֹחַ אֶת הַטֶּבֶל וַאֲפִלּוּ חָבֵר לְחָבֵר שֶׁמָּא יִסְמְכוּ זֶה עַל זֶה וְיֵאָכֵל הַטֶּבֶל:","הַמּוֹכֵר פֵּרוֹת לַחֲבֵרוֹ וְנִזְכַּר שֶׁהֵם טֶבֶל וְרָץ אַחֲרָיו לְתַקְּנוֹ וְלֹא מְצָאוֹ. אִם יָדוּעַ שֶׁאֵין קַיָּמִין וְשֶׁכְּבָר אָבְדוּ אוֹ נֶאֶכְלוּ אֵינוֹ צָרִיךְ לְעַשֵּׂר עֲלֵיהֶם. וְאִם סָפֵק שֶׁהֵם קַיָּמִין אוֹ אֵין קַיָּמִין צָרִיךְ לְהוֹצִיא עֲלֵיהֶן מַעַשְׂרוֹת מִפֵּרוֹת אֲחֵרוֹת:","הַמּוֹכֵר פֵּרוֹת לַחֲבֵרוֹ מוֹכֵר אוֹמֵר עַל מְנָת שֶׁהֵן טֶבֶל מָכַרְתִּי. וְלוֹקֵחַ אוֹמֵר לֹא לָקַחְתִּי מִמְּךָ אֶלָּא מְעֵשָּׂרִין. כּוֹפִין אֶת הַמּוֹכֵר לְתַקֵּן. קְנָס הוּא לוֹ מִפְּנֵי שֶׁמָּכַר טֶבֶל:","אֵין פּוֹרְעִין חוֹב מִן הַטֶּבֶל מִפְּנֵי שֶׁהוּא כְּמוֹכְרוֹ:","מִי שֶׁלָּקְחוּ בֵּית הַמֶּלֶךְ אֶת פֵּרוֹתָיו וְהֵם טְבָלִים. אִם מֵחֲמַת שֶׁהוּא חַיָּב לָהֶן צָרִיךְ לְהוֹצִיא עֲלֵיהֶן מַעַשְׂרוֹת. וְאִם לָקְחוּ בְּאֹנֶס אֵינוֹ צָרִיךְ לְעַשֵּׂר עֲלֵיהֶם:","הַלּוֹקֵחַ טֶבֶל מִשְּׁנֵי מְקוֹמוֹת מְעַשֵּׂר מִזֶּה עַל זֶה. הַמְקַבֵּל שָׂדֶה מִיִּשְׂרָאֵל אוֹ מִן הַנָּכְרִי חוֹלֵק וְנוֹתֵן לְבַעַל הַשָּׂדֶה בְּפָנָיו כְּדֵי שֶׁיֵּדַע שֶׁטֶּבֶל נָטַל. אֲבָל הַחוֹכֵר שָׂדֶה מִיִּשְׂרָאֵל אִם נָתַן לוֹ מִזֶּרַע אוֹתָהּ שָׂדֶה תּוֹרֵם וְאַחַר כָּךְ נוֹתֵן לוֹ מִזּוֹ שֶׁקָּצַץ לִתֵּן לוֹ וּבַעַל הַשָּׂדֶה מְעַשֵּׂר לְעַצְמוֹ. וְאִם נָתַן לוֹ מִזֶּרַע שָׂדֶה אַחֶרֶת אוֹ מִמִּין אַחֵר מוֹצִיא הַמַּעֲשֵׂר וְאַחַר כָּךְ נוֹתֵן לוֹ:","הַחוֹכֵר שָׂדֶה מִן הָעַכּוּ\"ם מְעַשֵּׂר וְאַחַר כָּךְ נוֹתֵן לוֹ. קְנָס קְנָסוּהוּ בָּזֶה כְּדֵי שֶׁלֹּא יַחְכֹּר מִן הָעַכּוּ\"ם, וְנִמְצֵאת הַשָּׂדֶה בּוּרָה לְפָנָיו עַד שֶׁיִּצְטָרֵךְ וְיִמְכְּרֶנָּה לְיִשְׂרָאֵל. וְכֵן הַמְקַבֵּל שְׂדֵה אֲבוֹתָיו מִן הָעַכּוּ\"ם קְנָסוּהוּ שֶׁיְּעַשֵּׂר וְאַחַר כָּךְ יִתֵּן חֶלְקוֹ לְעַכּוּ\"ם מְעֻשָּׂר כְּדֵי שֶׁלֹּא יִקְפֹּץ וִיקַבְּלָהּ מִמֶּנּוּ מִפְּנֵי שֶׁהִיא שְׂדֵה אֲבוֹתָיו עַד שֶׁתִּשָּׁאֵר לְפָנָיו בּוּרָה כְּדֵי שֶׁיִּמְכְּרֶנָּה לְיִשְׂרָאֵל:","אֵי זֶהוּ חוֹכֵר וְאֵי זֶהוּ מְקַבֵּל. חוֹכֵר שֶׁחוֹכֵר הַקַּרְקַע בְּדָבָר קָצוּב מִן הַזֶּרַע בְּכָךְ וְכָךְ סְאָה בֵּין עָשְׂתָה הַרְבֵּה בֵּין עָשְׂתָה מְעַט. מְקַבֵּל הוּא שֶׁיְּקַבֵּל אוֹתָהּ בְּחֵלֶק מִמַּה שֶּׁתֵּעָשֶׂה חֶצְיוֹ אוֹ שְׁלִישׁוֹ אוֹ מַה שֶּׁיִּתְּנוּ בֵּינֵיהֶן. שׂוֹכֵר הוּא שֶׁשּׂוֹכֵר הַקַּרְקַע בְּמָעוֹת:","שְׁנַיִם שֶׁקִּבְּלוּ שָׂדֶה בַּאֲרִיסוּת אוֹ יָרְשׁוּ אוֹ נִשְׁתַּתְּפוּ יָכוֹל הָאֶחָד לוֹמַר לַחֲבֵרוֹ טֹל אַתָּה חִטִּים שֶׁבְּמָקוֹם פְּלוֹנִי וַאֲנִי חִטִּים שֶׁבְּמָקוֹם פְּלוֹנִי אַתָּה יַיִן שֶׁבְּמָקוֹם פְּלוֹנִי וַאֲנִי יַיִן שֶׁבְּמָקוֹם פְּלוֹנִי. אֲבָל לֹא יֹאמַר טֹל אַתָּה חִטִּים וַאֲנִי שְׂעוֹרִים אַתָּה יַיִן וַאֲנִי שֶׁמֶן מִפְּנֵי שֶׁמּוֹכְרִין אֶת הַטֶּבֶל:","כֹּהֵן אוֹ לֵוִי שֶׁלָּקְחוּ פֵּרוֹת מִיִּשְׂרָאֵל אַחַר שֶׁנִּגְמְרָה מְלַאכְתָּן מוֹצִיאִין אֶת הַתְּרוּמָה וְהַמַּעַשְׂרוֹת מִידֵיהֶן וְנוֹתְנִין אוֹתָם לְכֹהֲנִים וְלִלְוִיִּם אֲחֵרִים. קְנָס הוּא לָהֶם כְּדֵי שֶׁלֹּא יִקְפְּצוּ לָגֳרָנוֹת וּלְגִתּוֹת וְיִקְנוּ טְבָלִים כְּדֵי לְהַפְקִיעַ מַתְּנוֹת אֲחֵיהֶם הַכֹּהֲנִים. וְאִם קָנוּ קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן אֵין מוֹצִיאִים מִיָּדָם:","כֹּהֵן אוֹ לֵוִי שֶׁמָּכְרוּ פֵּרוֹת תְּלוּשִׁין לְיִשְׂרָאֵל קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן וְאֵין צָרִיךְ לוֹמַר אִם מָכְרוּ בִּמְחֻבָּר הֲרֵי הַתְּרוּמָה אוֹ הַמַּעֲשֵׂר שֶׁלָּהֶם. וְאִם מָכְרוּ אַחַר גְּמַר מְלָאכָה הֲרֵי הַתְּרוּמָה וְהַמַּעֲשֵׂר שֶׁל לוֹקֵחַ וּמַפְרִישׁ וְנוֹתֵן לְכָל כֹּהֵן אוֹ לֵוִי שֶׁיִּרְצֶה:","כֹּהֵן וְלֵוִי שֶׁקִּבְּלוּ שָׂדֶה מִיִּשְׂרָאֵל כְּשֵׁם שֶׁחוֹלְקִין בְּחֻלִּין כָּךְ חוֹלְקִין בִּתְרוּמָה וּבְמַעַשְׂרוֹת וְהַיִּשְׂרָאֵל נוֹטֵל חֶלְקוֹ וְנוֹתֵן לְכָל כֹּהֵן אוֹ לֵוִי שֶׁיִּרְצֶה. אֲבָל יִשְׂרָאֵל שֶׁקִּבֵּל שָׂדֶה מִכֹּהֵן אוֹ מִלֵּוִי הַתְּרוּמָה אוֹ הַמַּעֲשֵׂר לְבַעַל הַשָּׂדֶה וּשְׁאָר הַמַּתָּנוֹת חוֹלְקִין:","הַמְקַבֵּל זֵיתִים לְהוֹצִיא מֵהֶן שֶׁמֶן בֵּין יִשְׂרָאֵל מִכֹּהֵן אוֹ לֵוִי בֵּין כֹּהֵן אוֹ לֵוִי מִיִּשְׂרָאֵל כְּשֵׁם שֶׁחוֹלְקִין בְּחֻלִּין כָּךְ חוֹלְקִין בִּתְרוּמָה וּמַעַשְׂרוֹת מִפְּנֵי שֶׁהַשֶּׁמֶן חָשׁוּב הוּא:","כֹּהֵן שֶׁמָּכַר שָׂדֶה לְיִשְׂרָאֵל וְאָמַר לוֹ עַל מְנָת שֶׁהַמַּעֲשֵׂר שֶׁלָּהּ שֶׁלִּי לְעוֹלָם הֲרֵי הֵן שֶׁלּוֹ כֵּיוָן שֶׁאָמַר עַל מְנָת נַעֲשֶׂה כְּמִי שֶׁשִּׁיֵּר מְקוֹם הַמַּעֲשֵׂר. וְאִם מֵת הַכֹּהֵן הֲרֵי בְּנוֹ כִּשְׁאָר הַכֹּהֲנִים. וְאִם אָמַר לוֹ עַל מְנָת שֶׁהַמַּעַשְׂרוֹת לִי וְלִבְנִי מֵת הוּא יִטְלֵם בְּנוֹ. עַל מְנָת שֶׁהַמַּעַשְׂרוֹת שֶׁלִּי כָּל זְמַן שֶׁהִיא לְפָנֶיךָ מְכָרָהּ לְאַחֵר אַף עַל פִּי שֶׁחָזַר וּלְקָחָהּ אֵין לַכֹּהֵן אוֹתָם הַמַּעַשְׂרוֹת:","יִשְׂרָאֵל שֶׁקִּבֵּל שָׂדֶה מִכֹּהֵן וְלֵוִי וְאָמַר לוֹ עַל מְנָת שֶׁהַמַּעַשְׂרוֹת שֶׁלִּי אַרְבַּע אוֹ חָמֵשׁ שָׁנִים מֻתָּר. עַל מְנָת שֶׁהֵן שֶׁלִּי לְעוֹלָם אָסוּר שֶׁאֵין כֹּהֵן עוֹשֶׂה כֹּהֵן. וְכֵן בֶּן לֵוִי שֶׁהָיָה עָלָיו חוֹב לְיִשְׂרָאֵל לֹא יִהְיֶה יִשְׂרָאֵל זֶה גּוֹבֶה מֵאֲחֵרִים וּמַפְרִישׁ עַד שֶׁיִּפְרַע כְּנֶגֶד חוֹבוֹ שֶׁאֵין לֵוִי זֶה עוֹשֶׂה בַּעַל חוֹב שֶׁלּוֹ כְּלֵוִי אַחֵר שֶׁיִּגְבֶּה מַעֲשֵׂר מֵאֲחֵרִים:","יִשְׂרָאֵל שֶׁיָּרַשׁ טֶבֶל מְמֹרַח מֵאֲבִי אִמּוֹ כֹּהֵן וְאוֹתוֹ אֲבִי אִמּוֹ יְרָשׁוֹ מֵאֲבִי אִמּוֹ יִשְׂרָאֵל הֲרֵי זֶה מַפְרִישׁ מִמֶּנּוּ מַעַשְׂרוֹתָיו וְהֵן שֶׁלּוֹ. שֶׁהַמַּתָּנוֹת הָרְאוּיוֹת לִיתָרֵם כְּמוֹ שֶׁהוּרְמוּ הֵן אַף עַל פִּי שֶׁלֹּא הוּרְמוּ:","הַנּוֹתֵן שָׂדֵהוּ בְּקַבָּלָה לְעַכּוּ\"ם אוֹ לְמִי שֶׁאֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת אַף עַל פִּי שֶׁלֹּא בָּאוּ לְעוֹנַת מַעַשְׂרוֹת צָרִיךְ לְעַשֵּׂר עַל יָדָם. נְתָנָהּ לְעַם הָאָרֶץ עַד שֶׁלֹּא בָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת אֵינוֹ צָרִיךְ לְעַשֵּׂר עַל יָדָם. וּמִשֶּׁבָּאוּ לְעוֹנַת הַמַּעַשְׂרוֹת צָרִיךְ לְעַשֵּׂר עַל יָדָם. כֵּיצַד הוּא עוֹשֶׂה. עוֹמֵד עַל הַגֹּרֶן וְנוֹטֵל וְאֵינוֹ חוֹשֵׁשׁ לְמַה שֶּׁאָכְלוּ שֶׁאֵין אָנוּ אַחְרָאִין לָהֶם:"],"Mishneh Torah, Transmission of the Oral Law 10":["חֲבֵרָיו שֶׁלְּרִבִּי מֵאִיר – הֶם רִבִּי יְהוּדָה, וְרִבִּי יוֹסֵי, וְרִבִּי שִׁמְעוֹן, וְרִבִּי נְחֶמְיָה, וְרִבִּי אֶלְעָזָר בֶּן שַׁמּוּעַ, וְרִבִּי יוֹחָנָן הַסַּנְדְּלָר, וְשִׁמְעוֹן בֶּן עַזַּאי, וְרִבִּי חֲנַנְיָה בֶּן תְּרַדְיוֹן. וְכֵן קִבְּלוּ חֲבֵרָיו שֶׁלְּרִבִּי עֲקִיבָה מֵרִבִּי אֱלִיעֶזֶר הַגָּדוֹל; וַחֲבֵרָיו שֶׁלְּרִבִּי עֲקִיבָה – הֶם רִבִּי טַרְפוֹן רִבּוֹ שֶׁלְּרִבִּי יוֹסֵי הַגָּלִילִי, וְרִבִּי שִׁמְעוֹן בֶּן אֶלְעָזָר, וְרִבִּי יוֹחָנָן בֶּן נוּרִי."],"Mishneh Torah, Transmission of the Oral Law 21":["נִמְצָא מֵרָב אַשֵׁי עַד מֹשֶׁה רַבֵּנוּ – אַרְבָּעִים אִישׁ, וְאֵלּוּ הֶן: (א) רָב אַשֵׁי, (ב) מֵרַבָּא, (ג) מֵרַבָּה, (ד) מֵרָב הוּנָא, (ה) מֵרִבִּי יוֹחָנָן וְרָב וּשְׁמוּאֵל, (ו) מֵרַבֵּנוּ הַקָּדוֹשׁ, (ז) מֵרַבַּן שִׁמְעוֹן אָבִיו, (ח) מֵרַבַּן גַּמְלִיאֵל אָבִיו, (ט) מֵרַבַּן שִׁמְעוֹן אָבִיו, (י) מֵרַבַּן גַּמְלִיאֵל הַזָּקֵן אָבִיו, (יא) מֵרַבַּן שִׁמְעוֹן אָבִיו, (יב) מֵהִלֵּל אָבִיו וְשַׁמַּאי, (יג) מִשְּׁמַעְיָה וְאַבְטַלְיוֹן, (יד) מִיְּהוּדָה וְשִׁמְעוֹן, (טו) מִיְּהוֹשׁוּעַ וְנִתַּאי, (טז) מִיּוֹסֵף וְיוֹסֵף, (יז) מֵאַנְטִיגְנוֹס, (יח) מִשִּׁמְעוֹן הַצַּדִּיק, (יט) מֵעֶזְרָא, (כ) מִבָּרוּךְ, (כא) מִיִּרְמְיָה, (כב) מִצְּפַנְיָה, (כג) מֵחֲבַקּוּק, (כד) מִנַּחוּם, (כה) מִיּוֹאֵל, (כו) מִמִּיכָה, (כז) מִיְּשַׁעְיָה, (כח) מֵעָמוֹס, (כט) מֵהוֹשֵׁעַ, (ל) מִזְּכַרְיָה, (לא) מִיְּהוֹיָדָע, (לב) מֵאֱלִישָׁע, (לג) מֵאֵלִיָּהוּ, (לד) מֵאֲחִיָּה, (לה) מִדָּוִיד, (לו) מִשְּׁמוּאֵל, (לז) מֵעֵלִי, (לח) מִפִּינְחָס, (לט) מִיְּהוֹשׁוּעַ, (מ) מִמֹּשֶׁה רַבֵּנוּ רִבָּן שֶׁלְּכָל הַנְּבִיאִים, מֵעִם ה' אֱלֹהֵי יִשְׂרָאֵל."],"Mishneh Torah, Transmission of the Oral Law 32":["וְכָל בֵּית דִּין שֶׁעָמַד אַחַר הַתַּלְמוּד בְּכָל מְדִינָה וּמְדִינָה וְגָזַר אוֹ הִתְקִין אוֹ הִנְהִיג לִבְנֵי מְדִינָתוֹ, אוֹ לִבְנֵי מְדִינוֹת – לֹא פָשְׁטוּ מַעֲשָׂיו בְּכָל יִשְׂרָאֵל: מִפְּנֵי רֹחַק מוֹשְׁבוֹתֵיהֶם, וְשִׁבּוּשׁ הַדְּרָכִים; וֶהֱיוֹת בֵּית דִּין שֶׁלְּאוֹתָהּ הַמְּדִינָה יְחִידִים, וּבֵית דִּין הַגָּדוֹל שֶׁלְּשִׁבְעִים בָּטַל מִכַּמָּה שָׁנִים קֹדֶם חִבּוּר הַתַּלְמוּד."],"Mishneh Torah, Transmission of the Oral Law 43":["וְרָאִיתִי לְחַלַּק חִבּוּר זֶה הֲלָכוֹת הֲלָכוֹת בְּכָל עִנְיָן וְעִנְיָן, וַאֲחַלַּק הַהֲלָכוֹת לִפְרָקִים שֶׁבְּאוֹתוֹ עִנְיָן; וְכָל פֵּרֶק וּפֵרֶק אֲחַלַּק אוֹתוֹ לַהֲלָכוֹת קְטַנּוֹת, כְּדֵי שֶׁיִּהְיוּ סְדוּרִין עַל פֶּה."],"Mishneh Torah, Trespass 5":["אֶחָד הַמַּקְדִּישׁ לְבֶדֶק הַבַּיִת דָּבָר הָרָאוּי לְחַזֵּק הַבֶּדֶק כְּגוֹן אֶבֶן אוֹ קוֹרָה. אוֹ הַמַּקְדִּישׁ לְבֶדֶק הַבַּיִת דָּבָר הָרָאוּי לַמִּזְבֵּחַ כְּגוֹן כְּבָשִׂים וְתוֹרִים. אוֹ הַמַּקְדִּישׁ לַמִּזְבֵּחַ דָּבָר הָרָאוּי לְבֶדֶק הַבַּיִת כְּגוֹן אֶבֶן וְקוֹרָה. אוֹ הַמַּקְדִּישׁ לָזֶה וְלָזֶה דְּבָרִים שֶׁאֵינָן רְאוּיִין לֹא לָזֶה וְלֹא לָזֶה כְּגוֹן הַמַּקְדִּישׁ תַּרְנְגוֹלִין וְחֹמֶץ וְצִיר אוֹ קַרְקַע אֲפִלּוּ הִקְדִּישׁ אַשְׁפָּה מְלֵאָה זֶבֶל אוֹ עָפָר אוֹ אֵפֶר. מוֹעֲלִין בְּכֻלָּן מִשָּׁעָה שֶׁהֻקְדְּשׁוּ עַד שֶׁיִּפָּדוּ דְּבָרִים הָרְאוּיִים לְהִפָּדוֹת:","כָּל קָדְשֵׁי בֶּדֶק הַבַּיִת עִם דְּבָרִים שֶׁמּוֹעֲלִין בָּהֶן מִקָּדְשֵׁי מִזְבֵּחַ מִצְטָרְפִין זֶה עִם זֶה לִמְעִילָה וְאִם נֶהֱנָה בִּשְׁוֵה פְּרוּטָה מִכֻּלָּם מָעַל:","אָכַל וְהֶאֱכִיל אֶת חֲבֵרוֹ אוֹ נֶהֱנָה וּמְהַנֶּה חֲבֵרוֹ אֲכִילָתוֹ וַהֲנָיַת חֲבֵרוֹ אוֹ אֲכִילַת חֲבֵרוֹ וַהֲנָיָתוֹ כֻּלָּן מִצְטָרְפִין לַמְּעִילָה וְאִם נַעֲשָׂה מִן הַכּל הֲנָיָה בִּפְרוּטָה מָעַל:","הַמְּעִילָה מִצְטָרֶפֶת לִזְמַן מְרֻבֶּה. כֵּיצַד. נֶהֱנָה הַיּוֹם מִן הַהֶקְדֵּשׁ וְנֶהֱנָה לְאַחַר כַּמָּה שָׁנִים בְּהֶעְלֵם אֶחָד הֲרֵי אֵלּוּ מִצְטָרְפִין לִפְרוּטָה וּמָעַל:","אֵין מְעִילָה אֶלָּא בְּתָלוּשׁ מִן הַקַּרְקַע אֲבָל הַנֶּהֱנֶה בַּקַּרְקַע עַצְמָהּ אוֹ בַּמְחֻבָּר לָהּ לֹא מָעַל אֲפִלּוּ פָּגַם. כֵּיצַד. הַחוֹרֵשׁ שְׂדֵה הֶקְדֵּשׁ אוֹ הַזּוֹרֵעַ בָּהּ פָּטוּר. נָטַל מֵאֲבָקָהּ וְנֶהֱנָה בָּהּ וּפְגָמָהּ מָעַל. הַדָּשׁ בִּשְׂדֵה הֶקְדֵּשׁ מָעַל שֶׁהֶאָבָק שֶׁלָּהּ מוֹעִיל לַשָּׂדֶה וַהֲרֵי נֶהֱנָה בָּאָבָק וּפָגַם הַשָּׂדֶה. וְכֵן אִם חָרַשׁ שְׂדֵה הֶקְדֵּשׁ כְּדֵי לְהַעֲלוֹת אָבָק לְעֵשֶׂב שֶׁנָּתַן בָּהּ וְנָטַל הָעֵשֶׂב מָעַל. הַדָּר בִּמְעָרַת הֶקְדֵּשׁ אוֹ בְּצֵל אִילָן אוֹ שׁוֹבָךְ שֶׁל הֶקְדֵּשׁ אַף עַל פִּי שֶׁנֶּהֱנָה לֹא מָעַל. וְכֵן הַמַּקְדִּישׁ בַּיִת בָּנוּי הַדָּר בּוֹ לֹא מָעַל. אֲבָל הַמַּקְדִּישׁ עֵצִים וַאֲבָנִים וּבָנָה בָּהֶן בַּיִת הַדָּר שָׁם מָעַל כְּמוֹ שֶׁיִּתְבָּאֵר:","גִּדּוּלֵי הֶקְדֵּשׁ מוֹעֲלִין בָּהֶן. כֵּיצַד. הִקְדִּישׁ שָׂדֶה וְהוֹצִיאָה עֲשָׂבִים אִילָן וְעָשָׂה פֵּרוֹת מוֹעֲלִין בָּהֶן. אֲבָל הַמַּקְדִּישׁ אֶת הַבּוֹר רֵיקָן וְאַחַר כָּךְ נִתְמַלֵּא מַיִם. הִקְדִּישׁ אַשְׁפָּה וְאַחַר כָּךְ נִתְמַלֵּאת זֶבֶל. שׁוֹבָךְ וְנִתְמַלֵּא יוֹנִים. הוֹאִיל וְאֵינָן גִּדּוּלֵי הֶקְדֵּשׁ אֵין מוֹעֲלִין בָּהֶן. וְכֵן הַזֶּבֶל וְהַפֶּרֶשׁ שֶׁבַּחֲצַר הֶקְדֵּשׁ לֹא נֶהֱנִין וְלֹא מוֹעֲלִין. וּמַה יַּעֲשׂוּ בָּהֶן יִמָּכְרוּ וְיִפְּלוּ דְּמֵיהֶן לַלִּשְׁכָּה. מַעְיָן שֶׁהוּא יוֹצֵא מִתּוֹךְ שְׂדֵה הֶקְדֵּשׁ אָסוּר לֵהָנוֹת בְּמַיִם שֶׁיּוֹצְאִין מִמֶּנּוּ בְּתוֹךְ הַשָּׂדֶה וְהַנֶּהֱנֶה לֹא מָעַל. יָצְאוּ הַמַּיִם חוּץ לַשָּׂדֶה מֻתָּר לֵהָנוֹת בָּהֶן. עֲרָבָה הַגְּדֵלָה בִּשְׂדֵה הֶקְדֵּשׁ לֹא נֶהֱנִין וְלֹא מוֹעֲלִין. אִילָן שֶׁל הֶדְיוֹט הַסָּמוּךְ לִשְׂדֵה הֶקְדֵּשׁ וְשָׁרָשָׁיו יוֹצְאִים בְּתוֹךְ הַשָּׂדֶה. אִם בֵּינוֹ לְבֵין הַשָּׂדֶה שֶׁל הֶקְדֵּשׁ עַד שֵׁשׁ עֶשְׂרֵה אַמָּה הֲרֵי אוֹתָן הַשָּׁרָשִׁין שֶׁבְּתוֹךְ הַשָּׂדֶה אֲסוּרִין וְהַנֶּהֱנֶה מֵהֶן לֹא מָעַל. הָיָה הָאִילָן רָחוֹק יֶתֶר עַל שֵׁשׁ עֶשְׂרֵה הַנֶּהֱנֶה בָּהֶן מָעַל. אִילָן שֶׁל הֶקְדֵּשׁ הַסָּמוּךְ לִשְׂדֵה הֶדְיוֹט וְשָׁרָשָׁיו יוֹצְאִין בְּתוֹךְ הַשָּׂדֶה אִם הָיָה בְּתוֹךְ שֵׁשׁ עֶשְׂרֵה אַמָּה מוֹעֲלִין בָּהֶן. הָיָה רָחוֹק יֶתֶר עַל שֵׁשׁ עֶשְׂרֵה אַמָּה אוֹתָן הַשָּׁרָשִׁין שֶׁבְּתוֹךְ הַשְּׂדֵה הֶדְיוֹט לֹא נֶהֱנִין וְלֹא מוֹעֲלִין:","קֵן שֶׁבָּרֹאשׁ הָאִילָן שֶׁל הֶקְדֵּשׁ שֶׁבָּנָה אוֹתָן הָעוֹף מֵעֵצִים וַעֲשָׂבִים וְכַיּוֹצֵא בָּהֶן. כָּל הַקֵּן עִם הַבֵּיצִים שֶׁבּוֹ עִם הָאֶפְרוֹחִים הַצְּרִיכִין לְאִמָּן אֵין נֶהֱנִין בָּהֶן וְהַנֶּהֱנֶה לֹא מָעַל:","הַמַּקְדִּישׁ אֶת הַיַּעַר מוֹעֲלִין בְּכֻלּוֹ בֵּין בָּאִילָנוֹת בֵּין בְּכָל קֵן שֶׁבְּרֹאשׁ הָאִילָנוֹת אוֹ שֶׁבֵּינֵיהֶן:","גִּזְבָּרִים שֶׁשָּׁפוּ עֲצֵי הֶקְדֵּשׁ וְקָצְצוּ אוֹתָן מוֹעֲלִין בְּאוֹתָן הָעֵצִים הַקְּטַנִּים שֶׁחָתְכוּ מֵעֵת שֶׁקָּצְצוּ. אֲבָל אֵין מוֹעֲלִין לֹא בַּשִּׁפּוּי וְלֹא בַּנְּסֹרֶת וְלֹא בַּנְּבִיָּה שֶׁל עֵצִים וְהוּא הַגּוּף הַקָּשֶׁה הֶעָגל שֶׁבְּתוֹךְ הָעֵץ הַדּוֹמֶה לְיַבֶּלֶת שֶׁלֹּא יִצְלַח לִמְלָאכָה:","הַמַּקְדִּישׁ עַבְדּוֹ אֵין מוֹעֲלִין בּוֹ וְלֹא בִּשְׂעָרוֹ אַף עַל פִּי שֶׁהוּא עוֹמֵד לְהִגָּזֵז מִפְּנֵי שֶׁהוּא מְחֻבָּר לוֹ וְכָל זְמַן שֶׁהוּא מְחֻבָּר הוֹלֵךְ וּמַשְׁבִּיחַ:","הַזּוֹרֵעַ פֵּרוֹת הֶקְדֵּשׁ פּוֹדֶה אוֹתָן בִּשְׁעַת זִרְעָן. וְאַף עַל פִּי שֶׁלֹּא פָּדָה הֲרֵי הַגִּדּוּלִין חֻלִּין וְאֵין מוֹעֲלִין בָּהֶן וְאֵין מְשַׁלְּמִין מֵהֶן קֶרֶן וְחֹמֶשׁ וְחַיָּבִין בְּחַלָּה:","שְׁמָרִים שֶׁל הֶקְדֵּשׁ שֶׁנָּתַן עֲלֵיהֶם מַיִם. רִאשׁוֹן וְשֵׁנִי וּשְׁלִישִׁי אָסוּר לֵהָנוֹת בּוֹ וְהַנֶּהֱנֶה לֹא מָעַל. רְבִיעִי מֻתָּר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקָדְשֵׁי בֶּדֶק הַבַּיִת. אֲבָל קָדְשֵׁי מִזְבֵּחַ אַף מֵרְבִיעִי וְאֵילָךְ לְעוֹלָם אָסוּר:","הַמַּקְדִּישׁ תַּרְנְגלֶת לַמִּזְבֵּחַ מוֹעֲלִין בָּהּ וּבְבֵיצָתָהּ. הִקְדִּישׁ חֲמוֹר לַמִּזְבֵּחַ מוֹעֲלִין בָּהּ וּבַחֲלָבָהּ. הִקְדִּישׁ תּוֹרִים לְבֶדֶק הַבַּיִת מוֹעֲלִין בָּהֶן וּבְבֵיצָתָן כְּמוֹ שֶׁבֵּאַרְנוּ:","כָּתְנוֹת כְּהֻנָּה שֶׁבָּלוּ מוֹעֲלִין בָּהֶן כִּשְׁאָר קָדָשִׁים. וְהַחֲדָשִׁים הוֹאִיל וְנִתְּנוּ לֵהָנוֹת בָּהֶן אֵין מוֹעֲלִין בָּהֶן:","קָדְשֵׁי עַכּוּ\"ם אִם לְבֶדֶק הַבַּיִת הִקְדִּישׁוּ מוֹעֲלִין בָּהֶן. וְאִם קָדְשֵׁי מִזְבֵּחַ הֵן אֵין בָּהֶן מְעִילָה מִן הַתּוֹרָה שֶׁנֶּאֱמַר בַּקָּרְבָּנוֹת (ויקרא א ב) \"דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל\". אֲבָל אָסוּר לֵהָנוֹת בָּהֶן מִדִּבְרֵי סוֹפְרִים:","קוֹל וּמַרְאֶה וְרֵיחַ שֶׁל הֶקְדֵּשׁ לֹא נֶהֱנִין וְלֹא מוֹעֲלִין. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֵרִיחַ בַּקְּטֹרֶת אַחַר שֶׁעָלְתָה הַתִּמֹּרֶת. אֲבָל אִם הֵרִיחַ בַּקְּטֹרֶת כְּשֶׁתַּעֲלֶה תִּמְרָתָהּ מָעַל:"],"Mishneh Torah, Vessels 17":["כָּל יְדוֹת הַכֵּלִים הֲרֵי הֵן כְּכֵלִים וְאִם נִטְמָא הַכְּלִי נִטמְאָה יָדוֹ הַצָּרִיךְ לָהּ בְּתַשְׁמִישׁוֹ וְשֶׁאֵין צָרִיךְ לָהּ טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר. לְפִיכָךְ הָאֶבֶן הַיּוֹצֵאת מִן הַתַּנּוּר טֶפַח וּמִן הַכִּירָה שָׁלֹשׁ אֶצְבָּעוֹת חִבּוּר וְאִם נִטְמָא הַתַּנּוּר וְהַכִּירָה נִטְמְאוּ אֲבָנִים אֵלּוּ. וָאֳכָלִין וּמַשְׁקִין הַנּוֹגְעִין בַּאֲבָנִים אֵלּוּ נִטְמְאוּ. וְאִם נָגְעוּ בְּחוּץ לְטֶפַח שֶׁל תַּנּוּר אוֹ בְּחוּץ לְשָׁלֹשׁ אֶצְבָּעוֹת שֶׁל כִּירָה טְהוֹרִין:","הַכֻּפָּח עֲשָׂאָהוּ לַאֲפִיָּה שִׁעוּרוֹ כְּתַנּוּר. עֲשָׂאָהוּ לְבִשּׁוּל שִׁעוּרוֹ כְּכִירָה:","מוּסַף הַתַּנּוּר שֶׁל בַּעֲלֵי בָּתִּים טָהוֹר וְשֶׁל נַחְתּוֹמִין טָמֵא בְּטֻמְאַת הַתַּנּוּר מִפְּנֵי שֶׁסּוֹמֵךְ עָלָיו אֶת הַשִּׁפּוּד. כַּיּוֹצֵא בּוֹ מוּסַף יוֹרָה שֶׁל שׁוֹלְקֵי זֵיתִים טָמֵא וְשֶׁל צַבָּעִים טָהוֹר:","עֲטֶרֶת הַכִּירָה טְהוֹרָה. וְטִירַת הַתַּנּוּר וְהוּא הַמָּקוֹם הַבָּנוּי בְּצִדּוֹ שֶׁמַּנִּיחִין בּוֹ אֶת הַפַּת בְּעֵת רְדִיָּתָהּ בִּזְמַן שֶׁהִיא גְּבוֹהָה אַרְבָּעָה טְפָחִים טְמֵאָה בְּטֻמְאַת הַתַּנּוּר. פָּחוֹת מֵאַרְבָּעָה טְפָחִים טְהוֹרָה לְפִי שֶׁאֵינָהּ חִבּוּר לוֹ. וְאִם חִבְּרָהּ לַתַּנּוּר אֲפִלּוּ עַל שָׁלֹשׁ אֲבָנִים טְמֵאָה:","בֵּית הַפָּךְ וּבֵית הַתַּבְלִין וּבֵית הַנֵּר שֶׁבַּכִּירָה אִם נִטְמֵאת הַכִּירָה בְּמַגָּע נִטְמְאוּ כֻּלָּן וְאִם נִטְמֵאת בַּאֲוִיר לֹא נִטְמְאוּ לְפִי שֶׁאֵינָן חִבּוּר לָהּ אֶלָּא מִדִּבְרֵי סוֹפְרִים. וּלְפִיכָךְ עָשׂוּ לָהּ הֶכֵּר כְּדֵי שֶׁלֹּא יִשָּׂרְפוּ עַל מַגָּעָן תְּרוּמָה וְקָדָשִׁים. וְכֵן כָּל שֶׁאָנוּ אוֹמְרִין בְּעִנְיָן זֶה שֶׁהוּא מִתְטַמֵּא בְּמַגָּע וְאֵינוֹ מִתְטַמֵּא בַּאֲוִיר אֵינוֹ חִבּוּר אֶלָּא מִדִּבְרֵיהֶם וְעָשׂוּ לוֹ הֶכֵּר זֶה כְּדֵי שֶׁלֹּא יִשָּׂרְפוּ עָלָיו קָדָשִׁים אֶלָּא תּוֹלִין:","חֲצַר הַכִּירָה בִּזְמַן שֶׁהִיא גְּבוֹהָה שָׁלֹשׁ אֶצְבָּעוֹת הֲרֵי זוֹ חִבּוּר וְאִם נִטְמֵאת הַכִּירָה אוֹ חֲצֵרָהּ בֵּין בַּאֲוִיר בֵּין בְּמַגָּע נִטְמֵאת הַשְּׁנִיָּה. הָיְתָה הֶחָצֵר פְּחוּתָה מִכָּאן וְנִטְמֵאת אַחַת מֵהֶן בְּמַגָּע נִטְמֵאת הַשְּׁנִיָּה. אֲבָל אִם נִטְמֵאת אַחַת מֵהֶן מֵאֲוִירָהּ בִּלְבַד אֵין חֲבֶרְתָּהּ טְמֵאָה לְפִי שֶׁאֵינָהּ חִבּוּר לָהּ אֶלָּא מִדִּבְרֵיהֶם. הָיְתָה חֲצַר הַכִּירָה מֻפְרֶשֶׁת מִמֶּנָּה בִּזְמַן שֶׁהִיא גְּבוֹהָה שָׁלֹשׁ אֶצְבָּעוֹת הֲרֵי זוֹ חִבּוּר לָהּ בֵּין לְטֻמְאַת מַגָּע בֵּין לְטֻמְאַת אֲוִיר. הָיְתָה פָּחוֹת מִכָּאן אוֹ שֶׁהָיְתָה הֶחָצֵר חֲלָקָה וְאֵין לָהּ שָׂפָה אֵין חִבּוּר לָהּ וְאִם נִטְמֵאת הַכִּירָה בֵּין מֵאֲוִירָהּ בֵּין בְּמַגַּע הֶחָצֵר טְהוֹרָה וְכֵן אִם נִטְמֵאת הֶחָצֵר הַכִּירָה טְהוֹרָה:","פִּטְפּוּטֵי כִּירָה שְׁלֹשָׁה הָיָה גֹּבַהּ כָּל אֶחָד מֵהֶן שָׁלֹשׁ אֶצְבָּעוֹת אוֹ פָּחוֹת אִם נִטְמֵאת הַכִּירָה בֵּין בְּמַגָּע בֵּין בַּאֲוִיר נִטְמְאוּ שְׁלָשְׁתָּן. וְכֵן אִם הָיוּ אַרְבָּעָה. נִטַּל אֶחָד מֵהֶן אִם נִטְמֵאת הַכִּירָה בְּמַגָּע נִטְמְאוּ שְׁנֵי הַפִּטְפּוּטִים שֶׁנִּשְׁאֲרוּ וְאִם נִטְמֵאת בָּאֲוִיר לֹא נִטְמְאוּ עִמָּהּ. עָשָׂה לָהּ שְׁנֵי הַפִּטְפּוּטִים זֶה כְּנֶגֶד זֶה אִם נִטְמֵאת הַכִּירָה בְּמַגָּע נִטְמְאוּ. וְאִם נִטְמֵאת בָּאֲוִיר לֹא נִטְמְאוּ. הָיוּ הַפִּטְפּוּטִים גְּבוֹהִין מִשָּׁלֹשׁ אֶצְבָּעוֹת וּלְמַטָּה מִתְטַמְּאִין עִמָּהּ בֵּין שֶׁנִּטְמֵאת בְּמַגָּע בֵּין שֶׁנִּטְמֵאת בָּאֲוִיר. וּמִשָּׁלֹשׁ וּלְמַעְלָה מִתְטַמְּאִין עִמָּהּ אִם נִטְמֵאת בְּמַגָּע אֲבָל אִם נִטְמֵאת מֵאֲוִירָהּ בִּלְבַד אֵין מִתְטַמְּאִין עִמָּהּ. הָיוּ מְשׁוּכִין מִן הַשָּׂפָה בְּתוֹךְ שָׁלֹשׁ אֶצְבָּעוֹת מִתְטַמְּאִין עִמָּהּ בֵּין שֶׁנִּטְמֵאת בְּמַגָּע בֵּין שֶׁנִּטְמֵאתָ בָּאֲוִיר. הָיוּ חוּץ לְשָׁלֹשׁ אֶצְבָּעוֹת מִתְטַמְּאִין עִמָּהּ אִם נִטְמֵאת בְּמַגָּע וְאִם נִטְמֵאת בָּאֲוִיר בִּלְבַד אֵין מִתְטַמְּאִין עִמָּהּ. וְאֵין מְדַקְדְּקִין בְּכָל הַשִּׁעוּרִין הָאֵלּוּ שֶׁכֻּלָּן הֵן מִדִּבְרֵי סוֹפְרִים:"],"Mishneh Torah, Vessels 28":["כָּל הַכֵּלִים שֶׁיֵּשׁ לָהֶן בֵּית קִבּוּל שֶׁנִּטְמְאוּ אֲחוֹרֵיהֶן בְּמַשְׁקִין לֹא נִטְמָא תּוֹכָן לִתְרוּמָה וְלֹא אָגְנֵיהֶן וְלֹא אָזְנֵיהֶן וְלֹא מְקוֹם אֶצְבַּע הַשּׁוֹקֵעַ בִּשְׂפַת הַכְּלִי. נִטְמָא תּוֹךְ הַכְּלִי נִטְמְאוּ כֻּלָּן. נָפְלוּ מַשְׁקִין טְמֵאִין עַל כַּנֵּי הַכֵּלִים אוֹ עַל אָגְנֵיהֶן אוֹ עַל אָזְנֵיהֶן אוֹ עַל יְדוֹת הַכֵּלִים הַמְקַבְּלִין הֲרֵי זֶה מְנַגְּבָן וְהֵן טְהוֹרִין וַאֲפִלּוּ אֲחוֹרֵי הַכְּלִי כֻּלּוֹ לֹא נִטְמְאוּ:","אֶחָד כְּלֵי הַשַּׂק כְּגוֹן הַשַּׂקִּין וְהַמַּרְצּוּפִין. אוֹ כְּלֵי הָעוֹר כְּגוֹן הַכָּרִים וְהַכְּסָתוֹת. וְאֶחָד כְּלֵי עֵץ אֲפִלּוּ קֻפּוֹת וּמִשְׁפָּלוֹת אִם נִטְמְאוּ אֲחוֹרֵיהֶן בְּמַשְׁקִין לֹא נִטְמָא תּוֹכָן:","פְּשׁוּטֵי כְּלֵי שֶׁטֶף שֶׁאֵין רְאוּיִין לְמִדְרָס כְּגוֹן הַשֻּׁלְחָן וְטַבְלָא שֶׁאֵין לָהּ דֹּפֶן הוֹאִיל וְאֵין מְקַבְּלִין טֻמְאָה מִן הַתּוֹרָה אִם נִטְמְאוּ אֲחוֹרֵיהֶן בְּמַשְׁקִין לֹא נִטְמָא תּוֹכָן. אֲבָל פְּשׁוּטֵי כְּלֵי שֶׁטֶף הָרְאוּיִים לְמִדְרָס כְּגוֹן הַמִּטָּה וְהָעוֹר שֶׁיְּשֵׁנִים עָלָיו וְהַכִּסֵּא וְכַיּוֹצֵא בָּהֶן אֵין לָהֶם אֲחוֹרַיִם וְתוֹךְ אֶלָּא בֵּין שֶׁנָּגְעוּ מַשְׁקִין בָּהֶן מִתּוֹכָן אוֹ מֵאֲחוֹרֵיהֶן נִטְמָא הַכְּלִי כֻּלּוֹ. וְכֵן מִדּוֹת יַיִן וְשֶׁמֶן וְזוֹמָא לִיסְטְרוֹת וּמְסַנֶּנֶת שֶׁל חַרְדָּל וּמְשַׁמֶּרֶת שֶׁל יַיִן אֵין לָהֶן אֲחוֹרַיִם וְתוֹךְ אֶלָּא אִם נָפַל מַשְׁקִין עַל מִקְצָתָן נִטְמְאוּ כֻּלָּן כְּמוֹ הַבְּגָדִים:","הַמַּרְדֵּעַ וְהַמַּלְמָד יֵשׁ לָהֶן אֲחוֹרַיִם וְתוֹךְ. כֵּיצַד. נָפְלוּ מַשְׁקִין עַל הַחַרְחוּר לֹא נִטְמָא מִן הָעֵץ הַסָּמוּךְ לַחַרְחוּר אֶלָּא שִׁבְעָה טְפָחִים בִּלְבַד וּשְׁאָר הָעֵץ טָהוֹר. וְכֵן אִם נָפְלוּ מַשְׁקִין עַל הַדָּרְבָן לֹא נִטְמָא אֶלָּא אַרְבָּעָה טְפָחִים הַסְּמוּכִין לַדָּרְבָן. נָפְלוּ חוּץ לְשִׁבְעָה וְחוּץ לְאַרְבָּעָה הֲרֵי זֶה כִּכְלִי קִבּוּל שֶׁנָּגְעוּ מַשְׁקִין בַּאֲחוֹרָיו וְלֹא נִטְמְאוּ אֶלָּא מִמְּקוֹם מַגָּעוֹ וְלַחוּץ:","כִּיס שֶׁבְּתוֹךְ כִּיס שֶׁנִּטְמָא אֶחָד מֵהֶן בְּמַשְׁקִין לֹא נִטְמָא חֲבֵרוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ שִׂפְתוֹתֵיהֶן שָׁוִין. אֲבָל אִם הָיָה הַחִיצוֹן עוֹדֵף וְנִטְמָא הַפְּנִימִי. נִטְמָא הַחִיצוֹן נִטְמָא הַחִיצוֹן לֹא נִטְמָא הַפְּנִימִי וּבְשֶׁרֶץ בֵּין כָּךְ וּבֵין כָּךְ אִם נִטְמָא אֶחָד מֵהֶם לֹא נִטְמָא חֲבֵרוֹ:","הַחוֹקֵק רֹבַע וַחֲצִי רֹבַע בְּעֵץ אֶחָד וְנִטְמָא אֶחָד מֵהֶן בְּמַשְׁקִין לֹא נִטְמָא הַשֵּׁנִי אַף עַל פִּי שֶׁהֵן עֵץ אֶחָד. כֵּיצַד. נָגְעוּ מַשְׁקִין טְמֵאִין בְּתוֹךְ הָרֹבַע הָרֹבַע וַאֲחוֹרָיו טְמֵאִין וַחֲצִי הָרֹבַע וַאֲחוֹרָיו טְהוֹרִין. נָגְעוּ בַּחֲצִי הָרֹבַע מִתּוֹכוֹ חֲצִי הָרֹבַע וַאֲחוֹרָיו טְמֵאִים הָרֹבַע וַאֲחוֹרָיו טְהוֹרִין. וּכְשֶׁהוּא מַטְבִּיל מַטְבִּיל אֶת הַכּל. נִטְמְאוּ אֲחוֹרֵי הָרֹבַע אוֹ אֲחוֹרֵי חֲצִי הָרֹבַע בְּמַשְׁקִין הֲרֵי אֲחוֹרֵי הַכְּלִי טָמֵא שֶׁאֵין חוֹלְקִין אֶת הָאֲחוֹרַיִם:","קוּמְקוּמוֹס שֶׁהָיוּ אֲחוֹרָיו טְמֵאִין וְהָיָה מַרְתִּיחַ אֵין חוֹשְׁשִׁין שֶׁמָּא יָצְאוּ מַשְׁקִין מִתּוֹכוֹ וְנָגְעוּ בַּאֲחוֹרָיו וְחָזְרוּ לְתוֹכוֹ אֶלָּא הֲרֵי הַמַּשְׁקִין שֶׁבְּתוֹכוֹ טְהוֹרִין לִתְרוּמָה: בְּרִיךְ רַחֲמָנָא דְּסַיְּעָן"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 4":["הַכֹּהֲנִּים הֻבְדְּלוּ מִכְּלַל הַלְוִיִּם לַעֲבוֹדַת הַקָּרְבָּנוֹת שֶׁנֶּאֱמַר (דברי הימים א כג יג) \"וַיִּבָּדֵל אַהֲרֹן לְהַקְדִּישׁוֹ קֹדֶשׁ קָדָשִׁים\". וּמִצְוַת עֲשֵׂה הִיא לְהַבְדִּיל הַכֹּהֲנִים וּלְקַדְּשָׁם וְלַהֲכִינָם לְקָרְבָּן שֶׁנֶּאֱמַר (ויקרא כא ח) \"וְקִדַּשְׁתּוֹ כִּי אֶת לֶחֶם אֱלֹהֶיךָ הוּא מַקְרִיב\":","וְצָרִיךְ כָּל אָדָם מִיִּשְׂרָאֵל לִנְהֹג בָּהֶן כָּבוֹד הַרְבֵּה וּלְהַקְדִּים אוֹתָם לְכָל דָּבָר שֶׁבִּקְדֻשָּׁה. לִפְתֹּחַ בַּתּוֹרָה רִאשׁוֹן. וּלְבָרֵךְ רִאשׁוֹן. וְלִטֹּל מָנָה יָפָה רִאשׁוֹן:","משֶׁה רַבֵּנוּ חִלֵּק הַכֹּהֲנִים לִשְׁמוֹנֶה מִשְׁמָרוֹת. אַרְבָּעָה מֵאֶלְעָזָר. וְאַרְבָּעָה מֵאִיתָמָר. וְכֵן הָיוּ עַד שְׁמוּאֵל הַנָּבִיא. וּבִימֵי שְׁמוּאֵל חִלְּקָם הוּא וְדָוִד הַמֶּלֶךְ לְאַרְבָּעָה וְעֶשְׂרִים מִשְׁמָר. וְעַל כָּל מִשְׁמָר וּמִשְׁמָר רֹאשׁ אֶחָד מְמֻנֶּה. וְעוֹלִין לִירוּשָׁלַיִם לַעֲבוֹדָה מִשְׁמָר לְכָל שַׁבָּת. וּמִיּוֹם הַשַּׁבָּת לְיוֹם הַשַּׁבָּת הֵן מִתְחַלְּפִין מִשְׁמָר יוֹצֵא וְהָאַחֵר שֶׁהוּא אַחֲרָיו נִכְנָס. עַד שֶׁיִּגְמְרוּ וְחוֹזְרִין חֲלִילָה:","וּמִצְוַת עֲשֵׂה לִהְיוֹת כָּל הַמִּשְׁמָרוֹת שָׁוִים בָּרְגָלִים. וְכָל שֶׁיָּבוֹא מִן הַכֹּהֲנִים בָּרֶגֶל וְרָצָה לַעֲבֹד עוֹבֵד וְחוֹלֵק עִמָּהֶם. וְאֵין אוֹמְרִין לוֹ לֵךְ עַד שֶׁיַּגִּיעַ מִשְׁמָרְךָ שֶׁנֶּאֱמַר (דברים יח ו) \"וְכִי יָבֹא הַלֵּוִי מֵאַחַד שְׁעָרֶיךָ\" וְגוֹ':","בַּמֶּה דְּבָרִים אֲמוּרִים בְּקָרְבְּנוֹת הָרְגָלִים וּבְחִלּוּק לֶחֶם הַפָּנִים וּבְחִלּוּק שְׁתֵּי הַלֶּחֶם שֶׁל עֲצֶרֶת. אֲבָל נְדָרִים וּנְדָבוֹת וּתְמִידִין אֵין מַקְרִיבִין אוֹתָן אֶלָּא מִשְׁמָר שֶׁזְּמַנּוֹ קָבוּעַ וַאֲפִלּוּ בָּרֶגֶל. שֶׁנֶּאֱמַר (דברים יח ח) \"חֵלֶק כְּחֵלֶק יֹאכֵלוּ לְבַד מִמְכָּרָיו עַל הָאָבוֹת\". כְּלוֹמַר חֵלֶק כְּחֵלֶק יֹאכְלוּ בְּקָרְבְּנוֹת הַצִּבּוּר. וְאֵין חֵלֶק כְּחֵלֶק בִּשְׁאָר הַדְּבָרִים שֶׁכְּבָר חָלְקוּ אוֹתָם הָאָבוֹת וּקְבָעוּם כָּל מִשְׁמָר וּמִשְׁמָר בְּשַׁבַּתּוֹ:","וְכֵן עֲבוֹדַת לֶחֶם הַפָּנִים בַּמִּשְׁמָר שֶׁזְּמַנּוֹ קָבוּעַ. אֲבָל עֲבוֹדַת שְׁתֵּי הַלֶּחֶם בְּכָל הַמִּשְׁמָרוֹת. וּמִנַּיִן שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בָּרְגָלִים שֶׁנֶּאֱמַר (דברים יח ו) \"מֵאַחַד שְׁעָרֶיךָ מִכָּל יִשְׂרָאֵל\" בְּשָׁעָה שֶׁכָּל יִשְׂרָאֵל בָּאִין בְּשַׁעַר אֶחָד. וּמִנַּיִן שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בַּכֹּהֲנִים שֶׁנֶּאֱמַר (דברים יח ח) \"חֵלֶק כְּחֵלֶק יֹאכֵלוּ\". וְאֵין שָׁם מַתָּנוֹת בַּמִּקְדָּשׁ לְהֵאָכֵל אֶלָּא לַכֹּהֲנִים בִּלְבַד:","וְכֵן כֹּהֵן שֶׁהָיָה לוֹ קָרְבָּן הֲרֵי זֶה בָּא לַמִּקְדָּשׁ וּמַקְרִיבוֹ בְּכָל יוֹם שֶׁיִּרְצֶה שֶׁנֶּאֱמַר (דברים יח ו) \"וּבָא בְּכָל אַוַּת נַפְשׁוֹ\" (דברים יח ז) \"וְשֵׁרֵת\". וַאֲפִלּוּ חַטָּאתוֹ וַאֲשָׁמוֹ הוּא מַקְרִיב וּמְכַפֵּר עַל יְדֵי עַצְמוֹ וְהָעוֹר שֶׁל קָרְבָּנוֹ וַאֲכִילָתוֹ שֶׁלּוֹ. וְאִם רָצָה לִתֵּן אֶת קָרְבָּנוֹ לְכָל כֹּהֵן שֶׁיִּרְצֶה לְהַקְרִיבוֹ נוֹתֵן. וְעוֹר הַקָּרְבָּן וַעֲבוֹדָתוֹ לְאוֹתוֹ הַכֹּהֵן בִּלְבַד שֶׁנָּתַן לוֹ:","הָיָה הַכֹּהֵן בַּעַל הַקָּרְבָּן בַּעַל מוּם נוֹתֵן קָרְבָּנוֹ לְאַנְשֵׁי מִשְׁמָר וְהָעוֹר שֶׁלָּהֶם. הָיָה זָקֵן אוֹ חוֹלֶה שֶׁיָּכוֹל לַעֲבֹד עַל יְדֵי הַדְּחָק נוֹתֵן קָרְבָּנוֹ לְכָל כֹּהֵן שֶׁיִּרְצֶה וְהָעוֹר וְהָעֲבוֹדָה לְאַנְשֵׁי מִשְׁמָר. וְאִם אֵינוֹ יָכוֹל לַעֲבֹד כְּלָל הֲרֵי הַקָּרְבָּן כֻּלּוֹ לְאַנְשֵׁי מִשְׁמָר:","הָיָה טָמֵא בְּקָרְבְּנוֹת הַצִּבּוּר וְכָל הַכֹּהֲנִים טְמֵאִים נוֹתְנוֹ לְבַעֲלֵי מוּמִין טְהוֹרִים שֶׁבְּאוֹתוֹ מִשְׁמָר. וְעוֹרוֹ וַעֲבוֹדָתוֹ לְאַנְשֵׁי מִשְׁמָר הַטְּמֵאִים:","הָיָה הַקָּרְבָּן שֶׁל כֹּהֵן גָּדוֹל וְהָיָה אוֹנֵן נוֹתְנוֹ לְכָל כֹּהֵן שֶׁיִּרְצֶה וְעוֹרוֹ וַעֲבוֹדָתוֹ לְאַנְשֵׁי מִשְׁמָר. כֵּיוָן שֶׁכֹּהֵן גָּדוֹל הָאוֹנֵן רָאוּי לַעֲבוֹדָה כְּמוֹ שֶׁיִּתְבָּאֵר הֲרֵי זֶה עוֹשֶׂה שָׁלִיחַ לְקָרְבָּנוֹ:","כָּל רֹאשׁ מִשְׁמָר וּמִשְׁמָר מְחַלֵּק מִשְׁמָרוֹ לְבָתֵּי אָבוֹת. עַד שֶׁיִּהְיֶה כָּל בֵּית אָב וַאֲנָשָׁיו עוֹבֵד בְּיוֹם אֶחָד מִימוֹת הַשַּׁבָּת. וְהָאַחֵר בְּיוֹם שֶׁל אַחֲרָיו. וְהָאַחֵר בְּיוֹם שֶׁל אַחֲרָיו. וּלְכָל בֵּית אָב וְאָב רֹאשׁ אֶחָד מְמֻנֶּה עָלָיו:","וּמְמַנִּין כֹּהֵן גָּדוֹל הוּא רֹאשׁ לְכָל הַכֹּהֲנִים. וּמוֹשְׁחִין אוֹתוֹ בְּשֶׁמֶן הַמִּשְׁחָה. וּמַלְבִּישִׁין אוֹתוֹ בִּגְדֵי כְּהֻנָּה גְּדוֹלָה שֶׁנֶּאֱמַר (ויקרא כא י) \"וְהַכֹּהֵן הַגָּדוֹל מֵאֶחָיו אֲשֶׁר יוּצַק\" וְגוֹ'. וְאִם אֵין שָׁם שֶׁמֶן הַמִּשְׁחָה מְרַבִּין אוֹתוֹ בְּבִגְדֵי כְּהֻנָּה גְּדוֹלָה בִּלְבַד שֶׁנֶּאֱמַר (ויקרא כא י) \"אֲשֶׁר יוּצַק עַל רֹאשׁוֹ שֶׁמֶן הַמִּשְׁחָה וּמִלֵּא אֶת יָדוֹ לִלְבּשׁ אֶת הַבְּגָדִים\". כְּשֵׁם שֶׁמִּתְרַבֶּה בְּשֶׁמֶן הַמִּשְׁחָה כָּךְ מִתְרַבֶּה בִּבְגָדִים:","כֵּיצַד מְרַבִּין אוֹתוֹ בִּבְגָדִים. לוֹבֵשׁ שְׁמוֹנָה בְּגָדִים וּפוֹשְׁטָן וְחוֹזֵר וְלוֹבְשָׁן לְמָחָר שִׁבְעַת יָמִים יוֹם אַחַר יוֹם שֶׁנֶּאֱמַר (שמות כט ל) \"שִׁבְעַת יָמִים יִלְבָּשָׁם הַכֹּהֵן תַּחְתָּיו מִבָּנָיו\". וּכְשֵׁם שֶׁרִבּוּי בְּגָדִים שִׁבְעָה כָּךְ מְשִׁיחָה בְּשֶׁמֶן שִׁבְעָה יוֹם אַחַר יוֹם. וְאִם עָבַד קֹדֶם שֶׁיִּתְרַבֶּה בִּבְגָדִים כָּל שִׁבְעָה אוֹ קֹדֶם שֶׁיִּמָּשַׁח כָּל שִׁבְעָה עֲבוֹדָתוֹ כְּשֵׁרָה. הוֹאִיל וְנִתְרַבָּה אוֹ נִמְשַׁח פַּעַם אַחַת נַעֲשָׂה כֹּהֵן גָּדוֹל לְכָל דָּבָר:","אֵין בֵּין כֹּהֵן מָשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה לִמְרֻבֶּה בְּגָדִים אֶלָּא פַּר שֶׁמֵּבִיא כֹּהֵן הַמָּשִׁיחַ אִם שָׁגַג בְּאֶחָד מִן הַמִּצְוֹת שֶׁחַיָּב עֲלֵיהֶן חַטָּאת שֶׁנֶּאֱמַר (ויקרא ד ג) \"אִם הַכֹּהֵן הַמָּשִׁיחַ יֶחֱטָא\" וְגוֹ'. אֲבָל לִשְׁאָר הַדְּבָרִים שָׁוִים הֵם:","אֵין מַעֲמִידִין כֹּהֵן גָּדוֹל אֶלָּא בֵּית דִּין שֶׁל אֶחָד וְשִׁבְעִים. וְאֵין מוֹשְׁחִין אוֹתוֹ אֶלָּא בַּיּוֹם שֶׁנֶּאֱמַר (ויקרא ו יג) \"בְּיוֹם הִמָּשַׁח אֹתוֹ\". וְכֵן אִם נִתְרַבָּה בִּבְגָדִים בִּלְבַד אֵין מְרַבִּין אוֹתוֹ אֶלָּא בַּיּוֹם. וְאֵין מְמַנִּין שְׁנֵי כֹּהֲנִים גְּדוֹלִים כְּאַחַת:","מְמַנִּין כֹּהֵן אֶחָד יִהְיֶה לְכֹהֵן גָּדוֹל כְּמוֹ הַמִּשְׁנֶה לַמֶּלֶךְ וְהוּא הַנִּקְרָא סְגָן. וְהוּא הַנִּקְרָא מְמֻנֶּה וְיִהְיֶה עוֹמֵד לִימִין כֹּהֵן גָּדוֹל תָּמִיד וְזֶה כָּבוֹד הוּא לוֹ. וְכָל הַכֹּהֲנִים מִתַּחַת יַד הַסְּגָן:","וְעוֹד מְמַנִּין קַתִּיקוֹלִין לִהְיוֹת לַסְּגָן כְּמוֹ הַסְּגָן לְכֹהֵן גָּדוֹל. וְאֵין פּוֹחֲתִין מִשְּׁנַיִם. וּמְמַנִּים אֲמַרְכָּלִין אֵין פָּחוֹת מִשִּׁבְעָה. וּמַפְתְּחוֹת הָעֲזָרָה בְּיָדָם רָצָה הָאֶחָד לִפְתֹּחַ אֵינוֹ יָכוֹל עַד שֶׁיִּתְכַּנְּסוּ כָּל הָאֲמַרְכּוֹלִין וְיִפְתְּחוּ:","וּמְמַנִּין גִּזְבָּרִין מִתַּחַת יְדֵי הָאֲמַרְכּוֹלִין. וְאֵין פּוֹחֲתִין מִשְּׁלֹשָׁה גִּזְבָּרִין. וְהַגִּזְבָּרִין הֵם שֶׁגּוֹבִין כָּל הַהֶקְדֵּשׁוֹת. וּפוֹדִין אֶת הַנִּפְדֶּה מֵהֶן וּמוֹצִיאִין אוֹתָן בִּדְבָרִים הָרְאוּיִין לָהֶן לְהוֹצִיאָן:","כֹּהֵן הַגָּדוֹל הַמָּשׁוּחַ קוֹדֵם לִמְרֻבֶּה בְּגָדִים. וּמְרֻבֶּה בְּגָדִים הָעוֹמֵד לְשָׁרֵת קוֹדֵם לְמָשׁוּחַ שֶׁעָבַר מֵחֲמַת קֶרִי. וְהָעוֹבֵר מֵחֲמַת קֶרִי קוֹדֵם לְעוֹבֵר מֵחֲמַת מוּם. וְהָעוֹבֵר מֵחֲמַת מוּם קוֹדֵם לְכֹהֵן מְשׁוּחַ מִלְחָמָה. וּמְשׁוּחַ מִלְחָמָה קוֹדֵם לִסְגָן. וּסְגָן קוֹדֵם לְקַתִּיקוֹל. וְקַתִּיקוֹל קוֹדֵם לַאֲמַרְכָּל. וַאֲמַרְכָּל קוֹדֵם לְגִזְבָּר. וְגִזְבָּר קוֹדֵם לְרֹאשׁ מִשְׁמָר. וְרֹאשׁ הַמִּשְׁמָר קוֹדֵם לְרֹאשׁ בֵּית אָב. וְרֹאשׁ בֵּית אָב קוֹדֵם לְכֹהֵן הֶדְיוֹט מִשְּׁאָר הַכֹּהֲנִים. נִמְצְאוּ הַכֹּהֲנִים תָּמִיד שְׁמוֹנֶה מַעֲלוֹת זוֹ לְמַעְלָה מִזּוֹ:","כְּשֶׁיָּמוּת הַמֶּלֶךְ אוֹ כֹּהֵן גָּדוֹל אוֹ אֶחָד מִשְּׁאָר הַמְמֻנִּים מַעֲמִידִין תַּחְתָּיו בְּנוֹ אוֹ הָרָאוּי לְיָרְשׁוֹ. וְכָל הַקּוֹדֵם לְנַחֲלָה קוֹדֵם לִשְׂרָרוֹת הַמֵּת. וְהוּא שֶׁיִּהְיֶה מְמַלֵּא מְקוֹמוֹ בְּחָכְמָה אוֹ בְּיִרְאָה אַף עַל פִּי שֶׁאֵינוֹ כְּמוֹתוֹ בְּחָכְמָה שֶׁנֶּאֱמַר בְּמֶלֶךְ (דברים יז כ) \"הוּא וּבָנָיו בְּקֶרֶב יִשְׂרָאֵל\". מְלַמֵּד שֶׁהַמַּלְכוּת יְרֻשָּׁה. וְהוּא הַדִּין לְכָל שְׂרָרָה שֶׁבְּקֶרֶב יִשְׂרָאֵל שֶׁהַזּוֹכֶה לָהּ זוֹכֶה לְעַצְמוֹ וּלְזַרְעוֹ:","מְשׁוּחַ מִלְחָמָה אֵין בְּנוֹ מִתְמַנֶּה תַּחְתָּיו לְעוֹלָם אֶלָּא הֲרֵי הוּא כִּשְׁאָר הַכֹּהֲנִים. אִם נִמְשַׁח לַמִּלְחָמָה נִמְשַׁח וְאִם לֹא נִמְשַׁח לֹא נִמְשַׁח. וּכְשֶׁכֹּהֵן מְשׁוּחַ מִלְחָמָה מְשַׁמֵּשׁ בַּמִּקְדָּשׁ מְשַׁמֵּשׁ בְּאַרְבָּעָה כֵּלִים כִּשְׁאָר כֹּהֲנִים. מַעֲלִין מִשְּׂרָרָה לִשְׂרָרָה גְּדוֹלָה מִמֶּנָּה וְאֵין מוֹרִידִין אוֹתוֹ לַשְּׂרָרָה שֶׁהִיא לְמַטָּה מִמֶּנָּה. שֶׁמַּעֲלִין בַּקֹּדֶשׁ וְלֹא מוֹרִידִין. וְאֵין מוֹרִידִין לְעוֹלָם מִשְּׂרָרָה שֶׁבְּקֶרֶב יִשְׂרָאֵל אֶלָּא אִם סָרַח:","וְכֹהֵן גָּדוֹל שֶׁעָבַר עֲבֵרָה שֶׁחַיָּב עָלֶיהָ מַלְקוֹת מַלְקִין אוֹתוֹ בְּבֵית דִּין שֶׁל שְׁלֹשָׁה כִּשְׁאָר מְחֻיְּבֵי מַלְקוֹת וְחוֹזֵר לִגְדֻלָּתוֹ:"],"Mishneh Torah, Vows 12":["כָּל הַנְּדָרִים וְהַשְּׁבוּעוֹת הָאָב מֵפֵר בְּיוֹם שָׁמְעוֹ. שֶׁנֶּאֱמַר (במדבר ל ו) \"כָּל נְדָרֶיהָ וֶאֱסָרֶיהָ\". אֲבָל הַבַּעַל אֵינוֹ יָכוֹל לְהָפֵר אֶלָּא כָּל נְדָרִים וּשְׁבוּעוֹת שֶׁיֵּשׁ בָּהֶן עִנּוּי נֶפֶשׁ אוֹ שֶׁהֵן בִּדְבָרִים שֶׁבֵּינוֹ לְבֵינָהּ כְּגוֹן שֶׁנִּשְׁבְּעָה אוֹ נָדְרָה שֶׁלֹּא תִּכְחל אוֹ שֶׁלֹּא תִּתְקַשֵּׁט שֶׁנֶּאֱמַר (במדבר ל יז) \"בֵּין אִישׁ לְאִשְׁתּוֹ\":","וּמַה בֵּין נְדָרִים שֶׁיֵּשׁ בָּהֶן עִנּוּי נֶפֶשׁ לִדְבָרִים שֶׁבֵּינוֹ לְבֵינָהּ. שֶׁהַנְּדָרִים שֶׁיֵּשׁ בָּהֶן עִנּוּי נֶפֶשׁ מֵפֵר אֶל עַצְמוֹ וְאֶל אֲחֵרִים. וְשֶׁבֵּינוֹ לְבֵינָהּ לְעַצְמוֹ מֵפֵר וְלַאֲחֵרִים אֵינוֹ מֵפֵר:","כֵּיצַד. נָדְרָה שֶׁלֹּא לֶאֱכל בָּשָׂר מֵפֵר לָהּ וְתִהְיֶה מֻתֶּרֶת לֶאֱכל עִם כָּל אָדָם לְעוֹלָם. אָסְרָה עָלֶיהָ תַּשְׁמִישׁ כָּל אָדָם שֶׁבָּעוֹלָם יָפֵר חֶלְקוֹ וְתִהְיֶה מְשַׁמַּשְׁתּוֹ. וּכְשֶׁיָּמוּת אוֹ יְגָרְשֶׁנָּה הֲרֵי הִיא אֲסוּרָה בְּתַשְׁמִישׁ כָּל אָדָם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֶחָד עִנּוּי גָּדוֹל וְאֶחָד עִנּוּי קָטָן וְאֶחָד עִנּוּי שֶׁהוּא לִזְמַן מְרֻבֶּה אוֹ לְפִי שָׁעָה הַכּל מֵפֵר הַבַּעַל:","כֵּיצַד. נָדְרָה אוֹ נִשְׁבְּעָה שֶׁלֹּא תִּרְחַץ הַיּוֹם. אוֹ שֶׁלֹּא תִּשְׁתֶּה יַיִן הַיּוֹם. אוֹ שֶׁלֹּא תֹּאכַל הַיּוֹם דְּבַשׁ. וְכֵן אִם נָדְרָה שֶׁלֹּא תִּכְחל הַיּוֹם אוֹ שֶׁלֹּא תִּלְבַּשׁ רִקְמָה הַיּוֹם מֵפֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲפִלּוּ נָדְרָה מִמַּאֲכָל רַע אוֹ מִמִּין שֶׁלֹּא טָעֲמָה אוֹתוֹ מִיָּמֶיהָ הֲרֵי זֶה יָפֵר:","נָדְרָה מִשְּׁתֵי כִּכָּרוֹת בְּאַחַת יֵשׁ לָהּ עִנּוּי וּבְאַחַת אֵין לָהּ עִנּוּי מֵפֵר לְזוֹ שֶׁמִּתְעַנָּה בָּהּ וְאֵינוֹ מֵפֵר לְזוֹ שֶׁאֵין לָהּ עִנּוּי:","נָדְרָה שֶׁלֹּא תֹּאכַל תְּאֵנִים שֶׁל מְדִינָה זוֹ יָפֵר מִשּׁוּם דְּבָרִים שֶׁבֵּינוֹ לְבֵינָהּ שֶׁעֵסֶק גָּדוֹל הוּא לוֹ לְהִטָּפֵל וּלְהָבִיא לָהּ מִמְּדִינָה אַחֶרֶת. לְפִיכָךְ אִם מֵת אוֹ גֵּרְשָׁהּ אוֹ שֶׁהֵבִיא לָהּ אִישׁ אַחֵר מִפֵּרוֹת אוֹתָהּ מְדִינָה הֲרֵי אֵלּוּ אֲסוּרִין עָלֶיהָ שֶׁאֵינוֹ מֵפֵר לַאֲחֵרִים בִּדְבָרִים שֶׁבֵּינוֹ לְבֵינָהּ:","וְכֵן אִם נָדְרָה שֶׁלֹּא לְהַנּוֹת לַבְּרִיּוֹת אַף עַל פִּי שֶׁאֵין הַבַּעַל בַּכְּלָל יֵשׁ לוֹ לְהָפֵר מִשּׁוּם דְּבָרִים שֶׁבֵּינוֹ לְבֵינָהּ. שֶׁלֹּא יִהְיֶה זָקוּק לְהַאֲכִילָהּ מִשֶּׁלּוֹ בִּלְבַד. וְכֵן אִם אָסְרָה הֲנָאָתָהּ עַל אֻמָּה (כֻּלָּהּ) כְּגוֹן [כָּל] הַיְהוּדִים אוֹ כָּל הַיִּשְׁמְעֵאלִים הֲרֵי זֶה יָפֵר:","הָאִשָּׁה שֶּׁאֲמָרָהּ לְבַעְלָהּ הֲנָאַת תַּשְׁמִישִׁי אֲסוּרָה עָלֶיךָ אֵינוֹ צָרִיךְ לְהָפֵר. הָא לְמָה זֶה דּוֹמֶה לְאוֹסֵר פֵּרוֹת חֲבֵרוֹ עַל בַּעַל הַפֵּרוֹת. וְכֵן הוּא שֶׁאוֹמֵר לָהּ הֲנָאַת תַּשְׁמִישִׁי אֲסוּרָה עָלַיִךְ לֹא אָמַר כְּלוּם מִפְּנֵי שֶׁהוּא מְשֻׁעְבָּד לָהּ בִּשְׁאֵר כְּסוּת וְעוֹנָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת אִישׁוּת. אֲבָל אִם אָמְרָה לוֹ הֲנָאַת תַּשְׁמִישְׁךָ אֲסוּרָה עָלַי צָרִיךְ לְהָפֵר. וְאִם לֹא הֵפֵר הֲרֵי זֶה אָסוּר לְשַׁמְּשָׁהּ שֶׁאֵין מַאֲכִילִין אֶת הָאָדָם דָּבָר הָאָסוּר לוֹ:","אָמְרָה יִקְדְּשׁוּ יָדַי לְעוֹשֵׂיהֶן אוֹ שֶׁנָּדְרָה שֶׁלֹּא יֵהָנֶה בְּמַעֲשֵׂה יָדֶיהָ אֵינוֹ נֶאֱסָר בְּמַעֲשֵׂה יָדֶיהָ מִפְּנֵי שֶׁיָּדֶיהָ מְשֻׁעְבָּדִין לוֹ. שֶׁאַף עַל פִּי שֶׁאָמְרוּ הַשִּׁחְרוּר וְהֶחָמֵץ וְהַהֶקְדֵּשׁ מַפְקִיעִין הַשִּׁעְבּוּד חֲכָמִים עָשׂוּ חִזּוּק לְשִׁעְבּוּד הַבַּעַל שֶׁאֵינָהּ יְכוֹלָה לְהַפְקִיעוֹ מִפְּנֵי שֶׁהוּא מִדִּבְרֵיהֶם. אֲבָל צָרִיךְ הוּא לְהָפֵר שֶׁמָּא יְגָרְשֶׁנָּה וְתִהְיֶה אֲסוּרָה לַחְזֹר לוֹ:","נִשְׁבְּעָה אוֹ נָדְרָה שֶׁלֹּא יֶהֱנֶה בָּהּ לֹא אֲבִי בַּעְלָהּ וְלֹא אֶחָיו וּשְׁאָר קְרוֹבָיו אֵינוֹ יָכוֹל לְהָפֵר. וְכֵן אִם נָדְרָה שֶׁלֹּא אֶתֵּן מַיִם לִפְנֵי בְּהֶמְתְּךָ וְתֶבֶן לִפְנֵי בְּקָרְךָ וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁאֵין בָּהֶן עִנּוּי נֶפֶשׁ וְאֵינָם מִדְּבָרִים שֶׁבֵּינוֹ לְבֵינָהּ וְאֵינָהּ מִמְּלָאכוֹת שֶׁהִיא חַיֶּבֶת בָּהֶן הֲרֵי זֶה אֵינוֹ יָכוֹל לְהָפֵר:","יֵשׁ לַבַּעַל וְלָאָב לְהָפֵר נְדָרִים שֶׁעֲדַיִן לֹא חָלוּ וְלֹא נֶאֶסְרָה בָּהֶן. כֵּיצַד. כְּגוֹן שֶׁאָמְרָה הַיַּיִן אָסוּר עָלַי אִם אֵלֵךְ לְמָקוֹם פְּלוֹנִי הֲרֵי זֶה מֵפֵר אַף עַל פִּי שֶׁעֲדַיִן לֹא הָלְכָה וְלֹא נֶאֶסְרָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָאָב אוֹ הַבַּעַל שֶׁאֵין שׁוֹמְעִין אֵינָם מְפֵרִין. אַף עַל פִּי שֶׁהַבַּעַל מֵפֵר נְדָרִים שֶׁלֹּא שְׁמָעָן הָרָאוּי לִשְׁמֹעַ אֵין הַשְּׁמוּעָה מְעַכֶּבֶת בּוֹ:","הַשּׁוֹטֶה אֵינוֹ מֵפֵר בֵּין אָב בֵּין בַּעַל. הַקָּטָן אֵין לוֹ אִישׁוּת לְפִיכָךְ אֵינוֹ מֵפֵר. וְהַבַּעַל מֵפֵר נִדְרֵי שְׁתֵּי נָשָׁיו כְּאַחַת. וְכֵן הָאָב מֵפֵר נִדְרֵי שְׁתֵּי בְּנוֹתָיו כְּאַחַת:","הֲפָרַת נְדָרִים כָּל הַיּוֹם וְאֵינָהּ מֵעֵת לְעֵת. כֵּיצַד. נָדְרָה בִּתְחִלַּת לֵיל שֵׁנִי הֲרֵי מֵפֵר כָּל אוֹתוֹ הַלַּיְלָה וְכָל יוֹם שֵׁנִי. נָדְרָה בְּיוֹם שֵׁנִי בִּתְחִלַּת הַיּוֹם מֵפֵר כָּל אוֹתוֹ הַיּוֹם. נָדְרָה בְּסוֹף הַיּוֹם עִם חֲשֵׁכָה אִם הֵפֵר לָהּ עַד שֶׁלֹּא תֶּחְשַׁךְ מוּפָר. וְאִם לֹא הֵפֵר לָהּ עַד שֶׁחֲשֵׁכָה אֵינוֹ יָכוֹל לְהָפֵר:","וּמַהוּ זֶה שֶׁכָּתוּב בַּתּוֹרָה (במדבר ל טו) \"מִיּוֹם אֶל יוֹם\". מְלַמֵּד שֶׁמֵּפֵר בַּלַּיְלָה אִם נָדְרָה בַּלַּיְלָה. וְכֵן מֵפֵר כָּל הַיּוֹם כְּמוֹ שֶׁבֵּאַרְנוּ. נָדְרָה וְשָׁהֲתָה כַּמָּה יָמִים וְאַחַר כָּךְ שָׁמַע הָאָב אוֹ הַבַּעַל הֲרֵי זֶה מֵפֵר בְּיוֹם שָׁמְעוֹ וּכְאִלּוּ נָדְרָה בְּעֵת שֶׁשְּׁמָעָהּ שֶׁנֶּאֱמַר (במדבר ל ו) (במדבר ל יג) \"בְּיוֹם שָׁמְעוֹ\" לֹא בְּיוֹם נִדְרָהּ בִּלְבַד:","נַעֲרָה מְאֹרָסָה שֶׁנָּדְרָה וְשָׁמַע אָבִיהָ וְהֵפֵר וּלְאַחַר יָמִים שָׁמַע הָאָרוּס וְהֵפֵר בְּיוֹם שָׁמְעוֹ אֵין זֶה מוּפָר. שֶׁנֶּאֱמַר (במדבר ל ו) \"וְאִם הֵנִיא אָבִיהָ אוֹתָהּ בְּיוֹם שָׁמְעוֹ\" וְגוֹ' (במדבר ל ז) \"וְאִם הָיוֹ תִהְיֶה לְאִישׁ וּנְדָרֶיהָ עָלֶיהָ\" (במדבר ל ח) \"וְשָׁמַע אִישָׁהּ בְּיוֹם שָׁמְעוֹ\" וְגוֹ' הָא לָמַדְתָּ שֶׁאַחַר שֶׁהֵפֵר הָאָב וְשָׁמַע הָאָרוּס הֲרֵי זֶה מֵפֵר בְּיוֹם שְׁמוֹעַ הָאָב. וְהוּא הַדִּין אִם שָׁמַע אָרוּס וְהֵפֵר וְאַחַר כַּמָּה יָמִים שָׁמַע הָאָב וְהֵפֵר בְּיוֹם שָׁמְעוֹ שֶׁאֵינוֹ מוּפָר. וּמִנַּיִן שֶׁבְּנַעֲרָה מְאֹרָסָה הַכָּתוּב מְדַבֵּר שֶׁהֲרֵי הוּא אוֹמֵר לְמַטָּה (במדבר ל יא) \"וְאִם בֵּית אִישָׁהּ נָדָרָה\" וְגוֹ' (במדבר ל יב) \"וְשָׁמַע אִישָׁהּ וְהֶחֱרִשׁ לָהּ\" וְגוֹ' מִכְּלַל שֶׁאִישָׁהּ הָאָמוּר לְמַעְלָה אָרוּס כְּמוֹ שֶׁבֵּאַרְנוּ:","שָׁמַע הָאָב אוֹ הַבַּעַל וְשָׁתַק כְּדֵי לְצַעֲרָהּ אַף עַל פִּי שֶׁלֹּא הָיָה בְּלִבּוֹ לְקַיֵּם נִדְרָהּ הוֹאִיל וְעָבַר הַיּוֹם וְלֹא הֵפֵר וְלֹא בִּטֵּל נִתְקַיְּמוּ נְדָרֶיהָ. נָדְרָה וְהֵפֵר לָהּ הָאָב אוֹ הַבַּעַל וְהִיא לֹא יָדְעָה שֶׁהֵפֵר וְעָבְרָה עַל נִדְרָהּ אוֹ עַל שְׁבוּעָתָהּ בְּזָדוֹן הֲרֵי זוֹ פְּטוּרָה וְאַף עַל פִּי שֶׁנִּתְכַּוְּנָה לְאִסּוּר הוֹאִיל וְנַעֲשָׂה הַהֶתֵּר פְּטוּרָה וְעַל זֶה נֶאֱמַר (במדבר ל ו) \"וַה' יִסְלַח לָהּ כִּי הֵנִיא אָבִיהָ אֹתָהּ\". וּמַכִּין אוֹתָהּ מַכַּת מַרְדּוּת מִפְּנֵי שֶׁנִּתְכַּוְּנָה לְאִסּוּר:","נָדְרָה וְעָבְרָה עַל נִדְרָהּ קֹדֶם שֶׁיָּפֵר לָהּ אָבִיהָ אוֹ בַּעְלָהּ אַף עַל פִּי שֶׁשָּׁמַע בּוֹ בַּיּוֹם וְהֵפֵר לָהּ הֲרֵי זוֹ חַיֶּבֶת עַל דָּבָר שֶׁעָבְרָה בּוֹ. אִם מַלְקוֹת מַלְקוֹת וְאִם קָרְבָּן קָרְבָּן:","שָׁמַע נִדְרָהּ וְשָׁתַק מִפְּנֵי שֶׁלֹּא הָיָה יוֹדֵעַ שֶׁיֵּשׁ לָאָב אוֹ לַבַּעַל לְהָפֵר. אוֹ שֶׁיָּדַע שֶׁיֵּשׁ לָהֶם לְהָפֵר אֲבָל לֹא יָדַע שֶׁנֵּדֶר זֶה צָרִיךְ הֲפָרָה וּלְאַחַר זְמַן יָדַע הֲרֵי זֶה יָפֵר וּשְׁעַת יְדִיעָתוֹ כְּאִלּוּ הִיא שְׁעַת הַנֵּדֶר אוֹ שְׁעַת שְׁמוּעָתוֹ וְיָפֵר כָּל הַיּוֹם:","נָדְרָה אִשְׁתּוֹ וְסָבוּר שֶׁהִיא בִּתּוֹ וְהֵפֵר לָהּ עַל דַּעַת שֶׁהִיא בִּתּוֹ. וְכֵן אִם נָדְרָה בְּנָזִיר וְסָבוּר שֶׁנָּדְרָה בְּקָרְבָּן וְהֵפֵר לָהּ עַל דַּעַת שֶׁנָּדְרָה קָרְבָּן. אָסְרָה עַצְמָהּ בִּתְאֵנִים וְסָבוּר [שֶׁאָסְרָה עַצְמָהּ] בַּעֲנָבִים וְהֵפֵר לָהּ עַל דַּעַת שֶׁנָּדְרָה לֶאֱסֹר [עַצְמָהּ] בַּעֲנָבִים צָרִיךְ לַחְזֹר וּלְהָפֵר כְּשֶׁיֵּדַע הַנֵּדֶר וְהַנּוֹדֶרֶת לְשֵׁם הַנּוֹדֶרֶת הַזֹּאת וּלְשֵׁם הַנֵּדֶר הַזֶּה שֶׁנֶּאֱמַר (במדבר ל יב) \"לֹא הֵנִיא אָבִיהָ אֹתָהּ\" לְנוֹדֶרֶת עַצְמָהּ וְאוֹמֵר (במדבר ל ה) \"וְשָׁמַע אָבִיהָ אֶת נִדְרָהּ\" עַד שֶׁיֵּדַע אֵי זֶה נֵדֶר נָדְרָה. וְיֵשׁ לוֹ לְהָפֵר אוֹתוֹ כָּל יוֹם הַיְדִיעָה:"],"Mishneh Torah, Woman Suspected of Infidelity 3":["כֵּיצַד סֵדֶר הַשְׁקָאַת סוֹטָה. הַבַּעַל בָּא לְבֵית דִּין שֶׁבְּעִירוֹ וְאוֹמֵר לָהֶן אִשְׁתִּי זוֹ קִנֵּאתִי לָהּ עִם פְּלוֹנִי וְנִסְתְּרָה עִמּוֹ וְאֵלּוּ הֵן עֵדַי וַהֲרֵי הִיא אוֹמֶרֶת שֶׁהִיא טְהוֹרָה וַאֲנִי רוֹצֶה לְהַשְׁקוֹתָהּ לִבְדֹּק הַדָּבָר. וּבֵית דִּין שׁוֹמְעִין דִּבְרֵי הָעֵדִים. וּמוֹסְרִין לוֹ שְׁנֵי תַּלְמִידֵי חֲכָמִים לְשָׁמְרוֹ שֶׁמָּא יָבֹא עָלֶיהָ קֹדֶם שְׁתִיָּה. שֶׁהֲרֵי נֶאֶסְרָה עָלָיו עַד שֶׁתִּשְׁתֶּה. וּמְשַׁלְּחִין אוֹתוֹ לִירוּשָׁלַיִם שֶׁאֵין מַשְׁקִין אֶת הַסּוֹטָה אֶלָּא בְּבֵית דִּין הַגָּדוֹל שֶׁל שִׁבְעִים זְקֵנִים בַּמִּקְדָּשׁ:","הִגִּיעוּ לִירוּשָׁלַיִם בֵּית דִּין הַגָּדוֹל מוֹשִׁיבִין אוֹתָהּ בֵּינֵיהֶן וּמְאַיְּמִין עָלֶיהָ שֶׁלֹּא בִּפְנֵי בַּעְלָהּ וּמַפְחִידִין אוֹתָהּ פַּחַד גָּדוֹל שֶׁלֹּא תִּשְׁתֶּה. וְאוֹמְרִים לָהּ בִּתִּי הַרְבֵּה הַיַּיִן עוֹשֶׂה. הַרְבֵּה שְׂחוֹק עוֹשֶׂה. הַרְבֵּה יַלְדוּת עוֹשָׂה. הַרְבֵּה שְׁכֵנִים רָעִים עוֹשִׂים. אַל תִּגְרְמִי לַשֵּׁם הַגָּדוֹל שֶׁנִּכְתַּב בִּקְדֻשָּׁה שֶׁיִּמָּחֶה עַל הַמַּיִם. וְאוֹמְרִין לָהּ בִּתִּי הַרְבֵּה קְדָמוּךְ וְנִשְׁטְפוּ וַאֲנָשִׁים גְּדוֹלִים וִיקָרִים תָּקַף יִצְרָן עֲלֵיהֶן וְנִכְשְׁלוּ. וּמַגִּידִין לָהּ מַעֲשֵׂה יְהוּדָה וְתָמָר כַּלָּתוֹ. וּמַעֲשֵׂה רְאוּבֵן בְּפִילֶגֶשׁ אָבִיו עַל פְּשָׁטוֹ. וּמַעֲשֵׂה אַמְנוֹן וַאֲחוֹתוֹ. כְּדֵי לְהָקֵל עָלֶיהָ עַד שֶׁתּוֹדֶה. וְאִם אָמְרָה הֵן נִטְמֵאתִי אוֹ אֵינִי שׁוֹתָה יוֹצְאָה בְּלֹא כְּתֻבָּה וְהוֹלֶכֶת לָהּ:","עָמְדָה בְּדִבּוּרָהּ שֶׁהִיא טְהוֹרָה. מְבִיאִין אוֹתָהּ לְשַׁעַר מִזְרָחִי שֶׁל עֲזָרָה שֶׁהוּא כְּנֶגֶד קדֶשׁ הַקָּדָשִׁים. וּמַעֲלִין אוֹתָהּ מִמָּקוֹם לְמָקוֹם וּמַקִּיפִין בָּהּ כְּדֵי לְיַגְּעָהּ עַד שֶׁתִּקְצַר נַפְשָׁהּ אוּלַי תּוֹדֶה:","אִם עָמְדָה בְּדִבּוּרָהּ מְבִיאִין אוֹתָהּ כְּנֶגֶד שַׁעַר הַמִּזְרָח מִבַּחוּץ וּמַעֲמִידִין אוֹתָהּ שָׁם. הָיְתָה מִתְכַּסָּה בִּלְבָנִים מִתְכַּסָּה בִּשְׁחוֹרִין. וְאִם הָיוּ הַשְּׁחוֹרִין נָאִין לָהּ מִתְכַּסָּה בִּבְגָדִים שֶׁאֵין לָהּ בָּהֶן נוֹי. וּמְסִירִין כָּל כְּלֵי כֶּסֶף וְזָהָב שֶׁעָלֶיהָ:","וּמְקַבְּצִין עָלֶיהָ קִבּוּץ גָּדוֹל שֶׁל נָשִׁים שֶׁכָּל הַנָּשִׁים הַנִּמְצָאוֹת שָׁם חַיָּבוֹת לִרְאוֹתָהּ שֶׁנֶּאֱמַר (יחזקאל כג מח) \"וְנִוַּסְּרוּ כָּל הַנָּשִׁים וְלֹא תַעֲשֶׂנָה כְּזִמַּתְכֶנָה\". וְכָל אִישׁ שֶּׁיַּחְפֹּץ לָבֹא לִרְאוֹתָהּ יָבֹא וְיִרְאֶה. וְהִיא עוֹמֶדֶת בֵּינֵיהֶן בְּלֹא רְדִיד וּבְלֹא מִטְפַּחַת אֶלָּא בִּבְגָדֶיהָ וְכִפָּה שֶׁעַל רֹאשָׁהּ כְּמוֹ שֶׁהָאִשָּׁה בְּתוֹךְ בֵּיתָהּ:","וְאֵין מַנִּיחִין שָׁם לֹא עֲבָדֶיהָ וְלֹא שִׁפְחוֹתֶיהָ מִפְּנֵי שֶׁהִיא מַכֶּרֶת אוֹתָן וְדַעְתָּהּ מִתְיַשֶּׁבֶת בָּהֶן:","וְאַחַר כָּךְ מַשְׁבִּיעָהּ הַכֹּהֵן בְּלָשׁוֹן שֶׁהִיא מַכֶּרֶת וּמוֹדִיעָהּ בִּלְשׁוֹנָהּ שֶׁלֹּא גָּרַם לָהּ אֶלָּא קִנּוּי וּסְתִירָה שֶׁקִּנֵּא לָהּ בַּעְלָהּ וְנִסְתְּרָה. וְאוֹמֵר לָהּ בְּלָשׁוֹן שֶׁמַּכֶּרֶת (במדבר ה יט) \"אִם לֹא שָׁכַב אִישׁ אֹתָךְ וְאִם לֹא שָׂטִית טֻמְאָה תַּחַת אִישֵׁךְ הִנָּקִי מִמֵּי הַמָּרִים הַמְאָרַרִים הָאֵלֶּה\" (במדבר ה כ) \"וְאַתְּ כִּי שָׂטִית תַּחַת אִישֵׁךְ וְכִי נִטְמֵאת וַיִּתֵּן אִישׁ בָּךְ אֶת שְׁכָבְתּוֹ מִבַּלְעֲדֵי אִישֵׁךְ\" (במדבר ה כא) \"יִתֵּן ה' אוֹתָךְ לְאָלָה וְלִשְׁבֻעָה בְּתוֹךְ עַמֵּךְ בְּתֵת ה' אֶת יְרֵכֵךְ נֹפֶלֶת וְאֶת בִּטְנֵךְ צָבָה\" (במדבר ה כב) \"וּבָאוּ הַמַּיִם הַמְאָרְרִים הָאֵלֶּה בְּמֵעַיִךְ לַצְבּוֹת בֶּטֶן וְלַנְפִּל יָרֵךְ\". וְהִיא אוֹמֶרֶת (במדבר ה כב) \"אָמֵן אָמֵן\" בְּלָשׁוֹן שֶׁמַּכֶּרֶת. וּמוֹדִיעָהּ שֶׁהַבֶּטֶן הִיא תִּלְקֶה תְּחִלָּה וְהַיָּרֵךְ בַּסּוֹף כְּדֵי שֶׁלֹּא לְהוֹצִיא לַעַז עַל הַמַּיִם:","וְאַחַר כָּךְ מֵבִיא מְגִלָּה שֶׁל עוֹר טָהוֹר כְּמוֹ סֵפֶר תּוֹרָה וְכוֹתֵב עָלֶיהָ בִּלְשׁוֹן הַקֹּדֶשׁ בִּדְיוֹ שֶׁאֵין בּוֹ קַנְקַנְתּוֹם לִשְׁמָהּ שֶׁל אִשָּׁה כְּמוֹ הַגֵּט. וְכוֹתֵב כָּל הַדְּבָרִים שֶׁהִשְׁבִּיעַ אוֹתָהּ בָּהֶם אוֹת בְּאוֹת מִלָּה בְּמִלָּה. וְכוֹתֵב אֶת הַשֵּׁם כִּכְתָבוֹ. וְאֵינוֹ כּוֹתֵב אָמֵן אָמֵן:","וְאַחַר כָּךְ מֵבִיא כְּלִי חֶרֶשׂ שֶׁלֹּא נַעֲשָׂה בּוֹ מְלָאכָה מֵעוֹלָם וְלֹא יֵרָאֶה כִּכְלִי בָּלֶה מֵאֹרֶךְ הַזְּמַן. וְאִם הֶחְזִירוֹ לַכִּבְשָׁן עַד שֶׁנִּתְחַדֵּשׁ כָּשֵׁר. וְנוֹתֵן לְתוֹכוֹ חֲצִי לוֹג מַיִם מִן הַכִּיּוֹר. וּבַחֲצִי לוֹג שֶׁהָיָה בַּמִּקְדָּשׁ הָיָה מוֹדְדוֹ. וְנִכְנַס בּוֹ לַהֵיכָל:","וּמָקוֹם הָיָה שָׁם אַמָּה עַל אַמָּה לִימִין הַנִּכְנָס וּבוֹ טַבְלָא שֶׁל שַׁיִשׁ וְטַבַּעַת קְבוּעָה בָּהּ. מַגְבִּיהַּ הַטַּבְלָא וְלוֹקֵחַ עָפָר מִקַּרְקַע הַמִּשְׁכָּן. וְנוֹתְנוֹ עַל גַּבֵּי הַמַּיִם כְּדֵי שֶׁיֵּרָאֶה עַל פְּנֵי הַמַּיִם. וְנוֹתֵן לְתוֹכָן דָּבָר מַר כְּגוֹן לַעֲנָה וְכַיּוֹצֵא בָּהּ שֶׁנֶּאֱמַר (במדבר ה יח) \"מֵי הַמָּרִים\". וּמוֹחֵק לְתוֹכָן הַמְּגִלָּה לִשְׁמָהּ וְיִמְחֹק יָפֶה יָפֶה עַד שֶׁלֹּא יִשָּׁאֵר בַּמְּגִלָּה רשֶׁם הַנִּכָּר כְּלָל:","וְאַחַר כָּךְ כֹּהֵן אֶחָד בָּא אֵלֶיהָ מִכֹּהֲנֵי הָעֲזָרָה וְאוֹחֵז בִּבְגָדֶיהָ מִכְּנֶגֶד פָּנֶיהָ וְקוֹרֵעַ עַד שֶׁהוּא מְגַלֶּה אֶת לִבָּהּ. וּמְגַלֶּה שְׂעָרָהּ וְסוֹתֵר מַחְלְפוֹת רֹאשָׁהּ כְּדֵי לְנַוְּלָהּ. וּמֵבִיא חֶבֶל מִצְרִי כְּדֵי לְהַזְכִּירָהּ מַעֲשֵׂה מִצְרַיִם שֶׁעָשְׂתָה. וְאִם לֹא מָצְאוּ מִצְרִי מֵבִיא חֶבֶל מִכָּל מָקוֹם. וְקוֹשְׁרוֹ לְמַעְלָה מִדָּדֶיהָ כְּדֵי שֶׁלֹּא יִפְּלוּ הַבְּגָדִים וְנִמְצֵאת עֲרֻמָּה שֶׁהֲרֵי נִקְרְעוּ:","וְאַחַר כָּךְ מֵבִיא עִשָּׂרוֹן קֶמַח שְׂעוֹרִים מִשֶּׁל בַּעַל. וְנוֹתְנוֹ בִּכְפִיפָה מִצְרִית. וְהַחֶבֶל וְהַכְּפִיפָה בָּאִין מִשְּׁיָרֵי הַלִּשְׁכָּה. וְנוֹתְנוֹ לְיָדֶיהָ כְּדֵי לְיַגְּעָהּ:","וְאַחַר כָּךְ לוֹקֵחַ הַמִּנְחָה מִן הַכְּפִיפָה וְנוֹתְנָהּ לִכְלִי שָׁרֵת. וְאֵינוֹ נוֹתֵן עָלֶיהָ שֶׁמֶן וְלֹא לְבוֹנָה. וְאִם נָתַן לוֹקֶה עַל הַשֶּׁמֶן בִּפְנֵי עַצְמוֹ וְעַל הַלְּבוֹנָה בִּפְנֵי עַצְמָהּ. שֶׁנֶּאֱמַר (במדבר ה טו) \"לֹא יִצֹק עָלֶיהָ שֶׁמֶן וְלֹא יִתֵּן עָלֶיהָ לְבֹנָה\":","וּבְכָל זְמַן שֶׁפּוֹרֵעַ רֹאשָׁהּ וְנוֹתֵן הָעִשָּׂרוֹן עַל יָדֶיהָ יִהְיוּ הַמַּיִם בִּכְלִי בְּיַד הַכֹּהֵן וְיַרְאֶה אוֹתָהּ אֶת הַמַּיִם שֶׁנֶּאֱמַר (במדבר ה יח) \"וּבְיַד הַכֹּהֵן יִהְיוּ מֵי הַמָּרִים הַמְאָרַרִים\":","וְאַחַר כָּךְ מַשְׁקֶה אוֹתָהּ. וְאַחַר שֶׁתִּשְׁתֶּה לוֹקֵחַ כְּלִי שָׁרֵת שֶׁבּוֹ הַמִּנְחָה וְנוֹתְנוֹ עַל יָדֶיהָ. וְכֹהֵן מֵנִיחַ יָדוֹ תַּחְתֶּיהָ וּמְנִיפָהּ בַּמִּזְרָח כִּשְׁאָר כָּל הַתְּנוּפוֹת. מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד. וְאַחַר כָּךְ מַגִּישׁ הַמִּנְחָה לְקֶרֶן דְּרוֹמִית מַעֲרָבִית שֶׁל מִזְבֵּחַ כִּשְׁאָר מְנָחוֹת שֶׁל יָחִיד. וְקוֹמֵץ וּמַקְטִיר הַקֹּמֶץ. וְהַשְּׁאָר נֶאֱכָל לַכֹּהֲנִים:","אִם טְהוֹרָה הִיא יוֹצֵאת וְהוֹלֶכֶת לָהּ וַהֲרֵי הִיא מֻתֶּרֶת לְבַעְלָהּ. וְאִם טְמֵאָה הִיא מִיָּד פָּנֶיהָ מוֹרִיקוֹת וְעֵינֶיהָ בּוֹלְטוֹת וְהִיא מִתְמַלֵּאת גִּידִין גִּידִין וְהֵן אוֹמְרִין הוֹצִיאוּהָ (הוֹצִיאוּהָ) כְּדֵי שֶׁלֹּא תִּפְרשֹׁ נִדָּה וְהַנִּדּוֹת מְטַמְּאוֹת עֶזְרַת נָשִׁים. וְהֵן מוֹצִיאִין אוֹתָהּ מֵעֶזְרַת נָשִׁים שֶׁהִיא עוֹמֶדֶת בָּהּ. וּבִטְנָהּ צָבָה בַּתְּחִלָּה וְאַחַר כָּךְ תִּפּל יְרֵכָהּ וְתָמוּת:","בְּאוֹתָהּ שָׁעָה שֶׁתָּמוּת הִיא יָמוּת הַנּוֹאֵף שֶׁהִשְׁקָה עַל יָדוֹ בְּכָל מָקוֹם שֶׁהוּא וְיֶאֶרְעוּ לוֹ מְאֹרָעוֹת שֶׁאֵרְעוּ לָהּ (במדבר ה כב) \"לַצְבּוֹת בֶּטֶן וְלַנְפִּל יָרֵךְ\". וְכָל זֶה אִם לֹא בָּא בַּעְלָהּ בִּיאָה אֲסוּרָה מֵעוֹלָם. אֲבָל אִם בָּעַל בְּעִילָה שֶׁל אִסּוּר אֵין הַמַּיִם בּוֹדְקִין אֶת אִשְׁתּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","וְאִם עָבַר וְהִשְׁקָה אֶת אִשְׁתּוֹ הֲרֵי זֶה מוֹסִיף עַל חַטָּאתוֹ פֶּשַׁע שֶׁגָּרַם לַשֵּׁם הַמְפֹרָשׁ שֶׁיִּמָּחֶה בַּמַּיִם לְבַטָּלָה וּמוֹצִיא לַעַז עַל מֵי סוֹטָה שֶׁאִשְׁתּוֹ אוֹמֶרֶת לַאֲחֵרוֹת שֶׁזִּנְּתָה וְלֹא בָּדְקוּ בָּהּ הַמַּיִם וְהִיא לֹא תֵּדַע שֶׁמַּעֲשֵׂי הַבַּעַל גָּרְמוּ שֶׁלֹּא בָּדְקוּ בָּהּ:","לְפִיכָךְ מִשֶּׁרַבּוּ הַמְנָאֲפִים בְּגָלוּי בְּבַיִת שֵׁנִי בִּטְּלוּ הַסַּנְהֶדְרִין אֶת מֵי הַמָּרִים וְסָמְכוּ עַל הַכָּתוּב בַּקַּבָּלָה (הושע ד יד) \"לֹא אֶפְקוֹד עַל בְּנוֹתֵיכֶם כִּי תִזְנֶינָה\" וְגוֹ':","סוֹטָה שֶׁיֵּשׁ לָהּ זְכוּת תַּלְמוּד תּוֹרָה אַף עַל פִּי שֶׁאֵינָהּ מְצֻוָּה עַל תַּלְמוּד תּוֹרָה הֲרֵי זֶה תּוֹלֶה לָהּ וְאֵינָהּ מֵתָה לִשְׁעָתָהּ אֶלָּא נִמֹּקֶת וְהוֹלֶכֶת וָחֳלָאִים כְּבֵדִים בָּאִין עָלֶיהָ עַד שֶׁתָּמוּת אַחַר שָׁנָה אוֹ שְׁתַּיִם אוֹ שָׁלֹשׁ לְפִי זְכוּתָהּ. וְהִיא מֵתָה בִּצְבִיַּת בֶּטֶן וּבִנְפִילַת אֵיבָרִין:","סוֹטָה שֶׁשָּׁתָת מֵי הַמָּרִים וְלֹא מֵתָה מִיָּד הֲרֵי הִיא מֻתֶּרֶת לְבַעְלָהּ. וַאֲפִלּוּ הָיָה כֹּהֵן. וְאַף עַל פִּי שֶׁהִתְחִילוּ הֶחֳלָאִים לָבוֹא עָלֶיהָ וְחָלוּ שְׁאָר אֵיבָרֶיהָ הוֹאִיל וְלֹא צָבְתָה בִּטְנָהּ וְלֹא הִתְחִיל יְרֵכָהּ לִנְפּל הֲרֵי זוֹ מֻתֶּרֶת. אֲבָל מִשֶּׁהִתְחִיל בִּטְנָהּ לַצְבּוֹת וִירֵכָהּ לִנְפּל הֲרֵי זוֹ אֲסוּרָה וַדָּאִית:","סוֹטָה שֶׁשָׁתָת וְהָיְתָה טְהוֹרָה הֲרֵי זוֹ מִתְחַזֶּקֶת וּפָנֶיהָ מַזְהִירוֹת. וְאִם הָיָה בָּהּ חלִי יָסוּר. וְתִתְעַבֵּר וְתֵלֵד זָכָר. וְאִם הָיָה דַּרְכָּהּ לֵילֵד בְּקֹשִׁי תֵּלֵד בִּמְהֵרָה. הָיָה דַּרְכָּהּ לֵילֵד נְקֵבוֹת תֵּלֵד זְכָרִים:","בָּאוּ עֵדֵי טֻמְאָה אַחַר שֶׁשָּׁתְתָה הֲרֵי זוֹ תֵּצֵא בְּלֹא כְּתֻבָּה וַאֲסוּרָה לְבַעְלָהּ. וַאֲפִלּוּ לֹא אֵרַע לָהּ דָּבָר מִדְּבָרִים אֵלּוּ מִפְּנֵי שֶׁאֵין הַמַּיִם בּוֹדְקִין אֶלָּא מִי שֶׁאֵין לָהּ עֵדִים שֶׁמּוֹדִיעִין זְנוּתָהּ. וְעוֹד שֶׁמָּא בַּעְלָהּ אֵינוֹ מְנֻקֶּה מֵעָוֹן לְפִיכָךְ לֹא בָּדְקוּ הַמַּיִם אֶת אִשְׁתּוֹ. אֲבָל אִם בָּא עֵד אֶחָד וְהֵעִיד שֶׁהָיְתָה טְמֵאָה אֵינָהּ אֲסוּרָה וְתֵשֵׁב תַּחַת בַּעְלָהּ שֶׁהֲרֵי שָׁתְתָה:","אִשָּׁה שֶׁזִּנְּתָה בְּאֹנֶס אוֹ בִּשְׁגָגָה אוֹ שֶׁבָּא עָלֶיהָ זֶה שֶׁקִּנֵּא לָהּ עִמּוֹ דֶּרֶךְ אֵיבָרִים אֵין הַמַּיִם בּוֹדְקִין אוֹתָהּ שֶׁנֶּאֱמַר (במדבר ה יג) \"וְהִיא לֹא נִתְפָּשָׂה\" פְּרָט לַאֲנוּסָה שֶׁהֲרֵי נִתְפְּשָׂה בְּחָזְקָה. (במדבר ה כז) \"וַתִּמְעל מַעַל בְּאִישָׁהּ\" פְּרָט לְשׁוֹגֶגֶת. (במדבר ה יג) \"וְשָׁכַב אִישׁ אֹתָהּ שִׁכְבַת זֶרַע\" פְּרָט לְבָא עָלֶיהָ דֶּרֶךְ אֵיבָרִים:"]} as Record<string, string[]>;
